static int g_failures = 0;
static int g_checks = 0;

/// 数"占位符没填上"那条警告（V6h 那一条用）。
/// NOTE: 处理器必须是**自由函数**（QtMessageHandler 就是个函数指针，带捕获的 lambda
///       换不过去），所以计数也只好放在文件作用域。
static int g_placeholderWarnings = 0;

static void countPlaceholderWarnings(QtMsgType, const QMessageLogContext &,
                                     const QString &message) {
    if (message.contains(QLatin1String("Unresolved placeholder"))) {
        ++g_placeholderWarnings;
    }
}

static QTextStream &out() {
    static QTextStream s(stdout);
    return s;
}

static void check(bool ok, const QString &what, const QString &detail = QString()) {
    ++g_checks;
    if (!ok) {
        ++g_failures;
    }
    out() << (ok ? "  PASS  " : "  FAIL  ") << what;
    if (!detail.isEmpty()) {
        out() << "   [" << detail << "]";
    }
    out() << "\n";
    out().flush();
}

static void section(const QString &title) {
    out() << "\n=== " << title << " ===\n";
    out().flush();
}

/**
 * @brief 往一个路径写一段内容，目录不存在就建出来，**写完立刻关掉句柄**。
 *
 * NOTE: 关句柄不是讲究，是必需的。Windows 上文件被一个还开着的 QFile 攥着时，
 *       后面的 rename / 删除 / 读都会失败，而报出来的错是"拒绝访问"或者
 *       "内容不是合法的 JSON" —— 看着像产品 bug，其实是测试自己没放手。
 *       用它替掉"就地 new 一个 QFile 写到作用域结束"，就不会再踩这个坑。
 */
static void writeFileAt(const QString &path, const QByteArray &bytes) {
    QDir().mkpath(QFileInfo(path).absolutePath());
    QFile file(path);
    if (file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
        file.write(bytes);
        file.close();
    }
}

/// 把一条路径包成 PowerShell 的单引号字符串（给 V5b 造包那条脚本用）。
/// NOTE: 单引号里面不转义反斜杠，所以 toNativeSeparators 是可以的；代价是路径里带 `'`
///       会破 —— 这个沙盒路径是我们自己拼的，不带。
static QString psQuoted(const QString &path) {
    return QStringLiteral("'") + QDir::toNativeSeparators(path) + QStringLiteral("'");
}

/// 造一个"服务器答了"的 HttpClient::Reply（给 X6 那几条话术断言用）。
/// NOTE: networkError 留空 = 连上了、拿到响应了。要验"没连上"那种，见下面 httpReplyFailed。
static HttpClient::Reply httpReply(int status, const QByteArray &raw = QByteArray()) {
    HttpClient::Reply reply;
    reply.status = status;
    reply.raw = raw;
    return reply;
}

/// 造一个"压根没连上"的 Reply：status 保持初值 -1、networkError 有话说。
static HttpClient::Reply httpReplyFailed(const QString &networkError) {
    HttpClient::Reply reply;
    reply.networkError = networkError;
    return reply;
}

static QJsonObject loadJson(const QString &path) {
    QFile f(path);
    if (!f.open(QIODevice::ReadOnly)) {
        qWarning() << "cannot open" << path;
        return QJsonObject();
    }
    return QJsonDocument::fromJson(f.readAll()).object();
}

// ---------------------------------------------------------------------------
// 改动前的 classpath 算法（原样抄自 LauncherManager.cpp 修改前的内容），
// 用来和现在的输出做对比，证明 1.19+ 零回归。
// ---------------------------------------------------------------------------
/// 把一条"相对数据目录"的路径变成产品现在发出去的那种绝对路径。
///
/// ★ 2026-09-28 起 classpath 上的每一条都是**绝对路径**（理由见 legacy::classpath 那段），
///   所以凡是拿相对路径去比 classpath 的断言都要过这一道。
static QString absoluteMcPath(const QString &relative) {
    return QDir::toNativeSeparators(
        QDir(AppPaths::minecraftDir()).absoluteFilePath(relative));
}

namespace legacy {

static bool allowed(const QJsonObject &libObj) {
    const QJsonArray rules = libObj[QStringLiteral("rules")].toArray();
    if (rules.isEmpty()) {
        return true;
    }
    bool ok = false;
    for (const QJsonValue &rv : rules) {
        const QJsonObject ruleObj = rv.toObject();
        const QString action = ruleObj[QStringLiteral("action")].toString();
        if (action.isEmpty()) {
            continue;
        }
        const QJsonObject osObj = ruleObj[QStringLiteral("os")].toObject();
        bool matches = osObj.isEmpty();
        if (!matches) {
            const QString ruleName = osObj[QStringLiteral("name")].toString().toLower();
            if (!ruleName.isEmpty()) {
                matches = (ruleName == QStringLiteral("windows"));
            }
        }
        if (!matches) {
            continue;
        }
        if (action == QStringLiteral("allow")) {
            ok = true;
        } else if (action == QStringLiteral("disallow") || action == QStringLiteral("deny")) {
            ok = false;
        }
    }
    return ok;
}

/// 改动前那条 classpath 算法（"零回归"那条断言拿它当参照）。
///
/// ★ 2026-09-28 改成**绝对路径**：产品侧那一天把 classpath 全部换成了绝对路径 ——
///   Forge/NeoForge 的 BootstrapLauncher 拿 `java.class.path` 里的字符串去和 JVM 模块路径
///   上的**盘上路径**做 `Paths.get(a).equals(Paths.get(b))` 比较，相对串永远不相等，于是
///   它认为同一个 jar 上了两次模块路径并抛 `IllegalStateException`（真机 6 个 NeoForge
///   实例全崩在那一条）。这一份参照实现跟着改，那条断言的**意思**没变：产品的算法和一份
///   独立写出来的实现逐项一致。
static QStringList classpath(const QJsonObject &versionJson, const QString &versionId) {
    QStringList cp;
    const QString root = AppPaths::minecraftDir();
    auto add = [&](const QString &p) {
        const QString absolute = QDir::toNativeSeparators(QDir(root).absoluteFilePath(p));
        if (!p.isEmpty() && !cp.contains(absolute)) {
            cp << absolute;
        }
    };
    add(QStringLiteral("versions/%1/%1.jar").arg(versionId));
    for (const QJsonValue &v : versionJson[QStringLiteral("libraries")].toArray()) {
        const QJsonObject libObj = v.toObject();
        if (!allowed(libObj)) {
            continue;
        }
        const QJsonObject downloads = libObj[QStringLiteral("downloads")].toObject();
        const QString artifactPath =
            downloads[QStringLiteral("artifact")].toObject()[QStringLiteral("path")].toString();
        if (!artifactPath.isEmpty()) {
            add(QDir::toNativeSeparators(QStringLiteral("libraries/%1").arg(artifactPath)));
        }
        const QString classifierKey =
            libObj[QStringLiteral("natives")].toObject()[QStringLiteral("windows")].toString();
        if (!classifierKey.isEmpty()) {
            const QString classifierPath = downloads[QStringLiteral("classifiers")]
                                               .toObject()[classifierKey]
                                               .toObject()[QStringLiteral("path")]
                                               .toString();
            if (!classifierPath.isEmpty()) {
                add(QDir::toNativeSeparators(QStringLiteral("libraries/%1").arg(classifierPath)));
            }
        }
    }
    return cp;
}

}  // namespace legacy

// ---------------------------------------------------------------------------

static QString javaVersionOf(const QString &exe) {
    QProcess p;
    p.start(exe, {QStringLiteral("-version")});
    if (!p.waitForFinished(20000)) {
        return QStringLiteral("<timeout>");
    }
    const QString text = QString::fromLocal8Bit(p.readAllStandardError());
    const QRegularExpression re(QStringLiteral("version \"([^\"]+)\""));
    const auto m = re.match(text);
    return m.hasMatch() ? m.captured(1) : text.trimmed();
}

/// 准备一个最小可用的沙箱 .minecraft，让 checkPreLaunch 能过。
static void prepareSandbox(const QString &sandbox, const QString &versionId) {
    QDir().mkpath(sandbox + "/versions/" + versionId);
    QDir().mkpath(sandbox + "/libraries/fake");
    QDir().mkpath(sandbox + "/assets/indexes");
    QFile jar(sandbox + "/versions/" + versionId + "/" + versionId + ".jar");
    if (jar.open(QIODevice::WriteOnly)) {
        jar.write("dummy");
    }
    QFile marker(sandbox + "/libraries/fake/marker.txt");
    if (marker.open(QIODevice::WriteOnly)) {
        marker.write("dummy");
    }
}

// ---------------------------------------------------------------------------
// 下载批次记账的验证。
//
// 全部离线：把 file:// 当"远端"用，可以精确控制哪些文件存在、哪个 URL 会失败，
// 不依赖 Mojang 在线。asset 对象的 URL 在代码里是写死到
// resources.download.minecraft.net 的，所以这里改成"对象已经在 objects/ 里"——
// 走 ExistsOnly 的跳过分支，一个网络请求都不会发出去。
// ---------------------------------------------------------------------------

namespace synth {

struct RemoteFile {
    QString path;
    QString url;
    QString sha1;
    qint64 size = 0;
};

/// 造一个本地文件并当作"远端"资源返回（url 是 file:// 形式）。
static RemoteFile makeRemote(const QString &remoteDir, const QString &relPath,
                             const QByteArray &content) {
    RemoteFile r;
    r.path = QDir(remoteDir).absoluteFilePath(relPath);
    QDir().mkpath(QFileInfo(r.path).absolutePath());
    QFile f(r.path);
    if (f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
        f.write(content);
        f.close();
    }
    r.url = QUrl::fromLocalFile(r.path).toString();
    r.sha1 =
        QString::fromLatin1(QCryptographicHash::hash(content, QCryptographicHash::Sha1).toHex());
    r.size = content.size();
    return r;
}

static QString sha1Of(const QByteArray &content) {
    return QString::fromLatin1(
        QCryptographicHash::hash(content, QCryptographicHash::Sha1).toHex());
}

}  // namespace synth

struct BatchObservation {
    int emissions = 0;
    bool success = false;
    bool finished = false;
    bool busyWhileInFlight = false;
    bool busyAfterEndBatch = false;
    bool busyAfter = false;
    DownloadStats stats;
};

/// 跑一批下载并记录 allDownloadsFinished 发了几次、内容是什么。
template <typename StartFn>
static BatchObservation runBatch(QCoreApplication &app, StartFn start) {
    DownloadManager mgr;
    BatchObservation obs;
    QEventLoop loop;
    QObject::connect(&mgr, &DownloadManager::allDownloadsFinished, &app, [&](bool ok) {
        ++obs.emissions;
        obs.success = ok;
        obs.finished = true;
        loop.quit();
    });

    mgr.beginBatch();
    start(mgr);
    obs.busyWhileInFlight = mgr.isBusy();
    mgr.endBatch();
    obs.busyAfterEndBatch = mgr.isBusy();
    // 关键：整批都被跳过时 endBatch() 会同步发信号，此时 quit() 已经没人听了，
    // 再 exec() 就会永久阻塞。必须先看标志。
    if (!obs.finished) {
        loop.exec();
    }
    obs.busyAfter = mgr.isBusy();
    obs.stats = mgr.stats();
    return obs;
}

/// pipeline 模式的全部断言（全离线）。
static int runPipelineTests(QCoreApplication &app, const QString &sandbox) {
    const QString work = sandbox + "/synth";
    QDir(work).removeRecursively();
    const QString remoteDir = work + "/remote";

    // "远端"资源：客户端 jar + 2 个库
    const synth::RemoteFile jar =
        synth::makeRemote(remoteDir, QStringLiteral("client.jar"), QByteArray("client-jar-body"));
    QList<synth::RemoteFile> libs;
    for (int i = 0; i < 2; ++i) {
        libs << synth::makeRemote(remoteDir, QStringLiteral("libs/lib%1.jar").arg(i),
                                 QStringLiteral("lib-body-%1").arg(i).toUtf8());
    }
    // 资产索引（DownloadManager 会无条件重取它）
    // asset 对象预先放进 objects/<hash 前两位>/<hash>，名字就是内容的 SHA1
    QJsonObject objects;
    const QString objectsRoot = sandbox + "/assets/objects";
    for (int i = 0; i < 3; ++i) {
        const QByteArray content = QStringLiteral("asset-body-%1").arg(i).toUtf8();
        const QString hash = synth::sha1Of(content);
        const QString path = objectsRoot + "/" + hash.left(2) + "/" + hash;
        QDir().mkpath(QFileInfo(path).absolutePath());
        QFile f(path);
        if (f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            f.write(content);
            f.close();
        }
        objects[QStringLiteral("minecraft/sound%1.ogg").arg(i)] =
            QJsonObject{{QStringLiteral("hash"), hash}, {QStringLiteral("size"), content.size()}};
    }
    const synth::RemoteFile index = synth::makeRemote(
        remoteDir, QStringLiteral("indexes/synthidx.json"),
        QJsonDocument(QJsonObject{{QStringLiteral("objects"), objects}}).toJson());

    const auto buildJson = [&](const QString &jarUrl, const QString &jarSha1, qint64 jarSize) {
        QJsonArray libArr;
        for (int i = 0; i < libs.size(); ++i) {
            libArr.append(QJsonObject{
                {QStringLiteral("name"), QStringLiteral("synth:lib%1:1.0").arg(i)},
                {QStringLiteral("downloads"),
                 QJsonObject{{QStringLiteral("artifact"),
                              QJsonObject{
                                  {QStringLiteral("url"), libs[i].url},
                                  {QStringLiteral("sha1"), libs[i].sha1},
                                  {QStringLiteral("size"), libs[i].size},
                                  {QStringLiteral("path"),
                                   QStringLiteral("synth/lib%1/1.0/lib%1-1.0.jar").arg(i)}}}}}});
        }
        return QJsonObject{
            {QStringLiteral("id"), QStringLiteral("synth-1")},
            {QStringLiteral("libraries"), libArr},
            {QStringLiteral("downloads"),
             QJsonObject{{QStringLiteral("client"),
                          QJsonObject{{QStringLiteral("url"), jarUrl},
                                      {QStringLiteral("sha1"), jarSha1},
                                      {QStringLiteral("size"), jarSize}}}}},
            {QStringLiteral("assetIndex"),
             QJsonObject{{QStringLiteral("id"), QStringLiteral("synthidx")},
                         {QStringLiteral("url"), index.url},
                         {QStringLiteral("sha1"), index.sha1},
                         {QStringLiteral("size"), index.size},
                         {QStringLiteral("totalSize"), 0}}}};
    };
    const QJsonObject goodJson = buildJson(jar.url, jar.sha1, jar.size);

    // 一次批次 = jar 1 + 库 2 + 索引 1 + asset 对象 3
    const int kExpectedTotal = 7;
    // asset 对象（索引里点名的内容）和索引本身都落在 AppPaths::assetsDir() 下，也就是沙盒的
    // .minecraft/assets —— downloadAssets() 现在不收目录参数了，两边必然同源。所以这 3 个
    // 对象在任何一批里都"已经存在"，会走 ExistsOnly 的跳过分支（也正好验证了这条分支）。
    const int kAssetObjects = 3;
    // 暖批次里只有索引还值得重取（它走 onAssetIndexDownloaded 那条无条件重取的路，
    // 不经过 fileAlreadyValid，和 VerifyMode 无关），其余 6 项全部跳过
    const int kWarmSkipped = kExpectedTotal - 1;

    const auto startGood = [&](const QString &base) {
        return [&, base](DownloadManager &mgr) {
            const QJsonObject client = goodJson[QStringLiteral("downloads")].toObject()
                                           [QStringLiteral("client")].toObject();
            mgr.downloadClientJar(QStringLiteral("synth-1"),
                                  client[QStringLiteral("url")].toString(),
                                  base + "/versions/synth-1/synth-1.jar",
                                  client[QStringLiteral("sha1")].toString(),
                                  client[QStringLiteral("size")].toVariant().toLongLong());
            mgr.downloadLibraries(mgr.extractLibraries(goodJson), base + "/libraries");
            mgr.downloadAssets(mgr.extractAssetIndex(goodJson));
        };
    };

    const QString coldBase = work + "/cold";
    const QString warmBase = work + "/warm";

    section("F. 下载批次记账（DownloadManager）");

    // F1 冷批次：jar/库/索引都不存在，真下；3 个 asset 对象已在盘上，跳过
    {
        const BatchObservation o = runBatch(app, startGood(coldBase));
        out() << "        冷批次: emissions=" << o.emissions << " total=" << o.stats.total
              << " done=" << o.stats.done << " failed=" << o.stats.failed
              << " skipped=" << o.stats.skipped << "\n";
        check(o.emissions == 1, "F1 冷批次: allDownloadsFinished 恰好发射 1 次",
              QString::number(o.emissions));
        check(o.success, "F1 冷批次: success == true");
        check(o.stats.total == kExpectedTotal && o.stats.done == kExpectedTotal,
              "F1 冷批次: total == done == 7",
              QString("%1/%2").arg(o.stats.done).arg(o.stats.total));
        check(o.stats.failed == 0, "F1 冷批次: 无失败");
        check(o.stats.skipped == kAssetObjects,
              "F1 冷批次: 只有已在盘上的 asset 对象被跳过（ExistsOnly）",
              QString("skipped=%1").arg(o.stats.skipped));
        check(o.busyWhileInFlight && o.busyAfterEndBatch,
              "F1 冷批次: 作业在途时 isBusy() 为真（含 endBatch 之后）");
        check(!o.busyAfter, "F1 冷批次: 全部结束后 isBusy() 为假");
    }

    // F2 暖批次：先把文件铺好，再跑第二次 —— 除索引（Always）外全部跳过
    {
        const BatchObservation first = runBatch(app, startGood(warmBase));
        check(first.emissions == 1 && first.stats.failed == 0,
              "F2 铺垫: 第一次下载成功且只发一次信号",
              QString("emissions=%1 failed=%2").arg(first.emissions).arg(first.stats.failed));

        const BatchObservation o = runBatch(app, startGood(warmBase));
        out() << "        暖批次: emissions=" << o.emissions << " total=" << o.stats.total
              << " done=" << o.stats.done << " skipped=" << o.stats.skipped << "\n";
        check(o.emissions == 1, "F2 暖批次: allDownloadsFinished 恰好发射 1 次",
              QString::number(o.emissions));
        check(o.success, "F2 暖批次: success == true");
        check(o.stats.skipped == kWarmSkipped,
              "F2 暖批次: 6 个已存在文件被跳过（索引永远重取）",
              QString("skipped=%1").arg(o.stats.skipped));
        check(o.stats.done == kExpectedTotal, "F2 暖批次: 跳过也计入 done/total（进度分母）",
              QString("%1/%2").arg(o.stats.done).arg(o.stats.total));
        check(!o.busyAfter, "F2 暖批次: 结束后 isBusy() 为假");
    }

    // F3 只刷新索引：其余文件都在，只把索引文件删掉
    // NOTE: 索引现在和 objects 同源，落在 AppPaths::assetsDir()（= 沙盒的 .minecraft/assets）
    //       下，不再是 base + "/assets"。删它其实是多余的（索引无条件重取），留着是为了
    //       让这一节的名字对得上它想证明的事。
    {
        QFile::remove(sandbox + "/assets/indexes/synthidx.json");
        const BatchObservation o = runBatch(app, startGood(warmBase));
        check(o.emissions == 1, "F3 只刷新索引: 仍然发射 1 次（改动前一次都不发）",
              QString::number(o.emissions));
        check(o.success, "F3 只刷新索引: success == true");
        check(o.stats.skipped == kWarmSkipped, "F3 只刷新索引: 其余 6 个跳过",
              QString("skipped=%1").arg(o.stats.skipped));
    }

    // F4 失败注入：客户端 jar 指向不存在的文件
    {
        const QString badUrl = QUrl::fromLocalFile(work + "/no-such-file.jar").toString();
        const QString failBase = work + "/fail";
        const QJsonObject badJson = buildJson(badUrl, jar.sha1, jar.size);
        const BatchObservation o = runBatch(app, [&](DownloadManager &mgr) {
            const QJsonObject client = badJson[QStringLiteral("downloads")].toObject()
                                           [QStringLiteral("client")].toObject();
            mgr.downloadClientJar(QStringLiteral("synth-1"),
                                  client[QStringLiteral("url")].toString(),
                                  failBase + "/versions/synth-1/synth-1.jar",
                                  client[QStringLiteral("sha1")].toString(),
                                  client[QStringLiteral("size")].toVariant().toLongLong());
            mgr.downloadLibraries(mgr.extractLibraries(badJson), failBase + "/libraries");
            mgr.downloadAssets(mgr.extractAssetIndex(badJson));
        });
        out() << "        失败注入: emissions=" << o.emissions << " success=" << o.success
              << " failed=" << o.stats.failed << "\n";
        for (const QString &p : o.stats.failedPaths) {
            out() << "        失败路径: " << p << "\n";
        }
        check(o.emissions == 1, "F4 失败: 仍然恰好发射 1 次", QString::number(o.emissions));
        check(!o.success, "F4 失败: success == false（改动前硬编码 true，失败报不出来）");
        check(o.stats.failed == 1, "F4 失败: failed == 1",
              QString::number(o.stats.failed));
        check(o.stats.failedPaths.contains(failBase + "/versions/synth-1/synth-1.jar"),
              "F4 失败: 失败清单里有那一项的完整路径");
        check(!o.busyAfter, "F4 失败: 结束后 isBusy() 为假（按钮不会永久变灰）");
    }

    // F5 同一个实例连跑两批：计数必须重置，不能叠加
    {
        DownloadManager mgr;
        int emissions = 0;
        QList<bool> successes;
        QObject::connect(&mgr, &DownloadManager::allDownloadsFinished, &app,
                         [&](bool ok) { ++emissions; successes << ok; });
        const QString base = work + "/reuse";
        const auto registerAll = [&]() {
            const QJsonObject client = goodJson[QStringLiteral("downloads")].toObject()
                                           [QStringLiteral("client")].toObject();
            mgr.downloadClientJar(QStringLiteral("synth-1"),
                                  client[QStringLiteral("url")].toString(),
                                  base + "/versions/synth-1/synth-1.jar",
                                  client[QStringLiteral("sha1")].toString(),
                                  client[QStringLiteral("size")].toVariant().toLongLong());
            mgr.downloadLibraries(mgr.extractLibraries(goodJson), base + "/libraries");
            mgr.downloadAssets(mgr.extractAssetIndex(goodJson));
        };

        bool finished1 = false;
        QEventLoop loop1;
        QObject::connect(&mgr, &DownloadManager::allDownloadsFinished, &app,
                         [&](bool) { finished1 = true; loop1.quit(); });
        mgr.beginBatch();
        registerAll();
        mgr.endBatch();
        if (!finished1) loop1.exec();
        const DownloadStats s1 = mgr.stats();

        bool finished2 = false;
        QEventLoop loop2;
        QObject::connect(&mgr, &DownloadManager::allDownloadsFinished, &app,
                         [&](bool) { finished2 = true; loop2.quit(); });
        mgr.beginBatch();
        registerAll();
        mgr.endBatch();
        if (!finished2) loop2.exec();
        const DownloadStats s2 = mgr.stats();

        out() << "        复用实例: 第一批 skipped=" << s1.skipped << "，第二批 skipped="
              << s2.skipped << "，emissions=" << emissions << "\n";
        check(emissions == 2, "F5 连跑两批: 每批各发射 1 次", QString::number(emissions));
        check(s1.total == kExpectedTotal && s2.total == kExpectedTotal,
              "F5 连跑两批: 每批 total 重置为 7",
              QString("%1, %2").arg(s1.total).arg(s2.total));
        check(s1.skipped == kAssetObjects && s2.skipped == kWarmSkipped,
              "F5 连跑两批: 第二批全部走跳过分支",
              QString("skipped=%1/%2").arg(s1.skipped).arg(s2.skipped));
        check(!mgr.isBusy(), "F5 连跑两批: 结束后 isBusy() 为假");
    }

    // F6 索引 SHA1 校验：把 assetIndex.sha1 故意写错。改动前这条路径写完文件就
    //    success = true（expectedSha1s 里登记了却没人读），镜像源拼错索引时会拿一份
    //    **内容不对的索引**去下几千个资源，而且要等资源层面才炸、看不出根因。
    //   改了之后：整批失败、坏索引删掉、后面的解析根本不跑。
    {
        QJsonObject badIndexJson = goodJson;
        QJsonObject ai = badIndexJson[QStringLiteral("assetIndex")].toObject();
        ai[QStringLiteral("sha1")] = QString(40, QLatin1Char('0'));
        badIndexJson[QStringLiteral("assetIndex")] = ai;

        const QString indexPath = sandbox + "/assets/indexes/synthidx.json";
        QFile::remove(indexPath);  // 先清掉，才能断言"坏索引没被留在盘上"

        const QString badBase = work + "/badindex";
        const BatchObservation o = runBatch(app, [&](DownloadManager &mgr) {
            const QJsonObject client = goodJson[QStringLiteral("downloads")].toObject()
                                           [QStringLiteral("client")].toObject();
            mgr.downloadClientJar(QStringLiteral("synth-1"),
                                  client[QStringLiteral("url")].toString(),
                                  badBase + "/versions/synth-1/synth-1.jar",
                                  client[QStringLiteral("sha1")].toString(),
                                  client[QStringLiteral("size")].toVariant().toLongLong());
            mgr.downloadLibraries(mgr.extractLibraries(goodJson), badBase + "/libraries");
            mgr.downloadAssets(mgr.extractAssetIndex(badIndexJson));
        });
        out() << "        索引 SHA1: emissions=" << o.emissions << " success=" << o.success
              << " failed=" << o.stats.failed << " total=" << o.stats.total << "\n";
        check(!o.success, "F6 索引 SHA1 不对: 整批报失败（改动前 success == true）");
        check(o.stats.failed == 1, "F6 索引 SHA1 不对: 只有索引这一项算失败",
              QString::number(o.stats.failed));
        check(o.stats.failedPaths.contains(indexPath),
              "F6 索引 SHA1 不对: 失败清单里是索引文件本身");
        check(!QFile::exists(indexPath), "F6 索引 SHA1 不对: 坏索引没有留在盘上");
        check(o.stats.total == 4,
              "F6 索引 SHA1 不对: 索引没被解析（否则会多出 3 个 asset 任务）",
              QString("total=%1").arg(o.stats.total));
    }

    return g_failures == 0 ? 0 : 1;
}

/// vm-batch 模式：走 VersionManager::downloadVersion 的完整批次编排。
/// version.json 是本地伪造的，靠 getVersionJson() 的磁盘回读填进缓存，
/// 不依赖 Mojang。
static int runVersionManagerBatch(QCoreApplication &app, const QString &sandbox) {
    const QString versionId = QStringLiteral("synth-1");
    const QString work = sandbox + "/synth-vm";
    QDir(work).removeRecursively();
    const QString remoteDir = work + "/remote";
    const QString base = sandbox + "/versions/" + versionId;

    const synth::RemoteFile jar = synth::makeRemote(remoteDir, QStringLiteral("client.jar"),
                                                   QByteArray("vm-client-jar-body"));
    const synth::RemoteFile index = synth::makeRemote(
        remoteDir, QStringLiteral("indexes/synthidx.json"),
        QJsonDocument(QJsonObject{{QStringLiteral("objects"), QJsonObject()}}).toJson());

    QJsonArray libArr;
    for (int i = 0; i < 2; ++i) {
        const synth::RemoteFile lib = synth::makeRemote(
            remoteDir, QStringLiteral("libs/vmlib%1.jar").arg(i),
            QStringLiteral("vm-lib-body-%1").arg(i).toUtf8());
        libArr.append(QJsonObject{
            {QStringLiteral("name"), QStringLiteral("synth:vmlib%1:1.0").arg(i)},
            {QStringLiteral("downloads"),
             QJsonObject{{QStringLiteral("artifact"),
                          QJsonObject{{QStringLiteral("url"), lib.url},
                                      {QStringLiteral("sha1"), lib.sha1},
                                      {QStringLiteral("size"), lib.size},
                                      {QStringLiteral("path"),
                                       QStringLiteral("synth/vmlib%1/1.0/vmlib%1-1.0.jar")
                                           .arg(i)}}}}}});
    }
    const QJsonObject versionJson{
        {QStringLiteral("id"), versionId},
        {QStringLiteral("libraries"), libArr},
        {QStringLiteral("downloads"),
         QJsonObject{{QStringLiteral("client"),
                      QJsonObject{{QStringLiteral("url"), jar.url},
                                  {QStringLiteral("sha1"), jar.sha1},
                                  {QStringLiteral("size"), jar.size}}}}},
        {QStringLiteral("assetIndex"),
         QJsonObject{{QStringLiteral("id"), QStringLiteral("synthidx")},
                     {QStringLiteral("url"), index.url},
                     {QStringLiteral("sha1"), index.sha1},
                     {QStringLiteral("size"), index.size}}}};

    // 落盘，让 getVersionJson() 能从磁盘回读进缓存（downloadVersion 的前置条件）
    QDir().mkpath(base);
    QFile jsonFile(base + "/" + versionId + ".json");
    if (!jsonFile.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
        out() << "无法写入 " << jsonFile.fileName() << "\n";
        return 2;
    }
    jsonFile.write(QJsonDocument(versionJson).toJson(QJsonDocument::Indented));
    jsonFile.close();

    VersionManager vm;
    int emissions = 0;
    bool lastSuccess = false;
    QString lastMessage;
    bool finished = false;
    int statsSignals = 0;
    int lastDone = 0;
    int lastTotal = 0;
    QEventLoop loop;
    QObject::connect(&vm, &VersionManager::versionDownloadFinished, &app,
                     [&](const QString &id, bool ok, const QString &msg) {
                         ++emissions;
                         lastSuccess = ok;
                         lastMessage = msg;
                         finished = true;
                         out() << "        versionDownloadFinished: id=" << id
                               << " success=" << ok << "\n";
                         loop.quit();
                     });
    QObject::connect(&vm, &VersionManager::versionDownloadStats, &app,
                     [&](int done, int total, int, const QString &) {
                         ++statsSignals;
                         lastDone = done;
                         lastTotal = total;
                     });

    section("G. VersionManager 批次编排");
    const QJsonObject loaded = vm.getVersionJson(versionId);
    check(!loaded.isEmpty(), "G0 版本 JSON 从磁盘回读成功（缓存已填充）");
    check(!vm.isDownloading(), "G0 下载前 isDownloading() 为假");

    vm.downloadVersion(versionId, base);
    check(vm.isDownloading(), "G1 已开始下载：isDownloading() 为真（UI 据此禁用启动）");
    if (!finished) {
        loop.exec();
    }
    out() << "        第一批: emissions=" << emissions << " statsSignals=" << statsSignals
          << " done/total=" << lastDone << "/" << lastTotal << "\n";
    check(emissions == 1, "G1 冷批次: versionDownloadFinished 恰好 1 次（改动前每个文件一次）",
          QString::number(emissions));
    check(lastSuccess, "G1 冷批次: success == true");
    check(statsSignals > 0, "G1 冷批次: 进度通过 versionDownloadStats 发出（不再进日志）",
          QString::number(statsSignals));
    check(lastDone == lastTotal && lastTotal == 4,
          "G1 冷批次: 4 个作业全部完成（jar 1 + 库 2 + 索引 1）",
          QString("%1/%2").arg(lastDone).arg(lastTotal));
    check(!vm.isDownloading(), "G1 冷批次: 结束后 isDownloading() 为假");

    // 第二批：文件都在了，只剩索引要重取
    emissions = 0;
    finished = false;
    statsSignals = 0;
    vm.downloadVersion(versionId, base);
    if (!finished) {
        loop.exec();
    }
    out() << "        第二批: emissions=" << emissions << " statsSignals=" << statsSignals << "\n";
    check(emissions == 1, "G2 重复下载: 仍然恰好 1 次", QString::number(emissions));
    check(lastSuccess, "G2 重复下载: success == true");
    check(lastMessage.contains(QStringLiteral("跳过")),
          "G2 重复下载: 汇总里说明了跳过了几个文件", lastMessage);
    check(!vm.isDownloading(), "G2 重复下载: 结束后 isDownloading() 为假");

    // 前置条件不满足（缓存里没有这个版本）也必须给终态，不能让 UI 干等
    emissions = 0;
    finished = false;
    vm.downloadVersion(QStringLiteral("no-such-cached-version"), work + "/nope");
    if (!finished) {
        out() << "        前置条件不满足时没有发出终态信号\n";
    }
    check(emissions == 1 && !lastSuccess,
          "G3 没有 version.json 时: 立刻回一个失败终态（UI 不会卡在下载中）",
          QString::number(emissions));

    // --- G4：从信号里往回接续（2026-09-22 那次无日志崩溃的修复）-------------------
    //
    // 那次是：原版那一批下完 -> allDownloadsFinished -> **在上一批的栈里**同步起了"加载器
    // 自己的库"那个批次 -> extractAssetIndex() -> Qt 内部一把 QReadWriteLock 的 unlock()
    // 抛了没接住的 std::system_error -> std::terminate -> abort()（启动器静默消失、
    // 一句日志都没有，取证工具在 build/tools/crashdump/）。
    //
    // 修法是把"接着干下一件事"排到下一轮事件循环（VersionManager::deferNextStep），
    // 并给排队的那一步套一层兜底：真抛了异常就翻成失败终态，别再穿到 terminate。
    // 下面这几条钉的就是这两件事 —— 它们不依赖网络，也不会真崩（崩了就是验证进程没了）。
    section("G4. 接续排到下一轮 + 兜底不 terminate");

    int deferredRan = 0;
    vm.deferNextStep([&deferredRan] { ++deferredRan; });
    check(deferredRan == 0, "G4.1 排队的那一步不在调用栈里同步跑（重入就是这么来的）",
          QString::number(deferredRan));
    QCoreApplication::processEvents();
    check(deferredRan == 1, "G4.2 下一轮事件循环里跑到了", QString::number(deferredRan));

    emissions = 0;
    lastSuccess = true;
    lastMessage.clear();
    vm.deferNextStep([] { throw std::runtime_error("验证工程故意抛的异常"); });
    QCoreApplication::processEvents();
    check(emissions == 1 && !lastSuccess,
          "G4.3 排队那一步抛异常 -> 翻成一个失败终态（改动前是 terminate/abort）",
          QString("emissions=%1 success=%2").arg(emissions).arg(lastSuccess));
    check(lastMessage.contains(QStringLiteral("内部错误")),
          "G4.4 那句话里说明了是内部错误（用户看得懂、也照旧弹窗）", lastMessage);
    check(!vm.isDownloading(),
          "G4.5 兜底之后批次状态是干净的（不会永远卡在「下载中」、按钮不会永久变灰）");

    // --- G5：补全文件（VersionManager::repairVersionFiles）------------------------
    //
    // 实例设置「启动」栏那颗「补全文件」走的就是它。用户 2026-09-26 的原话是「校验已装的，
    // 缺哪个补哪个」—— 前半句是重点：**不是"缺了才下"**，内容不对的也要换掉。
    //
    // 它和 downloadVersion() 有三处刻意不同（见 .hpp 里那段块注释），三条都在这里钉：
    //   ① json 从盘上读 —— 这一节从头到尾没有网络、也没有先 fetchVersionDetails 过；
    //   ② **不**写 version.json（那一步只有"下载一个版本"才该做）；
    //   ③ 客户端 jar 的落点按 InstanceFiles::jarPath()：加载器实例补的是**父版本**那一份。
    //
    // 用上面那批已经下好的文件当前提（G1/G2 摆的就是 jar 1 + 库 2 + 索引 1 这 4 个作业）。
    section("G5. 补全文件：校验已装的，只补缺的和坏的");

    const QString jarPath = base + "/" + versionId + ".jar";
    const QString lib0Path = sandbox + "/libraries/synth/vmlib0/1.0/vmlib0-1.0.jar";
    const QString lib1Path = sandbox + "/libraries/synth/vmlib1/1.0/vmlib1-1.0.jar";
    const QString jsonPath = base + "/" + versionId + ".json";

    auto readBytes = [](const QString &path) {
        QFile f(path);
        if (!f.open(QIODevice::ReadOnly)) {
            return QByteArray();
        }
        return f.readAll();
    };

    check(QFile::exists(jarPath) && QFile::exists(lib0Path) && QFile::exists(lib1Path),
          "G5.0 前提：4 个文件都在盘上（前两批下的）");

    // 坏的那两类都摆上：jar 换成**字节数一样、内容不对**的一份（证明"校验"看的是 sha1 而不是
    // 光比大小），另一个库直接删掉（证明缺的会补）。
    const QByteArray realJar = readBytes(jarPath);
    QByteArray bogusJar(realJar.size(), 'x');
    if (bogusJar == realJar) {
        bogusJar[0] = 'y';  // 极端情况：真内容本来就全是 x
    }
    writeFileAt(jarPath, bogusJar);
    QFile::remove(lib0Path);
    const QByteArray lib1Before = readBytes(lib1Path);
    const QByteArray jsonBefore = readBytes(jsonPath);

    emissions = 0;
    finished = false;
    lastSuccess = false;
    lastMessage.clear();
    lastDone = 0;
    lastTotal = 0;
    vm.repairVersionFiles(versionId);
    check(vm.isDownloading(), "G5.1 补全期间 isDownloading() 为真（这个实例据此不能启动）");
    if (!finished) {
        loop.exec();
    }
    out() << "        补全第一批: emissions=" << emissions << " done/total=" << lastDone << "/"
          << lastTotal << "\n";
    check(emissions == 1 && lastSuccess, "G5.1 补全: 恰好一个成功终态",
          QString("emissions=%1 success=%2").arg(emissions).arg(lastSuccess));
    check(lastDone == 4 && lastTotal == 4,
          "G5.1 补全: 4 个文件全过了一遍（jar 1 + 库 2 + 索引 1）",
          QString("%1/%2").arg(lastDone).arg(lastTotal));
    check(readBytes(jarPath) == realJar,
          "★ G5.2 内容不对的 jar 被换回来了（字节数一样，靠 sha1 认出来的）");
    check(QFile::exists(lib0Path) && readBytes(lib0Path) == QByteArray("vm-lib-body-0"),
          "G5.3 删掉的那个库补回来了");
    check(readBytes(lib1Path) == lib1Before,
          "G5.4 本来就是好的那个库一个字节都没动（校验通过就跳过，不是全量重写）");
    check(lastMessage.contains(QStringLiteral("跳过")),
          "G5.5 汇总里说明了有几个是本来就存在的", lastMessage);
    check(readBytes(jsonPath) == jsonBefore,
          "★ G5.6 补全**不动** version.json（和 downloadVersion 的区别 ②）");
    check(!vm.isDownloading(), "G5.6 结束后 isDownloading() 为假");

    // 再补一次：全都在了 ⇒ 还是成功终态（不是"没活干就当失败"），而且字节一个不变
    emissions = 0;
    finished = false;
    lastSuccess = false;
    lastMessage.clear();
    lastDone = 0;
    lastTotal = 0;
    vm.repairVersionFiles(versionId);
    if (!finished) {
        loop.exec();
    }
    check(emissions == 1 && lastSuccess, "G5.7 重复补全: 仍然是一个成功终态", lastMessage);
    check(lastMessage.contains(QStringLiteral("跳过")),
          "G5.7 重复补全: 汇总里明说这次跳过了", lastMessage);
    check(readBytes(jarPath) == realJar && readBytes(lib0Path) == QByteArray("vm-lib-body-0") &&
              readBytes(lib1Path) == lib1Before,
          "G5.7 重复补全: 三个文件一个字节都没动");
    check(!vm.isDownloading(), "G5.7 结束后 isDownloading() 为假");

    // 读不出 json：**立刻**回一个失败终态，而且一个批次都不开（UI 不能卡在「检查中」）
    emissions = 0;
    finished = false;
    lastSuccess = true;
    lastMessage.clear();
    vm.repairVersionFiles(QStringLiteral("no-such-version"));
    check(emissions == 1 && !lastSuccess,
          "G5.8 没有 version.json 时: 立刻回一个失败终态", QString::number(emissions));
    check(lastMessage.contains(QStringLiteral("version.json")),
          "G5.8 那句话点的是「读不出 version.json」（不是一句笼统的失败）", lastMessage);
    check(!vm.isDownloading(), "G5.8 而且一个批次都没开（不然按钮会一直灰着）");

    // ③ 加载器实例：目录里只有一份 json（主 jar 在原版那边），补全要补到**父版本**的目录里去
    const QString vanillaId = QStringLiteral("synth-g5vanilla");
    const QString loaderId = QStringLiteral("synth-g5loader");
    const QString vanillaDir = sandbox + "/versions/" + vanillaId;
    const QString loaderDir = sandbox + "/versions/" + loaderId;
    const synth::RemoteFile vanillaJar = synth::makeRemote(
        remoteDir, QStringLiteral("client-vanilla.jar"), QByteArray("g5-vanilla-jar-body"));
    QDir().mkpath(vanillaDir);
    QDir().mkpath(loaderDir);
    const QJsonObject vanillaJson{
        {QStringLiteral("id"), vanillaId},
        {QStringLiteral("libraries"), QJsonArray()},
        {QStringLiteral("downloads"),
         QJsonObject{{QStringLiteral("client"),
                      QJsonObject{{QStringLiteral("url"), vanillaJar.url},
                                  {QStringLiteral("sha1"), vanillaJar.sha1},
                                  {QStringLiteral("size"), vanillaJar.size}}}}}};
    writeFileAt(vanillaDir + "/" + vanillaId + ".json",
                QJsonDocument(vanillaJson).toJson(QJsonDocument::Indented));
    const QJsonObject loaderJson{
        {QStringLiteral("id"), loaderId},
        {QStringLiteral("inheritsFrom"), vanillaId},
        {QStringLiteral("mainClass"),
         QStringLiteral("net.fabricmc.loader.impl.launch.knot.KnotClient")}};
    writeFileAt(loaderDir + "/" + loaderId + ".json",
                QJsonDocument(loaderJson).toJson(QJsonDocument::Indented));
    // 父版本那份 jar 先摆一个内容不对的：这一条验的正是"补到哪个目录里去了"
    writeFileAt(vanillaDir + "/" + vanillaId + ".jar", QByteArray("not-the-vanilla-jar"));

    emissions = 0;
    finished = false;
    lastSuccess = false;
    lastMessage.clear();
    vm.repairVersionFiles(loaderId);
    if (!finished) {
        loop.exec();
    }
    check(emissions == 1 && lastSuccess, "G5.9 加载器实例补全: 成功", lastMessage);
    check(readBytes(vanillaDir + "/" + vanillaId + ".jar") ==
              QByteArray("g5-vanilla-jar-body"),
          "★ G5.9 客户端 jar 补进了**父版本**的目录（加载器实例自己没有 jar）",
          readBytes(vanillaDir + "/" + vanillaId + ".jar"));
    check(!QFile::exists(loaderDir + "/" + loaderId + ".jar"),
          "G5.9 加载器实例自己的目录里**没有**多出一个 jar（区别 ③ 的另一半）");

    return g_failures == 0 ? 0 : 1;
}

/// vm-fetch-fail 模式：元数据拉取走死路时，必须有终态信号。
static int runVersionManagerFetchFail(QCoreApplication &app) {
    VersionManager vm;
    const QString bogus = QStringLiteral("this-version-does-not-exist-9999");
    int emissions = 0;
    bool finished = false;
    QString reportedId;
    QEventLoop loop;
    QObject::connect(&vm, &VersionManager::versionDetailsFetched, &app,
                     [&](const QString &id, const QJsonObject &json) {
                         ++emissions;
                         reportedId = id;
                         out() << "        versionDetailsFetched: id=" << id
                               << " jsonEmpty=" << json.isEmpty() << "\n";
                         finished = true;
                         loop.quit();
                     });

    section("H. 元数据死路");
    QTimer::singleShot(30000, &loop, [&]() {
        out() << "        30 秒超时\n";
        loop.quit();
    });
    vm.fetchVersionDetails(bogus);
    if (!finished) {
        loop.exec();
    }
    check(emissions == 1, "H1 拉取不存在的版本: 有且只有一个终态信号", QString::number(emissions));
    check(reportedId == bogus, "H1 终态信号带回了请求的版本号", reportedId);
    check(!vm.isDownloading(), "H1 之后 isDownloading() 为假（按钮不会永久变灰）");
    return g_failures == 0 ? 0 : 1;
}

// ---------------------------------------------------------------------------
// I. 版本显示名：formatVersionName / normalizeVersionNameOptions（纯函数）
//    + VersionManager::displayParts()（读盘）+ LauncherSettings（读写设置）
// ---------------------------------------------------------------------------
// 这一节的意义：显示名是"用户唯一能看见的版本标识"，而拼错了不会崩、只会安静地
// 显示成另一个东西（甚至空串）。所以真值表整表逐条钉死，不留任何组合靠推理。
//
// NOTE: LauncherSettings 那一小段必须把 QSettings 重定向到沙盒 ini 再跑 —— 默认的
// NativeFormat 写的是**用户的真注册表**。上面 E 节末尾那句"测试不该改动机器上的设置"
// 是同一个顾虑，这里只是换了个办法满足它。
static int runVersionNameTests(const QString &sandbox) {
    section("I. 版本显示名");

    const QString id = QStringLiteral("1.20.1");
    const QString loaderName = QStringLiteral("Forge");
    const QString loaderVersion = QStringLiteral("47.2.0");

    VersionDisplayParts parts;
    parts.id = id;
    parts.loaderName = loaderName;
    parts.loaderVersion = loaderVersion;

    const VersionNameOptions kStructDefault;  // 自定义名✓ 版本名✓ 加载器名✓ 加载器版本✗

    // 16 行 = 四个布尔的全组合，下标 = c*8 + r*4 + n*2 + v。
    // 期望值是一张**手写**的表，不是拿另一份实现算出来的 —— 用实现算期望值等于没测。
    struct Table {
        QString customName;
        QStringList expected;
    };
    const QList<Table> tables = {
        {QString(),
         {QStringLiteral("1.20.1"), QStringLiteral("1.20.1"), QStringLiteral("1.20.1-Forge"),
          QStringLiteral("1.20.1-Forge-47.2.0"), QStringLiteral("1.20.1"), QStringLiteral("1.20.1"),
          QStringLiteral("1.20.1-Forge"), QStringLiteral("1.20.1-Forge-47.2.0"),
          QStringLiteral("1.20.1"), QStringLiteral("1.20.1"), QStringLiteral("1.20.1-Forge"),
          QStringLiteral("1.20.1-Forge-47.2.0"), QStringLiteral("1.20.1"), QStringLiteral("1.20.1"),
          QStringLiteral("1.20.1-Forge"), QStringLiteral("1.20.1-Forge-47.2.0")}},
        {QStringLiteral("我的整合包"),
         {QStringLiteral("1.20.1"), QStringLiteral("1.20.1"), QStringLiteral("1.20.1-Forge"),
          QStringLiteral("1.20.1-Forge-47.2.0"), QStringLiteral("1.20.1"), QStringLiteral("1.20.1"),
          QStringLiteral("1.20.1-Forge"), QStringLiteral("1.20.1-Forge-47.2.0"),
          QStringLiteral("我的整合包"), QStringLiteral("我的整合包"), QStringLiteral("我的整合包-Forge"),
          QStringLiteral("我的整合包-Forge-47.2.0"), QStringLiteral("我的整合包-1.20.1"),
          QStringLiteral("我的整合包-1.20.1"), QStringLiteral("我的整合包-1.20.1-Forge"),
          QStringLiteral("我的整合包-1.20.1-Forge-47.2.0")}},
    };

    for (const Table &table : tables) {
        VersionDisplayParts p = parts;
        p.customName = table.customName;
        const QString label = table.customName.isEmpty() ? QStringLiteral("<无自定义名>")
                                                         : table.customName;
        // 每个组合单独记一个"拼装畸形"的计数，最后汇成一条断言 —— 32 条独立的
        // 畸形断言会把输出淹掉，而这里要的信号是"有没有，有哪个"。
        QStringList malformed;
        for (int mask = 0; mask < 16; ++mask) {
            VersionNameOptions opt;
            opt.showCustomName = (mask & 8) != 0;
            opt.showRealVersion = (mask & 4) != 0;
            opt.showLoaderName = (mask & 2) != 0;
            opt.showLoaderVersion = (mask & 1) != 0;

            const QString got = formatVersionName(p, opt);
            const QString &want = table.expected.at(mask);
            check(got == want,
                  QString("I1 %1 c%2r%3n%4v%5 -> %6")
                      .arg(label)
                      .arg(opt.showCustomName ? 1 : 0)
                      .arg(opt.showRealVersion ? 1 : 0)
                      .arg(opt.showLoaderName ? 1 : 0)
                      .arg(opt.showLoaderVersion ? 1 : 0)
                      .arg(want),
                  got == want ? QString() : QStringLiteral("实际 ") + got);

            // 畸形 = 空串、或首尾/连续的分隔符。连续 '-' 正是"去重不对称"（Forge 拼成
            // Forge-Forge）会留下的痕迹，所以这条不能省。
            if (got.isEmpty() || got.startsWith(QLatin1Char('-')) ||
                got.endsWith(QLatin1Char('-')) || got.contains(QStringLiteral("--"))) {
                malformed.append(QStringLiteral("mask%1=%2").arg(mask).arg(got));
            }
        }
        check(malformed.isEmpty(), QString("I1 %1 的 16 种组合都非空、无多余分隔符").arg(label),
              malformed.join(QStringLiteral(", ")));
    }

    // I2 归一化：两条不变式必须自己站得住（真值表里非法格"看起来对"是被
    // formatVersionName 内部那道归一化救回来的，这里直接验那道归一化本身）。
    {
        VersionNameOptions allOff;
        allOff.showCustomName = false;
        allOff.showRealVersion = false;
        allOff.showLoaderName = false;
        allOff.showLoaderVersion = false;
        const VersionNameOptions fixed = normalizeVersionNameOptions(allOff);
        check(fixed.showRealVersion, "I2 自定义名+版本名同关 -> 版本名被强制打开");

        VersionNameOptions versionOnly;
        versionOnly.showCustomName = false;
        versionOnly.showRealVersion = false;
        versionOnly.showLoaderName = false;
        versionOnly.showLoaderVersion = true;
        const VersionNameOptions fixed2 = normalizeVersionNameOptions(versionOnly);
        check(!fixed2.showLoaderVersion, "I2 加载器名关着而加载器版本开着 -> 加载器版本被关掉");

        check(normalizeVersionNameOptions(kStructDefault) == kStructDefault,
              "I2 合法组合过一遍归一化不变");
        // 顺序：(a) 打开版本名，(b) 再判加载器。先 (b) 后 (a) 结果一样，但注释里
        // 写的顺序要和实现一致，所以这里把"两步都生效"的组合也钉一条。
        VersionNameOptions both;
        both.showCustomName = false;
        both.showRealVersion = false;
        both.showLoaderName = false;
        both.showLoaderVersion = true;
        const VersionNameOptions fixed3 = normalizeVersionNameOptions(both);
        check(fixed3.showRealVersion && !fixed3.showLoaderVersion,
              "I2 两条不变式同时触发时都生效");
    }

    // I3 清洗：元数据文件的意义就是让用户手写，手写的内容一律当不可信输入。
    {
        VersionDisplayParts p;
        p.id = QStringLiteral("1.20.1");

        VersionNameOptions customOnly;  // 只勾自定义名 —— 这时显示的是名称槽
        customOnly.showCustomName = true;
        customOnly.showRealVersion = false;
        customOnly.showLoaderName = false;
        customOnly.showLoaderVersion = false;

        p.customName = QStringLiteral("a\nb");
        check(formatVersionName(p, customOnly) == QStringLiteral("a b"),
              "I3 名字里的换行被折成空格", formatVersionName(p, customOnly));

        p.customName = QStringLiteral("  padded\tname  ");
        check(formatVersionName(p, customOnly) == QStringLiteral("padded name"),
              "I3 首尾空白去掉、制表符折成空格", formatVersionName(p, customOnly));

        p.customName = QString(200, QLatin1Char('x'));
        const QString truncated = formatVersionName(p, customOnly);
        check(truncated.size() == 64, "I3 超长名字被截到 64 字符",
              QString::number(truncated.size()));

        // 截断点**正好落在空格上**：simplified() 只保证截断前没有首尾空白，截断
        // 本身能重新制造一个尾随空格，而那个空格会被拼进显示名里变成 "xxx -1.20.1"。
        // 上面那条 200 个 'x' 的用例永远踩不到这个点，所以必须单独造一条。
        p.customName = QString(63, QLatin1Char('x')) + QLatin1Char(' ') + QString(50, QLatin1Char('y'));
        const QString cutOnSpace = formatVersionName(p, customOnly);
        check(!cutOnSpace.endsWith(QLatin1Char(' ')) &&
                  cutOnSpace.size() == 63,
              "I3 截断点落在空格上时不留尾随空格",
              QString("[%1] size=%2").arg(cutOnSpace.right(5)).arg(cutOnSpace.size()));

        // 截断后拼上其他段，不能出现 " -" 这种带空格的连接
        p.customName = QString(63, QLatin1Char('x')) + QLatin1Char(' ') + QString(50, QLatin1Char('y'));
        VersionNameOptions twoSegs;
        twoSegs.showCustomName = true;
        twoSegs.showRealVersion = true;
        check(!formatVersionName(p, twoSegs).contains(QStringLiteral(" -")),
              "I3 多段拼接时没有『空格+连字符』这种畸形连接",
              formatVersionName(p, twoSegs).right(20));

        // id 也要清洗 —— 在线清单和目录名同样不是我们能保证的内容
        VersionDisplayParts q;
        q.id = QStringLiteral("26.2\nsnapshot");
        VersionNameOptions realOnly;
        realOnly.showCustomName = false;
        check(!formatVersionName(q, realOnly).contains(QLatin1Char('\n')),
              "I3 id 里的换行同样被清掉", formatVersionName(q, realOnly));
    }

    // I4 displayParts() 读盘。用专门的假版本号，别碰 A~D 节摆在沙盒里的真版本。
    {
        const QString versionId = QStringLiteral("0.0.0-meta-check");
        const QString dir = sandbox + "/versions/" + versionId;
        QDir().mkpath(dir);
        const QString metaPath = dir + "/wtfml.meta";
        VersionManager vm;

        QFile::remove(metaPath);
        const VersionDisplayParts none = vm.displayParts(versionId);
        check(none.id == versionId && none.customName.isEmpty() && none.loaderName.isEmpty() &&
                  none.loaderVersion.isEmpty() && !none.nameFormatOverride.has_value(),
              "I4 没有 wtfml.meta 时只有 id、其余全空");

        const auto writeMeta = [&metaPath](const QByteArray &content) {
            QFile f(metaPath);
            if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
                return false;
            }
            f.write(content);
            f.close();
            return true;
        };

        check(writeMeta(R"({"name":"我的整合包","loaderName":"Forge","loaderVersion":"47.2.0"})"),
              "I4 能写出 wtfml.meta");
        const VersionDisplayParts full = vm.displayParts(versionId);
        check(full.customName == QStringLiteral("我的整合包") &&
                  full.loaderName == QStringLiteral("Forge") &&
                  full.loaderVersion == QStringLiteral("47.2.0"),
              "I4 三个字段都读出来",
              full.customName + "/" + full.loaderName + "/" + full.loaderVersion);
        check(formatVersionName(full, kStructDefault) == QStringLiteral("我的整合包-0.0.0-meta-check-Forge"),
              "I4 默认档位下拼成 自定义名-实际版本-加载器名",
              formatVersionName(full, kStructDefault));

        // realVersion：真实版本必须独立于目录名。上面那条断言同时是**回归断言** ——
        // 没写 realVersion 时参与拼装的仍是 id，与加这个字段之前逐字节一致。
        check(writeMeta(R"({"realVersion":"1.18.2"})"), "I4 能写出 realVersion");
        const VersionDisplayParts withReal = vm.displayParts(versionId);
        check(withReal.realVersion == QStringLiteral("1.18.2"), "I4 realVersion 读得出来",
              withReal.realVersion);
        check(formatVersionName(withReal, kStructDefault) == QStringLiteral("1.18.2"),
              "I4 只有 realVersion 时，名称槽退化成它而不是目录名",
              formatVersionName(withReal, kStructDefault));
        check(writeMeta(R"({"realVersion":123})"), "I4 能写出类型错的 realVersion");
        check(vm.displayParts(versionId).realVersion.isEmpty(),
              "I4 非字符串的 realVersion 被丢掉");

        // 畸形 JSON：整个文件当没有，但 id 必须还在（它是参数填的，不依赖文件）
        check(writeMeta(R"({"name":"断在这儿)"), "I4 能写出畸形 JSON");
        const VersionDisplayParts broken = vm.displayParts(versionId);
        check(broken.id == versionId && broken.customName.isEmpty(),
              "I4 畸形 JSON 当作没有元数据，id 不受影响");

        // 顶层是数组：同解析成功但 !isObject()，必须挡住
        check(writeMeta(R"(["name","我的整合包"])"), "I4 能写出顶层数组");
        check(vm.displayParts(versionId).customName.isEmpty(), "I4 顶层是数组时不当成元数据");

        // 字段类型不对：只丢该字段，别的字段照读
        check(writeMeta(R"({"name":123,"loaderName":"Forge"})"), "I4 能写出类型错的字段");
        const VersionDisplayParts mixed = vm.displayParts(versionId);
        check(mixed.customName.isEmpty() && mixed.loaderName == QStringLiteral("Forge"),
              "I4 非字符串字段只丢自己，不影响其他字段",
              mixed.customName + "/" + mixed.loaderName);

        // nameFormat 预留字段
        check(writeMeta(R"({"name":"我的整合包","nameFormat":{"showRealVersion":false}})"),
              "I4 能写出 nameFormat");
        const VersionDisplayParts withFormat = vm.displayParts(versionId);
        check(withFormat.nameFormatOverride.has_value() &&
                  !withFormat.nameFormatOverride->showRealVersion &&
                  withFormat.nameFormatOverride->showCustomName,
              "I4 nameFormat 解析成 override，没写的字段取 struct 默认值");
        check(formatVersionName(withFormat, kStructDefault) == QStringLiteral("我的整合包"),
              "I4 override 真的盖住了全局默认（全局是显示实际版本的）",
              formatVersionName(withFormat, kStructDefault));

        check(writeMeta(R"({"nameFormat":"showRealVersion"})"), "I4 能写出类型错的 nameFormat");
        check(!vm.displayParts(versionId).nameFormatOverride.has_value(),
              "I4 nameFormat 不是对象时不构造 override");

        // 撞名：<id>.json 是既定的版本 JSON 名字，元数据必须是另一个文件。
        // 这条钉的是"wtfml.meta 而不是 wtfml.json"这个决定本身。
        {
            const QString collisionId = QStringLiteral("wtfml");
            const QString collisionDir = sandbox + "/versions/" + collisionId;
            QDir().mkpath(collisionDir);
            QFile jsonFile(collisionDir + "/" + collisionId + ".json");
            if (jsonFile.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
                jsonFile.write(R"({"id":"wtfml","javaVersion":{"majorVersion":17}})");
                jsonFile.close();
            }
            QFile metaFile(collisionDir + "/wtfml.meta");
            if (metaFile.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
                metaFile.write(R"({"name":"撞名测试"})");
                metaFile.close();
            }
            VersionManager vm2;
            check(vm2.getVersionJson(collisionId).value(QStringLiteral("id")).toString() ==
                      collisionId,
                  "I4 撞名场景: 版本 JSON 读到的仍是版本 JSON");
            check(vm2.displayParts(collisionId).customName == QStringLiteral("撞名测试"),
                  "I4 撞名场景: 元数据读到的仍是元数据");

            // 别给下一次运行留脏目录：它没有 <id>.jar 所以不会被 installedVersions()
            // 认出来，但沙盒会一直长下去。
            QDir(collisionDir).removeRecursively();
        }

        QDir(dir).removeRecursively();
    }

    // I5 LauncherSettings：真值来源是 QSettings，所以要先把 QSettings 搬进沙盒。
    // 前面 E 节用真实注册表验的是 GlobalJavaSettings；这一节的键全是新加的，
    // 在用户机器上写它们没有任何意义，还会留下垃圾。
    {
        const QString settingsDir = sandbox + "/wtfml-settings";
        QDir(settingsDir).removeRecursively();
        QDir().mkpath(settingsDir);

        QSettings::setDefaultFormat(QSettings::IniFormat);
        QSettings::setPath(QSettings::IniFormat, QSettings::UserScope, settingsDir);

        // org/app 已经在 main() 开头设成 WTFML/WTFML 了。**两个都必须非空**：
        // INI 后端也会因 org 为空而 setStatus(AccessError)（qsettings.cpp:1069-1073），
        // 那样就是一个"写得进去但状态报错"的假沙盒。
        {
            QSettings probe;
            check(probe.status() == QSettings::NoError,
                  "I5 沙盒 QSettings 状态正常（org/app 都设了）",
                  QString::number(probe.status()));
        }

        LauncherSettings settings;
        check(settings.lastLaunchedVersion().isEmpty(), "I5 全新沙盒里没有『上次启动的版本』");
        check(settings.versionNameOptions() == kStructDefault, "I5 全新沙盒里是默认档位");

        settings.setLastLaunchedVersion(QStringLiteral("1.20.1"));
        settings.setVersionNameOptions([] {
            VersionNameOptions o;
            o.showLoaderVersion = true;  // 默认关，这里主动打开
            return o;
        }());
        check(settings.versionNameOptions().showLoaderVersion,
              "I5 setter 打开加载器版本后立即生效");

        // 换个实例读：验的是真的落了盘，不是留在成员变量里
        LauncherSettings reopened;
        check(reopened.lastLaunchedVersion() == QStringLiteral("1.20.1"),
              "I5 上次启动的版本跨实例读得回来", reopened.lastLaunchedVersion());
        check(reopened.versionNameOptions().showLoaderVersion,
              "I5 四个开关跨实例读得回来");

        // 「缺失前置提醒」（2026-10-09，需求一里那个勾）。它有两件事要钉死：
        //   ① 全新沙盒里**默认开着**（用户要的那个弹窗默认就弹）；
        //   ② 关掉之后**跨实例读得回来** —— 也就是说读的是盘上 `Download/WarnMissingDependencies`
        //      那个键，不是留在某个成员变量里（留在内存里的话换一个实例就"自己又打开了"）。
        check(reopened.warnMissingDependencies(),
              "I5 全新沙盒里「缺失前置提醒」默认是开的（那个弹窗默认就弹）");
        reopened.setWarnMissingDependencies(false);
        {
            LauncherSettings again;
            check(!again.warnMissingDependencies(),
                  "I5 关掉「缺失前置提醒」跨实例读得回来（读的是盘上那个键）");
        }
        reopened.setWarnMissingDependencies(true);  // 写回默认，后面的用例不许看见"关着"

        // 手改注册表/ini 是用户真会干的事，不变式必须在读的那一侧也兜住。
        // 直接往 ini 里写非法组合，再重新 load —— "手改绕不过不变式"这句话得有测试。
        {
            QSettings raw;
            raw.setValue(QStringLiteral("Version/NameShowCustom"), false);
            raw.setValue(QStringLiteral("Version/NameShowReal"), false);
            raw.setValue(QStringLiteral("Version/NameShowLoaderName"), false);
            raw.setValue(QStringLiteral("Version/NameShowLoaderVersion"), true);
            raw.sync();
        }
        LauncherSettings reloaded;
        check(reloaded.versionNameOptions().showRealVersion,
              "I5 手改成『两个都关』后 load 会强制打开版本名");
        check(!reloaded.versionNameOptions().showLoaderVersion,
              "I5 手改成『只开加载器版本』后 load 会把它关掉");

        VersionDisplayParts bare;
        bare.id = QStringLiteral("1.20.1");
        check(formatVersionName(bare, reloaded.versionNameOptions()) == QStringLiteral("1.20.1"),
              "I5 手改后的非法档位拼出来仍是版本号，不是空串",
              formatVersionName(bare, reloaded.versionNameOptions()));
        settings.save();  // 把合法值写回去，别让这条 ini 停在非法状态

        QSettings::setDefaultFormat(QSettings::NativeFormat);
        QDir(settingsDir).removeRecursively();
    }

    // I6 实际版本（realVersion）：目录名里揉着加载器时，显示名不能靠它
    //
    // 真机背景：用户的目录名是 `1.18.2-Forge_40.3.12`、`1.21.1-NeoForge_21.1.210`、
    // `26.2-Fabric 0.19.5` 这种，加载器和版本早就糊在一起了。拿目录名当"实际版本"，
    // 再往 loaderName 里填 "Forge"，就会拼出 `我的整合包-1.18.2-Forge_40.3.12-Forge`
    // —— 去重只对**完全相同**的串生效，救不了 `Forge` 和 `Forge_40.3.12`。
    // PCL 用 Setup.ini 的 VersionVanillaName 解决同一个问题。I1 那一整张表用的 parts
    // 没有 realVersion，所以它同时是"不写这个字段就零变化"的回归断言。
    {
        VersionDisplayParts p;
        p.id = QStringLiteral("我的目录名");
        p.customName = QStringLiteral("我的整合包");
        p.realVersion = QStringLiteral("1.18.2");
        p.loaderName = QStringLiteral("Forge");

        VersionNameOptions realOnly;
        realOnly.showCustomName = false;
        realOnly.showRealVersion = true;
        realOnly.showLoaderName = false;
        realOnly.showLoaderVersion = false;

        check(formatVersionName(p, kStructDefault) == QStringLiteral("我的整合包-1.18.2-Forge"),
              "I6 默认档位 -> 自定义名-实际版本-加载器名",
              formatVersionName(p, kStructDefault));
        check(formatVersionName(p, realOnly) == QStringLiteral("1.18.2"),
              "I6 只勾版本名 -> 是 realVersion，不是目录名",
              formatVersionName(p, realOnly));
        check(!formatVersionName(p, kStructDefault).contains(QStringLiteral("我的目录名")),
              "I6 realVersion 有值时，目录名不出现在显示名里",
              formatVersionName(p, kStructDefault));

        // 目录名恰好等于 realVersion（1.20.1 这种没改过名的实例是常态）：
        // 退化路径和显式路径必须给出同一个结果，不能拼出重复段。
        VersionDisplayParts same;
        same.id = QStringLiteral("1.18.2");
        same.realVersion = QStringLiteral("1.18.2");
        same.loaderName = QStringLiteral("Forge");
        check(formatVersionName(same, kStructDefault) == QStringLiteral("1.18.2-Forge"),
              "I6 realVersion 与目录名相同时不拼出重复段",
              formatVersionName(same, kStructDefault));

        // 用户手写的字段一律当不可信输入，realVersion 也要过清洗
        VersionDisplayParts dirty;
        dirty.id = QStringLiteral("目录名");
        dirty.realVersion = QStringLiteral("  1.18.2\n");
        check(formatVersionName(dirty, realOnly) == QStringLiteral("1.18.2"),
              "I6 realVersion 的首尾空白和换行被清掉",
              formatVersionName(dirty, realOnly));
        dirty.realVersion = QString(200, QLatin1Char('v'));
        check(formatVersionName(dirty, realOnly).size() == 64,
              "I6 超长 realVersion 被截到 64 字符",
              QString::number(formatVersionName(dirty, realOnly).size()));
    }

    // I7 launchStatusName()：底栏左下角「启动中...」那句里的实例名。
    //
    // 用户 2026-09-24 原话：「启动的时候…文本为版本名（没有就版本号-加载器名称，**不受名字
    // 显示设置影响**）启动中...」。这个函数的签名里**没有 options 参数**就是那句话的骨架
    // （想传开关都没处传），下面再用真值表把两档的具体写法钉死。
    {
        VersionDisplayParts p;
        p.id = QStringLiteral("1.21.1-NeoForge_21.1.210");  // 真机上目录名的样子
        p.realVersion = QStringLiteral("1.21.1");
        p.loaderName = QStringLiteral("NeoForge");
        p.loaderVersion = QStringLiteral("21.1.210");

        // ① 没有自定义名 → "版本号-加载器名"。**用的是 realVersion 不是目录名** ——
        //    拿目录名会拼出 `1.21.1-NeoForge_21.1.210-NeoForge`（版本号和加载器各说两遍）。
        check(launchStatusName(p) == QStringLiteral("1.21.1-NeoForge"),
              "I7 没重命名过 -> 版本号-加载器名", launchStatusName(p));
        check(!launchStatusName(p).contains(QStringLiteral("NeoForge_21.1.210")),
              "I7 不拿目录名当版本号（那会把加载器名也说两遍）", launchStatusName(p));

        // ② 有自定义名 → **只用名字**。这一条是"照 formatVersionName() 凑一个开关组合"
        //    凑不出来的地方：凑出来的会是 `我的整合包-1.21.1-NeoForge`。
        p.customName = QStringLiteral("我的整合包");
        check(launchStatusName(p) == QStringLiteral("我的整合包"),
              "I7 重命名过 -> 只有名字，不缀版本号和加载器", launchStatusName(p));
        check(!launchStatusName(p).contains(QStringLiteral("NeoForge")),
              "I7 有名字时结果里不含加载器名", launchStatusName(p));

        // ③ 「不受名字显示设置影响」：把四个开关摆遍所有组合，这一句都不许变
        //    （拿 formatVersionName() 对照着钉——它在某些档位下**就是**会变）。
        bool stable = true;
        bool formatMoves = false;
        for (int mask = 0; mask < 16; ++mask) {
            VersionNameOptions o;
            o.showCustomName = (mask & 1) != 0;
            o.showRealVersion = (mask & 2) != 0;
            o.showLoaderName = (mask & 4) != 0;
            o.showLoaderVersion = (mask & 8) != 0;
            if (launchStatusName(p) != QStringLiteral("我的整合包")) {
                stable = false;
            }
            if (formatVersionName(p, o) != QStringLiteral("我的整合包")) {
                formatMoves = true;
            }
        }
        check(stable, "I7 十六种开关组合下「启动中」那句的名字一个字都不变");
        check(formatMoves, "I7 （对照）formatVersionName() 在同样这些档位下确实会变");

        // ④ 没有自定义名、也没有加载器名 → 就是版本号
        VersionDisplayParts vanilla;
        vanilla.id = QStringLiteral("1.20.1");
        check(launchStatusName(vanilla) == QStringLiteral("1.20.1"),
              "I7 原版实例 -> 就是版本号", launchStatusName(vanilla));

        // ⑤ realVersion 为空时退化成目录名（和 formatVersionName() 同一条兜底：
        //    这个实例在"启动中"和下拉框里必须报同一个版本号）
        VersionDisplayParts noReal;
        noReal.id = QStringLiteral("26.2-Fabric 0.19.5");
        noReal.loaderName = QStringLiteral("Fabric");
        check(launchStatusName(noReal) == QStringLiteral("26.2-Fabric 0.19.5-Fabric"),
              "I7 realVersion 为空时用目录名兜底（和 formatVersionName 同一处退化）",
              launchStatusName(noReal));
        // ⑤b realVersion **非空、但清洗完为空**（只有空白 / 控制字符 —— wtfml.meta 是能手改
        //     的文本文件）⇒ 必须和上面那一档给同一个答案。2026-09-26 之前这一格两边是分开的：
        //     formatVersionName() 先清洗再判空，而 launchStatusName() 先判空再清洗 ⇒
        //     列表里显示目录名、底栏"启动中"那句显示加载器名 —— "两处必须一致"当时是假的。
        VersionDisplayParts blankReal;
        blankReal.id = QStringLiteral("26.2-Fabric 0.19.5");
        blankReal.realVersion = QStringLiteral("   ");
        blankReal.loaderName = QStringLiteral("Fabric");
        check(launchStatusName(blankReal) == launchStatusName(noReal),
              "I7 realVersion 只有空白时和「空」走同一条兜底（判空要排在清洗**之后**）",
              launchStatusName(blankReal));

        // ⑥ 目录名也是空的（理论上不会）：有什么给什么，别以分隔符打头
        VersionDisplayParts onlyLoader;
        onlyLoader.loaderName = QStringLiteral("Fabric");
        check(launchStatusName(onlyLoader) == QStringLiteral("Fabric"),
              "I7 只有加载器名时不会拼出以 - 打头的串", launchStatusName(onlyLoader));

        // ⑦ 手写的字段照旧当不可信输入清洗（这一串要摆进底栏那一格，那格宽度是钉死的）
        VersionDisplayParts dirty;
        dirty.id = QStringLiteral("1.20.1");
        dirty.customName = QStringLiteral("  我的\n整合包  ");
        check(launchStatusName(dirty) == QStringLiteral("我的 整合包"),
              "I7 自定义名里的换行折成空格、首尾空白去掉", launchStatusName(dirty));
        dirty.customName = QString(200, QLatin1Char('n'));
        check(launchStatusName(dirty).size() == 64, "I7 超长自定义名截到 64 字符",
              QString::number(launchStatusName(dirty).size()));
    }

    return 0;
}

// ---------------------------------------------------------------------------
// J. 已安装版本扫描：名字对不上时必须说一声
//
// 真机背景：用户的 versions/ 里有目录被手动改过名、里面的 jar 却还叫旧名字
// （851 MB 和 388 MB 的整合包各一个）。判据**不放松** —— 放宽成"目录里有任意 .jar
// 就算已安装"会把下载中途失败留下的半个版本也收进来 —— 但静默忽略会让用户以为
// 启动器坏了。这一节钉的是"必须上报"，且不该被误报的东西（空目录、散落的 zip）
// 一条都不能报。
//
// NOTE: installedVersions() 走 AppPaths::versionsDir()，也就是 exe 旁边的
// .minecraft/versions，正好就是本文件里那个 sandbox。displayParts 那几节同理。
// ---------------------------------------------------------------------------
static int runVersionJvmArgsTests(const QString &sandbox) {
    section("K. 按版本的自定义 JVM 参数（wtfml.meta 的 jvmArgs）");

    const QString versionsRoot = sandbox + "/versions";
    const QString versionId = QStringLiteral("参数版本");
    const QString metaPath = versionsRoot + "/" + versionId + "/wtfml.meta";
    QDir().mkpath(versionsRoot + "/" + versionId);

    const auto writeMeta = [&metaPath](const QByteArray &content) {
        QFile file(metaPath);
        if (file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            file.write(content);
        }
    };

    VersionManager vm;

    // 文件不存在 -> 空列表，而且**不打日志**（每个已安装版本都会被问一次，打日志就是刷屏）
    QFile::remove(metaPath);
    check(vm.versionJvmArgs(versionId).isEmpty(), "K1 没有 wtfml.meta 时返回空列表");

    // 正常：数组逐条按原顺序取出
    writeMeta(R"({"jvmArgs": ["-XX:+PerfDisableSharedMem", "-Xss1M"]})");
    const QStringList normal = vm.versionJvmArgs(versionId);
    check(normal == QStringList({QStringLiteral("-XX:+PerfDisableSharedMem"),
                                 QStringLiteral("-Xss1M")}),
          "K2 数组按原顺序逐条取出", normal.join(QStringLiteral(" | ")));

    // 参数本身含空格也不能被切开（这正是用数组而不是空格分隔字符串的理由）
    writeMeta(R"({"jvmArgs": ["-Dfoo=bar baz"]})");
    const QStringList withSpace = vm.versionJvmArgs(versionId);
    check(withSpace.size() == 1 && withSpace.first() == QStringLiteral("-Dfoo=bar baz"),
          "K2 含空格的单条参数不被切开", withSpace.join(QStringLiteral(" | ")));

    // 类型错：不是数组 -> 当空（并告警）
    out() << "  —— 下面几条 qWarning 是**预期**的（故意写坏的元数据）——\n";
    writeMeta(R"({"jvmArgs": "-XX:+PerfDisableSharedMem"})");
    check(vm.versionJvmArgs(versionId).isEmpty(), "K3 jvmArgs 是字符串时当空（不是数组）");

    // 数组里有非字符串元素 -> 跳过那一个、留下其余的
    writeMeta(R"({"jvmArgs": ["-Xss1M", 42, null, "-XX:+UseG1GC"]})");
    const QStringList mixed = vm.versionJvmArgs(versionId);
    check(mixed == QStringList({QStringLiteral("-Xss1M"), QStringLiteral("-XX:+UseG1GC")}),
          "K3 数组里的非字符串元素被跳过、其余保留", mixed.join(QStringLiteral(" | ")));

    // 空串元素会被丢掉：空参数传给 JVM 是纯粹的噪音，QProcess 也会把它当独立参数
    writeMeta(R"({"jvmArgs": ["", "-Xss1M"]})");
    check(vm.versionJvmArgs(versionId) == QStringList({QStringLiteral("-Xss1M")}),
          "K4 空串元素被丢掉");

    writeMeta(R"({"jvmArgs": []})");
    check(vm.versionJvmArgs(versionId).isEmpty(), "K4 空数组返回空列表");

    // 字段缺失 / 值是 null：与"文件不存在"一样是空，不算错
    writeMeta(R"({"name": "只是有个名字"})");
    check(vm.versionJvmArgs(versionId).isEmpty(), "K4 没有 jvmArgs 字段时返回空列表");
    writeMeta(R"({"jvmArgs": null})");
    check(vm.versionJvmArgs(versionId).isEmpty(), "K4 jvmArgs 是 null 时返回空列表");

    // 整个文件是坏 JSON -> 当没有（readVersionMeta 会告警）
    writeMeta("{ 这不是 JSON");
    check(vm.versionJvmArgs(versionId).isEmpty(), "K5 元数据文件坏掉时返回空列表");

    // 与 displayParts() 共用同一份读盘逻辑：同一份文件里读名字和读参数互不影响
    writeMeta(R"({"name": "我的整合包", "realVersion": "1.18.2",
                 "jvmArgs": ["-XX:+PerfDisableSharedMem"]})");
    const VersionDisplayParts parts = vm.displayParts(versionId);
    check(parts.customName == QStringLiteral("我的整合包") &&
              parts.realVersion == QStringLiteral("1.18.2"),
          "K6 同一份元数据里名字字段照常读到", parts.customName + "/" + parts.realVersion);
    check(vm.versionJvmArgs(versionId) ==
              QStringList({QStringLiteral("-XX:+PerfDisableSharedMem")}),
          "K6 同一份元数据里 jvmArgs 也照常读到");

    // 清理：留着会让下一次运行读到脏数据（这个目录没有 <id>.jar，本来也不会被认成版本）
    QDir(versionsRoot + "/" + versionId).removeRecursively();
    check(vm.versionJvmArgs(versionId).isEmpty(), "K7 清理后回到空列表");

    return 0;
}

// 实例判据：InstanceFiles::resolve() 的纯函数真值表 + 两条走真磁盘的对照。
// 真值表是**手算的**，所以它能挡住"改了判据没人发现"。
static int runInstanceFileTests(const QString &sandbox) {
    section("N. 实例判据（认得出哪个是客户端 jar）");

    const auto listing = [](const QString &dir, const QStringList &jars,
                            const QStringList &jsons) {
        InstanceFiles::DirListing l;
        l.dirName = dir;
        l.jarNames = jars;
        l.jsonNames = jsons;
        return l;
    };

    {
        // ① 精确匹配优先 —— 即使还有别的 jar 也轮不到它们。
        const auto r = InstanceFiles::resolve(
            listing(QStringLiteral("1.20.1"),
                    {QStringLiteral("1.20.1.jar"), QStringLiteral("别的.jar")},
                    {QStringLiteral("1.20.1.json")}));
        check(r.recognized() && r.jarName == QStringLiteral("1.20.1.jar"),
              "N1 有 <目录名>.jar 时用它（哪怕旁边还有别的 jar）", r.jarName);
        check(r.jsonName == QStringLiteral("1.20.1.json"), "N1 json 也精确匹配", r.jsonName);
    }
    {
        // ② 顶层恰好一个 jar —— 用户自己在资源管理器里改过目录名的那类。
        const auto r = InstanceFiles::resolve(
            listing(QStringLiteral("名字对不上"), {QStringLiteral("旧名字.jar")},
                    {QStringLiteral("旧名字.json")}));
        check(r.recognized() && r.jarName == QStringLiteral("旧名字.jar"),
              "N1 顶层恰好一个 jar 时用它（目录名被外部改过）", r.jarName);
        check(r.jsonName == QStringLiteral("旧名字.json"), "N1 json 同理", r.jsonName);
    }
    {
        // 大小写：Windows 文件系统不区分大小写，改名时只改了大小写不该认不出来。
        const auto r = InstanceFiles::resolve(listing(QStringLiteral("mypack"),
                                                     {QStringLiteral("MyPack.jar")}, {}));
        check(r.recognized() && r.jarName == QStringLiteral("MyPack.jar"),
              "N1 精确匹配不区分大小写，但返回磁盘上的真实拼写", r.jarName);
    }
    {
        // ③ 两个 jar 又没有精确匹配 → 不认，且候选都留着给告警用。
        const auto r = InstanceFiles::resolve(listing(QStringLiteral("两个jar"),
                                                     {QStringLiteral("aaa.jar"),
                                                      QStringLiteral("bbb.jar")},
                                                     {}));
        check(!r.recognized(), "N1 顶层两个 jar 又没有同名的那一个 → 不认");
        check(r.jarCandidates.size() == 2, "N1 认不出来时候选 jar 都留着（告警要用）",
              QString::number(r.jarCandidates.size()));
    }
    check(!InstanceFiles::resolve(listing(QStringLiteral("空的"), {}, {})).recognized(),
          "N1 一个 jar 都没有的目录不认");
    check(!InstanceFiles::resolve(listing(QStringLiteral("只有json"), {},
                                          {QStringLiteral("x.json")}))
               .recognized(),
          "N1 只有 json 没有 jar 的目录不认（下载残骸）");
    {
        // json 缺席**不**否决实例。
        const auto r = InstanceFiles::resolve(listing(QStringLiteral("缺json"),
                                                     {QStringLiteral("缺json.jar")}, {}));
        check(r.recognized() && r.jsonName.isEmpty(),
              "N1 有 jar 没有 json 时仍然认得出（json 缺席不否决）");
    }
    {
        // 两个 json 又没有精确匹配 → json 解析不出来，但**不影响**认不认得出。
        const auto r = InstanceFiles::resolve(listing(QStringLiteral("两个json"),
                                                     {QStringLiteral("两个json.jar")},
                                                     {QStringLiteral("a.json"),
                                                      QStringLiteral("b.json")}));
        check(r.recognized() && r.jsonName.isEmpty(),
              "N1 两个 json 又没同名的那一个 → json 解析不出来，但仍算实例");
    }
    {
        // ④ 一个 jar 都没有、但 json 声明了父版本 → 认得出。带模组加载器的版本长这样：
        //    Fabric 装出来的目录里只有一份 json，客户端 jar 在原版那个目录里。
        InstanceFiles::DirListing l =
            listing(QStringLiteral("fabric-loader-0.15.11-1.20.1"), {},
                    {QStringLiteral("fabric-loader-0.15.11-1.20.1.json")});
        l.inheritsFrom = QStringLiteral("1.20.1");
        const auto r = InstanceFiles::resolve(l);
        check(r.recognized(), "N1 只有 json、但 json 声明了父版本 → 认得出（Fabric 那种）");
        check(r.jarName.isEmpty(), "N1 它自己没有客户端 jar（jarName 是空的）", r.jarName);
        check(r.inheritsFrom == QStringLiteral("1.20.1"), "N1 父版本号跟着解析结果出来",
              r.inheritsFrom);
    }
    {
        // 顶层有垃圾 jar、又认不出哪个是客户端 jar，但 json 声明了父版本 → 仍然认得出。
        // 那两个 jar 跟这个版本没关系（用户丢进来的、装别的加载器剩下的），客户端 jar
        // 反正在父版本那边 —— 按 ①/② 硬挑一个才是错的。
        InstanceFiles::DirListing l = listing(QStringLiteral("混乱"),
                                              {QStringLiteral("a.jar"),
                                               QStringLiteral("b.jar")},
                                              {QStringLiteral("混乱.json")});
        l.inheritsFrom = QStringLiteral("1.20.1");
        const auto r = InstanceFiles::resolve(l);
        check(r.recognized() && r.jarName.isEmpty(),
              "N1 有垃圾 jar 但声明了父版本 → 认得出，那些 jar 不算自己的", r.jarName);
    }
    {
        // 声明了父版本、但连 json 都读不懂（inheritsFrom 空）时**不能**认 —— 下载残骸
        // 的那种目录必须继续被挡在外面，判据不能因为"多了一条路"就整体放松。
        const auto r = InstanceFiles::resolve(
            listing(QStringLiteral("坏json"), {}, {QStringLiteral("坏json.json")}));
        check(!r.recognized(), "N1 只有 json、json 又没声明父版本 → 还是不认");
    }

    // 下面两条走真磁盘：纯函数吃得对不对，取决于 scanDir 扫出来的东西对不对。
    const QString versionsRoot = sandbox + "/versions";
    {
        const QString id = QStringLiteral("N段-外部改名");
        writeFileAt(versionsRoot + "/" + id + "/" + QStringLiteral("老名字.jar"), "dummy");
        const auto r = InstanceFiles::resolveInstance(id);
        check(r.recognized() && r.jarName == QStringLiteral("老名字.jar"),
              "N2 走真磁盘扫出来的结果和纯函数一致", r.jarName);
        check(InstanceFiles::jarPath(id) == versionsRoot + "/" + id + "/老名字.jar",
              "N2 jarPath 用的是解析出来的名字，不是硬拼的", InstanceFiles::jarPath(id));

        // 不递归：实例目录底下的 libraries/ 里有几百个库 jar（下载时写在那），
        // 递归扫会把它们当成客户端 jar 的候选，"顶层恰好一个 jar"立刻失效。
        // 这条断言防的是将来有人"顺手"给 scanDir 加上 QDir::Subdirectories。
        writeFileAt(versionsRoot + "/" + id + "/libraries/net/fake/lib.jar", "dummy");
        const auto afterLibs = InstanceFiles::resolveInstance(id);
        check(afterLibs.recognized() && afterLibs.jarName == QStringLiteral("老名字.jar") &&
                  afterLibs.jarCandidates.size() == 1,
              "N2 libraries/ 里的库 jar 不算候选（扫描不递归）",
              QString::number(afterLibs.jarCandidates.size()));
        // NOTE: 清理必须能真的删干净。以前这里就地 new 了一个 QFile 写到作用域结束，
        //       句柄还开着，removeRecursively() 就删不掉 —— 每跑一次留一个目录在
        //       沙盒里，谁也没发现。走 writeFileAt() 它写完就关。
        const bool cleaned = QDir(versionsRoot + "/" + id).removeRecursively();
        check(cleaned && !QDir(versionsRoot + "/" + id).exists(),
              "N2 用完的沙盒目录删干净了（句柄没被自己攥着）");
    }
    // 继承型实例走真磁盘：jar 归谁、路径怎么拼、链走不动时怎么办。
    {
        const QString vanilla = QStringLiteral("N段-原版");
        const QString loader = QStringLiteral("N段-加载器");
        const QString loader2 = QStringLiteral("N段-加载器二层");
        writeFileAt(versionsRoot + "/" + vanilla + "/" + vanilla + ".jar", "dummy");
        writeFileAt(versionsRoot + "/" + vanilla + "/" + vanilla + ".json",
                    "{\"id\":\"" + vanilla.toUtf8() + "\"}");
        // 加载器：**只有一份 json**，一个 jar 都没有（Fabric 装出来就是这样）。
        writeFileAt(versionsRoot + "/" + loader + "/" + loader + ".json",
                    "{\"id\":\"" + loader.toUtf8() + "\",\"inheritsFrom\":\"" +
                        vanilla.toUtf8() + "\"}");
        // 二层：它继承的是另一个"自己也没有 jar"的版本 —— 链要能一路走下去。
        writeFileAt(versionsRoot + "/" + loader2 + "/" + loader2 + ".json",
                    "{\"id\":\"" + loader2.toUtf8() + "\",\"inheritsFrom\":\"" +
                        loader.toUtf8() + "\"}");

        const auto r = InstanceFiles::resolveInstance(loader);
        check(r.recognized() && r.jarName.isEmpty() && r.inheritsFrom == vanilla,
              "N4 走真磁盘：只有 json 的加载器目录被认得出来（jar 不是自己的）",
              r.inheritsFrom);

        check(InstanceFiles::jarOwnerId(loader) == vanilla,
              "N4 jar 的主人是它基于的原版", InstanceFiles::jarOwnerId(loader));
        check(InstanceFiles::jarOwnerId(loader2) == vanilla,
              "N4 链上两层都没有 jar，一路找到原版", InstanceFiles::jarOwnerId(loader2));
        check(InstanceFiles::jarName(loader) == vanilla + QStringLiteral(".jar"),
              "N4 jarName 给的是主人那个 jar 的名字（不是 <id>.jar）",
              InstanceFiles::jarName(loader));
        check(InstanceFiles::jarPath(loader) ==
                  versionsRoot + "/" + vanilla + "/" + vanilla + ".jar",
              "N4 jarPath 指着原版那个目录", InstanceFiles::jarPath(loader));
        check(InstanceFiles::jarRelativePath(loader) ==
                  QStringLiteral("versions/%1/%2.jar").arg(vanilla, vanilla),
              "N4 jarRelativePath 拼进 classpath 的那一段", InstanceFiles::jarRelativePath(loader));
        // 自立型实例（自己有 jar，且 jar 名和目录名不一样）必须与改动前逐字节一致 ——
        // 这条防的是"多了一条继承的路，把老路顺手改歪了"。
        const QString solo = QStringLiteral("N段-自立");
        writeFileAt(versionsRoot + "/" + solo + "/" + QStringLiteral("真名.jar"), "dummy");
        check(InstanceFiles::jarOwnerId(solo) == solo, "N4 自己有 jar 时主人就是自己",
              InstanceFiles::jarOwnerId(solo));
        check(InstanceFiles::jarRelativePath(solo) ==
                  QStringLiteral("versions/%1/真名.jar").arg(solo),
              "N4 自立型实例的 classpath 那一段和改动前一样",
              InstanceFiles::jarRelativePath(solo));

        // 环：A 继承 B、B 继承 A。不能死循环，也不能崩 —— 退化成链上最后一个。
        const QString ringA = QStringLiteral("N段-环A");
        const QString ringB = QStringLiteral("N段-环B");
        writeFileAt(versionsRoot + "/" + ringA + "/" + ringA + ".json",
                    "{\"id\":\"" + ringA.toUtf8() + "\",\"inheritsFrom\":\"" + ringB.toUtf8() +
                        "\"}");
        writeFileAt(versionsRoot + "/" + ringB + "/" + ringB + ".json",
                    "{\"id\":\"" + ringB.toUtf8() + "\",\"inheritsFrom\":\"" + ringA.toUtf8() +
                        "\"}");
        check(InstanceFiles::jarOwnerId(ringA) == ringB,
              "N4 继承链成环时不死循环，退化成链上最后一个",
              InstanceFiles::jarOwnerId(ringA));

        // 父版本没装：仍然算实例（列表里看得见），但 jar 的主人指向那个不存在的父版本 ——
        // 启动时那句话要说的是"父版本没装"，而不是"缺客户端 JAR"指着一个加载器目录。
        const QString orphan = QStringLiteral("N段-孤儿");
        writeFileAt(versionsRoot + "/" + orphan + "/" + orphan + ".json",
                    "{\"id\":\"" + orphan.toUtf8() +
                        "\",\"inheritsFrom\":\"N段-根本没装\"}");
        check(InstanceFiles::resolveInstance(orphan).recognized(),
              "N4 父版本没装时实例仍然认得出来（是「没装原版」，不是「不是实例」）");
        check(InstanceFiles::jarOwnerId(orphan) == QStringLiteral("N段-根本没装"),
              "N4 找不到 jar 时主人指向那个缺失的父版本（报错才指得对地方）",
              InstanceFiles::jarOwnerId(orphan));

        for (const QString &id : {vanilla, loader, loader2, ringA, ringB, orphan, solo}) {
            QDir(versionsRoot + "/" + id).removeRecursively();
        }
        check(!QDir(versionsRoot + "/" + loader).exists(),
              "N4 继承型用例的沙盒目录删干净了");
    }

    {
        // 解析不出来时退回老名字 —— 只想拿个名字去看看在不在的调用方在正常目录上逐字节不变。
        const QString missing = QStringLiteral("N段-不存在");
        check(InstanceFiles::jarName(missing) == missing + QStringLiteral(".jar"),
              "N3 认不出时 jarName 退回 <id>.jar（老行为）", InstanceFiles::jarName(missing));
        check(InstanceFiles::jsonName(missing) == missing + QStringLiteral(".json"),
              "N3 认不出时 jsonName 退回 <id>.json", InstanceFiles::jsonName(missing));
        check(InstanceFiles::jarPath(missing) ==
                  AppPaths::versionJarPath(missing),
              "N3 认不出时 jarPath 与改动前逐字节一致", InstanceFiles::jarPath(missing));
    }

    return 0;
}

// wtfml.meta 的写侧：合并写、坏文件拒绝写、稳定 id 幂等。
// 这个文件以前只有读侧，重命名 / 分组 / 每实例设置三件事都靠这一层。
static int runVersionMetaWriteTests(const QString &sandbox) {
    section("O. wtfml.meta 写侧（合并写、坏文件拒写、稳定 id）");

    const QString versionsRoot = sandbox + "/versions";
    const QString id = QStringLiteral("O段-元数据");
    const QString metaPath = versionsRoot + "/" + id + "/wtfml.meta";
    writeFileAt(versionsRoot + "/" + id + "/" + id + ".jar", "dummy");

    const auto readMetaFile = [&]() {
        QFile f(metaPath);
        if (!f.open(QIODevice::ReadOnly)) {
            return QJsonObject();
        }
        return QJsonDocument::fromJson(f.readAll()).object();
    };
    const auto writeMetaFile = [&](const QByteArray &bytes) { writeFileAt(metaPath, bytes); };

    VersionManager vm;

    // ---- 合并写：只动点名要改的键，用户手写的那几个原样留着 ----
    // 用真字段名（name / loaderName / …）。NOTE: 显示名在文件里叫 `name`，
    // 而 VersionDisplayParts 里那个成员叫 `customName` —— 这一段的重点之一就是
    // "写进去的东西读侧真的看得见"，两边用不同的名字正是最容易写错的地方。
    writeMetaFile(R"({"name":"我的整合包","loaderName":"Forge","loaderVersion":"47.2.0",
                      "jvmArgs":["-Dfoo=bar baz"],"realVersion":"1.20.1"})");
    {
        QJsonObject fields;
        fields.insert(QStringLiteral("name"), QStringLiteral("改过的名字"));
        QString error;
        check(vm.updateVersionMeta(id, fields, &error), "O1 合并写成功", error);
    }
    {
        const QJsonObject after = readMetaFile();
        check(after.value(QStringLiteral("name")).toString() == QStringLiteral("改过的名字"),
              "O1 点名的那个键被改掉了");
        // 写侧 → 读侧的往返：displayParts() 是这套字段真正的消费者，它读得到才算数。
        check(vm.displayParts(id).customName == QStringLiteral("改过的名字"),
              "O1 写进去的显示名，读侧（displayParts）真的看得见",
              vm.displayParts(id).customName);
        check(vm.displayParts(id).loaderName == QStringLiteral("Forge") &&
                  vm.displayParts(id).loaderVersion == QStringLiteral("47.2.0"),
              "O1 读侧看到的加载器字段还是老样子");
        check(after.value(QStringLiteral("loaderName")).toString() == QStringLiteral("Forge") &&
                  after.value(QStringLiteral("loaderVersion")).toString() ==
                      QStringLiteral("47.2.0"),
              "O1 没点名的加载器字段原样保留（没被整体覆盖）");
        check(after.value(QStringLiteral("realVersion")).toString() == QStringLiteral("1.20.1"),
              "O1 realVersion 也留着");
        const QJsonArray jvm = after.value(QStringLiteral("jvmArgs")).toArray();
        check(jvm.size() == 1 && jvm.first().toString() == QStringLiteral("-Dfoo=bar baz"),
              "O1 用户手写的 jvmArgs 逐字保留（含空格那条）");
    }

    // ---- 传 null 是"删掉这个键"，不是"写成 null" ----
    {
        QJsonObject fields;
        fields.insert(QStringLiteral("loaderName"), QJsonValue::Null);
        QString error;
        check(vm.updateVersionMeta(id, fields, &error), "O2 传 null 删字段成功", error);
        const QJsonObject after = readMetaFile();
        check(!after.contains(QStringLiteral("loaderName")),
              "O2 那个键真的不在了（不是留了个 null）");
        check(after.contains(QStringLiteral("loaderVersion")),
              "O2 旁边的键没被牵连");
    }

    // ---- 坏文件：拒绝写，且一个字节都不动 ----
    writeMetaFile("{ 这不是 JSON");
    {
        QByteArray before;
        {
            QFile f(metaPath);
            if (f.open(QIODevice::ReadOnly)) {
                before = f.readAll();
            }
        }
        QJsonObject fields;
        fields.insert(QStringLiteral("name"), QStringLiteral("不该写进去"));
        QString error;
        check(!vm.updateVersionMeta(id, fields, &error), "O3 坏文件时拒绝写");
        check(!error.isEmpty(), "O3 拒绝写时给出了能看懂的原因", error);
        QByteArray after;
        {
            QFile f(metaPath);
            if (f.open(QIODevice::ReadOnly)) {
                after = f.readAll();
            }
        }
        check(after == before, "O3 被拒绝时原文件逐字节不变（用户写坏的内容还在，没被吞掉）");
    }

    // ---- 没有这个文件时可以新建 ----
    QFile::remove(metaPath);
    {
        QJsonObject fields;
        fields.insert(QStringLiteral("name"), QStringLiteral("新建的"));
        QString error;
        check(vm.updateVersionMeta(id, fields, &error), "O4 文件不存在时能建出来", error);
        check(vm.displayParts(id).customName == QStringLiteral("新建的"),
              "O4 建出来的内容对（读侧看得见）", vm.displayParts(id).customName);
    }

    // ---- 稳定 id：只生成一次，第二次读回来的必须是同一个 ----
    QFile::remove(metaPath);
    {
        check(vm.instanceId(id).isEmpty(), "O5 没写过时没有稳定 id（读侧不生成）");
        check(vm.instanceId(id).isEmpty(), "O5 再读一次还是没有（没有偷偷写盘）");
        check(!QFile::exists(metaPath), "O5 只读不会把文件造出来");

        const QString first = vm.ensureInstanceId(id);
        check(!first.isEmpty(), "O5 ensureInstanceId 拿到了一个 id", first);
        check(QFile::exists(metaPath), "O5 这时文件真的落盘了");
        check(vm.instanceId(id) == first, "O5 从盘上读得回来（不是只在内存里）");
        check(vm.ensureInstanceId(id) == first, "O5 再 ensure 一次是同一个 id（幂等）");

        // 换一个 VersionManager 读：它不知道内存里的任何东西，只能靠盘上的文件。
        VersionManager other;
        check(other.instanceId(id) == first, "O5 换一个对象读到的还是同一个（真的落盘了）");
    }
    {
        // 稳定 id 和显示名能共存，互不干扰。
        QJsonObject fields;
        fields.insert(QStringLiteral("name"), QStringLiteral("带 id 的实例"));
        check(vm.updateVersionMeta(id, fields), "O6 有 id 之后再写别的字段照样成功");
        check(!vm.instanceId(id).isEmpty(), "O6 稳定 id 没被后续写入挤掉");
        check(vm.displayParts(id).customName == QStringLiteral("带 id 的实例"),
              "O6 显示名也写进去了（读侧看得见）", vm.displayParts(id).customName);
    }
    {
        // 手改坏的 instanceId（类型不对）当没有处理 —— 下次 ensure 会生成一个新的覆盖它。
        writeMetaFile(R"({"instanceId": 12345, "name":"id 被写坏了"})");
        check(vm.instanceId(id).isEmpty(), "O7 instanceId 不是字符串时当没有（不返回垃圾）");
        const QString regenerated = vm.ensureInstanceId(id);
        check(!regenerated.isEmpty() && !regenerated.contains(QStringLiteral("12345")),
              "O7 坏值被一个新的 UUID 顶掉", regenerated);
        check(vm.instanceId(id) == regenerated, "O7 换回来的新 id 读得回来");
        check(readMetaFile().value(QStringLiteral("name")).toString() ==
                  QStringLiteral("id 被写坏了"),
              "O7 顶掉坏 id 时没把旁边的显示名一起抹掉");
    }

    const bool cleaned = QDir(versionsRoot + "/" + id).removeRecursively();
    check(cleaned && !QDir(versionsRoot + "/" + id).exists(),
          "O8 用完的沙盒目录删干净了（句柄没被自己攥着）");
    return 0;
}

// 重命名：名字校验的真值表 + 真改磁盘目录名（含失败路径）。
static int runRenameInstanceTests(const QString &sandbox) {
    section("P. 重命名实例（名字校验 + 真改目录名）");

    const QString versionsRoot = sandbox + "/versions";

    // 造文件走 writeFileAt()（文件级那个 helper）：它写完就关句柄，理由见那儿的 NOTE。
    const auto writeFile = [](const QString &path, const QByteArray &bytes) {
        writeFileAt(path, bytes);
    };

    // ---------- P1 名字校验的真值表 ----------
    // 合法的那一半里，前几个是**真机上真实存在**的实例名，不是编的。
    {
        const QStringList legal = {
            QStringLiteral("我的整合包"),
            QStringLiteral("原版ATT2地图（无模组）"),
            QStringLiteral("26.2-Fabric 0.19.5"),
            QStringLiteral("1.18.2-Forge_40.3.12"),
            QStringLiteral("a"),
            QStringLiteral("带 空格 的 名字"),
            QStringLiteral("版本.1"),
            QStringLiteral("v1-测试_02"),
            QString(QStringLiteral("长").repeated(64)),
        };
        for (const QString &name : legal) {
            const QString problem = InstanceFiles::validateDirName(name);
            check(problem.isEmpty(), QStringLiteral("P1 合法：%1").arg(name), problem);
        }
    }
    {
        // 每一条都写清"为什么必须非法"，将来有人放松规则时这些会红给他看。
        const QList<QPair<QString, QString>> illegal = {
            {QString(), QStringLiteral("空名字")},
            {QStringLiteral("   "), QStringLiteral("全是空白")},
            {QStringLiteral("a/b"), QStringLiteral("斜杠（路径穿越）")},
            {QStringLiteral("a\\b"), QStringLiteral("反斜杠（路径穿越）")},
            {QStringLiteral("../跑出去"), QStringLiteral("相对路径（路径穿越）")},
            {QStringLiteral("."), QStringLiteral("单个点")},
            {QStringLiteral(".."), QStringLiteral("两个点")},
            {QStringLiteral("a:b"), QStringLiteral("冒号")},
            {QStringLiteral("a*b"), QStringLiteral("星号")},
            {QStringLiteral("a?b"), QStringLiteral("问号")},
            {QStringLiteral("a\"b"), QStringLiteral("双引号")},
            {QStringLiteral("a<b"), QStringLiteral("小于号")},
            {QStringLiteral("a>b"), QStringLiteral("大于号")},
            {QStringLiteral("a|b"), QStringLiteral("竖线")},
            {QStringLiteral("名字."), QStringLiteral("结尾的点（Windows 会静默吃掉）")},
            {QStringLiteral("a\tb"), QStringLiteral("制表符")},
            {QStringLiteral("CON"), QStringLiteral("保留设备名 CON")},
            {QStringLiteral("con"), QStringLiteral("保留设备名 con（不区分大小写）")},
            {QStringLiteral("CON.txt"), QStringLiteral("保留设备名带扩展名")},
            {QStringLiteral("COM1"), QStringLiteral("保留设备名 COM1")},
            {QStringLiteral("LPT9"), QStringLiteral("保留设备名 LPT9")},
            {QStringLiteral("NUL"), QStringLiteral("保留设备名 NUL")},
            {QStringLiteral("CONIN$"), QStringLiteral("保留设备名 CONIN$（控制台输入口）")},
            {QStringLiteral("conout$"), QStringLiteral("保留设备名 conout$（大小写不区分）")},
            {QStringLiteral("COM¹"), QStringLiteral("保留设备名 COM¹（U+00B9，Windows 认）")},
            {QStringLiteral("LPT³"), QStringLiteral("保留设备名 LPT³（U+00B3）")},
            {QString(QStringLiteral("长").repeated(65)), QStringLiteral("65 个字符（超一个）")},
        };
        for (const auto &entry : illegal) {
            const QString problem = InstanceFiles::validateDirName(entry.first);
            check(!problem.isEmpty(), QStringLiteral("P1 非法：%1").arg(entry.second));
        }
    }
    {
        // 反过来那一侧：**不是**保留名的不能被误判（2026-09-25 补）。COM0 / LPT0 看着像
        // 设备名，实测**不是**（GetFullPathName 不把它们映射进设备命名空间，建目录照建）；
        // 上标那一族里只有 ¹²³ 三个算设备名，`COM´`（U+00B4，重音符）不算。
        // 判据要是写成"以 COM 开头就拒"，用户给实例起名 COM0 会收到一句"这个名字不能用"
        // 而完全不知道为什么 —— 过严和过松一样是错的，两条边界都得有人钉。
        check(InstanceFiles::validateDirName(QStringLiteral("COM0")).isEmpty(),
              "P1 合法：COM0（设备名只到 COM9，0 不在里面）");
        check(InstanceFiles::validateDirName(QStringLiteral("LPT0")).isEmpty(),
              "P1 合法：LPT0 同上");
        check(InstanceFiles::validateDirName(QStringLiteral("COM´")).isEmpty(),
              "P1 合法：COM´（U+00B4 是重音符，不是上标一）");
    }
    {
        // 首尾空白先 trim 再判 —— 用户多敲一个空格不是错误，规整掉正是他想要的。
        // 所以"名字 "是**合法**的（会被改名叫"名字"），这一点和"名字."（非法）
        // 的不对称是刻意的：trim 管得着空格，管不着点。
        check(InstanceFiles::validateDirName(QStringLiteral(" 我的整合包 ")).isEmpty(),
              "P1 首尾空白先 trim 再判");
        check(InstanceFiles::validateDirName(QStringLiteral("我的整合包 ")).isEmpty(),
              "P1 尾随空格不拒绝（trim 会处理掉它，不该逼用户重打一遍）");
    }

    // ---------- P2 重名比较 ----------
    {
        const QString a = QStringLiteral("P2-版本A");
        const QString b = QStringLiteral("P2-版本B");
        writeFile(versionsRoot + "/" + a + "/" + a + ".jar", "dummy");

        check(!InstanceFiles::validateRenameTarget(a, b).isEmpty(),
              "P2 撞上已有实例的名字会被挡下");
        check(!InstanceFiles::validateRenameTarget(QStringLiteral("p2-版本a"), b).isEmpty(),
              "P2 重名比较不区分大小写（Windows 的文件系统本来就不区分）");
        check(!InstanceFiles::validateRenameTarget(a, a).isEmpty(),
              "P2 名字一个字没改会被挡下");
        // 只差大小写：合法。它改的是磁盘上那个名字的显示大小写，目标"已存在"的
        // 那个其实就是它自己。
        check(InstanceFiles::validateRenameTarget(QStringLiteral("p2-版本a"), a).isEmpty(),
              "P2 只改大小写是合法的（那不是重名，是同一个目录）",
              InstanceFiles::validateRenameTarget(QStringLiteral("p2-版本a"), a));
        check(!InstanceFiles::validateRenameTarget(QStringLiteral("a/b"), a).isEmpty(),
              "P2 形状问题照样先报出来");

        QDir(versionsRoot + "/" + a).removeRecursively();
    }

    // ---------- P3 真改磁盘 ----------
    const auto makeInstance = [&](const QString &id, const QString &jarName) {
        writeFile(versionsRoot + "/" + id + "/" + jarName, "dummy");
        writeFile(versionsRoot + "/" + id + "/" + id + ".json", "{}");
    };

    VersionManager vm;
    {
        const QString oldId = QStringLiteral("P3-老名");
        const QString newId = QStringLiteral("P3-新名");
        makeInstance(oldId, oldId + ".jar");
        // 用户手写的字段：改名是**合并**写，它必须活下来。
        writeFile(AppPaths::versionMetaPath(oldId),
                  R"({"jvmArgs":["-Dkeep=me"],"realVersion":"1.20.1"})");

        QString error;
        check(vm.renameInstance(oldId, newId, &error), "P3 改名成功", error);
        check(!QDir(AppPaths::versionDir(oldId)).exists(), "P3 老目录不在了");
        check(QDir(AppPaths::versionDir(newId)).exists(), "P3 新目录在");
        check(QFile::exists(versionsRoot + "/" + newId + "/" + newId + ".jar"),
              "P3 jar 跟着改了名");
        check(QFile::exists(versionsRoot + "/" + newId + "/" + newId + ".json"),
              "P3 json 也跟着改了名");
        check(!QFile::exists(versionsRoot + "/" + newId + "/" + oldId + ".jar"),
              "P3 老名字的 jar 没留下");

        check(vm.displayParts(newId).customName == newId,
              "P3 显示名写成了新名字", vm.displayParts(newId).customName);
        check(vm.displayParts(newId).realVersion == QStringLiteral("1.20.1"),
              "P3 用户手写的 realVersion 活着（改名是合并写）",
              vm.displayParts(newId).realVersion);
        check(vm.versionJvmArgs(newId).contains(QStringLiteral("-Dkeep=me")),
              "P3 用户手写的 jvmArgs 也活着",
              vm.versionJvmArgs(newId).join(QLatin1Char(' ')));
        check(!vm.instanceId(newId).isEmpty(), "P3 顺手定下了稳定 id（分组归属要用它）",
              vm.instanceId(newId));

        check(InstanceFiles::resolveInstance(newId).recognized(), "P3 改完名之后判据认得出来");
        const QStringList installed = vm.installedVersions();
        check(installed.contains(newId) && !installed.contains(oldId),
              "P3 列表里新名字在、老名字不在了");

        QDir(versionsRoot + "/" + newId).removeRecursively();
    }

    // ---------- P4 jar 名和目录名本来就不一致的实例 ----------
    // 判据放松之后这种目录是"认得出"的，改名时顺带把它**规范**回 <目录名>.jar。
    {
        const QString oldId = QStringLiteral("P4-改过名的");
        const QString newId = QStringLiteral("P4-规范了");
        makeInstance(oldId, QStringLiteral("老jar名.jar"));
        QString error;
        check(vm.renameInstance(oldId, newId, &error), "P4 能改（判据认得出它）", error);
        check(QFile::exists(versionsRoot + "/" + newId + "/" + newId + ".jar"),
              "P4 改完名 jar 就叫 <新目录名>.jar 了（顺手规范回来）");
        check(!QFile::exists(versionsRoot + "/" + newId + "/老jar名.jar"), "P4 老 jar 名没留下");
        QDir(versionsRoot + "/" + newId).removeRecursively();
    }

    // ---------- P5 没有 json 的实例 ----------
    // 半个版本（只有 jar）：改名不能因为它没有 json 就失败，也不许凭空造一个 json 出来。
    {
        const QString oldId = QStringLiteral("P5-没有json");
        const QString newId = QStringLiteral("P5-改完了");
        writeFile(versionsRoot + "/" + oldId + "/" + oldId + ".jar", "dummy");
        QString error;
        check(vm.renameInstance(oldId, newId, &error), "P5 没有 json 也能改名", error);
        check(QFile::exists(versionsRoot + "/" + newId + "/" + newId + ".jar"), "P5 jar 改好了");
        check(!QFile::exists(versionsRoot + "/" + newId + "/" + newId + ".json"),
              "P5 没有凭空造出一个 json（原来没有就该还是没有）");
        QDir(versionsRoot + "/" + newId).removeRecursively();
    }

    // ---------- P6 只改大小写 ----------
    // 走的是 MoveFileEx，改的只是磁盘上那个名字的显示大小写。真机上"用户想把
    // 小写开头改成大写开头"是很正常的要求，而这一条最容易在实现里被"目标已存在"
    // 那道检查误伤。
    {
        const QString oldId = QStringLiteral("P6-case");
        const QString newId = QStringLiteral("P6-Case");
        makeInstance(oldId, oldId + ".jar");
        QString error;
        const bool ok = vm.renameInstance(oldId, newId, &error);
        check(ok, "P6 只改大小写能成功", error);
        if (ok) {
            const QStringList entries =
                QDir(versionsRoot).entryList(QDir::Dirs | QDir::NoDotAndDotDot);
            check(entries.contains(newId) && !entries.contains(oldId),
                  "P6 磁盘上的目录名真的换成了新的大小写", entries.join(QLatin1Char('|')));
            check(QFile::exists(versionsRoot + "/" + newId + "/" + newId + ".jar"),
                  "P6 jar 的大小写也跟着改了");
            QDir(versionsRoot + "/" + newId).removeRecursively();
        } else {
            QDir(versionsRoot + "/" + oldId).removeRecursively();
        }
    }

    // ---------- P7 失败路径：磁盘不能被动过 ----------
    {
        const QString kept = QStringLiteral("P7-别动我");
        const QString other = QStringLiteral("P7-已经在了");
        makeInstance(kept, kept + ".jar");
        makeInstance(other, other + ".jar");
        writeFile(versionsRoot + "/" + other + "/内容是别的.txt", "xx");

        QString error;
        check(!vm.renameInstance(kept, other, &error), "P7 撞上已有实例时拒绝改名");
        check(!error.isEmpty(), "P7 给了原因", error);

        // 一个字节都不能动：老目录还在、老 jar 还在、目标目录里的东西也没被盖掉。
        check(QFile::exists(versionsRoot + "/" + kept + "/" + kept + ".jar"),
              "P7 失败之后老 jar 还在");
        check(QFile::exists(versionsRoot + "/" + other + "/" + other + ".jar"),
              "P7 目标目录里原来的 jar 还在（没被静默盖掉）");
        check(QFile::exists(versionsRoot + "/" + other + "/内容是别的.txt"),
              "P7 目标目录里别的东西也没被动过");
        check(!QFile::exists(AppPaths::versionMetaPath(kept)),
              "P7 前置检查阶段就退出了：连 meta 都没建出来");

        // 目录不存在的实例
        check(!vm.renameInstance(QStringLiteral("P7-压根没有"), QStringLiteral("P7-x"), &error),
              "P7 目录不存在时拒绝改名");
        check(!error.isEmpty(), "P7 也给了原因", error);

        // 名字不合法
        check(!vm.renameInstance(kept, QStringLiteral("a/b"), &error), "P7 名字非法时拒绝改名");
        check(QFile::exists(versionsRoot + "/" + kept + "/" + kept + ".jar"),
              "P7 非法名字没碰到磁盘");

        QDir(versionsRoot + "/" + kept).removeRecursively();
        QDir(versionsRoot + "/" + other).removeRecursively();
    }

    // ---------- P8 坏 meta 时拒绝改名 ----------
    // 和写侧同一条规矩：往一份读不懂的内容上合并 = 丢用户手写的东西。改名走的是
    // 同一条写路径，所以这里必须一样地拒绝，而且**目录名一个字节都不能动**。
    {
        const QString oldId = QStringLiteral("P8-坏meta");
        makeInstance(oldId, oldId + ".jar");
        writeFile(AppPaths::versionMetaPath(oldId), "{ 这不是 JSON");
        QString error;
        check(!vm.renameInstance(oldId, QStringLiteral("P8-新名"), &error),
              "P8 meta 坏掉时拒绝改名");
        check(QDir(AppPaths::versionDir(oldId)).exists(),
              "P8 目录名没动（失败发生在改名字之前）");
        check(!QDir(AppPaths::versionDir(QStringLiteral("P8-新名"))).exists(),
              "P8 也没留下一个新目录");
        QDir(versionsRoot + "/" + oldId).removeRecursively();
    }

    // ---------- P9 沙盒收拾干净 ----------
    // 各分支自己都删过，但"到底删掉没有"要有一条统一的断言兜着：N / O 两段就因为
    // 攥着文件句柄，removeRecursively() 一直静默失败，每跑一次在沙盒里留一个目录，
    // 而所有断言照样全绿。那种漏法只能靠这种"回头看一眼"的断言抓住。
    {
        const QStringList left = QDir(versionsRoot).entryList(
            QStringList() << QStringLiteral("P*"), QDir::Dirs | QDir::NoDotAndDotDot);
        check(left.isEmpty(), "P9 P 段造出来的目录一个都没剩下", left.join(QLatin1Char('|')));
    }

    return 0;
}

// 实例分组：<数据目录>/wtfml.folders。
//
// NOTE: 这一段里所有"到底写进盘里没有"的断言，一律**换一个 InstanceGroupStore 对象读回来**
//       再判。拿同一个对象自证等于没验：它把读到的内容缓存在 m_root 里，盘上那份哪怕一个
//       字节都没动，同一个对象也照样能"读出"它内存里那份看起来正确的值来。
// NOTE: 反过来，每个"先自己写一份原始文件、再读"的子段都必须**新建一个 store**：按需重读
//       的触发条件是"目录变了"，不是"文件变了"（见 InstanceGroupStore::ensureLoaded()）。
//       这是设计如此 —— 一份 .minecraft 里的文件不会被别人改，能改它的只有启动器自己。
static int runInstanceGroupTests(const QString &sandbox) {
    section("Q. 实例分组（wtfml.folders）");

    const QString versionsRoot = sandbox + "/versions";
    const QString groupFile = AppPaths::instanceGroupFilePath();

    // 这个文件只有这一节会造，但"起点是干净的"得自己保证 —— Q1 那两条断言（读到空、
    // 光读不写盘）都建立在"文件不存在"之上。
    QDir().remove(groupFile);
    check(!QFile::exists(groupFile), "Q1 前提：沙盒里本来没有 wtfml.folders");

    const auto readBytes = [&]() {
        QFile file(groupFile);
        if (!file.open(QIODevice::ReadOnly)) {
            return QByteArray();
        }
        const QByteArray bytes = file.readAll();
        file.close();  // Windows：别攥着句柄，后面还要删它
        return bytes;
    };
    const auto writeRaw = [&](const QByteArray &bytes) { writeFileAt(groupFile, bytes); };
    const auto readRaw = [&]() { return QJsonDocument::fromJson(readBytes()).object(); };

    const QString packId = QStringLiteral("11111111-1111-1111-1111-111111111111");
    const QString modId = QStringLiteral("22222222-2222-2222-2222-222222222222");

    // ---------- Q1 没有文件时读到空，而且不写盘 ----------
    {
        InstanceGroupStore store;
        check(store.groups().isEmpty(), "Q1 没有文件时组清单是空的");
        check(store.groupIdOf(QStringLiteral("随便什么实例")).isEmpty(), "Q1 归属也是空的");
        check(!QFile::exists(groupFile), "Q1 光是读不会把文件造出来");
    }

    // ---------- Q2 建两个组：落盘、读得回来、读不发声 ----------
    {
        InstanceGroupStore store;
        int changed = 0;
        QObject::connect(&store, &InstanceGroupStore::groupsChanged, [&changed] { ++changed; });

        QList<InstanceGroupStore::Group> groups;
        groups.append({packId, QStringLiteral("整合包")});
        groups.append({modId, QStringLiteral("模组")});
        QString error;
        check(store.replaceGroups(groups, &error), "Q2 写入两个组成功", error);
        check(changed == 1, "Q2 写成功发了一次 groupsChanged", QString::number(changed));
        check(QFile::exists(groupFile), "Q2 文件落盘了");
    }
    {
        InstanceGroupStore other;
        int changed = 0;
        QObject::connect(&other, &InstanceGroupStore::groupsChanged, [&changed] { ++changed; });

        const QList<InstanceGroupStore::Group> groups = other.groups();
        check(groups.size() == 2, "Q2 另一个对象读回来两个组", QString::number(groups.size()));
        check(!groups.isEmpty() && groups.at(0).id == packId &&
                  groups.at(0).name == QStringLiteral("整合包"),
              "Q2 第一个组的 id 和名字都对");
        check(groups.size() > 1 && groups.at(1).id == modId &&
                  groups.at(1).name == QStringLiteral("模组"),
              "Q2 第二个组也对，而且顺序就是用户排的那个（不是按 id 排）");
        check(readRaw().value(QStringLiteral("version")).toInt() == 1,
              "Q2 文件里带着格式版本 1");
        check(changed == 0, "Q2 光是读不发 groupsChanged", QString::number(changed));
    }

    // ---------- Q3 不认识的字段原样留着 ----------
    // 模拟"更新版本的启动器往里写了别的东西"：我们碰一次之后，那些字段必须还在文件里。
    // 这是我们唯一能做的向后兼容 —— 反过来（把不认识的键抹掉）在用户那边的表现是
    // "换回旧版启动器打开一次，新版的分组颜色/图标就没了"，而且完全无声。
    {
        QJsonObject root = readRaw();
        root.insert(QStringLiteral("将来的字段"), QStringLiteral("别弄丢我"));
        writeRaw(QJsonDocument(root).toJson(QJsonDocument::Indented));

        InstanceGroupStore store;
        QList<InstanceGroupStore::Group> groups = store.groups();
        check(groups.size() == 2, "Q3 前提：带着未知字段的文件照样读得出两个组");
        groups[0].name = QStringLiteral("整合包（改过名）");
        QString error;
        check(store.replaceGroups(groups, &error), "Q3 改完组名写回去成功", error);

        const QJsonObject after = readRaw();
        check(after.value(QStringLiteral("将来的字段")).toString() == QStringLiteral("别弄丢我"),
              "Q3 不认识的字段没被抹掉");
        check(after.value(QStringLiteral("groups")).toArray().at(0).toObject()
                  .value(QStringLiteral("name")).toString() == QStringLiteral("整合包（改过名）"),
              "Q3 名字确实改了");
        const QList<InstanceGroupStore::Group> reread = InstanceGroupStore().groups();
        check(reread.size() == 2 && reread.at(0).id == packId,
              "Q3 改名不动 id —— 归属挂的是 id，不是名字");
    }

    // ---------- Q3b 手改过的归属（值两端多了空格）：读得出来，而且下一次写盘不许丢 ----------
    // 读侧（groupIdOf）读的是 trim 过的值，写侧（writeThrough）原来**不 trim** 就把它拿去
    // 和清洗过的组 id 比 —— 两边不一致时，记事本里多敲两个空格的那一条在界面上是一条完全
    // 正常的归属，而**任何一次写盘**（改别的实例的分组就会重写整份文件）都会把它当成
    // "指向一个不存在的组"悄悄清掉：用户下次打开就是"这个实例怎么又回未分组了"，
    // 而且没有任何提示（2026-09-25 修，写侧那一句见 writeThrough）。
    //
    // NOTE: 这一小段把**整份文件**换成它自己那一份（要的就是"手改过的文件"那个形状），
    //       所以先留一份原样，验完再写回去 —— 下一节 Q4 用的那两个组就在里面，
    //       不还回去的话它会以"找不到那个分组"红给你看（而那是这一段的锅）。
    const QByteArray q3bBefore = readBytes();
    {
        const QString paddedKey = QStringLiteral("Q3b-实例");
        QJsonObject root;
        root.insert(QStringLiteral("version"), 1);
        QJsonArray groupArray;
        QJsonObject groupObject;
        groupObject.insert(QStringLiteral("id"), QStringLiteral("q3b-group"));
        groupObject.insert(QStringLiteral("name"), QStringLiteral("手改的组"));
        groupArray.append(groupObject);
        root.insert(QStringLiteral("groups"), groupArray);
        QJsonObject membersObject;
        membersObject.insert(paddedKey, QStringLiteral("  q3b-group  "));
        root.insert(QStringLiteral("members"), membersObject);
        writeRaw(QJsonDocument(root).toJson(QJsonDocument::Indented));

        InstanceGroupStore reader;
        check(reader.groupIdOf(paddedKey) == QStringLiteral("q3b-group"),
              "Q3b 值两端带空格的归属读得出来（读侧本来就 trim）",
              reader.groupIdOf(paddedKey));
        // 写一次盘：给**另一个**实例归组，整份文件就会被重写（用户那边就是这个形状）。
        QString error;
        check(reader.assign(QStringLiteral("Q3b-别的实例"), QStringLiteral("q3b-group"), &error),
              "Q3b 顺手改一个别的实例的归属（这一次写盘会把整份文件重写一遍）", error);
    }
    {
        // **换一个对象**读回来：同一个对象读的是它内存里那份，盘上丢没丢看不出来。
        InstanceGroupStore after;
        check(after.groupIdOf(QStringLiteral("Q3b-实例")) == QStringLiteral("q3b-group"),
              "Q3b 写盘之后那一条还在（不许当成「指向不存在的组」清掉）",
              after.groupIdOf(QStringLiteral("Q3b-实例")));
        check(after.groupIdOf(QStringLiteral("Q3b-别的实例")) == QStringLiteral("q3b-group"),
              "Q3b 这一次新归的那条也在");
        writeRaw(q3bBefore);
        check(InstanceGroupStore().groupIdOf(QStringLiteral("Q3b-实例")).isEmpty(),
              "Q3b 收尾：把文件还回去（Q4 那一节用的两个组就在那一份里）");
    }

    // ---------- Q4 归组 ----------
    {
        InstanceGroupStore store;
        QString error;
        check(store.assign(QStringLiteral("Q4-实例A"), packId, &error), "Q4 归组成功", error);
        check(store.assign(QStringLiteral("Q4-实例B"), packId, &error),
              "Q4 第二个实例也归进同一个组", error);
        check(store.groupIdOf(QStringLiteral("Q4-实例A")) == packId, "Q4 同一个对象里读得到");
        check(store.groupIdOf(QStringLiteral("Q4-实例C")).isEmpty(), "Q4 没归过的是未分组");
    }
    {
        InstanceGroupStore other;
        check(other.groupIdOf(QStringLiteral("Q4-实例A")) == packId,
              "Q4 另一个对象也读得到（真的落盘了）");
        check(other.groupIdOf(QStringLiteral("Q4-实例B")) == packId, "Q4 实例 B 也是");
        const QString stored = readRaw().value(QStringLiteral("members")).toObject()
                                   .value(QStringLiteral("Q4-实例A")).toString();
        check(stored == packId, "Q4 成员表里存的就是组 id（不是组名）", stored);
    }

    // ---------- Q5 改名搬运（rekey） ----------
    {
        InstanceGroupStore store;
        QString error;
        check(store.rekey(QStringLiteral("Q4-实例A"), QStringLiteral("Q5-实例A-新名"), &error),
              "Q5 改名搬运成功", error);
    }
    {
        InstanceGroupStore other;
        check(other.groupIdOf(QStringLiteral("Q4-实例A")).isEmpty(), "Q5 老键上没有归属了");
        check(other.groupIdOf(QStringLiteral("Q5-实例A-新名")) == packId, "Q5 归属搬到新键上");
        check(other.groupIdOf(QStringLiteral("Q4-实例B")) == packId,
              "Q5 别人的归属一个都没动");
    }

    // ---------- Q6 无事可做的几个空操作**一个字节都不写盘** ----------
    // 这条只能这么验：**把文件删掉**，再调那几个空操作 —— 只要有一个真的写了盘，
    // 文件就会重新出现。比"内容没变"强，因为内容没变也可能是重写了一遍一模一样的。
    //
    // 为什么在乎：用户只是改了个名（没分过组），不该平白多出一个 wtfml.folders。
    {
        QDir().remove(groupFile);
        check(!QFile::exists(groupFile), "Q6 前提：文件删掉了");

        InstanceGroupStore store;
        QString error;
        check(store.rekey(QStringLiteral("Q6-同名"), QStringLiteral("Q6-同名"), &error),
              "Q6 两个键一样时返回成功");
        check(store.rekey(QStringLiteral("Q6-压根没这个键"), QStringLiteral("Q6-新"), &error),
              "Q6 老键本来就没归属时返回成功");
        check(store.rekey(QString(), QStringLiteral("Q6-新"), &error), "Q6 空键时返回成功");
        check(store.rekey(QStringLiteral("Q6-新"), QString(), &error), "Q6 新键为空时返回成功");
        check(!QFile::exists(groupFile), "Q6 这几个空操作一个字节都没写盘");
    }

    // ---------- Q7 删组：清掉指向它的成员条目，实例一个不动 ----------
    {
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"},"
            "{\"id\":\"g2\",\"name\":\"乙\"}],"
            "\"members\":{\"Q7-实例A\":\"g1\",\"Q7-实例B\":\"g2\",\"Q7-实例C\":\"g1\"}}"));

        // 造两个真目录，证明"删组不删实例"不是嘴上说说 —— 这是全段唯一碰 versions/ 的地方。
        const QString dirA = versionsRoot + "/Q7-实例A";
        writeFileAt(dirA + "/Q7-实例A.jar", "not a real jar");
        writeFileAt(dirA + "/q7-留个记号.txt", "别删我");

        InstanceGroupStore store;
        QList<InstanceGroupStore::Group> kept;
        kept.append({QStringLiteral("g2"), QStringLiteral("乙")});
        QString error;
        check(store.replaceGroups(kept, &error), "Q7 全量替换成只剩乙组成功", error);

        InstanceGroupStore other;
        const QList<InstanceGroupStore::Group> groups = other.groups();
        check(groups.size() == 1 && groups.first().id == QStringLiteral("g2"),
              "Q7 另一个对象读回来只剩一个组", QString::number(groups.size()));
        check(other.groupIdOf(QStringLiteral("Q7-实例A")).isEmpty(),
              "Q7 甲组里的实例变成未分组");
        check(other.groupIdOf(QStringLiteral("Q7-实例C")).isEmpty(), "Q7 另一个也是");
        check(other.groupIdOf(QStringLiteral("Q7-实例B")) == QStringLiteral("g2"),
              "Q7 别的组的归属一点没动");
        check(!readRaw().value(QStringLiteral("members")).toObject()
                   .contains(QStringLiteral("Q7-实例A")),
              "Q7 指向已删组的成员条目从文件里清掉了（不留一条谁都查不到的残留）");
        check(QFile::exists(dirA + "/Q7-实例A.jar") &&
                  QFile::exists(dirA + "/q7-留个记号.txt"),
              "Q7 实例目录里一个文件都没少 —— 删组从来不删实例");

        QDir(dirA).removeRecursively();
    }

    // ---------- Q8 assign 的失败路径 ----------
    {
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"}],\"members\":{}}"));
        const QByteArray before = readBytes();

        InstanceGroupStore store;
        QString error;
        check(!store.assign(QStringLiteral("Q8-实例"), QStringLiteral("没有这个组"), &error),
              "Q8 归到一个不存在的组时拒绝");
        check(!error.isEmpty(), "Q8 而且给了原因", error);
        check(!store.assign(QString(), QStringLiteral("g1"), &error), "Q8 空实例键时拒绝");
        check(!error.isEmpty(), "Q8 也给了原因", error);
        check(readBytes() == before, "Q8 两次失败的写入一个字节都没落盘");

        // 取消分组（空 groupId）不需要那个组存在，本来就该成功
        error.clear();  // 免得上面那两条失败的原因被当成这两条的 detail 打出来
        check(store.assign(QStringLiteral("Q8-实例"), QStringLiteral("g1"), &error),
              "Q8 归到存在的组成功", error);
        check(store.assign(QStringLiteral("Q8-实例"), QString(), &error),
              "Q8 取消分组成功（不要求任何组存在）", error);
        check(InstanceGroupStore().groupIdOf(QStringLiteral("Q8-实例")).isEmpty(),
              "Q8 取消之后这个实例读回来还是未分组（空串）");

        // 但文件里那一条**留着**，写的是那个保留值（2026-09-24 改的）。以前这里写的是
        // "成员表里那条没了"，而那条现在是**错**的：删掉条目 = 用户从来没表过态，于是
        // MainWindow 下一次刷新就按版本类型把它归类回去 —— 表现是"点了确定没生效"。
        // 两者在界面上是同一格，在文件里必须分得开，理由见 ungroupedMarker() 那段。
        const QJsonObject markedMembers =
            readRaw().value(QStringLiteral("members")).toObject();
        check(markedMembers.size() == 1 &&
                  markedMembers.value(QStringLiteral("Q8-实例")).toString() ==
                      InstanceGroupStore::ungroupedMarker(),
              "Q8 取消分组在文件里写成那个保留值（不是把条目删掉）",
              markedMembers.value(QStringLiteral("Q8-实例")).toString());
    }

    // ---------- Q9 读不懂的文件：读到空 + 拒绝写 ----------
    // 拒绝写和 wtfml.meta 是同一条规矩：往一份读不懂的内容上合并 = 把用户的东西丢掉。
    // 今天能造出这种文件的只有"用户手改"和"文件坏了"，两种都不该被我们悄悄抹掉。
    {
        const QByteArray broken = QByteArrayLiteral("{ \"version\": 1, \"groups\": [ ");
        writeRaw(broken);
        InstanceGroupStore store;
        check(store.groups().isEmpty(), "Q9 坏 JSON 时当没有组");
        check(store.groupIdOf(QStringLiteral("Q8-实例")).isEmpty(), "Q9 坏 JSON 时归属也算没有");

        QList<InstanceGroupStore::Group> groups;
        groups.append({packId, QStringLiteral("想覆盖它")});
        QString error;
        check(!store.replaceGroups(groups, &error), "Q9 读不懂的文件拒绝写");
        check(!error.isEmpty(), "Q9 而且说清了原因", error);
        check(!store.assign(QStringLiteral("Q8-实例"), QString(), &error),
              "Q9 另一条写路径（assign）同样拒绝");
        check(readBytes() == broken, "Q9 拒绝写之后文件逐字节没动");
    }
    {
        const QByteArray future = QByteArrayLiteral(
            "{\"version\":2,\"groups\":[{\"id\":\"g1\",\"name\":\"将来的组\"}]}");
        writeRaw(future);
        InstanceGroupStore store;
        check(store.groups().isEmpty(), "Q9 格式版本不认识时当空（不猜新旧格式的差别）");

        QList<InstanceGroupStore::Group> groups;
        groups.append({packId, QStringLiteral("我")});
        QString error;
        check(!store.replaceGroups(groups, &error), "Q9 版本不认识时拒绝写（别把它降级成 v1）");
        check(readBytes() == future, "Q9 文件逐字节没动");
    }

    // ---------- Q10 不可信数据清洗 ----------
    {
        // 成员指向一个**已经不存在的组**：这是"组被删了但两边不同步"的正常残留，
        // 当未分组处理、不报错；清理交给下一次写。
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"}],"
            "\"members\":{\"Q10-实例A\":\"g1\",\"Q10-实例B\":\"早就没了的组\"}}"));
        InstanceGroupStore store;
        check(store.groupIdOf(QStringLiteral("Q10-实例A")) == QStringLiteral("g1"),
              "Q10 正常的那条读得到");
        check(store.groupIdOf(QStringLiteral("Q10-实例B")).isEmpty(),
              "Q10 指向不存在的组时当未分组（它不在 groups() 里）");

        QString error;
        QList<InstanceGroupStore::Group> groups = store.groups();
        check(store.replaceGroups(groups, &error), "Q10 随便写一次成功", error);
        check(!readRaw().value(QStringLiteral("members")).toObject()
                   .contains(QStringLiteral("Q10-实例B")),
              "Q10 下一次写的时候顺手把那条悬空的清掉了");
        check(InstanceGroupStore().groupIdOf(QStringLiteral("Q10-实例A")) ==
                  QStringLiteral("g1"),
              "Q10 而正常那条留着");
    }
    {
        // 组条目本身的问题：没 id 的认不出来、id 重复的说不清指谁、名字为空至少退回 id。
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"name\":\"没有 id 的组\"},"
            "{\"id\":\"g1\",\"name\":\"甲\"},{\"id\":\"g1\",\"name\":\"乙\"},"
            "{\"id\":\"g2\"},{\"id\":\"\",\"name\":\"空 id\"}]}"));
        const QList<InstanceGroupStore::Group> groups = InstanceGroupStore().groups();
        check(groups.size() == 2, "Q10 没 id / 空 id 的丢掉了，重复 id 的只留一个",
              QString::number(groups.size()));
        check(!groups.isEmpty() && groups.at(0).id == QStringLiteral("g1") &&
                  groups.at(0).name == QStringLiteral("甲"),
              "Q10 重复 id 留的是第一个");
        check(groups.size() > 1 && groups.at(1).id == QStringLiteral("g2") &&
                  groups.at(1).name == QStringLiteral("g2"),
              "Q10 名字为空时退回 id（界面上至少还认得出来是哪一个）");
    }
    {
        // 成员表里塞了非字符串的值：认不出来就当没分过组，别让 QJsonValue::toString()
        // 的"空串"悄悄变成一个合法键。
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"}],"
            "\"members\":{\"Q10-实例A\":{\"这是\":\"对象\"},\"Q10-实例B\":\"g1\",\"\":\"g1\"}}"));
        InstanceGroupStore store;
        check(store.groupIdOf(QStringLiteral("Q10-实例A")).isEmpty(),
              "Q10 成员值不是字符串时当没有");
        check(store.groupIdOf(QString()).isEmpty(), "Q10 空键当成没有");
        check(store.groupIdOf(QStringLiteral("Q10-实例B")) == QStringLiteral("g1"),
              "Q10 同一个文件里正常那条照样读得到");
    }
    {
        // 文件在但内容是空的（用户清空过、或者写了一半）：不该崩，当空。
        writeRaw(QByteArray());
        InstanceGroupStore store;
        check(store.groups().isEmpty(), "Q10 空文件当没有组");
    }

    // ---------- Q11 换游戏文件夹 = 自动换一套分组 ----------
    // 没有任何"重置"钩子，靠的是访问器内部比较 AppPaths::minecraftDir()。所以要验的
    // 恰恰是"**同一个对象**在目录变了之后自己重读了" —— 换个新对象来验就绕过了这条。
    {
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"第一份的组\"}],"
            "\"members\":{\"Q11-实例\":\"g1\"}}"));
        const QString second = QCoreApplication::applicationDirPath() + "/.minecraft-Q11";
        QDir(second).removeRecursively();
        QDir().mkpath(second);

        const QString first = AppPaths::minecraftDir();
        const QByteArray firstBytes = readBytes();
        InstanceGroupStore store;
        check(store.groups().size() == 1 &&
                  store.groups().first().name == QStringLiteral("第一份的组"),
              "Q11 前提：读到的是第一份的组");

        AppPaths::setMinecraftDir(second);
        check(AppPaths::instanceGroupFilePath() == second + "/wtfml.folders",
              "Q11 文件路径跟着目录走");
        check(store.groups().isEmpty(), "Q11 换到第二份（还没有文件）时读到空");
        QString error;
        QList<InstanceGroupStore::Group> groups;
        groups.append({QStringLiteral("g-second"), QStringLiteral("第二份的组")});
        check(store.replaceGroups(groups, &error), "Q11 在第二份里建组成功", error);
        check(QFile::exists(second + "/wtfml.folders"),
              "Q11 文件落在第二份目录里，没有写回第一份");

        AppPaths::setMinecraftDir(first);
        check(readBytes() == firstBytes, "Q11 第一份那个文件逐字节没被动过");
        check(store.groups().size() == 1 &&
                  store.groups().first().name == QStringLiteral("第一份的组"),
              "Q11 切回来读到的是第一份的组（同一个对象，没人通知它）");
        check(store.groupIdOf(QStringLiteral("Q11-实例")) == QStringLiteral("g1"),
              "Q11 第一份的归属也回来了");

        QDir(second).removeRecursively();
        check(!QDir(second).exists(), "Q11 第二份目录删干净了（没攥着文件句柄）");
    }

    // ---------- Q9b 文件读不懂时，assign 报的是**真因**，不是「找不到那个分组」 ----------
    //
    // 2026-09-24 改的：assign() 原来先判"这个组在不在已知表里"，而一份读不懂的文件会让
    // groups() 返回空表 —— 于是用户一路被告知"找不到那个分组，可能刚刚被删掉了"，而
    // 分组一个都没删，是这一版压根没读进来。查错会查到"我是不是点错了"上去。
    {
        const QByteArray broken = QByteArrayLiteral("{ 这不是 JSON");
        writeRaw(broken);
        InstanceGroupStore store;

        QString assignError;
        check(!store.assign(QStringLiteral("Q9b-实例"), QStringLiteral("随便哪个组"), &assignError),
              "Q9b 文件读不懂时 assign 拒绝写");
        QString replaceError;
        check(!store.replaceGroups(store.groups(), &replaceError),
              "Q9b 同一条路上 replaceGroups 也拒绝");
        // 两条路的理由必须是**同一句话**：它们说的是同一件事（写侧那道闸就在
        // writeThrough() 开头），措辞不一样的话用户看到的解释会随他点了哪个按钮变。
        check(assignError == replaceError,
              "Q9b assign 和 replaceGroups 报的是同一句话（都是那份文件读不懂的真因）",
              QStringLiteral("assign=[%1] replace=[%2]").arg(assignError, replaceError));
        check(!assignError.isEmpty() &&
                  !assignError.contains(QStringLiteral("找不到那个分组")),
              "Q9b 报的不是「找不到那个分组」（那是被挡住的那个假因）", assignError);
        check(!assignError.contains(QStringLiteral("没有指定要给哪个实例分组")),
              "Q9b 也不是判错成「空键」那条内部错误");
        check(readBytes() == broken, "Q9b 拒绝之后文件逐字节没动");
    }

    // ---------- Q13 写盘失败不许在内存里留下幽灵状态 ----------
    //
    // 这一条验的是 writeThrough() 里那份 candidate 副本（2026-09-24 改的）。原来那三句
    // 直接盖在 m_root 上，而后面三条失败路径都不回滚 —— 于是"告知失败"的那个操作会先在
    // 内存里生效（groups() / groupIdOf() 读的正是 m_root），接着**另一次成功的写盘**会把
    // 这份幽灵状态一起提交：「说失败的操作在稍后静默生效」。
    //
    // 怎么造"读没事、只有写失败"：先让那个对象**正常加载**一份文件，再把文件路径占成
    // 一个**目录** —— QSaveFile 提交不了。顺序很讲究：反过来（一开始就是目录）的话加载那
    // 一步就会失败，对象会记住"这个文件打不开"并从此拒绝一切写（见 ensureLoaded 里那段），
    // 那样验到的就不是幽灵、而是另一条闸了。
    {
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"}]}"));
        InstanceGroupStore store;
        check(store.groups().size() == 1, "Q13 前提：这个对象正常加载了那份文件");

        // 目录一占上，写的每一条路都得断，而加载那一步不会再跑（对象已经认下了目录）。
        QDir().remove(groupFile);
        check(QDir().mkpath(groupFile), "Q13 前提：把 wtfml.folders 占成一个目录");

        QList<InstanceGroupStore::Group> groups;
        groups.append({QStringLiteral("g1"), QStringLiteral("甲")});
        groups.append({QStringLiteral("g-幽灵"), QStringLiteral("幽灵组")});
        QString error;
        check(!store.replaceGroups(groups, &error), "Q13 写盘失败时如实返回 false", error);
        check(!error.isEmpty(), "Q13 失败原因说的是那句「打不开 / 写不进去」", error);
        // 这一条就是幽灵本身：写盘失败了，那它就不该在内存里出现。
        check(store.groups().size() == 1 &&
                  store.groups().first().id == QStringLiteral("g1"),
              "Q13 写失败之后内存里还是原来那一个组（失败不许先在内存里生效）",
              QStringLiteral("%1 个组").arg(store.groups().size()));
        check(store.groupIdOf(QStringLiteral("Q13-实例")).isEmpty(),
              "Q13 内存里也没多出别的归属");

        // 失败之后**另一次成功的写盘**：落盘的内容里不能带着上一次那笔。
        check(QDir().rmdir(groupFile), "Q13 把那个占位的目录拿掉");
        check(QDir().mkpath(AppPaths::minecraftDir()), "Q13 数据目录还在");
        QString error2;
        check(store.replaceGroups(store.groups(), &error2),
              "Q13 路径恢复之后这个对象写成功（它没被那次失败卡死）", error2);
        check(store.assign(QStringLiteral("Q13-实例"), QStringLiteral("g1"), &error2),
              "Q13 正常的赋值也成功", error2);

        const QByteArray bytes = readBytes();
        const QString text = QString::fromUtf8(bytes);
        check(!text.contains(QStringLiteral("幽灵")),
              "★ Q13 落盘那份里没有那次失败留下的「幽灵组」");
        const QJsonObject raw = QJsonDocument::fromJson(bytes).object();
        check(raw.value(QStringLiteral("groups")).toArray().size() == 1,
              "Q13 落盘那份里正好一个组（不是两个）",
              QString::number(raw.value(QStringLiteral("groups")).toArray().size()));
        // 换一个新对象读回来（同一个对象自证等于没验，见这一段开头那两条 NOTE）。
        InstanceGroupStore reread;
        check(reread.groups().size() == 1 &&
                  reread.groupIdOf(QStringLiteral("Q13-实例")) == QStringLiteral("g1"),
              "Q13 新对象读回来的就是刚写的那一份");
    }

    // ---------- Q14 五个默认组：什么时候种、什么时候一个字节都不写 ----------
    // 用户 2026-09-24 原话：「把实例分组做个默认（可安装mod，原版，快照版，远古版，置顶），
    // 默认可以删除」。**"默认可以删除"这件要求的全部实现就在 Q14b/Q14c 那两条上**：
    // 只有"文件不存在"才种，删过之后就再也不会长回来。
    {
        QDir().remove(groupFile);
        check(!QFile::exists(groupFile), "Q14 前提：先把文件拿掉");

        InstanceGroupStore store;
        int changed = 0;
        QObject::connect(&store, &InstanceGroupStore::groupsChanged, [&changed] { ++changed; });
        QString error;
        check(store.seedDefaultGroups(&error), "Q14 文件不在时种一次", error);
        check(changed == 1, "Q14 种成功发了一次 groupsChanged", QString::number(changed));
        check(QFile::exists(groupFile), "Q14 种完文件真的落盘了");

        // 五个 id 和名字都写死在这里（**不是**拿 defaultGroups() 跟自己比）：id 写歪了
        // 后果是"昨天分好的今天全回未分组"（自动归类按 id 找组，见 defaultGroupId()），
        // 那是这份文件里最不该漂的东西，值得在这里逐条钉住。
        const QList<InstanceGroupStore::Group> seeded = InstanceGroupStore().groups();
        QStringList seededPairs;
        for (const InstanceGroupStore::Group &group : seeded) {
            seededPairs << group.id + QLatin1Char('=') + group.name;
        }
        check(seededPairs == QStringList({QStringLiteral("default-pinned=置顶"),
                                          QStringLiteral("default-moddable=可安装mod"),
                                          QStringLiteral("default-vanilla=原版"),
                                          QStringLiteral("default-snapshot=快照版"),
                                          QStringLiteral("default-old=远古版")}),
              "Q14 种下去的就是那五个（id 写死、顺序就是界面上的顺序，置顶在最前）",
              seededPairs.join(QLatin1Char('|')));
        check(InstanceGroupStore::defaultGroups().size() == 5,
              "Q14 defaultGroups() 是五条",
              QString::number(InstanceGroupStore::defaultGroups().size()));

        // 读路径上的"表过态"：种子没给任何实例写归属。
        check(!InstanceGroupStore().isAssigned(QStringLiteral("Q14-没提过")),
              "Q14 刚种完，谁都没表过态（自动归类才有事可做）");
    }

    // ---------- Q14b 文件在（哪怕组全被删光了）就一个字节都不写 ----------
    {
        const QByteArray before = readBytes();
        InstanceGroupStore store;
        int changed = 0;
        QObject::connect(&store, &InstanceGroupStore::groupsChanged, [&changed] { ++changed; });
        check(store.seedDefaultGroups(), "Q14b 文件本来就在时直接成功");
        check(changed == 0, "Q14b 而且一声不响（没写盘就不该发 groupsChanged）",
              QString::number(changed));
        check(readBytes() == before, "Q14b 文件逐字节没被动过");
    }
    {
        // 用户把五个默认组**全删光**之后的样子：文件在、组清单是空的。
        // 这一条是"默认可以删除"最容易被写漏的那一格 —— 判据从"有没有那五个组"
        // 退化成"文件在不在"的话，用户删完一重启它们就全回来了。
        writeRaw(QByteArrayLiteral("{\"version\":1,\"groups\":[],\"members\":{}}"));
        const QByteArray before = readBytes();
        InstanceGroupStore store;
        check(store.seedDefaultGroups(), "Q14c 组清单是空的时候也直接成功");
        check(store.groups().isEmpty(), "Q14c 删光的组没被种回来");
        check(readBytes() == before, "Q14c 一个字节都没写盘");
    }

    // ---------- Q14d 那个保留值在各条写路径上留得住 ----------
    // 写路径的清洗规则是"指向不存在的组的归属清掉"，而保留值**不在组清单里** ——
    // 漏掉那一条例外的话，用户一按「确定」它就被清掉（="我明明选过未分组"）。
    {
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"}],"
            "\"members\":{\"Q14-明确未分组\":\"ungrouped\",\"Q14-在甲组\":\"g1\","
            "\"Q14-悬空\":\"早就没了的组\"}}"));

        InstanceGroupStore store;
        check(store.isAssigned(QStringLiteral("Q14-明确未分组")),
              "Q14d 写了保留值 = 表过态（不然会被自动归类拉走）");
        check(store.isAssigned(QStringLiteral("Q14-悬空")),
              "Q14d 指向已删组的残留也算表过态（理由见 isAssigned() 那段：删组后落未分组的"
              "那一半靠它，用不着写清理代码）");
        check(!store.isAssigned(QStringLiteral("Q14-没提过")), "Q14d 文件里没有这一条才是没表过态");
        check(!store.isAssigned(QString()), "Q14d 例外：空键一律当没表过态");
        check(store.groupIdOf(QStringLiteral("Q14-明确未分组")).isEmpty() &&
                  store.groupIdOf(QStringLiteral("Q14-悬空")).isEmpty(),
              "Q14d 两者读回来都是未分组（界面上看不出区别，文件里分得开）");

        // 别的写路径（全量替换）不能把它顺手清掉。
        QList<InstanceGroupStore::Group> groups;
        groups.append({QStringLiteral("g1"), QStringLiteral("甲")});
        QString error;
        check(store.replaceGroups(groups, &error), "Q14d 全量替换写回去成功", error);
        const QJsonObject members = readRaw().value(QStringLiteral("members")).toObject();
        check(members.value(QStringLiteral("Q14-明确未分组")).toString() ==
                  InstanceGroupStore::ungroupedMarker(),
              "Q14d ★ 保留值在写路径上留得住",
              members.value(QStringLiteral("Q14-明确未分组")).toString());
        check(members.value(QStringLiteral("Q14-在甲组")).toString() == QStringLiteral("g1"),
              "Q14d 正常那条也留着");
        check(!members.contains(QStringLiteral("Q14-悬空")),
              "Q14d 而悬空那条被清掉了（清理规则本身没被这条例外带歪）");
        check(InstanceGroupStore().isAssigned(QStringLiteral("Q14-明确未分组")),
              "Q14d 换个对象读回来还是表过态的");

        // 再走一遍 assign()：取消分组两次，结果一样是那个保留值。
        check(store.assign(QStringLiteral("Q14-明确未分组"), QString(), &error),
              "Q14d 再取消一次也成功", error);
        check(readRaw().value(QStringLiteral("members")).toObject()
                  .value(QStringLiteral("Q14-明确未分组")).toString() ==
              InstanceGroupStore::ungroupedMarker(),
              "Q14d assign(空) 写的还是保留值");
    }

    // ---------- Q15 「置顶前的归属」：置顶记下原来在哪一组，取消置顶走回去 ----------
    //
    // 用户 2026-09-26 原话：「加一个记录置顶前这玩意属于哪一组的，用户直接塞的取消置顶
    // 才归进未分类」。四种来路四种落点（完整规矩见 InstanceGroupStore 文件头那一段），
    // 外加"记录什么时候作废"（写侧那道自清理不变量）和几条空操作。
    //
    // NOTE: 这一段凡是"盘上究竟写了什么"的断言一律读**文件**（readRaw()），不问任何一个
    //       store 对象 —— 拿内存自证等于没验（见本节开头那两段）。
    {
        const auto membersInFile = [&readRaw]() {
            return readRaw().value(QStringLiteral("members")).toObject();
        };
        const auto originsInFile = [&readRaw]() {
            return readRaw().value(QStringLiteral("pinOrigin")).toObject();
        };
        // 每一条子段的起点：两个自定义组（g1「甲」/ g2「乙」= 置顶组）+ 想要的那几条归属。
        // origins 传空 = **连 pinOrigin 这一格都不写**（老文件/手改的文件就是那个样子）。
        const auto seed = [&writeRaw](const QByteArray &members, const QByteArray &origins) {
            QByteArray json = QByteArrayLiteral(
                "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"},"
                "{\"id\":\"g2\",\"name\":\"乙\",\"pinned\":true}],\"members\":");
            json += members;
            if (!origins.isEmpty()) {
                json += QByteArrayLiteral(",\"pinOrigin\":") + origins;
            }
            json += '}';
            writeRaw(json);
        };

        QString error;

        // (1) 从一个**普通的组**置顶 ⇒ 取消置顶回到那个组。
        {
            seed(QByteArrayLiteral("{\"Q15-甲组\":\"g1\"}"), QByteArray());
            InstanceGroupStore store;
            check(store.pinInstance(QStringLiteral("Q15-甲组"), &error), "Q15 置顶成功", error);
            check(membersInFile().value(QStringLiteral("Q15-甲组")).toString() ==
                      QStringLiteral("g2"),
                  "Q15 置顶 = 这一条落盘进了置顶组那一格");
            check(originsInFile().value(QStringLiteral("Q15-甲组")).toString() ==
                          QStringLiteral("g1") &&
                      !originsInFile().value(QStringLiteral("Q15-甲组")).isNull(),
                  "Q15 ★ 顺手记下了「置顶之前它在哪一组」（用户 2026-09-26 那句）",
                  originsInFile().value(QStringLiteral("Q15-甲组")).toString());
            check(store.unpinInstance(QStringLiteral("Q15-甲组"), &error), "Q15 取消置顶成功",
                  error);
            check(membersInFile().value(QStringLiteral("Q15-甲组")).toString() ==
                      QStringLiteral("g1"),
                  "Q15 ★ 取消置顶**回到置顶之前的那一组**（这一条就是这次改动要的那件事）",
                  membersInFile().value(QStringLiteral("Q15-甲组")).toString());
            check(originsInFile().isEmpty(),
                  "Q15 记录用完就删（留着的话下一次置顶会把旧账当成「置顶前」再读一遍）",
                  QString::number(originsInFile().size()));
            check(readRaw().contains(QStringLiteral("pinOrigin")),
                  "Q15 这一格还在（写侧一律写出来，空的就是 {} —— 和 expanded / pinned 同规矩）");
            check(InstanceGroupStore().groupIdOf(QStringLiteral("Q15-甲组")) ==
                      QStringLiteral("g1"),
                  "Q15 换个对象读回来也是那个组");
        }

        // (2) 从**没表过态**置顶（显示层按版本类型把它归在某组里）⇒ 取消置顶把成员条目
        //     **删掉**，让它重新按类型归类 —— 落回它置顶前**显示**的那一组。
        {
            seed(QByteArrayLiteral("{}"), QByteArray());
            InstanceGroupStore store;
            check(store.pinInstance(QStringLiteral("Q15-没提过"), &error), "Q15 置顶成功", error);
            check(originsInFile().contains(QStringLiteral("Q15-没提过")) &&
                      originsInFile().value(QStringLiteral("Q15-没提过")).isNull(),
                  "Q15 ★ 置顶前压根没有归属那一种记成 **null**（不是空串、也不是保留值）",
                  originsInFile().value(QStringLiteral("Q15-没提过")).toVariant().toString());
            check(store.unpinInstance(QStringLiteral("Q15-没提过"), &error), "Q15 取消置顶成功",
                  error);
            check(!membersInFile().contains(QStringLiteral("Q15-没提过")),
                  "Q15 ★ 取消置顶把这一条**删掉**了（不是写成「明确选了未分组」）—— 于是显示层"
                  "按版本类型再算一遍，落回它置顶前显示的那一组；写成保留值等于替用户说了一句"
                  "他没说过的话，那个实例从此再也不会被自动归类");
            check(!InstanceGroupStore().isAssigned(QStringLiteral("Q15-没提过")),
                  "Q15 读回来就是「没表过态」");
            check(originsInFile().isEmpty(), "Q15 记录也跟着没了",
                  QString::number(originsInFile().size()));
        }

        // (3) 从「未分组」（= 用户**明确**选过的那一档）置顶 ⇒ 取消置顶回到那条保留值。
        //     它和 (2) 在界面上是同一格，在文件里必须差一格 —— 这正是"别把 (2) 写成保留值"
        //     那条的反面：这里写回去的**就是**保留值，因为它本来就是保留值。
        {
            seed(QByteArrayLiteral("{\"Q15-明确未分组\":\"ungrouped\"}"), QByteArray());
            InstanceGroupStore store;
            check(store.isAssigned(QStringLiteral("Q15-明确未分组")) &&
                      store.groupIdOf(QStringLiteral("Q15-明确未分组")).isEmpty(),
                  "Q15 前提：它明确选了未分组（表过态，但读回来是空串）");
            check(store.pinInstance(QStringLiteral("Q15-明确未分组"), &error), "Q15 置顶成功",
                  error);
            check(originsInFile().value(QStringLiteral("Q15-明确未分组")).toString() ==
                      InstanceGroupStore::ungroupedMarker(),
                  "Q15 ★ 置顶前是「明确未分组」的，记的就是那个保留值本身",
                  originsInFile().value(QStringLiteral("Q15-明确未分组")).toString());
            check(store.unpinInstance(QStringLiteral("Q15-明确未分组"), &error),
                  "Q15 取消置顶成功", error);
            check(membersInFile().value(QStringLiteral("Q15-明确未分组")).toString() ==
                      InstanceGroupStore::ungroupedMarker(),
                  "Q15 ★ 取消置顶回到「明确选了未分组」那条保留值（这一条留得住，不是被删掉）",
                  membersInFile().value(QStringLiteral("Q15-明确未分组")).toString());
        }

        // (4) **用户自己塞进置顶组的** ⇒ 取消置顶落未分组（用户那句"用户直接塞的才归进未分类"）。
        //     两条来路各来一次：走 assign()（=「移入分组」那个动作），和"文件里本来就在
        //     置顶组里、连 pinOrigin 这一格都没有"（= 这一版之前的老数据）。
        {
            seed(QByteArrayLiteral("{}"), QByteArray());
            InstanceGroupStore store;
            check(store.assign(QStringLiteral("Q15-直接塞的"), QStringLiteral("g2"), &error),
                  "Q15 前提：「移入分组」把它直接塞进了置顶组", error);
            check(!originsInFile().contains(QStringLiteral("Q15-直接塞的")),
                  "Q15 ★ 塞进置顶组**不记**「置顶前的归属」—— 记的是「置顶前」那一格，而这个"
                  "动作压根不是置顶（用户那句把两条路分得很清楚）");
            check(store.unpinInstance(QStringLiteral("Q15-直接塞的"), &error), "Q15 取消置顶成功",
                  error);
            check(membersInFile().value(QStringLiteral("Q15-直接塞的")).toString() ==
                      InstanceGroupStore::ungroupedMarker(),
                  "Q15 ★ 没有记录 ⇒ 取消置顶落**未分组**（写那条保留值，和「移出分组」逐字"
                  "同一个落点）");
        }
        {
            seed(QByteArrayLiteral("{\"Q15-老数据\":\"g2\"}"), QByteArray());
            InstanceGroupStore store;
            check(!originsInFile().contains(QStringLiteral("Q15-老数据")),
                  "Q15 前提：老文件里连 pinOrigin 这一格都没有");
            check(store.unpinInstance(QStringLiteral("Q15-老数据"), &error), "Q15 取消置顶成功",
                  error);
            check(membersInFile().value(QStringLiteral("Q15-老数据")).toString() ==
                      InstanceGroupStore::ungroupedMarker(),
                  "Q15 ★ 老数据也一样落未分组（这一格没有 = 一条记录都没有，读侧不做任何猜测）");
        }

        // (5) 改名的同时把记录一起搬到新键上。
        {
            seed(QByteArrayLiteral("{\"Q15-老键\":\"g2\"}"),
                 QByteArrayLiteral("{\"Q15-老键\":\"g1\"}"));
            InstanceGroupStore store;
            check(store.rekey(QStringLiteral("Q15-老键"), QStringLiteral("Q15-新键"), &error),
                  "Q15 改名搬运成功", error);
            check(membersInFile().value(QStringLiteral("Q15-新键")).toString() ==
                          QStringLiteral("g2") &&
                      originsInFile().value(QStringLiteral("Q15-新键")).toString() ==
                          QStringLiteral("g1"),
                  "Q15 ★ 归属和「置顶前的归属」一起搬到新键上（不搬的话，改完名再取消置顶"
                  "就落未分组了，而用户什么都没做错）");
            check(!membersInFile().contains(QStringLiteral("Q15-老键")) &&
                      !originsInFile().contains(QStringLiteral("Q15-老键")),
                  "Q15 老键上两格都清干净了");
        }

        // (6) 别的动作把记录清掉 —— 写侧那道自清理不变量（只留"此刻确实待在置顶组里"的）。
        //     每一条都是"先摆成'在置顶组里、记着 g1'，再走那个动作，然后记录必须没了"。
        {
            // (6a) 移入别组。
            seed(QByteArrayLiteral("{\"Q15-搬家\":\"g2\"}"),
                 QByteArrayLiteral("{\"Q15-搬家\":\"g1\"}"));
            InstanceGroupStore store;
            check(store.assign(QStringLiteral("Q15-搬家"), QStringLiteral("g1"), &error),
                  "Q15 移入甲组成功", error);
            check(!originsInFile().contains(QStringLiteral("Q15-搬家")),
                  "Q15 ★ 挪进别组之后记录作废（它已经不在置顶组里了，那个动作只剩"
                  "「取消置顶」一个读者）");
        }
        {
            // (6b) 移出分组（= 明确选未分组）。
            seed(QByteArrayLiteral("{\"Q15-移出\":\"g2\"}"),
                 QByteArrayLiteral("{\"Q15-移出\":\"g1\"}"));
            InstanceGroupStore store;
            check(store.assign(QStringLiteral("Q15-移出"), QString(), &error), "Q15 移出分组成功",
                  error);
            check(!originsInFile().contains(QStringLiteral("Q15-移出")) &&
                      membersInFile().value(QStringLiteral("Q15-移出")).toString() ==
                          InstanceGroupStore::ungroupedMarker(),
                  "Q15 ★ 「移出分组」也把记录清掉");
        }
        {
            // (6c) 换一个置顶组：原来那一组不再是置顶组了，它的成员自然不再是"被置顶的"。
            seed(QByteArrayLiteral("{\"Q15-换置顶\":\"g2\"}"),
                 QByteArrayLiteral("{\"Q15-换置顶\":\"g1\"}"));
            InstanceGroupStore store;
            check(store.setGroupPinned(QStringLiteral("g1"), true, &error), "Q15 换成甲组当置顶组",
                  error);
            check(!originsInFile().contains(QStringLiteral("Q15-换置顶")) &&
                      membersInFile().value(QStringLiteral("Q15-换置顶")).toString() ==
                          QStringLiteral("g2"),
                  "Q15 ★ 换了置顶组 ⇒ 老记录的读者（下箭头）已经不在那一行了，记录跟着作废"
                  "（成员一个字节都没动）");
        }
        {
            // (6d) 删掉那个组（全量替换里没有 g2）。
            seed(QByteArrayLiteral("{\"Q15-删组\":\"g2\"}"),
                 QByteArrayLiteral("{\"Q15-删组\":\"g1\"}"));
            InstanceGroupStore store;
            QList<InstanceGroupStore::Group> kept;
            kept.append({QStringLiteral("g1"), QStringLiteral("甲")});
            check(store.replaceGroups(kept, &error), "Q15 换成只剩甲组的清单", error);
            check(!originsInFile().contains(QStringLiteral("Q15-删组")) &&
                      !membersInFile().contains(QStringLiteral("Q15-删组")),
                  "Q15 ★ 置顶组被删掉：指向它的归属和记录一起清（实例本身一个字节都不动）");
        }
        {
            // (6e) 恢复默认：整张清单换成五个默认组（g1/g2 都是自定义的，一起没）。
            seed(QByteArrayLiteral("{\"Q15-恢复默认\":\"g2\"}"),
                 QByteArrayLiteral("{\"Q15-恢复默认\":\"g1\"}"));
            InstanceGroupStore store;
            check(store.restoreDefaultGroups(&error), "Q15 恢复默认分组设置", error);
            check(!originsInFile().contains(QStringLiteral("Q15-恢复默认")) &&
                      !membersInFile().contains(QStringLiteral("Q15-恢复默认")),
                  "Q15 ★ 「恢复默认」也一样（记录不会跨过一整张新清单活下来）");
        }

        // (7) 几条空操作：**一个字节都不写盘**。
        {
            // 已经在置顶组里的那一条：不算失败，但也不该盖掉已有的那条记录 —— 那记的是
            // 上一次置顶之前它在哪，比此刻这一格有用得多。
            seed(QByteArrayLiteral("{\"Q15-已经在了\":\"g2\"}"),
                 QByteArrayLiteral("{\"Q15-已经在了\":\"g1\"}"));
            const QByteArray before = readBytes();
            InstanceGroupStore store;
            check(store.pinInstance(QStringLiteral("Q15-已经在了"), &error),
                  "Q15 已经在置顶组里时置顶也算成功（不是失败）", error);
            check(readBytes() == before, "Q15 ★ 一个字节都不写盘");
            check(originsInFile().value(QStringLiteral("Q15-已经在了")).toString() ==
                      QStringLiteral("g1"),
                  "Q15 ★ 也不许盖掉已有的那条记录",
                  originsInFile().value(QStringLiteral("Q15-已经在了")).toString());
        }
        {
            // 这一份 .minecraft 里没有置顶组（那颗上箭头本来就没画）。store 这一层不写盘、
            // 也不报错：这件事此刻没有去处，不是失败。
            writeRaw(QByteArrayLiteral(
                "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"}],\"members\":{}}"));
            const QByteArray before = readBytes();
            InstanceGroupStore store;
            check(store.pinInstance(QStringLiteral("Q15-没去处"), &error),
                  "Q15 没有置顶组时置顶也返回成功（这一下本来就没有去处）", error);
            check(readBytes() == before, "Q15 ★ 没有置顶组 ⇒ 一个字节都不写盘");
        }
    }

    // ---------- Q15b pinnedGroupIdOf()：写侧那道自清理和读侧那颗箭头用同一份判据 ----------
    // 抽成静态函数就是为了这两处看到的**必须是同一个答案** —— 各写一遍的话，某天有人只
    // 改了一处（比如又加一条退回的路），表现是"记录清掉的那一档和箭头送去的那一档不是
    // 同一个组"，于是取消置顶把实例送进一个它从没待过的组（中途每一步都"看起来对"）。
    {
        const auto group = [](const char *id, bool pinned) {
            InstanceGroupStore::Group g;
            g.id = QString::fromLatin1(id);
            g.name = g.id;
            g.pinned = pinned;
            return g;
        };
        check(InstanceGroupStore::pinnedGroupIdOf(QList<InstanceGroupStore::Group>()).isEmpty(),
              "Q15b 空清单 = 空串（那颗上箭头没有去处）");
        // 手改出来的"两个都是 true"：取第一个 —— 这和 groups() 那套归一化（留第一个）
        // 看到的是同一个。
        QList<InstanceGroupStore::Group> twoPinned;
        twoPinned.append(group("g1", false));
        twoPinned.append(group("g2", true));
        twoPinned.append(group("g3", true));
        check(InstanceGroupStore::pinnedGroupIdOf(twoPinned) == QStringLiteral("g2"),
              "Q15b 多过一个置顶组时取**第一个**（和读侧归一化同一条规矩）",
              InstanceGroupStore::pinnedGroupIdOf(twoPinned));
        // 老文件那条退回路：一个都没勾，但那个叫「置顶」的默认组还在清单里。
        QList<InstanceGroupStore::Group> legacy;
        legacy.append(group("g1", false));
        InstanceGroupStore::Group fallback = group("x", false);
        fallback.id = InstanceGroupStore::defaultGroupId(InstanceGroupStore::DefaultKind::Pinned);
        legacy.append(fallback);
        check(InstanceGroupStore::pinnedGroupIdOf(legacy) ==
                  InstanceGroupStore::defaultGroupId(InstanceGroupStore::DefaultKind::Pinned),
              "Q15b 一个都没勾 ⇒ 退回「置顶」那个默认组（老用户的迁移路）");
        check(InstanceGroupStore::pinnedGroupIdOf(QList<InstanceGroupStore::Group>() <<
                                                  group("g1", false))
                  .isEmpty(),
              "Q15b 连它都不在 ⇒ 空串（第三条出口）");
        // 读侧那一头就是它：一份文件读出来的组清单，两条路必须一样。
        writeRaw(QByteArrayLiteral(
            "{\"version\":1,\"groups\":[{\"id\":\"g1\",\"name\":\"甲\"},"
            "{\"id\":\"g2\",\"name\":\"乙\",\"pinned\":true}],\"members\":{}}"));
        InstanceGroupStore store;
        check(InstanceGroupStore::pinnedGroupIdOf(store.groups()) == store.pinnedGroupId(),
              "Q15b ★ pinnedGroupId() 就是 pinnedGroupIdOf(groups()) —— 两条路一个答案");
    }

    // ---------- Q12 沙盒收拾干净 ----------
    QDir().remove(groupFile);
    check(!QFile::exists(groupFile), "Q12 Q 段造出来的 wtfml.folders 删掉了");
    const QStringList left = QDir(versionsRoot).entryList(
        QStringList() << QStringLiteral("Q*"), QDir::Dirs | QDir::NoDotAndDotDot);
    check(left.isEmpty(), "Q12 Q 段造出来的目录一个都没剩下", left.join(QLatin1Char('|')));

    return 0;
}

// 判据在 2026-09-21 放松过：以前要求 <id>/<id>.jar（目录名和 jar 名必须一致），
// 现在只要求"认得出哪个是客户端 jar"（<id>.jar 优先，否则顶层恰好一个 jar 就是它）。
//
// NOTE: J1 那几条**是有意翻转的**，不是"顺手改坏又被改回来"。旧断言写着"判据没有放松"，
//       而它当初存在的唯一目的就是钉住那个行为。翻转的理由：用户自己在资源管理器里改了
//       目录名、没改里面 jar 名的实例，旧判据下会从列表里**静默消失**（真机上 388 MB 和
//       851 MB 的整合包各一个），本轮要消灭的正是这种静默。
static int runInstalledScanTests(const QString &sandbox) {
    section("J. 已安装版本扫描（认不出的要说）");

    const QString versionsRoot = sandbox + "/versions";
    // 目录名和 jar 名不一致（用户改过目录名）—— 现在要能认出来。
    const QString renamedDir = QStringLiteral("名字对不上");
    const QString renamedJar = QStringLiteral("旧名字.jar");
    // 目录名和 jar 名不一致，而且连 json 也是老名字 —— 真机上被外部改名的实例就长这样。
    const QString renamedJson = QStringLiteral("旧名字.json");
    // 有 jar 没有 json。json 缺席**不该**否决实例（半个版本、下载残骸的判据是 jar）。
    const QString noJsonDir = QStringLiteral("只有jar没json");
    const QString noJsonJar = QStringLiteral("随便起的名字.jar");
    // 顶层两个 jar 又认不出哪个是客户端 —— 这一类继续不认，且必须报出来。
    const QString twoJarsDir = QStringLiteral("两个jar");
    const QString twoJarsOne = QStringLiteral("aaa.jar");
    const QString twoJarsTwo = QStringLiteral("bbb.jar");
    const QString emptyDir = QStringLiteral("纯空目录");
    const QString strayZip = QStringLiteral("散落的整合包.zip");
    const QString goodDir = QStringLiteral("名字对得上");

    const auto writeFile = [](const QString &path) {
        QFile file(path);
        if (file.open(QIODevice::WriteOnly)) {
            file.write("dummy");
        }
    };

    QDir().mkpath(versionsRoot + "/" + renamedDir);
    writeFile(versionsRoot + "/" + renamedDir + "/" + renamedJar);
    writeFile(versionsRoot + "/" + renamedDir + "/" + renamedJson);

    QDir().mkpath(versionsRoot + "/" + noJsonDir);
    writeFile(versionsRoot + "/" + noJsonDir + "/" + noJsonJar);

    QDir().mkpath(versionsRoot + "/" + twoJarsDir);
    writeFile(versionsRoot + "/" + twoJarsDir + "/" + twoJarsOne);
    writeFile(versionsRoot + "/" + twoJarsDir + "/" + twoJarsTwo);

    QDir().mkpath(versionsRoot + "/" + emptyDir);
    writeFile(versionsRoot + "/" + strayZip);

    QDir().mkpath(versionsRoot + "/" + goodDir);
    writeFile(versionsRoot + "/" + goodDir + "/" + goodDir + ".jar");

    VersionManager vm;

    // warnings 传 nullptr 时必须与加这个参数之前**完全一样**：不崩、不多事。
    const QStringList silent = vm.installedVersions();

    check(silent.contains(renamedDir), "J1 名字对不上的目录**进**列表（判据已放松）",
          renamedDir);
    check(silent.contains(noJsonDir), "J1 有 jar 没有 json 的目录也进列表（json 缺席不否决）",
          noJsonDir);
    check(silent.contains(goodDir), "J1 名字对得上的目录照常进列表", goodDir);
    check(!silent.contains(twoJarsDir), "J1 顶层两个 jar 又认不出客户端的目录不进列表",
          twoJarsDir);

    QStringList warnings;
    const QStringList reported = vm.installedVersions(&warnings);
    check(reported == silent, "J1 传不传 warnings，返回的列表逐项一致");
    check(!reported.contains(emptyDir) && !reported.contains(strayZip),
          "J2 纯空目录和散落的 zip 都不算版本");

    // 上报条数还是 1，但**来源全变了**：以前是 renamedDir（名字对不上），现在是 twoJarsDir
    // （两个 jar 认不出）。数字不变纯属巧合，别以为这条没动过。
    check(warnings.size() == 1, "J1 恰好上报一条（认得出的、空目录、zip 都不该报）",
          QString::number(warnings.size()));
    if (warnings.size() == 1) {
        const QString w = warnings.first();
        check(w.contains(twoJarsDir) && w.contains(twoJarsOne) && w.contains(twoJarsTwo),
              "J1 告警里点了目录名和两个 jar 的名字", w);
    }
    const QString joined = warnings.join(QStringLiteral("\n"));
    check(!joined.contains(emptyDir), "J2 纯空目录不产生告警");
    check(!joined.contains(strayZip), "J2 散落在 versions/ 下的 zip 不产生告警");
    check(!joined.contains(goodDir), "J1 名字对得上的目录不产生告警");
    // 判据放松之后这两类都认得出，所以都不该出现在告警里 —— 这是放松的收益，别又报回来。
    check(!joined.contains(renamedDir), "J1 名字对不上的目录不再产生告警（它已经认得出了）");
    check(!joined.contains(noJsonDir), "J1 缺 json 的目录不产生告警");

    // 清理：留着会让沙盒一直长下去，尤其 twoJarsDir 会污染下一次运行
    // （那时它会变成"预先存在的"一条告警）。
    for (const QString &dir : {renamedDir, noJsonDir, twoJarsDir, emptyDir, goodDir}) {
        QDir(versionsRoot + "/" + dir).removeRecursively();
    }
    QFile::remove(versionsRoot + "/" + strayZip);

    QStringList afterCleanup;
    vm.installedVersions(&afterCleanup);
    check(afterCleanup.isEmpty(), "J3 清理后不再有任何告警（下一次运行不会被污染）",
          QString::number(afterCleanup.size()));

    return 0;
}

// 内存建议值：纯函数真值表 + 自动/手动档的落盘行为。
// 真值表是**手算出来的**（不是跑一遍记下输出），所以它能挡住"改了公式没人发现"。
static int runMemorySuggestionTests(const QString &sandbox) {
    Q_UNUSED(sandbox);
    section("L. 内存建议值（自动档按系统内存算）");

    // ---- L1: Xmx 真值表 ----
    // 规则：min(总/4, 可用/2) → 夹 [1024, 8192] → 再套"物理内存一半"的硬顶 →
    //       向下取整到 256，但不小于 256。
    struct XmxCase {
        qint64 total;
        qint64 available;
        int expect;
        const char *why;
    };
    const XmxCase xmxCases[] = {
        {0, 0, 4096, "读不到系统内存 → 内置默认值（不拿可用内存硬凑）"},
        {16384, 12288, 4096, "16G 空闲 → 16G/4"},
        {16384, 4096, 2048, "16G 但只剩 4G 可用 → 改成按可用算"},
        {32768, 24576, 8192, "32G → 32G/4 = 8G，正好到上限"},
        {65536, 49152, 8192, "64G → 被上限 8192 压住（不是 16G）"},
        {8192, 6144, 2048, "8G → 2G"},
        {4096, 3000, 1024, "4G → 1G，正好到下限"},
        {2048, 1500, 1024, "2G → 算出 512 被下限抬到 1024，又受 1G 硬顶"},
        {1024, 800, 512, "1G → 硬顶 512 压过下限（按 1024 硬凑会让 JVM 连堆都开不起来）"},
        {2048, 0, 1024, "可用内存读不到 → 只按总量算"},
        {65536, 2048, 1024, "可用内存极低 → 只剩 1024 可给"},
        {10000, 8000, 2304, "非 256 整数倍 → 向下取整（框里不出现 2500 这种数）"},
        {512, 400, 256, "极小机器 → 硬顶 256，但不再往下（setXmx 的下限）"},
    };
    for (const XmxCase &c : xmxCases) {
        const int got = GlobalJavaSettings::suggestXmxMb(c.total, c.available);
        check(got == c.expect,
              QStringLiteral("L1 suggestXmxMb(%1, %2) = %3")
                  .arg(c.total)
                  .arg(c.available)
                  .arg(c.expect),
              got == c.expect ? QString::fromUtf8(c.why)
                              : QStringLiteral("实际 %1（%2）").arg(got).arg(QString::fromUtf8(c.why)));
    }
    // 越低配的机器越不该给出"超过一半物理内存"的值（这一条是上面整张表的共同不变量）
    for (const XmxCase &c : xmxCases) {
        if (c.total <= 0) {
            continue;
        }
        const int got = GlobalJavaSettings::suggestXmxMb(c.total, c.available);
        check(got <= c.total / 2 || got == 256,
              QStringLiteral("L1 (%1, %2) 不会要超过一半物理内存").arg(c.total).arg(c.available),
              QString::number(got));
    }
    // 一律是 256 的整数倍：和界面两个框的步长一致
    for (const XmxCase &c : xmxCases) {
        const int got = GlobalJavaSettings::suggestXmxMb(c.total, c.available);
        check(got % 256 == 0, QStringLiteral("L1 (%1, %2) 是 256 的整数倍").arg(c.total).arg(c.available),
              QString::number(got));
    }

    // ---- L1b: 「这个实例装了多少模组」那一档（见 FEATURES.md 待办"自动档不认整合包规模"）----
    // 规则加在**第 1 步**上：total/4 + 每 64 模组 512 MB（最多 +4096），之后照旧走
    // min(可用/2) → 夹 [1024, 8192] → min(总量/2) → 向下取整 256。数字同样是手算的。
    struct ModCase {
        qint64 total;
        qint64 available;
        int mods;
        int expect;
        const char *why;
    };
    const ModCase modCases[] = {
        {16384, 12288, 0, 4096, "一个模组都没有 → 和加这一档之前逐字节一样"},
        {16384, 12288, 63, 4096, "不满一档（64）不加"},
        {16384, 12288, 64, 4608, "一档 → 4096 + 512"},
        {16384, 12288, 200, 5632, "三档 → 4096 + 3*512（「200 模组」正是待办里那个例子）"},
        {16384, 12288, 1000, 6144, "加成封顶 +4096 → 8192，再被「可用/2」压回 6144"},
        {32768, 32768, 1000, 8192, "机器够大时顶到自动档的上限 8192（加成封顶 +4096 正是它）"},
        {32768, 6144, 200, 3072, "机器只有 6G 可用 → 可用/2 把加成整档吃掉（机器现实说了算）"},
        {4096, 3000, 128, 1280, "小机器：加成照样透出来一点（1024 → 1280），但超不过总量的一半"},
        {0, 0, 256, 4096, "读不到系统内存 → 内置默认值，加成不加"},
        {16384, 12288, -5, 4096, "负数当「没有模组」（不拿它去算减法）"},
    };
    for (const ModCase &c : modCases) {
        const int got = GlobalJavaSettings::suggestXmxMb(c.total, c.available, c.mods);
        check(got == c.expect,
              QStringLiteral("L1b suggestXmxMb(%1, %2, mods=%3) = %4")
                  .arg(c.total)
                  .arg(c.available)
                  .arg(c.mods)
                  .arg(c.expect),
              got == c.expect ? QString::fromUtf8(c.why)
                              : QStringLiteral("实际 %1（%2）").arg(got).arg(QString::fromUtf8(c.why)));
    }
    // 同两条不变量，对有模组的那一档照样成立
    for (const ModCase &c : modCases) {
        const int got = GlobalJavaSettings::suggestXmxMb(c.total, c.available, c.mods);
        check(got % 256 == 0,
              QStringLiteral("L1b (%1, %2, mods=%3) 是 256 的整数倍").arg(c.total).arg(c.available).arg(c.mods),
              QString::number(got));
        if (c.total > 0) {
            check(got <= c.total / 2 || got == 256,
                  QStringLiteral("L1b (%1, %2, mods=%3) 不会要超过一半物理内存")
                      .arg(c.total)
                      .arg(c.available)
                      .arg(c.mods),
                  QString::number(got));
        }
    }
    // 同一个实例、同一个机器，模组多的**不会**拿到比模组少的小（单调不降）
    for (int mods = 0; mods <= 512; mods += 16) {
        const int few = GlobalJavaSettings::suggestXmxMb(16384, 12288, mods);
        const int many = GlobalJavaSettings::suggestXmxMb(16384, 12288, mods + 64);
        check(many >= few,
              QStringLiteral("L1b mods=%1 → %2，mods=%3 → %4（多的不该更小）")
                  .arg(mods)
                  .arg(few)
                  .arg(mods + 64)
                  .arg(many),
              QStringLiteral("%1 / %2").arg(few).arg(many));
    }

    // ---- L2: Xms 真值表 ----
    struct XmsCase {
        int xmx;
        int expect;
    };
    const XmsCase xmsCases[] = {
        {1024, 512}, {2048, 512}, {4096, 1024}, {8192, 2048},
        {256, 256},   // Xmx 比下限还小时跟着退到 Xmx（Xms > Xmx 会让 JVM 拒绝启动）
        {512, 512},   // 同上：下限不超过 Xmx 本身
    };
    for (const XmsCase &c : xmsCases) {
        const int got = GlobalJavaSettings::suggestXmsMb(c.xmx);
        check(got == c.expect, QStringLiteral("L2 suggestXmsMb(%1) = %2").arg(c.xmx).arg(c.expect),
              QString::number(got));
    }
    // 不变量：Xms 永远不大于 Xmx（这条错了就是 JVM 直接起不来）。
    // 逐档扫一遍，只在出错时点出是哪一档，避免刷屏。
    {
        int badXmx = 0;
        for (int xmx = 256; xmx <= 16384; xmx += 256) {
            if (GlobalJavaSettings::suggestXmsMb(xmx) > xmx) {
                badXmx = xmx;
                break;
            }
        }
        check(badXmx == 0, "L2 Xms 永远 <= Xmx（256 到 16384 逐档扫过）",
              badXmx == 0 ? QString() : QStringLiteral("xmx=%1").arg(badXmx));
    }

    // ---- L3: 自动档的重算与落盘 ----
    // 真值来源是 QSettings，所以照 I5 那套先把 QSettings 搬进沙盒（**必须在第一个
    // QSettings 对象出现之前**），跑完再搬回去。这一节的键在真机器上写一遍没有意义，
    // 还会给用户留下垃圾。
    {
        const QString settingsDir = sandbox + "/memory-settings";
        QDir(settingsDir).removeRecursively();
        QDir().mkpath(settingsDir);

        QSettings::setDefaultFormat(QSettings::IniFormat);
        QSettings::setPath(QSettings::IniFormat, QSettings::UserScope, settingsDir);

        section("L3 自动档：重算、落盘、手动档不许被动");

        // 老配置（没有 Java/MemoryAuto 这个键）：两个值都是内置默认 → 当自动档。
        // 这就是"升级上来的老用户不会因为多了这一项而换一套内存"。
        {
            QSettings raw;
            raw.clear();
            raw.setValue(QStringLiteral("Java/Xmx"), 4096);
            raw.setValue(QStringLiteral("Java/Xms"), 1024);
            raw.sync();
        }
        {
            GlobalJavaSettings old;
            check(old.autoMemory(), "L3 老配置留着内置默认值 → 当自动档（升级不改老行为）");
        }

        // 老配置但用户自己调过 → 当手动档，绝不静默改掉他定好的内存
        {
            QSettings raw;
            raw.clear();
            raw.setValue(QStringLiteral("Java/Xmx"), 8192);
            raw.setValue(QStringLiteral("Java/Xms"), 2048);
            raw.sync();
            GlobalJavaSettings custom;
            check(!custom.autoMemory(), "L3 老配置里是用户自己调过的值 → 当手动档");
            check(custom.xmx() == 8192 && custom.xms() == 2048, "L3 手动档的值原样读回",
                  QStringLiteral("%1/%2").arg(custom.xmx()).arg(custom.xms()));
            // 手动档下重算**一个数字都不许动**：这是自动档最容易踩的坑
            const SystemMemory::Usage usage = custom.refreshSuggestedMemory();
            check(custom.xmx() == 8192 && custom.xms() == 2048,
                  "L3 手动档下重算不动用户的数字",
                  QStringLiteral("%1/%2").arg(custom.xmx()).arg(custom.xms()));
            check(usage.totalMb > 0, "L3 手动档下也照样读了系统内存（界面拿它写说明）",
                  QString::number(usage.totalMb));
        }

        // 自动档：两个值都该是"这台机器现在算出来的"，且与纯函数逐位一致
        // （界面显示的就是这个函数算的那个数）。
        {
            QSettings raw;
            raw.clear();
            raw.setValue(QStringLiteral("Java/MemoryAuto"), true);
            raw.sync();
            GlobalJavaSettings autoJava;
            check(autoJava.autoMemory(), "L3 盘上写着自动 → 自动档");

            const SystemMemory::Usage usage = autoJava.refreshSuggestedMemory();
            check(usage.totalMb > 0, "L3 读到系统物理内存总量", QString::number(usage.totalMb));
            check(usage.availableMb > 0, "L3 读到当前可用内存", QString::number(usage.availableMb));
            check(usage.availableMb <= usage.totalMb, "L3 可用内存不超过总量",
                  QStringLiteral("%1/%2").arg(usage.availableMb).arg(usage.totalMb));
            check(autoJava.xmx() == GlobalJavaSettings::suggestXmxMb(usage.totalMb, usage.availableMb),
                  "L3 自动档的 Xmx 就是纯函数算出来的那个值", QString::number(autoJava.xmx()));
            check(autoJava.xms() == GlobalJavaSettings::suggestXmsMb(autoJava.xmx()),
                  "L3 自动档的 Xms 是 Xmx 的四分之一档", QString::number(autoJava.xms()));
            check(autoJava.xmx() >= 1024 && autoJava.xmx() <= 8192, "L3 自动档的值在体面范围内",
                  QString::number(autoJava.xmx()));
            check(autoJava.xmx() % 256 == 0 && autoJava.xms() % 256 == 0,
                  "L3 自动档的两个值都是 256 的整数倍",
                  QStringLiteral("%1/%2").arg(autoJava.xmx()).arg(autoJava.xms()));

            // 用户改过的值一个数字都不许动（手动档）。
            // 10000 是**故意选的**：建议值上限是 8192，所以"它被换掉了"这件事永远能测出来，
            // 不会在这台机器上恰好建议 3072 之类的值时假通过。
            autoJava.setXmx(10000);
            autoJava.setXms(2500);
            autoJava.setAutoMemory(false);  // 这一句内部就落盘了
            autoJava.refreshSuggestedMemory();
            check(autoJava.xmx() == 10000 && autoJava.xms() == 2500,
                  "L3 切手动档后重算仍然不动用户的数字",
                  QStringLiteral("%1/%2").arg(autoJava.xmx()).arg(autoJava.xms()));

            check(!QSettings().value(QStringLiteral("Java/MemoryAuto"), QVariant()).isNull(),
                  "L3 Java/MemoryAuto 这个键真的写进盘了");

            // 换个实例读：验的是真落了盘，不是留在成员变量里
            GlobalJavaSettings reopened;
            check(!reopened.autoMemory(), "L3 手动档跨实例读得回来");
            check(reopened.xmx() == 10000 && reopened.xms() == 2500, "L3 手动档的值也读得回来",
                  QStringLiteral("%1/%2").arg(reopened.xmx()).arg(reopened.xms()));

            // 切回自动：refreshSuggestedMemory() 立刻按当前内存把值重算一遍，
            // 手动档留下的 10000 必须被覆盖掉（它不是建议值域里的数）
            reopened.setAutoMemory(true);
            const SystemMemory::Usage back = reopened.refreshSuggestedMemory();
            check(reopened.xmx() == GlobalJavaSettings::suggestXmxMb(back.totalMb, back.availableMb),
                  "L3 切回自动档会按当前内存重算", QString::number(reopened.xmx()));
            check(reopened.xmx() != 10000, "L3 重算覆盖了手动档留下的 10000",
                  QString::number(reopened.xmx()));
        }

        QSettings::setDefaultFormat(QSettings::NativeFormat);
        QDir(settingsDir).removeRecursively();
    }

    return 0;
}

// ---------------------------------------------------------------------------
// M. release 文件解析（GlobalJavaSettings::majorVersionFromReleaseFile）
//
// 这个纯函数决定"扫本机 Java 时能不能不启动 JVM"，而它解析错了的后果是**静默认不出**
// 已经装好的 Java（然后白白去下一个几百 MB 的运行时）。所以这里钉两件事：
//   1. 各种写法的真值表 —— 含只写 JAVA_VERSION_DATE 这种假阳性陷阱；
//   2. 真机对账 —— 每个扫出来的运行时，"release 文件里读到的版本"必须等于"真的跑一次
//      java -version 问出来的版本"。这一条才是"快路没有改变结果"的凭据，
//      前一条只证明解析器本身对。
// ---------------------------------------------------------------------------
static void runEffectiveJavaSettingsTests(const QString &sandbox) {
    section("R. 每实例设置的合成（resolveJavaSettings / 覆盖的读写）");

    // 全局那一层的样板值。五项各不相同、都不是边界值 —— 这样"某一项被改错了"
    // 在下面每一条断言里都看得出来。
    const EffectiveJavaSettings global = [] {
        EffectiveJavaSettings g;
        g.javaPath = QStringLiteral("C:/java/global/bin/java.exe");
        g.xmx = 4096;
        g.xms = 1024;
        g.autoMemory = false;
        g.extraJvmArgs = QStringLiteral("-XX:+UseG1GC");
        return g;
    }();

    /// 两份额值的差异（字段名列表）。用来钉"只动了这一项"。
    const auto diff = [](const EffectiveJavaSettings &a, const EffectiveJavaSettings &b) {
        QStringList fields;
        if (a.javaPath != b.javaPath) {
            fields << QStringLiteral("javaPath");
        }
        if (a.xmx != b.xmx) {
            fields << QStringLiteral("xmx");
        }
        if (a.xms != b.xms) {
            fields << QStringLiteral("xms");
        }
        if (a.autoMemory != b.autoMemory) {
            fields << QStringLiteral("autoMemory");
        }
        if (a.extraJvmArgs != b.extraJvmArgs) {
            fields << QStringLiteral("extraJvmArgs");
        }
        return fields;
    };
    const auto onlyChanged = [&](const JavaSettingsOverride &ov, const QString &field) {
        return diff(resolveJavaSettings(global, ov), global) == QStringList{field};
    };

    // ---- R1 一项都不覆盖：有效值就是全局那一份 ----
    {
        const EffectiveJavaSettings got = resolveJavaSettings(global, JavaSettingsOverride());
        check(diff(global, got).isEmpty(), "R1 没有任何覆盖时有效值 == 全局逐字段",
              diff(global, got).join(QStringLiteral(" | ")));
    }

    // ---- R2 逐项覆盖：只动被覆盖的那一项 ----
    {
        JavaSettingsOverride ov;
        ov.javaPath = QStringLiteral("D:/jdk8/bin/java.exe");
        check(onlyChanged(ov, QStringLiteral("javaPath")),
              "R2 只覆盖 javaPath 时其余四项一个字不动");
    }
    {
        JavaSettingsOverride ov;
        ov.xmx = 8192;
        check(onlyChanged(ov, QStringLiteral("xmx")), "R2 只覆盖 Xmx（8192，在范围内）");
    }
    {
        JavaSettingsOverride ov;
        ov.xms = 512;
        check(onlyChanged(ov, QStringLiteral("xms")), "R2 只覆盖 Xms");
    }
    {
        JavaSettingsOverride ov;
        ov.autoMemory = true;
        check(onlyChanged(ov, QStringLiteral("autoMemory")), "R2 只覆盖「内存分配」这一档");
    }
    {
        JavaSettingsOverride ov;
        ov.extraJvmArgs = QString();
        const EffectiveJavaSettings got = resolveJavaSettings(global, ov);
        check(onlyChanged(ov, QStringLiteral("extraJvmArgs")),
              "R2 只覆盖额外 JVM 参数时其余四项不动");
        check(got.extraJvmArgs.isEmpty(),
              "R2 空串是**真覆盖**：有效值是空的，不是全局那份 -XX:+UseG1GC",
              got.extraJvmArgs);
    }

    // ---- R3 钳位：覆盖层要把全局那条规则重做一遍 ----
    // 用户只覆盖一项、另一项还是全局的，两个数凑在一起就可能越界。
    {
        const auto resolved = [&](const JavaSettingsOverride &ov) {
            return resolveJavaSettings(global, ov);
        };

        JavaSettingsOverride ov;
        ov.xmx = 128;
        check(resolved(ov).xmx == 256, "R3 覆盖的 Xmx 低于 256 → 抬到 256",
              QString::number(resolved(ov).xmx));

        ov = JavaSettingsOverride();
        ov.xms = 64;
        check(resolved(ov).xms == 128, "R3 覆盖的 Xms 低于 128 → 抬到 128",
              QString::number(resolved(ov).xms));

        // 只覆盖 Xms、而它比有效 Xmx 大：JVM 会拒绝启动（Initial heap size ... larger
        // than the maximum heap size），所以必须压到 Xmx 上。
        ov = JavaSettingsOverride();
        ov.xms = 8192;
        check(resolved(ov).xms == 4096 && resolved(ov).xmx == 4096,
              "R3 只覆盖 Xms 且大于有效 Xmx → 压到 Xmx（Xmx 本身不动）",
              QStringLiteral("%1 / %2").arg(resolved(ov).xms).arg(resolved(ov).xmx));

        // 反方向：只覆盖 Xmx、比全局那个 Xms 还小 —— 全局的 Xms 要跟着退下来
        ov = JavaSettingsOverride();
        ov.xmx = 512;
        check(resolved(ov).xms == 512,
              "R3 覆盖的 Xmx 比全局 Xms 还小时，Xms 跟着退到 Xmx（不是留着 1024）",
              QString::number(resolved(ov).xms));

        // 两个都覆盖、方向相反：以 Xmx 为准
        ov = JavaSettingsOverride();
        ov.xmx = 512;
        ov.xms = 2048;
        check(resolved(ov).xms == 512 && resolved(ov).xmx == 512,
              "R3 两个都覆盖且 Xms > Xmx → Xms 被压到有效 Xmx",
              QStringLiteral("%1 / %2").arg(resolved(ov).xms).arg(resolved(ov).xmx));

        // 正好压在下限上：不该被抬走
        ov = JavaSettingsOverride();
        ov.xmx = 256;
        ov.xms = 128;
        check(resolved(ov).xmx == 256 && resolved(ov).xms == 128,
              "R3 正好在下限上（256 / 128）不动它");
    }

    // ---- R4 从 meta 读覆盖：类型不对当没写，null 当没有 ----
    {
        check(javaOverrideFromJson(QJsonObject()).isEmpty(), "R4 空对象 → 一项覆盖都没有");
        check(javaOverrideFromJson(QJsonObject{{QStringLiteral("javaPath"), QJsonValue::Null}})
                  .isEmpty(),
              "R4 值是 null → 当没有（手写或删键留下的形态，不是空路径覆盖）");
        check(javaOverrideFromJson(QJsonObject{{QStringLiteral("xmx"), QStringLiteral("8192")}})
                  .isEmpty(),
              "R4 xmx 写成了字符串 → 当没有（**不是**当成 0）");
        check(javaOverrideFromJson(QJsonObject{{QStringLiteral("autoMemory"), 1}}).isEmpty(),
              "R4 autoMemory 写成数字 → 当没有");
        // 非整数的 double：**自己截断**（2026-09-25 修）。这一条钉的是一个实测过的 Qt 行为：
        // QJsonValue::toInt() 遇到 4096.5 返回的是**默认值 0**（它不截断，探针见
        // tmp/probe_toint），而那个 0 一路走到夹取那一段就变成"用户设了 4096 MB、起步内存
        // 256 MB"这种**没人报错**的错值。所以截断是我们自己做的，而且下限以下/上限以上
        // 一律当"没写"（下游认得的意思只有这一个）。
        const JavaSettingsOverride truncated = javaOverrideFromJson(QJsonObject{
            {QStringLiteral("xmx"), 4096.5}, {QStringLiteral("xms"), 1024.9}});
        check(truncated.xmx.has_value() && *truncated.xmx == 4096 &&
                  truncated.xms.has_value() && *truncated.xms == 1024,
              "R4 4096.5 → 4096（截断，不是丢掉、更不是变成 0）",
              QStringLiteral("%1 / %2")
                  .arg(truncated.xmx.has_value() ? *truncated.xmx : -1)
                  .arg(truncated.xms.has_value() ? *truncated.xms : -1));
        check(javaOverrideFromJson(QJsonObject{{QStringLiteral("xmx"), 1e30}}).isEmpty() &&
                  javaOverrideFromJson(QJsonObject{{QStringLiteral("xmx"), -1e30}}).isEmpty(),
              "R4 越界的 double（1e30 / -1e30）→ 当没写（强转是未定义行为）");

        // 空串在这一层是**有值**的：这一层照文件里写的读，"空 = 跟随全局"那条归一是
        // 对话框那一层的事（见 InstanceSettingsDialog::override()）。
        const JavaSettingsOverride emptyPath =
            javaOverrideFromJson(QJsonObject{{QStringLiteral("javaPath"), QString()}});
        check(emptyPath.javaPath.has_value() && emptyPath.javaPath->isEmpty(),
              "R4 空串是有值 —— 这一层不做归一，照读");
        check(!emptyPath.isEmpty(), "R4 有值时 isEmpty() 为假");

        const JavaSettingsOverride numbers = javaOverrideFromJson(QJsonObject{
            {QStringLiteral("xmx"), 8192},
            {QStringLiteral("xms"), 2048.0},
            {QStringLiteral("autoMemory"), true}});
        check(numbers.xmx.has_value() && *numbers.xmx == 8192 && numbers.xms.has_value() &&
                  *numbers.xms == 2048 && numbers.autoMemory.has_value() && *numbers.autoMemory,
              "R4 正常的数字 / 布尔读得出来");
    }

    // ---- R5 写回 meta 的那一份 JSON ----
    {
        const QJsonObject none = javaOverrideToJson(JavaSettingsOverride());
        QStringList nullKeys;
        for (const QString &key : none.keys()) {
            if (none.value(key).isNull()) {
                nullKeys << key;
            }
        }
        nullKeys.sort();
        check(nullKeys == QStringList({QStringLiteral("autoMemory"), QStringLiteral("extraJvmArgs"),
                                       QStringLiteral("javaPath"), QStringLiteral("xms"),
                                       QStringLiteral("xmx")}),
              "R5 一项覆盖都没有时五个键都在、值都是 null（= 让写侧把键删掉）",
              nullKeys.join(QStringLiteral(",")));

        JavaSettingsOverride ov;
        ov.xmx = 8192;
        ov.extraJvmArgs = QString();
        const QJsonObject json = javaOverrideToJson(ov);
        check(json.value(QStringLiteral("xmx")).toInt() == 8192 &&
                  json.value(QStringLiteral("javaPath")).isNull(),
              "R5 有值的写值、没值的写 null");
        check(json.value(QStringLiteral("extraJvmArgs")).isString() &&
                  json.value(QStringLiteral("extraJvmArgs")).toString().isEmpty(),
              "R5 空串写成**空字符串**而不是 null —— 它是一项真的覆盖");

        const JavaSettingsOverride back = javaOverrideFromJson(json);
        check(back.xmx.has_value() && *back.xmx == 8192 && back.extraJvmArgs.has_value() &&
                  back.extraJvmArgs->isEmpty() && !back.xms.has_value(),
              "R5 写出去再读回来是同一份覆盖");
    }

    // ---- R6 真盘一趟：覆盖写进 wtfml.meta，再读回来 ----
    {
        const QString versionId = QStringLiteral("实例设置版本");
        const QString versionDir = AppPaths::versionDir(versionId);
        QDir(versionDir).removeRecursively();
        QDir().mkpath(versionDir);
        VersionManager vm;

        JavaSettingsOverride ov;
        ov.xmx = 8192;
        ov.autoMemory = false;
        ov.extraJvmArgs = QStringLiteral("-XX:+PerfDisableSharedMem");
        QString error;
        check(vm.updateVersionMeta(versionId, javaOverrideToJson(ov), &error),
              "R6 覆盖写进 wtfml.meta", error);

        const JavaSettingsOverride back = javaOverrideFromJson(vm.versionMeta(versionId));
        check(back.xmx.has_value() && *back.xmx == 8192 && back.autoMemory.has_value() &&
                  !*back.autoMemory && back.extraJvmArgs.has_value(),
              "R6 读回来是写进去的那一份");
        {
            const EffectiveJavaSettings got = resolveJavaSettings(global, back);
            check(got.xmx == 8192 && got.xms == 1024 && got.javaPath == global.javaPath &&
                      got.extraJvmArgs == QStringLiteral("-XX:+PerfDisableSharedMem"),
                  "R6 合成之后：覆盖的两项听实例的，其余三项还是全局的",
                  QStringLiteral("%1 / %2 / %3").arg(got.xmx).arg(got.xms).arg(got.extraJvmArgs));
        }

        // 追加参数（jvmArgs）和覆盖是同一个文件里**两个不同的键**，各管各的：写覆盖
        // 不能把它抹掉。（这两件事在真机上会同时出现在一个 wtfml.meta 里。）
        check(vm.updateVersionMeta(
                  versionId,
                  {{VersionManager::jvmArgsField(), QJsonArray{QStringLiteral("-Xss1M")}}}, &error),
              "R6 往同一个文件里写追加参数", error);
        check(vm.updateVersionMeta(versionId, javaOverrideToJson(JavaSettingsOverride()), &error),
              "R6 把它全部切回「跟随全局」", error);
        check(vm.versionJvmArgs(versionId) == QStringList{QStringLiteral("-Xss1M")},
              "R6 写覆盖时没有把追加参数抹掉",
              vm.versionJvmArgs(versionId).join(QStringLiteral(" | ")));
        {
            const QJsonObject raw = vm.versionMeta(versionId);
            check(!raw.contains(QStringLiteral("xmx")) &&
                      !raw.contains(QStringLiteral("extraJvmArgs")) &&
                      !raw.contains(QStringLiteral("autoMemory")),
                  "R6 「跟随全局」真的把键从文件里删了（不是留一个等于全局的值）",
                  QString::fromUtf8(QJsonDocument(raw).toJson(QJsonDocument::Compact)));
            check(javaOverrideFromJson(raw).isEmpty(), "R6 再读就是一项覆盖都没有");
        }

        QDir(versionDir).removeRecursively();
        check(!QDir(versionDir).exists(), "R6 沙盒里那个版本目录删干净了");
    }

    // ---- R7 「值 → 要写进 meta 的那批字段」整批（javaOverrideMetaFields） ----
    // 这是写侧真正交给 updateVersionMeta() 的东西：五项加追加参数一起。它以前长在
    // MainWindow::applyInstanceSettings() 里，而那里收的是对话框引用 —— 验证工程驱动
    // 不了它（自定义类型进不了 Q_ARG），于是"清空追加参数之后那个键还在不在"这种事
    // 没有任何断言盯着。搬成纯函数之后这里直接喂值、比对 JSON。
    {
        const QString jvmKey = VersionManager::jvmArgsField();

        // ① 全部「跟随全局」+ 没有追加参数：六个键都在，值全是 Null（= 让写侧删键）。
        {
            const QJsonObject fields =
                javaOverrideMetaFields(JavaSettingsOverride(), QStringList(), jvmKey);
            check(fields.size() == 6, "R7 六个键一个都不漏（五项 + 追加参数）",
                  QString::number(fields.size()));
            bool allNull = true;
            for (const QString &key : fields.keys()) {
                allNull = allNull && fields.value(key).isNull();
            }
            check(allNull, "R7 一项都没覆盖时六个键全是 Null（写侧照它删键）",
                  QString::fromUtf8(QJsonDocument(fields).toJson(QJsonDocument::Compact)));
        }

        // ② 有覆盖 + 有追加参数：覆盖写值，追加参数写数组（条数和顺序都要对）。
        {
            JavaSettingsOverride ov;
            ov.javaPath = QStringLiteral("D:/jdk8/java.exe");
            ov.xms = 512;
            const QJsonObject fields = javaOverrideMetaFields(
                ov, QStringList({QStringLiteral("-Xss1M"), QStringLiteral("-Dfoo=bar baz")}),
                jvmKey);
            check(fields.value(QStringLiteral("javaPath")).toString() ==
                          QStringLiteral("D:/jdk8/java.exe") &&
                      fields.value(QStringLiteral("xms")).toInt() == 512,
                  "R7 覆盖了的那两项写的是值");
            check(fields.value(QStringLiteral("xmx")).isNull(),
                  "R7 没覆盖的那几项还是 Null（不是顺手写一个等于全局的值）");
            const QJsonArray args = fields.value(jvmKey).toArray();
            check(args.size() == 2 && args.at(0).toString() == QStringLiteral("-Xss1M") &&
                      args.at(1).toString() == QStringLiteral("-Dfoo=bar baz"),
                  "R7 追加参数写成数组，含空格的那一条**没有被切开**",
                  QString::fromUtf8(QJsonDocument(args).toJson(QJsonDocument::Compact)));
        }

        // ③ 真盘一趟：清空追加参数之后那个键要**从文件里消失**（不是留一个空数组）。
        //    这条是 R7 存在的理由：留着一个空数组时读侧当空、界面上也看不出来，但手写
        //    这个文件的人会以为该往里填 —— 而"这个实例没有追加参数"就是键不存在。
        {
            const QString versionId = QStringLiteral("实例设置字段版本");
            const QString versionDir = AppPaths::versionDir(versionId);
            QDir(versionDir).removeRecursively();
            QDir().mkpath(versionDir);
            VersionManager vm;
            QString error;

            check(vm.updateVersionMeta(
                      versionId,
                      javaOverrideMetaFields(JavaSettingsOverride(),
                                             QStringList({QStringLiteral("-Xss1M")}), jvmKey),
                      &error),
                  "R7 先写一份带追加参数的", error);
            check(vm.versionJvmArgs(versionId) == QStringList{QStringLiteral("-Xss1M")},
                  "R7 读回来就是那一条");
            check(vm.updateVersionMeta(
                      versionId,
                      javaOverrideMetaFields(JavaSettingsOverride(), QStringList(), jvmKey),
                      &error),
                  "R7 再把追加参数清空重写一遍", error);
            const QJsonObject raw = vm.versionMeta(versionId);
            check(!raw.contains(jvmKey), "R7 那个键真的从文件里没了（不是留一个空数组）",
                  QString::fromUtf8(QJsonDocument(raw).toJson(QJsonDocument::Compact)));
            check(vm.versionJvmArgs(versionId).isEmpty(), "R7 读侧也当它没有");

            QDir(versionDir).removeRecursively();
        }
    }
}

// ---------------------------------------------------------------------------
// S. 实例 Java 版本不符时的提醒开关
//
// 这个功能有两处存储、各管一段：**全局总闸**（QSettings 的 Java/WarnVersionMismatch）
// 和**每个实例自己的记忆**（wtfml.meta 的 skipJavaVersionWarning）。这里钉这两处的
// 读写语义；"谁在什么时候问"归 mw_check 的 U 段，那个三岔口对话框本身归 ui_check 的 V 段。
//
// 为什么值得单开一段：两处的默认值都必须是"提醒" —— 那是加这个功能之前的行为
// （一律报错拦下，等于总是提醒）。默认值写反，老配置一升级就变成"悄悄放行一个版本
// 不对的 Java"，而静默选错 Java 正是这一层最怕的错。
// ---------------------------------------------------------------------------
static void runJavaWarnMismatchTests(const QString &sandbox) {
    section("S. 实例 Java 版本不符时的提醒开关（全局总闸 + 每实例记忆）");

    // ---- S1 全局总闸：默认提醒、改了立刻落盘 ----
    // 真值来源是 QSettings，照 L3 那套先把 QSettings 搬进沙盒（**必须在第一个
    // QSettings 对象出现之前**），跑完再搬回去。
    {
        const QString settingsDir = sandbox + "/warn-mismatch-settings";
        QDir(settingsDir).removeRecursively();
        QDir().mkpath(settingsDir);

        QSettings::setDefaultFormat(QSettings::IniFormat);
        QSettings::setPath(QSettings::IniFormat, QSettings::UserScope, settingsDir);

        // 盘上是个"加这个开关之前"的老配置：有别的 Java 键，就是没有这一个
        {
            QSettings raw;
            raw.clear();
            raw.setValue(QStringLiteral("Java/Path"), QStringLiteral("C:/java/bin/java.exe"));
            raw.sync();
        }
        {
            GlobalJavaSettings fresh;
            check(fresh.warnVersionMismatch(),
                  "S1 老配置（盘上没有这个键）默认是「提醒」—— 那正是加它之前的行为");
        }
        {
            GlobalJavaSettings s;
            s.setWarnVersionMismatch(false);
            // 换个对象读：验的是真落了盘，不是留在成员变量里
            GlobalJavaSettings reopened;
            check(!reopened.warnVersionMismatch(), "S1 关掉之后立刻落盘，另一个对象读回来是关的");
            check(!QSettings().value(QStringLiteral("Java/WarnVersionMismatch")).toBool(),
                  "S1 盘上那个键真的写成了 false（不是只改了内存）");
            reopened.setWarnVersionMismatch(true);
            GlobalJavaSettings back;
            check(back.warnVersionMismatch(), "S1 再打开一次也一样落盘");
        }

        QSettings::setDefaultFormat(QSettings::NativeFormat);
        QDir(settingsDir).removeRecursively();
    }

    // ---- S2 每实例记忆：wtfml.meta 里的 skipJavaVersionWarning ----
    // 「缺省 = 提醒」是这一节的全部要害：盘上没有这个键和写着 false 是**两种不同的
    // 局面**（一个是从来没表过态，一个是表过态说别问了），而读侧对两者都返回 false
    // 是刻意的 —— 它问的是"要不要提醒"。所以反向那条（改回提醒）必须**把键删掉**，
    // 不能让文件里留一个 false 占位：那会让"这个实例表过态"看起来永远成立。
    {
        const QString versionId = QStringLiteral("版本提醒开关版本");
        const QString versionDir = AppPaths::versionDir(versionId);
        QDir(versionDir).removeRecursively();
        QDir().mkpath(versionDir);
        VersionManager vm;

        check(VersionManager::skipJavaVersionWarningField() ==
                  QStringLiteral("skipJavaVersionWarning"),
              "S2 键名是约定的那一个（读侧写侧共用这个出处）",
              VersionManager::skipJavaVersionWarningField());
        check(javaPathMetaField() == QStringLiteral("javaPath"),
              "S2 javaPath 那个键名的出处也是约定的（写侧要拿它写回匹配的 Java）",
              javaPathMetaField());
        check(!vm.skipJavaVersionWarning(versionId),
              "S2 盘上还没有这个键 → 缺省是**提醒**（= 加这个功能之前的行为）");
        check(!vm.skipJavaVersionWarning(QStringLiteral("根本没有这个实例")),
              "S2 连 meta 文件都没有的实例也当提醒，不炸");

        QString error;
        check(vm.updateVersionMeta(
                  versionId,
                  {{VersionManager::jvmArgsField(), QJsonArray{QStringLiteral("-Xss1M")}}}, &error),
              "S2 先往同一份 meta 里放一份追加参数", error);
        check(vm.updateVersionMeta(
                  versionId,
                  {{VersionManager::skipJavaVersionWarningField(), QJsonValue(true)}}, &error),
              "S2 写「以后不再提醒这个实例」", error);
        check(vm.skipJavaVersionWarning(versionId), "S2 读回来是 true（真的落盘了）");
        check(vm.versionJvmArgs(versionId) == QStringList{QStringLiteral("-Xss1M")},
              "S2 合并写没有把同一份 meta 里的追加参数抹掉",
              vm.versionJvmArgs(versionId).join(QStringLiteral(" | ")));

        // 手写文件会干的事：类型写坏。宁可多问一句，也不要因为一个坏值从此静默不问。
        check(vm.updateVersionMeta(
                  versionId, {{VersionManager::skipJavaVersionWarningField(), QJsonValue(1)}},
                  &error),
              "S2 把那个键写坏成数字", error);
        check(!vm.skipJavaVersionWarning(versionId),
              "S2 类型不对 → 当提醒（在下面那条 qWarning 之外静默地退回缺省）");

        check(vm.updateVersionMeta(
                  versionId, {{VersionManager::skipJavaVersionWarningField(),
                              QJsonValue(QJsonValue::Null)}}, &error),
              "S2 改回提醒（写 Null = 让写侧删键）", error);
        check(!vm.skipJavaVersionWarning(versionId), "S2 读回来是 false（= 提醒）");
        check(!vm.versionMeta(versionId).contains(VersionManager::skipJavaVersionWarningField()),
              "S2 那个键真的从文件里没了，不是留一个 false 在那儿占位",
              QString::fromUtf8(
                  QJsonDocument(vm.versionMeta(versionId)).toJson(QJsonDocument::Compact)));
        check(vm.versionJvmArgs(versionId) == QStringList{QStringLiteral("-Xss1M")},
              "S2 删键那一次也没碰追加参数");

        QDir(versionDir).removeRecursively();
    }

    // ---- S3 allowMismatchedPath：那个口子只可能由用户的明确授权打开 ----
    // 用一个**压根不存在**的路径来证这件事：它在 javaMatchesMajor() 那里必然为假
    // （那一步会去冷启一个 JVM，起不来），如果这个参数判在那个函数**之后**，这里
    // 就一定返回 false。返回 true 说明它判在前面、一条探测都没做 —— 而除了
    // 「Java 版本不符」那个框的「仍然启动」，没有任何调用点会把它置真。
    {
        GlobalJavaSettings settings;
        EffectiveJavaSettings io;
        io.javaPath = QStringLiteral("C:/这个目录不存在/java.exe");
        QString error;
        check(!settings.ensureJavaForVersion(io, 17, QString(), /*allowAutoSelect=*/false, &error),
              "S3 前景：手动档 + 一个探不出主版本的路径 → 拒绝（现有的硬错误原样成立）");
        error.clear();
        check(settings.ensureJavaForVersion(io, 17, QString(), /*allowAutoSelect=*/false, &error,
                                            /*allowMismatchedPath=*/true),
              "S3 同一个路径，用户明确授权之后放行（口子在探测之前）", error);
        check(io.javaPath == QStringLiteral("C:/这个目录不存在/java.exe"),
              "S3 放行时不动那条路径 —— 用户要的就是它", io.javaPath);
        check(error.isEmpty(), "S3 放行那一次没有留下失败原因", error);
    }
}

static void runJavaReleaseParseTests() {
    section("M. release 文件解析（majorVersionFromReleaseFile）");

    const QList<QPair<QString, int>> cases = {
        {QStringLiteral("JAVA_VERSION=\"21.0.7\"\n"), 21},
        {QStringLiteral("JAVA_VERSION=\"25.0.1\"\n"), 25},
        {QStringLiteral("JAVA_VERSION=\"17.0.15\"\n"), 17},
        {QStringLiteral("JAVA_VERSION=\"11.0.12\"\n"), 11},
        // Java 8 那代主版本在第二段
        {QStringLiteral("JAVA_VERSION=\"1.8.0_422\"\n"), 8},
        {QStringLiteral("JAVA_VERSION=\"1.8.0_51\"\n"), 8},
        // 只写了日期：不得被当成版本
        {QStringLiteral("JAVA_VERSION_DATE=\"2025-10-21\"\n"), -1},
        // 压根没有版本信息
        {QStringLiteral("MODULES=\"java.base\"\n"), -1},
        {QStringLiteral(""), -1},
        {QStringLiteral("\n\n"), -1},
        // 认不出来就不猜，返回 -1 让调用方退回真的问一次
        {QStringLiteral("JAVA_VERSION=\"not-a-version\"\n"), -1},
        {QStringLiteral("JAVA_VERSION=\"\"\n"), -1},
    };
    for (const auto &c : cases) {
        const int got = GlobalJavaSettings::majorVersionFromReleaseFile(c.first);
        const QString label =
            c.first.trimmed().isEmpty() ? QStringLiteral("<空>") : c.first.trimmed();
        check(got == c.second, QStringLiteral("release 解析 %1 -> %2").arg(label).arg(c.second),
              QStringLiteral("实际 %1").arg(got));
    }

    // 真实的 release 文件里 JAVA_VERSION 只是其中一行，后面还跟着一整行 MODULES。
    // 只认 JAVA_VERSION= 才不会撞上别的行。
    const QString realistic = QStringLiteral("JAVA_VERSION=\"25.0.1\"\n"
                                             "JAVA_VERSION_DATE=\"2025-10-21\"\n"
                                             "MODULES=\"java.base java.compiler java.xml\"\n"
                                             "IMPLEMENTOR=\"Microsoft\"\n");
    check(GlobalJavaSettings::majorVersionFromReleaseFile(realistic) == 25,
          QStringLiteral("真实 release 文件（JAVA_VERSION 后面还跟着 MODULES 等行）"),
          QString::number(GlobalJavaSettings::majorVersionFromReleaseFile(realistic)));

    // 真机对账：本机扫出来的每个运行时，两个来源必须说同一个版本。
    GlobalJavaSettings settings;
    const QMap<int, QString> found = settings.scanLocalJavaVersions();
    out() << "  本机扫到 " << found.size() << " 个运行时，逐个与 java -version 对账：\n";
    for (auto it = found.cbegin(); it != found.cend(); ++it) {
        const QString probed = javaVersionOf(it.value());
        // Java 8 问出来是 "1.8.0_51"，其余是 "25.0.1" 这种
        const QString expect = it.key() == 8 ? QStringLiteral("1.8") : QString::number(it.key());
        check(probed.startsWith(expect),
              QStringLiteral("Java %1：扫描结果与 java -version 一致").arg(it.key()),
              QStringLiteral("%1 -> %2").arg(it.value(), probed));
    }

    // pickMinimalJavaAtLeast()：安装加载器要的 Java **只要够新**（不像启动那样要精确主版本，
    // 见 GlobalJavaSettings::installerJavaFor() 的注释）。这是它的全部规则，所以整张表钉死。
    //
    // 「配的那份太老、本机恰好有够新的」那种场景在这儿造不出来（installerJavaFor() 要读环境
    // 变量、扫磁盘），所以只钉这个纯函数 —— 那才是"挑谁"这件事的唯一判据。
    {
        QMap<int, QString> candidates;
        candidates[8] = QStringLiteral("jre8");
        candidates[17] = QStringLiteral("jre17");
        candidates[21] = QStringLiteral("jre21");
        candidates[25] = QStringLiteral("jre25");
        check(GlobalJavaSettings::pickMinimalJavaAtLeast(17, candidates) == QLatin1String("jre17"),
              QStringLiteral("够新的里面取**最小**的（要 17，候选 17/21/25 → 17）"),
              GlobalJavaSettings::pickMinimalJavaAtLeast(17, candidates));
        check(GlobalJavaSettings::pickMinimalJavaAtLeast(18, candidates) == QLatin1String("jre21"),
              QStringLiteral("要 18 时取 21（17 不够新）"),
              GlobalJavaSettings::pickMinimalJavaAtLeast(18, candidates));
        check(GlobalJavaSettings::pickMinimalJavaAtLeast(8, candidates) == QLatin1String("jre8"),
              QStringLiteral("要 Java 8 时不该挑更新的那份（1.16.5 的安装器就得 Java 8）"),
              GlobalJavaSettings::pickMinimalJavaAtLeast(8, candidates));
        check(GlobalJavaSettings::pickMinimalJavaAtLeast(26, candidates).isEmpty(),
              QStringLiteral("一个都不够新 → 空（调用方据此报错，而不是随便挑一个）"));
        check(GlobalJavaSettings::pickMinimalJavaAtLeast(0, candidates).isEmpty() &&
                  GlobalJavaSettings::pickMinimalJavaAtLeast(-1, candidates).isEmpty(),
              QStringLiteral("requiredMajor <= 0（不知道要求）→ 空"));

        QMap<int, QString> withEmpty;
        withEmpty[13] = QString();
        withEmpty[17] = QStringLiteral("jre17");
        check(GlobalJavaSettings::pickMinimalJavaAtLeast(9, withEmpty) == QLatin1String("jre17"),
              QStringLiteral("路径为空的那条不算候选（主版本对得上也不行）"),
              GlobalJavaSettings::pickMinimalJavaAtLeast(9, withEmpty));

        candidates.clear();
        check(GlobalJavaSettings::pickMinimalJavaAtLeast(17, candidates).isEmpty(),
              QStringLiteral("候选是空的时候 → 空"));
    }
}

// ---------------------------------------------------------------------------
// T. 玩家外观（免鉴权的档案请求 + 内容寻址的贴图缓存）
//
// 这一节**全离线**。真正发请求的那一半（官方 200/204 各长什么样）这里一个字节都不碰：
// 状态码怎么读由 T7 的纯函数钉住，缓存命中的那半条路由 T6 的"同步性"钉住，剩下的
// 留给真机验证（见 PlayerSkinStore.hpp 文件头）。
//
// 为什么值得单开一段：这些判断（哪一段该取哪个字段、缓存文件叫什么名字、命中缓存要不要
// 发请求）**没有一行能靠肉眼看截图验准**，而且它们错了的表现全是"看起来没问题" ——
// 比如缓存文件名里少拼一个斜杠，症状只是"每次开窗都重下一遍贴图"，谁都不会察觉。
// ---------------------------------------------------------------------------

/// 造一段"看起来像皮肤 PNG"的字节：8 字节签名 + IHDR + 宽高。
/// NOTE: **不是**一张真能解码的图 —— looksLikeSkinPng() 只看文件头这 24 个字节，
///       这一节要验的正是"它只看了那么点"（真解码那一步在界面侧，见 .hpp）。
static QByteArray fakeSkinPng(quint32 width, quint32 height) {
    const auto bigEndian = [](quint32 value) {
        QByteArray bytes;
        bytes.append(static_cast<char>((value >> 24) & 0xff));
        bytes.append(static_cast<char>((value >> 16) & 0xff));
        bytes.append(static_cast<char>((value >> 8) & 0xff));
        bytes.append(static_cast<char>(value & 0xff));
        return bytes;
    };
    QByteArray bytes("\x89PNG\r\n\x1a\n", 8);
    bytes.append(QByteArray(4, '\0'));  // 块长度：这里不看它
    bytes.append(QByteArrayLiteral("IHDR"));
    bytes.append(bigEndian(width));
    bytes.append(bigEndian(height));
    return bytes;
}

static void runPlayerSkinTests(const QString &sandbox) {
    section("T. 玩家外观（档案解析 + 内容寻址缓存）");

    const QString skinUrl = QStringLiteral("https://textures.minecraft.net/texture/1a2b3c");
    const QString capeUrl = QStringLiteral("https://textures.minecraft.net/texture/4d5e6f");

    // 一份"官方会发回来"的信封。里面那层 base64 **现场生成**，不贴长字面量：贴的话
    // 改一个字段就得重算一遍，而下一个人多半不会重算 —— 于是测试会对着一段过期的
    // base64 断言，一边改着别的、一边还以为都验到了。
    const auto envelope = [](const QString &innerJson) {
        QJsonObject entry;
        entry.insert(QStringLiteral("name"), QStringLiteral("textures"));
        entry.insert(QStringLiteral("value"), QString::fromLatin1(innerJson.toUtf8().toBase64()));
        QJsonObject root;
        root.insert(QStringLiteral("id"), QStringLiteral("0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f"));
        root.insert(QStringLiteral("name"), QStringLiteral("Player"));
        root.insert(QStringLiteral("properties"), QJsonArray{entry});
        return QJsonDocument(root).toJson(QJsonDocument::Compact);
    };

    // ---- T1 解一份真形状的档案 ----
    {
        const QString inner = QStringLiteral(
                                  R"JSON({"timestamp":1700000000000,)JSON"
                                  R"JSON("profileId":"0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f",)JSON"
                                  R"JSON("profileName":"Player","textures":{)JSON"
                                  R"JSON("SKIN":{"url":"%1","metadata":{"model":"slim"}},)JSON"
                                  R"JSON("CAPE":{"url":"%2"}}})JSON")
                                  .arg(skinUrl, capeUrl);
        QString error;
        const PlayerSkinProfile profile =
            PlayerSkinStore::parseProfileJson(envelope(inner), &error);
        check(profile.skinUrl == skinUrl, "T1 解出 SKIN.url", profile.skinUrl);
        check(profile.capeUrl == capeUrl, "T1 解出 CAPE.url", profile.capeUrl);
        check(profile.variant == QStringLiteral("slim"),
              "T1 metadata.model == slim → 纤细模型", profile.variant);
        check(error.isEmpty(), "T1 解成功时不留下失败原因", error);
        check(!profile.isEmpty(), "T1 有皮肤的档案不是空的");
        check(profile.sameAs(profile), "T1 一份档案和自己逐字段相同");
    }

    // ---- T2 缺件与坏件各是什么下场 ----
    // 「解不出来」和「这个人没有披风」必须分得开：都返回空档案的话，调用方只能靠
    // 猜 —— 而猜错的那种（把一份坏档案当成"没皮肤"）正好会让用户看到默认外观。
    {
        QString error;
        const PlayerSkinProfile noProperties =
            PlayerSkinStore::parseProfileJson(QStringLiteral(R"({"id":"x","name":"Player"})")
                                                  .toUtf8(),
                                              &error);
        check(noProperties.isEmpty() && !error.isEmpty(), "T2 没有 properties → 解不出来且有原因",
              error);

        error.clear();
        QJsonObject entry;
        entry.insert(QStringLiteral("name"), QStringLiteral("textures"));
        // 不是合法 base64（`!` 不在字母表里）
        entry.insert(QStringLiteral("value"), QStringLiteral("!!!!这不是 base64!!!!"));
        QJsonObject root;
        root.insert(QStringLiteral("properties"), QJsonArray{entry});
        check(PlayerSkinStore::parseProfileJson(QJsonDocument(root).toJson(QJsonDocument::Compact),
                                                &error)
                  .isEmpty() &&
                  !error.isEmpty(),
              "T2 base64 坏掉 → 解不出来且有原因", error);

        // 只有 SKIN 没有 CAPE：这是**多数人**的档案（没披风），必须解得出来，
        // 而且 capeUrl 是空串、不是"整个档案作废"。
        const QString skinOnly =
            QStringLiteral(R"JSON({"textures":{"SKIN":{"url":"%1"}}})JSON").arg(skinUrl);
        error.clear();
        const PlayerSkinProfile noCape =
            PlayerSkinStore::parseProfileJson(envelope(skinOnly), &error);
        check(noCape.skinUrl == skinUrl && noCape.capeUrl.isEmpty(),
              "T2 只有 SKIN 没有 CAPE（没披风是常态）→ 照样解得出来，capeUrl 空", error);

        // metadata.model 缺字段 / 是个没见过的词：一律当经典。宁可画粗一点，
        // 也不要因为一个没见过的字符串把手臂画瘦（同 SkinModel::isSlimVariant）。
        const QString noModel =
            QStringLiteral(R"JSON({"textures":{"SKIN":{"url":"%1"}}})JSON").arg(skinUrl);
        check(PlayerSkinStore::parseProfileJson(envelope(noModel), &error).variant ==
                  QStringLiteral("classic"),
              "T2 metadata 缺字段 → 经典模型");
        const QString unknownModel = QStringLiteral(
                                         R"JSON({"textures":{"SKIN":{"url":"%1",)JSON"
                                         R"JSON("metadata":{"model":"wide"}}}})JSON")
                                         .arg(skinUrl);
        check(PlayerSkinStore::parseProfileJson(envelope(unknownModel), &error).variant ==
                  QStringLiteral("classic"),
              "T2 metadata.model 是个没见过的词 → 也当经典");

        // 有 textures 但没有 SKIN.url：每个账号都有皮肤，所以这是协议变了。
        const QString noSkin = QStringLiteral(R"JSON({"textures":{"CAPE":{"url":"%1"}}})JSON")
                                   .arg(capeUrl);
        error.clear();
        check(PlayerSkinStore::parseProfileJson(envelope(noSkin), &error).isEmpty() &&
                  !error.isEmpty(),
              "T2 没有 SKIN.url → 解不出来（不把一份没皮肤的档案发出去）", error);
    }

    // ---- T3 缓存路径是内容寻址的 ----
    {
        const QString first = PlayerSkinStore::cachePathForUrl(skinUrl);
        check(first == PlayerSkinStore::cachePathForUrl(skinUrl),
              "T3 同一个 URL 两次算出同一个路径");
        check(first != PlayerSkinStore::cachePathForUrl(capeUrl), "T3 不同 URL 不同路径");

        const QString name = QFileInfo(first).fileName();
        check(name.size() == 44 && name.endsWith(QStringLiteral(".png")),
              "T3 文件名是 40 位十六进制 + .png（sha1）", name);
        check(name.left(40) ==
                  QString::fromLatin1(
                      QCryptographicHash::hash(skinUrl.toUtf8(), QCryptographicHash::Sha1).toHex()),
              "T3 那 40 位真的是这个 URL 的 sha1（不是序号、不是时间戳）", name.left(40));
        // 缓存在**当前游戏目录**下（沙盒里就是沙盒）：这条同时钉住"它基于 AppPaths，
        // 不会写到 PCL 那份只读的数据目录里去"。
        check(QDir::cleanPath(first).startsWith(QDir::cleanPath(sandbox) + QLatin1Char('/')),
              "T3 缓存落在当前游戏目录下面（换目录各存一份）",
              QDir::toNativeSeparators(first));
    }

    // ---- T4 档案缓存的往返与坏件 ----
    {
        const QString uuid = QStringLiteral("0f0f0f0f-0f0f-0f0f-0f0f-0f0f0f0f0f0f");
        const QString uuidPlain = QStringLiteral("0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f");
        check(PlayerSkinStore::uuidKey(uuid) == uuidPlain,
              "T4 带横线的 uuid 归一成 32 位无横线（URL 和文件名共用这一个形式）");
        check(PlayerSkinStore::uuidKey(uuidPlain.toUpper()) == uuidPlain,
              "T4 大写也归一成小写（官方一律小写，大写进去查不到人）");
        check(PlayerSkinStore::uuidKey(QStringLiteral("不是 uuid")).isEmpty(),
              "T4 认不出来 → 空串（不去拼一个野路径）");
        check(PlayerSkinStore::cachedProfilePath(QStringLiteral("不是 uuid")).isEmpty(),
              "T4 uuid 认不出来时档案路径也是空串");
        check(PlayerSkinStore::cachedProfilePath(uuid) ==
                  PlayerSkinStore::cachedProfilePath(uuidPlain),
              "T4 带不带横线的 uuid 指向同一份档案缓存");

        PlayerSkinProfile written;
        written.skinUrl = skinUrl;
        written.capeUrl = capeUrl;
        written.variant = QStringLiteral("slim");
        QString error;
        check(PlayerSkinStore::saveProfile(uuid, written, &error),
              "T4 存一份档案（目录不存在也要自己建出来）", error);

        PlayerSkinProfile loaded;
        check(PlayerSkinStore::loadCachedProfile(uuid, &loaded), "T4 读回来成功");
        check(loaded.sameAs(written), "T4 往返逐字段一致",
              QStringLiteral("%1 / %2 / %3").arg(loaded.skinUrl, loaded.capeUrl, loaded.variant));

        // 坏文件：读不懂 / 版本不认识 / 没有皮肤。三条都必须返回 false **而不是抛**，
        // 而且**不动 out**（调用方手上那份别被一个空值盖掉）。
        const QString path = PlayerSkinStore::cachedProfilePath(uuid);
        PlayerSkinProfile untouched;
        untouched.skinUrl = QStringLiteral("https://example.invalid/keep-me");
        const QList<QPair<QString, QByteArray>> broken = {
            {QStringLiteral("不是 JSON"), QByteArrayLiteral("{ 这不是 json")},
            {QStringLiteral("版本不认识"), QByteArrayLiteral(R"({"version":99,"skin":"x"})")},
            {QStringLiteral("有版本没皮肤"), QByteArrayLiteral(R"({"version":1,"skin":""})")},
        };
        for (const auto &item : broken) {
            writeFileAt(path, item.second);
            untouched.skinUrl = QStringLiteral("https://example.invalid/keep-me");
            check(!PlayerSkinStore::loadCachedProfile(uuid, &untouched),
                  QStringLiteral("T4 档案坏掉（%1）→ 返回 false 而不是抛").arg(item.first));
            check(untouched.skinUrl == QStringLiteral("https://example.invalid/keep-me"),
                  QStringLiteral("T4 失败时不动 out（%1）").arg(item.first), untouched.skinUrl);
        }
        // 手改文件会干的事：variant 写成一个没见过的词 → 当经典，而不是原样透出去
        writeFileAt(path, QByteArrayLiteral(R"({"version":1,"skin":"https://a.b/c.png",)"
                                            R"("variant":"wide"})"));
        PlayerSkinProfile odd;
        check(PlayerSkinStore::loadCachedProfile(uuid, &odd) &&
                  odd.variant == QStringLiteral("classic"),
              "T4 缓存里 variant 是个没见过的词 → 读回来当经典", odd.variant);
        QFile::remove(path);
    }

    // ---- T5 贴图字节的判据（只看文件头，不解码） ----
    {
        check(PlayerSkinStore::looksLikeSkinPng(fakeSkinPng(64, 64)), "T5 64×64 → 认");
        check(PlayerSkinStore::looksLikeSkinPng(fakeSkinPng(64, 32)),
              "T5 64×32（老格式）→ 认");
        check(!PlayerSkinStore::looksLikeSkinPng(fakeSkinPng(64, 16)), "T5 64×16 → 不认");
        check(!PlayerSkinStore::looksLikeSkinPng(fakeSkinPng(128, 128)), "T5 128×128 → 不认");
        check(!PlayerSkinStore::looksLikeSkinPng(fakeSkinPng(32, 64)), "T5 32×64 → 不认");
        check(!PlayerSkinStore::looksLikeSkinPng(QByteArrayLiteral("<html>404</html>")),
              "T5 一张网页 → 不认（下回来的经常是这个）");
        check(!PlayerSkinStore::looksLikeSkinPng(QByteArray()), "T5 空字节 → 不认");
        check(!PlayerSkinStore::looksLikeSkinPng(QByteArrayLiteral("\x89PNG\r\n\x1a\n")),
              "T5 只有签名、后面截断了 → 不认（不能读越界）");
    }

    // ---- T6 贴图地址认不认（官方给的就是 http://，这条 2026-09-21 折在真机上） ----
    {
        // 下面这个 URL 是**真档案里的形状**，不是编的：官方 sessionserver 返回的
        // SKIN.url / CAPE.url 都是 `http://textures.minecraft.net/texture/<sha>`。
        // 原先那条"不是 https 就拒"的规矩把**每一份真档案**都拒了 —— 表现就是右栏永远
        // 画默认外观、缓存目录里只躺着一份 profile-*.json、一张 .png 都没有。
        const QUrl upgraded = PlayerSkinStore::textureRequestUrl(
            QStringLiteral("http://textures.minecraft.net/texture/cfa1f1c5ca1e"));
        check(upgraded.isValid() && upgraded.scheme() == QStringLiteral("https"),
              "T6 官方那个 http:// 地址认得出来、并升级成 https", upgraded.toString());
        check(upgraded.host() == QStringLiteral("textures.minecraft.net") &&
                  upgraded.path() == QStringLiteral("/texture/cfa1f1c5ca1e"),
              "T6 升级只换协议，host 和 path 原样不动", upgraded.toString());

        const QUrl alreadyHttps = PlayerSkinStore::textureRequestUrl(skinUrl);
        check(alreadyHttps == QUrl(skinUrl),
              "T6 本来就是 https 的一动都不动", alreadyHttps.toString());

        // 拒掉的那些：地址是**外面**（解出来的档案）给的，不能让它把请求带到别处去。
        // ftp/file 是靠"协议只认 http(s)"挡下的，别人家的域名是靠 host 挡下的 —— 两条
        // 规矩各有用处，所以两条都钉住。
        const QStringList rejects = {
            QStringLiteral("file:///C:/Windows/win.ini"),
            QStringLiteral("ftp://textures.minecraft.net/texture/x"),
            QStringLiteral("https://evil.example.com/texture/x"),
            QStringLiteral("http://textures.minecraft.net.evil.example.com/x"),
            QString(),
            QStringLiteral("这不是一个地址"),
        };
        QString firstAccepted;
        for (const QString &bad : rejects) {
            if (PlayerSkinStore::textureRequestUrl(bad).isValid() && firstAccepted.isEmpty()) {
                firstAccepted = bad;
            }
        }
        check(firstAccepted.isEmpty(),
              "T6 别的协议 / 别人家的 host / 空串 / 一句废话 → 一律认不出来", firstAccepted);
    }

    // ---- T6b 命中缓存 → 同步发信号（一个请求都没发） ----
    {
        const QString url = QStringLiteral("https://textures.minecraft.net/texture/cached-one");
        const QString path = PlayerSkinStore::cachePathForUrl(url);
        writeFileAt(path, fakeSkinPng(64, 64));

        PlayerSkinStore store;
        QString gotUrl;
        QString gotPath;
        int readyCount = 0;
        int failedCount = 0;
        QString lastError;
        QObject::connect(&store, &PlayerSkinStore::textureReady,
                         [&](const QString &readyUrl, const QString &readyPath) {
                             ++readyCount;
                             gotUrl = readyUrl;
                             gotPath = readyPath;
                         });
        QObject::connect(&store, &PlayerSkinStore::failed, [&](const QString &message) {
            ++failedCount;
            lastError = message;
        });

        store.fetchTexture(url);
        // "同步"本身就是断言：一个真的网络请求不可能在这一行之前回来。所以这一条同时
        // 钉住了两件事 —— 命中缓存会发信号、以及**它没有去问官方**。
        check(readyCount == 1 && gotPath == path,
              "T6b 命中缓存 → 同步发 textureReady（贴图 URL 是内容哈希，缓存永不失效）",
              gotPath);
        check(gotUrl == url, "T6b 发回来的 URL 就是**问的那个**（升级只发生在发请求那一步）",
              gotUrl);

        // 空 URL = 这个人没有披风。**常态**，不是错误：一个信号都不该发。
        store.fetchTexture(QString());
        check(readyCount == 1 && failedCount == 0,
              "T6b 没有披风（空 URL）→ 什么都不做、也不报错");

        // 地址是我们从外面解出来的，取之前要过 textureRequestUrl()（判据见上一节）。
        // 这样写还有个好处：这条路**不发请求**，于是"地址不认就直接判失败"这件事能在
        // 离线的一节里钉住。
        store.fetchTexture(QStringLiteral("file:///C:/Windows/win.ini"));
        check(failedCount == 1 && lastError.contains(QStringLiteral("不可用")),
              "T6b 地址不认的贴图 → 直接当失败（不跟着一份被改过的档案去下任意地址）",
              lastError);

        // NOTE: "不命中缓存时会去请求"这条**故意不在这里断言** —— 那会真的发一个请求，
        //       而这一节是不联网的。它的两个半边都有别的落点：缓存检查发生在请求之前
        //       （T6b 那条同步性），请求本身的行为留给真机验证。
        QFile::remove(path);
    }

    // ---- T7 状态码怎么读（204 是唯一反直觉的那一个） ----
    {
        using Outcome = PlayerSkinStore::ProfileFetchOutcome;
        const QString inner =
            QStringLiteral(R"JSON({"textures":{"SKIN":{"url":"%1"}}})JSON").arg(skinUrl);
        check(PlayerSkinStore::classifyProfileResponse(200, envelope(inner)) == Outcome::Ok,
              "T7 200 + 一份能解出皮肤的 body → Ok");
        check(PlayerSkinStore::classifyProfileResponse(204, QByteArray()) ==
                  Outcome::NoSuchPlayer,
              "T7 204 → 「查不到这个人」（sessionserver 也用 204 表达软限流），**不是错误**");
        // 429 以前钉的是 Failed（理由是"限流走 204 那条路"）—— 2026-09-22 真机上撞到它
        // 之后这条理由不成立了：它确实是限流，而且是**明说**的那种。
        check(PlayerSkinStore::classifyProfileResponse(429, QByteArray()) == Outcome::Throttled,
              "T7 429 → 限流（也不是错误，但和 204 不同：它明说问得太勤，要退避）");

        // 退避窗口。这三条是"又 429"那个现象的解药：被挡之后这一分钟里不要再问。
        const QDateTime throttleNow = QDateTime::currentDateTimeUtc();
        check(!PlayerSkinStore::withinThrottleBackoff(QDateTime(), throttleNow),
              "T7 从没被限流过（无效值）→ 不跳（默认那份不许变成「永远跳过」）");
        check(PlayerSkinStore::withinThrottleBackoff(
                  throttleNow.addMSecs(PlayerSkinStore::kThrottleBackoffMs), throttleNow),
              "T7 刚被限流过 → 这一分钟里跳过（不然每次刷新都往限流窗口里撞）");
        check(!PlayerSkinStore::withinThrottleBackoff(throttleNow.addMSecs(-1), throttleNow),
              "T7 退避窗口过了 → 照常去问（限流不许把外观永久冻住）");
        check(PlayerSkinStore::classifyProfileResponse(500, QByteArray()) == Outcome::Failed,
              "T7 500 → 失败");
        check(PlayerSkinStore::classifyProfileResponse(0, QByteArray()) == Outcome::Failed,
              "T7 连状态码都没有（网络层就失败了）→ 失败");
        // 被代理塞了一张网页时很常见：状态码是 200，但 body 不是档案。
        // 这一条是**必须**的 —— 只看状态码会把一页 HTML 当成"这人没皮肤"。
        check(PlayerSkinStore::classifyProfileResponse(
                  200, QByteArrayLiteral("<html>429 Too Many Requests</html>")) ==
                  Outcome::Failed,
              "T7 200 但 body 不是档案 → 失败（不能只看状态码）");
    }
}

// ---------------------------------------------------------------------------

/// 离线账号那张随机皮肤：地址怎么拼、列表怎么解、挑下标越界了怎么办、盘上那一行还算不算数。
///
/// NOTE: 这一节**一个请求都不发**。"那个端点今天还在不在"不是断言能钉住的东西，它归
///       mw_check 里那条一次性探针（`random-skin-live`）。这里只钉**没有一行能靠肉眼
///       看准**的那几件事。
static void runRandomSkinTests(const QString &sandbox) {
    section("ZE. 离线账号的随机皮肤（挑地址 + 记盘）");

    // 下面这两个哈希是**真的**：2026-09-24 从 `api.mineskin.org/v2/skins?size=3` 拿回来的
    // 那三行原样（连重复的那一条也照抄 —— 它正好拿来钉去重）。自己编一串 `aaaa…` 证不了
    // "64 位十六进制"这个形态是**从真响应里**看出来的这件事。
    const QString hashA = QStringLiteral(
        "ba61d4e3a112c1959cfc5c7811ee442f055334ef787eee1795f9d947d56bfa39");
    const QString hashB = QStringLiteral(
        "a48f69d77cb323c5bbe0250143759cd7abff5e08774f7888556fa641cfa75f12");

    // ---- ZE1 列表地址（唯一出处：想换源就改这一处） ----
    {
        const QUrl list = RandomSkinStore::listRequestUrl(RandomSkinStore::defaultListSize());
        check(list.host() == QStringLiteral("api.mineskin.org") &&
                  list.path() == QStringLiteral("/v2/skins"),
              "ZE1 列表端点还是那一个（NameMC 那条路走不通，理由见 RandomSkinStore.hpp）",
              list.toString());
        check(list.query() == QStringLiteral("size=128"),
              "ZE1 默认要满一页（列表只有 next 游标、没有「跳到第 N 页」，「随机」的范围就是这一页）",
              list.query());
        // 超限**自己先钳住**：官方对超限回的是 400（实测 size=200/256/500 都是），
        // 而不是一个截短了的列表 —— 与其拿一个 400 去猜，不如根本别发出去。
        check(RandomSkinStore::listRequestUrl(100000).query() == QStringLiteral("size=128"),
              "ZE1 要得比上限多 → 钳到 128（官方对超限回 400，不是给个短列表）",
              RandomSkinStore::listRequestUrl(100000).query());
        check(RandomSkinStore::listRequestUrl(0).query() == QStringLiteral("size=1") &&
                  RandomSkinStore::listRequestUrl(-7).query() == QStringLiteral("size=1"),
              "ZE1 要 0 条 / 负数 → 钳到 1（不拼出一个 size=0 的地址）");
    }

    // ---- ZE2 拼官方贴图地址（那个 host 只有一处知道） ----
    {
        const QString built = PlayerSkinStore::textureUrlForHash(hashA);
        check(built == QStringLiteral("https://textures.minecraft.net/texture/%1").arg(hashA),
              "ZE2 拼出来的就是官方 CDN 上那一张（挑它的是别人、装它的是这里）", built);
        // 关键的一条：拼出来的东西必须过 textureRequestUrl() —— 那是"这个地址算不算数"的
        // **唯一**判据。过不去的话，"挑出来的地址"和"能不能取"就成了两套规矩。
        check(PlayerSkinStore::textureRequestUrl(built).isValid(),
              "ZE2 拼出来的地址过得了 textureRequestUrl()（白名单只有一套）");

        // 拒掉的形态：长度不对 / 有大写 / 混了非十六进制 / 空串。**不悄悄转小写** ——
        // 这是外面来的东西，把一个大写串"修好"成合法地址，等于让调用方以为它拿到的
        // 就是它要的那一张。
        const QStringList rejects = {
            hashA.left(63),  // 短一位
            hashA + QStringLiteral("0"),  // 长一位
            hashA.toUpper(),  // 大写（官方一律小写）
            hashA.left(63) + QStringLiteral("z"),  // 非十六进制
            QStringLiteral("1a2b3c"),  // 老档案里那种短 hash
            QString(),
        };
        QString firstAccepted;
        for (const QString &bad : rejects) {
            if (!PlayerSkinStore::textureUrlForHash(bad).isEmpty() && firstAccepted.isEmpty()) {
                firstAccepted = bad;
            }
        }
        check(firstAccepted.isEmpty(),
              "ZE2 长度不对 / 大写 / 非十六进制 / 空串 → 一律拼不出地址", firstAccepted);
    }

    // ---- ZE3 解那一页（真响应 + 每一条坏在哪） ----
    {
        // 真响应的形状（`name` 真的是 null）。里面混了六条，只有两条该活下来：
        //   ① hashA            真的、能用
        //   ② hashA 再来一次    同一张图连着出现 —— **去重**
        //   ③ hashB            真的、能用
        //   ④ 短一位的 hash     形态不对 → 丢（留着它只会在挑中之后才发现是坏的）
        //   ⑤ 大写 hash         同上
        //   ⑥ texture 是 null   没有贴图 → 跳过（另一条还是能挑）
        const QByteArray body =
            QByteArrayLiteral(R"JSON({"success":true,"skins":[)JSON") +
            QByteArrayLiteral(R"JSON({"uuid":"c1db371c68fe4c02a4069aed4aa44bbe",)JSON")
                .append(R"JSON("shortId":"055516fe","name":null,"texture":")JSON")
                .append(hashA.toUtf8())
                .append(R"JSON(","timestamp":1790216929364},)JSON")
                .append(R"JSON({"uuid":"dup","shortId":"x","name":null,"texture":")JSON")
                .append(hashA.toUtf8())
                .append(R"JSON(","timestamp":1790216929365},)JSON")
                .append(R"JSON({"uuid":"2cafb05fd3bb4639b2dff9cf7171eeea",)JSON")
                .append(R"JSON("shortId":"a8dd74ab","name":"某人","texture":")JSON")
                .append(hashB.toUtf8())
                .append(R"JSON(","timestamp":1790216919393},)JSON")
                .append(R"JSON({"uuid":"short","texture":")JSON")
                .append(hashA.left(63).toUtf8())
                .append(R"JSON("},)JSON")
                .append(R"JSON({"uuid":"upper","texture":")JSON")
                .append(hashA.toUpper().toUtf8())
                .append(R"JSON("},)JSON")
                .append(QByteArrayLiteral(R"JSON({"uuid":"notexture","texture":null}])JSON"))
                .append(QByteArrayLiteral("}"));
        QString error;
        const QStringList hashes = RandomSkinStore::parseTextureHashes(body, &error);
        check(hashes == QStringList{hashA, hashB},
              "ZE3 六条里只活下来两条：去重 + 形态不对的丢掉 + 没有贴图的跳过",
              hashes.join(QStringLiteral(", ")));
        check(error.isEmpty(), "ZE3 解得出来就不该有那句原因", error);

        // 解出来的每一条都拼得出地址 —— 和 ZE2 串起来，这条是"挑中的一定能取"的前提。
        QString unpickable;
        for (const QString &hash : hashes) {
            if (PlayerSkinStore::textureUrlForHash(hash).isEmpty()) {
                unpickable = hash;
            }
        }
        check(unpickable.isEmpty(), "ZE3 解出来的每一条都拼得出官方地址", unpickable);

        // 三种解不出来的情况，各有一句**不同**的原因（"接口变了"和"这个库现在空的"
        // 是两回事，混成一句就没法查）。
        QString e1, e2, e3;
        check(RandomSkinStore::parseTextureHashes(QByteArrayLiteral("<html>Just a moment...</html>"),
                                                  &e1)
                      .isEmpty() &&
                  !e1.isEmpty(),
              "ZE3 不是 JSON（比如代理塞了一张 Cloudflare 的拦截页）→ 空 + 一句原因", e1);
        check(RandomSkinStore::parseTextureHashes(
                  QByteArrayLiteral(R"JSON({"success":true,"nope":[]})JSON"), &e2)
                      .isEmpty() &&
                  !e2.isEmpty(),
              "ZE3 是 JSON 但没有 skins 这一项（接口形状变了？）→ 空 + 一句原因", e2);
        check(RandomSkinStore::parseTextureHashes(
                  QByteArrayLiteral(R"JSON({"success":true,"skins":[]})JSON"), &e3)
                      .isEmpty() &&
                  !e3.isEmpty(),
              "ZE3 skins 是空的（这次真的一条都没有）→ 空 + 一句原因", e3);
        check(e1 != e2 && e2 != e3 && e1 != e3,
              "ZE3 那三种情况说的是三句不同的话（不然查起来分不出是哪种）");
    }

    // ---- ZE4 挑下标（掷骰子和取值拆开，取值这半每条边界都能钉） ----
    {
        const QStringList hashes{hashA, hashB};
        check(RandomSkinStore::pickIndex(hashes, 0) == hashA, "ZE4 第 0 张");
        check(RandomSkinStore::pickIndex(hashes, 1) == hashB, "ZE4 最后一张");
        check(RandomSkinStore::pickIndex(hashes, 2).isEmpty() &&
                  RandomSkinStore::pickIndex(hashes, -1).isEmpty(),
              "ZE4 越界（多了 / 负数）→ 空串，走失败那条路，不去读一个不存在的下标");
        check(RandomSkinStore::pickIndex(QStringList(), 0).isEmpty(),
              "ZE4 空列表 → 空串");

        // 骰子那半：**不**断言"两次一定不一样"（那是在赌运气），只断言它真的在动。
        // 128 个桶里抽 64 次，全都落在**同一个**桶的概率是 (1/128)^63 ≈ 0 —— 这条钉的是
        // "bounded() 被写成 bounded(1)、或者干脆硬编成第一张"那类改法。
        QStringList many;
        for (int i = 0; i < 128; ++i) {
            many.append(QStringLiteral("h%1").arg(i));
        }
        QSet<QString> picked;
        bool inRange = true;
        for (int i = 0; i < 64; ++i) {
            const QString one = RandomSkinStore::pickIndex(
                many, QRandomGenerator::global()->bounded(many.size()));
            if (one.isEmpty()) {
                inRange = false;
                break;
            }
            picked.insert(one);
        }
        check(inRange, "ZE4 掷 64 次骰子，每一次都落在 [0, size) 里（没有一次空手而归）");
        check(picked.size() > 1,
              "ZE4 那 64 次挑出来**不止一张**（钉的是「骰子真的在动」，不是在赌两次不一样）",
              QString::number(picked.size()));
    }

    // ---- ZE5 盘上那一行（往返 + 坏件） ----
    {
        // 离线账号的 uuid 形态和正版一样（md5("OfflinePlayer:" + 名字)，见 AccountStore），
        // 所以这里拿一个正的 uuid 就够。
        const QString uuid = QStringLiteral("1f2e3d4c-5b6a-7988-9a0b-1c2d3e4f5a6b");
        const QString url = PlayerSkinStore::textureUrlForHash(hashA);

        check(RandomSkinStore::chosenPathFor(QStringLiteral("不是 uuid")).isEmpty(),
              "ZE5 uuid 认不出来 → 路径是空串（不拼一个野路径）");
        check(RandomSkinStore::loadChosenSkinUrl(uuid).isEmpty(),
              "ZE5 还没挑过 → 空串（**常态**：第一次用这个账号，不是错误）");

        const QString path = RandomSkinStore::chosenPathFor(uuid);
        check(path.endsWith(QStringLiteral("/random-1f2e3d4c5b6a79889a0b1c2d3e4f5a6b.txt")),
              "ZE5 记在 <skinsDir>/random-<32 位>.txt", QDir::toNativeSeparators(path));
        check(QDir::cleanPath(path).startsWith(QDir::cleanPath(sandbox) + QLatin1Char('/')),
              "ZE5 落在当前游戏目录下面（换目录各记一份）",
              QDir::toNativeSeparators(path));

        QString error;
        check(RandomSkinStore::saveChosenSkinUrl(uuid, url, &error),
              "ZE5 记下来（目录不存在也要自己建出来）", error);
        check(RandomSkinStore::loadChosenSkinUrl(uuid) == url, "ZE5 读回来就是那一张");

        // 盘上那份**也算外面来的**（文件是可以手改的），所以读的时候要过同一把尺子。
        const QList<QPair<QString, QString>> broken = {
            {QStringLiteral("https://evil.example.com/texture/x"),
             QStringLiteral("别人家的 host")},
            {QStringLiteral("file:///C:/Windows/win.ini"), QStringLiteral("不是 http(s)")},
            {QString(), QStringLiteral("空文件")},
            {QStringLiteral("   \n  "), QStringLiteral("只有空白")},
            {QStringLiteral("随便写的一句话"), QStringLiteral("一句废话")},
            {QStringLiteral(R"({"skin":"x"})"), QStringLiteral("一段 JSON")},
        };
        QString firstAccepted;
        for (const auto &one : broken) {
            QFile file(path);
            if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
                firstAccepted = QStringLiteral("写不进 %1").arg(one.second);
                break;
            }
            file.write(one.first.toUtf8());
            file.close();
            if (!RandomSkinStore::loadChosenSkinUrl(uuid).isEmpty() && firstAccepted.isEmpty()) {
                firstAccepted = one.second;
            }
        }
        check(firstAccepted.isEmpty(),
              "ZE5 手改成别人家的 host / 别的协议 / 空白 / 废话 → 一律当没挑过（读侧重新挑一张）",
              firstAccepted);

        // 官方那个地址写成 http:// 时读回来是**原样那一行**：升级只发生在真发请求那一刻
        // （见 PlayerSkinStore::textureRequestUrl 的 NOTE）—— 这里要是顺手改了它，
        // 缓存路径和 textureReady() 发出去的 url 就对不上了，调用方认不出贴图。
        const QString httpUrl = QStringLiteral("http://textures.minecraft.net/texture/") + hashA;
        {
            QFile file(path);
            check(file.open(QIODevice::WriteOnly | QIODevice::Truncate),
                  "ZE5 前提：那个文件写得进去");
            file.write(httpUrl.toUtf8());
            file.close();
        }
        check(RandomSkinStore::loadChosenSkinUrl(uuid) == httpUrl,
              "ZE5 盘上是 http:// 的官方地址 → 原样读回来，**不在这里升级**",
              RandomSkinStore::loadChosenSkinUrl(uuid));

        // 收拾自己写的东西。
        QFile::remove(path);
        check(RandomSkinStore::loadChosenSkinUrl(uuid).isEmpty(), "ZE5 删掉之后又回到「还没挑过」");
    }
}

// ---------------------------------------------------------------------------
// ZF. 离线名字 → 游戏会给的那张官方默认皮肤（src/manage/DefaultSkin）
//
// 这一节有两半：**纯函数**那一半（Java 的 UUID.hashCode()、18 元表的下标、两套规矩各自的
// 路径、缓存文件名怎么拼）和**真读一个 JAR** 那一半。后半是真跑的：工程自己造几个假版本
// 目录 + 假 JAR，因为这一节最要紧的一条断言恰恰是"判据是**那个 JAR 里有没有这一条**，
// 不是版本号" —— 拿真版本号去判就证不出这件事（而且分界线那两个小版本本机一个都没有）。
//
// 真值表来自**本机 JVM**：一个跑 `UUID.nameUUIDFromBytes(("OfflinePlayer:" + 名字).getBytes(UTF_8))`
// 的小程序（java-runtime-delta 那份 JDK 编译运行的）。自己按理解推一遍再拿它当断言，
// 等于什么都没证 —— 所以这里钉的是 JVM 打印出来的那几行原样，含两个中文名字。
//
// 假 JAR 那套工具（makeFakeJar / makePngBytes）在 fakejar.hpp 里，和 mw_check 的 ZG 段共用。
// ---------------------------------------------------------------------------
static void runDefaultSkinTests(const QString &sandbox) {
    section("ZF. 离线名字 → 官方默认皮肤（Java 哈希 + 两套规矩 + 真 JAR）");

    // 前提：这一节直接拼 sandbox 底下的路径，而 cachePathFor() 走 AppPaths::skinsDir()。
    // 两边必须指的是同一份 .minecraft —— 前面哪一节要是忘了把数据根目录换回来，
    // 那一条得先红，不然下面的失败全都会指向错的地方。
    check(AppPaths::minecraftDir() == sandbox, "ZF0 前提：数据根目录就是本工程的沙箱",
          AppPaths::minecraftDir());

    // 名字 | uuid（去横线的 32 位） | Java 的 hashCode | 老规矩走 alex 吗 | 18 元表下标
    struct Truth {
        const char *name;
        const char *uuid;
        int hash;
        bool oldSlim;
        int index;
    };
    const Truth truths[] = {
        {"mwcheck", "812a1f97218b36f699f24550d02d507b", -377602998, false, 12},
        {"RandSkin", "e65be28925ff3a6f85e13db168f27f93", 783784644, false, 6},
        {"Steve", "5627dd98e6be3c21b8a8e92344183641", 1277771483, true, 11},
        {"Zed", "15e4f325c74836a38c9ae454e9162eca", -1222635752, false, 10},
        // 下标 0 和 17 是**表的两端**：分开覆盖才证得了"名字是按 index % 9 取的、
        // 窄宽是按 index < 9 判的"，只测中间那几个的话两边都对得上就看不出来。
        {"Mine", "f2de408889f93162b33450698f1c6a53", 1192184784, false, 0},
        {"有 空格", "6d120cb0cacc3730959a60976be407a6", 1503681713, true, 17},
        {"玩家", "511a6918f6693b23ba72decf60a9cb59", 2108180397, true, 3},
        {"测试玩家", "74fa8980f33435d2ad59af30e3c2f0cb", -917118039, true, 15},
        {"Notch", "b50ad385829d3141a2167e7d7539ba7f", -524802362, false, 4},
    };
    const QStringList names = DefaultSkin::skinNames();

    // ---- ZF1 名字表（新规矩那 18 条的名字顺序，唯一出处） ----
    check(names == QStringList({QStringLiteral("alex"), QStringLiteral("ari"), QStringLiteral("efe"),
                                QStringLiteral("kai"), QStringLiteral("makena"),
                                QStringLiteral("noor"), QStringLiteral("steve"),
                                QStringLiteral("sunny"), QStringLiteral("zuri")}),
          "ZF1 名字表那 9 个、顺序和游戏里那个数组一样（1.20.1 常量池里逐个抄的）",
          names.join(QStringLiteral(", ")));
    check(DefaultSkin::eighteenCount() == 18,
          "ZF1 一次要点 18 张 = 9 个名字 × {窄, 宽}（18 不是另一个常量，是从表长出来的）",
          QString::number(DefaultSkin::eighteenCount()));

    // ---- ZF2 Java 那个 UUID.hashCode()（**逐位**要和 JVM 一样） ----
    {
        QString mismatch;
        for (const Truth &t : truths) {
            const QString name = QStringLiteral("%1").arg(QString::fromUtf8(t.name));
            // 游戏算 uuid 那一句：md5("OfflinePlayer:" + 名字) 再摆版本位/变体位。
            // **中文名字也要对**（所以真值表里放了两个）：错一个字节就是另一张脸。
            const QString uuid = AccountStore::offlineUuidFor(name);
            if (uuid != QString::fromLatin1(t.uuid)) {
                mismatch = QStringLiteral("%1 的 uuid 是 %2，JVM 给的是 %3")
                               .arg(name, uuid, QString::fromLatin1(t.uuid));
                break;
            }
            int hash = 0;
            if (!DefaultSkin::uuidHashCode(uuid, &hash) || hash != t.hash) {
                mismatch = QStringLiteral("%1 的 hashCode 是 %2，JVM 给的是 %3")
                               .arg(name)
                               .arg(hash)
                               .arg(t.hash);
                break;
            }
            // 带横线的写法（AuthManager::playerUuid() 给的那种）必须是同一个哈希。
            int dashedHash = 0;
            const QString dashed = uuid.left(8) + QLatin1Char('-') + uuid.mid(8, 4) +
                                   QLatin1Char('-') + uuid.mid(12, 4) + QLatin1Char('-') +
                                   uuid.mid(16, 4) + QLatin1Char('-') + uuid.mid(20);
            if (!DefaultSkin::uuidHashCode(dashed, &dashedHash) || dashedHash != t.hash) {
                mismatch = QStringLiteral("%1 带横线的 uuid 算出来是 %2（不带横线是 %3）")
                               .arg(name)
                               .arg(dashedHash)
                               .arg(t.hash);
                break;
            }
        }
        check(mismatch.isEmpty(),
              "ZF2 9 个名字（含两个中文名）的 uuid 和 hashCode 与 JVM 逐位一致", mismatch);

        int ignored = 0;
        check(!DefaultSkin::uuidHashCode(QStringLiteral("不是uuid"), &ignored) &&
                  !DefaultSkin::uuidHashCode(QString(), &ignored) &&
                  !DefaultSkin::uuidHashCode(QStringLiteral("812a1f97-218b-36f6-99f2-4550d02d50"), &ignored),
              "ZF2 认不出形状的一律返回 false（少一位也不行）—— 不悄悄补零凑一个数出来");
    }

    // ---- ZF3 新规矩：18 元表的下标 ----
    {
        QString wrong;
        for (const Truth &t : truths) {
            const QString uuid = QString::fromLatin1(t.uuid);
            const DefaultSkin::Prediction p = DefaultSkin::predict(uuid, DefaultSkin::Rule::Eighteen);
            const QString expectedEntry =
                QStringLiteral("assets/minecraft/textures/entity/player/%1/%2.png")
                    .arg(t.index < 9 ? QStringLiteral("slim") : QStringLiteral("wide"),
                         names.at(t.index % 9));
            if (!p.valid || p.index != t.index || p.entryPath != expectedEntry ||
                p.slim != (t.index < 9) || p.name != names.at(t.index % 9)) {
                wrong = QStringLiteral("%1: 下标 %2（JVM 说 %3）、路径 %4")
                            .arg(QString::fromUtf8(t.name))
                            .arg(p.index)
                            .arg(t.index)
                            .arg(p.entryPath);
                break;
            }
        }
        check(wrong.isEmpty(), "ZF3 9 个名字的下标 / 名字 / 窄宽 / 条目路径全对（下界 0 和上界 17 都在里面）",
              wrong);

        // 负数哈希要**掰回** [0, 18)：Java 的 Math.floorMod 是这么定义的，C++ 的 % 不是。
        // mwcheck 的哈希是 -377602998，直接取 % 会得到 -12。
        const DefaultSkin::Prediction mwcheck =
            DefaultSkin::predict(QString::fromLatin1("812a1f97218b36f699f24550d02d507b"),
                                 DefaultSkin::Rule::Eighteen);
        check(mwcheck.index == 12 && mwcheck.entryPath.endsWith(QStringLiteral("wide/kai.png")),
              "ZF3 负数哈希按 floorMod 掰回正数（mwcheck → 12 → wide/kai，不是 -12）",
              QString::number(mwcheck.index));

        check(!DefaultSkin::predict(QString::fromLatin1("812a1f97218b36f699f24550d02d507b"),
                                    DefaultSkin::Rule::Unknown)
                   .valid,
              "ZF3 没定下规矩（Unknown）时不算 —— 不当成「随便挑一套」");
    }

    // ---- ZF4 老规矩：只有两张，按哈希的最低位 ----
    {
        QString wrong;
        for (const Truth &t : truths) {
            const DefaultSkin::Prediction p =
                DefaultSkin::predict(QString::fromLatin1(t.uuid), DefaultSkin::Rule::Two);
            const QString expectedEntry = QStringLiteral("assets/minecraft/textures/entity/%1.png")
                                              .arg(t.oldSlim ? QStringLiteral("alex")
                                                             : QStringLiteral("steve"));
            if (!p.valid || p.slim != t.oldSlim || p.entryPath != expectedEntry || p.index != -1) {
                wrong = QStringLiteral("%1: %2").arg(QString::fromUtf8(t.name), p.entryPath);
                break;
            }
        }
        check(wrong.isEmpty(),
              "ZF4 老规矩只按最低位分 alex(窄) / steve(宽)，下标固定 -1（字节码里 alex 就是 slim）",
              wrong);
    }

    // ---- ZF5 缓存文件名（读和写的唯一出处） ----
    {
        const QString uuid = QString::fromLatin1("f2de408889f93162b33450698f1c6a53");
        const QString modern = DefaultSkin::cachePathFor(
            uuid, QStringLiteral("1.20.1"),
            QStringLiteral("assets/minecraft/textures/entity/player/slim/alex.png"));
        const QString old = DefaultSkin::cachePathFor(
            uuid, QStringLiteral("1.18.2"), QStringLiteral("assets/minecraft/textures/entity/alex.png"));
        check(QFileInfo(modern).absolutePath() == QDir::cleanPath(sandbox + QStringLiteral("/skins")),
              "ZF5 落在 <数据目录>/skins 底下（**只进缓存，不缝进资源**）",
              QFileInfo(modern).absolutePath());
        check(QFileInfo(modern).fileName() ==
                  QStringLiteral("default-f2de408889f93162b33450698f1c6a53-") +
                      QString::fromLatin1(QCryptographicHash::hash(QByteArrayLiteral("1.20.1"),
                                                                   QCryptographicHash::Md5)
                                              .toHex()
                                              .left(12)) +
                      QStringLiteral("-player-slim-alex.png"),
              "ZF5 名字里有账号键 + 版本键 + 条目别名三段",
              QFileInfo(modern).fileName());
        // 版本键那一段**必须有**：换到低版本算出来的是另一条路径的另一张图，
        // 没有它两次算出来的缓存会撞在同一个文件名上（旧那张会被当成"算过了"）。
        check(modern != old && old.endsWith(QStringLiteral("-alex.png")),
              "ZF5 换了版本 → 换一个文件名（老规矩那张的别名是 alex，不是同一个）", old);
        check(DefaultSkin::cachePathFor(QStringLiteral("不是uuid"), QStringLiteral("1.20.1"),
                                        QStringLiteral("assets/minecraft/textures/entity/alex.png"))
                      .isEmpty() &&
                  DefaultSkin::cachePathFor(uuid, QString(), QStringLiteral("x.png")).isEmpty(),
              "ZF5 账号认不出来 / 没选中版本 → 不拼路径（不拼一个野名字出来）");
    }

    // ---- ZF6 真 JAR：新规矩命中，而且**第二次不碰 JAR** ----
    {
        const QString playerName = QStringLiteral("Mine");  // 下标 0 → slim/alex
        const QByteArray png = makePngBytes(QColor(0x20, 0x80, 0xC0));
        const QString versionId = QStringLiteral("1.20.1");
        const QString jar = sandbox + QStringLiteral("/versions/") + versionId + QLatin1Char('/') +
                            versionId + QStringLiteral(".jar");
        const bool made =
            makeFakeJar(jar, {{QStringLiteral("assets/minecraft/textures/entity/player/slim/alex.png"),
                               png}});
        check(made, "ZF6 前提：假 JAR 造出来了（真 zip，条目名带斜杠）", jar);
        if (made) {
            QString path;
            bool slim = false;
            QString reason;
            const DefaultSkin::Result first =
                DefaultSkin::resolve(playerName, versionId, &path, &slim, &reason);
            check(first == DefaultSkin::Result::Resolved && slim && !path.isEmpty(),
                  "ZF6 新规矩那条从 JAR 里取到了，而且模型是窄的（下标 0）",
                  QStringLiteral("%1 / %2").arg(int(first)).arg(reason));
            // 取出来的**就是那张图**：不是"文件在那儿"就算数（尺寸和像素都量一遍）。
            const QImage written(path);
            check(!written.isNull() && written.size() == QSize(64, 64) &&
                      written.pixel(8, 8) == QColor(0x20, 0x80, 0xC0).rgba(),
                  "ZF6 落盘的那张图就是 JAR 里那张（64×64、像素值也对）",
                  QStringLiteral("%1 字节 / %2x%3")
                      .arg(QFileInfo(path).size())
                      .arg(written.width())
                      .arg(written.height()));

            // **把 JAR 整个删掉**再算一次。这一条是"缓存命中不碰 JAR"的真证据 ——
            // 按耗时去断言是不稳的，把源抽掉则是确定的。
            QDir(sandbox + QStringLiteral("/versions/") + versionId).removeRecursively();
            QString again, againReason;
            bool againSlim = false;
            const DefaultSkin::Result second =
                DefaultSkin::resolve(playerName, versionId, &again, &againSlim, &againReason);
            check(second == DefaultSkin::Result::Resolved && again == path && againSlim,
                  "ZF6 JAR 删掉之后照样算得出来（缓存命中 = 两次 QFile::exists，不起进程）",
                  againReason);
        }
    }

    // ---- ZF7 真 JAR：老规矩命中，而且换版本**不会**拿上一份缓存顶上 ----
    {
        const QString playerName = QStringLiteral("Mine");  // 老规矩：哈希偶数 → steve（宽）
        const QString versionId = QStringLiteral("1.18.2");
        const QString jar = sandbox + QStringLiteral("/versions/") + versionId + QLatin1Char('/') +
                            versionId + QStringLiteral(".jar");
        const bool made = makeFakeJar(
            jar, {{QStringLiteral("assets/minecraft/textures/entity/steve.png"),
                   makePngBytes(QColor(0x90, 0x60, 0x30))},
                  // 顺带放一个"新规矩那条路径"的条目，但**不是**这个玩家要的那一条
                  // （每个名字要哪一条是算出来的，所以这一条必须与他无关）。
                  {QStringLiteral("assets/minecraft/textures/entity/player/wide/zuri.png"),
                   makePngBytes(QColor(0xFF, 0x00, 0xFF))}});
        check(made, "ZF7 前提：老规矩那个假 JAR 造出来了", jar);
        if (made) {
            QString path;
            bool slim = true;
            QString reason;
            const DefaultSkin::Result result =
                DefaultSkin::resolve(playerName, versionId, &path, &slim, &reason);
            const QString modernPath = DefaultSkin::cachePathFor(
                AccountStore::offlineUuidFor(playerName), QStringLiteral("1.20.1"),
                QStringLiteral("assets/minecraft/textures/entity/player/slim/alex.png"));
            check(result == DefaultSkin::Result::Resolved && !slim &&
                      path.endsWith(QStringLiteral("-steve.png")),
                  "ZF7 新规矩那条取不到 → 换老规矩那条（steve，宽模型）",
                  QStringLiteral("%1 / %2").arg(path, reason));
            // 上一节那份现代的缓存**还在盘上**，但这一趟绝不能拿它顶上：它算的是另一个版本。
            check(QFile::exists(modernPath) && path != modernPath,
                  "ZF7 同一账号换到低版本 → 拿到的是低版本那张，上一份缓存还在但没被拿去顶");
            // 这一条把"判据是 JAR"钉死：这个 JAR 里**有一个**新规矩的条目（wide/zuri），
            // 但按名字算出来要的不是它 —— 判据是"有没有**这一条**"，不是"有没有新规矩的目录"。
            check(!path.endsWith(QStringLiteral("zuri.png")),
                  "ZF7 不是「JAR 里有新规矩的条目就算新规矩」：要的是**这个名字对应的那一条**");
        }
    }

    // ---- ZF8 取不到 / 坏掉，各是哪一种 ----
    {
        // ① 两条都没有（不是原版客户端：第三方安装器做的薄壳 JAR 就长这样）→ Unavailable，
        //    这是**常态**：调用方会退回"随机挑一张"，不报错。
        const QString emptyId = QStringLiteral("1.19.9-noskin");
        const QString emptyJar = sandbox + QStringLiteral("/versions/") + emptyId + QLatin1Char('/') +
                                 emptyId + QStringLiteral(".jar");
        const bool emptyMade =
            makeFakeJar(emptyJar, {{QStringLiteral("README.txt"), QByteArrayLiteral("nope")}});
        QString path;
        bool slim = false;
        QString reason;
        const DefaultSkin::Result none =
            DefaultSkin::resolve(QStringLiteral("Mine"), emptyId, &path, &slim, &reason);
        check(emptyMade && none == DefaultSkin::Result::Unavailable && path.isEmpty() &&
                  !reason.isEmpty(),
              "ZF8 JAR 里两条都没有 → Unavailable（**常态**：退回随机那张，不记日志不弹窗）", reason);

        // ② 没有选中版本 → Unavailable（用户一个版本都没装，或者正在装）。
        const DefaultSkin::Result noVersion =
            DefaultSkin::resolve(QStringLiteral("Mine"), QString(), &path, &slim, &reason);
        check(noVersion == DefaultSkin::Result::Unavailable && path.isEmpty(),
              "ZF8 没选中任何已安装版本 → Unavailable", reason);

        // ③ 那个 JAR 根本不是 zip（文件坏了 / 半截）→ Failed。和"没有这一条"分开：
        //    前者值得记一行日志，后者是常态。
        const QString brokenId = QStringLiteral("1.20.6-notzip");
        const QString brokenJar = sandbox + QStringLiteral("/versions/") + brokenId +
                                  QLatin1Char('/') + brokenId + QStringLiteral(".jar");
        QDir().mkpath(QFileInfo(brokenJar).absolutePath());
        bool brokenWritten = false;
        {
            QFile file(brokenJar);
            brokenWritten = file.open(QIODevice::WriteOnly);
            if (brokenWritten) {
                file.write(QByteArrayLiteral("这不是 zip"));
                file.close();
            }
        }
        const DefaultSkin::Result broken =
            DefaultSkin::resolve(QStringLiteral("Mine"), brokenId, &path, &slim, &reason);
        check(brokenWritten && broken == DefaultSkin::Result::Failed && path.isEmpty(),
              "ZF8 那个 JAR 打不开 → Failed（和「里面没有这一条」是两件事）", reason);
        // 那句话**不许是空的**：它最后会落成日志里那行「算离线默认皮肤失败：…」，而这句话
        // 的全部意义就是"怎么老是随机那张"有个交代。NotAnArchive 这一档 ZipUtil 不给
        // 原因（退出码 4 就是终点，连异常文字都没有），照抄就把那行日志留成一个悬空的冒号
        // —— 这一条正是为它写的（改之前这里 reason 就是空串）。
        check(broken != DefaultSkin::Result::Failed || !reason.trimmed().isEmpty(),
              "ZF8 而且 Failed 那句原因不能是空的（日志那行不许是个悬空的冒号）",
              QStringLiteral("「%1」").arg(reason));

        // ④ 条目在、但不是一张图 → Failed，而且**盘上不许留下东西**：写下去的话
        //    "文件存在"就等于"已经算好了"，那张坏图会永远躺在缓存里（每次开启动器都拿它
        //    解码、每次失败，而且再没有哪一趟来纠正它）。
        const QString badPngId = QStringLiteral("1.20.7-badpng");
        const QString badPngJar = sandbox + QStringLiteral("/versions/") + badPngId +
                                  QLatin1Char('/') + badPngId + QStringLiteral(".jar");
        const bool badMade = makeFakeJar(
            badPngJar, {{QStringLiteral("assets/minecraft/textures/entity/player/slim/alex.png"),
                         QByteArrayLiteral("<html>Just a moment...</html>")}});
        const DefaultSkin::Result badPng =
            DefaultSkin::resolve(QStringLiteral("Mine"), badPngId, &path, &slim, &reason);
        const QString badPath = DefaultSkin::cachePathFor(
            AccountStore::offlineUuidFor(QStringLiteral("Mine")), badPngId,
            QStringLiteral("assets/minecraft/textures/entity/player/slim/alex.png"));
        check(badMade && badPng == DefaultSkin::Result::Failed && !QFile::exists(badPath),
              "ZF8 那条不是 PNG → Failed，而且一个字都不落盘（坏图进了缓存就再也修不回来）",
              reason);
    }

    // 收拾自己造的东西：假版本目录 + 这个账号的缓存图。
    for (const QString &id : {QStringLiteral("1.20.1"), QStringLiteral("1.18.2"),
                              QStringLiteral("1.19.9-noskin"), QStringLiteral("1.20.6-notzip"),
                              QStringLiteral("1.20.7-badpng")}) {
        QDir(sandbox + QStringLiteral("/versions/") + id).removeRecursively();
    }
    for (const QString &entry : QDir(sandbox + QStringLiteral("/skins"))
                                    .entryList({QStringLiteral("default-*")}, QDir::Files)) {
        QFile::remove(sandbox + QStringLiteral("/skins/") + entry);
    }
    check(!QFile::exists(sandbox + QStringLiteral("/versions/1.20.1")),
          "ZF9 假版本目录收干净了（后面那些节扫的是同一份沙箱）");
}

/// 把 JSON 值压成一行字符串，用来做"逐字段相等"的比较。
/// QJsonObject 没有值语义的 ==，比较它们的 toJson 是同一件事，而且失败时能直接打印出来。
static QString flatJson(const QJsonValue &value) {
    if (value.isObject()) {
        return QString::fromUtf8(QJsonDocument(value.toObject()).toJson(QJsonDocument::Compact));
    }
    if (value.isArray()) {
        return QString::fromUtf8(QJsonDocument(value.toArray()).toJson(QJsonDocument::Compact));
    }
    return value.toString();
}

// ---------------------------------------------------------------------------
// U. 带模组加载器的版本：inheritsFrom 的合并、主类、maven 风格的库
//
// 两个 fixture 都是**真货**：1.19.json 是 Mojang 的元数据，fabric-loader-0.19.5-1.19.json
// 是 meta.fabricmc.net 给的 profile json（原样存下来，一个字没改）。用真数据是因为
// "薄 json"的那些特征（没有 jar、没有 assetIndex、库只有 name+url）正是这节要证的东西，
// 自造的假 json 只会证回我自己以为的格式。
// ---------------------------------------------------------------------------
static void runLoaderInheritanceTests(const QString &sandbox) {
    section("U. 加载器版本的继承（inheritsFrom 合并 / 主类 / maven 库）");

    const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";
    const QJsonObject vanilla = loadJson(metaDir + "/1.19.json");
    const QJsonObject loader = loadJson(metaDir + "/fabric-loader-0.19.5-1.19.json");
    check(!vanilla.isEmpty() && !loader.isEmpty(), "两份 fixture 都读到了");
    if (vanilla.isEmpty() || loader.isEmpty()) {
        return;
    }

    const QString loaderId = loader[QStringLiteral("id")].toString();
    const QJsonArray vanillaLibs = vanilla[QStringLiteral("libraries")].toArray();
    const QJsonArray loaderLibs = loader[QStringLiteral("libraries")].toArray();

    // --- U1. 先钉住"这份 profile 确实是薄的" -------------------------------------
    // 这几条同时是后面所有断言的前提：合并要是没做事，下面每一条都会红。
    check(VersionInheritance::parentIdOf(loader) == vanilla[QStringLiteral("id")].toString(),
          "U1 Fabric profile 的 inheritsFrom 指向原版",
          VersionInheritance::parentIdOf(loader));
    check(VersionInheritance::parentIdOf(vanilla).isEmpty(), "U1 原版的 json 没有 inheritsFrom");
    check(!loader.contains(QStringLiteral("downloads")) &&
              !loader.contains(QStringLiteral("assetIndex")) &&
              !loader.contains(QStringLiteral("javaVersion")) &&
              !loader.contains(QStringLiteral("logging")),
          "U1 Fabric profile 里没有 jar/assetIndex/javaVersion/logging（都是继承来的）");
    check(!loader[QStringLiteral("mainClass")].toString().isEmpty() &&
              loader[QStringLiteral("mainClass")].toString() !=
                  vanilla[QStringLiteral("mainClass")].toString(),
          "U1 主类跟原版不一样（否则「主类从 json 读」这件事根本验不出来）");
    check(loaderLibs.size() == 8, "U1 Fabric profile 有 8 个库", QString::number(loaderLibs.size()));

    int mavenStyle = 0;
    for (const QJsonValue &v : loaderLibs) {
        const QJsonObject lib = v.toObject();
        if (lib[QStringLiteral("downloads")].toObject().isEmpty() &&
            !lib[QStringLiteral("name")].toString().isEmpty() &&
            !lib[QStringLiteral("url")].toString().isEmpty()) {
            ++mavenStyle;
        }
    }
    check(mavenStyle == loaderLibs.size(), "U1 这 8 个库全是「只有 name+url」的 maven 风格",
          QString::number(mavenStyle));

    // --- U2. 纯合并 -------------------------------------------------------------
    section("U2. VersionInheritance::merge（父在前、子覆盖）");
    const QJsonObject merged = VersionInheritance::merge(loader, vanilla);

    check(merged[QStringLiteral("id")].toString() == loaderId, "U2 id 用子的",
          merged[QStringLiteral("id")].toString());
    check(!merged.contains(QStringLiteral("inheritsFrom")) &&
              VersionInheritance::parentIdOf(merged).isEmpty(),
          "U2 结果里没有 inheritsFrom（合完就不该再往上指，否则链会重复走）");
    check(merged[QStringLiteral("mainClass")].toString() ==
              loader[QStringLiteral("mainClass")].toString(),
          "U2 mainClass 用子的（KnotClient）",
          merged[QStringLiteral("mainClass")].toString());
    check(flatJson(merged[QStringLiteral("assetIndex")]) ==
              flatJson(vanilla[QStringLiteral("assetIndex")]),
          "U2 assetIndex 从父版本继承");
    check(flatJson(merged[QStringLiteral("javaVersion")]) ==
              flatJson(vanilla[QStringLiteral("javaVersion")]),
          "U2 javaVersion 从父版本继承（决定拿哪个 Java 跑）");
    check(flatJson(merged[QStringLiteral("downloads")]) ==
              flatJson(vanilla[QStringLiteral("downloads")]),
          "U2 downloads 从父版本继承（客户端 jar 的地址/哈希）");
    check(flatJson(merged[QStringLiteral("logging")]) ==
              flatJson(vanilla[QStringLiteral("logging")]),
          "U2 logging 从父版本继承（少了它游戏起不来）");

    // 这条是上面那条的另一半：子**声明了**这个键，哪怕值是空对象也是子赢（不回退到父的）。
    // 真数据里就有这一号 —— Forge 装出来的 profile 写着 `"logging": {}`，用意正是把原版
    // 那份 log4j 配置清掉，官方启动器的合并同样是"子赢"。只有 null / 根本没有这个键才
    // 算"没写"。**判据不能写成"logging 必须非空"**：2026-09-22 就是这条把真装的断言顶红
    // 的（当时还怀疑是 merge 丢了键，其实数据里就是空对象）。
    {
        QJsonObject childClearingLogging = loader;
        childClearingLogging.insert(QStringLiteral("logging"), QJsonObject());
        const QJsonObject mergedCleared =
            VersionInheritance::merge(childClearingLogging, vanilla);
        check(mergedCleared.contains(QStringLiteral("logging")) &&
                  flatJson(mergedCleared[QStringLiteral("logging")]) ==
                      flatJson(QJsonObject()),
              "U2 子写了空对象也算声明了（Forge 的 logging:{} 就是这么清掉原版那份的）",
              flatJson(mergedCleared[QStringLiteral("logging")]));
    }

    // 上面那条的前提是"父那份自己没有 inheritsFrom"（真数据里父就是原版，它不指别人）。
    // 父自己也指着上一级那种（子 → 父 → 祖父）才是会漏的那个形状：`out = parent` 会把
    // 父的 inheritsFrom 一起抄过来，于是合出来的这份 json 还指着祖父 —— 读它的人
    // （启动参数展开、classpath 拼接）会再去找祖父合一遍，多走一层。合完就是**什么都不缺**
    // 的一份，那个字段一条都不该留（2026-09-25 修）。
    {
        QJsonObject chainedParent = vanilla;
        chainedParent.insert(QStringLiteral("inheritsFrom"), QStringLiteral("1.19.2"));
        const QJsonObject mergedChain = VersionInheritance::merge(loader, chainedParent);
        check(!mergedChain.contains(QStringLiteral("inheritsFrom")) &&
                  VersionInheritance::parentIdOf(mergedChain).isEmpty(),
              "U2 父那一份自己也写着 inheritsFrom 时，结果里同样一条都不留",
              VersionInheritance::parentIdOf(mergedChain));
    }

    // 库：父的全部在，子的全在，按 name 去重、子赢、且**留在父原来的位置上**
    {
        QSet<QString> names;
        for (const QJsonValue &v : vanillaLibs) {
            names.insert(v.toObject()[QStringLiteral("name")].toString());
        }
        const int parentOnly = names.size();
        for (const QJsonValue &v : loaderLibs) {
            names.insert(v.toObject()[QStringLiteral("name")].toString());
        }
        const QJsonArray mergedLibs = merged[QStringLiteral("libraries")].toArray();
        check(mergedLibs.size() == names.size(), "U2 库是两边名字的并集（没有重复）",
              QString("%1 vs %2").arg(mergedLibs.size()).arg(names.size()));

        // 前 parentOnly 条逐条等于父的（原版原顺序，一位不差）
        bool prefixSame = mergedLibs.size() >= vanillaLibs.size();
        for (int i = 0; prefixSame && i < vanillaLibs.size(); ++i) {
            prefixSame = flatJson(mergedLibs.at(i)) == flatJson(vanillaLibs.at(i));
        }
        check(prefixSame, "U2 父的库原顺序铺在前面");

        bool childPresent = true;
        for (const QJsonValue &v : loaderLibs) {
            const QString name = v.toObject()[QStringLiteral("name")].toString();
            bool found = false;
            for (const QJsonValue &m : mergedLibs) {
                if (m.toObject()[QStringLiteral("name")].toString() == name) {
                    found = flatJson(m) == flatJson(v);  // 子赢：值也是子的
                    break;
                }
            }
            if (!found) {
                childPresent = false;
                out() << "        缺/被顶掉: " << name << "\n";
            }
        }
        check(childPresent, "U2 子的 8 个库全在，且值用的是子的那份");
        check(parentOnly == vanillaLibs.size(), "U2 原版 1.19 的 88 个库名字本来就互不相同",
              QString::number(parentOnly));
    }

    // 覆盖语义的合成用例：同名库要"子赢 + 留在父的位置上"，不能挪到队尾
    {
        const QJsonObject parentJson = QJsonDocument::fromJson(R"JSON({
            "id": "P", "mainClass": "p.Main",
            "libraries": [
                {"name": "g:same:1.0", "downloads": {"artifact": {"path": "old/same.jar"}}},
                {"name": "g:onlyParent:1.0", "downloads": {"artifact": {"path": "old/only.jar"}}}
            ]
        })JSON").object();
        // 去重是**按 name 全串**做的（Mojang 那边也是：name 就是坐标，带版本号），
        // 所以要验"覆盖"就必须两边写成一模一样的 name。
        const QJsonObject childJson = QJsonDocument::fromJson(R"JSON({
            "id": "C", "inheritsFrom": "P", "mainClass": "c.Main",
            "libraries": [
                {"name": "g:same:1.0", "url": "https://example.invalid/", "sha1": "beef"},
                {"name": "g:onlyChild:1.0", "url": "https://example.invalid/", "sha1": "cafe"}
            ]
        })JSON").object();
        const QJsonArray libs = VersionInheritance::merge(childJson, parentJson)
                                    [QStringLiteral("libraries")].toArray();
        check(libs.size() == 3, "U2 同名库被顶掉、不同名的都在", QString::number(libs.size()));
        check(libs.at(0).toObject()[QStringLiteral("sha1")].toString() == QStringLiteral("beef"),
              "U2 被覆盖的库留在**父原来的位置**、值是子的（挪到队尾会改变 classpath 里谁盖住谁）",
              libs.at(0).toObject()[QStringLiteral("sha1")].toString());
        check(libs.at(1).toObject()[QStringLiteral("name")].toString() ==
                  QStringLiteral("g:onlyParent:1.0"),
              "U2 父独有的库留在原位置");
        check(libs.at(2).toObject()[QStringLiteral("name")].toString() ==
                  QStringLiteral("g:onlyChild:1.0"),
              "U2 子独有的库接在最后");
    }

    // arguments：jvm/game 都是"父在前、子在后"，而且**不拆分**那一整条 argv
    {
        const QJsonArray parentJvm = vanilla[QStringLiteral("arguments")]
                                         .toObject()[QStringLiteral("jvm")].toArray();
        const QJsonArray childJvm = loader[QStringLiteral("arguments")]
                                        .toObject()[QStringLiteral("jvm")].toArray();
        const QJsonArray jvm = merged[QStringLiteral("arguments")]
                                   .toObject()[QStringLiteral("jvm")].toArray();
        check(jvm.size() == parentJvm.size() + childJvm.size(),
              "U2 arguments.jvm 是两边拼起来的（父在前）",
              QString::number(jvm.size()));
        bool jvmPrefix = jvm.size() >= parentJvm.size();
        for (int i = 0; jvmPrefix && i < parentJvm.size(); ++i) {
            jvmPrefix = flatJson(jvm.at(i)) == flatJson(parentJvm.at(i));
        }
        check(jvmPrefix, "U2 父的 jvm 参数在前面（手写的规则对象也原样带着）");
        check(jvm.size() > 0 && jvm.last().toString() == childJvm.first().toString() &&
                  jvm.last().toString().contains(QStringLiteral("-DFabricMcEmu=")),
              "U2 子的 -DFabricMcEmu 那一行在**最后**（要盖住原版主类就得后写）",
              jvm.last().toString());

        const QJsonArray game = merged[QStringLiteral("arguments")]
                                    .toObject()[QStringLiteral("game")].toArray();
        check(flatJson(game) == flatJson(vanilla[QStringLiteral("arguments")]
                                             .toObject()[QStringLiteral("game")]),
              "U2 arguments.game 原样继承（子的 game 是空数组，不能把父的顶掉）",
              QString::number(game.size()));
    }

    // complianceLevel / minimumLauncherVersion 取大的
    {
        const int compliance = qMax(vanilla[QStringLiteral("complianceLevel")].toInt(),
                                    loader[QStringLiteral("complianceLevel")].toInt());
        const int minLauncher = qMax(vanilla[QStringLiteral("minimumLauncherVersion")].toInt(),
                                     loader[QStringLiteral("minimumLauncherVersion")].toInt());
        check(merged[QStringLiteral("complianceLevel")].toInt() == compliance,
              "U2 complianceLevel 取大的",
              QString::number(merged[QStringLiteral("complianceLevel")].toInt()));
        check(merged[QStringLiteral("minimumLauncherVersion")].toInt() == minLauncher,
              "U2 minimumLauncherVersion 取大的",
              QString::number(merged[QStringLiteral("minimumLauncherVersion")].toInt()));
    }
    check(VersionInheritance::merge(loader, vanilla).size() == merged.size(),
          "U2 合并是纯函数（同样的输入再来一次，结果一样大）");

    // --- U3. 合并后的 json 拿去启动 -------------------------------------------------
    section("U3. 合并后的 json 走启动路径（主类 / classpath）");
    {
        GlobalJavaSettings s;
        LauncherManager launcher;
        const QStringList args = launcher.generateJvmArguments(
            QString(), loaderId, QStringLiteral("1"), merged, s, true, 17);

        const int cpIndex = args.indexOf(QStringLiteral("-cp"));
        const QStringList cp = cpIndex >= 0
                                   ? args.at(cpIndex + 1).split(QLatin1Char(';'), Qt::SkipEmptyParts)
                                   : QStringList();
        check(cpIndex >= 0 && cpIndex + 2 < args.size(), "U3 参数里有 -cp 和主类");
        check(cpIndex + 2 < args.size() &&
                  args.at(cpIndex + 2) == loader[QStringLiteral("mainClass")].toString(),
              "U3 主类是 KnotClient（从 json 读，不是写死的 net.minecraft.client.main.Main）",
              cpIndex + 2 < args.size() ? args.at(cpIndex + 2) : QString());

        bool emuKept = false;
        for (const QString &a : args) {
            if (a == QStringLiteral("-DFabricMcEmu= net.minecraft.client.main.Main ")) {
                emuKept = true;
            }
        }
        check(emuKept, "U3 -DFabricMcEmu 那一行是**一个** argv 元素（带空格也没被拆开）");

        // 加载器的 8 个库必须都在 classpath 上（maven 风格，没有 downloads.artifact）
        int libsOnCp = 0;
        for (const QJsonValue &v : loaderLibs) {
            const QJsonObject lib = v.toObject();
            const QString path = LibraryRules::mavenPathForName(lib[QStringLiteral("name")].toString());
            const QString want = absoluteMcPath(QStringLiteral("libraries/%1").arg(path));
            if (!path.isEmpty() && cp.contains(want)) {
                ++libsOnCp;
            } else {
                out() << "        不在 classpath 上: " << lib[QStringLiteral("name")].toString()
                      << " -> " << path << "\n";
            }
        }
        check(libsOnCp == loaderLibs.size(),
              "U3 加载器的 8 个库都在 classpath 上（不然 NoClassDefFoundError）",
              QString("%1/%2").arg(libsOnCp).arg(loaderLibs.size()));

        // 原版的库也必须在（加载器是"套在"原版上的，两边都要）
        int vanillaOnCp = 0;
        for (const QJsonValue &v : vanillaLibs) {
            const QJsonObject lib = v.toObject();
            if (!LibraryRules::libraryAllowed(lib)) {
                continue;
            }
            const QString path = LibraryRules::artifactFor(lib).path;
            if (!path.isEmpty() &&
                cp.contains(absoluteMcPath(QStringLiteral("libraries/%1").arg(path)))) {
                ++vanillaOnCp;
            }
        }
        check(vanillaOnCp > 50, "U3 原版的库也照样在 classpath 上（两边都不少）",
              QString::number(vanillaOnCp));

        // 客户端 jar 的路径：加载器目录里没有 jar，所以这里拼出来的是**原版那个目录**
        // 底下那个 jar —— 这一段是 launch 模式的真正风险点（找不到就 "Could not find
        // or load main class"）。
        check(!cp.isEmpty() &&
                  cp.first() == absoluteMcPath(InstanceFiles::jarRelativePath(loaderId)),
              "U3 classpath 第一条走 InstanceFiles::jarRelativePath（绝对化之后）",
              cp.isEmpty() ? QString() : cp.first());
    }

    // --- U4. DownloadManager 认得出 maven 风格的库 ---------------------------------
    section("U4. maven 风格的库（只有 name + url）");
    {
        DownloadManager dm;
        const QList<Library> picked = dm.extractLibraries(loader);
        check(picked.size() == loaderLibs.size(), "U4 8 个库一个不少地被选中（改之前是 0 个）",
              QString::number(picked.size()));

        int withUrl = 0;
        int withSha1 = 0;
        bool insideLibraries = true;
        for (const Library &lib : picked) {
            if (lib.url.startsWith(QStringLiteral("https://maven.fabricmc.net/")) &&
                lib.url.endsWith(QLatin1Char('/') + QFileInfo(lib.path).fileName())) {
                ++withUrl;
            }
            if (!lib.sha1.isEmpty() && lib.size > 0) {
                ++withSha1;
            }
            if (lib.path.contains(QStringLiteral("..")) || lib.path.startsWith(QLatin1Char('/'))) {
                insideLibraries = false;
            }
        }
        check(withUrl == picked.size(), "U4 每条的地址都是 maven 仓库 + 拼出来的路径",
              QString::number(withUrl));
        // 最后两个（intermediary / fabric-loader）本来就没有 sha1，所以只能断言"给了的都在"
        check(withSha1 == 6, "U4 给了 sha1 的 6 个都带上了校验信息（能校验的还是校验）",
              QString::number(withSha1));
        check(insideLibraries, "U4 路径都在 libraries/ 里面（没有 ../ 越界）");

        // 每条的路径都必须等于"用它自己的 name 现算一遍"的结果
        bool mavenPathOk = true;
        for (const Library &lib : picked) {
            if (lib.path != LibraryRules::mavenPathForName(lib.name)) {
                mavenPathOk = false;
                out() << "        路径不对: " << lib.name << " -> " << lib.path << "\n";
            }
        }
        check(mavenPathOk, "U4 每条的 path 都是按它自己的坐标拼出来的");
        bool hasAsm = false;
        for (const Library &lib : picked) {
            if (lib.path == QStringLiteral("org/ow2/asm/asm/9.10.1/asm-9.10.1.jar")) {
                hasAsm = true;
            }
        }
        check(hasAsm, "U4 坐标拼出来的路径正确（org.ow2.asm:asm:9.10.1 那个）");
    }

    // 坐标 -> 路径的纯函数真值表（含"脏名字一律拒绝"）
    {
        // 三段（没有 classifier）是**最常见**的形状，7/8 个 Fabric 坐标都是它 ——
        // 这条曾经红过：白名单循环把"空的 classifier"也当成脏段，于是每一个不带
        // classifier 的坐标都解析失败（库全被静默丢掉）。留着当回归钉子。
        check(LibraryRules::mavenPathForName(QStringLiteral("net.fabricmc:fabric-loader:0.19.5")) ==
                  QStringLiteral("net/fabricmc/fabric-loader/0.19.5/fabric-loader-0.19.5.jar"),
              "U4 坐标 -> maven 路径（三段、没有 classifier）");
        check(LibraryRules::mavenPathForName(
                  QStringLiteral("org.lwjgl:lwjgl:3.3.1:natives-windows")) ==
                  QStringLiteral("org/lwjgl/lwjgl/3.3.1/lwjgl-3.3.1-natives-windows.jar"),
              "U4 带 classifier 的坐标");
        check(LibraryRules::mavenPathForName(QStringLiteral("net.fabricmc:intermediary:1.19@zip")) ==
                  QStringLiteral("net/fabricmc/intermediary/1.19/intermediary-1.19.zip"),
              "U4 @扩展名照收");
        // 版本号里的 `+` 是 Fabric 真在用的（sponge-mixin），白名单漏了它这个库就没了
        check(LibraryRules::mavenPathForName(
                  QStringLiteral("net.fabricmc:sponge-mixin:0.17.4+mixin.0.8.7")) ==
                  QStringLiteral("net/fabricmc/sponge-mixin/0.17.4+mixin.0.8.7/"
                                 "sponge-mixin-0.17.4+mixin.0.8.7.jar"),
              "U4 版本号里的 + 照收（Maven 允许，Fabric 真的在用）");
        check(LibraryRules::mavenPathForName(QStringLiteral("../../evil:pwn:1.0")).isEmpty(),
              "U4 group 里带 ../ 的坐标直接拒绝（拼出来会写到 libraries/ 外面去）");
        check(LibraryRules::mavenPathForName(QStringLiteral("g:a")).isEmpty(),
              "U4 段数不够的坐标拒绝");
        check(LibraryRules::mavenPathForName(QStringLiteral("g:a:1:bad name")).isEmpty(),
              "U4 段里有空格（白名单外的字符）也拒绝");
        check(LibraryRules::mavenPathForName(QStringLiteral("g:a:1:2:3")) ==
                  QStringLiteral("g/a/1/a-1-2.jar"),
              "U4 第 5 段往后当作不存在（maven 没有那种形式）");

        // 坏名字不能变成"幽灵下载条目"
        const QJsonObject evil = QJsonDocument::fromJson(R"JSON({
            "libraries": [
                {"name": "../../evil:pwn:1.0", "url": "https://example.invalid/"},
                {"name": "g:good:1.0", "url": "https://example.invalid/"}
            ]
        })JSON").object();
        DownloadManager dm;
        const QList<Library> picked = dm.extractLibraries(evil);
        check(picked.size() == 1 && picked.first().name == QStringLiteral("g:good:1.0"),
              "U4 坏坐标被丢掉、好坐标照收", QString::number(picked.size()));
    }

    // --- U5. 真磁盘：VersionManager 顺着链合并，坏链要说得清 ------------------------
    section("U5. 真磁盘上的继承链（VersionManager / InstanceFiles）");
    {
        const QString versionsRoot = sandbox + "/versions";
        const QString parentId = QStringLiteral("U段-父");
        const QString childId = QStringLiteral("U段-加载器");
        const QString orphanId = QStringLiteral("U段-孤儿");
        const QString ringA = QStringLiteral("U段-环A");
        const QString ringB = QStringLiteral("U段-环B");
        const QString missingId = QStringLiteral("U段-没有这个");

        const auto writeJson = [&](const QString &id, const QJsonObject &json) {
            QDir().mkpath(versionsRoot + "/" + id);
            writeFileAt(versionsRoot + "/" + id + "/" + id + ".json",
                        QJsonDocument(json).toJson(QJsonDocument::Indented));
        };

        // 父版本：目录里有 jar，而且**名字不是 id**（外部改过名的实例）
        QDir().mkpath(versionsRoot + "/" + parentId);
        writeJson(parentId, vanilla);
        {
            QFile jar(versionsRoot + "/" + parentId + "/真名.jar");
            if (jar.open(QIODevice::WriteOnly)) {
                jar.write("dummy");
                jar.close();
            }
        }

        // 加载器版本：目录里**只有一份 json**，inheritsFrom 指向那个改过名的父版本
        QJsonObject child = loader;
        child[QStringLiteral("id")] = childId;
        child[QStringLiteral("inheritsFrom")] = parentId;
        writeJson(childId, child);

        VersionManager vm;
        const QJsonObject diskMerged = vm.getVersionJson(childId);
        check(diskMerged[QStringLiteral("mainClass")].toString() ==
                  loader[QStringLiteral("mainClass")].toString(),
              "U5 getVersionJson 返回的是合并结果（主类是 KnotClient）",
              diskMerged[QStringLiteral("mainClass")].toString());
        check(diskMerged[QStringLiteral("libraries")].toArray().size() ==
                  vanillaLibs.size() + loaderLibs.size(),
              "U5 合并结果里两边库都在",
              QString::number(diskMerged[QStringLiteral("libraries")].toArray().size()));
        check(flatJson(diskMerged[QStringLiteral("assetIndex")]) ==
                  flatJson(vanilla[QStringLiteral("assetIndex")]),
              "U5 原版那份 assetIndex 也合进来了");
        check(!diskMerged.contains(QStringLiteral("inheritsFrom")),
              "U5 合并结果里没有 inheritsFrom");
        check(vm.inheritanceProblem(childId).isEmpty(),
              "U5 这条链本身没问题（inheritanceProblem 为空）", vm.inheritanceProblem(childId));

        // 加载器目录里没有 jar，客户端 jar 在原版那个（被改过名的）目录里
        check(InstanceFiles::jarOwnerId(childId) == parentId,
              "U5 jar 归属找到父版本", InstanceFiles::jarOwnerId(childId));
        check(InstanceFiles::jarRelativePath(childId) ==
                  QStringLiteral("versions/%1/真名.jar").arg(parentId),
              "U5 classpath 指向的是父版本目录里那个 jar",
              InstanceFiles::jarRelativePath(childId));
        {
            GlobalJavaSettings s;
            LauncherManager launcher;
            const QStringList args = launcher.generateJvmArguments(
                QString(), childId, QStringLiteral("1"), diskMerged, s, true, 17);
            const int cpIndex = args.indexOf(QStringLiteral("-cp"));
            const QStringList cp =
                cpIndex >= 0 ? args.at(cpIndex + 1).split(QLatin1Char(';'), Qt::SkipEmptyParts)
                             : QStringList();
            check(!cp.isEmpty() &&
                      cp.first() == absoluteMcPath(InstanceFiles::jarRelativePath(childId)),
                  "U5 「装了加载器、jar 在原版那边」这条链拼得出真的 classpath",
                  cp.isEmpty() ? QString() : cp.first());
            check(cpIndex >= 0 &&
                      cp.contains(absoluteMcPath(
                          QStringLiteral("libraries/org/ow2/asm/asm/9.10.1/asm-9.10.1.jar"))),
                  "U5 加载器的库也在同一条 classpath 上");
        }

        // 父版本没装：必须说"请先安装原版「X」"，而不是"重新下载这个版本"
        const QString orphanProblem = vm.inheritanceProblem(orphanId);
        writeJson(orphanId, [&] {
            QJsonObject j = loader;
            j[QStringLiteral("id")] = orphanId;
            j[QStringLiteral("inheritsFrom")] = missingId;
            return j;
        }());
        const QString problem = vm.inheritanceProblem(orphanId);
        check(!problem.isEmpty(), "U5 父版本没装 -> inheritanceProblem 非空");
        check(problem.contains(missingId), "U5 那句话点名了缺的是哪个版本", problem);
        check(orphanProblem.isEmpty(), "U5 没写 inheritsFrom 之前是没问题的（对照）");
        // 合并只能给出"合不完整的那一份"，但不能崩、也不能返回空
        VersionManager vmOrphan;
        const QJsonObject orphanMerged = vmOrphan.getVersionJson(orphanId);
        check(!orphanMerged.isEmpty() &&
                  orphanMerged[QStringLiteral("mainClass")].toString() ==
                      loader[QStringLiteral("mainClass")].toString(),
              "U5 父版本缺失时 getVersionJson 交出自己能给的那份（不是空）");
        check(orphanMerged[QStringLiteral("libraries")].toArray().size() == loaderLibs.size(),
              "U5 父版本缺失时只有加载器自己的库");

        // 成环：A -> B -> A
        {
            QJsonObject a = loader;
            a[QStringLiteral("id")] = ringA;
            a[QStringLiteral("inheritsFrom")] = ringB;
            QJsonObject b = vanilla;
            b[QStringLiteral("id")] = ringB;
            b[QStringLiteral("inheritsFrom")] = ringA;
            writeJson(ringA, a);
            writeJson(ringB, b);

            VersionManager vmRing;
            const QJsonObject ringMerged = vmRing.getVersionJson(ringA);
            check(!ringMerged.isEmpty(), "U5 成环时 getVersionJson 也会返回（不挂死）");
            const QString ringProblem = vmRing.inheritanceProblem(ringA);
            check(!ringProblem.isEmpty() && ringProblem.contains(QStringLiteral("环")),
                  "U5 成环 -> inheritanceProblem 说是环", ringProblem);
        }

        // 链太长：18 层
        {
            const int chainLength = VersionInheritance::maxDepth() + 2;
            for (int i = chainLength - 1; i >= 0; --i) {
                QJsonObject j = loader;
                j[QStringLiteral("id")] = QStringLiteral("U段-链%1").arg(i);
                if (i + 1 < chainLength) {
                    j[QStringLiteral("inheritsFrom")] = QStringLiteral("U段-链%1").arg(i + 1);
                } else {
                    j.remove(QStringLiteral("inheritsFrom"));
                }
                writeJson(QStringLiteral("U段-链%1").arg(i), j);
            }
            VersionManager vmChain;
            const QJsonObject chainMerged = vmChain.getVersionJson(QStringLiteral("U段-链0"));
            check(!chainMerged.isEmpty(), "U5 链太长时也会返回（不挂死）");
            const QString chainProblem = vmChain.inheritanceProblem(QStringLiteral("U段-链0"));
            check(!chainProblem.isEmpty() && chainProblem.contains(QStringLiteral("长")),
                  "U5 超过 maxDepth 的链 -> inheritanceProblem 说链太长", chainProblem);
            check(vmChain.inheritanceProblem(QStringLiteral("U段-链%1").arg(chainLength - 1)).isEmpty(),
                  "U5 链尾自己没问题（对照，说明上面那条不是因为别的原因）");
        }

        // 收摊：把这一节建的目录全删掉，后面的用例/扫描看到的还是干净的沙箱
        for (const QString &id : {parentId, childId, orphanId, ringA, ringB}) {
            QDir(versionsRoot + "/" + id).removeRecursively();
        }
        for (int i = 0; i < VersionInheritance::maxDepth() + 2; ++i) {
            QDir(versionsRoot + QStringLiteral("/U段-链%1").arg(i)).removeRecursively();
        }
        check(!QDir(versionsRoot).exists() || !QDir(versionsRoot).entryList(QDir::Dirs)
                                                   .filter(QStringLiteral("U段")).size(),
              "U5 沙箱恢复原样（这一节建的目录都删了）");
    }
}

// ---------------------------------------------------------------------------
// V. 加载器安装：地址怎么拼、列表里怎么挑、profile 能不能装、界面下标怎么翻
//
// 这一节整节**离线**。真正发请求的那两条路在这一节里跑不起来：Fabric 那条要真下几 MB
// 的库、Forge/NeoForge 那条要真起一个 Java 进程装一百秒，沙箱里都没法替。所以把"决定"
// 和"发请求"拆开：所有决定（LoaderMeta 里的纯函数、VersionManager 里的下标翻译）都在
// 这一节钉住；"真发请求那一次"是 `loader-install` 那个**联网**模式（见下面那一段），
// 不进默认模式。
//
// 这一节里的数据全部是**真数据**（tests/meta/ 下那几份原样存下来的）：
//   fabric-loader-0.19.5-1.19.json    meta.fabricmc.net 的 profile
//   forge-promotions_slim.json        files.minecraftforge.net 的推广版本表
//   neoforge-maven-metadata.xml       maven.neoforged.net 的全部 1716 个版本号
//   optifine-downloads.html           optifine.net/downloads 整页 203 KB（53 个游戏版本一节）
//   optifine-1.18.2-list.json         bmclapi2 的 /optifine/1.18.2（11 条，正式版和预览版混排）
//   optifine-adloadx.html             optifine.net/adloadx?f=… 的广告页（那条带 token 的链接）
//   forge-promotions_slim_mirror.json **镜像（BMCLAPI）**那份 Forge 推广表 —— 2026-09-22
//                                     实测是个旧文件（1782 B / 29 个游戏版本，最新停在
//                                     1.15.2），用户报的"每个版本都没有 Forge 支持"就是从
//                                     它来的
//   installer-help-legacy-1.8.9.txt   Forge 1.8.9 安装器（11.15.1.2318）的 `--help` 原样
//   installer-help-neoforge-26.2.txt  NeoForge 26.2 安装器的 `--help` 原样
//   neoforge-26.2.0.88.json           NeoForge 安装器写出来的那份 profile 原样（它的
//                                     arguments.game 里就是启动崩溃缺的那三个 --fml.*）
// 挑版本的规则、id 的格式、inheritsFrom 长什么样，都不许靠我自己的样例来证 —— U 节那次
// 已经吃过"自造 json 永远抓不到真数据里的 `+`"的亏。
//
// NOTE: NeoForge 那几条尤其只能拿真数据验：`<versions>` 是**按发布时间排的**（实测那份的
//       末尾是 `21.1.251, 26.3.0.8-beta` —— 一个给旧版本补发的正式版夹在一堆快照中间），
//       自造的"排序好的"样例会把"取最后一个"这种错做法验成绿的。
// ---------------------------------------------------------------------------
static void runLoaderInstallTests() {
    section("V. 加载器安装（纯函数：地址 / 挑版本 / profile 检查 / 下标翻译）");

    const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";
    const QJsonObject loaderProfile = loadJson(metaDir + "/fabric-loader-0.19.5-1.19.json");
    check(!loaderProfile.isEmpty(), "V 真 profile fixture 读到了");
    if (loaderProfile.isEmpty()) {
        return;
    }

    // --- V1. 地址怎么拼 ---------------------------------------------------------
    check(LoaderMeta::fabricLoaderListUrl(QStringLiteral("1.19")) ==
              QStringLiteral("https://meta.fabricmc.net/v2/versions/loader/1.19"),
          "V1 加载器列表的地址",
          LoaderMeta::fabricLoaderListUrl(QStringLiteral("1.19")));
    check(LoaderMeta::fabricProfileUrl(QStringLiteral("1.19"), QStringLiteral("0.19.5")) ==
              QStringLiteral(
                  "https://meta.fabricmc.net/v2/versions/loader/1.19/0.19.5/profile/json"),
          "V1 profile 的地址",
          LoaderMeta::fabricProfileUrl(QStringLiteral("1.19"), QStringLiteral("0.19.5")));
    check(LoaderMeta::fabricLoaderId(QStringLiteral("1.19"), QStringLiteral("0.19.5")) ==
              QStringLiteral("fabric-loader-0.19.5-1.19"),
          "V1 版本 id 是 fabric-loader-<加载器>-<游戏>",
          LoaderMeta::fabricLoaderId(QStringLiteral("1.19"), QStringLiteral("0.19.5")));
    check(!LoaderMeta::fabricMetaBase().endsWith(QLatin1Char('/')),
          "V1 根地址不带结尾的斜杠（拼出来不会出现双斜杠）");

    // --- V2. 列表里挑哪一个 -----------------------------------------------------
    // 列表的形状照实测来：**按新到旧排**，而且只有最新那条的 stable 是 true。
    const auto entry = [](const QString &version, bool stable) {
        const QJsonObject loader{{QStringLiteral("version"), version},
                                 {QStringLiteral("stable"), stable}};
        return QJsonObject{{QStringLiteral("loader"), loader}};
    };
    {
        // 实测的形状：第一条就是 stable。
        const QJsonArray realShaped{entry(QStringLiteral("0.19.5"), true),
                                    entry(QStringLiteral("0.19.4"), false),
                                    entry(QStringLiteral("0.19.3"), false)};
        const LoaderMeta::LoaderPick pick = LoaderMeta::pickFabricLoader(realShaped);
        check(pick.ok() && pick.version == QStringLiteral("0.19.5") && pick.stable,
              "V2 实测形状（最新那条是 stable）-> 挑最新那条", pick.version);

        // 有更新的非 stable 在前面时，仍然挑 stable 那条（版本号比较不是我们判断的事，
        // 但"优先正式版"是）。挑错这条的表现是"装上一个 corner 版本"。
        const QJsonArray newerUnstable{entry(QStringLiteral("0.20.0"), false),
                                       entry(QStringLiteral("0.19.5"), true),
                                       entry(QStringLiteral("0.19.4"), false)};
        const LoaderMeta::LoaderPick stablePick = LoaderMeta::pickFabricLoader(newerUnstable);
        check(stablePick.ok() && stablePick.version == QStringLiteral("0.19.5") && stablePick.stable,
              "V2 前面有更新的非正式版时，挑的是那条稳定的", stablePick.version);

        // 一个 stable 都没有（老版本的游戏常常是这种）：退回第一个，并且**如实**说它不是。
        const QJsonArray allUnstable{entry(QStringLiteral("0.15.0"), false),
                                     entry(QStringLiteral("0.14.9"), false)};
        const LoaderMeta::LoaderPick firstPick = LoaderMeta::pickFabricLoader(allUnstable);
        check(firstPick.ok() && firstPick.version == QStringLiteral("0.15.0") && !firstPick.stable,
              "V2 没有 stable 时退回第一个，并如实标成「不是正式版」", firstPick.version);

        check(!LoaderMeta::pickFabricLoader(QJsonArray()).ok(),
              "V2 空列表（快照那种「还没支持」的版本）-> 挑不出来，由调用方报错");

        // 坏条目跳过，不要让一个空 version 把整次安装带偏。
        const QJsonArray withJunk{entry(QString(), false), QJsonObject(), entry(QStringLiteral("0.19.0"), false)};
        const LoaderMeta::LoaderPick junkPick = LoaderMeta::pickFabricLoader(withJunk);
        check(junkPick.ok() && junkPick.version == QStringLiteral("0.19.0"),
              "V2 没有版本号的条目被跳过，挑到后面那个真的", junkPick.version);
        check(!LoaderMeta::pickFabricLoader(QJsonArray{QJsonObject(), entry(QString(), false)}).ok(),
              "V2 全是坏条目时也挑不出来（不是「挑一个空串」）");
    }

    // --- V3. profile 能不能照这样装下去 -----------------------------------------
    {
        const LoaderMeta::ProfileCheck good =
            LoaderMeta::checkFabricProfile(loaderProfile, QStringLiteral("1.19"));
        check(good.ok(), "V3 真 profile + 它真正基于的那个版本 -> 通过",
              QString::number(static_cast<int>(good.problem)));
        // 这条是"别自己发明 id 格式"的钉子：目录名同时是别的启动器/加载器找版本时用的名字。
        check(good.ok() &&
                  good.id == LoaderMeta::fabricLoaderId(QStringLiteral("1.19"),
                                                        QStringLiteral("0.19.5")),
              "V3 真 profile 里的 id 正好是 fabric-loader-0.19.5-1.19（我们没自己造）",
              good.id);
        check(good.ok() && good.parent == QStringLiteral("1.19"),
              "V3 真 profile 的 inheritsFrom 就是原版 1.19", good.parent);

        // 拿真数据只换一个游戏版本 = 最像真事故的那种情况（服务端给了别的版本的 profile）。
        const LoaderMeta::ProfileCheck wrongParent =
            LoaderMeta::checkFabricProfile(loaderProfile, QStringLiteral("1.18.2"));
        check(wrongParent.problem == LoaderMeta::ProfileProblem::WrongParent &&
                  wrongParent.parent == QStringLiteral("1.19"),
              "V3 装到 1.18.2 上、profile 却基于 1.19 -> WrongParent（宁可停下也不装出个错版本）");

        const auto withId = [&loaderProfile](const QString &id) {
            QJsonObject copy = loaderProfile;
            copy[QStringLiteral("id")] = id;
            return copy;
        };
        const auto idProblem = [&](const QString &id) {
            return LoaderMeta::checkFabricProfile(withId(id), QStringLiteral("1.19")).problem;
        };
        check(idProblem(QStringLiteral("../evil")) == LoaderMeta::ProfileProblem::BadId,
              "V3 id 里带 ../ -> BadId（这个 json 会原样落盘成 versions/<id>/，不能写到外面去）");
        check(idProblem(QStringLiteral("a/b")) == LoaderMeta::ProfileProblem::BadId,
              "V3 id 里带路径分隔符 -> BadId");
        check(idProblem(QStringLiteral("a b")) == LoaderMeta::ProfileProblem::BadId,
              "V3 id 里带空格 -> BadId");
        check(idProblem(QString()) == LoaderMeta::ProfileProblem::BadId, "V3 id 空着 -> BadId");
        check(idProblem(QStringLiteral(".")) == LoaderMeta::ProfileProblem::BadId &&
                  idProblem(QStringLiteral("..")) == LoaderMeta::ProfileProblem::BadId,
              "V3 id 是 . 或 .. -> BadId（它们能过字符白名单，但不是版本名）");

        // 白名单本身的真值表：**和 maven 那条是同一个**（都是"网上来的字符串当路径段用"）。
        check(LoaderMeta::isSafeVersionId(QStringLiteral("fabric-loader-0.19.5-1.19")) &&
                  LoaderMeta::isSafeVersionId(QStringLiteral("1.19.2")) &&
                  LoaderMeta::isSafeVersionId(QStringLiteral("26.2-snapshot-1")) &&
                  LoaderMeta::isSafeVersionId(QStringLiteral("a_b+c.d")),
              "V3 合法版本名（含真 Fabric id、快照名、下划线加号）都放行");
        check(!LoaderMeta::isSafeVersionId(QStringLiteral("a\\b")) &&
                  !LoaderMeta::isSafeVersionId(QStringLiteral("a:b")) &&
                  !LoaderMeta::isSafeVersionId(QStringLiteral("上")) &&
                  !LoaderMeta::isSafeVersionId(QStringLiteral("1.19 ")) &&
                  !LoaderMeta::isSafeVersionId(QStringLiteral("../1.19")),
              "V3 反斜杠 / 冒号 / 中文 / 尾空格 / ../ 一律拒绝");

        // 缺 inheritsFrom：不是"通过"，而是"父版本对不上"（空 != 1.19）。
        QJsonObject noParent = loaderProfile;
        noParent.remove(QStringLiteral("inheritsFrom"));
        check(LoaderMeta::checkFabricProfile(noParent, QStringLiteral("1.19")).problem ==
                  LoaderMeta::ProfileProblem::WrongParent,
              "V3 profile 里没有 inheritsFrom -> 当成父版本对不上，不装");
    }

    // --- V4. 界面下标 -> 加载器 -------------------------------------------------
    {
        check(VersionManager::loaderKindCount() == 4,
              "V4 四个加载器（界面那组钮里 0..3 是它们，第 4 个是「不装」）",
              QString::number(VersionManager::loaderKindCount()));

        struct Expect {
            int index;
            VersionManager::LoaderKind kind;
            const char *name;
        };
        const Expect expects[] = {
            {0, VersionManager::LoaderKind::Fabric, "Fabric"},
            {1, VersionManager::LoaderKind::Forge, "Forge"},
            {2, VersionManager::LoaderKind::NeoForge, "NeoForge"},
            {3, VersionManager::LoaderKind::OptiFine, "OptiFine"},
        };
        for (const Expect &e : expects) {
            // 故意先填一个别的：翻译失败时**不许**动这个变量（调用方可能还指望旧的）。
            VersionManager::LoaderKind kind = VersionManager::LoaderKind::OptiFine;
            const bool ok = VersionManager::loaderKindFromIndex(e.index, &kind);
            check(ok && kind == e.kind &&
                      VersionManager::loaderDisplayName(kind) == QLatin1String(e.name),
                  QString("V4 下标 %1 -> %2").arg(e.index).arg(QLatin1String(e.name)),
                  VersionManager::loaderDisplayName(kind));
        }

        VersionManager::LoaderKind keep = VersionManager::LoaderKind::NeoForge;
        check(!VersionManager::loaderKindFromIndex(-1, &keep) &&
                  keep == VersionManager::LoaderKind::NeoForge,
              "V4 -1（一个都没勾）翻不出来，而且没动传进去的那个变量");
        check(!VersionManager::loaderKindFromIndex(VersionManager::loaderKindCount(), &keep) &&
                  keep == VersionManager::LoaderKind::NeoForge,
              "V4 下标 4（界面上的「不装」）翻不出来 —— 它是「装纯原版」，不是加载器");
        check(!VersionManager::loaderKindFromIndex(99, &keep),
              "V4 越界下标翻不出来（界面表和枚举表对不上时宁可什么都不装）");
        check(VersionManager::loaderKindFromIndex(0, nullptr),
              "V4 out 允许传 nullptr（只想问「这个下标认不认」）");

        // 四个都接通了（OptiFine 是 2026-09-22 接上的，走的是第三条路：**无界面入口 +
        // 换 APPDATA + 对着临时目录装**）。界面靠它决定"点了下载弹哪一种话"，数据层也靠
        // 它拦一道 —— 挡反了的症状是"用户勾着某个加载器，装出来一个纯原版"。
        check(VersionManager::loaderInstallSupported(VersionManager::LoaderKind::Fabric) &&
                  VersionManager::loaderInstallSupported(VersionManager::LoaderKind::Forge) &&
                  VersionManager::loaderInstallSupported(VersionManager::LoaderKind::NeoForge) &&
                  VersionManager::loaderInstallSupported(VersionManager::LoaderKind::OptiFine),
              "V4 四个加载器都接通了");

        // 显示名不能空：它既写进 wtfml.meta 的 loaderName，也是弹窗里的主语。
        for (int i = 0; i < VersionManager::loaderKindCount(); ++i) {
            VersionManager::LoaderKind kind = VersionManager::LoaderKind::Fabric;
            VersionManager::loaderKindFromIndex(i, &kind);
            check(!VersionManager::loaderDisplayName(kind).isEmpty(),
                  QString("V4 下标 %1 的加载器有显示名").arg(i));
        }
    }

    // --- V5. Forge：版本从推广表里挑、地址怎么拼 --------------------------------
    //
    // 这份表是 4 KB 的推广版本表，一次把**所有**游戏版本的 Forge 推荐版本都带回来。
    const QJsonObject forgePromos = loadJson(metaDir + "/forge-promotions_slim.json");
    check(!forgePromos[QStringLiteral("promos")].toObject().isEmpty(),
          "V5 真推广表读到了（顶层得有个非空的 promos）");
    {
        // 实测 1.20.1 那一对是 47.4.10（recommended）/ 47.4.23（latest）。
        const LoaderMeta::LoaderPick rec =
            LoaderMeta::pickForgeVersion(forgePromos, QStringLiteral("1.20.1"));
        check(rec.ok() && rec.version == QStringLiteral("47.4.10") && rec.stable,
              "V5 有 recommended 时挑 recommended（不是数字更大的 latest）",
              rec.ok() ? QStringLiteral("%1 stable=%2").arg(rec.version).arg(rec.stable)
                       : QStringLiteral("挑不出来"));

        // 真表里有一大批游戏版本**只有 latest 一个键**（实测 1.20 只有 46.0.14，
        // 1.19.1 只有 42.0.9，1.21.6 只有 56.0.9）：必须兜底到它，否则那些版本一个都
        // 装不了。这一条只能拿真数据验 —— 自造的样例很容易写成"每个版本两个键都在"。
        const LoaderMeta::LoaderPick onlyLatest =
            LoaderMeta::pickForgeVersion(forgePromos, QStringLiteral("1.20"));
        check(onlyLatest.ok() && onlyLatest.version == QStringLiteral("46.0.14") &&
                  !onlyLatest.stable,
              "V5 只有 latest 的游戏版本 -> 用 latest，并如实标成「不是推荐的」",
              onlyLatest.ok() ? QStringLiteral("%1 stable=%2").arg(onlyLatest.version)
                                    .arg(onlyLatest.stable)
                              : QStringLiteral("挑不出来"));

        // 反过来钉一下上面那条的前提：1.7.10 在真表里**两个键都有**（值还一样）。留着
        // 这条是因为我第一版把"1.7.10 只有 latest"写进了注释和断言里 —— 那是想当然。
        check(LoaderMeta::pickForgeVersion(forgePromos, QStringLiteral("1.7.10")).stable,
              "V5 1.7.10 在真表里两个键都有（所以它走的是 recommended 那一支）",
              LoaderMeta::pickForgeVersion(forgePromos, QStringLiteral("1.7.10")).version);

        // 表里根本没有这个游戏版本（快照、或者比 Forge 最新的正式版还新）：挑不出来，
        // 由调用方报"还没有支持这个版本"，**不能**退回装纯原版。
        check(!LoaderMeta::pickForgeVersion(forgePromos, QStringLiteral("26.2-snapshot-1")).ok(),
              "V5 表里没有的游戏版本 -> 挑不出来");
        check(!LoaderMeta::pickForgeVersion(QJsonObject(), QStringLiteral("1.20.1")).ok(),
              "V5 表整个是空的（网络拿到一份烂东西）-> 挑不出来，不崩");

        // 地址和目录名。这两个名字**不是我们发明的**：`1.20.1-forge-47.4.10` 是安装器
        // 自己写进版本 json 的 id，也是别的启动器认的目录名。
        check(LoaderMeta::forgeLoaderId(QStringLiteral("1.20.1"), QStringLiteral("47.4.10")) ==
                  QStringLiteral("1.20.1-forge-47.4.10"),
              "V5 Forge 的目录名是 <游戏>-forge-<加载器>",
              LoaderMeta::forgeLoaderId(QStringLiteral("1.20.1"), QStringLiteral("47.4.10")));
        check(LoaderMeta::forgeInstallerUrl(QStringLiteral("1.20.1"),
                                            QStringLiteral("47.4.10")) ==
                  QStringLiteral("https://maven.minecraftforge.net/net/minecraftforge/forge/"
                                 "1.20.1-47.4.10/forge-1.20.1-47.4.10-installer.jar"),
              "V5 Forge 安装器地址（maven 直链，坐标是 <游戏>-<加载器>）",
              LoaderMeta::forgeInstallerUrl(QStringLiteral("1.20.1"),
                                            QStringLiteral("47.4.10")));
        check(!LoaderMeta::forgePromotionsUrl().contains(QStringLiteral(" ")),
              "V5 推广表地址里没有空格（拼坏了的症状是 404，不是崩）");
    }

    // --- V5b. 镜像那份推广表是**旧的**（2026-09-22 加）--------------------------
    //
    // 用户报的是"反复提示各个版本没有 Forge 支持（实际上是有的）"。真因在**数据**上：镜像
    // （BMCLAPI）那份 promotions_slim.json 是个旧文件，拿它挑 1.16 以后的版本**一条都挑不
    // 出来**，于是界面上就成了"这个版本还没有 Forge 支持"。两份都是实测原样存下来的。
    //
    // 所以版本表那条路是"镜像发一发，挑不出来就换官方再发一发"（见 VersionManager::
    // retryInstallerListFromOfficial）。这一节钉的就是那个前提：镜像那份确实挑不出来、
    // 官方那份确实挑得出来。
    {
        QFile mirrorFile(metaDir + "/forge-promotions_slim_mirror.json");
        QByteArray mirrorBytes;
        if (mirrorFile.open(QIODevice::ReadOnly)) {
            mirrorBytes = mirrorFile.readAll();
        }
        const QJsonObject promosMirror =
            loadJson(metaDir + "/forge-promotions_slim_mirror.json");
        check(!promosMirror[QStringLiteral("promos")].toObject().isEmpty() &&
                  mirrorBytes.size() > 100,
              "V5b 镜像那份推广表 fixture 读到了", QString::number(mirrorBytes.size()));
        if (!promosMirror.isEmpty()) {
            check(!LoaderMeta::pickForgeVersion(promosMirror, QStringLiteral("26.2")).ok(),
                  "V5b 拿镜像那份挑 26.2 -> 挑不出来（用户看到的「没有支持」就是这么来的）");
            check(!LoaderMeta::pickForgeVersion(promosMirror, QStringLiteral("1.20.1")).ok(),
                  "V5b 拿镜像那份挑 1.20.1 -> 也挑不出来（不是只有最新那几个版本受影响）");
            check(LoaderMeta::pickForgeVersion(promosMirror, QStringLiteral("1.8.9")).ok(),
                  "V5b 镜像那份里**有** 1.8.9（所以那次 1.8.9 的安装器真的被下下来、跑了 —— "
                  "日志里那段报错是另一件事）",
                  LoaderMeta::pickForgeVersion(promosMirror, QStringLiteral("1.8.9")).version);
            // 同一份代码、换官方那份就挑得出来 —— 兜底那条路的意义就在这里。
            check(LoaderMeta::pickForgeVersion(forgePromos, QStringLiteral("26.2")).ok(),
                  "V5b 换官方那份之后挑得出来（镜像挑不出来就退官方，有用的）",
                  LoaderMeta::pickForgeVersion(forgePromos, QStringLiteral("26.2")).version);
            // 两份的体量：镜像那份小得多。不靠"哪个文件新"判断，靠"挑不出来就退"。
            QFileInfo officialInfo(metaDir + "/forge-promotions_slim.json");
            check(mirrorBytes.size() < officialInfo.size(),
                  "V5b 镜像那份比官方那份小得多（实测 1782 B / 4111 B）",
                  QStringLiteral("%1 / %2").arg(mirrorBytes.size()).arg(officialInfo.size()));
        }
    }

    // --- V6. NeoForge：版本号比大小 / 前缀匹配 / 从 maven 元数据里挑 ------------
    //
    // 这一节的值全得和**真数据**对上：maven 那份 1716 个版本号里有 21.1.x 和 21.10.x
    // 两族（分别对应 MC 1.21.1 和 1.21.10），按字符串前缀比就会把它们混起来 ——
    // 实测最容易犯的错是"1.21.1 挑出 21.10.64"。
    {
        // 一个小糖：让下面那几条断言能写成 nums({21, 1, 251}) 的样子。
        const auto nums = [](QList<int> values) { return values; };
        // 反过来：把解析结果写成 "21.1" 的样子，失败时看得懂（QList<int> 没有 join()）。
        const auto dotted = [](const QList<int> &values) {
            QStringList parts;
            for (int value : values) {
                parts.append(QString::number(value));
            }
            return parts.join(QLatin1Char('.'));
        };

        check(LoaderMeta::parseDottedVersion(QStringLiteral("21.1.251")) ==
                  nums({21, 1, 251}),
              "V6 点分版本号解析", QStringLiteral("21.1.251"));
        check(LoaderMeta::parseDottedVersion(QString()).isEmpty() &&
                  LoaderMeta::parseDottedVersion(QStringLiteral("21.1-beta")).isEmpty() &&
                  LoaderMeta::parseDottedVersion(QStringLiteral("+5")).isEmpty() &&
                  LoaderMeta::parseDottedVersion(QStringLiteral(" 5")).isEmpty() &&
                  LoaderMeta::parseDottedVersion(QStringLiteral("21..1")).isEmpty(),
              "V6 不是纯数字的段一律解析失败（顺带挡住带符号/空白的写法）");

        check(LoaderMeta::compareDottedVersions(nums({21, 1, 251}), nums({21, 10, 64})) < 0 &&
                  LoaderMeta::compareDottedVersions(nums({26, 2, 0, 88}), nums({26, 2})) > 0 &&
                  LoaderMeta::compareDottedVersions(nums({21, 1, 251}), nums({21, 1, 251})) == 0,
              "V6 比大小：短的按补零算（26.2 < 26.2.0.88），且 21.1.x < 21.10.x");

        check(LoaderMeta::isDottedPrefix(nums({21, 1}), nums({21, 1, 251})) &&
                  !LoaderMeta::isDottedPrefix(nums({21, 1}), nums({21, 10, 64})) &&
                  !LoaderMeta::isDottedPrefix(nums({21, 1, 251}), nums({21, 1})) &&
                  !LoaderMeta::isDottedPrefix(QList<int>(), nums({21, 1})),
              "V6 前缀是**逐段**比的：21.1 是 21.1.251 的前缀，不是 21.10.64 的");

        // 游戏版本 -> NeoForge 前缀。去掉开头的 `1.` 再取两段；只有一段时补一个 `.0`
        // （不补的话 `1.21` 会退化成前缀 `[21]`，把 21.1.x / 21.11.x 全算进来）。
        check(LoaderMeta::neoForgeVersionPrefix(QStringLiteral("1.21.1")) == nums({21, 1}) &&
                  LoaderMeta::neoForgeVersionPrefix(QStringLiteral("1.20.2")) == nums({20, 2}) &&
                  LoaderMeta::neoForgeVersionPrefix(QStringLiteral("1.21")) == nums({21, 0}) &&
                  LoaderMeta::neoForgeVersionPrefix(QStringLiteral("26.2")) == nums({26, 2}) &&
                  LoaderMeta::neoForgeVersionPrefix(QStringLiteral("26.1.2")) == nums({26, 1}),
              "V6 游戏版本 -> NeoForge 前缀",
              QStringLiteral("%1 / %2")
                  .arg(dotted(LoaderMeta::neoForgeVersionPrefix(QStringLiteral("1.21.1"))),
                       dotted(LoaderMeta::neoForgeVersionPrefix(QStringLiteral("1.21")))));
        check(LoaderMeta::neoForgeVersionPrefix(QStringLiteral("snapshot")).isEmpty(),
              "V6 不是数字的游戏版本 -> 空前缀（调用方据此报错，不会乱挑）");

        // --- V6b 自然序比较（compareVersionStrings）----------------------------
        //
        // 这一级是 2026-09-24 修的：排序的最后一级 tie-break 原来是 `a < b`（字符串），
        // 而它接手的正是"切掉后缀之后数字一模一样"的那一族 —— NeoForge 26.1 那批
        // `26.1.0.0-alpha.N+snapshot-N`。按字符串比 `alpha.10 < alpha.2`，于是「最新档」
        // 会挑中一个更旧的快照（列表是"新到旧"的）。
        {
            const auto cmp = [](const QString &l, const QString &r) {
                return LoaderMeta::compareVersionStrings(l, r);
            };
            check(cmp(QStringLiteral("26.1.0.0-alpha.2+snapshot-1"),
                      QStringLiteral("26.1.0.0-alpha.1+snapshot-1")) > 0,
                  "V6b alpha.2 比 alpha.1 新（按字符串比 `\"alpha.1\" < \"alpha.2\"` 会反过来）");
            check(cmp(QStringLiteral("26.1.0.0-alpha.10+snapshot-1"),
                      QStringLiteral("26.1.0.0-alpha.2+snapshot-1")) > 0,
                  "V6b alpha.10 比 alpha.2 新（数字段按**数值**比，不是按首位字符）");
            check(cmp(QStringLiteral("26.3.0.10-beta"), QStringLiteral("26.3.0.9-beta")) > 0,
                  "V6b 26.3.0.10-beta 比 26.3.0.9-beta 新");
            check(cmp(QStringLiteral("1.21.10"), QStringLiteral("1.21.2")) > 0,
                  "V6b 1.21.10 比 1.21.2 新（按字符串比是反的：1.21.10 排在 1.21.2 前面）");
            check(cmp(QStringLiteral("1.21"), QStringLiteral("1.21.0")) < 0,
                  "V6b 前缀短的算旧（1.21 < 1.21.0）—— 靠这一条把次序钉死成全序");
            check(cmp(QStringLiteral("1.2.3"), QStringLiteral("1.2.3")) == 0,
                  "V6b 同一个版本号比出来是 0");
            // 全序的三条性质：反对称、传递、（对同一对）结果稳定。std::sort 要的正是这些。
            check(cmp(QStringLiteral("a.2"), QStringLiteral("a.10")) ==
                      -cmp(QStringLiteral("a.10"), QStringLiteral("a.2")),
                  "V6b 反对称：cmp(a,b) == -cmp(b,a)");
            check(cmp(QStringLiteral("1.9"), QStringLiteral("1.10")) < 0 &&
                      cmp(QStringLiteral("1.10"), QStringLiteral("1.11")) < 0 &&
                      cmp(QStringLiteral("1.9"), QStringLiteral("1.11")) < 0,
                  "V6b 传递：1.9 < 1.10 < 1.11 且 1.9 < 1.11");
        }

        // --- V6c 排序里"后缀不同、数字相同"那一族：新的在前 ---------------------
        // 拿真那一族的形状造一份最小的列表（26.1.0.0-alpha.1 / .2 / .10 + 一个正式版）。
        // 这几条**故意**用 sortLoaderVersionsNewestFirst() 自己排，而不是直接调比较函数：
        // 上一版的问题就在这个函数最后一级上。
        {
            LoaderMeta::LoaderVersionList list;
            list.append({QStringLiteral("26.1.0.0-alpha.1+snapshot-1"), false});
            list.append({QStringLiteral("26.1.0.0-alpha.10+snapshot-1"), false});
            list.append({QStringLiteral("26.1.0.0-alpha.2+snapshot-1"), false});
            list.append({QStringLiteral("26.1.0.0"), true});
            LoaderMeta::sortLoaderVersionsNewestFirst(list);
            check(list.size() == 4, "V6c 排完还是四条（没丢没重）");
            check(list.value(0).version == QStringLiteral("26.1.0.0"),
                  "V6c 正式版排在最前（数字一样时正式版在前，这一级没被新加的 tie-break 顶掉）",
                  list.value(0).version);
            check(list.value(1).version == QStringLiteral("26.1.0.0-alpha.10+snapshot-1") &&
                      list.value(2).version == QStringLiteral("26.1.0.0-alpha.2+snapshot-1") &&
                      list.value(3).version == QStringLiteral("26.1.0.0-alpha.1+snapshot-1"),
                  "★ V6c 三个快照按 10 > 2 > 1 排（改之前是 2 > 1 > 10，最后一条最旧）",
                  QStringLiteral("%1, %2, %3")
                      .arg(list.value(1).version, list.value(2).version, list.value(3).version));
        }

        // 真 maven 元数据。
        QFile mavenFile(metaDir + "/neoforge-maven-metadata.xml");
        QByteArray maven;
        if (mavenFile.open(QIODevice::ReadOnly)) {
            maven = mavenFile.readAll();
        }
        check(maven.size() > 10000, "V6 真 maven 元数据读到了",
              QString::number(maven.size()));
        if (!maven.isEmpty()) {
            // 实测：21.1.x 那一族数字最大的是 21.1.251，而这**正好是文件末尾附近**那个
            // 夹在一堆 26.3 快照中间的行 —— 所以"挑出来是它"不能证明什么，"不是 26.3.x
            // 也不是 21.10.64"才是这两条断言的意思。
            const LoaderMeta::LoaderPick pick1211 =
                LoaderMeta::pickNeoForgeVersion(maven, QStringLiteral("1.21.1"));
            check(pick1211.ok() && pick1211.version == QStringLiteral("21.1.251"),
                  "V6 1.21.1 -> 21.1.251（真数据里 21.1.x 那一族最大那个）",
                  pick1211.version);
            check(!pick1211.version.startsWith(QStringLiteral("21.10.")),
                  "V6 没有把 21.10.x 当成 1.21.1 的加载器（字符串前缀比就会犯这个错）",
                  pick1211.version);

            // 反过来：1.21.10 那一族也得挑得出来（证明前缀比较不是"只认短的"）。
            const LoaderMeta::LoaderPick pick12110 =
                LoaderMeta::pickNeoForgeVersion(maven, QStringLiteral("1.21.10"));
            check(pick12110.ok() && pick12110.version == QStringLiteral("21.10.64"),
                  "V6 1.21.10 -> 21.10.64（反过来那一族）", pick12110.version);

            // 两段式游戏版本：1.21 -> 21.0.x。
            const LoaderMeta::LoaderPick pick121 =
                LoaderMeta::pickNeoForgeVersion(maven, QStringLiteral("1.21"));
            check(pick121.ok() && pick121.version == QStringLiteral("21.0.167"),
                  "V6 1.21 -> 21.0.167（前缀补的那个 .0 起作用了）", pick121.version);

            // 四段式：26.2 -> 26.2.0.88。这条钉的是"比大小要能比长度不一样的两串"。
            const LoaderMeta::LoaderPick pick262 =
                LoaderMeta::pickNeoForgeVersion(maven, QStringLiteral("26.2"));
            check(pick262.ok() && pick262.version == QStringLiteral("26.2.0.88"),
                  "V6 26.2 -> 26.2.0.88（四段）", pick262.version);

            // NeoForge 从 1.20.2 才开始有：1.20.1 得挑不出来（真数据里确实一个都没有）。
            check(!LoaderMeta::pickNeoForgeVersion(maven, QStringLiteral("1.20.1")).ok(),
                  "V6 1.20.1 -> 挑不出来（NeoForge 那时还没出生）");

            // 带后缀的一个都不能挑中：`-beta` 那一大堆占了整个文件的大多数。
            check(!pick1211.version.contains(QLatin1Char('-')),
                  "V6 挑中的版本号不带后缀（beta 全都跳过了）", pick1211.version);
        }

        check(LoaderMeta::neoforgeLoaderId(QStringLiteral("21.1.251")) ==
                  QStringLiteral("neoforge-21.1.251"),
              "V6 NeoForge 的目录名**不带**游戏版本前缀（和 Forge 不一样，不能统一）",
              LoaderMeta::neoforgeLoaderId(QStringLiteral("21.1.251")));
        check(LoaderMeta::neoforgeInstallerUrl(QStringLiteral("21.1.251")) ==
                  QStringLiteral("https://maven.neoforged.net/releases/net/neoforged/neoforge/"
                                 "21.1.251/neoforge-21.1.251-installer.jar"),
              "V6 NeoForge 安装器地址",
              LoaderMeta::neoforgeInstallerUrl(QStringLiteral("21.1.251")));
    }

    // --- V6b. 官方地址 -> 镜像地址（含 2026-09-22 新认的 Forge / NeoForge 那几条）------
    //
    // 这一批是**纯函数**、不碰网络，钉的是"哪条地址会被换成什么"。换错的症状不是崩，而是
    // "下载全失败"或者"白等了很久才发现根本没走镜像"，所以每条都得有写死的期望值。
    // NOTE: 这几条 2026-09-22 才补上（在此之前这四个函数一条断言都没有）。
    {
        const QString base = QStringLiteral("https://bmclapi2.bangbang93.com");

        // 原来就认得的那三个：路径形状和官方一样（只有资源对象要多一层 /assets）。
        check(DownloadManager::mirrorUrl(
                  QStringLiteral("https://launchermeta.mojang.com/mc/game/version_manifest.json")) ==
                  base + QStringLiteral("/mc/game/version_manifest.json"),
              "V6b 版本清单：换 host、路径照抄",
              DownloadManager::mirrorUrl(QStringLiteral(
                  "https://launchermeta.mojang.com/mc/game/version_manifest.json")));
        check(DownloadManager::mirrorUrl(
                  QStringLiteral("https://resources.download.minecraft.net/ab/abcdef")) ==
                  base + QStringLiteral("/assets/ab/abcdef"),
              "V6b 资源对象：多一层 /assets");
        check(DownloadManager::mirrorUrl(
                  QStringLiteral("https://libraries.minecraft.net/com/foo/bar/1.0/bar-1.0.jar")) ==
                  base + QStringLiteral("/maven/com/foo/bar/1.0/bar-1.0.jar"),
              "V6b 原版库：加 /maven 前缀");

        // 2026-09-22 新认的（用户报的"forge 下载太慢"就是走这条路）。
        check(DownloadManager::mirrorUrl(LoaderMeta::forgeInstallerUrl(
                  QStringLiteral("1.20.1"), QStringLiteral("47.4.10"))) ==
                  base + QStringLiteral("/maven/net/minecraftforge/forge/1.20.1-47.4.10/"
                                        "forge-1.20.1-47.4.10-installer.jar"),
              "V6b Forge 安装器 jar 走镜像（以前是原样过去）",
              DownloadManager::mirrorUrl(LoaderMeta::forgeInstallerUrl(QStringLiteral("1.20.1"),
                                                                      QStringLiteral("47.4.10"))));
        check(DownloadManager::mirrorUrl(
                  QStringLiteral("https://maven.minecraftforge.net/net/minecraftforge/"
                                 "JarJarFileSystems/0.4.2/JarJarFileSystems-0.4.2.jar")) ==
                  base + QStringLiteral("/maven/net/minecraftforge/JarJarFileSystems/0.4.2/"
                                        "JarJarFileSystems-0.4.2.jar"),
              "V6b Forge 的库也走镜像（装出来的版本 json 里就是这些地址）");
        check(DownloadManager::mirrorUrl(LoaderMeta::forgePromotionsUrl()) ==
                  base + QStringLiteral("/maven/net/minecraftforge/forge/promotions_slim.json"),
              "V6b Forge 推广表：files 那个 host 也是标准 maven 布局",
              DownloadManager::mirrorUrl(LoaderMeta::forgePromotionsUrl()));
        check(DownloadManager::mirrorUrl(LoaderMeta::neoforgeInstallerUrl(
                  QStringLiteral("21.1.251"))) ==
                  base + QStringLiteral("/maven/net/neoforged/neoforge/21.1.251/"
                                        "neoforge-21.1.251-installer.jar"),
              "V6b NeoForge 安装器 jar 走镜像（官方那个 /releases 前缀要**去掉**）",
              DownloadManager::mirrorUrl(
                  LoaderMeta::neoforgeInstallerUrl(QStringLiteral("21.1.251"))));
        check(DownloadManager::mirrorUrl(LoaderMeta::neoforgeMavenMetadataUrl()) ==
                  base + QStringLiteral("/maven/net/neoforged/neoforge/maven-metadata.xml"),
              "V6b NeoForge 的版本表走镜像");

        // 镜像上**没有**的那些：宁可原样走官方，也不许拼一个不存在的地址出来。
        check(DownloadManager::mirrorUrl(
                  QStringLiteral("https://maven.neoforged.net/snapshots/net/neoforged/neoforge/"
                                 "26.2.0.1/neoforge-26.2.0.1-installer.jar")) ==
                  QStringLiteral("https://maven.neoforged.net/snapshots/net/neoforged/neoforge/"
                                 "26.2.0.1/neoforge-26.2.0.1-installer.jar"),
              "V6b NeoForge 的 snapshots 支**不**换（镜像只收 releases，换了就是 404）");
        check(DownloadManager::mirrorUrl(
                  QStringLiteral("https://meta.fabricmc.net/v2/versions/loader/1.19")) ==
                  QStringLiteral("https://meta.fabricmc.net/v2/versions/loader/1.19"),
              "V6b 认不出来的 host（Fabric 那套）原样返回");

        // 按版本号 / 索引号重拼的那三个（官方地址里的 sha1 镜像不认，只能用 id 拼）。
        check(DownloadManager::mirrorVersionJsonUrl(QStringLiteral("1.18.2")) ==
                  base + QStringLiteral("/version/1.18.2/json"),
              "V6b 版本 JSON 按版本号拼",
              DownloadManager::mirrorVersionJsonUrl(QStringLiteral("1.18.2")));
        check(DownloadManager::mirrorClientJarUrl(QStringLiteral("1.18.2")) ==
                  base + QStringLiteral("/version/1.18.2/client"),
              "V6b 客户端 jar 按版本号拼");
        check(DownloadManager::mirrorAssetIndexUrl(QStringLiteral("1.18")) ==
                  base + QStringLiteral("/indexes/1.18.json"),
              "V6b 资源索引按索引号拼（这条地址在镜像上实测 404，所以下载那边有一条"
              "退回官方的兜底 —— 那一段只有联网真跑才看得见，见 loader-install 的 mirror 模式）");

        // 给安装器的那个根地址：**结尾的斜杠是行为的一部分**，不是排版问题（实测漏了它，
        // 安装器会去要 .../mavennet/...，镜像 404、它自己退回官方）。
        const QString mavenRoot = DownloadManager::mirrorMavenRootUrl();
        check(mavenRoot == base + QStringLiteral("/maven/"),
              "V6b --mirror 用的根地址就是这个", mavenRoot);
        check(mavenRoot.endsWith(QLatin1Char('/')),
              "V6b 根地址结尾必须有斜杠");
    }

    // --- V6c. 安装器命令行（--mirror 是唯一一条"拨到镜像"的实际动作）-------------
    {
        const QString jar = QStringLiteral("C:/cache/installers/forge-1.20.1-47.4.10-installer.jar");
        const QStringList official =
            VersionManager::forgeInstallerArguments(jar, QStringLiteral("D:/mc"), false);
        check(official.size() == 4 && official.at(0) == QStringLiteral("-jar") &&
                  official.at(1) == jar && official.at(2) == QStringLiteral("--installClient") &&
                  official.at(3) == QStringLiteral("D:/mc"),
              "V6c 官方源：四个参数，--installClient 带着目标目录（不给它，安装器会装到用户主"
              "目录去）",
              official.join(QLatin1Char(' ')));
        check(!official.contains(QStringLiteral("--mirror")),
              "V6c 官方源下**不给** --mirror（用户的源选择不许被绕过）");

        const QStringList mirror =
            VersionManager::forgeInstallerArguments(jar, QStringLiteral("D:/mc"), true);
        check(mirror.size() == 6 && mirror.at(4) == QStringLiteral("--mirror") &&
                  mirror.at(5) == DownloadManager::mirrorMavenRootUrl(),
              "V6c 镜像源：多一对 --mirror <根地址>（安装器自己下那十几个库也走它）",
              mirror.join(QLatin1Char(' ')));
        check(mirror.mid(0, 4) == official,
              "V6c 加不加 --mirror，前面那四个参数一字不差");
    }

    // --- V6g. 安装器的命令行开关要**先探一次**（2026-09-22 加）-----------------
    //
    // 起因是一条真机日志（用户报的那个 1.8.9 安装失败）：安装器被喂了 `--installClient`，
    // 它当场 joptsimple.UnrecognizedOptionException 退出码 1 —— 那个年代的安装器把"装
    // 客户端"做成了图形界面，命令行里根本没有这条路。所以跑安装器之前先跑一次 `--help`
    // 问它。下面两份帮助都是真的：在真安装器 jar 上跑出来的，原样存进 meta/。
    //
    // 实测的边界（每个都下了 4~5 MB 的安装器跑 `--help`）：1.7.10 / 1.8.9（11.15.1.1722
    // 和 11.15.1.2318）/ 1.9.4 / 1.10.2 / 1.11.2 都不认；1.12.2（14.23.5.2859）和 26.2
    // （65.1.0）都认。
    {
        const auto readMetaText = [&metaDir](const QString &name) {
            QFile file(metaDir + QLatin1Char('/') + name);
            if (!file.open(QIODevice::ReadOnly)) {
                return QString();
            }
            return QString::fromUtf8(file.readAll());
        };

        const QString legacyHelp =
            readMetaText(QStringLiteral("installer-help-legacy-1.8.9.txt"));
        check(legacyHelp.contains(QStringLiteral("--extract")) &&
                  legacyHelp.contains(QStringLiteral("--installServer")),
              "V6g 老安装器那份帮助读到了（--extract / --installServer 都在，说明是真东西）",
              QString::number(legacyHelp.size()));
        if (!legacyHelp.isEmpty()) {
            const VersionManager::InstallerOptions legacy =
                VersionManager::parseInstallerHelp(legacyHelp);
            check(legacy.probed, "V6g 探到了就置 probed");
            check(!legacy.supportsInstallClient,
                  "V6g 老安装器不认 --installClient -> 报「这个安装器只有图形界面」"
                  "（以前是把它喂过去，用户看到一段 Java 堆栈）");
            check(!legacy.supportsMirror, "V6g 老安装器也不认 --mirror");
        }

        const QString modernHelp =
            readMetaText(QStringLiteral("installer-help-neoforge-26.2.txt"));
        check(modernHelp.contains(QStringLiteral("--installClient")),
              "V6g 现代安装器那份帮助读到了（--installClient 在）",
              QString::number(modernHelp.size()));
        if (!modernHelp.isEmpty()) {
            const VersionManager::InstallerOptions modern =
                VersionManager::parseInstallerHelp(modernHelp);
            check(modern.supportsInstallClient && modern.supportsMirror,
                  "V6g 现代安装器两个开关都认 -> 这条路一行都没变（26.2 那次真装就是这么跑的）");
        }

        // 探不出来时的默认值必须是"宁可信其有"：探针是为了少一次莫名其妙的报错，
        // 不能反过来变成新的"把本来能装的版本拦下来"的关。
        const VersionManager::InstallerOptions none;
        check(!none.probed && none.supportsInstallClient && none.supportsMirror,
              "V6g 没探到时默认两个都认（起不来 / 超时 / 输出是空的那几支都走这里）");

        // 探到不认 --mirror 就不给：宁可它自己那条下载路慢一点，也不能死在多给一个参数上。
        const QString probeJar =
            QStringLiteral("C:/cache/installers/forge-1.8.9-11.15.1.1722-installer.jar");
        const QStringList noMirror = VersionManager::forgeInstallerArguments(
            probeJar, QStringLiteral("D:/mc"), true, false);
        check(noMirror.size() == 4 && !noMirror.contains(QStringLiteral("--mirror")),
              "V6g 探到不认 --mirror -> 那一条就不给（其余四个参数一字不动）",
              noMirror.join(QLatin1Char(' ')));
        const QStringList yesMirror = VersionManager::forgeInstallerArguments(
            probeJar, QStringLiteral("D:/mc"), true, true);
        check(yesMirror.size() == 6,
              "V6g 认 --mirror 时照旧给（老行为不变）", yesMirror.join(QLatin1Char(' ')));

        // 老游戏版本的安装器 jar 在**另一种坐标**上（实测：1.8.9-11.15.1.2318-1.8.9 有、
        // 单坐标那份 404）。常规那种下不来时换它再下一遍。
        check(LoaderMeta::forgeInstallerUrlAlternate(QStringLiteral("1.8.9"),
                                                     QStringLiteral("11.15.1.2318")) ==
                  QStringLiteral("https://maven.minecraftforge.net/net/minecraftforge/forge/"
                                 "1.8.9-11.15.1.2318-1.8.9/"
                                 "forge-1.8.9-11.15.1.2318-1.8.9-installer.jar"),
              "V6g 第二种坐标是 <游戏>-<加载器>-<游戏>（文件名里也是三段）",
              LoaderMeta::forgeInstallerUrlAlternate(QStringLiteral("1.8.9"),
                                                     QStringLiteral("11.15.1.2318")));
        check(LoaderMeta::forgeInstallerUrlAlternate(QStringLiteral("1.8.9"),
                                                     QStringLiteral("11.15.1.2318")) !=
                  LoaderMeta::forgeInstallerUrl(QStringLiteral("1.8.9"),
                                                QStringLiteral("11.15.1.2318")),
              "V6g 两种坐标确实是两个地址（不一样才值得再下一遍）"
              " —— 也正是 V6d 那条 shouldRecordOfficialFallback 的判据");
    }

    // --- V6h. version.json 自己声明的游戏参数（2026-09-22 加）------------------
    //
    // 起因是用户报的那次启动崩溃：NeoForge 26.2 的版本 json 在 arguments.game 里写着
    // `--fml.neoForgeVersion 26.2.0.88 --fml.mcVersion 26.2 --fml.neoFormVersion 2`，而
    // 启动器**只展开 arguments.jvm**，于是 FML 报 "--fml.mcVersion must be present as a
    // command-line argument"、接着 VersionSupportMatrix 拿着空版本号 NPE，游戏在加载窗口
    // 那一步就没了（日志见 build/.minecraft/logs/latest.log）。
    //
    // 两份都是真数据：meta/neoforge-26.2.0.88.json 是那个安装器写出来的 profile 原样，
    // meta/26.2.json 是原版那份。
    //
    // NOTE: 判据必须是**继承链合并过**的那份 json —— 真实启动时 generateJvmArguments 拿到的
    //       就是它。第一版把判据设在 `inheritsFrom` 上，而 merge 刻意丢掉了那个字段，于是
    //       单元测试（喂原样 profile）全绿、真机照旧崩在原来那一句上。所以下面先合并再喂。
    {
        const QJsonObject neoforgeJson = loadJson(metaDir + "/neoforge-26.2.0.88.json");
        const QJsonObject vanillaJson = loadJson(metaDir + "/26.2.json");
        check(!neoforgeJson.isEmpty() && !vanillaJson.isEmpty(),
              "V6h 两份真数据都读到了");
        if (!neoforgeJson.isEmpty() && !vanillaJson.isEmpty()) {
            QHash<QString, QString> placeholders;
            placeholders[QStringLiteral("auth_player_name")] = QStringLiteral("Steve");
            placeholders[QStringLiteral("version_name")] = QStringLiteral("neoforge-26.2.0.88");
            placeholders[QStringLiteral("game_directory")] =
                QStringLiteral("D:/mc/versions/neoforge-26.2.0.88");
            placeholders[QStringLiteral("assets_root")] = QStringLiteral("D:/mc/assets");
            placeholders[QStringLiteral("assets_index_name")] = QStringLiteral("29");
            placeholders[QStringLiteral("auth_uuid")] = QStringLiteral("uuid-1");
            placeholders[QStringLiteral("auth_access_token")] = QStringLiteral("tok");
            placeholders[QStringLiteral("user_type")] = QStringLiteral("msa");
            placeholders[QStringLiteral("version_type")] = QStringLiteral("release");

            const QJsonObject neoforgeMerged =
                VersionInheritance::merge(neoforgeJson, vanillaJson);
            check(neoforgeMerged.value(QStringLiteral("inheritsFrom")).toString().isEmpty() &&
                      !neoforgeMerged.value(QStringLiteral("mainClass")).toString().isEmpty() &&
                      !neoforgeMerged.value(QStringLiteral("libraries")).toArray().isEmpty(),
                  "V6h 合并后的 json 是个完整的版本（没有 inheritsFrom、有 mainClass 和库）"
                  "—— 启动时喂进 generateJvmArguments 的就是这一份",
                  neoforgeMerged.value(QStringLiteral("mainClass")).toString());
            const QStringList extra = VersionArguments::extraGameArguments(
                neoforgeMerged, QStringList(), placeholders);
            check(extra == QStringList{QStringLiteral("--fml.neoForgeVersion"),
                                       QStringLiteral("26.2.0.88"),
                                       QStringLiteral("--fml.mcVersion"),
                                       QStringLiteral("26.2"),
                                       QStringLiteral("--fml.neoFormVersion"),
                                       QStringLiteral("2")},
                  "V6h NeoForge 那三条 --fml.* 一条不少地带上（少了 --fml.mcVersion 就是那次"
                  "崩溃的第一句话）",
                  extra.join(QLatin1Char(' ')));

            // 已经在命令行里的选项要跳过（连同它的值），否则同一个选项发两遍。
            const QStringList deduped = VersionArguments::extraGameArguments(
                neoforgeMerged, QStringList{QStringLiteral("--fml.mcVersion")}, placeholders);
            check(deduped == QStringList{QStringLiteral("--fml.neoForgeVersion"),
                                         QStringLiteral("26.2.0.88"),
                                         QStringLiteral("--fml.neoFormVersion"),
                                         QStringLiteral("2")},
                  "V6h 已经发过的选项连它的值一起跳过", deduped.join(QLatin1Char(' ')));

            // 纯原版那条路必须**逐字节不变**（原版没有父版本，喂进来的就是 json 自己那份）：
            // 判据是它 arguments.game 里全是原版那套名字，而那一套启动器上面已经发过了。
            check(VersionArguments::extraGameArguments(vanillaJson, QStringList(), placeholders)
                      .isEmpty(),
                  "V6h 纯原版（arguments.game 那代）一条都不加",
                  QString::number(
                      vanillaJson[QStringLiteral("arguments")].toObject()[QStringLiteral("game")]
                          .toArray()
                          .size()));
            // 老格式那份也一样：1.12.2 的原版 json 用 minecraftArguments 写同一套名字。
            const QJsonObject vanillaLegacy = loadJson(metaDir + "/1.12.2.json");
            check(!vanillaLegacy.value(QStringLiteral("minecraftArguments")).toString().isEmpty(),
                  "V6h 1.12.2 那份原版确实是老格式（minecraftArguments）—— 老格式这条路也验到了");
            check(VersionArguments::extraGameArguments(vanillaLegacy, QStringList(), placeholders)
                      .isEmpty(),
                  "V6h 纯原版（minecraftArguments 那代）也一条都不加");
            // ★ 占位符警告（2026-09-26 修的那条）：extraGameArguments 拿到的这一份里，
            //   绝大多数条目**下一句就会被整条跳掉**（原版那套名字启动器上面已经发过了），
            //   而它们身上的 ${clientid} / ${auth_xuid} / ${user_properties} … 我们本来就
            //   不提供 —— 所以"替换"必须排到过滤**之后**去做，否则每一条都会甩一句
            //   "Unresolved placeholder"（实测 1.18.2 / 1.20.1 各 11 条、1.21.11+ 有 10 条），
            //   而那几行**一个字节都不会进命令行**。
            //
            //   原来那一版传的是 `expand(game, 空映射, ...)` —— **空映射不等于"不替换"**，
            //   substitutePlaceholders() 是无条件调的，警告照发，注释逐字承诺的事一件没做到。
            //
            //   这里量两件事：真夹具过一遍**一条警告都没有**；**并且先自检拦法通不通** ——
            //   故意拿一个没人填的占位符调一次，计数必须动一下，否则"0 条"可能只是这个处理器
            //   压根收不到东西（那种假绿正是这个坑第一次溜过去的原因）。
            {
                const QtMessageHandler previous = qInstallMessageHandler(countPlaceholderWarnings);
                g_placeholderWarnings = 0;
                const QStringList vanillaArgs =
                    VersionArguments::extraGameArguments(vanillaJson, QStringList(), placeholders);
                const QStringList legacyArgs = VersionArguments::extraGameArguments(
                    vanillaLegacy, QStringList(), placeholders);
                const int fromRealJsons = g_placeholderWarnings;
                VersionArguments::substitutePlaceholders(QStringLiteral("--clientId ${clientid}"),
                                                         QHash<QString, QString>());
                const int afterProbe = g_placeholderWarnings;
                qInstallMessageHandler(previous);
                check(fromRealJsons == 0,
                      "V6h 两份真原版 json 过一遍 extraGameArguments()：一句占位符警告都没有"
                      "（替换排在过滤之后 —— 原来这里每次启动刷 10~11 条）",
                      QStringLiteral("%1 条；两次都回空表（%2 / %3 项）")
                          .arg(fromRealJsons)
                          .arg(vanillaArgs.size())
                          .arg(legacyArgs.size()));
                check(afterProbe == fromRealJsons + 1,
                      "V6h 自检：这个计数器确实数得到那条警告（不然上面那条是白绿）",
                      QStringLiteral("%1 → %2").arg(fromRealJsons).arg(afterProbe));
            }
            // Fabric 的 profile 自己不带游戏参数，合并之后 arguments.game 里只剩原版那一套 ——
            // 生产那条路喂给它的正是合并后的这份。
            const QJsonObject fabricProfile =
                loadJson(metaDir + "/fabric-loader-0.19.5-1.19.json");
            const QJsonObject fabricVanilla = loadJson(metaDir + "/1.19.json");
            check(!fabricProfile.isEmpty() && !fabricVanilla.isEmpty(),
                  "V6h Fabric + 它依赖的那份原版都读到了");
            check(VersionArguments::extraGameArguments(
                      VersionInheritance::merge(fabricProfile, fabricVanilla), QStringList(),
                      placeholders)
                          .isEmpty(),
                  "V6h Fabric 合并之后也不加（它的东西都在 arguments.jvm 里）");

            // 规则对象照旧复用 LibraryRules：命中的留下、不命中的整条丢掉。
            QJsonObject ruled;
            ruled[QStringLiteral("inheritsFrom")] = QStringLiteral("1.26");
            QJsonObject ruledArguments;
            QJsonArray ruledGame;
            QJsonObject linuxEntry;
            linuxEntry[QStringLiteral("rules")] =
                QJsonArray{QJsonObject{{QStringLiteral("action"), QStringLiteral("allow")},
                                       {QStringLiteral("os"),
                                        QJsonObject{{QStringLiteral("name"),
                                                     QStringLiteral("linux")}}}}};
            linuxEntry[QStringLiteral("value")] = QStringLiteral("--fml.linuxOnly");
            QJsonObject windowsEntry;
            windowsEntry[QStringLiteral("rules")] =
                QJsonArray{QJsonObject{{QStringLiteral("action"), QStringLiteral("allow")},
                                       {QStringLiteral("os"),
                                        QJsonObject{{QStringLiteral("name"),
                                                     QStringLiteral("windows")}}}}};
            windowsEntry[QStringLiteral("value")] = QStringLiteral("--launchTarget");
            ruledGame.append(linuxEntry);
            ruledGame.append(windowsEntry);
            ruledGame.append(QStringLiteral("forgeclient"));
            ruledArguments[QStringLiteral("game")] = ruledGame;
            ruled[QStringLiteral("arguments")] = ruledArguments;
            const QStringList ruledOut =
                VersionArguments::extraGameArguments(ruled, QStringList(), placeholders);
            check(ruledOut == QStringList{QStringLiteral("--launchTarget"),
                                          QStringLiteral("forgeclient")},
                  "V6h 规则命中的留下、不命中的丢掉（复用 LibraryRules，没有第二份规则逻辑）",
                  ruledOut.join(QLatin1Char(' ')));

            // 老格式（1.12.2 那一代 Forge 的 minecraftArguments）：原版那套名字一个都不重复，
            // 加载器自己的 --tweakClass 得带上。
            QJsonObject legacyForge;
            legacyForge[QStringLiteral("inheritsFrom")] = QStringLiteral("1.12.2");
            legacyForge[QStringLiteral("minecraftArguments")] =
                QStringLiteral("--username ${auth_player_name} --version ${version_name} "
                               "--gameDir ${game_directory} --assetsDir ${assets_root} "
                               "--assetIndex ${assets_index_name} --uuid ${auth_uuid} "
                               "--accessToken ${auth_access_token} --userType ${user_type} "
                               "--tweakClass net.minecraftforge.fml.common.launcher.FMLTweaker");
            const QStringList legacyOut = VersionArguments::extraGameArguments(
                VersionInheritance::merge(legacyForge, vanillaLegacy), QStringList(),
                placeholders);
            check(legacyOut ==
                      QStringList{QStringLiteral("--tweakClass"),
                                  QStringLiteral("net.minecraftforge.fml.common.launcher.FMLTweaker")},
                  "V6h 老格式的 minecraftArguments 也吃：原版那套名字全跳过，--tweakClass 带上",
                  legacyOut.join(QLatin1Char(' ')));
        }
    }

    // --- V6d. 镜像失败时"退一步走官方"的两条边界（2026-09-22 加）----------------
    //
    // 这条兜底原来只有资源索引有（镜像那条 /indexes/<id>.json 实测全 404）。现在
    // **所有**走镜像的下载都能退一步 —— 起因是那次 NeoForge 26.2 的实测验收：兜底让
    // 索引下成之后，失败变成 38 个资源对象，逐条 curl 探出来镜像不是 404，是 302 跳到
    // openbmclapi 的兄弟节点、慢到 30 秒都拿不全（官方同一时刻 1 秒就给）。
    {
        check(!DownloadManager::shouldRecordOfficialFallback(QStringLiteral("https://a/x"), QString()),
              "V6d 调用方没给官方地址 -> 不登记（没有第二条路）");
        check(!DownloadManager::shouldRecordOfficialFallback(QStringLiteral("https://a/x"),
                                            QStringLiteral("https://a/x")),
              "V6d 两个地址一样 -> 不登记（否则等于原样再发一次，白等一个超时）");
        check(DownloadManager::shouldRecordOfficialFallback(
                  DownloadManager::mirrorUrl(
                      QStringLiteral("https://resources.download.minecraft.net/0a/0a1234")),
                  QStringLiteral("https://resources.download.minecraft.net/0a/0a1234")),
              "V6d 镜像地址 + 官方地址（资源对象就是这么登记的）-> 登记",
              DownloadManager::mirrorUrl(
                  QStringLiteral("https://resources.download.minecraft.net/0a/0a1234")));
        check(DownloadManager::shouldRecordOfficialFallback(
                  DownloadManager::mirrorClientJarUrl(QStringLiteral("1.18.2")),
                  QStringLiteral("https://piston-data.mojang.com/v1/objects/xx/client.jar")),
              "V6d 客户端 jar：镜像那条是按版本号拼的，跟官方那条完全不像 -> 登记");
    }

    // --- V6e. 镜像"太慢就先不用"的判据（2026-09-22 加）---------------------------
    //
    // 起因还是那次 NeoForge 26.2 的实测：兜底只认"失败"，可镜像这条链子**不是失败**，
    // 它是 302 跳到一条只有几百字节每秒的链子上、细水长流地掉字节 —— Qt 的
    // setTransferTimeout() 是"不活动超时"，于是既不会失败（等不到兜底）也不会完成，
    // 整条安装就那么挂着（gdb 里主线程空转在事件循环里，三个 socket 挂着、一个文件不落）。
    // 处置是给"走了镜像、而且知道官方那条地址"的回复加一条失速判据 + 一段降级期。
    //
    // 这几条钉的是判据本身（纯函数 + 公开的两个开关），"真慢到触发"那一半只能靠 live
    // 那一跑 —— 本地造不出一条慢慢掉字节的服务器。
    {
        const qint64 kMinBytes = 64 * 1024;

        check(!DownloadManager::mirrorDemotedAt(1000, 0),
              "V6e 从来没降级过（期限 0）-> 不在降级期里");
        check(DownloadManager::mirrorDemotedAt(1000, 2000),
              "V6e 现在还没到期限 -> 在降级期里");
        check(!DownloadManager::mirrorDemotedAt(2000, 2000),
              "V6e 正好到期限那一刻 -> 已经不再是降级期（边界取开）");
        check(!DownloadManager::mirrorDemotedAt(2001, 2000),
              "V6e 期限过了 -> 镜像又能用了");

        check(DownloadManager::mirrorStalled(0, kMinBytes),
              "V6e 一跳一个字节都没进 -> 算没动（连接挂死就是这种）");
        check(DownloadManager::mirrorStalled(kMinBytes - 1, kMinBytes),
              "V6e 差一个字节到下限 -> 算没动");
        check(!DownloadManager::mirrorStalled(kMinBytes, kMinBytes),
              "V6e 正好到下限 -> 不算没动（判据是「不到下限」）");
        check(!DownloadManager::mirrorStalled(400 * 1024, kMinBytes),
              "V6e 一跳 400 KB（官方那条版本清单的水平）-> 不算没动");
        check(DownloadManager::mirrorStalled(-5, kMinBytes),
              "V6e 计数变小（跳转会让 downloadProgress 从头报）-> 按「没动」算，"
              "最多误记一跳，下一跳真在动就会把连击清零");

        // 2026-09-23 加的那一道闸（理由和实测见头文件 countsTowardStallStrike()）：
        // 一跳的进账不到下限**还不够**记 strike，这条回复必须至少收到过一个字节。
        // 上面那条 mirrorStalled(0, ...) 仍然成立 —— 变的不是"0 算不算没动"，
        // 变的是"一条还没开始传的回复该不该被这条判据管"。
        check(!DownloadManager::countsTowardStallStrike(0, 0, kMinBytes),
              "V6e 一个字节都没收到、进账 0 -> **不算**失速（它不是慢，是还没轮到它）");
        check(!DownloadManager::countsTowardStallStrike(0, 10 * 1024 * 1024, kMinBytes),
              "V6e 闸门只看「收到过字节没有」：没收到过的话，进账那一路怎么算都不记 strike");
        check(DownloadManager::countsTowardStallStrike(1, 0, kMinBytes),
              "V6e 收到过 1 个字节之后停住 -> 算失速（细水长流那条链子的真形状）");
        check(DownloadManager::countsTowardStallStrike(1, kMinBytes - 1, kMinBytes),
              "V6e 收到过字节、这一跳差一个字节到下限 -> 算失速");
        check(!DownloadManager::countsTowardStallStrike(1, kMinBytes, kMinBytes),
              "V6e 收到过字节、这一跳到下限 -> 不算失速（闸门不是在 mirrorStalled 上再收紧一次）");
        check(DownloadManager::countsTowardStallStrike(1024, -5, kMinBytes),
              "V6e 收到过字节、计数变小 -> 照样算失速（这条老行为一个字没动）");

        check(DownloadManager::demoteDeadline(400000, 100000) == 400000 +
                  DownloadManager::kMirrorDemoteMs,
              "V6e 上一次降级早就过期了 -> 从现在起重开一段");
        check(DownloadManager::demoteDeadline(1000, 500000) == 500000,
              "V6e 上一次降级还没过期 -> **顺延**（取晚的那个），不会把期限提前");

        // 真对象上的两种状态：降级只影响"往哪走"，不改用户的设置。
        DownloadManager dm;
        const QString assetUrl = QStringLiteral(
            "https://resources.download.minecraft.net/0a/0a1234");
        dm.setUseMirror(true);
        check(dm.mirrorPreferred(), "V6e 选了镜像源、又没降级 -> 走镜像");
        check(dm.endpoint(assetUrl) != assetUrl && dm.endpoint(assetUrl).contains(
                  QStringLiteral("bmclapi")),
              "V6e 这时候 endpoint() 给的是镜像那条", dm.endpoint(assetUrl));
        dm.demoteMirrorForSlowDownload(QStringLiteral("bmclapi2.bangbang93.com"));
        check(dm.isMirrorDemoted(), "V6e 降级镜像源那个主机 -> 就在降级期里");
        check(!dm.mirrorPreferred(), "V6e 降级期里**不再**走镜像");
        check(dm.endpoint(assetUrl) == assetUrl,
              "V6e 降级期里 endpoint() 给回官方那条（只换地址，后面那套记账不用改）",
              dm.endpoint(assetUrl));
        check(dm.useMirror(),
              "V6e 降级**没有**把用户的「下载源」设置改掉（设置里还是镜像源）");
        dm.setUseMirror(false);
        check(dm.endpoint(assetUrl) == assetUrl, "V6e 用户改回官方源 -> 当然还是官方那条");

        // 降级**按主机**（2026-09-23 加）：整合包那条路上"镜像"是每条文件各自的首选地址
        // （Modrinth 清单里给 2~3 条，preferredUrlOrder() 把 cdn.modrinth.com 排前面），
        // 一个全局的降级位会让一个慢 CDN 把别的 CDN 一起关掉 —— 那次事故的现场就是这么垮的：
        // mediafilez 上 8 条不动 -> 全体降级 -> 89% 的字节（1405.9 MB）被赶到慢 CDN 上。
        {
            DownloadManager perHost;
            perHost.setUseMirror(true);
            const QString slowCdn = QStringLiteral("mediafilez.forgecdn.net");
            const QString fastCdn = QStringLiteral("cdn.modrinth.com");
            perHost.demoteMirrorForSlowDownload(slowCdn);
            check(perHost.mirrorDemotedFor(slowCdn), "V6e 按主机降级：那条慢 CDN 确实在降级期里");
            check(!perHost.mirrorDemotedFor(fastCdn),
                  "V6e 按主机降级：**别的 CDN 一点没受影响**（这次事故的判据就是这一条）");
            check(!perHost.mirrorDemotedFor(QString()), "V6e 空主机名 -> 按没降级算");
            check(perHost.mirrorDemotedFor(QStringLiteral("MEDIAFILEZ.forgecdn.net")) == false,
                  "V6e 主机名是区分大小写的串比较（QUrl::host() 给的一律小写，这一条只是钉住"
                  "「不做事先转换」）");
            check(perHost.isMirrorDemoted() == false,
                  "V6e 被降级的那条不是镜像源那个主机 -> 镜像源这一侧照走");
            check(perHost.mirrorPreferred(), "V6e 镜像源没被降级 -> mirrorPreferred() 仍然为真");
            // 顺延是**按主机**各自算的：再降一次慢 CDN 不影响快 CDN 的（本来就没有的）期限。
            perHost.demoteMirrorForSlowDownload(fastCdn);
            check(perHost.mirrorDemotedFor(fastCdn), "V6e 再降另一个主机 -> 各记各的");
            check(perHost.mirrorDemotedFor(slowCdn), "V6e 后降的那个不覆盖先降的那个");
        }
    }

    // --- V6f. 看门狗端到端：挂着不动的那条真的会被掐掉、换官方那条（本地假镜像）------
    //
    // V6e 钉的是判据，这一节把整条链子跑一遍。两个假镜像都给 HTTP 头、body 只给一点点
    // 就不给了，它们对应真慢链子的两种形状：
    //   (a) 细水长流：吐了一小口（够不着"一跳 64 KB"那条下限）就停住 —— 镜像那条 302 到
    //       MinIO 的链子就是这个形状（实测 0.85~10 KB/s），**这一种该被看门狗在 10 秒判掉**；
    //   (b) 一个字节都不吐。这一种**不该**被判失速（它可能只是还没轮到它、还在建连或排在
    //       一条 h2 连接的队列里），该由 Qt 那条 30 秒的不活动超时收尾，照样走"退回官方、
    //       不算失败"那条路（2026-09-23 加的判据，理由见 countsTowardStallStrike()）。
    // "官方那条"给成 file://（一个真文件），所以这两条用例**都不碰外网**，在哪台机器上跑
    // 都是同一个结果；顺带证明了 abort / 超时之后那次重发真的走通了。
    // 代价：十来秒（看门狗两跳）+ 三十秒（等 Qt 那条超时），是这套里仅有的按秒计的用例。
    {
        QTemporaryDir scratch(QDir::tempPath() + "/wtfml_stallwatch-XXXXXX");
        check(scratch.isValid(), "V6f 临时目录建出来了");
        QTcpServer fakeMirror;
        const bool listening = fakeMirror.listen(QHostAddress::LocalHost, 0);
        check(listening, "V6f 本地假镜像起来了（起不来这条用例就没意义，直接算失败）");
        if (scratch.isValid() && listening) {
            // 细水长流：请求读掉，回一个 Content-Length 很大、body 只给 1 KB 的响应，
            // 然后**再也不给**（连接也不关 —— 关了 Qt 会当成"传完了"）。
            // 那 1 KB 是关键：一个字节都没收到过的回复按新判据不记 strike，这一条就变成
            // (b) 那个形状了（下面单独有用例钉住）。
            QObject::connect(&fakeMirror, &QTcpServer::newConnection, &fakeMirror, [&fakeMirror] {
                while (QTcpSocket *s = fakeMirror.nextPendingConnection()) {
                    s->setParent(&fakeMirror);
                    QObject::connect(s, &QTcpSocket::readyRead, s, [s]() {
                        if (s->property("answered").toBool()) {
                            return;
                        }
                        s->setProperty("answered", true);
                        s->readAll();
                        s->write("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\n"
                                 "Content-Length: 1000000\r\n\r\n");
                        s->write(QByteArray(1024, 'x'));
                        s->flush();
                    });
                }
            });

            const QString officialPath = scratch.path() + "/official.txt";
            const QByteArray body = QByteArrayLiteral("official-source-payload");
            {
                QFile f(officialPath);
                check(f.open(QIODevice::WriteOnly) && f.write(body) == body.size(),
                      "V6f 官方那条（一个真文件）写好了");
            }

            const QString mirrorUrl = QStringLiteral("http://127.0.0.1:%1/pretend-mirror")
                                          .arg(fakeMirror.serverPort());
            const QString destPath = scratch.path() + "/out.txt";
            const QString sha1 = QString::fromLatin1(
                QCryptographicHash::hash(body, QCryptographicHash::Sha1).toHex());

            DownloadManager dm;
            dm.setUseMirror(true);
            QEventLoop loop;
            bool finished = false;
            bool ok = false;
            QString failure;
            QObject::connect(&dm, &DownloadManager::allDownloadsFinished, &loop,
                             [&](bool success) {
                                 finished = true;
                                 ok = success;
                                 loop.quit();
                             });
            QObject::connect(&dm, &DownloadManager::downloadFinished, &loop,
                             [&](const QString &, bool success, const QString &m) {
                                 if (!success) {
                                     failure = m;
                                 }
                             });
            QElapsedTimer elapsed;
            elapsed.start();
            dm.beginBatch();
            dm.downloadFile(mirrorUrl, destPath, sha1, body.size(), VerifyMode::SizeAndSha1,
                            QUrl::fromLocalFile(officialPath).toString());
            dm.endBatch();
            // 兜底：真卡住也不能让验证工程自己挂在这儿（看门狗那两跳一共 10 秒）。
            QTimer::singleShot(60000, &loop, &QEventLoop::quit);
            loop.exec();
            const qint64 tookMs = elapsed.elapsed();

            check(finished, "V6f 这条下载有终态（没终态 = 挂住了，整批都不动了）");
            check(dm.mirrorDemotedFor(QStringLiteral("127.0.0.1")),
                  "V6f 假镜像细水长流了 10 秒 -> **那个主机**被降级（降级是按主机记的，"
                  "所以问的是 127.0.0.1 而不是镜像源那个主机）");
            check(ok, "V6f 退回官方那条之后下成了", failure);
            QFile out(destPath);
            check(out.exists(), "V6f 文件真的落盘了", destPath);
            check(out.open(QIODevice::ReadOnly) && out.readAll() == body,
                  "V6f 落盘的内容就是官方那条给的（不是假镜像那份半截 body）");
            check(tookMs >= 8000 && tookMs < 45000,
                  "V6f 是「等两跳才退」那个时间（10 秒上下：不是立刻退，也没等到 30 秒超时）",
                  QStringLiteral("%1 ms").arg(tookMs));
        }

        // (b) 一个字节都不吐的假镜像：**不该**被判失速（2026-09-23 那次 422 个文件的导入就是
        //     因为"还没收到第一个字节也算失速"垮掉的：头一批里 8 条两跳就被判"镜像太慢"，
        //     然后整个主机被降级 300 秒）。它该由 Qt 那条 30 秒的不活动超时收尾，照样退回
        //     官方、照样下成 —— 这一条同时钉住"少了那条判据不会把整批挂死"。
        QTcpServer silentMirror;
        const bool silentListening = silentMirror.listen(QHostAddress::LocalHost, 0);
        check(silentListening, "V6f 第二个假镜像（只 accept、一个字节都不发）起来了");
        if (scratch.isValid() && silentListening) {
            QObject::connect(&silentMirror, &QTcpServer::newConnection, &silentMirror,
                             [&silentMirror] {
                                 silentMirror.nextPendingConnection()->setParent(&silentMirror);
                             });

            const QString officialPath = scratch.path() + "/official2.txt";
            const QByteArray body2 = QByteArrayLiteral("official-source-payload-2");
            {
                QFile f(officialPath);
                check(f.open(QIODevice::WriteOnly) && f.write(body2) == body2.size(),
                      "V6f 官方那条（第二个真文件）写好了");
            }

            DownloadManager dm2;
            dm2.setUseMirror(true);
            QEventLoop loop;
            bool finished = false;
            bool ok = false;
            QString failure;
            QObject::connect(&dm2, &DownloadManager::allDownloadsFinished, &loop,
                             [&](bool success) {
                                 finished = true;
                                 ok = success;
                                 loop.quit();
                             });
            QObject::connect(&dm2, &DownloadManager::downloadFinished, &loop,
                             [&](const QString &, bool success, const QString &m) {
                                 if (!success) {
                                     failure = m;
                                 }
                             });
            QElapsedTimer elapsed;
            elapsed.start();
            dm2.beginBatch();
            dm2.downloadFile(QStringLiteral("http://127.0.0.1:%1/silent-mirror")
                                 .arg(silentMirror.serverPort()),
                             scratch.path() + "/out2.txt",
                             QString::fromLatin1(
                                 QCryptographicHash::hash(body2, QCryptographicHash::Sha1).toHex()),
                             body2.size(), VerifyMode::SizeAndSha1,
                             QUrl::fromLocalFile(officialPath).toString());
            dm2.endBatch();
            // 兜底：真卡住也不能让验证工程自己挂在这儿（等的是 Qt 那条 30 秒的不活动超时）。
            QTimer::singleShot(90000, &loop, &QEventLoop::quit);
            loop.exec();
            const qint64 tookMs = elapsed.elapsed();

            check(finished, "V6f 一个字节都不吐的那条也有终态（没被误判，也没挂住）");
            check(!dm2.mirrorDemotedFor(QStringLiteral("127.0.0.1")),
                  "V6f 一个字节都没收到过 -> **没有**被判失速、那个主机也没被降级");
            check(ok, "V6f 它照样退回官方那条下成了", failure);
            QFile out2(scratch.path() + "/out2.txt");
            check(out2.exists() && out2.open(QIODevice::ReadOnly) && out2.readAll() == body2,
                  "V6f 落盘的内容就是官方那条给的");
            check(tookMs >= 25000 && tookMs < 80000,
                  "V6f 走的是 Qt 那条 30 秒不活动超时（不是 10 秒那条看门狗判据）",
                  QStringLiteral("%1 ms").arg(tookMs));
        }
    }

    // --- V6i. 发出去的请求有上限 / 卡死的回复会被判失败（2026-09-22 加）----------
    //
    // 这一节钉的是"一次 422 个文件的整合包导入把整批挂死"那两个真因。当时的现场：
    // 422 个请求一次性全交给 QNetworkAccessManager → Qt 每个主机只开 6 条连接，其余在它
    // 内部排队（30 秒的传输超时从请求建好就开始算）→ 排在后面的回复一个字节都收不到 →
    // 失速看门狗两跳（10 秒）把它们全判成"镜像太慢"并重发 → 重发又是几百条一起发 →
    // 最后整批再也不动：进度条停在 1%、没有错误、没有弹窗，用户只能重启。
    //
    // 两条都在本地跑：假服务器只 accept、一个字节都不发，一次外网都不碰。
    {
        // (1) 判据本身（纯函数）：到顶之后**不管还排着多少条**都不发。
        //
        // 上限写成 kMaxConcurrentDownloads 而不是那个字面数字：这一节验的是**规则**
        // （到顶就不发、不管排着多少），不是"这个数等于几"。2026-09-23 把上限从 6 调到 24
        // （见那个常量上的实测记录）时，正是这几行证明"改的只是个数、规则一个字没动"。
        constexpr int kCap = DownloadManager::kMaxConcurrentDownloads;
        check(!DownloadManager::mayIssueAnotherDownload(0, 0),
              "V6i 队列是空的 -> 没有什么可发");
        check(DownloadManager::mayIssueAnotherDownload(0, 1),
              "V6i 队列里有一条、连接空着 -> 发");
        check(DownloadManager::mayIssueAnotherDownload(kCap - 1, 1),
              "V6i 第 kCap 条还能发（0 起算 = kCap-1）",
              QStringLiteral("kCap=%1").arg(kCap));
        check(!DownloadManager::mayIssueAnotherDownload(kCap, 1),
              "V6i 到顶了 -> 不发（哪怕队列里还排着一条）",
              QStringLiteral("kCap=%1").arg(kCap));
        check(!DownloadManager::mayIssueAnotherDownload(kCap, 10000),
              "V6i 到顶了、还排着一万条 -> 一条都不发（挂死那次的形状）");
        check(!DownloadManager::mayIssueAnotherDownload(kCap + 1, 3),
              "V6i 超过了也不发");
    }

    // (1b) 判据本身（纯函数）：**按主机**那一条（2026-09-23 加，把上限从 6 调到 24 时补的）。
    //
    // 全局放 24 条之后，"排队必须发生在我们自己手里"这条不变量在**单个主机**上会被打破：
    // 一个走 h1.1 的主机，Qt 只认 6 条连接，第 7 条开始进 Qt 内部那个会超时的队列
    // （本地实测：24 路放给一个每条 12 秒才回的 h1.1 假服务器，40 条作业里 28 条
    // `Operation timed out`）。所以没证明自己走 h2 的主机只能放 6 条 —— 这个 6 就是
    // Qt 每主机的连接上限，正好是"我们发出去的都拿得到连接"的最大条数。
    {
        constexpr int kHostCap = DownloadManager::kMaxConcurrentPerHost;
        check(DownloadManager::mayIssueAnotherDownloadToHost(0, false),
              "V6i 这个主机还没证明过 h2、当下一条都没有 -> 发");
        check(DownloadManager::mayIssueAnotherDownloadToHost(kHostCap - 1, false),
              "V6i 还没证明过 h2、到第 kHostCap-1 条 -> 还能发",
              QStringLiteral("kHostCap=%1").arg(kHostCap));
        check(!DownloadManager::mayIssueAnotherDownloadToHost(kHostCap, false),
              "V6i 还没证明过 h2 的主机放满 kHostCap 条 -> 不发（多发的会进 Qt 那个会超时的队列）",
              QStringLiteral("kHostCap=%1").arg(kHostCap));
        check(!DownloadManager::mayIssueAnotherDownloadToHost(kHostCap + 5, false),
              "V6i 一个没证明过 h2 的主机超了 -> 更不发");
        check(DownloadManager::mayIssueAnotherDownloadToHost(kHostCap, true),
              "V6i 证明过 h2 了 -> 这条判据不再管它（放几条归全局上限）",
              QStringLiteral("kHostCap=%1").arg(kHostCap));
        check(DownloadManager::mayIssueAnotherDownloadToHost(1000, true),
              "V6i 证明过 h2 的主机上一千条在飞也不管（流多路复用，不是连接）");
    }

    // (2) 端到端：一次排进去**比上限多得多**的作业，真正被交给 Qt 的只有按主机允许的那几条。
    //
    // NOTE: 作业数必须**超过**上限，否则这条用例会退化成"全都发出去了也算过"。上限从 6 改成
    //       24 那次就踩过这个：原来写死的 20 条在新上限下一条都不会排队，用例还照样绿。
    //
    // 【为什么非要**两台**假服务器】单看一台是量不出按主机那条判据的：Qt 自己对每个
    //   host:port 也只开 6 条连接，所以"我们拦住了"和"Qt 拦住了"这两种情况在那台服务器上
    //   看到的都是 6 条 —— 那么写的话，把判据整个删掉也照样绿（2026-09-23 加这条时就是为了
    //   躲开这个：**断言要量"由我们自己决定"的那一格**）。两个端口就不一样了：Qt 的 6 条是
    //   **每个 host:port** 各算各的（敢给的话它开 6 + 6 = 12 条），而我们的判据按**主机名**
    //   算（同一个 127.0.0.1，两个端口合起来只有 6 条）。于是"两台服务器上一共挂了几条连接"
    //   这一格由我们说了算：6 = 判据在，12 = 判据被删了。
    //
    // 这条同时是那次挂死的**直接**回归测试：改之前几百条会一个不落地全建连（422 条就是
    // 422 条），改之后多出来的留在我们自己的队列里 —— 只有"在我们手里排"才谈得上后面那些
    // 看门狗判据。
    {
        QTcpServer floodA;
        QTcpServer floodB;
        const bool floodListening = floodA.listen(QHostAddress::LocalHost, 0)
                                    && floodB.listen(QHostAddress::LocalHost, 0);
        check(floodListening, "V6i 两个假服务器都起来了（起不来这条用例就没意义，直接算失败）");
        if (floodListening) {
            // 只接不回：连上的那些就一直挂着（"收不到一个字节"那种回复）。
            const auto hold = [](QTcpServer *server) {
                QObject::connect(server, &QTcpServer::newConnection, server,
                                 [server] { server->nextPendingConnection()->setParent(server); });
            };
            hold(&floodA);
            hold(&floodB);
            QTemporaryDir floodDir(QDir::tempPath() + "/wtfml_flood-XXXXXX");
            check(floodDir.isValid(), "V6i 落盘用的临时目录建出来了");
            if (floodDir.isValid()) {
                {
                    DownloadManager dm;
                    QEventLoop spin;
                    const int jobs = DownloadManager::kMaxConcurrentDownloads * 2;
                    dm.beginBatch();
                    for (int i = 0; i < jobs; ++i) {
                        // 两个端口交替：两个主机名相同、端口不同 —— 正是上面说的那个形状。
                        const quint16 port = (i % 2 == 0) ? floodA.serverPort() : floodB.serverPort();
                        dm.downloadFile(QStringLiteral("http://127.0.0.1:%1/mod%2.jar")
                                            .arg(port)
                                            .arg(i),
                                        floodDir.path() + QStringLiteral("/mod%1.jar").arg(i));
                    }
                    dm.endBatch();
                    // 给 Qt 一点时间把连接建起来（它自己的超时是 30 秒，这里只等 0.7 秒）。
                    QTimer::singleShot(700, &spin, &QEventLoop::quit);
                    spin.exec();
                    const int sockets = floodA.findChildren<QTcpSocket *>().size()
                                        + floodB.findChildren<QTcpSocket *>().size();
                    out() << "        " << jobs << " 条作业 -> 两个端口的假服务器上一共挂着 "
                          << sockets << " 条连接（按主机上限 "
                          << DownloadManager::kMaxConcurrentPerHost << "；判据没了的话是 "
                          << DownloadManager::kMaxConcurrentPerHost * 2 << "）\n";
                    check(sockets >= 1, "V6i 至少真发出去了一条（不是整批都没动）",
                          QStringLiteral("connections=%1").arg(sockets));
                    check(sockets <= DownloadManager::kMaxConcurrentPerHost,
                          "V6i 一次发出去的作业比上限多 -> 多出来的排在我们自己的队列里"
                          "（同一个主机名的两个端口合起来也只放 kMaxConcurrentPerHost 条）",
                          QStringLiteral("connections=%1").arg(sockets));
                    // 这时候整批当然还没完（6 条挂着、42 条排着）：界面不该解禁。
                    check(dm.isBusy(), "V6i 队列里还有活儿的时候 isBusy() 为真");
                }
            }
        }
    }

    // (3) 端到端：一条**没有备用地址**、发出去之后一个字节都收不到的下载，到点会被判失败。
    //
    // 这一条是 V6f 的另一半。V6f 那种回复有退路（走镜像 + 知道官方那条地址），看门狗 10 秒
    // 就 abort 它换一条路；**没有**退路的那些以前是没人管的 —— 而它一旦永远不结束，
    // pendingDownloads 就永远归不了零，整批永远收不了尾（那次挂死的就是这一类）。
    {
        QTcpServer deadServer;
        const bool deadListening = deadServer.listen(QHostAddress::LocalHost, 0);
        check(deadListening, "V6i 第二个假服务器起来了（这条用来验卡死兜底）");
        if (deadListening) {
            QObject::connect(&deadServer, &QTcpServer::newConnection, &deadServer,
                             [&deadServer] {
                                 deadServer.nextPendingConnection()->setParent(&deadServer);
                             });
            QTemporaryDir deadDir(QDir::tempPath() + "/wtfml_wedged-XXXXXX");
            check(deadDir.isValid(), "V6i 卡死那条的临时目录建出来了");
            if (deadDir.isValid()) {
                const QString destPath = deadDir.path() + "/never.jar";
                DownloadManager dm;
                // 真机上这个期限是 90 秒（看门狗两跳的九倍），逐条用例等不起，压到 3 秒。
                dm.setNoProgressGiveUpMs(3000);
                bool finished = false;
                bool ok = true;
                QString failure;
                QEventLoop loop;
                QObject::connect(&dm, &DownloadManager::allDownloadsFinished, &loop,
                                 [&](bool success) {
                                     finished = true;
                                     ok = success;
                                     loop.quit();
                                 });
                QObject::connect(&dm, &DownloadManager::downloadFinished, &loop,
                                 [&](const QString &, bool success, const QString &m) {
                                     if (!success) {
                                         failure = m;
                                     }
                                 });
                QElapsedTimer elapsed;
                elapsed.start();
                dm.beginBatch();
                dm.downloadFile(QStringLiteral("http://127.0.0.1:%1/never.jar")
                                    .arg(deadServer.serverPort()),
                                destPath);
                dm.endBatch();
                // 兜底：真卡住也不能让验证工程自己挂在这儿。
                QTimer::singleShot(30000, &loop, &QEventLoop::quit);
                loop.exec();
                const qint64 tookMs = elapsed.elapsed();

                check(finished, "V6i 没有备用地址、又收不到字节的那条也有终态（以前它能永远挂着）");
                check(!ok, "V6i 它被判成失败（不是「什么都没发生」）");
                check(dm.stats().failed == 1, "V6i 失败数记上了",
                      QString::number(dm.stats().failed));
                check(failure.contains(QStringLiteral("gave up")),
                      "V6i 失败原因说的是「等不到数据、放弃了」", failure);
                check(!QFile::exists(destPath), "V6i 没有落下半个文件", destPath);
                check(tookMs >= 2500 && tookMs < 25000,
                      "V6i 是「到点才判」那个时间（不是立刻失败，也不是等到 30 秒传输超时）",
                      QStringLiteral("%1 ms").arg(tookMs));
                check(!dm.isBusy(), "V6i 收尾之后不忙了 —— 界面不会永远停在「下载中」");
            }
        }
    }

    // --- V7. 安装完之后的产物核对 + launcher_profiles ---------------------------
    //
    // 这两条是"退出码 0 不等于装好了"那一道闸。退出码是安装器自己说了算的，而**磁盘上
    // 那份 json** 才是别的启动器和我们的启动路径要读的东西。
    {
        const auto produced = [](const QString &id, const QString &parent) {
            QJsonObject json;
            if (!id.isNull()) {
                json.insert(QStringLiteral("id"), id);
            }
            if (!parent.isNull()) {
                json.insert(QStringLiteral("inheritsFrom"), parent);
            }
            return json;
        };
        const QString forgeId = LoaderMeta::forgeLoaderId(QStringLiteral("1.20.1"),
                                                          QStringLiteral("47.4.10"));

        const LoaderMeta::ProfileCheck good =
            LoaderMeta::checkInstallerResult(produced(forgeId, QStringLiteral("1.20.1")),
                                             QStringLiteral("1.20.1"), forgeId);
        check(good.ok(), "V7 id 和 inheritsFrom 都对 -> 认它装好了",
              QStringLiteral("%1 / %2").arg(good.id, good.parent));

        const LoaderMeta::ProfileCheck renamed =
            LoaderMeta::checkInstallerResult(produced(QStringLiteral("1.20.1-forge-47.4.23"),
                                                      QStringLiteral("1.20.1")),
                                             QStringLiteral("1.20.1"), forgeId);
        check(renamed.problem == LoaderMeta::ProfileProblem::BadId,
              "V7 安装器哪天换了命名约定（id 和我们算的目录名对不上）-> 不认",
              renamed.id);

        // 目录名合法但安装器认的是另一个父版本：装是装上了，但它基于的不是用户选的那个。
        const LoaderMeta::ProfileCheck otherParent =
            LoaderMeta::checkInstallerResult(produced(forgeId, QStringLiteral("1.20.4")),
                                             QStringLiteral("1.20.1"), forgeId);
        check(otherParent.problem == LoaderMeta::ProfileProblem::WrongParent,
              "V7 装出来的版本基于另一个原版 -> 不认（启动时它去找那个原版，用户不知道）",
              otherParent.parent);

        // 空 json / 只有一半：走同一条路，别崩。
        check(LoaderMeta::checkInstallerResult(QJsonObject(), QStringLiteral("1.20.1"), forgeId)
                      .problem == LoaderMeta::ProfileProblem::BadId &&
                  LoaderMeta::checkInstallerResult(produced(forgeId, QStringLiteral("1.20.1")),
                                                   QStringLiteral("1.20.1"), QString())
                          .problem == LoaderMeta::ProfileProblem::BadId,
              "V7 空 json / 期望 id 是空的 -> BadId，不是崩");

        // launcher_profiles.json：安装器的硬前置（缺了它安装器直接拒绝干活）。我们只在
        // 它不存在时才补一份 —— 已有的那份里可能是用户真正的启动器档案。
        check(LoaderMeta::launcherProfilesFileName() == QStringLiteral("launcher_profiles.json"),
              "V7 前置文件名");
        const QJsonObject minimal =
            QJsonDocument::fromJson(LoaderMeta::minimalLauncherProfiles()).object();
        check(minimal.value(QStringLiteral("version")).toInt() == 3 &&
                  minimal.value(QStringLiteral("profiles")).isObject() &&
                  minimal.value(QStringLiteral("settings")).isObject(),
              "V7 补的那份是能解析的 JSON，且带着安装器认的那三个键",
              QString::fromUtf8(LoaderMeta::minimalLauncherProfiles()).left(60));
    }

    // --- V8. OptiFine：版本表得从"网页"里读出来 --------------------------------
    //
    // 这一节整节拿**真数据**验（三份 OptiFine fixture 见本函数开头那份清单）。OptiFine
    // 和另外三个加载器最不一样的地方就在这儿：它**没有一份规整的版本表接口** —— 镜像那边
    // 是一条 JSON 数组（正式版和预览版混在一起），官方那边只有一张给人看的下载页（203 KB
    // 的 HTML，53 个游戏版本各一节，每节里"正式版/预览版/旧版本"三类行混排）。所以"挑哪
    // 一个"这件事全是从网页里抠出来的，也正是最该拿真页面钉住的地方。
    {
        // --- V8.1 地址怎么拼（四条都真发过请求）---
        check(LoaderMeta::optifineDownloadsPageUrl() ==
                  QStringLiteral("https://optifine.net/downloads"),
              "V8.1 官方下载页地址", LoaderMeta::optifineDownloadsPageUrl());
        check(LoaderMeta::optifineMirrorListUrl(QStringLiteral("1.18.2")) ==
                  QStringLiteral("https://bmclapi2.bangbang93.com/optifine/1.18.2"),
              "V8.1 镜像的版本表地址（一个游戏版本一页）",
              LoaderMeta::optifineMirrorListUrl(QStringLiteral("1.18.2")));
        check(LoaderMeta::optifineMirrorFileUrl(QStringLiteral("1.18.2"), QStringLiteral("HD_U"),
                                                QStringLiteral("H9")) ==
                  QStringLiteral("https://bmclapi2.bangbang93.com/optifine/1.18.2/HD_U/H9"),
              "V8.1 镜像的文件地址最后两段是 type/patch（**不是**文件名）",
              LoaderMeta::optifineMirrorFileUrl(QStringLiteral("1.18.2"), QStringLiteral("HD_U"),
                                                QStringLiteral("H9")));
        check(LoaderMeta::optifineAdPageUrl(QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar")) ==
                  QStringLiteral("https://optifine.net/adloadx?f=OptiFine_1.18.2_HD_U_H9.jar"),
              "V8.1 官方那条路上的广告页地址",
              LoaderMeta::optifineAdPageUrl(QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar")));

        // --- V8.2 文件名白名单：它要落成盘上一个文件、也要拼进地址 ---
        check(LoaderMeta::isSafeJarFileName(QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar")) &&
                  LoaderMeta::isSafeJarFileName(
                      QStringLiteral("preview_OptiFine_1.18.2_HD_U_H9_pre2.jar")) &&
                  LoaderMeta::isSafeJarFileName(
                      QStringLiteral("forge-1.20.1-47.4.10-installer.jar")),
              "V8.2 真文件名都放行（正式版 / 预览版 / Forge 那个）");
        check(!LoaderMeta::isSafeJarFileName(QStringLiteral("../x.jar")) &&
                  !LoaderMeta::isSafeJarFileName(QStringLiteral("a/b.jar")) &&
                  !LoaderMeta::isSafeJarFileName(QStringLiteral("a\\b.jar")) &&
                  !LoaderMeta::isSafeJarFileName(QStringLiteral("x.jar?x=1")) &&
                  !LoaderMeta::isSafeJarFileName(QStringLiteral("x.jar.exe")) &&
                  !LoaderMeta::isSafeJarFileName(QStringLiteral("上.jar")) &&
                  !LoaderMeta::isSafeJarFileName(QStringLiteral("x.jar ")) &&
                  !LoaderMeta::isSafeJarFileName(QStringLiteral("x.zip")) &&
                  !LoaderMeta::isSafeJarFileName(QString()),
              "V8.2 带路径 / 带参数 / 中文 / 尾空格 / 空 / 不是 .jar 的一律拒绝");
        check(LoaderMeta::isOptifinePreviewFile(
                  QStringLiteral("preview_OptiFine_1.18.2_HD_U_H9_pre2.jar")) &&
                  !LoaderMeta::isOptifinePreviewFile(
                      QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar")),
              "V8.2 预览版靠文件名前缀认（真数据里就是这一条把 11 条筛掉了 8 条）");

        // --- V8.3 安装器文件名 -> 版本号（要写进 wtfml.meta、也要和目录名对得上）---
        const auto editionOf = [](const QString &mc, const QString &file) {
            return LoaderMeta::optifineEditionFromFile(mc, file);
        };
        check(editionOf(QStringLiteral("1.18.2"),
                        QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar")) ==
                  QStringLiteral("HD_U_H9"),
              "V8.3 OptiFine_1.18.2_HD_U_H9.jar -> HD_U_H9",
              editionOf(QStringLiteral("1.18.2"), QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar")));
        check(editionOf(QStringLiteral("1.18.2"),
                        QStringLiteral("preview_OptiFine_1.18.2_HD_U_H9_pre2.jar")) ==
                  QStringLiteral("HD_U_H9_pre2"),
              "V8.3 预览版切出来是 HD_U_H9_pre2（和镜像那份 type=HD_U_H9 + patch=pre2 对得上）",
              editionOf(QStringLiteral("1.18.2"),
                        QStringLiteral("preview_OptiFine_1.18.2_HD_U_H9_pre2.jar")));
        // 换个游戏版本就得换前缀切 —— 切法只有这一处，官方/镜像两条路才切得同一个值。
        check(editionOf(QStringLiteral("1.8.9"), QStringLiteral("OptiFine_1.8.9_HD_U_M5.jar")) ==
                  QStringLiteral("HD_U_M5"),
              "V8.3 换一个游戏版本（1.8.9 -> HD_U_M5）",
              editionOf(QStringLiteral("1.8.9"), QStringLiteral("OptiFine_1.8.9_HD_U_M5.jar")));

        // --- V8.4 官方下载页：稳定档认 downloadLineMain，最新档认最上面那条 ------
        QFile downloadsFile(metaDir + "/optifine-downloads.html");
        QByteArray downloads;
        if (downloadsFile.open(QIODevice::ReadOnly)) {
            downloads = downloadsFile.readAll();
        }
        check(downloads.size() > 100000, "V8.4 真下载页读到了",
              QString("%1 字节").arg(downloads.size()));
        if (!downloads.isEmpty()) {
            const QString html = QString::fromUtf8(downloads);
            const auto pickFromPage = [&html](const QString &mc) {
                return LoaderMeta::pickOptifineFromDownloadsPage(html, mc);
            };
            const auto pickNewest = [&html](const QString &mc) {
                return LoaderMeta::pickOptifineFromDownloadsPage(html, mc,
                                                                 LoaderMeta::LoaderChannel::Newest);
            };

            // 实测 1.18.2 那一节：正文（downloadLineMain）是 H9，折叠在「+ More」里的两条是
            // H7/H6，**这一节里没有预览版**。挑成 H7/H6 就是"给用户默默装了个旧版本"。
            const LoaderMeta::OptiFinePick pick1182 = pickFromPage(QStringLiteral("1.18.2"));
            check(pick1182.ok() &&
                      pick1182.fileName == QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar"),
                  "V8.4 1.18.2 稳定档 -> H9（More 里那两条 H7/H6 不能要）", pick1182.fileName);
            // 这一节里没有预览版，所以**两档挑出来的是同一个** —— 这正是"换了档才会不一样"
            // 那条分界的反证：不看数据就没法知道哪一版有这个区别。
            check(pickNewest(QStringLiteral("1.18.2")).fileName ==
                      QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar"),
                  "V8.4 1.18.2 最新档也是 H9（这一节里没有预览版）",
                  pickNewest(QStringLiteral("1.18.2")).fileName);

            // 1.8.9 那一节更狠：预览版（M6-pre2/pre1）排在最前面，正文是 M5，More 里还有一堆
            // 旧版本。稳定档必须挑 M5；最新档挑的**就是**最上面那条预览版（用户 2026-09-23
            // 拍板："beta 版虽然不稳定，但是也能使用，要列出来"——预览版同理）。
            const LoaderMeta::OptiFinePick pick189 = pickFromPage(QStringLiteral("1.8.9"));
            check(pick189.ok() &&
                      pick189.fileName == QStringLiteral("OptiFine_1.8.9_HD_U_M5.jar"),
                  "V8.4 1.8.9 稳定档 -> M5（那一节最前面是预览版 M6-pre2，不能要）",
                  pick189.fileName);
            const LoaderMeta::OptiFinePick newest189 = pickNewest(QStringLiteral("1.8.9"));
            check(newest189.fileName ==
                      QStringLiteral("preview_OptiFine_1.8.9_HD_U_M6_pre2.jar"),
                  "V8.4 1.8.9 最新档 -> 最上面那条预览版 M6-pre2", newest189.fileName);
            // ★ 两档挑出来的**必须是不同的文件**：这一节就是"多一档"这件事在真数据上的证据。
            check(newest189.fileName != pick189.fileName,
                  "V8.4 1.8.9 上两档挑出不同版本（稳定 M5 / 最新 M6-pre2）");

            // 只有预览版、还没发正式版的游戏版本：那一节里**根本没有 main 行** ——
            // 稳定档挑不出来（由调用方报"还没有支持这个版本的正式版"），**最新档挑得出来**
            // （2026-09-23 之前这里两档都挑不出来，预览版也装不了；现在装得下去了）。
            check(!pickFromPage(QStringLiteral("1.21.8")).ok() &&
                      !pickFromPage(QStringLiteral("26.1.2")).ok(),
                  "V8.4 只有预览版的版本（1.21.8 / 26.1.2）稳定档挑不出来");
            check(pickNewest(QStringLiteral("1.21.8")).fileName ==
                      QStringLiteral("preview_OptiFine_1.21.8_HD_U_J6_pre16.jar") &&
                      pickNewest(QStringLiteral("26.1.2")).fileName ==
                          QStringLiteral("preview_OptiFine_26.1.2_HD_U_K1_pre2.jar"),
                  "V8.4 同一批版本最新档挑得出预览版（1.21.8 -> J6_pre16 / 26.1.2 -> K1_pre2）",
                  QStringLiteral("%1 / %2")
                      .arg(pickNewest(QStringLiteral("1.21.8")).fileName,
                           pickNewest(QStringLiteral("26.1.2")).fileName));

            // 1.21.4 那一节：预览版 J4_pre2/J4_pre1 在前、正式版 J3 在后 —— 两档在这一节上
            // 分开（和 1.8.9 同理，只是这里的是"预览版比正式版更新"的现代版本）。
            check(pickFromPage(QStringLiteral("1.21.4")).fileName ==
                      QStringLiteral("OptiFine_1.21.4_HD_U_J3.jar") &&
                      pickNewest(QStringLiteral("1.21.4")).fileName ==
                          QStringLiteral("preview_OptiFine_1.21.4_HD_U_J4_pre2.jar"),
                  "V8.4 1.21.4 稳定档 J3 / 最新档 J4_pre2",
                  QStringLiteral("%1 / %2")
                      .arg(pickFromPage(QStringLiteral("1.21.4")).fileName,
                           pickNewest(QStringLiteral("1.21.4")).fileName));

            // 页面上根本没有的游戏版本：**不许**从整页里随便挑一个 —— 那会装出一个别的游戏
            // 版本的 OptiFine，而用户以为装的是他要的那个。
            check(!pickFromPage(QStringLiteral("1.99")).ok() &&
                      !pickFromPage(QString()).ok() &&
                      !pickNewest(QStringLiteral("1.99")).ok(),
                  "V8.4 页面上没有的版本 -> 两档都挑不出来，不是「随便挑一个」");
        }

        // --- V8.5 镜像的版本表：按发布时间（`_id` 那 4 个字节）从新到旧 -------------
        QFile mirrorFile(metaDir + "/optifine-1.18.2-list.json");
        QByteArray mirrorBytes;
        if (mirrorFile.open(QIODevice::ReadOnly)) {
            mirrorBytes = mirrorFile.readAll();
        }
        const QJsonArray mirrorList = QJsonDocument::fromJson(mirrorBytes).array();
        check(mirrorList.size() == 11, "V8.5 镜像那份真数据读到了（11 条）",
              QString("%1 条").arg(mirrorList.size()));
        if (!mirrorList.isEmpty()) {
            const LoaderMeta::OptiFinePick mirrorPick =
                LoaderMeta::pickOptifineFromMirror(mirrorList, QStringLiteral("1.18.2"));
            check(mirrorPick.ok() &&
                      mirrorPick.fileName == QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar") &&
                      mirrorPick.type == QStringLiteral("HD_U") &&
                      mirrorPick.patch == QStringLiteral("H9"),
                  "V8.5 1.18.2 的镜像表稳定档 -> H9", QStringLiteral("%1 type=%2 patch=%3")
                      .arg(mirrorPick.fileName, mirrorPick.type, mirrorPick.patch));

            // 稳定档挑出来的那条，type/patch 用的是**镜像自己那两个字段**（不是从版本号切
            // 出来的）—— 那既是从下载地址的唯一来源，也钉住了"挑法和列表走同一份取数"。
            const QString lastFile =
                mirrorList.last().toObject().value(QStringLiteral("filename")).toString();
            check(LoaderMeta::isOptifinePreviewFile(lastFile),
                  "V8.5 那份数组的最后一条是预览版（所以「取最后一条」那个错做法会挑中它）",
                  lastFile);

            // 1.18.2 这份数据上 H9 正式版就是最新发布的那一条，所以两档挑出来是同一个；
            // 真正的"两档分开"在 1.21.4 那一份上（见下面 V8.5c）。
            check(LoaderMeta::pickOptifineFromMirror(mirrorList, QStringLiteral("1.18.2"),
                                                     LoaderMeta::LoaderChannel::Newest)
                      .fileName == QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar"),
                  "V8.5 1.18.2 最新档也是 H9（H9 就是这份数据里最后发出来的那条）");

            // 全是预览版（正式的还没发）-> **稳定档挑不出来、最新档挑得出来**。
            QJsonArray previewsOnly;
            for (const QJsonValue &value : mirrorList) {
                if (LoaderMeta::isOptifinePreviewFile(
                        value.toObject().value(QStringLiteral("filename")).toString())) {
                    previewsOnly.append(value);
                }
            }
            check(!previewsOnly.isEmpty() &&
                      !LoaderMeta::pickOptifineFromMirror(previewsOnly, QStringLiteral("1.18.2"))
                           .ok(),
                  "V8.5 只剩预览版时稳定档挑不出来",
                  QString("%1 条预览版").arg(previewsOnly.size()));
            check(LoaderMeta::pickOptifineFromMirror(previewsOnly, QStringLiteral("1.18.2"),
                                                     LoaderMeta::LoaderChannel::Newest)
                      .fileName == QStringLiteral("preview_OptiFine_1.18.2_HD_U_H9_pre3.jar"),
                  "V8.5 同一批数据最新档挑得出预览版（H9_pre3，2023-03-26 那条）");

            // 缺字段 / 文件名不能用的条目一律跳过：别让一条烂数据把整次安装带偏（挑不出来，
            // 而不是"挑一条烂的"）。
            const QJsonArray junk{
                QJsonObject{{QStringLiteral("filename"),
                             QStringLiteral("OptiFine_1.18.2_HD_U_X1.jar")}},
                QJsonObject{{QStringLiteral("filename"), QStringLiteral("../evil.jar")},
                            {QStringLiteral("type"), QStringLiteral("HD_U")},
                            {QStringLiteral("patch"), QStringLiteral("X1")}},
                QJsonObject{{QStringLiteral("filename"),
                             QStringLiteral("OptiFine_1.18.2_HD_U_X2.jar")},
                            {QStringLiteral("type"), QString()},
                            {QStringLiteral("patch"), QStringLiteral("X2")}}};
            check(!LoaderMeta::pickOptifineFromMirror(junk, QStringLiteral("1.18.2")).ok(),
                  "V8.5 缺 type/patch 的、文件名带路径的 -> 全跳过");
            check(!LoaderMeta::pickOptifineFromMirror(QJsonArray(), QStringLiteral("1.18.2")).ok(),
                  "V8.5 空数组 -> 挑不出来（快照那种「还没支持」的版本）");
        }

        // --- V8.5b 镜像那份数组**不是按时间排的**，是按 (type, patch) 字典序 ---------
        //
        // 1.21.1 那 8 条是最好的证据：数组里 `pre10, pre11, … pre15` 排在 `pre9` **前面**
        // （字典序），而时间上 pre9 是最老的（09-04）、pre15 是最新的（09-23）——
        // 所以"把数组倒过来"这个老做法在这份真数据上挑出来的是**最老**的那条预览版。
        {
            QFile f(metaDir + "/optifine-1.21.1-list.json");
            QByteArray bytes;
            if (f.open(QIODevice::ReadOnly)) {
                bytes = f.readAll();
            }
            const QJsonArray arr = QJsonDocument::fromJson(bytes).array();
            check(arr.size() == 8, "V8.5b 1.21.1 的镜像数据读到了（8 条）",
                  QString("%1 条").arg(arr.size()));
            const QString firstPatch =
                arr.first().toObject().value(QStringLiteral("patch")).toString();
            const QString lastPatch =
                arr.last().toObject().value(QStringLiteral("patch")).toString();
            check(firstPatch == QStringLiteral("J1") && lastPatch == QStringLiteral("pre9"),
                  "V8.5b 数组首尾是 J1 / pre9（字典序，不是时间序）",
                  QStringLiteral("%1 … %2").arg(firstPatch, lastPatch));

            const LoaderMeta::LoaderVersionList list =
                LoaderMeta::listOptifineVersionsFromMirror(arr, QStringLiteral("1.21.1"));
            check(LoaderMeta::loaderVersionStrings(list) ==
                      (QStringList{QStringLiteral("HD_U_J1"), QStringLiteral("HD_U_J1_pre15"),
                                   QStringLiteral("HD_U_J1_pre14"), QStringLiteral("HD_U_J1_pre13"),
                                   QStringLiteral("HD_U_J1_pre12"), QStringLiteral("HD_U_J1_pre11"),
                                   QStringLiteral("HD_U_J1_pre10"),
                                   QStringLiteral("HD_U_J1_pre9")}),
                  "V8.5b 列表按发布时间从新到旧（J1 09-24 → pre15 09-23 → … → pre9 09-04）",
                  LoaderMeta::loaderVersionStrings(list).join(QStringLiteral(", ")));
            // ★ 反证：数组倒过来（老做法）得到的是 pre9 打头 —— 全份数据里最老的那条。
            QStringList reversed = LoaderMeta::loaderVersionStrings(list);
            std::reverse(reversed.begin(), reversed.end());
            check(reversed.first() == QStringLiteral("HD_U_J1_pre9") &&
                      list.first().version == QStringLiteral("HD_U_J1"),
                  "★ V8.5b 倒过来是 pre9 打头（最老），按 `_id` 排是 J1 打头（最新）");
            check(list.value(0).stable && !list.value(1).stable,
                  "V8.5b 正式版标记只在那条正式版上（J1），预览版那 7 条都是 false");
            check(LoaderMeta::pickOptifineFromMirror(arr, QStringLiteral("1.21.1"),
                                                     LoaderMeta::LoaderChannel::Newest)
                          .fileName == QStringLiteral("OptiFine_1.21.1_HD_U_J1.jar") &&
                      LoaderMeta::pickOptifineFromMirror(arr, QStringLiteral("1.21.1")).fileName ==
                          QStringLiteral("OptiFine_1.21.1_HD_U_J1.jar"),
                  "V8.5b 1.21.1 上两档挑出来是同一个（正式版 J1 反而是最后发的那条）");
        }

        // --- V8.5c 镜像源上"预览版比正式版新"的版本：两档分开 --------------------
        //
        // 1.21.4 那一份：J4_pre2（2025-02-20）、J4_pre1（02-19）都**比正式版 J3（02-09）新**，
        // 而且这份数据里 18 条只有 1 条正式版 —— 正是"最新档装预览版、稳定档装正式版"的
        // 真实场景（1.21.4 的正式版 J4 到 2026-09 都还没发）。
        {
            QFile f(metaDir + "/optifine-1.21.4-list.json");
            QByteArray bytes;
            if (f.open(QIODevice::ReadOnly)) {
                bytes = f.readAll();
            }
            const QJsonArray arr = QJsonDocument::fromJson(bytes).array();
            const LoaderMeta::LoaderVersionList list =
                LoaderMeta::listOptifineVersionsFromMirror(arr, QStringLiteral("1.21.4"));
            check(arr.size() == 18 && list.size() == 18,
                  "V8.5c 1.21.4 的镜像数据读到了（18 条，一条都没被跳过）",
                  QStringLiteral("%1 / %2").arg(arr.size()).arg(list.size()));
            int stableCount = 0;
            for (const LoaderMeta::LoaderVersionEntry &entry : list) {
                stableCount += entry.stable ? 1 : 0;
            }
            check(stableCount == 1 && list.value(2).version == QStringLiteral("HD_U_J3") &&
                      list.value(2).stable,
                  "V8.5c 18 条里只有 1 条正式版（J3），它排在第 3 位（前两条是更新的预览版）",
                  QStringLiteral("正式版 %1 条，第 3 条是 %2")
                      .arg(stableCount)
                      .arg(list.value(2).version));
            check(list.value(0).version == QStringLiteral("HD_U_J4_pre2") &&
                      list.value(1).version == QStringLiteral("HD_U_J4_pre1"),
                  "V8.5c 头两条是 J4 的两个预览版（它们比正式版 J3 新）",
                  QStringLiteral("%1, %2").arg(list.value(0).version, list.value(1).version));
            const LoaderMeta::OptiFinePick newest =
                LoaderMeta::pickOptifineFromMirror(arr, QStringLiteral("1.21.4"),
                                                   LoaderMeta::LoaderChannel::Newest);
            const LoaderMeta::OptiFinePick stablePick =
                LoaderMeta::pickOptifineFromMirror(arr, QStringLiteral("1.21.4"));
            check(newest.fileName == QStringLiteral("preview_OptiFine_1.21.4_HD_U_J4_pre2.jar") &&
                      stablePick.fileName == QStringLiteral("OptiFine_1.21.4_HD_U_J3.jar"),
                  "★ V8.5c 1.21.4 上两档挑出不同版本（最新 J4_pre2 预览版 / 稳定 J3 正式版）",
                  QStringLiteral("%1 / %2").arg(newest.fileName, stablePick.fileName));
        }

        // --- V8.6 广告页 -> 真下载地址（官方那条路多出来的那一步）-----------------
        QFile adFile(metaDir + "/optifine-adloadx.html");
        QByteArray ad;
        if (adFile.open(QIODevice::ReadOnly)) {
            ad = adFile.readAll();
        }
        check(!ad.isEmpty(), "V8.6 真广告页读到了", QString("%1 字节").arg(ad.size()));
        if (!ad.isEmpty()) {
            const QString adHtml = QString::fromUtf8(ad);
            // 实测：那份页面里是**两条一模一样的** H7 链接（同一个 token）—— 说明当时要抓的
            // 那个文件在那张页面上是 H7。
            const QString h7 = LoaderMeta::optifineJarUrlFromAdPage(
                adHtml, QStringLiteral("OptiFine_1.18.2_HD_U_H7.jar"));
            check(h7 == QStringLiteral("https://optifine.net/downloadx?f=OptiFine_1.18.2_HD_U_H7.jar"
                                       "&x=cf26b5f8b42616a53a7c935f403ec643"),
                  "V8.6 页面里那条**相对**链接被补成了绝对地址（含 token）", h7);

            // 我们要的是 H9，而页面上两条都是 H7：**不猜**。猜的代价是下一个不知道是什么版本
            // 的 jar —— 而"看起来能下"恰恰是这种错最难被发现的地方。
            check(LoaderMeta::optifineJarUrlFromAdPage(
                      adHtml, QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar"))
                      .isEmpty(),
                  "V8.6 页面上没有我们要的那个文件名（又是两条）-> 空，不猜");
        }
        // 页面里**只有一条**链接时就直接用它 —— 实测那个 token 和文件名**不绑定**（拿 H7 的
        // token 去请求 H9，下下来的照样是 6.7 MB 的 H9 jar），所以"只有一条"是可以信的。
        // NOTE: 这一条是**自造**的一条链接（上面那两条才是真页面）—— 真页面里凑不出"只有一条
        //       而且文件名对不上"的形状，但那条分支在真实请求里会走到（页面结构变简单时）。
        check(LoaderMeta::optifineJarUrlFromAdPage(
                  QStringLiteral("<a href=\"downloadx?f=OptiFine_1.18.2_HD_U_H9.jar"
                                 "&x=0123456789abcdef\">"),
                  QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar")) ==
                  QStringLiteral("https://optifine.net/downloadx?f=OptiFine_1.18.2_HD_U_H9.jar"
                                 "&x=0123456789abcdef"),
              "V8.6 只有一条链接时直接用（token 不跟文件名绑定）");
        check(LoaderMeta::optifineJarUrlFromAdPage(QString(), QStringLiteral("x.jar")).isEmpty() &&
                  LoaderMeta::optifineJarUrlFromAdPage(
                      QStringLiteral("<a href=\"downloadx?f=a.jar&x=zz\">"),
                      QStringLiteral("a.jar"))
                      .isEmpty(),
              "V8.6 没有链接 / token 不像十六进制 -> 空（不往下猜地址）");

        // --- V8.7 装完之后"认目录名"用的那个形状 ---------------------------------
        //
        // 真装出来的是 `versions/1.18.2-OptiFine_HD_U_H9/`，而这个名字**不是我们拼的**
        // （安装器按自己那份 jar 里的版本号拼的）—— 所以那一步是"装完去盘上认"，认出来之后
        // 用它切出版本号写进 wtfml.meta。这一条钉住那个切法：
        {
            const QString id = QStringLiteral("1.18.2-OptiFine_HD_U_H9");
            const QString prefix = QStringLiteral("1.18.2") + QStringLiteral("-OptiFine_");
            check(LoaderMeta::isSafeVersionId(id) && id.startsWith(prefix) &&
                      id.mid(prefix.size()) == QStringLiteral("HD_U_H9"),
                  "V8.7 安装器装出来的目录名能当版本 id，切出来就是 HD_U_H9");
        }
    }
}

// ---------------------------------------------------------------------------
// loader-install 模式：**联网**真装一次带加载器的版本，装进沙箱。
//
// 这是 V 节验不了的那一半：真发请求、真落盘、真写 wtfml.meta，装完还顺手验"装出来的
// 东西能不能启动"（启动前检查 + classpath）。四个加载器走的是**三条完全不同的路**
// （Fabric 是我们自己拉 json + 下库；Forge/NeoForge 是另起一个 Java 进程跑它们的安装器
// `--installClient <目录>`；OptiFine 是**同一个安装器的无界面入口** `optifine.Installer`，
// 但它把命令行给的目录整个丢掉、只认 %APPDATA% 下面那个 .minecraft，所以得给子进程换
// APPDATA、把它指到我们自己的一个临时目录上，装完再从那个临时目录里把产物认出来搬回去），
// 所以这个模式也得分着跑：
//
//     verify.exe loader-install 1.21.8                （默认 Fabric）
//     verify.exe loader-install 1.20.1 forge
//     verify.exe loader-install 1.21.1 neoforge
//     verify.exe loader-install 1.18.2 optifine
//
// 后面还能再跟一个词 `mirror`：整个安装走**镜像源**（这一条是 2026-09-22 加的，用来真验
// "Forge/NeoForge 的下载拨到 bmclapi"这件事 —— 安装器 jar、版本表、还有安装器**自己**下
// 那十几个库（靠给它 `--mirror`）都该走镜像）。不给这个词就是官方源，和产品默认一致。
//
// **不进默认模式**：默认模式必须能离线跑（这一条要联网）。Forge/NeoForge/OptiFine 那三条
// 还额外要求**机器上有 java**（PATH 上，或者用 JAVA_HOME 那种环境变量指一个）—— 它们是
// 真的起一个 Java 子进程，这一点没法在验证里替掉。
//
// 前提：沙箱（bin/.minecraft）里已经有一个装好的原版版本 —— versions/<mc>/ 下
// **同时**有 <mc>.json 和 <mc>.jar。这样这条路只会下加载器自己那点东西（几 MB 的库 /
// 6 MB 的安装器），最后那个"把原版补齐"的步骤也只会走校验 + 补资源，不会去拉原版那
// 几百 MB 的客户端 jar。
//
// NOTE: 装完之后沙箱里会多出来东西（versions/ 下的加载器目录、cache/installers/ 下的
//       安装器 jar、还有 launcher_profiles.json），这是**故意留着的**：这个模式的价值
//       之一就是让人能去盘上看真装出来的是什么样子。清沙箱的话这些东西一起没。
// ---------------------------------------------------------------------------
static int runLoaderInstallLive(QCoreApplication &app, const QString &sandbox,
                                const QString &gameVersion, VersionManager::LoaderKind kind,
                                bool useMirror) {
    const QString versionsRoot = sandbox + "/versions";
    const QString parentDir = versionsRoot + "/" + gameVersion;
    const QString loaderName = VersionManager::loaderDisplayName(kind);
    out() << "loader-install: " << loaderName << " / 原版 " << gameVersion << " 在沙箱里吗 -> json="
          << (QFile::exists(parentDir + "/" + gameVersion + ".json") ? "有" : "没有")
          << " jar=" << (QFile::exists(parentDir + "/" + gameVersion + ".jar") ? "有" : "没有")
          << "\n";
    out().flush();
    if (!QFile::exists(parentDir + "/" + gameVersion + ".json") ||
        !QFile::exists(parentDir + "/" + gameVersion + ".jar")) {
        // 这个模式只负责"把加载器装到已经装好的原版上"，原版自己都没装全就不是它的活：
        // 直接拒绝，别让产品替它补原版（那会把两种失败混在一起，看不出是谁的问题）。
        out() << "  原版不完整（json/jar 缺一个），先把 " << gameVersion << " 装全再来\n";
        return 2;
    }

    VersionManager vm;
    // 镜像源开关：产品里是「设置 -> 下载源」在下载那一刻交给它的（MainWindow 里那一行），
    // 这里直接拨，好让这条路也能按镜像跑一遍。
    vm.setUseMirror(useMirror);
    out() << "  下载源 = " << (useMirror ? "镜像源（bmclapi）" : "官方源") << "\n";
    out().flush();
    QString installedId;
    QString message;
    bool finished = false;
    bool succeeded = false;
    QObject::connect(&vm, &VersionManager::loaderInstallMessage, &app,
                     [](const QString &text) { out() << "  · " << text << "\n"; out().flush(); });

    QEventLoop loop;
    QObject::connect(&vm, &VersionManager::versionDownloadFinished, &app,
                     [&](const QString &id, bool ok, const QString &msg) {
                         installedId = id;
                         message = msg;
                         succeeded = ok;
                         finished = true;
                     });
    QObject::connect(&vm, &VersionManager::versionDownloadFinished, &loop, [&] { loop.quit(); });

    // --- 安装器要用的那份 Java ---------------------------------------------------
    //
    // 产品里这一步是 MainWindow::startLoaderInstall() 在**点下「下载版本」那一刻**做的
    // （版本 json 的 javaVersion.majorVersion → installerJavaFor()），mw_check 的 Y4 钉的
    // 是界面那一段接线。这里补的是"在**真机器**上把那套判据跑一遍"：那张纯函数表（本文件
    // M 段）和接线都验过了，唯独"在本机扫一圈、真挑出一份能用的"离线造不出来 ——
    // installerJavaFor() 会读 PATH / JAVA_HOME / 本机已装的运行时。
    //
    // 断言写成**与机器无关**的形式（live 模式在哪台机器上跑都得站得住）：
    //   - 说成功 → 挑中的那份主版本必须真的够新（拿 Java 8 去跑一个要 17 的安装器，用户
    //     看到的是 UnsupportedClassVersionError 那串鬼话，不是"该装个新 Java"）；
    //   - 说失败 → 必须给出一句能照做的理由。
    // 本机（Java 21）走的是前一条。
    if (kind != VersionManager::LoaderKind::Fabric) {
        int requiredMajor = 0;
        QFile versionFile(parentDir + "/" + gameVersion + ".json");
        if (versionFile.open(QIODevice::ReadOnly)) {
            requiredMajor = QJsonDocument::fromJson(versionFile.readAll())
                                .object()["javaVersion"]
                                .toObject()["majorVersion"]
                                .toInt();
            versionFile.close();
        }
        check(requiredMajor > 0, "沙箱里那份原版 json 说了它要哪个 Java",
              QString::number(requiredMajor));

        // 「设置」里那份给一个**不存在**的路径：认不出主版本 → 该去本机找一份够新的，
        // 而不是拿着它硬上。
        const QString kBogusJava = QStringLiteral("C:/没有这个目录/java.exe");
        QString picked;
        QString reason;
        const bool javaOk =
            GlobalJavaSettings::installerJavaFor(requiredMajor, kBogusJava, &picked, &reason);
        out() << "  · 安装器要 Java " << requiredMajor << "，配的那份认不出来 -> "
              << (javaOk ? "挑中 " + picked : "挑不出来：" + reason) << "\n";
        out().flush();
        if (javaOk) {
            const int pickedMajor = GlobalJavaSettings::probeJavaMajorVersion(picked);
            check(!picked.isEmpty() && picked != kBogusJava && pickedMajor >= requiredMajor,
                  "挑中的那份真的够新（挑不出来时必须给理由，不能拿着旧的硬上）",
                  picked + " = Java " + QString::number(pickedMajor));
            check(QFile::exists(picked), "挑中的那份在盘上", picked);
        } else {
            check(!reason.isEmpty() && reason.contains(QString::number(requiredMajor)),
                  "挑不出来时给了一句能照做的理由", reason);
        }

        // 反过来那条 —— 这次改动的**要害**就在这儿：配置里那份**已经够新**时必须原样用它。
        // "顺手换个更贴近的"是没道理的：用户配着 Java 21 去装一个要 17 的版本，换掉他选的
        // 那份只会让人莫名其妙（而且旧实现还会把它写回全局设置）。
        const QString onPath = QStandardPaths::findExecutable(QStringLiteral("java"));
        if (!onPath.isEmpty() &&
            GlobalJavaSettings::probeJavaMajorVersion(onPath) >= requiredMajor) {
            QString kept;
            QString why;
            const bool keptOk =
                GlobalJavaSettings::installerJavaFor(requiredMajor, onPath, &kept, &why);
            check(keptOk && kept == onPath, "配的那份够新就原样用它（不换）",
                  kept + " / 原配置 " + onPath);
        } else {
            out() << "  · PATH 上那份没有或不够新，本机造不出「够新就原样用」那条\n";
            out().flush();
        }
    }

    out() << "开始装：installLoaderVersion(" << gameVersion << ", " << loaderName << ")\n";
    out().flush();
    QElapsedTimer timer;
    timer.start();
    // javaPath 传空 = 用 PATH 上的 `java`。这个模式不读用户的设置（它跑在沙箱里，
    // 而沙箱里那个 QSettings 是空的），指望"设置里配过"会在这台机器上跑不起来。
    vm.installLoaderVersion(gameVersion, kind, QString());
    if (!finished) {
        // 超时兜底：卡住时也要退出来，不然是个永远不返回的验证。
        //
        // NOTE: 这个数**必须**比产品自己的硬超时（VersionManager 里那个 30 分钟）长。
        //       原来是 300 秒，结果是"产品还在正常跑，验证先放弃了"——实测 Forge 40.3.0
        //       在 1.18.2 上装一次，光从 creeperhost 那个镜像下十几个库就超过 300 秒，
        //       报出来的是"失败"，而产品那一路其实一切正常。留 35 分钟：比产品的 30 分钟
        //       多 5 分钟，这样"真卡住了"报出来的是产品那句中文（带它最后的输出），
        //       而不是这里一句光秃秃的"超时"。
        constexpr int kLiveWaitMs = 35 * 60 * 1000;
        QTimer::singleShot(kLiveWaitMs, &loop, [&] {
            out() << "  超时 " << kLiveWaitMs << " ms，结束等待（产品自己那条硬超时早该报了）\n";
            out().flush();
            loop.quit();
        });
        loop.exec();
    }
    out() << "装完用了 " << timer.elapsed() << " ms：" << (succeeded ? "成功" : "失败")
          << "（" << installedId << "）\n"
          << message << "\n";
    out().flush();
    check(succeeded, "installLoaderVersion 报成功", message);
    if (!succeeded) {
        return 1;
    }

    // --- 装出来的东西长什么样 ---------------------------------------------------
    //
    // 目录名的约定**四种各不相同**，而且都不是我们发明的（是安装器/加载器服务自己定的，
    // 别的启动器按它找目录）。所以这里按 kind 分别钉，不能"统一一下"。
    const QString loaderId = installedId;
    if (kind == VersionManager::LoaderKind::Fabric) {
        check(loaderId.startsWith(QStringLiteral("fabric-loader-")) &&
                  loaderId.contains(gameVersion),
              "版本目录名是 fabric-loader-<加载器>-<游戏>", loaderId);
    } else if (kind == VersionManager::LoaderKind::Forge) {
        check(loaderId.startsWith(gameVersion + QStringLiteral("-forge-")),
              "版本目录名是 <游戏>-forge-<加载器>", loaderId);
    } else if (kind == VersionManager::LoaderKind::NeoForge) {
        check(loaderId.startsWith(QStringLiteral("neoforge-")) &&
                  !loaderId.contains(gameVersion + QLatin1Char('-')),
              "版本目录名是 neoforge-<加载器>（**不带**游戏版本前缀）", loaderId);
    } else {
        // OptiFine 这个目录名**不是我们拼的**（上面三条都是）：它的安装器按自己那份 jar 里
        // 的版本号拼目录名，我们压根不知道会拼出什么，是装完去临时目录里认出来的（见
        // VersionManager::adoptOptifineProducts）。所以这里只能钉形状 —— 具体版本号是版本表
        // 里挑中的那个，下面拿 wtfml.meta 里的 loaderVersion 反过来对。
        const QString prefix = gameVersion + QStringLiteral("-OptiFine_");
        check(loaderId.startsWith(prefix) && loaderId.mid(prefix.size()).contains(QLatin1Char('_')),
              "版本目录名是 <游戏>-OptiFine_<版本>（安装器自己拼的，我们只是认出来）", loaderId);
    }
    const QString loaderDir = versionsRoot + "/" + loaderId;
    const QJsonObject onDisk = loadJson(loaderDir + "/" + loaderId + ".json");
    check(!onDisk.isEmpty() && onDisk[QStringLiteral("id")].toString() == loaderId &&
              onDisk[QStringLiteral("inheritsFrom")].toString() == gameVersion,
          "json 落盘了，而且是原样那份 profile（id / inheritsFrom 都对）",
          loaderDir + "/" + loaderId + ".json");

    // 库里那几个 maven 库都得真在盘上（这条是"下载列表和 classpath 用同一个解析"的落地）
    const QString librariesDir = AppPaths::minecraftDir() + "/libraries";
    int missingLibs = 0;
    QString firstMissing;
    const QJsonArray libs = onDisk[QStringLiteral("libraries")].toArray();
    for (const QJsonValue &value : libs) {
        const QJsonObject libObj = value.toObject();
        if (!LibraryRules::libraryAllowed(libObj)) {
            continue;
        }
        const LibraryRules::Artifact artifact = LibraryRules::artifactFor(libObj);
        // 判据是 hasPath() 不是 valid()：OptiFine 那两个库没有下载地址（jar 是它的安装器
        // 自己放进 libraries/ 的），但对它们来说"盘上得有一份"照样成立 —— 那正是这条要钉的。
        const QString path =
            artifact.hasPath() ? librariesDir + "/" + artifact.path : QString();
        if (path.isEmpty() || !QFile::exists(path)) {
            ++missingLibs;
            if (firstMissing.isEmpty()) {
                firstMissing = artifact.path;
            }
        }
    }
    check(libs.size() > 0 && missingLibs == 0, "profile 里那几个库全下到 libraries/ 下了",
          QString("库 %1 个，缺 %2 个（%3）").arg(libs.size()).arg(missingLibs).arg(firstMissing));

    const QJsonObject meta = loadJson(AppPaths::versionMetaPath(loaderId));
    // loaderName 跟外面的 loaderName 比，**不写死 "Fabric"**：这条原来是 Fabric 单干时写的，
    // 加了 forge/neoforge 之后就成了"产品对了、断言红"（2026-09-22 真装时撞上）。
    check(meta[QStringLiteral("realVersion")].toString() == gameVersion &&
              meta[QStringLiteral("loaderName")].toString() == loaderName &&
              !meta[QStringLiteral("loaderVersion")].toString().isEmpty(),
          "wtfml.meta 里写进了 realVersion / loaderName / loaderVersion",
          QString("realVersion=%1 loaderName=%2 loaderVersion=%3")
                  .arg(meta[QStringLiteral("realVersion")].toString(),
                       meta[QStringLiteral("loaderName")].toString(),
                       meta[QStringLiteral("loaderVersion")].toString()));
    if (kind == VersionManager::LoaderKind::OptiFine) {
        // 这一条是 OptiFine 独有的：目录名是**安装器装出来**的，而写进 wtfml.meta 的
        // loaderVersion 是我们从那个目录名里切出来的 —— 两者必须一致，不然「已安装版本」
        // 那一栏显示的版本号会和盘上那个目录对不上（用户核不了、我们也核不了）。
        check(meta[QStringLiteral("loaderVersion")].toString() ==
                  loaderId.mid(gameVersion.size() + QStringLiteral("-OptiFine_").size()),
              "wtfml.meta 里的 loaderVersion 就是目录名里那一段（不是另算的一个）",
              meta[QStringLiteral("loaderVersion")].toString());
    }

    // --- 装出来的这个版本能不能启动 ---------------------------------------------
    const QJsonObject merged = vm.getVersionJson(loaderId);
    // 合并结果的主类必须是**加载器**那个，而不是原版的 —— 这一条就是"启动真的会走加载器"
    // 这件事的判据：主类错了游戏起来就是纯原版（模组全不加载）。
    //
    // 判据写法：主类**非空**、等于 json 里那个、而且**不等于原版 json 里的主类**。
    // 不写死具体类名（`KnotClient` / `cpw.mods.bootstraplauncher.BootstrapLauncher` 这种）
    // 是因为那是加载器自己的版本细节 —— 它哪天换个引导类，这里不该跟着红。
    const QJsonObject parentJson = loadJson(parentDir + "/" + gameVersion + ".json");
    const QString parentMain = parentJson[QStringLiteral("mainClass")].toString();
    const QString loaderMain = merged[QStringLiteral("mainClass")].toString();
    check(!loaderMain.isEmpty() && loaderMain == onDisk[QStringLiteral("mainClass")].toString() &&
              loaderMain != parentMain,
          "顺着继承链读出来的主类是加载器那个（不是原版那个）",
          QStringLiteral("%1（原版是 %2）").arg(loaderMain, parentMain));
    if (kind == VersionManager::LoaderKind::Fabric) {
        // Fabric 这一条留着写死，因为 V 节那份真 profile 里就是它，两边能对上。
        check(loaderMain.contains(QStringLiteral("Knot")),
              "Fabric 的是 KnotClient（V 节那份真 profile 里就是这个）", loaderMain);
    }
    // 两样分开判，因为"继承"对它们不是同一条规矩：
    //  - downloads 是**父版本独有**的键（加载器的 profile 里根本没有），它非空就直接证明
    //    继承发生了。
    //  - logging 要按"子赢"核对：子声明了就取子的 —— Forge 1.18.2 装出来的 profile 写着
    //    `"logging": {}`，那是它有意清掉原版那份 log4j 配置（官方启动器也一样），子没声明
    //    才继承父的。**所以这里不能断言"logging 非空"**：2026-09-22 就是这条把真装的
    //    断言顶红的（当时怀疑是 merge 丢了键，其实数据里就是个空对象）。
    const QJsonValue expectedLogging = onDisk.contains(QStringLiteral("logging"))
                                           ? onDisk[QStringLiteral("logging")]
                                           : parentJson[QStringLiteral("logging")];
    check(!merged[QStringLiteral("downloads")].toObject().isEmpty() &&
              flatJson(merged[QStringLiteral("logging")]) == flatJson(expectedLogging),
          "原版那两样（downloads 从父版本继承 / logging 按子赢）合对了",
          QString("downloads=%1 logging=%2（子的是 %3）")
              .arg(merged[QStringLiteral("downloads")].toObject().isEmpty() ? "空" : "有",
                   flatJson(merged[QStringLiteral("logging")]),
                   flatJson(expectedLogging)));
    check(vm.inheritanceProblem(loaderId).isEmpty(), "这个版本没有继承链问题",
          vm.inheritanceProblem(loaderId));
    if (kind == VersionManager::LoaderKind::OptiFine) {
        // **这个加载器和别的都不一样**：它的安装器把原版那份客户端 jar **逐字节**抄进了自己
        // 的版本目录（实测 sha1 = 2e9a3e3107cca00d6bc9c97bf7d149cae163ef21，就是原版那份），
        // 所以这个目录里有自己的 jar —— jar 归属是它自己，不是原版。别的三个目录里只有 json。
        check(InstanceFiles::jarOwnerId(loaderId) == loaderId,
              "OptiFine 的版本目录里有自己那份客户端 jar（安装器抄进去的），归属是它自己",
              InstanceFiles::jarOwnerId(loaderId));
    } else {
        check(InstanceFiles::jarOwnerId(loaderId) == gameVersion,
              "客户端 jar 认到原版那个目录（加载器目录里只有 json，没有 jar）",
              InstanceFiles::jarOwnerId(loaderId));
    }

    // 安装器**不下资源文件**（assets），而且 Forge 连原版的 json 都不写（只在
    // versions/<原版>/ 留一份 sha1 与官方一致的客户端 jar）。所以这条路必须自己把原版
    // 补齐 —— 缺了那一半，用户拿到的是一个能装模组、一进游戏就崩的版本。
    check(QFile::exists(parentDir + "/" + gameVersion + ".json"),
          "装完之后原版的 json 也在沙箱里（加载器自己只写了它那一份）",
          parentDir + "/" + gameVersion + ".json");
    check(QFile::exists(AppPaths::assetsDir() + "/indexes/" +
                        parentJson[QStringLiteral("assetIndex")].toObject()
                            [QStringLiteral("id")]
                                .toString() +
                        QStringLiteral(".json")),
          "资源索引也补齐了（安装器一个资源文件都不下）",
          AppPaths::assetsDir());
    check(QFile::exists(InstanceFiles::jarPath(loaderId)), "那个 jar 真的在盘上",
          InstanceFiles::jarPath(loaderId));

    QStringList warnings;
    const QStringList installed = vm.installedVersions(&warnings);
    check(installed.contains(loaderId), "装完就出现在「已安装版本」列表里",
          QString("列表里 %1 个：%2").arg(installed.size()).arg(installed.join(QStringLiteral(", "))));

    LauncherManager launcher;
    QStringList errors;
    check(launcher.checkPreLaunch(loaderId, &errors), "启动前检查过了",
          errors.join(QStringLiteral("; ")));

    // classpath：客户端 jar 得是**原版那个**，加载器自己的库也得在上面
    EffectiveJavaSettings javaSettings;
    javaSettings.javaPath = QStringLiteral("C:/does-not-matter/java.exe");  // 只拼参数，不起进程
    javaSettings.xms = 1024;
    javaSettings.xmx = 2048;
    const QStringList args = launcher.generateJvmArguments(
        QString(), loaderId, QString(), merged, javaSettings, true, 17);
    const QString joined = args.join(QLatin1Char(' '));
    // 客户端 jar 在 classpath 上**必须是实际被启动的那一个**：别的三个加载器是原版目录里
    // 那份，OptiFine 是它自己目录里那份（安装器抄进去的）—— 拼错了的症状是启动时一个
    // NoClassDefFound，而不是装的时候报错。
    const QString expectJar =
        kind == VersionManager::LoaderKind::OptiFine ? loaderId : gameVersion;
    check(joined.contains(QStringLiteral("versions/%1/%1.jar").arg(expectJar)),
          "classpath 上的客户端 jar 是实际被启动的那一份",
          joined.left(400));
    int libsOnClasspath = 0;
    for (const QJsonValue &value : libs) {
        const LibraryRules::Artifact artifact = LibraryRules::artifactFor(value.toObject());
        // 同上：classpath 这一条也要算上 localOnly 的那几个（它们没地址、但有 jar，而且
        // 少了 launchwrapper 那个主类就起不来）。
        if (artifact.hasPath() &&
            joined.contains(QDir::toNativeSeparators(QStringLiteral("libraries/%1").arg(artifact.path)))) {
            ++libsOnClasspath;
        }
    }
    check(libsOnClasspath == libs.size(), "加载器自己的库也全在 classpath 上",
          QString("%1/%2").arg(libsOnClasspath).arg(libs.size()));

    out() << "\n===== " << (g_failures == 0 ? "全部通过" : "有失败项") << ": "
          << (g_checks - g_failures) << "/" << g_checks << " =====\n";
    out().flush();
    return g_failures == 0 ? 0 : 1;
}

// ============================================================================
// W / X 节：账号与外观 —— 多账号存储（AccountStore）和皮肤披风那几条接口的纯函数（SkinApi）
// ============================================================================

/// 造一份"活动槽里那份凭据"该有的样子。字段名照抄 AuthManager 落盘时用的那一套
/// （Minecraft 那份是 access_token / expires_at / name / uuid；微软那份必须有 refresh_token）。
/// expires_at 给一个固定的远未来值 —— 这一节不构造 AuthManager，没人去解析它。
static QJsonObject stubMinecraftPayload(const QString &uuid, const QString &name) {
    QJsonObject payload;
    payload.insert(QStringLiteral("access_token"), QStringLiteral("at-") + name);
    payload.insert(QStringLiteral("expires_at"), QStringLiteral("2030-01-01T00:00:00Z"));
    payload.insert(QStringLiteral("name"), name);
    payload.insert(QStringLiteral("uuid"), uuid);
    return payload;
}

static QJsonObject stubMicrosoftPayload(const QString &refreshToken) {
    QJsonObject payload;
    payload.insert(QStringLiteral("access_token"), QStringLiteral("ms-at-") + refreshToken);
    payload.insert(QStringLiteral("refresh_token"), refreshToken);
    return payload;
}

/// 把"活动槽"摆成某个账号的样子。写盘顺手断言一次 —— 后面那一串断言全都建立在
/// "盘上确实有这两份凭据"之上，前提不成立的话后面的红是误导。
static void putActiveCredentials(const QString &label, const QString &uuid, const QString &name,
                                 const QString &refreshToken) {
    check(TokenStore::writeJson(TokenStore::microsoftKey(), stubMicrosoftPayload(refreshToken)),
          label + QStringLiteral(" 前提：微软凭据写得进沙盒"));
    check(TokenStore::writeJson(TokenStore::minecraftKey(), stubMinecraftPayload(uuid, name)),
          label + QStringLiteral(" 前提：Minecraft 凭据写得进沙盒"));
}

/// 列表里第 index 项（越界返回空项）。**故意不让它崩** —— 一条失败的断言把整节带崩，
/// 后面几十条结果就全看不到了。
static SavedAccount accountAt(const QList<SavedAccount> &list, int index) {
    return index >= 0 && index < list.size() ? list.at(index) : SavedAccount();
}

static void runAccountSkinTests(const QString &sandbox) {
    section("W. 多账号存储（活动槽 ↔ 列表）");

    // 真值来源是 QSettings，照 I5 那套先把它搬进沙盒 —— **必须在第一个 QSettings 对象
    // 出现之前**。这一节的键在真机器上写一遍没有意义，还会把用户自己的登录状态覆盖掉。
    const QString settingsDir = sandbox + "/wtfml-accounts";
    QDir(settingsDir).removeRecursively();
    QDir().mkpath(settingsDir);
    QSettings::setDefaultFormat(QSettings::IniFormat);
    QSettings::setPath(QSettings::IniFormat, QSettings::UserScope, settingsDir);

    const QString uuidA = QStringLiteral("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");
    const QString uuidB = QStringLiteral("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb");

    // ---- W1 空盘：什么都是空的 ----
    {
        check(!TokenStore::hasValue(TokenStore::minecraftKey()),
              "W1 前提：沙盒的活动槽本来是空的（否则说明沙盒没换成新目录）");
        check(AccountStore::accounts().isEmpty(), "W1 全新盘上没有已保存的账号");
        check(AccountStore::activeUuid().isEmpty(), "W1 全新盘上没有当前账号");
        check(!AccountStore::contains(uuidA), "W1 全新盘里查不到任何账号");
        check(AccountStore::nameOf(uuidA).isEmpty(), "W1 查一个不存在的账号，名字是空串");

        QString error;
        check(!AccountStore::captureActive(&error), "W1 没登录时收不进列表");
        check(!error.isEmpty(), "W1 而且给得出原因", error);
    }

    // ---- W2 只有 Minecraft 那一半凭据 → 不收 ----
    // 微软那份才是"下次还能不能换出新令牌"的来路。只有一半的账号收进列表，将来切过去
    // 必然换不出令牌 —— 与其那时候报一个查不明白的错，不如当场不收。
    {
        check(TokenStore::writeJson(TokenStore::minecraftKey(), stubMinecraftPayload(uuidA, "Alice")),
              "W2 前提：只写 Minecraft 那份");
        QString error;
        check(!AccountStore::captureActive(&error),
              "W2 只有 Minecraft 凭据、没有微软那份 → 不收进列表");
        check(!error.isEmpty(), "W2 而且说得出是缺了哪一半", error);
        check(AccountStore::accounts().isEmpty(), "W2 列表里一条都没多");
        TokenStore::clear(TokenStore::minecraftKey());
    }

    // ---- W3 两份都齐 → 收进列表，uuid 和名字都从凭据自己身上读 ----
    {
        putActiveCredentials(QStringLiteral("W3"), uuidA, QStringLiteral("Alice"),
                             QStringLiteral("rt-A"));
        QString error;
        check(AccountStore::captureActive(&error), "W3 两份凭据都齐 → 收进列表", error);

        const QList<SavedAccount> list = AccountStore::accounts();
        check(list.size() == 1, "W3 列表里正好一条", QString::number(list.size()));
        check(accountAt(list, 0).uuid == uuidA, "W3 那一项的 uuid 就是凭据里的 uuid");
        check(AccountStore::nameOf(uuidA) == QStringLiteral("Alice"),
              "W3 名字是从凭据自己身上读的", AccountStore::nameOf(uuidA));
        check(AccountStore::activeUuid() == uuidA, "W3 当前账号就是刚收进来的这个");
        check(AccountStore::contains(uuidA), "W3 contains() 认得出它");
        check(accountAt(list, 0).isCurrent, "W3 而且标着「当前」");
        check(!accountAt(list, 0).savedAt.isEmpty(),
              "W3 存进来的时刻有值（界面要显示「存于 …」）", accountAt(list, 0).savedAt);

        SavedAccount found;
        check(AccountStore::find(uuidA, &found) && found.uuid == uuidA,
              "W3 find() 按 uuid 找得到");
        check(AccountStore::find(uuidA, &found) && found.isCurrent,
              "W3 find() 也带着「当前」标记");
    }

    // ---- W4 同一个账号再收一次 → 就地更新，不是追加 ----
    // 令牌换新了、用户改了名字，都还是同一个人。重复追加的症状是列表里出现两条同名项，
    // 而点哪一条都"切得过去"，下次查起来很绕。
    {
        const int before = AccountStore::accounts().size();
        check(TokenStore::writeJson(TokenStore::minecraftKey(),
                                    stubMinecraftPayload(uuidA, QStringLiteral("Alice2"))),
              "W4 前提：换一份名字不同的凭据进活动槽");
        QString error;
        check(AccountStore::captureActive(&error), "W4 同一账号再收一次成功", error);
        const QList<SavedAccount> list = AccountStore::accounts();
        check(list.size() == before, "W4 列表条数没变（就地更新，不是追加）",
              QString("%1 -> %2").arg(before).arg(list.size()));
        check(AccountStore::nameOf(uuidA) == QStringLiteral("Alice2"),
              "W4 名字更新成了凭据里的新名字", AccountStore::nameOf(uuidA));
        check(accountAt(list, 0).isCurrent, "W4 更新之后「当前」标记还在它身上");
    }

    // ---- W5 第二个账号：追加到末尾，「当前」标记跟着活动槽走 ----
    {
        putActiveCredentials(QStringLiteral("W5"), uuidB, QStringLiteral("Bob"),
                             QStringLiteral("rt-B"));
        QString error;
        check(AccountStore::captureActive(&error), "W5 第二个账号也收得进来", error);

        const QList<SavedAccount> list = AccountStore::accounts();
        check(list.size() == 2, "W5 列表里有两条", QString::number(list.size()));
        check(accountAt(list, 0).uuid == uuidA && accountAt(list, 1).uuid == uuidB,
              "W5 新来的追加在末尾（顺序 = 收进来的先后）");
        check(!accountAt(list, 0).isCurrent && accountAt(list, 1).isCurrent,
              "W5 「当前」是**现算**的，不是存下来的字段");
    }

    // ---- W6 切换：活动槽的**字节**真的被换成了列表里那一份 ----
    // 这一条是整节的核心。切换不是"记一个 uuid 就完事"，而是把那个账号的两份凭据
    // 写回活动槽 —— 因为启动游戏、刷新令牌读的全是活动槽（AuthManager 一个字没改）。
    {
        QString error;
        check(AccountStore::activate(uuidA, &error), "W6 切到 Alice", error);
        check(AccountStore::activeUuid() == uuidA, "W6 当前账号换成了 Alice");

        const QJsonObject mc = TokenStore::readJson(TokenStore::minecraftKey());
        check(mc.value(QStringLiteral("name")).toString() == QStringLiteral("Alice2"),
              "W6 活动槽里 Minecraft 那份是 Alice 的**副本**（连 W4 更新过的名字一起）",
              mc.value(QStringLiteral("name")).toString());
        const QJsonObject ms = TokenStore::readJson(TokenStore::microsoftKey());
        // 切到 A 之前活动槽里放的是 **B** 的微软凭据（W5 写进去的）。这里必须是 A 的
        // rt-A —— 写回来的是"列表里收着的那一份"，不是"上一个账号留下的那一份"。
        check(ms.value(QStringLiteral("refresh_token")).toString() == QStringLiteral("rt-A"),
              "W6 微软那份也来自列表里的副本，不是上一个账号留下的",
              ms.value(QStringLiteral("refresh_token")).toString());

        const QList<SavedAccount> list = AccountStore::accounts();
        check(accountAt(list, 0).isCurrent && !accountAt(list, 1).isCurrent,
              "W6 列表上的「当前」标记跟着翻过来了");
    }

    // ---- W7 切回去：副本一个字段都没丢 ----
    {
        QString error;
        check(AccountStore::activate(uuidB, &error), "W7 切回 Bob", error);
        const QJsonObject ms = TokenStore::readJson(TokenStore::microsoftKey());
        const QJsonObject mc = TokenStore::readJson(TokenStore::minecraftKey());
        check(ms.value(QStringLiteral("refresh_token")).toString() == QStringLiteral("rt-B"),
              "W7 微软那份换成了 Bob 的（说明上一趟把 Alice 的副本完整留在列表里了）");
        check(mc.value(QStringLiteral("name")).toString() == QStringLiteral("Bob") &&
                  mc.value(QStringLiteral("uuid")).toString() == uuidB,
              "W7 Minecraft 那份也对");
    }

    // ---- W8 切不存在的 / 空 uuid → 失败，而且活动槽**不许被动过** ----
    // 失败时动了一半活动槽是最坏的下场：用户看着还是原来那个人，盘上已经是别人的令牌了。
    {
        QString error;
        check(!AccountStore::activate(uuidA.left(30), &error),
              "W8 切一个不在列表里的 uuid → 失败");
        check(!error.isEmpty(), "W8 而且说得出是「不在列表里」", error);
        check(AccountStore::activeUuid() == uuidB,
              "W8 失败的时候活动槽没被动过（还在 Bob）", AccountStore::activeUuid());
        check(!AccountStore::activate(QString(), &error), "W8 空 uuid 也失败");
    }

    // ---- W9 删非当前账号：列表少一条，活动槽不动 ----
    {
        check(AccountStore::remove(uuidA), "W9 删掉 Alice");
        check(!AccountStore::contains(uuidA), "W9 它从列表里没了");
        check(AccountStore::accounts().size() == 1, "W9 列表里剩一条");
        check(AccountStore::activeUuid() == uuidB,
              "W9 删的不是当前账号 → 活动槽原封不动（还登录着 Bob）",
              AccountStore::activeUuid());
        check(TokenStore::hasValue(TokenStore::minecraftKey()),
              "W9 活动槽里那份凭据也还在（删别人不该把我踢下线）");
        check(!AccountStore::remove(uuidA), "W9 再删一次 → 失败（列表里本来就没有它）");
    }

    // ---- W10 删**当前**账号 = 退出登录 ----
    // 留着会是"当前账号不在列表里"这种说得通但没人想要的状态，所以连活动槽一起清空。
    {
        check(AccountStore::remove(uuidB), "W10 删掉当前账号 Bob");
        check(AccountStore::accounts().isEmpty(), "W10 列表空了");
        check(AccountStore::activeUuid().isEmpty(), "W10 当前账号也空了（= 退出登录）");
        check(!TokenStore::hasValue(TokenStore::microsoftKey()) &&
                  !TokenStore::hasValue(TokenStore::minecraftKey()),
              "W10 活动槽那两份字节是**真的删掉了**，不是写成空值");
        check(!QSettings().contains(TokenStore::currentUuidKey()),
              "W10 CurrentAccountUuid 也一并清掉");
    }

    // ---- W10b 登出：只清登录状态，**账号留在列表里** ----
    //
    // 和 W10（删当前账号）只差一条：列表里那一项**不动**。所以这一节和 W10 一样要钉住
    // "盘上确实没登录状态了"，另外**必须**再钉一条"账号还在" —— 少了后一条，这个函数就
    // 退化成 W10 了，而它俩在界面上是两个按钮（「登出」和「删除所选」）。
    {
        putActiveCredentials(QStringLiteral("W10b"), uuidA, QStringLiteral("Alice"),
                             QStringLiteral("rt-A"));
        check(AccountStore::captureActive(), "W10b 先把 Alice 收进列表");
        putActiveCredentials(QStringLiteral("W10b"), uuidB, QStringLiteral("Bob"),
                             QStringLiteral("rt-B"));
        check(AccountStore::captureActive(), "W10b 再把 Bob 收进列表");
        check(AccountStore::activeUuid() == uuidB, "W10b 前提：当前账号是 Bob");

        check(AccountStore::logout(), "W10b 登出");
        check(AccountStore::activeUuid().isEmpty(), "W10b 盘上没有当前账号了（是「没登录」）");
        check(!TokenStore::hasValue(TokenStore::microsoftKey()) &&
                  !TokenStore::hasValue(TokenStore::minecraftKey()),
              "W10b 活动槽那两份凭据是**真的删掉了**，不是写成空值");
        // 这一句必须清：activeUuid() 第二档只看 CurrentAccountUuid 是不是指向一个**离线**
        // 账号 —— 登出的是离线账号时不清它，盘上就还是"当前是某某"。
        check(!QSettings().contains(TokenStore::currentUuidKey()),
              "W10b CurrentAccountUuid 也一并清掉");
        check(AccountStore::accounts().size() == 2 && AccountStore::contains(uuidA) &&
                  AccountStore::contains(uuidB),
              "W10b **两个账号都还在列表里**（这一条才是「登出」和「删除」的分界）",
              QString::number(AccountStore::accounts().size()));
        check(!accountAt(AccountStore::accounts(), 0).isCurrent &&
                  !accountAt(AccountStore::accounts(), 1).isCurrent,
              "W10b 列表上那个「当前」标记跟着没了");

        // 本来就没登录：返回 false。**顺带钉住盘上的东西一个字节没动** —— 清一遍空槽是
        // 空操作，但要是它返回 true，界面就会说一句"已退出登录"，而那句话是假的。
        check(!AccountStore::logout(), "W10b 再登出一次 → 失败（本来就没登录）");
        check(AccountStore::accounts().size() == 2,
              "W10b 那一下没把列表动掉", QString::number(AccountStore::accounts().size()));

        // 回来：这才是"登出可逆"的判据 —— 副本里该有的字段一个都没少。
        QString error;
        check(AccountStore::activate(uuidB, &error), "W10b 切回 Bob（登出之后还能回来）", error);
        check(AccountStore::activeUuid() == uuidB, "W10b 当前账号又是 Bob 了");
        const QJsonObject ms = TokenStore::readJson(TokenStore::microsoftKey());
        check(ms.value(QStringLiteral("refresh_token")).toString() == QStringLiteral("rt-B"),
              "W10b 回来的那份副本是完整的（refresh_token 还在）",
              ms.value(QStringLiteral("refresh_token")).toString());

        // 收尾：还原成 W10 结束时的样子（列表空 + 活动槽空）—— W11 的前提就是这两条，
        // 不还原的话它那句「活动槽是空的 → 谁都不标当前」会因为这儿还登录着 Bob 而红，
        // 而那不是 W11 的错。
        check(AccountStore::remove(uuidA) && AccountStore::remove(uuidB),
              "W10b 收尾：把这一节造的两个账号删干净");
        check(AccountStore::accounts().isEmpty() && AccountStore::activeUuid().isEmpty(),
              "W10b 收尾：列表和活动槽都回到空（W11 的前提）");
    }

    // ---- W11 盘上有坏项 / 残项时的下场 ----
    // 手写一份列表（当"外部写入者"），验产品的读。两种坏法各一条：
    //   - 一项连 uuid 都没有 → 列表里**不摆**（摆一个点不动的账号比少一项更难查）；
    //   - 一项缺了微软那半边 → activate 拒掉，别把半份凭据写进活动槽。
    {
        const QString uuidBad = QStringLiteral("dddddddddddddddddddddddddddddddd");
        QJsonObject noUuid;
        noUuid.insert(QStringLiteral("name"), QStringLiteral("没有 uuid"));
        QJsonObject halfBaked;
        halfBaked.insert(QStringLiteral("uuid"), uuidBad);
        halfBaked.insert(QStringLiteral("name"), QStringLiteral("HalfBaked"));
        halfBaked.insert(QStringLiteral("minecraft"), stubMinecraftPayload(uuidBad, "HalfBaked"));
        // 微软那半边故意不给
        QJsonObject root;
        root.insert(QStringLiteral("accounts"), QJsonArray{noUuid, halfBaked});
        check(TokenStore::writeJson(TokenStore::accountsKey(), root),
              "W11 前提：手写一份带坏项的列表进沙盒");

        const QList<SavedAccount> list = AccountStore::accounts();
        check(list.size() == 1, "W11 没有 uuid 的那一项被跳过了", QString::number(list.size()));
        check(!list.isEmpty() && list.at(0).uuid == uuidBad, "W11 留下来的是有 uuid 的那一项");
        check(!list.isEmpty() && !list.at(0).isCurrent,
              "W11 活动槽是空的 → 谁都不标「当前」");

        QString error;
        check(!AccountStore::activate(uuidBad, &error),
              "W11 切一份缺了微软那半的凭据 → 失败");
        check(!error.isEmpty(), "W11 而且提示重新登录一次", error);
        check(AccountStore::activeUuid().isEmpty(),
              "W11 失败之后活动槽仍然是空的（没写进半份凭据）");
    }

    // ---- W12 离线 uuid 的推法（纯函数） ----
    // 期望值是**独立算出来**的（python -c 按 md5("OfflinePlayer:"+名字) 加版本位/变体位），
    // 不是拿被测代码自己跑一遍当答案 —— 那样只能证明"它和它自己一致"。
    {
        check(AccountStore::offlineUuidFor(QStringLiteral("Notch")) ==
                  QStringLiteral("b50ad385829d3141a2167e7d7539ba7f"),
              "W12 Notch 的离线 uuid 和游戏自己那套规则算出来的一致",
              AccountStore::offlineUuidFor(QStringLiteral("Notch")));
        check(AccountStore::offlineUuidFor(QStringLiteral("Steve")) ==
                  QStringLiteral("5627dd98e6be3c21b8a8e92344183641"),
              "W12 Steve 也是",
              AccountStore::offlineUuidFor(QStringLiteral("Steve")));
        check(AccountStore::offlineUuidFor(QStringLiteral("离线测试")) ==
                  QStringLiteral("97247186eee73f638958c7740bee3775"),
              "W12 非 ASCII 名字按 UTF-8 字节算（这一步最容易写错成 QString::toLocal8Bit）",
              AccountStore::offlineUuidFor(QStringLiteral("离线测试")));

        const QString uuid = AccountStore::offlineUuidFor(QStringLiteral("Notch"));
        check(uuid.size() == 32, "W12 是 32 位不带横线的那种", QString::number(uuid.size()));
        check(uuid == uuid.toLower(), "W12 全小写（和档案里给的 profile.id 一个形态）");
        // 版本位/变体位：md5 的直接输出不是合法 uuid，得按 RFC 4122 摆过才和游戏一致。
        // 少了这一步，值看着**一样是 32 位十六进制**，只是永远对不上 —— 不报错的那种错。
        check(uuid.at(12) == QLatin1Char('3'), "W12 版本位是 3（RFC 4122 的 v3）",
              QString(uuid.at(12)));
        check(QStringLiteral("89ab").contains(uuid.at(16)),
              "W12 变体位是 RFC 4122 那一档（8/9/a/b）", QString(uuid.at(16)));
        check(AccountStore::offlineUuidFor(QStringLiteral("Notch")) == uuid,
              "W12 同一个名字推两次是同一个值（否则每次开窗都是新身份）");
        check(AccountStore::offlineUuidFor(QStringLiteral("notch")) != uuid,
              "W12 大小写算两个名字（游戏那边也这么算）");
    }

    // ---- W13 名字不合法的那几条：一条都不许进列表，也不许把人踢下线 ----
    // 现场：W11 那份手写列表里还剩一条（HalfBaked），再收一个正常的在线账号进来。
    {
        putActiveCredentials(QStringLiteral("W13"), uuidA, QStringLiteral("Alice"),
                             QStringLiteral("rt-A"));
        check(AccountStore::captureActive(), "W13 前提：收一个在线账号 Alice 进列表");
        const int before = AccountStore::accounts().size();

        const QStringList bad = {QString(),
                                 QStringLiteral("   "),
                                 QStringLiteral("有 空格"),
                                 QStringLiteral("带\t制表符"),
                                 QString(17, QLatin1Char('x'))};
        for (const QString &name : bad) {
            QString error;
            check(!AccountStore::addOffline(name, &error),
                  QStringLiteral("W13 「%1」加不进去（%2 个字符）")
                      .arg(name, QString::number(name.size())));
            check(!error.isEmpty(), "W13 而且给了原因，不是闷着失败", error);
        }
        check(AccountStore::accounts().size() == before,
              "W13 那五条失败一条都没进列表",
              QString::number(AccountStore::accounts().size()));
        check(AccountStore::activeUuid() == uuidA,
              "W13 失败之后当前账号还是 Alice（加离线账号失败不许把人踢下线）",
              AccountStore::activeUuid());
        check(TokenStore::hasValue(TokenStore::minecraftKey()),
              "W13 活动槽里那份凭据也还在");
    }

    // ---- W14 加一条离线账号：进列表、成当前账号、活动槽清空 ----
    {
        const QString offlineUuid = AccountStore::offlineUuidFor(QStringLiteral("Steve"));
        const int before = AccountStore::accounts().size();

        QString error;
        check(AccountStore::addOffline(QStringLiteral("Steve"), &error),
              "W14 Steve 加得进去", error);
        check(AccountStore::contains(offlineUuid), "W14 列表里认得出它");
        check(AccountStore::nameOf(offlineUuid) == QStringLiteral("Steve"),
              "W14 名字就是它", AccountStore::nameOf(offlineUuid));
        check(AccountStore::accounts().size() == before + 1, "W14 只多了一条",
              QString::number(AccountStore::accounts().size()));

        SavedAccount found;
        check(AccountStore::find(offlineUuid, &found) && found.offline,
              "W14 这一项带着「离线」那个标志（界面靠它挂「（离线）」）");
        check(AccountStore::find(offlineUuid, &found) && found.isCurrent,
              "W14 而且它就是当前账号（加完顺手切过去）");
        check(!AccountStore::isOffline(uuidA), "W14 在线那条不会被认成离线账号");

        // 盘上那一项**真的没有**凭据副本 —— 这是"离线账号"这句话的字面意思。
        // 走原始 JSON 看（SavedAccount 里不带副本，从 find() 看不出来）。
        QJsonArray raw = TokenStore::readJson(TokenStore::accountsKey())
                             .value(QStringLiteral("accounts"))
                             .toArray();
        bool sawOffline = false;
        for (const QJsonValue &value : raw) {
            const QJsonObject item = value.toObject();
            if (item.value(QStringLiteral("uuid")).toString() != offlineUuid) {
                continue;
            }
            sawOffline = true;
            check(item.value(QStringLiteral("offline")).toBool(),
                  "W14 盘上写着 offline = true");
            check(!item.contains(QStringLiteral("microsoft")) &&
                      !item.contains(QStringLiteral("minecraft")),
                  "W14 这一项里一个凭据字节都没有（离线账号就是只有名字）");
        }
        check(sawOffline, "W14 原始列表里确实有这一项（上面那两条才有东西可验）");

        // 加完 = 离开在线身份：活动槽两份都空掉。
        check(!TokenStore::hasValue(TokenStore::microsoftKey()) &&
                  !TokenStore::hasValue(TokenStore::minecraftKey()),
              "W14 活动槽被清空了（离线身份没有凭据那一半）");
        // 这一条钉的就是 activeUuid() 改动的那个点：活动槽空着、而当前是离线账号。
        check(AccountStore::activeUuid() == offlineUuid,
              "W14 活动槽空着也认得出当前是谁（离线账号的第二档）",
              AccountStore::activeUuid());
        // 但那个在线账号**没丢**：它的副本还在列表里，点一下就回来（下一节验）。
        check(AccountStore::contains(uuidA), "W14 原来那个在线账号还在列表里，没被顶掉");

        // 同名再加一次 = 就地更新，不出现第二条 Steve。
        const int afterFirst = AccountStore::accounts().size();
        check(AccountStore::addOffline(QStringLiteral("Steve"), &error),
              "W14 同一个名字再加一次也成功", error);
        check(AccountStore::accounts().size() == afterFirst,
              "W14 但列表条数没变（同一个名字 = 同一个人）",
              QString::number(AccountStore::accounts().size()));
    }

    // ---- W15 在线 ↔ 离线来回切 ----
    {
        const QString offlineUuid = AccountStore::offlineUuidFor(QStringLiteral("Steve"));

        // 切回在线：凭据被写回活动槽，当前账号跟着换。
        QString error;
        check(AccountStore::activate(uuidA, &error),
              "W15 切回在线账号 Alice", error);
        check(AccountStore::activeUuid() == uuidA, "W15 当前账号换成 Alice",
              AccountStore::activeUuid());
        check(TokenStore::hasValue(TokenStore::microsoftKey()) &&
                  TokenStore::hasValue(TokenStore::minecraftKey()),
              "W15 活动槽那两份凭据都回来了");
        check(!AccountStore::isOffline(uuidA), "W15 切回来之后它不是离线账号");

        // 再切到离线：这一档一个凭据字节都不碰，也不会失败。
        check(AccountStore::activate(offlineUuid, &error), "W15 再切到离线账号 Steve", error);
        check(AccountStore::activeUuid() == offlineUuid, "W15 当前账号换成 Steve",
              AccountStore::activeUuid());
        check(!TokenStore::hasValue(TokenStore::minecraftKey()),
              "W15 活动槽又被清空了");

        // 回归钉子①：活动槽空着 + 记录键指向一个**在线**账号 → 必须是"没登录"。
        // 不卡这一条的话，删掉当前账号之后界面还会说"当前是某某"（记录键上写着它）。
        TokenStore::clear(TokenStore::microsoftKey());
        TokenStore::clear(TokenStore::minecraftKey());
        QSettings settings;
        settings.setValue(TokenStore::currentUuidKey(), uuidA);
        settings.sync();
        check(AccountStore::activeUuid().isEmpty(),
              "W15 活动槽空着时，记录键指向在线账号**不算**当前（= 没登录）",
              AccountStore::activeUuid());

        // 回归钉子②：记录键指向一个**不在列表里**的 uuid → 也是"没登录"（孤儿键）。
        settings.setValue(TokenStore::currentUuidKey(),
                          QStringLiteral("cccccccccccccccccccccccccccccccc"));
        settings.sync();
        check(AccountStore::activeUuid().isEmpty(),
              "W15 记录键指向列表里没有的账号 → 也是「没登录」（孤儿键不算数）",
              AccountStore::activeUuid());

        // 收拾回"当前是离线账号"，顺便验 remove()。
        check(AccountStore::activate(offlineUuid, &error) &&
                  AccountStore::activeUuid() == offlineUuid,
              "W15 切回离线账号（上面两条钉子之后盘上还是能恢复的）");
        check(AccountStore::remove(offlineUuid), "W15 删掉离线账号 Steve");
        check(!AccountStore::contains(offlineUuid), "W15 列表里没了");
        check(AccountStore::activeUuid().isEmpty(),
              "W15 删的是当前账号 → 当前也空了（离线账号同样适用这条）",
              AccountStore::activeUuid());
        check(!QSettings().contains(TokenStore::currentUuidKey()),
              "W15 记录键也一并清掉，不留孤儿");
    }

    // ---- W16 边界：16 个字符收得下（17 个在 W13 已经拒了） ----
    {
        const QString name = QString(16, QLatin1Char('y'));
        QString error;
        check(AccountStore::addOffline(name, &error),
              "W16 16 个字符是收的（上限就是 16）", error);
        check(AccountStore::isOffline(AccountStore::offlineUuidFor(name)),
              "W16 而且它确实是一条离线账号");
        check(AccountStore::remove(AccountStore::offlineUuidFor(name)),
              "W16 收尾：把它删掉");
    }

    QSettings::setDefaultFormat(QSettings::NativeFormat);
    QDir(settingsDir).removeRecursively();

    // ============================================================================
    // X 节：皮肤/披风那几条接口的纯函数。全是纯函数 —— 不联网、不碰盘，也不碰上面的沙盒。
    // ============================================================================
    section("X. 皮肤/披风接口的纯函数（解析 / variant / multipart / 话术）");

    const QString skinClassic = QStringLiteral("https://textures.minecraft.net/texture/aaa");
    const QString skinSlim = QStringLiteral("https://textures.minecraft.net/texture/bbb");
    const QString capeUrl = QStringLiteral("https://textures.minecraft.net/texture/ccc");

    // ---- X1 解当前皮肤：有 ACTIVE 就用 ACTIVE，没有才退回第一件能用的 ----
    {
        const QByteArray twoSkins =
            QStringLiteral(R"J({"skins":[)J"
                           R"J({"id":"1","state":"INACTIVE","url":"%1","variant":"CLASSIC"},)J"
                           R"J({"id":"2","state":"ACTIVE","url":"%2","variant":"SLIM"}]})J")
                .arg(skinClassic, skinSlim)
                .toUtf8();
        const SkinSummary chosen = SkinApi::parseCurrentSkin(twoSkins);
        check(chosen.url == skinSlim, "X1 有 ACTIVE 就选 ACTIVE 那一件（哪怕它排在后面）",
              chosen.url);
        check(chosen.variant == QStringLiteral("slim"),
              "X1 顺带把小写形态也解出来了（读回来的是大写 SLIM）", chosen.variant);
        check(!chosen.isEmpty(), "X1 解出来的不是空的");

        // 旧档案里 state 可能整个字段都没有。那时退回第一件**有 url 的**。
        const QByteArray noState =
            QStringLiteral(R"J({"skins":[{"url":"%1"},{"url":"%2"}]})J")
                .arg(skinClassic, skinSlim)
                .toUtf8();
        check(SkinApi::parseCurrentSkin(noState).url == skinClassic,
              "X1 没有 state 字段 → 退回第一件");

        // 没有 url 的项不能"占住"退回的位置 —— 它连图都下不了。
        const QByteArray blankFirst =
            QStringLiteral(R"J({"skins":[{"id":"1"},{"url":"%1"}]})J").arg(skinSlim).toUtf8();
        check(SkinApi::parseCurrentSkin(blankFirst).url == skinSlim,
              "X1 url 为空的项被跳过，退回的是第一件真的有 url 的");

        check(SkinApi::parseCurrentSkin(QByteArrayLiteral(R"J({"skins":[]})J")).isEmpty(),
              "X1 skins 是空数组 → 空摘要（= 这份档案没有皮肤信息）");
        check(SkinApi::parseCurrentSkin(QByteArrayLiteral("<html>404</html>")).isEmpty(),
              "X1 body 根本不是 JSON → 空摘要（不能把一页 HTML 当皮肤）");
        check(SkinApi::parseCurrentSkin(QByteArray()).isEmpty(), "X1 空 body → 空摘要");
    }

    // ---- X2 variant 只有 slim 认 slim ----
    // 协议本身的默认值是 classic：档案里没有 variant 字段就是经典模型。所以"认不出来"
    // 必须落到 classic，**不能**落到 slim（那会让所有人的模型悄悄变成 Alex）。
    {
        check(SkinApi::normalizeVariant(QStringLiteral("SLIM")) == QStringLiteral("slim"),
              "X2 读回来的大写 SLIM → slim");
        check(SkinApi::normalizeVariant(QStringLiteral("slim")) == QStringLiteral("slim"),
              "X2 已经是小写的 slim → slim");
        check(SkinApi::normalizeVariant(QStringLiteral("Slim")) == QStringLiteral("slim"),
              "X2 大小写混着写也认");
        check(SkinApi::normalizeVariant(QStringLiteral("CLASSIC")) == QStringLiteral("classic"),
              "X2 CLASSIC → classic");
        check(SkinApi::normalizeVariant(QString()) == QStringLiteral("classic"),
              "X2 空串（档案里没这个字段）→ classic，这是协议默认值");
        check(SkinApi::normalizeVariant(QStringLiteral("Cape")) == QStringLiteral("classic"),
              "X2 认不出来的值 → classic，不回落到 slim");
    }

    // ---- X3 解披风列表 ----
    {
        const QByteArray body =
            QStringLiteral(R"J({"capes":[)J"
                           R"J({"id":"c1","alias":"Migrator","url":"%1","state":"ACTIVE"},)J"
                           R"J({"id":"c2","alias":"MineCon 2016","url":"%2","state":"inactive"},)J"
                           R"J({"id":"c3"})J"
                           R"J(]})J")
                .arg(capeUrl, capeUrl)
                .toUtf8();
        const QList<OwnedCape> capes = SkinApi::parseCapes(body);
        check(capes.size() == 3, "X3 三件都解出来了", QString::number(capes.size()));
        const auto capeAt = [&capes](int i) {
            return i >= 0 && i < capes.size() ? capes.at(i) : OwnedCape();
        };
        check(capeAt(0).id == QStringLiteral("c1") && capeAt(0).alias == QStringLiteral("Migrator"),
              "X3 id 和显示名都解出来了");
        check(capeAt(0).active, "X3 state=ACTIVE → 标成当前披风");
        check(!capeAt(1).active, "X3 state=inactive（小写）→ 不是当前披风");
        check(capeAt(2).alias == QStringLiteral("c3"),
              "X3 没带 alias → 退回 id（列表上不能显示成空白）", capeAt(2).alias);
        check(capeAt(2).url.isEmpty() && !capeAt(2).active,
              "X3 只有 id 的项照样摆出来（能点，只是没缩略图）");

        // 没有 id 的项**丢掉**：PUT 要的就是 id，摆一件点了没反应的披风不如不摆。
        const QByteArray noId =
            QStringLiteral(R"J({"capes":[{"alias":"没有 id","url":"%1","state":"ACTIVE"}]})J")
                .arg(capeUrl)
                .toUtf8();
        check(SkinApi::parseCapes(noId).isEmpty(), "X3 没有 id 的项被丢掉（点了也设不成当前）");

        check(SkinApi::parseCapes(QByteArrayLiteral(R"J({"capes":[]})J")).isEmpty(),
              "X3 一件披风都没有 → 空列表（常态化，不是错误）");
        check(SkinApi::parseCapes(QByteArrayLiteral("not json")).isEmpty(),
              "X3 body 不是 JSON → 空列表，不抛");
        check(SkinApi::parseCapes(QByteArray()).isEmpty(), "X3 空 body → 空列表");

        // **裸数组**那种形状（没有外层那个 "capes" 键）：旧的 `api.mojang.com` 那条查披风
        // 的路、以及别的启动器从 OpenAPI 那边看到的就是它。上面几条喂的全是"外层是对象"
        // 那份（**产品走的就是这份**，见 X7），只有这一组钉得住另一种。
        // NOTE: 产品**不发**一条独立的"列披风"请求 —— 那条路由不存在（2026-09-22 的 404）。
        const QByteArray bareCapes =
            QStringLiteral(R"J([{"id":"c1","alias":"Migrator","url":"%1","state":"ACTIVE"},)J"
                           R"J({"id":"c2","alias":"MineCon 2016","url":"%2","state":"INACTIVE"}])J")
                .arg(capeUrl, capeUrl)
                .toUtf8();
        const QList<OwnedCape> fromBare = SkinApi::parseCapes(bareCapes);
        check(fromBare.size() == 2,
              "X3 裸数组（/capes 那种形状）也解得出来 —— 只认一种的话这里会是 0",
              QString::number(fromBare.size()));
        if (fromBare.size() == 2) {
            check(fromBare.at(0).id == QStringLiteral("c1") &&
                      fromBare.at(0).alias == QStringLiteral("Migrator") && fromBare.at(0).active,
                  "X3 裸数组里 ACTIVE 那件照样认成当前披风、alias 照样读出来");
            check(fromBare.at(1).url == capeUrl && !fromBare.at(1).active,
                  "X3 裸数组里的 url 也读出来了（INACTIVE 那件不是当前）");
        }
        check(SkinApi::parseCapes(QByteArrayLiteral("[]")).isEmpty(),
              "X3 裸空数组 → 空列表（和「解不出来」分不开，但至少不抛）");
        check(SkinApi::parseCapes(QByteArrayLiteral(R"J({"capes":null})J")).isEmpty(),
              "X3 capes 显式是 null → 空列表，不抛");
    }

    // ---- X4 皮肤尺寸只有 64×64 和 64×32 两种 ----
    // 老格式（64×32）到现在还有人在用，所以两种都收。判据只看宽高：官方那边也校验，
    // 但它在传上去之后才回一句英文 400，用户白等一圈。
    {
        check(SkinApi::isAcceptableSkinSize(64, 64), "X4 64×64（新格式）收");
        check(SkinApi::isAcceptableSkinSize(64, 32), "X4 64×32（老格式）也收");
        check(!SkinApi::isAcceptableSkinSize(128, 128), "X4 128×128 不收（那是高清皮肤，官方不收）");
        check(!SkinApi::isAcceptableSkinSize(64, 128), "X4 64×128 不收");
        check(!SkinApi::isAcceptableSkinSize(128, 64), "X4 128×64 不收");
        check(!SkinApi::isAcceptableSkinSize(63, 64), "X4 63×64 不收");
        check(!SkinApi::isAcceptableSkinSize(64, 31), "X4 64×31 不收");
        check(!SkinApi::isAcceptableSkinSize(0, 0), "X4 0×0 不收（读不出来的图）");
    }

    // ---- X5 multipart 请求体 ----
    {
        const QByteArray boundary = QByteArrayLiteral("----WTFMLBoundary1234");
        // 故意在 PNG 字节里塞 CRLF 和一个 NUL：手写 multipart 最容易折的就是这种字节
        // （按文本处理会把它们改成别的，官方收到一张坏图、回一句看不懂的错）。
        QByteArray png;
        png.append(QByteArrayLiteral("\x89PNG\r\n\x1a\n"));
        png.append(QByteArrayLiteral("\x00\x00\x00\x0dIHDR"));
        png.append(QByteArrayLiteral("\r\n\x00\xff\xfe"));

        const QByteArray body = SkinApi::skinUploadBody(png, QStringLiteral("SLIM"), boundary);
        check(body.contains(png), "X5 皮肤字节**原样**在请求体里（CRLF 和 NUL 都没被折）");
        check(body.contains(QByteArrayLiteral("name=\"variant\"\r\n\r\nslim\r\n")),
              "X5 variant 段写的是**小写**（大写进来也小写出去）",
              QString::fromLatin1(body.left(200)));
        check(body.contains(QByteArrayLiteral("name=\"file\"; filename=\"skin.png\"")),
              "X5 file 那一段带着文件名");
        check(body.contains(QByteArrayLiteral("Content-Type: image/png\r\n\r\n")),
              "X5 file 那一段写明了 Content-Type（不写官方会当文本收）");
        // 两段各自的起始 + 结尾那一条，一共三条边界。
        check(body.count(boundary) == 3, "X5 三条 boundary（两段开头 + 结尾一条）",
              QString::number(body.count(boundary)));
        check(body.startsWith(QByteArrayLiteral("--") + boundary + QByteArrayLiteral("\r\n")),
              "X5 请求体以第一段的 boundary 开头");
        check(body.endsWith(QByteArrayLiteral("--") + boundary + QByteArrayLiteral("--\r\n")),
              "X5 以结尾那条边界收尾（少了官方解不出最后一段）");
        // 段落之间是**空行**（\r\n\r\n）：头部和正文之间必须有一个，少一个整段就废了。
        check(body.contains(QByteArrayLiteral("variant\"\r\n\r\n")) &&
                  body.contains(QByteArrayLiteral("image/png\r\n\r\n")),
              "X5 头部和正文之间都有那个空行");

        check(SkinApi::skinUploadContentType(boundary) ==
                  QByteArrayLiteral("multipart/form-data; boundary=") + boundary,
              "X5 Content-Type 里带着同一个 boundary");
    }

    // ---- X6 失败话术（401 / 403 / 404 / 别的，各是各的行动） ----
    {
        const QString what = QStringLiteral("上传皮肤失败");

        const QString expired = SkinApi::failureText(httpReply(401, QByteArray()), what);
        check(expired.contains(what), "X6 401 那句话带着「在做什么」", expired);
        check(expired.contains(QStringLiteral("重新登录")),
              "X6 401 → 说清是登录态那件事（用户的动作是重新登录）", expired);

        // 403 有两种：应用没被批准（要提交申请）和权限不够。这里验的是**后者** ——
        // 正文里没有那句 "Invalid app registration" 时不能瞎指路。
        const QString forbidden = SkinApi::failureText(httpReply(403, QByteArray()), what);
        check(forbidden.contains(QStringLiteral("403")), "X6 403（通用）→ 说清是 403", forbidden);
        check(!forbidden.contains(QStringLiteral("aka.ms")),
              "X6 403 通用那种**不许**指到「提交申请」（那是另一种 403）", forbidden);

        // 正文里带了那句 → 转成能照着做的那段话（和登录那条路同一个口径）。
        const QByteArray notApproved =
            QByteArrayLiteral(R"({"errorMessage":"Invalid app registration"})");
        const QString hint = SkinApi::failureText(httpReply(403, notApproved), what);
        check(hint.contains(QStringLiteral("aka.ms/mce-reviewappid")),
              "X6 403 +「Invalid app registration」→ 给出提交申请那个地址（和登录那条路一致）",
              hint);
        check(hint.contains(QStringLiteral("不用换账号")),
              "X6 那段话要说明账号本身没问题（否则用户会去换账号、重登）");

        const QString missing = SkinApi::failureText(httpReply(404, QByteArray()), what);
        check(missing.contains(QStringLiteral("没有可改的 Minecraft 档案")),
              "X6 404 → 说清是「这个账号没有档案」（比如没买游戏）", missing);

        // 429：限流。**不许**跟下面那条通用分支走 —— 通用分支认的正是正文里那个 `error`
        // 字段（Minecraft 服务 429 时它就是 "TOO_MANY_REQUESTS"），端给用户等于说了句
        // 他照做不了的话。2026-09-22 真机日志里那句
        // "读取披风失败（HTTP 429）：TOO_MANY_REQUESTS" 就是从这儿来的。
        const QByteArray tooMany = QByteArrayLiteral(
            R"({"path":"/minecraft/profile","errorType":"TOO_MANY_REQUESTS","error":"TOO_MANY_REQUESTS","status":429})");
        const QString throttled = SkinApi::failureText(httpReply(429, tooMany), what);
        check(throttled.contains(what) && throttled.contains(QStringLiteral("429")),
              "X6 429 → 说清哪一步、什么状态码（日志里那行要能对得上）", throttled);
        check(!throttled.contains(QStringLiteral("TOO_MANY_REQUESTS")),
              "X6 429 **不**把官方那个错误码端给用户（它一个字都没说该干什么）", throttled);
        check(throttled.contains(QStringLiteral("等一两分钟")),
              "X6 429 → 下一步是等一会儿（不是重新登录、也不是换账号）", throttled);
        check(throttled.contains(QStringLiteral("这不是账号")),
              "X6 429 → 说明这跟账号无关（否则用户会去换账号、重登，那都没用）", throttled);
        check(throttled == HttpClient::throttledText(what),
              "X6 429 那句话的唯一出处是 HttpClient::throttledText()（登录链说的是同一句）");

        const QByteArray badSize = QByteArrayLiteral(
            R"({"errorMessage":"Skin must be 64x64 or 64x32","path":"/minecraft/profile/skins","traceId":"abc"})");
        const QString detailed = SkinApi::failureText(httpReply(400, badSize), what);
        check(detailed.contains(QStringLiteral("Skin must be 64x64 or 64x32")),
              "X6 别的状态码 → 把官方那句原因带出来", detailed);
        check(!detailed.contains(QStringLiteral("traceId")) &&
                  !detailed.contains(QStringLiteral("/minecraft/profile/skins")),
              "X6 但只带原因，**不把正文里别的键（path / traceId）丢给用户看**", detailed);

        const QString bare = SkinApi::failureText(httpReply(500, QByteArray()), what);
        check(bare.contains(QStringLiteral("500")) && bare.contains(what),
              "X6 什么正文都没有 → 至少说清哪一步、什么状态码", bare);
        // 正文是 HTML（代理塞网页那种）时 bodyDetail 取不到字段，要走通用那条，不能空。
        check(!SkinApi::failureText(httpReply(502, QByteArrayLiteral("<html>502 Bad Gateway</html>")), what)
                   .isEmpty(),
              "X6 body 不是 JSON 也不会返回空串");

        // 断网 / DNS 解析不了 / 超时被 abort：**没有 HTTP 状态码**（HttpClient 给的初值
        // 是 -1）。这条分支是这一版补上的 —— 以前报出来的是「读取披风失败（HTTP -1）。」，
        // 用户既不知道该去查网络，还看见一个不存在的状态码。
        const QString offline =
            SkinApi::failureText(httpReplyFailed(QStringLiteral("Host not found")), what);
        check(offline.contains(what), "X6 没连上 → 也要说清是哪一步在干什么", offline);
        check(offline.contains(QStringLiteral("Host not found")),
              "X6 没连上 → 把网络那句原因带出来（用户要拿它去查网络/代理）", offline);
        check(!offline.contains(QStringLiteral("-1")) &&
                  !offline.contains(QStringLiteral("HTTP")),
              "X6 没连上 **不许**端出一个不存在的状态码（HTTP -1）", offline);
    }

    // ---- X7 披风列表来自**档案**那条地址（没有一条独立的 /capes 路由） ----
    // 这一条钉的是一个**没有纯函数可验**的东西：请求打到哪个地址。2026-09-22 真机上披风
    // 一直回 404，根因就是这里原来有一条 `GET /minecraft/profile/capes` —— 按"设披风、
    // 取消披风都在 /capes/active 下，那把拥有的列一遍大概也在 /capes 下"对称猜出来的，
    // 而那条路由**不存在**（对过 Mojang 的 OpenAPI：那一层只有 /capes/active 两个方法）。
    // 它之所以能活到真机上，是因为路径原本是个 .cpp 私有常量，离线跑的几个工程一行都碰不到。
    {
        check(SkinApi::profilePath() == QStringLiteral("/minecraft/profile"),
              "X7 档案那条路径是 /minecraft/profile", SkinApi::profilePath());
        check(SkinApi::baseUrl() + SkinApi::profilePath() ==
                  QStringLiteral("https://api.minecraftservices.com/minecraft/profile"),
              "X7 于是「档案 / 皮肤当前状态 / 披风列表」是同一个地址",
              SkinApi::baseUrl() + SkinApi::profilePath());
        // 反面：它**不是** `/minecraft/profile/capes` 那种独立路由。这条写成这样，是为了让
        // "又猜了一条不存在的路由"有一句断言拦着，而不是等真机上再看到一个 404。
        check(!SkinApi::profilePath().endsWith(QStringLiteral("/capes")),
              "X7 而且它不是那条不存在的 /capes（404 的真因，别再加回来）",
              SkinApi::profilePath());
    }
}

// ---------------------------------------------------------------------------
// V. 整合包导入（Modrinth 格式）：清单解析、路径判据、按前缀解压
//
// 三层各验各的，因为它们的错法完全不同：
//   * 纯函数（ModpackImport）：一段 json 进去、一个结果出来，不碰磁盘不联网；
//   * ZipUtil 那两个新函数：真造一个压缩包、真解一次 —— 下面 V5 钉的两个坑都是实测
//     踩出来的（条目名里的反斜杠、两个前缀的优先级）；
//   * 真清单：meta/modrinth-index-att2.json 是从一个真整合包（779 MB，ATT2）里原样
//     读出来的，用它证"真实的一百多条路径一条都没被误判"—— 自造的假 json 只会证回
//     我自己以为的格式。
// ---------------------------------------------------------------------------
// =========================================================================
// Y 节：下载页那四个分类 + 四个加载器的「能挑哪些版本」。
//
// 这一节全是**真数据**（meta/ 下那几份夹具都是原样存下来的真响应），因为要证的恰恰是
// 「这份真清单/真清单文件里的分布对不对」—— 自己编几条只能证明「我按我写的规则分了堆」。
// =========================================================================
static void runVersionChannelTests() {
    const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";

    // ---------------------------------------------------------------------
    section("Y. 版本四分类（真清单 915 条）");
    // ---------------------------------------------------------------------

    QList<MinecraftVersion> manifest;
    QStringList manifestIds;
    {
        QFile fixture(metaDir + "/manifest.json");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "Y1 读到了真清单夹具（meta/manifest.json）");
        if (!haveFixture) {
            return;
        }
        const QByteArray json = fixture.readAll();
        fixture.close();

        // 走产品自己那条解析路（DownloadManager::parseVersionManifest），不是在这儿再写一份
        // 解析 —— 否则这一节验的是「测试怎么读清单」，和产品读出来的是不是同一份就没保证了。
        DownloadManager downloadManager;
        downloadManager.parseVersionManifest(QJsonDocument::fromJson(json));
        manifest = downloadManager.getAvailableVersions();
        check(manifest.size() == 915, "Y1 产品那条解析路读出 915 条",
              QString::number(manifest.size()));
        if (manifest.size() != 915) {
            return;
        }

        // type 必须带出来 —— 四分类的前三类全靠它，丢了的话前三个分类会一起空掉，
        // 而"空掉"在界面上和"这个版本没有版本"长得一模一样，所以得在这儿钉住。
        int typed = 0;
        for (const MinecraftVersion &version : manifest) {
            if (!version.type.isEmpty()) {
                ++typed;
            }
            manifestIds.append(version.id);
        }
        check(typed == manifest.size(), "Y1 每一条的 type 都读出来了（前三类的判据来源）",
              QStringLiteral("%1/%2").arg(typed).arg(manifest.size()));
    }

    const QList<VersionManager::VersionChannel> channels =
        VersionManager::groupIntoChannels(manifest);

    // --- Y2. 分堆的账 -----------------------------------------------------
    check(channels.size() == VersionCategory::channelCount(), "Y2 分出来就是四堆",
          QString::number(channels.size()));
    if (channels.size() != VersionCategory::channelCount()) {
        return;
    }
    check(channels.at(0).channel == VersionCategory::Channel::Release &&
              channels.at(1).channel == VersionCategory::Channel::Snapshot &&
              channels.at(2).channel == VersionCategory::Channel::Old &&
              channels.at(3).channel == VersionCategory::Channel::AprilFools,
          "Y2 四堆的顺序 = 界面上从上到下的顺序（正式/快照/远古/愚人节）");

    const QStringList expectedTexts{QStringLiteral("正式版"), QStringLiteral("快照版"),
                                    QStringLiteral("远古版"), QStringLiteral("愚人节版")};
    const QStringList expectedKeys{QStringLiteral("release"), QStringLiteral("snapshot"),
                                   QStringLiteral("old"), QStringLiteral("aprilfools")};
    bool textsOk = true;
    bool keysOk = true;
    for (int i = 0; i < 4; ++i) {
        if (channels.at(i).text != expectedTexts.at(i)) {
            textsOk = false;
        }
        if (channels.at(i).key != expectedKeys.at(i)) {
            keysOk = false;
        }
    }
    check(textsOk, "Y2 四段文字对得上", channels.at(3).text);
    check(keysOk, "Y2 四个键对得上（界面认键、不认文字）", channels.at(3).key);

    const int expectedCounts[4] = {103, 742, 61, 9};
    const QString expectedNotes[4] = {
        QStringLiteral("Y2 正式版 103 条（清单里的 release 一共就这些）"),
        QStringLiteral("Y2 快照版 742 条（愚人节那 9 条已经从 751 条里摘走了）"),
        QStringLiteral("Y2 远古版 61 条（old_beta 26 + old_alpha 35，两样都要收）"),
        QStringLiteral("Y2 愚人节版 9 条")};
    for (int i = 0; i < 4; ++i) {
        check(channels.at(i).versions.size() == expectedCounts[i], expectedNotes[i],
              QString::number(channels.at(i).versions.size()));
    }

    int total = 0;
    QStringList allIds;
    for (const VersionManager::VersionChannel &channel : channels) {
        total += channel.versions.size();
        for (const MinecraftVersion &version : channel.versions) {
            allIds.append(version.id);
        }
    }
    check(total == manifest.size(), "Y2 四堆加起来一条不丢",
          QStringLiteral("%1 vs %2").arg(total).arg(manifest.size()));
    check(allIds.size() == QSet<QString>(allIds.begin(), allIds.end()).size(),
          "Y2 也没有哪一条进了两堆（上面那件事的另一面）");
    // 顺序原样（清单本来就是新到旧）。重排过的话界面上第一条就不是最新的那个了。
    check(channels.at(0).versions.value(0).id == QStringLiteral("26.3"),
          "Y2 正式版第一条是 26.3（顺序原样，没被重排）",
          channels.at(0).versions.value(0).id);
    check(channels.at(1).versions.value(0).id == QStringLiteral("26.3-rc-3"),
          "Y2 快照版第一条是 26.3-rc-3", channels.at(1).versions.value(0).id);
    check(channels.at(2).versions.value(0).id == QStringLiteral("b1.8.1"),
          "Y2 远古版第一条是 b1.8.1（清单里 old_beta 排在 old_alpha 前面）",
          channels.at(2).versions.value(0).id);

    // 每一条的 type 和它落的那一堆必须对得上 —— 这是"前三类照抄 type"这件事本身
    int mismatched = 0;
    for (const VersionManager::VersionChannel &channel : channels) {
        for (const MinecraftVersion &version : channel.versions) {
            if (VersionCategory::channelFor(version.id, version.type) != channel.channel) {
                ++mismatched;
            }
        }
    }
    check(mismatched == 0, "Y2 每一堆里的每一条都是按 channelFor 的结论放进去的",
          QString::number(mismatched));

    // --- Y2b. 「最新版本」那一组的两条 --------------------------------------
    //
    // 树上最上面那一组（用户原话：「下载游戏那个界面最上方放一个 最新版本 类，默认展开，
    // 里面放最新的正式版和快照」）。这里钉的是**挑哪两条**这件事本身 —— 界面那一侧
    // （摆在哪、默认展开、点一下是什么）由 mw_check 管，视觉由 ui_shot 07d 管。
    const QList<VersionManager::LatestVersion> latest = VersionManager::latestVersions(manifest);
    check(latest.size() == 2, "Y2b 清单上挑得出两条（一个正式版、一个快照）",
          QString::number(latest.size()));
    check(latest.size() == 2 &&
              latest.at(0).channel == VersionCategory::Channel::Release &&
              latest.at(1).channel == VersionCategory::Channel::Snapshot,
          "Y2b 顺序固定：正式版在前、快照在后（不是按清单里的先后）",
          QStringLiteral("%1 条").arg(latest.size()));
    if (latest.size() != 2) {
        return;
    }
    check(latest.at(0).version.id == QStringLiteral("26.3") &&
              latest.at(1).version.id == QStringLiteral("26.3-rc-3"),
          "Y2b 这份夹具上挑出来的是 26.3 与 26.3-rc-3（清单前两条，一条一版）",
          latest.at(0).version.id + QStringLiteral(" / ") + latest.at(1).version.id);
    // 和"它自己那一堆的第一条"必须是**同一份数据**：两处各挑各的，早晚会出现
    // "最新版本里写着 A、正式版那一栏的第一条却是 B"。
    check(latest.at(0).version.releaseTime == channels.at(0).versions.value(0).releaseTime &&
              latest.at(0).version.type == channels.at(0).versions.value(0).type &&
              latest.at(1).version.releaseTime == channels.at(1).versions.value(0).releaseTime &&
              latest.at(1).version.type == channels.at(1).versions.value(0).type,
          "Y2b 那两条就是「正式版 / 快照版」两堆各自的头一条（同一份数据、不是各挑各的）");

    // 清单是空的（离线 / 第一发就失败）⇒ 一条都没有。界面照旧把那一组摆出来，里面是空的。
    check(VersionManager::latestVersions({}).isEmpty(), "Y2b 空清单挑出来就是空的（不是两条空的）");

    // 缺哪一类就只有一条 —— **不许**拿另一类去补位。这份清单里只有快照没有正式版。
    QList<MinecraftVersion> onlySnapshot;
    onlySnapshot.append(MinecraftVersion{QStringLiteral("26.3-rc-3"), QStringLiteral("snapshot"),
                                         QString(), QString(),
                                         QStringLiteral("2026-09-14T12:58:38+00:00")});
    const QList<VersionManager::LatestVersion> oneOnly =
        VersionManager::latestVersions(onlySnapshot);
    check(oneOnly.size() == 1 && oneOnly.at(0).channel == VersionCategory::Channel::Snapshot &&
              oneOnly.at(0).version.id == QStringLiteral("26.3-rc-3"),
          "Y2b 只有快照没有正式版时，就只给那一条（不拿别的类补位）",
          QString::number(oneOnly.size()));

    // 愚人节版在清单里也是 type == snapshot：按 type 判会让它当上"最新快照"。
    QList<MinecraftVersion> withAprilFools;
    withAprilFools.append(MinecraftVersion{QStringLiteral("26w14a"), QStringLiteral("snapshot"),
                                           QString(), QString(),
                                           QStringLiteral("2026-04-01T12:00:00+00:00")});
    withAprilFools.append(MinecraftVersion{QStringLiteral("26.3"), QStringLiteral("release"),
                                           QString(), QString(),
                                           QStringLiteral("2026-09-15T11:23:02+00:00")});
    withAprilFools.append(MinecraftVersion{QStringLiteral("26.2-snapshot-1"),
                                           QStringLiteral("snapshot"), QString(), QString(),
                                           QStringLiteral("2026-08-25T12:53:43+00:00")});
    const QList<VersionManager::LatestVersion> noApril =
        VersionManager::latestVersions(withAprilFools);
    check(noApril.size() == 2 &&
              noApril.at(1).version.id == QStringLiteral("26.2-snapshot-1"),
          "Y2b 最新的快照**跳过**愚人节版（26w14a 也是 type=snapshot，但它进的是愚人节那一栏）",
          QStringLiteral("%1 条，快照那条是 %2")
              .arg(noApril.size())
              .arg(noApril.size() > 1 ? noApril.at(1).version.id : QStringLiteral("<无>")));

    // 那一组的身份：**非空、且和四个分类键两两不同**（同一个角色里住着树上五个顶层身份，
    // 撞了之后"哪一条是展开的"那笔账会串到另一条上）。
    const QString latestKey = VersionManager::latestGroupKey();
    check(!latestKey.isEmpty() && !VersionCategory::channelKeys().contains(latestKey),
          "Y2b 「最新版本」那一组的身份非空、且和四个分类键都不撞",
          latestKey);
    check(!VersionManager::latestGroupText().isEmpty(),
          "Y2b 那一组给用户看的名字非空", VersionManager::latestGroupText());

    // --- Y3. 愚人节版那张名单 ---------------------------------------------
    const QStringList aprilIds = VersionCategory::aprilFoolsVersionIds();
    check(aprilIds.size() == 9, "Y3 名单 9 条", QString::number(aprilIds.size()));

    // 名单里的每一条都得在**这份**清单里 —— 打错一个字符的那条会立刻掉出来。
    QStringList missingInManifest;
    for (const QString &id : aprilIds) {
        if (!manifestIds.contains(id, Qt::CaseInsensitive)) {
            missingInManifest.append(id);
        }
    }
    check(missingInManifest.isEmpty(),
          "Y3 名单里每一条都能在这份真清单里找到（打错一个字符就会掉出来）",
          missingInManifest.join(QStringLiteral("、")));

    // 反过来：那 9 条**全**在愚人节版那一堆里（没有谁被留在快照版里）
    QStringList aprilInBucket;
    for (const MinecraftVersion &version : channels.at(3).versions) {
        aprilInBucket.append(version.id);
    }
    check(aprilInBucket.contains(QStringLiteral("3D Shareware v1.34"), Qt::CaseInsensitive),
          "Y3 有大写和空格的 3D Shareware v1.34 也认出来了（比的时候不能区分大小写）",
          aprilInBucket.join(QStringLiteral("、")));
    check(aprilInBucket.contains(QStringLiteral("1.RV-Pre1")),
          "Y3 1.RV-Pre1（3/31 发布，日期规则会漏掉它）也在里面");
    int aprilLeftInSnapshot = 0;
    for (const MinecraftVersion &version : channels.at(1).versions) {
        if (VersionCategory::isAprilFoolsVersion(version.id)) {
            ++aprilLeftInSnapshot;
        }
    }
    check(aprilLeftInSnapshot == 0, "Y3 愚人节那几条没有谁还被留在快照版里",
          QString::number(aprilLeftInSnapshot));

    // 名单里每一条的发布日期都得落在 3/31~4/1 这个窗口 —— 这条是**名单打错的兜底判据**：
    // 打错的那条会立刻掉出日期窗口。上一条（"在不在清单里"）单独是抓不全的。
    QStringList oddDates;
    for (const MinecraftVersion &version : channels.at(3).versions) {
        const QString date = version.releaseTime.mid(5, 5);
        if (date != QLatin1String("03-31") && date != QLatin1String("04-01")) {
            oddDates.append(version.id + QStringLiteral(" @") + version.releaseTime.left(10));
        }
    }
    check(oddDates.isEmpty(), "Y3 愚人节版那 9 条的发布日期都在 3/31~4/1 这个窗口里",
          oddDates.join(QStringLiteral("、")));

    // 日期那条规则为什么被否掉：落在 3/31~4/1 的**不止**愚人节版
    QStringList onDateButNotApril;
    for (const MinecraftVersion &version : manifest) {
        const QString date = version.releaseTime.mid(5, 5);
        if ((date == QLatin1String("03-31") || date == QLatin1String("04-01")) &&
            !VersionCategory::isAprilFoolsVersion(version.id)) {
            onDateButNotApril.append(version.id);
        }
    }
    check(onDateButNotApril.contains(QStringLiteral("26.1.1")),
          "Y3 4/1 发布的**正式版** 26.1.1 不是愚人节版（日期当判据就会把它塞进那一栏）",
          onDateButNotApril.join(QStringLiteral("、")));
    check(onDateButNotApril.size() == 5,
          "Y3 落在那个日期窗口里的正经版本一共 5 条（这就是日期规则被否掉的原因）",
          QStringLiteral("%1: %2")
              .arg(onDateButNotApril.size())
              .arg(onDateButNotApril.join(QStringLiteral("、"))));

    // --- Y4. 几张表本身 ---------------------------------------------------
    check(VersionCategory::channelKeys() == expectedKeys, "Y4 四个键");
    check(VersionCategory::channelTexts() == expectedTexts, "Y4 四段文字");
    // 键和文字**一一对应**：两张表按同一个顺序，且 channelAt/channelIndex 互为反函数
    bool consistent = true;
    for (int i = 0; i < VersionCategory::channelCount(); ++i) {
        const VersionCategory::Channel channel = VersionCategory::channelAt(i);
        if (VersionCategory::channelIndex(channel) != i || channels.at(i).channel != channel) {
            consistent = false;
        }
    }
    check(consistent, "Y4 channelAt 和 channelIndex 互为反函数、且和界面那条顺序是同一个顺序");
    // 越界不许崩，也不许给一个 -1 那种（界面下标和堆数将来对不上时）
    check(VersionCategory::channelAt(-1) == VersionCategory::Channel::Release &&
              VersionCategory::channelAt(99) == VersionCategory::Channel::Release,
          "Y4 channelAt 越界时回一个确定的分类（不是 -1 / 不崩）");
    check(VersionCategory::isAprilFoolsVersion(QStringLiteral("3d shareware v1.34")) &&
              VersionCategory::isAprilFoolsVersion(QStringLiteral("3D SHAREWARE V1.34")),
          "Y4 认愚人节版时大小写不敏感");
    check(!VersionCategory::isAprilFoolsVersion(QStringLiteral("26.1.1")), "Y4 26.1.1 不是愚人节版");
    check(VersionCategory::channelFor(QString(), QStringLiteral("release")) ==
              VersionCategory::Channel::Release,
          "Y4 id 空着时按 type 走（不给空 id 瞎认）");
    // 没见过的 type：落到快照版（宁可多列一条，也不让它从四个分类里凭空消失）
    check(VersionCategory::channelFor(QStringLiteral("99w99a"), QStringLiteral("whatever")) ==
              VersionCategory::Channel::Snapshot,
          "Y4 没见过的 type 落到快照版（一条都不许从四分类里漏掉）");

    // ---------------------------------------------------------------------
    section("Y5. 四个加载器的「能挑哪些版本」（真 maven 清单 / 真页面）");
    // ---------------------------------------------------------------------
    //
    // 这一段回答的是「安装页上点开一个加载器，列表里该有些什么」。四份数据源都是真的：
    //   meta/forge-maven-metadata.xml     211487 B / 5048 条
    //   meta/neoforge-maven-metadata.xml  63597 B
    //   meta/optifine-downloads.html      200723 B（官方下载页）
    //   meta/optifine-1.18.2-list.json    11 条（镜像那份 JSON）

    // --- Y6. Forge：新开的那个 maven 源 -----------------------------------
    {
        QFile fixture(metaDir + "/forge-maven-metadata.xml");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "Y6 读到了真 Forge maven 清单（meta/forge-maven-metadata.xml）");
        if (haveFixture) {
            const QByteArray xml = fixture.readAll();
            fixture.close();
            check(xml.size() > 200000, "Y6 那一份是 200 KB 以上（5048 条那个全集）",
                  QString::number(xml.size()));

            const QStringList v1201 = LoaderMeta::loaderVersionStrings(
                LoaderMeta::listForgeVersions(xml, QStringLiteral("1.20.1")));
            check(v1201.size() == 132, "Y6 Forge 1.20.1 下有 132 个版本",
                  QString::number(v1201.size()));
            check(v1201.value(0) == QStringLiteral("47.4.23"),
                  "Y6 最新的那个排第一（1.20.1 是 47.4.23）", v1201.value(0));
            check(v1201.contains(QStringLiteral("47.4.10")),
                  "Y6 官方在用的那个 47.4.10 也在列表里",
                  QStringLiteral("列表 %1 条").arg(v1201.size()));

            // 新到旧（清单自己是按发布时间排的，不能直接拿来当"版本大小"的顺序）
            bool descending = true;
            for (int i = 1; i < v1201.size(); ++i) {
                if (LoaderMeta::compareDottedVersions(
                        LoaderMeta::parseDottedVersion(v1201.at(i - 1)),
                        LoaderMeta::parseDottedVersion(v1201.at(i))) < 0) {
                    descending = false;
                }
            }
            check(descending, "Y6 整份列表严格从新到旧");

            // 老版本那种 <游戏>-<加载器>-<游戏> 坐标要归一
            const QStringList v189 = LoaderMeta::loaderVersionStrings(
                LoaderMeta::listForgeVersions(xml, QStringLiteral("1.8.9")));
            check(v189.contains(QStringLiteral("11.15.1.2318")) &&
                      v189.contains(QStringLiteral("11.15.1.1722")),
                  "Y6 1.8.9 那两种坐标都归一成版本号了",
                  v189.mid(0, 3).join(QStringLiteral(", ")));
            bool tailsGone = true;
            for (const QString &version : v189) {
                if (version.contains(QLatin1Char('-'))) {
                    tailsGone = false;
                }
            }
            check(tailsGone, "Y6 归一之后没有剩下带尾巴的");

            // 1.10 那条：坐标尾巴是 1.10.0，按**字符串**前缀剥不掉，得逐段比
            const QStringList v110 = LoaderMeta::loaderVersionStrings(
                LoaderMeta::listForgeVersions(xml, QStringLiteral("1.10")));
            check(v110.contains(QStringLiteral("12.18.0.2000")),
                  "Y6 1.10 的尾巴 1.10.0 也剥掉了（逐段比前缀，不是比字符串）",
                  v110.mid(0, 3).join(QStringLiteral(", ")));

            // 带字母后缀的那些（10.13.3.1401-1710ls）不收 —— 它们"谁更新"没有定义
            const QStringList v1710 = LoaderMeta::loaderVersionStrings(
                LoaderMeta::listForgeVersions(xml, QStringLiteral("1.7.10")));
            bool onlyDotted = true;
            for (const QString &version : v1710) {
                if (LoaderMeta::parseDottedVersion(version).isEmpty()) {
                    onlyDotted = false;
                }
            }
            check(onlyDotted && !v1710.isEmpty(),
                  "Y6 1.7.10 那 13 个带字母后缀的不收进来（但正经的那些还在）",
                  QStringLiteral("%1 条").arg(v1710.size()));

            // 不串味：清单里没有的游戏版本回空，而不是把前缀够得着的那些串进来
            check(LoaderMeta::listForgeVersions(xml, QStringLiteral("1.7")).isEmpty(),
                  "Y6 清单里没有 1.7（只有 1.7.10）时回空，不会把 1.7.10 的串进来");
            check(LoaderMeta::listForgeVersions(xml, QStringLiteral("1.2")).isEmpty(),
                  "Y6 1.2 也不会把 1.20.x 的串进来");
            check(LoaderMeta::listForgeVersions(xml, QString()).isEmpty(),
                  "Y6 空游戏版本号回空（不拿它去前缀匹配整份清单）");

            // 归一那一手单独钉一遍（两头的形状 + 差一个字都不行）
            check(LoaderMeta::forgeLoaderVersionFromCoordinate(QStringLiteral("1.20.1-47.4.10"),
                                                              QStringLiteral("1.20.1")) ==
                      QStringLiteral("47.4.10"),
                  "Y6 常规坐标 1.20.1-47.4.10 → 47.4.10");
            check(LoaderMeta::forgeLoaderVersionFromCoordinate(
                      QStringLiteral("1.8.9-11.15.1.2318-1.8.9"), QStringLiteral("1.8.9")) ==
                      QStringLiteral("11.15.1.2318"),
                  "Y6 老坐标 1.8.9-11.15.1.2318-1.8.9 → 11.15.1.2318");
            check(LoaderMeta::forgeLoaderVersionFromCoordinate(QStringLiteral("1.20.1-47.4.10"),
                                                              QStringLiteral("1.20"))
                      .isEmpty(),
                  "Y6 游戏版本 1.20 不会把 1.20.1 的坐标当成自己的（差一个字都不行）");
        }
    }

    // --- Y6b. 频道键：那两块牌子与"真版本号"互不相认 ----------------------
    //
    // 界面上那两档（下载最新版 / 下载稳定版）是拿 `@latest` / `@stable` 两个键表达的；
    // 用户点某一条具体版本号时走的是同一根管子的另一支。这两种取值必须互相排斥，
    // 否则"钉了 1.20.1-47.4.10 结果按最新档挑"这种事就会静悄悄地发生。
    {
        check(LoaderMeta::loaderChannelKey(LoaderMeta::LoaderChannel::Stable) ==
                  QStringLiteral("@stable") &&
                  LoaderMeta::loaderChannelKey(LoaderMeta::LoaderChannel::Newest) ==
                      QStringLiteral("@latest"),
              "Y6b 两个键就是 @stable / @latest");
        LoaderMeta::LoaderChannel channel = LoaderMeta::LoaderChannel::Stable;
        check(LoaderMeta::loaderChannelFromKey(QStringLiteral("@latest"), &channel) &&
                  channel == LoaderMeta::LoaderChannel::Newest,
              "Y6b @latest 解成最新档");
        channel = LoaderMeta::LoaderChannel::Newest;
        check(LoaderMeta::loaderChannelFromKey(QStringLiteral("@stable"), &channel) &&
                  channel == LoaderMeta::LoaderChannel::Stable,
              "Y6b @stable 解成稳定档（上一次解出来的结果不会留在里头）");
        check(!LoaderMeta::loaderChannelFromKey(QStringLiteral("1.20.1-47.4.10"), &channel) &&
                  !LoaderMeta::loaderChannelFromKey(QString(), &channel) &&
                  !LoaderMeta::loaderChannelFromKey(QStringLiteral("@Latest"), &channel),
              "Y6b 真版本号 / 空串 / 大小写不一样的键 -> 都不是频道键");
        // ★ 这条是上面所有断言的地基：`@` 不在版本号那个白名单里（`[A-Za-z0-9._+-]`），
        //   所以真版本号永远长不成 `@latest` 那个样子，两个键也永远过不了真版本号那关。
        check(!LoaderMeta::isSafeVersionId(QStringLiteral("@latest")) &&
                  !LoaderMeta::isSafeVersionId(QStringLiteral("@stable")) &&
                  LoaderMeta::isSafeVersionId(QStringLiteral("1.20.1-47.4.10")),
              "★ Y6b `@` 不在版本号白名单里 —— 两个键和真版本号不可能撞车");

        const LoaderMeta::LoaderRequest byChannel =
            LoaderMeta::loaderRequestFromChoice(QStringLiteral("@latest"));
        check(!byChannel.pinned() && byChannel.channel == LoaderMeta::LoaderChannel::Newest,
              "Y6b @latest -> 没钉版本、按最新档挑");
        const LoaderMeta::LoaderRequest byDefault = LoaderMeta::loaderRequestFromChoice(QString());
        check(!byDefault.pinned() && byDefault.channel == LoaderMeta::LoaderChannel::Stable,
              "Y6b 空串 -> 按稳定档挑（这就是改动前「按老规矩挑」那条路）");
        const LoaderMeta::LoaderRequest pinned =
            LoaderMeta::loaderRequestFromChoice(QStringLiteral("1.20.1-47.4.10"));
        check(pinned.pinned() && pinned.pinnedVersion == QStringLiteral("1.20.1-47.4.10") &&
                  pinned.channel == LoaderMeta::LoaderChannel::Stable,
              "Y6b 真版本号 -> 钉死它（频道那个字段就不起作用了）");
    }

    // --- Y7. NeoForge -----------------------------------------------------
    //
    // 改动前这一段断言的是「列表里没有 -beta」。而用户 2026-09-23 报的那一版（26.3）
    // 上游**只发过 -beta**，于是列表被清空、只能显示「无可用版本」；他那台机器上跑的
    // exe 更旧，看到的是「列表没取到」。现在 beta 一律列出来、在第二行标「测试版」，
    // 「稳定档」挑不出来时那条自己灰掉写「没有正式版」——所以这一段整个反过来了。
    {
        QFile fixture(metaDir + "/neoforge-maven-metadata.xml");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "Y7 读到了真 NeoForge maven 清单");
        if (haveFixture) {
            const QByteArray xml = fixture.readAll();
            fixture.close();

            const QString games[4] = {QStringLiteral("1.21.1"), QStringLiteral("26.2"),
                                      QStringLiteral("1.20.2"), QStringLiteral("1.21.10")};
            bool allNonEmpty = true;
            bool flagsOk = true;              // 每条的 stable 就是「版本号里没有 - 或 +」
            bool stableIsFirstStable = true;  // 稳定档挑的 == 列表里第一条正式版
            bool newestIsFirst = true;        // 最新档挑的 == 列表第一条
            for (const QString &game : games) {
                const LoaderMeta::LoaderVersionList list =
                    LoaderMeta::listNeoForgeVersions(xml, game);
                if (list.isEmpty()) {
                    allNonEmpty = false;
                    continue;
                }
                QString firstStable;
                for (const LoaderMeta::LoaderVersionEntry &entry : list) {
                    const bool expected = !entry.version.contains(QLatin1Char('-')) &&
                                          !entry.version.contains(QLatin1Char('+'));
                    if (entry.stable != expected) {
                        flagsOk = false;
                    }
                    if (firstStable.isEmpty() && entry.stable) {
                        firstStable = entry.version;
                    }
                }
                // 两档挑法必须和列表走同一份解析 —— 不能列表一套、挑版本又一套
                if (LoaderMeta::pickNeoForgeVersion(xml, game).version != firstStable) {
                    stableIsFirstStable = false;
                }
                if (LoaderMeta::pickNeoForgeVersion(xml, game, LoaderMeta::LoaderChannel::Newest)
                        .version != list.first().version) {
                    newestIsFirst = false;
                }
            }
            check(allNonEmpty, "Y7 那四个游戏版本都列得出东西");
            check(flagsOk, "Y7 每条的 stable 就是「版本号里没有 - 或 +」（界面靠它标「测试版」）");
            check(stableIsFirstStable,
                  "Y7 稳定档挑出来的 == 列表里第一条正式版（和列表同一处解析，不是两套）");
            check(newestIsFirst, "Y7 最新档挑出来的 == 列表第一条（beta 也在里头挑）");

            // ★ 用户报的那一版的原样数据：26.3 只发过 -beta，9 条。
            const LoaderMeta::LoaderVersionList nf263 =
                LoaderMeta::listNeoForgeVersions(xml, QStringLiteral("26.3"));
            check(nf263.size() == 9, "★ Y7 26.3 那 9 条 -beta 全列出来了（改动前一条都不列）",
                  QStringLiteral("%1 条").arg(nf263.size()));
            int stable263 = 0;
            for (const LoaderMeta::LoaderVersionEntry &entry : nf263) {
                stable263 += entry.stable ? 1 : 0;
            }
            // 注意 `nf263.size() == 9` 这一半不能省：不带它的话，"列表被清空"那个老 bug
            // 也能让这条断言变绿（空列表里当然没有正式版）。
            check(nf263.size() == 9 && stable263 == 0 &&
                      LoaderMeta::pickNeoForgeVersion(xml, QStringLiteral("26.3")).version.isEmpty(),
                  "★ Y7 26.3 列出来的 9 条一条正式版都没有 -> 稳定档挑不出来（那条灰掉写「没有正式版」）",
                  QStringLiteral("%1 条 / 正式 %2 条").arg(nf263.size()).arg(stable263));
            check(LoaderMeta::pickNeoForgeVersion(xml, QStringLiteral("26.3"),
                                                  LoaderMeta::LoaderChannel::Newest)
                      .version == QStringLiteral("26.3.0.8-beta"),
                  "★ Y7 26.3 最新档挑得出 26.3.0.8-beta —— 点「下载最新版」装的就是它");

            // ★ beta 不是都挂在尾巴上：1.21.10 里第 3 条就是 beta，前两条是正式版。
            // 所以挑正式版必须逐条看 stable，不能靠"从头往下取第一条"或者比名字长短。
            const LoaderMeta::LoaderVersionList v2110 =
                LoaderMeta::listNeoForgeVersions(xml, QStringLiteral("1.21.10"));
            check(v2110.size() == 63 && v2110.value(0).stable && !v2110.value(2).stable &&
                      v2110.value(2).version == QStringLiteral("21.10.62-beta"),
                  "★ Y7 1.21.10 第 3 条是 21.10.62-beta（beta 混在正式版中间）",
                  QStringLiteral("%1 条，第 3 条 %2")
                      .arg(v2110.size())
                      .arg(v2110.value(2).version));

            // 21.1.x 和 21.10.x 不能串（逐段比前缀那条）
            const QStringList v211 = LoaderMeta::loaderVersionStrings(
                LoaderMeta::listNeoForgeVersions(xml, QStringLiteral("1.21.1")));
            bool noCross = true;
            for (const QString &version : v211) {
                if (version.startsWith(QLatin1String("21.10"))) {
                    noCross = false;
                }
            }
            check(noCross, "Y7 1.21.1 的列表里没有 21.10.x（逐段比前缀，不是比字符串）",
                  QStringLiteral("%1 条").arg(v211.size()));
        }
    }

    // --- Y8. OptiFine：两条路各列各的，但正式版那一段必须一致 -----------------
    //
    // 改动前这里断言的是「两条路**逐条**一致」。那在"只列正式版"的年代成立（两路都
    // 只剩 H9/H7/H6），现在预览版也列出来了，而两条路**预览版的覆盖范围本来就不同**：
    // 官方页按小节走（1.18.2 只有 3 条正式版），镜像是全量（3 条正式版 + 8 条预览版）。
    // 所以改成钉"正式版子序列一致"，逐条一致那条断言撤销。
    {
        QFile listFixture(metaDir + "/optifine-1.18.2-list.json");
        QFile pageFixture(metaDir + "/optifine-downloads.html");
        const bool haveList = listFixture.open(QIODevice::ReadOnly);
        const bool havePage = pageFixture.open(QIODevice::ReadOnly);
        check(haveList && havePage, "Y8 读到了 OptiFine 那两份真夹具（镜像 JSON + 官方页）");
        if (haveList && havePage) {
            const QJsonArray mirror = QJsonDocument::fromJson(listFixture.readAll()).array();
            const QString html = QString::fromUtf8(pageFixture.readAll());
            listFixture.close();
            pageFixture.close();

            const LoaderMeta::LoaderVersionList pageList =
                LoaderMeta::listOptifineVersionsFromDownloadsPage(html, QStringLiteral("1.18.2"));
            const LoaderMeta::LoaderVersionList mirrorVersionList =
                LoaderMeta::listOptifineVersionsFromMirror(mirror, QStringLiteral("1.18.2"));
            const QStringList fromPage = LoaderMeta::loaderVersionStrings(pageList);
            const QStringList fromMirror = LoaderMeta::loaderVersionStrings(mirrorVersionList);
            const QStringList expected{QStringLiteral("HD_U_H9"), QStringLiteral("HD_U_H7"),
                                       QStringLiteral("HD_U_H6")};
            check(fromPage == expected, "Y8 官方页 1.18.2 列出来是 H9/H7/H6（那一小节就这 3 条）",
                  fromPage.join(QStringLiteral(", ")));

            // 镜像是全量：3 条正式版 + 8 条预览版，而且**混着排**（H9 后面紧跟 H9_pre3），
            // 所以老的"两条路逐条一致"在这份真数据上已经不成立了 —— 那正是这次要改的。
            int mirrorStable = 0;
            QStringList mirrorStableList;
            for (const LoaderMeta::LoaderVersionEntry &entry : mirrorVersionList) {
                if (entry.stable) {
                    ++mirrorStable;
                    mirrorStableList << entry.version;
                }
            }
            check(mirror.size() == 11 && fromMirror.size() == 11 && mirrorStable == 3,
                  "Y8 镜像 1.18.2 是 11 条（3 条正式版 + 8 条预览版）",
                  QStringLiteral("原始 %1 / 列表 %2 / 正式版 %3")
                      .arg(mirror.size())
                      .arg(fromMirror.size())
                      .arg(mirrorStable));
            check(fromMirror.size() != fromPage.size(),
                  "★ Y8 两条路**不再逐条一致**（镜像多了老版本的预览版）",
                  QStringLiteral("页 %1 条 / 镜像 %2 条")
                      .arg(fromPage.size())
                      .arg(fromMirror.size()));
            // 一致的是**正式版子序列**：换个下载源不该连正式版都翻个面。
            check(mirrorStableList == expected,
                  "★ Y8 两条路的正式版子序列一致（页 H9/H7/H6 == 镜像里挑出 stable 的那 3 条）",
                  mirrorStableList.join(QStringLiteral(", ")));

            // 挑法（默认档 = 稳定档）：两条路都落在 H9 上，而且 H9 就是列表里第一条正式版。
            check(LoaderMeta::pickOptifineFromDownloadsPage(html, QStringLiteral("1.18.2")).fileName ==
                      QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar"),
                  "Y8 官方页稳定档挑出来是 H9 那个 jar");
            check(LoaderMeta::pickOptifineFromMirror(mirror, QStringLiteral("1.18.2")).fileName ==
                      QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar"),
                  "Y8 镜像稳定档挑出来是 H9 那个 jar");

            // ★ 列表里第一条**正式版**必须就是稳定档挑出来的那个 —— 列出来的和装下去
            // 的是同一个，用户照着列表点不会装到别的东西上。
            QString firstStable;
            for (const LoaderMeta::LoaderVersionEntry &entry : mirrorVersionList) {
                if (entry.stable) {
                    firstStable = entry.version;
                    break;
                }
            }
            check(!firstStable.isEmpty() &&
                      firstStable == LoaderMeta::optifineEditionFromFile(
                                         QStringLiteral("1.18.2"),
                                         LoaderMeta::pickOptifineFromMirror(
                                             mirror, QStringLiteral("1.18.2")).fileName),
                  "★ Y8 镜像里第一条正式版 == 稳定档实际挑的那条", firstStable);

            // 版本号 ↔ 文件名（「钉死一个 OptiFine 版本」那条路就是靠它落地的）
            check(LoaderMeta::optifineInstallerFileName(QStringLiteral("1.18.2"),
                                                       QStringLiteral("HD_U_H9")) ==
                      QStringLiteral("OptiFine_1.18.2_HD_U_H9.jar"),
                  "Y8 版本号 → 文件名（正式版）");
            check(LoaderMeta::optifineInstallerFileName(QStringLiteral("1.18.2"),
                                                       QStringLiteral("HD_U_H9_pre2")) ==
                      QStringLiteral("preview_OptiFine_1.18.2_HD_U_H9_pre2.jar"),
                  "Y8 版本号 → 文件名（预览版要补 preview_ 前缀）");

            // 对着那 11 条真数据**逐条**核两个往返：版本号↔文件名、版本号↔镜像路径两段
            int checkedRows = 0;
            int badRows = 0;
            for (const QJsonValue &value : mirror) {
                const QJsonObject entry = value.toObject();
                const QString fileName = entry.value(QStringLiteral("filename")).toString();
                const QString edition =
                    LoaderMeta::optifineEditionFromFile(QStringLiteral("1.18.2"), fileName);
                ++checkedRows;
                if (LoaderMeta::optifineInstallerFileName(QStringLiteral("1.18.2"), edition) !=
                    fileName) {
                    ++badRows;
                }
                const LoaderMeta::OptiFineMirrorPath path =
                    LoaderMeta::optifineMirrorPathFromEdition(edition);
                if (path.type != entry.value(QStringLiteral("type")).toString() ||
                    path.patch != entry.value(QStringLiteral("patch")).toString()) {
                    ++badRows;
                }
            }
            check(checkedRows == 11 && badRows == 0,
                  "Y8 那 11 条真数据上：版本号↔文件名、版本号↔镜像路径段 两个往返都对",
                  QStringLiteral("核了 %1 条、错 %2 条").arg(checkedRows).arg(badRows));
            // 切点是**最后一个**下划线 —— 这正是上面那 11 条往返全对的理由：
            // 正式版 HD_U_H9 -> HD_U/H9（和镜像自己的 type/patch 一致）
            // 预览版 HD_U_H9_pre2 -> HD_U_H9/pre2（也一致，不是 HD_U/H9）
            // 要是在第一个下划线处切，预览版那 6 条会全错，而正式版那 3 条照样对。
            const LoaderMeta::OptiFineMirrorPath releasePath =
                LoaderMeta::optifineMirrorPathFromEdition(QStringLiteral("HD_U_H9"));
            check(releasePath.type == QStringLiteral("HD_U") &&
                      releasePath.patch == QStringLiteral("H9"),
                  "Y8 切点在最后一个下划线（正式版 HD_U_H9 → HD_U / H9）",
                  QStringLiteral("%1 / %2").arg(releasePath.type, releasePath.patch));
            const LoaderMeta::OptiFineMirrorPath previewPath =
                LoaderMeta::optifineMirrorPathFromEdition(QStringLiteral("HD_U_H9_pre2"));
            check(previewPath.type == QStringLiteral("HD_U_H9") &&
                      previewPath.patch == QStringLiteral("pre2"),
                  "Y8 预览版切出来也是镜像那两个字段（HD_U_H9_pre2 → HD_U_H9 / pre2）",
                  QStringLiteral("%1 / %2").arg(previewPath.type, previewPath.patch));
            // 一个下划线都没有的版本号切不出来，如实回 ok()=false —— 调用方靠它报"认不出
            // 下载地址"，而不是拼一个一定 404 的路径出去（见 adoptOptifineEdition 里那个守卫）。
            check(!LoaderMeta::optifineMirrorPathFromEdition(QStringLiteral("H9")).ok(),
                  "Y8 一个下划线都没有的版本号（H9）回 ok()=false");
            check(!LoaderMeta::optifineMirrorPathFromEdition(QString()).ok(),
                  "Y8 空版本号回 ok()=false");
            check(!LoaderMeta::optifineMirrorPathFromEdition(QStringLiteral("HD_")).ok(),
                  "Y8 尾巴是空的（HD_）也回 ok()=false，不给出半个路径");
        }
    }

    // --- Y9. Fabric：列表和挑法走同一份解析 --------------------------------
    {
        // 夹具里那份是 profile（薄 json），不是「版本列表」那个接口的回复，
        // 所以这里按接口的形状造一份最小的：{loader:{version,stable}}。
        const QJsonArray list =
            QJsonDocument::fromJson(R"([
                {"loader":{"version":"0.19.5","stable":true}},
                {"loader":{"version":"0.19.4","stable":false}},
                {"loader":{"version":"0.19.3","stable":false}},
                {"loader":{"version":"","stable":false}}
            ])")
                .array();
        const LoaderMeta::LoaderVersionList entries = LoaderMeta::listFabricLoaderVersions(list);
        check(LoaderMeta::loaderVersionStrings(entries) ==
                  (QStringList{QStringLiteral("0.19.5"), QStringLiteral("0.19.4"),
                               QStringLiteral("0.19.3")}),
              "Y9 Fabric：空版本号那条被跳过、顺序原样（接口本来就是新到旧）",
              LoaderMeta::loaderVersionStrings(entries).join(QStringLiteral(", ")));
        check(entries.value(0).stable && !entries.value(1).stable,
              "Y9 Fabric：stable 只标在接口自己标了的那条上");
        check(LoaderMeta::pickFabricLoader(list).version == QStringLiteral("0.19.5"),
              "Y9 Fabric：挑法和列表走同一份解析，挑出来的还是 0.19.5");
        check(LoaderMeta::pickFabricLoader(QJsonArray()).ok() == false,
              "Y9 Fabric：空列表回 ok()=false（不是回一个空版本的 ok()=true）");
    }

    // ---------------------------------------------------------------------
    section("Y10. 版本号下面那行小字：发布日期（精确到日）");
    // ---------------------------------------------------------------------
    // 用户原话：「在版本号下面小字写发布时间（精确到日）」。那一行现在是
    // releaseDateText() 从 releaseTime 里切出来的 —— 走的必须是真清单那 915 条
    //（每一条都是 `2026-09-15T11:23:02+00:00` 这种 25 个字符的 ISO8601），
    // 不是自己编两个好看的字符串。
    {
        int cut = 0;
        int tenChars = 0;
        QSet<QString> dates;
        for (const MinecraftVersion &version : manifest) {
            const QString text = releaseDateText(version.releaseTime);
            if (!text.isEmpty()) {
                ++cut;
                dates.insert(text);
            }
            // **精确到日**：切出来就是那 10 个字符，不是 `2026-09-15T11:23:02+00:00`
            // 这种一长串，也不是 `2026/09/15` 那种换个写法。
            if (text.size() == 10 && text == version.releaseTime.left(10)) {
                ++tenChars;
            }
        }
        check(cut == manifest.size() && tenChars == manifest.size(),
              "Y10 915 条真清单的 releaseTime 全都切成了 yyyy-MM-dd（一个空的都没有）",
              QStringLiteral("%1/%2 条有日期，%3 条正好是前 10 个字符")
                  .arg(cut)
                  .arg(manifest.size())
                  .arg(tenChars));
        check(dates.size() > 100,
              "Y10 那 915 条切出来的日期有 100 多种（真值，不是写死的）",
              QString::number(dates.size()));
    }
    // 时区**不换算**：清单是 UTC，本机多半在 UTC+8 —— 23:30 那条要是被换算一遍
    // 就成了第二天，而它和 00:30 那条就再也分不出来了。这两条钉住这个方向。
    check(releaseDateText(QStringLiteral("2026-09-15T23:30:00+00:00")) ==
              QStringLiteral("2026-09-15"),
          "Y10 UTC 当天最后一刻那条还是当天（不许被本机时区推到第二天）",
          releaseDateText(QStringLiteral("2026-09-15T23:30:00+00:00")));
    check(releaseDateText(QStringLiteral("2026-09-15T00:30:00+00:00")) ==
              QStringLiteral("2026-09-15"),
          "Y10 UTC 当天刚开始那条也还是当天（不许被推到前一天）",
          releaseDateText(QStringLiteral("2026-09-15T00:30:00+00:00")));
    check(releaseDateText(QStringLiteral("2026-09-15T11:23:02Z")) == QStringLiteral("2026-09-15"),
          "Y10 `Z` 那种写法也认（清单换写法不至于整列空掉）",
          releaseDateText(QStringLiteral("2026-09-15T11:23:02Z")));
    check(releaseDateText(QStringLiteral("  2026-09-15T11:23:02+00:00  ")) ==
              QStringLiteral("2026-09-15"),
          "Y10 两头有空白也照样切（值从别的地方来的时候带空白是常事）");
    // 兜底那条：认不出来的时候，前 10 个字符长得像日期就认它。
    check(releaseDateText(QStringLiteral("2026-09-15 11:23:02")) == QStringLiteral("2026-09-15"),
          "Y10 不带 T 的写法（`2026-09-15 11:23:02`）也切出那 10 个字符",
          releaseDateText(QStringLiteral("2026-09-15 11:23:02")));
    check(releaseDateText(QStringLiteral("2026-09-15")) == QStringLiteral("2026-09-15"),
          "Y10 只给到日的那半截原样用");
    // 认不出来就回空串 —— 调用方（代理）见空串就**不画那一行**，所以这里不能瞎猜一个日期。
    check(releaseDateText(QString()).isEmpty() && releaseDateText(QStringLiteral("   ")).isEmpty(),
          "Y10 空值 / 只有空白回空串（那一行就不画，而不是画个 0000-00-00）");
    check(releaseDateText(QStringLiteral("not-a-date")).isEmpty() &&
              releaseDateText(QStringLiteral("2026-13-45")).isEmpty() &&
              releaseDateText(QStringLiteral("2026-09-1")).isEmpty(),
          "Y10 认不出来的、月份日期越界的、只给到 9 号那种都回空串（不瞎猜）",
          releaseDateText(QStringLiteral("2026-13-45")));
}

static void runModpackImportTests(const QString &sandbox) {
    section("V. 整合包导入：清单解析 / 路径判据 / 按前缀解压");

    // --- V1. 清单文件叫什么、认哪些加载器 -------------------------------------
    check(ModpackImport::modrinthIndexName() == QStringLiteral("modrinth.index.json"),
          "V1 Modrinth 的清单文件名叫 modrinth.index.json",
          ModpackImport::modrinthIndexName());
    check(ModpackImport::curseForgeManifestName() == QStringLiteral("manifest.json"),
          "V1 CurseForge 的清单文件名叫 manifest.json",
          ModpackImport::curseForgeManifestName());
    // 顺序**钉住**：靠遍历 QJsonObject 的键去挑"包里要哪个加载器"是拿实现细节当规则用，
    // 换一次 Qt 就可能挑到另一个。四条的顺序 = 认的顺序。
    const QStringList keys = ModpackImport::loaderDependencyKeys();
    check(keys.size() == 4 && keys.at(0) == QStringLiteral("fabric-loader") &&
              keys.at(1) == QStringLiteral("forge") && keys.at(2) == QStringLiteral("neoforge") &&
              keys.at(3) == QStringLiteral("quilt-loader"),
          "V1 认的加载器键是固定的四条，顺序也固定", keys.join(QLatin1Char(',')));
    check(ModpackImport::unsupportedLoaderText(QString(), QString()).isEmpty() &&
              ModpackImport::unsupportedLoaderText(QStringLiteral("fabric-loader"),
                                                   QStringLiteral("0.16.14"))
                  .isEmpty() &&
              ModpackImport::unsupportedLoaderText(QStringLiteral("forge"),
                                                   QStringLiteral("47.4.10"))
                  .isEmpty(),
          "V1 纯原版 / Fabric / Forge 都算能用，没有一句拦人的话");
    const QString quiltText = ModpackImport::unsupportedLoaderText(
        QStringLiteral("quilt-loader"), QStringLiteral("0.20.0"));
    check(quiltText.contains(QStringLiteral("Quilt")) &&
              quiltText.contains(QStringLiteral("没有")) &&
              quiltText.contains(QStringLiteral("0.20.0")),
          "V1 Quilt 拦下来，而且说清了是哪个加载器、哪个版本、没有导入", quiltText);
    // NOTE: 这一条 2026-09-25 改过。原来钉的是"CurseForge 那一支要把「清单里没有下载
    //       地址」说清楚"—— 那一支已经删了（CurseForge 现在装得了，见 ZG 节），留着
    //       就等于钉一个不存在的分支。现在这个函数只回答一件事：**两个清单都没有**
    //       ⇒ 认不出它是什么格式。所以钉的是"把两个名字都写出来"，以及它替用户猜了
    //       一句"多半是个普通压缩包"（不说这一句，用户只能自己猜要不要放弃）。
    const QString cfText = ModpackImport::unsupportedFormatText(ModpackImport::Format::CurseForge);
    check(cfText.contains(QStringLiteral("manifest.json")) &&
              cfText.contains(ModpackImport::modrinthIndexName()) &&
              cfText.contains(QStringLiteral("压缩包")),
          "V1 认不出格式那句话：两个清单文件名都写着 + 替用户猜一句它多半是什么", cfText);
    const QString unknownText = ModpackImport::unsupportedFormatText(ModpackImport::Format::Unknown);
    check(unknownText.contains(QStringLiteral("modrinth.index.json")) &&
              unknownText.contains(QStringLiteral("manifest.json")),
          "V1 认不出格式的话把两种清单的名字都说了出来（用户能自己去核对）", unknownText);

    // --- V2. 路径判据（这条漏一个 = 整合包能往实例目录外面写文件） --------------
    {
        struct Case {
            const char *path;
            bool safe;
            const char *why;
        };
        const Case cases[] = {
            {"mods/sodium.jar", true, "普通的相对路径"},
            {"config/openloader/data/x.zip", true, "多几层也可以"},
            {"mods/../../x.jar", false, "逐段判：中间那段 `..` 拦得住"},
            {"../../x.jar", false, "开头的 `..`"},
            {"..\\..\\x.jar", false, "反斜杠一律拒绝（按 / 切它就是一整段，逐段看不出问题）"},
            {"mods\\sodium.jar", false, "同上：Windows 上反斜杠也是分隔符"},
            {"/etc/passwd", false, "绝对路径"},
            {"C:/x.jar", false, "盘符（冒号本来就在非法字符里）"},
            {"mods/a:b.jar", false, "段里带冒号"},
            {"", false, "空路径"},
            {"mods/", false, "结尾多一个斜杠会切出一个空段"},
            {"a//b", false, "中间空段"},
            {"mods/./x.jar", false, "`.` 不是一段合法的目录名"},
            {"mods/x./y.jar", false, "以点结尾的段（Windows 会悄悄吃掉那个点）"},
            {"mods/x.jar ", false, "以空格结尾的段（同上；整合包这条路不做 trim）"},
            {"mods/CON.jar", false, "段的主名是 Windows 保留设备名"},
            {"mods/con.txt", false, "保留名判据不区分大小写（section('.') 之后是 con）"},
        };
        int wrong = 0;
        for (const Case &c : cases) {
            if (ModpackImport::isSafeRelativePath(QString::fromUtf8(c.path)) != c.safe) {
                ++wrong;
                out() << "        [判错了] " << c.path << "（该是"
                      << (c.safe ? "安全" : "不安全") << "：" << c.why << "）\n";
            }
        }
        check(wrong == 0, "V2 路径安全性真值表 17 条全对", QStringLiteral("错 %1 条").arg(wrong));

        // 长度：240 是上限（Windows 的 MAX_PATH 260 减去实例目录那一段）。边界要判准，
        // 否则"刚好 240 的正常长路径"会被整包拒绝。
        const QString ok240 = QStringLiteral("mods/") + QString(235, QLatin1Char('a'));
        check(ok240.length() == 240 && ModpackImport::isSafeRelativePath(ok240),
              "V2 正好 240 个字符的路径放行", QStringLiteral("长度 %1").arg(ok240.length()));
        const QString tooLong = ok240 + QLatin1Char('a');
        check(!ModpackImport::isSafeRelativePath(tooLong), "V2 241 个字符的路径拒绝");
    }

    // --- V3. 从包名推实例名 ---------------------------------------------------
    {
        check(ModpackImport::suggestInstanceName(QStringLiteral("  一个包  ")) ==
                  QStringLiteral("一个包"),
              "V3 前后的空白去掉");
        check(ModpackImport::suggestInstanceName(
                  QStringLiteral("ATT2: The Journey Of Revelation")) ==
                  QStringLiteral("ATT2- The Journey Of Revelation"),
              "V3 建不出目录的字符换成 `-`（这里是 名字里的 `:`）",
              ModpackImport::suggestInstanceName(
                  QStringLiteral("ATT2: The Journey Of Revelation")));
        check(ModpackImport::suggestInstanceName(QStringLiteral("包.")) == QStringLiteral("包"),
              "V3 结尾的点去掉（Windows 会静默吃掉它）",
              ModpackImport::suggestInstanceName(QStringLiteral("包.")));
        check(ModpackImport::suggestInstanceName(QString()) == QStringLiteral("整合包") &&
                  ModpackImport::suggestInstanceName(QStringLiteral("   ")) ==
                      QStringLiteral("整合包") &&
                  ModpackImport::suggestInstanceName(QStringLiteral("..")) ==
                      QStringLiteral("整合包"),
              "V3 空的 / 全是空白 / `..` 都退化成一句通用的名字");
        const QString con = ModpackImport::suggestInstanceName(QStringLiteral("CON"));
        check(con != QStringLiteral("CON") && con.contains(QStringLiteral("CON")),
              "V3 保留设备名换个说法绕开（不能原样用它建目录）", con);
        const QString longName = ModpackImport::suggestInstanceName(QString(200, QLatin1Char('x')));
        check(longName.length() <= InstanceFiles::kMaxDirNameLength && !longName.isEmpty(),
              "V3 超长的名字收到实例名的长度上限内",
              QStringLiteral("长度 %1").arg(longName.length()));
        // 这一条是这一节里最要紧的：候选名字是**界面预填**到输入框里的，它自己过不了
        // 校验的话，用户一进来就撞一句报错，而他什么都没输。
        // NOTE: 这里比的是 suggestInstanceName() 的**产物**，不是包名本身 —— 包名里带
        //       冒号、带结尾的点、叫 CON 都是正常的（真那份就叫
        //       "ATT2: The Journey Of Revelation.1.8.4"，名字里就有冒号）。要证的是
        //       "推出来、预填进输入框的那个名字，用户直接点确定就能过"。
        const QStringList packNames = {QStringLiteral("ATT2: The Journey Of Revelation.1.8.4"),
                                       QStringLiteral("包."), QStringLiteral("CON"), QString(),
                                       longName, QStringLiteral("带 空格 的名字"),
                                       QStringLiteral(".."), QStringLiteral("名字里带/斜杠")};
        int bad = 0;
        for (const QString &packName : packNames) {
            const QString candidate = ModpackImport::suggestInstanceName(packName);
            const QString problem = InstanceFiles::validateRenameTarget(candidate, QString());
            if (!problem.isEmpty()) {
                ++bad;
                out() << "        [推出来的名字过不了校验] 包名「" << packName << "」-> 「"
                      << candidate << "」：" << problem << "\n";
            }
        }
        check(bad == 0, "V3 推出来的每一个候选名字都过得了 validateRenameTarget()",
              QStringLiteral("坏 %1 个").arg(bad));
    }

    // --- V3b. 先试哪条地址：cdn.modrinth.com 排最前 -----------------------------
    {
        // 真机背景：那个包里同一条文件常常给 2~3 条地址（forgecdn 两台 + modrinth 一台），
        // 清单把 modrinth 排在最后，而原来的代码只用 first() 和 value(1)。实测 3~10 倍差
        // （见 ModpackImport.hpp 里 preferredUrlOrder 的注释）。这一节钉的就是"换次序"，
        // 不钉任何速度 —— 速度是网络的事，验证工程不联网。
        const QString cf1 = QStringLiteral(
            "https://mediafilez.forgecdn.net/files/8246/47/L_Enders_Cataclysm-3.31.jar");
        const QString cf2 = QStringLiteral(
            "https://edge.forgecdn.net/files/8246/47/L_Enders_Cataclysm-3.31.jar");
        const QString mr = QStringLiteral(
            "https://cdn.modrinth.com/data/46KJle7n/versions/C3H0azzB/L_Enders_Cataclysm-3.31.jar");

        const QStringList tri = ModpackImport::preferredUrlOrder({cf1, cf2, mr});
        check(tri.size() == 3 && tri.value(0) == mr,
              "V3b 三条地址里 modrinth 那条排到最前（另两条只换位次、不丢）",
              tri.join(QStringLiteral(" | ")));
        check(tri.value(1) == cf1 && tri.value(2) == cf2,
              "V3b 剩下那两条保持原来的相对次序（换位次不是打乱）",
              tri.join(QStringLiteral(" | ")));

        // 只有一条 modrinth 的（那个包里 42 个文件是这样）：原样返回。
        const QStringList onlyMr = ModpackImport::preferredUrlOrder({mr});
        check(onlyMr.size() == 1 && onlyMr.value(0) == mr, "V3b 单条地址原样返回");

        // 三条里一条 modrinth 都没有：**次序一个字符都不动** —— 这条最要紧，
        // 它是"认不出就别乱动"那条兜底（全是 forgecdn 的文件有 90 个）。
        const QStringList onlyCf = ModpackImport::preferredUrlOrder({cf1, cf2});
        check(onlyCf == QStringList({cf1, cf2}),
              "V3b 一条 modrinth 都没有时次序不动", onlyCf.join(QStringLiteral(" | ")));

        // host 必须按 QUrl 判，不能拿 QString::contains("modrinth") 那种办法认：
        // 一个**别家**的 host 里带这个字样（比如被抓包的镜像站）不该被当成首选。
        const QStringList trap = ModpackImport::preferredUrlOrder(
            {cf1, QStringLiteral("https://cdn.modrinth.com.evil.example/x.jar")});
        check(trap.value(0) == cf1,
              "V3b 认的是 host 本身，不是串里有没有 modrinth 那几个字",
              trap.join(QStringLiteral(" | ")));

        // 空表（清单里 downloads 是空的那些已经在解析时被剔掉了，这里只是别崩）。
        check(ModpackImport::preferredUrlOrder({}).isEmpty(), "V3b 空表返回空表");
    }

    // --- V4. 解析：一小段一小段地看它拒绝什么、接受什么 ------------------------

    {
        // 最小的一份合法清单：一个文件、一条依赖。
        const QByteArray minimal = R"json({
            "formatVersion": 1,
            "game": "minecraft",
            "name": "测试包",
            "versionId": "1.0",
            "dependencies": {"minecraft": "1.20.2", "fabric-loader": "0.16.14"},
            "files": [
                {"path": "mods/a.jar", "hashes": {"sha1": "aa"},
                 "downloads": ["https://example.invalid/a.jar"], "fileSize": 12}
            ]
        })json";
        const ModpackImport::Result okResult = ModpackImport::parseModrinthIndex(minimal);
        check(okResult.ok && okResult.pack.name == QStringLiteral("测试包") &&
                  okResult.pack.version == QStringLiteral("1.0") &&
                  okResult.pack.gameVersion == QStringLiteral("1.20.2") &&
                  okResult.pack.loaderKey == QStringLiteral("fabric-loader") &&
                  okResult.pack.loaderVersion == QStringLiteral("0.16.14") &&
                  okResult.pack.files.size() == 1 && okResult.pack.filesSkipped == 0 &&
                  okResult.pack.format == ModpackImport::Format::Modrinth,
              "V4 一份最小的合法清单：名字/版本/游戏版本/加载器/文件都对",
              okResult.ok ? QStringLiteral("%1 个文件").arg(okResult.pack.files.size())
                          : okResult.problem);
        if (okResult.ok && okResult.pack.files.size() == 1) {
            const ModpackImport::PackFile &file = okResult.pack.files.first();
            check(file.path == QStringLiteral("mods/a.jar") && file.sha1 == QStringLiteral("aa") &&
                      file.size == 12 && file.urls.size() == 1,
                  "V4 每条文件的路径 / sha1 / 字节数 / 地址都读出来了");
        }

        const auto problemOf = [](const QByteArray &json) {
            const ModpackImport::Result r = ModpackImport::parseModrinthIndex(json);
            return r.ok ? QString() : r.problem;
        };
        check(problemOf(QByteArray("这不是 json")).contains(QStringLiteral("读不懂")),
              "V4 不是 json：说「读不懂」");
        check(problemOf(QByteArray("{}")).contains(QStringLiteral("formatVersion")),
              "V4 缺 formatVersion/files：说它不是整合包清单");
        check(problemOf(R"json({"formatVersion":1,"files":[],"game":"factorio",
                                "dependencies":{"minecraft":"1.20.2"}})json")
                  .contains(QStringLiteral("Minecraft")),
              "V4 别的游戏的包：说「这不是 Minecraft 的整合包」");
        check(problemOf(R"json({"formatVersion":1,"files":[],"game":"minecraft",
                                "dependencies":{}})json")
                  .contains(QStringLiteral("dependencies.minecraft")),
              "V4 没写基于哪个原版：说清了缺的是 dependencies.minecraft");
        check(!problemOf(R"json({"formatVersion":1,"game":"minecraft",
                                 "dependencies":{"minecraft":"1.20.2"},"files":[]})json")
                   .isEmpty(),
              "V4 一条文件都没有：不装（不然就是「装完了，什么都没有」）");

        // 路径不安全 = **整包拒绝**，不是跳过那一条。它碰的是"会写到实例目录外面去"，
        // 放过其余的等于让用户在一个被做过手脚的包上继续走。
        const QByteArray traversal = R"json({
            "formatVersion": 1, "game": "minecraft",
            "dependencies": {"minecraft": "1.20.2"},
            "files": [
                {"path": "mods/a.jar", "downloads": ["https://example.invalid/a.jar"]},
                {"path": "../../外面的文件.txt", "downloads": ["https://example.invalid/b"]}
            ]
        })json";
        const ModpackImport::Result bad = ModpackImport::parseModrinthIndex(traversal);
        check(!bad.ok && bad.problem.contains(QStringLiteral("../../外面的文件.txt")) &&
                  bad.problem.contains(QStringLiteral("整个包")),
              "V4 有一条往外跳的路径：整包拒绝，而且把那一条原样指出来", bad.problem);

        // 跳过的两类：只给服务端用的、没有下载地址的。两个都要**记一笔**（用户看不到
        // 的那部分最容易变成"进了游戏才发现少个 mod"）。
        const QByteArray skipped = R"json({
            "formatVersion": 1, "game": "minecraft",
            "dependencies": {"minecraft": "1.20.2"},
            "files": [
                {"path": "mods/a.jar", "downloads": ["https://example.invalid/a.jar"]},
                {"path": "mods/server.jar", "downloads": ["https://example.invalid/s.jar"],
                 "env": {"client": "unsupported"}},
                {"path": "config/x.txt", "downloads": []},
                {"path": "mods/a.jar", "hashes": {"sha1": "后面那条"},
                 "downloads": ["https://example.invalid/a2.jar"]}
            ]
        })json";
        const ModpackImport::Result s = ModpackImport::parseModrinthIndex(skipped);
        check(s.ok && s.pack.files.size() == 1 && s.pack.filesSkipped == 2,
              "V4 只给服务端用的、没有下载地址的各记一笔跳过；同一个路径出现两次以最后一条为准",
              s.ok ? QStringLiteral("留下 %1、跳过 %2").arg(s.pack.files.size())
                            .arg(s.pack.filesSkipped)
                    : s.problem);
        if (s.ok && s.pack.files.size() == 1) {
            check(s.pack.files.first().sha1 == QStringLiteral("后面那条"),
                  "V4 重复路径：留下的是**最后**那一条");
        }

        // 纯原版的包：依赖表里只有 minecraft。能装，只是没有加载器要塞。
        const QByteArray vanillaPack = R"json({
            "formatVersion": 1, "game": "minecraft",
            "dependencies": {"minecraft": "1.18.2"},
            "files": [{"path": "mods/a.jar", "downloads": ["https://example.invalid/a.jar"]}]
        })json";
        const ModpackImport::Result v = ModpackImport::parseModrinthIndex(vanillaPack);
        check(v.ok && v.pack.loaderKey.isEmpty(),
              "V4 纯原版的包（依赖表里只有 minecraft）认了，加载器键是空的");

        // 名字缺了不能拒绝整个包（它只是"起实例名时的候选"）。
        const QByteArray noName = R"json({
            "formatVersion": 1, "game": "minecraft", "versionId": "9.9",
            "dependencies": {"minecraft": "1.20.2"},
            "files": [{"path": "mods/a.jar", "downloads": ["https://example.invalid/a.jar"]}]
        })json";
        const ModpackImport::Result nn = ModpackImport::parseModrinthIndex(noName);
        check(nn.ok && nn.pack.name == QStringLiteral("9.9") && nn.pack.version == QStringLiteral("9.9"),
              "V4 没有 name：退化成版本号，不因为缺名字拒绝整个包",
              nn.ok ? nn.pack.name : nn.problem);
    }

    // --- V5. ZipUtil：真造一个压缩包、真解一次 -------------------------------
    //
    // 两个坑都是实测踩出来的，都值得钉住：
    //   ① PowerShell 的 Compress-Archive 写进去的条目名用的是**反斜杠**。按 `/` 比前缀
    //      的话一条都匹配不上 —— 表现是"解压成功、解出来 0 个文件"，不报任何错。
    //   ② 两个前缀的**顺序**就是优先级（client-overrides 盖过 overrides），这是整合包
    //      格式的规矩，不能调换。
    {
        const QString work = sandbox + "/modpack-check";
        QDir(work).removeRecursively();
        const QString src = work + "/src";
        writeFileAt(src + "/overrides/config/a.txt", "来自 overrides");
        writeFileAt(src + "/client-overrides/config/a.txt", "来自 client-overrides");
        writeFileAt(src + "/overrides/config/b.txt", "只在 overrides 里");
        writeFileAt(src + "/overrides/mods/x.jar", "假的 mod");
        writeFileAt(src + "/modrinth.index.json", "{}");
        writeFileAt(src + "/README.txt", "不该被解出来");

        const QString archive = work + "/pack.zip";
        const QString script =
            QStringLiteral("Compress-Archive -Path %1 -DestinationPath %2 -Force")
                .arg(QStringLiteral("'") + QDir::toNativeSeparators(src) + QStringLiteral("\\*'"),
                     QStringLiteral("'") + QDir::toNativeSeparators(archive) + QStringLiteral("'"));
        QProcess ps;
        ps.start(QStringLiteral("powershell"),
                 {QStringLiteral("-NoProfile"), QStringLiteral("-NonInteractive"),
                  QStringLiteral("-ExecutionPolicy"), QStringLiteral("Bypass"),
                  QStringLiteral("-Command"), script});
        const bool compressed = ps.waitForFinished(180000) &&
                                ps.exitStatus() == QProcess::NormalExit && ps.exitCode() == 0;
        check(compressed, "V5 造出一个测试用的压缩包（Compress-Archive）",
              QString::fromLocal8Bit(ps.readAllStandardError()).trimmed().left(200));
        if (!compressed) {
            QDir(work).removeRecursively();
            return;
        }

        // 读单个条目：有 / 没有 / 不是 zip 三种结果必须分得清 —— 界面给的是三句不同的话。
        QByteArray bytes;
        QString error;
        check(ZipUtil::readEntry(archive, ModpackImport::modrinthIndexName(), &bytes, &error) ==
                      ZipUtil::EntryStatus::Ok &&
                  bytes == QByteArray("{}"),
              "V5 readEntry 读到了那一份清单，字节原样", QString::fromUtf8(bytes).left(40));
        check(ZipUtil::readEntry(archive, QStringLiteral("nope.json"), &bytes, &error) ==
                  ZipUtil::EntryStatus::NotFound,
              "V5 压缩包里没有那个条目：报 NotFound（= 「这不是整合包」，不是「文件坏了」）");
        // 上面那次 NotFound 之后 bytes 要被清掉，不能留着上一次的内容（留着的话调用方
        // 拿它去解析，会解出一份**上一个包**的清单）。
        check(bytes.isEmpty(), "V5 没读到东西时 out 被清空了（不然会拿上一次的字节去解析）");
        check(ZipUtil::readEntry(archive, QStringLiteral("MODRINTH.INDEX.JSON"), &bytes,
                                 &error) == ZipUtil::EntryStatus::Ok,
              "V5 条目名大小写不一样也认得（zip 的条目名区分大小写，但整合包工具不一定讲究）");
        const QString notAZip = work + "/假.zip";
        writeFileAt(notAZip, "这不是压缩包");
        check(ZipUtil::readEntry(notAZip, ModpackImport::modrinthIndexName(), &bytes, &error) ==
                  ZipUtil::EntryStatus::NotAnArchive,
              "V5 不是 zip 的文件：报 NotAnArchive（= 「这个文件打不开」）");

        // 按前缀解压：剥掉前缀、"杂项一个都不碰"、后一个前缀盖前一个。
        const QString out = work + "/out";
        int extracted = 0;
        const QStringList roots = {QStringLiteral("overrides/"), QStringLiteral("client-overrides/")};
        const bool extractedOk =
            ZipUtil::extractSubtrees({archive}, out, roots, &extracted, &error);
        check(extractedOk && extracted == 4,
              "V5 extractSubtrees 解出 4 个条目（两个 a.txt、一个 b.txt、一个 x.jar）",
              extractedOk ? QStringLiteral("解出 %1 个").arg(extracted) : error);

        const auto readText = [](const QString &path) {
            QFile f(path);
            return f.open(QIODevice::ReadOnly) ? QString::fromUtf8(f.readAll()) : QString();
        };
        check(!QFile::exists(out + "/overrides/config/a.txt") &&
                  !QFile::exists(out + "/client-overrides/config/a.txt") &&
                  QFile::exists(out + "/config/a.txt"),
              "V5 前缀被剥掉了：解出来的是 <目标>/config/a.txt，不是 <目标>/<前缀>/config/a.txt");
        check(readText(out + "/config/a.txt") == QStringLiteral("来自 client-overrides"),
              "V5 两个前缀撞同一个文件时，client-overrides 盖过 overrides");
        check(readText(out + "/config/b.txt") == QStringLiteral("只在 overrides 里") &&
                  readText(out + "/mods/x.jar") == QStringLiteral("假的 mod"),
              "V5 overrides 底下别的条目也解出来了");
        check(!QFile::exists(out + "/modrinth.index.json") && !QFile::exists(out + "/README.txt"),
              "V5 不属于任何前缀的条目一个都没碰（清单文件和 README 没进实例目录）");

        QDir(work).removeRecursively();
    }

    // --- V5z. 拖进来的那一个文件到底是什么（2026-09-29 加） --------------------
    //
    // 用户原话：「打开某个实例设置的时候如果拖入.jar/.zip之类的文件，检测是整合包还是资源包
    // 等」。判据层是 `manage/DroppedResource`（纯函数：输入一条路径，输出一个 Kind）——
    // 它只做判断，问什么、往哪儿放都在 MainWindow 那边，所以这一节能在这儿钉死。
    //
    // ★ 八个包**一趟 PowerShell 造完**（一个 ZipArchive::Create 里连着建八个）：.NET 的
    //   `CreateEntry()` 按原字面量写条目名，`Compress-Archive` 会规整掉反斜杠 —— 要测
    //   "反斜杠写的包"就只能走 .NET。见 V5c 里那条 NOTE，同一个理由。
    //
    // ★ 优先级那两条是这一节的**主角**：一个包里同时有 `pack.mcmeta`+`assets/` 和
    //   `shaders/`（真实世界里的资源包太常见了），判成资源包还是光影，取决于两个判据的
    //   先后 —— 排错了不会崩、不会报错，就是往 shaderpacks/ 里塞一个资源包。
    {
        const QString work = sandbox + "/dropped";
        QDir(work).removeRecursively();
        QDir().mkpath(work);

        const auto buildArchive = [&](const QString &archive,
                                      const QList<QPair<QString, QString>> &entries) {
            // ★ 条目名/正文**只能**自己包单引号：`psQuoted()` 会顺手 toNativeSeparators，
            //   那会把条目名里的 `/` 全折成 `\` —— 造出来的就不再是我们要测的那个包了。
            const auto psq = [](const QString &text) {
                return QStringLiteral("'") + text + QStringLiteral("'");
            };
            QStringList lines;
            lines << QStringLiteral("$ErrorActionPreference='Stop'")
                  << QStringLiteral("Add-Type -AssemblyName System.IO.Compression.FileSystem")
                  << QStringLiteral("$z=[System.IO.Compression.ZipFile]::Open(%1,'Create')")
                         .arg(psQuoted(archive))
                  << QStringLiteral("try{");
            for (const QPair<QString, QString> &entry : entries) {
                if (entry.second.isEmpty()) {
                    // 空目录条目：名字以 `/` 结尾（zip 里合法，而且真有工具这么写）。
                    lines << QStringLiteral("  $z.CreateEntry(%1)").arg(psq(entry.first));
                } else {
                    lines << QStringLiteral("  $e=$z.CreateEntry(%1)").arg(psq(entry.first))
                          << QStringLiteral("  $s=$e.Open()")
                          << QStringLiteral("  $b=[System.Text.Encoding]::UTF8.GetBytes(%1)")
                                 .arg(psq(entry.second))
                          << QStringLiteral("  $s.Write($b,0,$b.Length)")
                          << QStringLiteral("  $s.Close()");
                }
            }
            lines << QStringLiteral("} finally { $z.Dispose() }");
            QProcess ps;
            ps.start(QStringLiteral("powershell"),
                     {QStringLiteral("-NoProfile"), QStringLiteral("-NonInteractive"),
                      QStringLiteral("-ExecutionPolicy"), QStringLiteral("Bypass"),
                      QStringLiteral("-Command"), lines.join(QLatin1Char('\n'))});
            return ps.waitForFinished(180000) && ps.exitStatus() == QProcess::NormalExit &&
                   ps.exitCode() == 0;
        };

        const QString respack = work + "/respack.zip";
        check(buildArchive(respack,
                           {{QStringLiteral("pack.mcmeta"), QStringLiteral("{}")},
                            {QStringLiteral("assets/minecraft/lang/zh_cn.json"), QStringLiteral("{}")}}),
              "V5z 造出一个资源包（pack.mcmeta + assets/）");
        const QString datapack = work + "/datapack.zip";
        check(buildArchive(datapack,
                           {{QStringLiteral("pack.mcmeta"), QStringLiteral("{}")},
                            {QStringLiteral("data/minecraft/tags/function/a.json"), QStringLiteral("{}")}}),
              "V5z 造出一个数据包（pack.mcmeta + data/）");
        const QString shader = work + "/shader.zip";
        check(buildArchive(shader,
                           {{QStringLiteral("shaders/final.fsh"), QStringLiteral("void main(){}")},
                            {QStringLiteral("shaders/gbuffers_terrain.vsh"), QStringLiteral("void main(){}")}}),
              "V5z 造出一个光影包（shaders/）");
        // ★ 同时有 assets/ 和 shaders/：资源包排在前面 ⇒ 必须是资源包。
        const QString both = work + "/respack-with-shader.zip";
        check(buildArchive(both,
                           {{QStringLiteral("pack.mcmeta"), QStringLiteral("{}")},
                            {QStringLiteral("assets/minecraft/lang/zh_cn.json"), QStringLiteral("{}")},
                            {QStringLiteral("shaders/final.fsh"), QStringLiteral("void main(){}")}}),
              "V5z 造出一个「资源包 + 里面还带 shaders/」的包（真实世界里的常客）");
        const QString nested = work + "/nested.zip";
        check(buildArchive(nested,
                           {{QStringLiteral("MyPack/pack.mcmeta"), QStringLiteral("{}")},
                            {QStringLiteral("MyPack/assets/minecraft/lang/zh_cn.json"),
                              QStringLiteral("{}")}}),
              "V5z 造出一个「整个目录一起压」的包（条目都套在 MyPack/ 底下）");
        const QString backslash = work + "/backslash.zip";
        check(buildArchive(backslash, {{QStringLiteral("assets\\minecraft\\x.txt"),
                                        QStringLiteral("反斜杠")}}),
              "V5z 造出一个条目名用反斜杠写的包（国内那些「一键压缩」常这么干）");
        const QString mrpack = work + "/mrpack.zip";
        check(buildArchive(mrpack,
                           {{QStringLiteral("modrinth.index.json"), QStringLiteral("{}")},
                            {QStringLiteral("overrides/mods/a.jar"), QStringLiteral("x")}}),
              "V5z 造出一个 Modrinth 整合包");
        const QString cfpack = work + "/cfpack.zip";
        check(buildArchive(cfpack,
                           {{QStringLiteral("manifest.json"), QStringLiteral("{}")},
                            {QStringLiteral("overrides/config/a.txt"), QStringLiteral("x")}}),
              "V5z 造出一个 CurseForge 整合包");
        const QString junk = work + "/junk.zip";
        check(buildArchive(junk, {{QStringLiteral("README.txt"), QStringLiteral("说明")}}),
              "V5z 造出一个「里面什么都不是」的压缩包");

        const auto kindOf = [](const QString &path) {
            return DroppedResource::classify(path);
        };
        const auto isKind = [&](const QString &path, ResourceCatalog::Kind kind) {
            const DroppedResource::Result r = kindOf(path);
            return r.known && r.kind == kind;
        };

        check(isKind(respack, ResourceCatalog::Kind::ResourcePack),
              "V5z pack.mcmeta + assets/ ⇒ 资源包", kindOf(respack).detail);
        check(isKind(datapack, ResourceCatalog::Kind::DataPack),
              "V5z pack.mcmeta + data/ ⇒ 数据包", kindOf(datapack).detail);
        check(isKind(shader, ResourceCatalog::Kind::Shader),
              "V5z 只有 shaders/ ⇒ 光影", kindOf(shader).detail);
        // ★★ 优先级：这条要是红了，用户拖一个带 shaders/ 的资源包进来会进 shaderpacks/。
        check(isKind(both, ResourceCatalog::Kind::ResourcePack),
              "★★ V5z 同时有 assets/ 和 shaders/ ⇒ **资源包**（那一串判据的先后就是优先级，"
              "排错了就是往光影目录里塞资源包）",
              kindOf(both).detail);
        check(isKind(nested, ResourceCatalog::Kind::ResourcePack),
              "V5z 套在一层目录里的包也认得出来（GitHub 的 zipball / 右键压缩都是这个形状）",
              kindOf(nested).detail);
        check(isKind(mrpack, ResourceCatalog::Kind::Modpack),
              "V5z 根上有 modrinth.index.json ⇒ 整合包", kindOf(mrpack).detail);
        check(isKind(cfpack, ResourceCatalog::Kind::Modpack),
              "V5z 根上有 manifest.json ⇒ 整合包（CurseForge 那个格式）",
              kindOf(cfpack).detail);

        // `.jar` **一个字节都不读盘**：它是不是压缩包、里面有什么，都不影响判断
        // （模组就是模组）。这一条同时钉住"后缀大小写不敏感"。
        const QString jar = work + "/某某模组.JAR";
        writeFileAt(jar, "不是真的 jar，只是个名字");
        check(isKind(jar, ResourceCatalog::Kind::Mod),
              "V5z .jar 就是模组（后缀大小写不敏感、**不读盘**：这个文件根本不是压缩包）",
              kindOf(jar).detail);

        // 认不出来的那几档：反斜杠那个包、什么都不是的包、根本不是压缩包的文件、目录、不存在
        // 的路径。它们必须一律 `known == false` —— 界面上那一句"这几个认不出来"就是它。
        check(!kindOf(backslash).known,
              "V5z 条目名用反斜杠写的包：连 assets/ 都拼不出来 ⇒ 认不出来（如实说，不猜）",
              kindOf(backslash).detail);
        check(!kindOf(junk).known, "V5z 里面什么都没有的压缩包 ⇒ 认不出来",
              kindOf(junk).detail);
        const QString notZip = work + "/其实是文本.zip";
        writeFileAt(notZip, "这不是压缩包");
        check(!kindOf(notZip).known,
              "V5z 后缀是 .zip 但不是压缩包 ⇒ 认不出来（不是「整合包」，也不是崩）",
              kindOf(notZip).detail);
        check(!kindOf(work).known, "V5z 拖进来的是个目录 ⇒ 认不出来", kindOf(work).detail);
        check(!kindOf(work + "/根本没有这个文件.zip").known,
              "V5z 盘上没有这个文件 ⇒ 认不出来", kindOf(work + "/根本没有这个文件.zip").detail);
        check(!kindOf(QString()).known, "V5z 空串 ⇒ 认不出来（不崩）");

        // `detail` 那一格是界面拿去写在括号里的"为什么"，认不出来时**必须有一句人话**
        // （空串的话那一行会变成「xxx（)」）。
        check(!kindOf(junk).detail.isEmpty() && !kindOf(notZip).detail.isEmpty(),
              "V5z 认不出来的时候带一句理由（界面上那个括号里就是它）",
              kindOf(notZip).detail);

        // ★ 空目录条目那一档：`Compress-Archive` 会写进 `assets/` 这样以斜杠结尾的记录。
        //   只按 `assets/…` 认前缀的话，一个只有空目录的资源包会被判成"什么都没有"。
        const QString dirOnly = work + "/dir-only.zip";
        check(buildArchive(dirOnly,
                           {{QStringLiteral("pack.mcmeta"), QStringLiteral("{}")},
                            {QStringLiteral("assets/"), QString()}}),
              "V5z 造出一个「assets 只是一条空目录记录」的资源包");
        check(isKind(dirOnly, ResourceCatalog::Kind::ResourcePack),
              "V5z 目录条目本身（`assets/` 这一条）也算数 ⇒ 还是资源包",
              kindOf(dirOnly).detail);

        // ★ `listEntries()` 就是上面那条路读条目表用的那一发：条目名**原样**拿回来
        //   （不替我们归一化、不排序，谁用谁自己折），不是压缩包时和 readEntry 分得一样清。
        QStringList names;
        QString error;
        check(ZipUtil::listEntries(respack, &names, &error) == ZipUtil::EntryStatus::Ok &&
                  names.size() == 2 && names.contains(QStringLiteral("pack.mcmeta")) &&
                  names.contains(QStringLiteral("assets/minecraft/lang/zh_cn.json")),
              "V5z listEntries 把两个条目名原样拿回来了", names.join(QLatin1Char(' ')));
        check(ZipUtil::listEntries(backslash, &names, &error) == ZipUtil::EntryStatus::Ok &&
                  names.contains(QStringLiteral("assets\\minecraft\\x.txt")),
              "V5z listEntries **不替我们归一化**反斜杠（折成 `/` 是调用方的事）",
              names.join(QLatin1Char(' ')));
        check(ZipUtil::listEntries(notZip, &names, &error) == ZipUtil::EntryStatus::NotAnArchive,
              "V5z listEntries 对不是压缩包的文件报 NotAnArchive");
        // ★ 盘上根本没有这一份：**和 readEntry 给同一个答案**（打不开 = NotAnArchive，不是
        //   NotFound）。`NotFound` 在这个枚举里的意思是"**压缩包里**没有这一条"，一条都还没
        //   读到的时候谈不上"没有哪一条"；两处答得不一样的话，界面同一个故障会说出两句
        //   不同的话。上面 V5z 那一条"盘上没有这个文件 ⇒ 认不出来"是**判据层**自己先挡掉的
        //   （它的 detail 是「找不到这份文件」）—— listEntries 根本轮不到。
        QByteArray oneEntry;
        check(ZipUtil::listEntries(work + "/没有这个.zip", &names, &error) ==
                      ZipUtil::EntryStatus::NotAnArchive &&
                  ZipUtil::readEntry(work + "/没有这个.zip", QStringLiteral("a.txt"), &oneEntry,
                                     &error) == ZipUtil::EntryStatus::NotAnArchive,
              "V5z listEntries 和不存在的文件对同一份读不了的东西给同一个答案"
              "（NotAnArchive，和 readEntry 一致）",
              error);
        // 空表也要能读（一个成员都没有的 zip 是合法的）。
        const QString emptyZip = work + "/empty.zip";
        check(buildArchive(emptyZip, {}), "V5z 造得出一个空压缩包");
        names = QStringList{QStringLiteral("上一次留下的")};
        check(ZipUtil::listEntries(emptyZip, &names, &error) == ZipUtil::EntryStatus::Ok &&
                  names.isEmpty(),
              "V5z 空压缩包 ⇒ 空表（而且把 out 里上一次留下的东西清掉了）");

        QDir(work).removeRecursively();
    }

    // --- V5c. extractArchives：那几条恶意条目名一个都不许解出去（zip slip） ------
    //
    // 这一节盯的是 LauncherManager::prepareNatives() 那条路（旧格式的 natives 是从
    // 官方 jar 里解出来的，用的是 ZipUtil::extractArchives）。原来的守卫只判条目名里
    // 有没有 `..`，漏了"条目名本身就是绝对路径"那一类 —— .NET 的 Path.Combine 会把
    // 目标目录整个丢掉，文件落到外面去。
    //
    // NOTE: 造包这一步**只能**用 .NET 的 ZipArchive::Create：PowerShell 的 Compress-Archive
    //       会把 `..`、绝对路径这些名字规整掉，造不出要测的东西（实测确认过条目名原样保留）。
    {
        const QString work = sandbox + "/zip-slip";
        QDir(work).removeRecursively();
        QDir().mkpath(work);  // ZipFile::Open('Create') 不会自己建父目录
        const QString archive = work + "/evil.zip";
        // 带盘符的绝对路径那条：Path.Combine 遇到它会丢掉 $out，于是落点就是它自己。
        // 落点**故意挑在沙盒里** —— 防线漏了也只是在沙盒里多出一个文件，碰不到系统目录。
        const QString escapeTarget =
            QDir::fromNativeSeparators(QDir(work).absolutePath()) + QStringLiteral("/escaped.txt");
        // `/abs.txt` 这类"只有斜杠开头"的条目，落点是**当前盘的根目录**（.NET 拿它当
        // 相对当前盘的绝对路径）。记一下它本来在不在：这条只该在"本来没有、跑完出现了"
        // 时红，不能因为盘根目录本来就有个同名文件而误报。
        const QString driveRootEscape = QDir::rootPath() + QStringLiteral("abs.txt");
        const bool driveRootEscapeExisted = QFile::exists(driveRootEscape);

        const QString script =
            QStringLiteral("$ErrorActionPreference='Stop'\n"
                           "Add-Type -AssemblyName System.IO.Compression.FileSystem\n"
                           "$zip=[System.IO.Compression.ZipFile]::Open(%1,'Create')\n"
                           "try{\n"
                           "  $items=@(\n"
                           "    @{n='ok.txt';c='正常条目'},\n"
                           "    @{n='sub\\ok2.txt';c='反斜杠条目'},\n"
                           "    @{n='../evil.txt';c='翻上去'},\n"
                           "    @{n='/abs.txt';c='斜杠开头的绝对路径'},\n"
                           "    @{n=%2;c='带盘符的绝对路径'},\n"
                           "    @{n='META-INF/MANIFEST.MF';c='签名文件'}\n"
                           "  )\n"
                           "  foreach($it in $items){\n"
                           "    $e=$zip.CreateEntry($it.n)\n"
                           "    $w=New-Object System.IO.StreamWriter($e.Open())\n"
                           "    $w.Write($it.c)\n"
                           "    $w.Dispose()\n"
                           "  }\n"
                           "} finally { $zip.Dispose() }\n")
                .arg(psQuoted(archive),
                     QStringLiteral("'") + escapeTarget + QStringLiteral("'"));
        QProcess ps;
        ps.start(QStringLiteral("powershell"),
                 {QStringLiteral("-NoProfile"), QStringLiteral("-NonInteractive"),
                  QStringLiteral("-ExecutionPolicy"), QStringLiteral("Bypass"),
                  QStringLiteral("-Command"), script});
        const bool madeZip = ps.waitForFinished(180000) &&
                             ps.exitStatus() == QProcess::NormalExit && ps.exitCode() == 0;
        check(madeZip, "V5c 造出一个带恶意条目名的压缩包（ZipArchive::Create 才造得出）",
              QString::fromLocal8Bit(ps.readAllStandardError()).trimmed().left(200));
        if (!madeZip) {
            QDir(work).removeRecursively();
            return;
        }

        const QString out = work + "/out";
        QString error;
        const bool ok = ZipUtil::extractArchives({archive}, out,
                                                  {QStringLiteral("META-INF")}, &error);
        check(ok, "V5c 解压整体算成功（恶意条目是被跳过的，不是整包失败）", error);

        const auto readTextAt = [](const QString &path) {
            QFile f(path);
            return f.open(QIODevice::ReadOnly) ? QString::fromUtf8(f.readAll()) : QString();
        };
        // 正路照样得通：正常的条目要解出来，反斜杠的条目名归一之后也落在目标目录里
        //（Minecraft 那些 jar 是 `/`，但别的工具打的包不一定讲究）。
        check(readTextAt(out + "/ok.txt") == QStringLiteral("正常条目") &&
                  readTextAt(out + "/sub/ok2.txt") == QStringLiteral("反斜杠条目"),
              "V5c 正常条目照解不误，反斜杠条目名归一成 / 之后落在目标目录里");
        // 四条恶意条目：一个都不许出现在目标目录外面。
        check(!QFile::exists(work + "/evil.txt"),
              "V5c `../evil.txt` 没有翻到目标目录上面去");
        check(driveRootEscapeExisted || !QFile::exists(driveRootEscape),
              "V5c `/abs.txt` 没有落到当前盘的根目录下（Combine 会丢掉目标目录）",
              driveRootEscape);
        check(!QFile::exists(escapeTarget),
              "V5c 带盘符的绝对路径条目没有写到外面去", escapeTarget);
        check(!QFile::exists(out + "/META-INF/MANIFEST.MF"),
              "V5c excludePrefixes 那条路照样挡着（META-INF 没进目标目录）");

        QDir(work).removeRecursively();
    }

    // --- V5d. 导出：CurseForge 指纹（murmur2 + 先剔空白字节） ------------------
    //
    // 这一节的期望值**不是**从 C++ 这边抄出来的：它们是一份 Python 独立实现算的
    // （`C:\Users\User\.claude\jobs\b62c43ac\tmp\fp3.py`），而那份实现拿一个真 jar
    // 跟 CurseForge 自己记录里的 `fileFingerprint` 对上过 —— 就是这一节最后那几条
    // （`meta/jei-fingerprint.jar`，sha1 也在断言里钉着，防的是夹具哪天被换掉）。
    // 所以这几条真能发现"哪一步抄错了"，而不是把 C++ 的输出再读一遍。
    {
        struct FingerprintCase {
            const char *what;
            QByteArray bytes;
            quint32 expected;
        };
        // 挑这些长度是为了把 murmur2 的**每一段**都走到：0、正好 4 的倍数、余 1、余 2、余 3，
        // 外加"剔完空白之后长度变了"的两种。空内容与纯空白那两个的期望值是**同一个数** ——
        // 这就是"剔空白"这件事最直白的一条：文件里有没有空白跟指纹无关。
        const QList<FingerprintCase> cases = {
            {"空内容", QByteArray(), 1540447798u},
            {"只有空白字节（\\t\\n\\r 空格）", QByteArray("\t\n\r \t"), 1540447798u},
            {"abcd（正好 4 字节，不进末梢）", QByteArray("abcd"), 3376380438u},
            {"abcde（余 1）", QByteArray("abcde"), 3469237630u},
            {"abcdef（余 2）", QByteArray("abcdef"), 455443312u},
            {"abcdefg（余 3）", QByteArray("abcdefg"), 184182053u},
            {"a b\\tc\\r\\nd  \\n（剔完就是 abcd）", QByteArray("a b\tc\r\nd  \n"), 3376380438u},
            {" abcde （撇号外面有空白，还是 abcde）", QByteArray(" abcde "), 3469237630u},
        };
        for (const FingerprintCase &one : cases) {
            const quint32 got = ModpackExport::curseForgeFingerprintOfBytes(one.bytes);
            check(got == one.expected,
                  QStringLiteral("V5d 指纹：%1").arg(QString::fromUtf8(one.what)),
                  QStringLiteral("期望 %1，实得 %2").arg(one.expected).arg(got));
        }
        // 0x00~0xFF 全都在，其中 0x09/0x0A/0x0D/0x20 会被剔掉，长度仍是 256（4 的倍数）。
        // 单独来一条是因为它同时压着"哪些字节算空白"：多剔一个（比如把 0x0B 也算上）
        // 或者少剔一个，这一个数就变。
        QByteArray allBytes;
        for (int i = 0; i < 256; ++i) {
            allBytes.append(static_cast<char>(i));
        }
        check(ModpackExport::curseForgeFingerprintOfBytes(allBytes) == 2094645347u,
              "V5d 指纹：0x00~0xFF 全字节表（剔掉的只有 09/0A/0D/20 这四个）",
              QString::number(ModpackExport::curseForgeFingerprintOfBytes(allBytes)));

        // 走文件那一趟：内容一样就得是同一个数，而且**跨读缓冲**的那一段（读侧一次 64 KiB，
        // 这个文件 287914 字节）不能把末梢状态丢掉 —— 掉一次，长文件的指纹就全错，
        // 而短文件那条路照样绿。
        QByteArray big;
        for (int i = 0; i < 200000; ++i) {
            big.append(static_cast<char>((i * 37 + 11) & 0xFF));
            if (i % 7 == 0) {
                big.append(QByteArrayLiteral(" \t"));
            }
            if (i % 13 == 0) {
                big.append(QByteArrayLiteral("\r\n"));
            }
        }
        check(big.size() == 287914,
              "V5d 大文件的字节数对得上（造法跟算期望值那份脚本一字不差）",
              QString::number(big.size()));
        check(ModpackExport::curseForgeFingerprintOfBytes(big) == 545617932u,
              "V5d 指纹：287914 字节、其中 91039 个是空白（跨了读缓冲）",
              QString::number(ModpackExport::curseForgeFingerprintOfBytes(big)));

        const QString fpWork = sandbox + "/export-fingerprint";
        QDir(fpWork).removeRecursively();
        QDir().mkpath(fpWork);
        const QString bigPath = fpWork + "/big.bin";
        writeFileAt(bigPath, big);
        quint32 fromFile = 0;
        QString fpError;
        const bool fpOk = ModpackExport::curseForgeFingerprint(bigPath, &fromFile, &fpError);
        check(fpOk && fromFile == 545617932u,
              "V5d 同一个文件走两条路（读文件 / 直接喂字节）得到的指纹一模一样",
              fpOk ? QString::number(fromFile) : fpError);
        // 读不到的文件必须是"失败 + 一句原因"，不能悄悄给出一个 0 或者 1（那会变成一个
        // 假指纹，拿去问接口当然查不到，于是整个文件白进 overrides —— 看着像"没认出来"）。
        const QString missingPath = fpWork + "/没有这个文件.bin";
        quint32 missingOut = 12345;
        QString missingError;
        const bool missingOk =
            ModpackExport::curseForgeFingerprint(missingPath, &missingOut, &missingError);
        check(!missingOk && !missingError.trimmed().isEmpty() && missingOut == 12345,
              "V5d 文件读不了时返回 false、给一句原因，且不碰出参", missingError);

        // 真文件那一条：这个 jar 是 CurseForge 上 JEI 的 `31.7.0.37` 那一份，
        // **`3309664856` 是 CurseForge 自己记录里的 `fileFingerprint`**（不是我们算的）。
        // 夹具的 sha1 一起钉着：本地文件的指纹只由字节决定，夹具被换掉这条就该红。
        const QString jarPath =
            QStringLiteral(REPO_ROOT_PATH) + "/tests/meta/jei-fingerprint.jar";
        QFile jar(jarPath);
        const bool haveJar = jar.open(QIODevice::ReadOnly);
        check(haveJar, "V5d 读到了真 jar 夹具（meta/jei-fingerprint.jar）", jarPath);
        if (haveJar) {
            const QByteArray jarBytes = jar.readAll();
            jar.close();
            check(QCryptographicHash::hash(jarBytes, QCryptographicHash::Sha1).toHex() ==
                      QByteArrayLiteral("c19b8bfb43a753ad8c27612d516ce61c58b0d2e6"),
                  "V5d 夹具就是那一份文件（sha1 与 CurseForge 记录里的一致）");
            quint32 jarFp = 0;
            QString jarError;
            const bool jarOk = ModpackExport::curseForgeFingerprint(jarPath, &jarFp, &jarError);
            check(jarOk && jarFp == 3309664856u,
                  "V5d 真 jar 的指纹与 CurseForge 记录里的 fileFingerprint 一字不差",
                  jarOk ? QString::number(jarFp) : jarError);
        }
        QDir(fpWork).removeRecursively();
    }

    // --- V5e. 导出：两份清单写出来能被我们自己的解析器读回来（往返） ------------
    //
    // 导出和导入是同一件事的两个方向，所以这里不另立一套"期望值"：**让 ModpackImport
    // 去读**我们写出来的东西。它能读回来 = 格式是对的（这一层完全离线能验，而它正好
    // 盖住导出最容易写错的那一层）。
    {
        ModpackExport::Spec spec;
        spec.format = ModpackExport::Format::Modrinth;
        spec.name = QStringLiteral("我的整合包");
        spec.version = QStringLiteral("1.2.3");
        spec.summary = QStringLiteral("一句话简介");
        spec.gameVersion = QStringLiteral("1.21.1");
        spec.loaderKey = ModpackImport::fabricLoaderKey();
        spec.loaderVersion = QStringLiteral("0.16.14");

        ModpackExport::MatchedFile mod;
        mod.path = QStringLiteral("mods/sodium.jar");
        mod.sha1 = QStringLiteral("1111111111111111111111111111111111111111");
        mod.sha512 = QString(128, QLatin1Char('a'));
        mod.urls = {QStringLiteral("https://cdn.modrinth.com/data/AABBCC/versions/xx/sodium.jar")};
        mod.size = 123456;
        mod.envClient = QStringLiteral("required");
        mod.envServer = QStringLiteral("required");
        spec.files.append(mod);

        // 用户自己改过名字的（`.disabled`）：**路径原样写**，状态就不丢（导入回来还是禁用的）。
        ModpackExport::MatchedFile disabled = mod;
        disabled.path = QStringLiteral("mods/别的名字.jar.disabled");
        disabled.sha1 = QStringLiteral("2222222222222222222222222222222222222222");
        spec.files.append(disabled);

        const QByteArray index = ModpackExport::buildModrinthIndex(spec);
        const ModpackImport::Result parsed = ModpackImport::parseModrinthIndex(index);
        check(parsed.ok, "V5e 我们写出来的 modrinth.index.json 自己的解析器读得回来",
              parsed.problem);
        if (parsed.ok) {
            const ModpackImport::Pack &pack = parsed.pack;
            check(pack.format == ModpackImport::Format::Modrinth && pack.name == spec.name &&
                      pack.version == spec.version && pack.gameVersion == spec.gameVersion,
                  "V5e 往返：名字 / 版本号 / 基于哪个原版都对得上",
                  pack.name + QLatin1Char('|') + pack.version + QLatin1Char('|') + pack.gameVersion);
            check(pack.loaderKey == ModpackExport::modrinthDependencyKey(spec.loaderKey) &&
                      pack.loaderVersion == spec.loaderVersion,
                  "V5e 往返：加载器那一行（键与纯版本号）",
                  pack.loaderKey + QLatin1Char('|') + pack.loaderVersion);
            check(pack.fileCount() == 2 && pack.filesSkipped == 0,
                  "V5e 往返：两条文件都在、一条都没被跳过",
                  QStringLiteral("%1 / 跳过 %2").arg(pack.fileCount()).arg(pack.filesSkipped));
            if (pack.fileCount() == 2) {
                const ModpackImport::PackFile &back = pack.files.at(0);
                check(back.path == mod.path && back.urls == mod.urls && back.sha1 == mod.sha1 &&
                          back.size == mod.size,
                      "V5e 往返：路径 / 地址 / sha1 / 字节数都原样读回来",
                      back.path);
                check(pack.files.at(1).path == disabled.path,
                      "V5e 往返：`.disabled` 的文件路径原样（名字没被改写）",
                      pack.files.at(1).path);
            }
        }

        // 纯原版的包：依赖表里只有 minecraft 那一行，不该多出加载器来。
        ModpackExport::Spec vanilla = spec;
        vanilla.loaderKey.clear();
        vanilla.loaderVersion.clear();
        vanilla.name = QStringLiteral("原版包");
        const ModpackImport::Result vanillaParsed =
            ModpackImport::parseModrinthIndex(ModpackExport::buildModrinthIndex(vanilla));
        check(vanillaParsed.ok && vanillaParsed.pack.loaderKey.isEmpty() &&
                  vanillaParsed.pack.gameVersion == spec.gameVersion,
              "V5e 纯原版的包往返回来加载器那一行是空的（不会被当成 Quilt 之类认不出的键）",
              vanillaParsed.problem);

        // 一条都没认出来的包：`files` 那一格照样写出来（空的），但**我们自己装不回去** ——
        // 解析器把"一条文件都没有"判成整包无效。这条钉的是那个已知缺口，免得以后有人
        // 以为"空 files 也没事"：真到那一步（一个都认不出来）得由调用方拦住，
        // 在界面上照实说，而不是导出一个自己都装不回来的包。
        ModpackExport::Spec nothing = spec;
        nothing.files.clear();
        const QByteArray nothingIndex = ModpackExport::buildModrinthIndex(nothing);
        const QJsonObject nothingRoot = QJsonDocument::fromJson(nothingIndex).object();
        check(nothingRoot.contains(QStringLiteral("files")) &&
                  nothingRoot.value(QStringLiteral("files")).toArray().isEmpty() &&
                  !ModpackImport::parseModrinthIndex(nothingIndex).ok,
              "V5e 一条都没认出来时清单里 files 是空数组，而我们自己的解析器拒收这种包"
              "（调用方必须在导出前拦下这一档）");

        // 缺哈希的条目**写不进去**（调用方该把它分到 overrides 去，不是丢）。理由见
        // writableAsIndexFile：清单里的 sha1 是安装时唯一的完整性判据。
        ModpackExport::MatchedFile noHash = mod;
        noHash.path = QStringLiteral("mods/没哈希.jar");
        noHash.sha1.clear();
        check(!ModpackExport::writableAsIndexFile(noHash) &&
                  ModpackExport::writableAsIndexFile(mod),
              "V5e writableAsIndexFile：缺 sha1 的不能写进 files[]，两条都齐的能");
        ModpackExport::Spec withBad = spec;
        withBad.files.append(noHash);
        const ModpackImport::Result withBadParsed =
            ModpackImport::parseModrinthIndex(ModpackExport::buildModrinthIndex(withBad));
        check(withBadParsed.ok && withBadParsed.pack.fileCount() == 2,
              "V5e 缺哈希的那条被写清单这一步拦下（不是写出一条坏的，也不是悄悄少一条）",
              QString::number(withBadParsed.pack.fileCount()));
        // 没地址的同理：导入方拿到它也不知道从哪下。
        ModpackExport::MatchedFile noUrl = mod;
        noUrl.urls.clear();
        check(!ModpackExport::writableAsIndexFile(noUrl),
              "V5e writableAsIndexFile：一条地址都没有的也不能写进 files[]");

        // CurseForge 那份：`files[]` 里只有两个号，加载器是一个字符串。
        ModpackExport::Spec forge = spec;
        forge.format = ModpackExport::Format::CurseForge;
        forge.files.clear();
        forge.loaderKey = ModpackImport::forgeLoaderKey();
        forge.loaderVersion = QStringLiteral("47.2.0");
        forge.author = QStringLiteral("某个人");
        forge.refs.append({238222, 8971390});
        forge.refs.append({0, 0});  // 两个号缺一个的那条：写不出去，也不该写出去
        const QByteArray manifest = ModpackExport::buildCurseForgeManifest(forge);
        const ModpackImport::Result cfParsed = ModpackImport::parseCurseForgeManifest(manifest);
        check(cfParsed.ok && cfParsed.pack.format == ModpackImport::Format::CurseForge,
              "V5e 我们写出来的 manifest.json 自己的解析器读得回来", cfParsed.problem);
        if (cfParsed.ok) {
            check(cfParsed.pack.pendingRefs.size() == 1 &&
                      cfParsed.pack.pendingRefs.at(0).projectId == 238222 &&
                      cfParsed.pack.pendingRefs.at(0).fileId == 8971390,
                  "V5e 往返：两个号原样回来、只有一条（号不全的那条没写出去）",
                  QString::number(cfParsed.pack.pendingRefs.size()));
            check(cfParsed.pack.loaderKey == ModpackImport::forgeLoaderKey() &&
                      cfParsed.pack.loaderVersion == forge.loaderVersion &&
                      cfParsed.pack.gameVersion == forge.gameVersion,
                  "V5e 往返：CurseForge 的加载器字符串拆回来的键与版本",
                  cfParsed.pack.loaderKey + QLatin1Char('|') + cfParsed.pack.loaderVersion);
            check(cfParsed.pack.overridesDir == QStringLiteral("overrides"),
                  "V5e 往返：overrides 那一层目录名（manifest 里明写了 `overrides`）",
                  cfParsed.pack.overridesDir);
        }

        // 加载器 id 的拼法：四个前缀各一条，外加 NeoForge 1.20.1 那个特例。
        // 期望值不是"我觉得该长这样"：`<前缀>-<版本>` 是这个格式的写法，而 1.20.1 那一条
        // 照的是 Prism 的做法（那一代的 NeoForge 版本号本身就带游戏版本）。
        const auto loaderIdIs = [](const QString &key, const QString &version,
                                   const QString &game, const QString &expected) {
            return ModpackExport::curseForgeLoaderId(key, version, game) == expected;
        };
        check(loaderIdIs(ModpackImport::forgeLoaderKey(), QStringLiteral("47.2.0"),
                         QStringLiteral("1.21.1"), QStringLiteral("forge-47.2.0")) &&
                  loaderIdIs(ModpackImport::fabricLoaderKey(), QStringLiteral("0.16.14"),
                             QStringLiteral("1.21.1"), QStringLiteral("fabric-0.16.14")) &&
                  loaderIdIs(ModpackImport::quiltLoaderKey(), QStringLiteral("0.20.0"),
                             QStringLiteral("1.21.1"), QStringLiteral("quilt-0.20.0")),
              "V5e CurseForge 的加载器 id = `<前缀>-<纯版本号>`");
        check(loaderIdIs(ModpackImport::neoforgeLoaderKey(), QStringLiteral("21.1.210"),
                         QStringLiteral("1.21.1"), QStringLiteral("neoforge-21.1.210")) &&
                  loaderIdIs(ModpackImport::neoforgeLoaderKey(), QStringLiteral("47.1.106"),
                             QStringLiteral("1.20.1"), QStringLiteral("neoforge-1.20.1-47.1.106")),
              "V5e NeoForge 只在 1.20.1 上插一段游戏版本（别的版本不加）");
        check(ModpackExport::curseForgeLoaderId(QStringLiteral("OptiFine"), QStringLiteral("H8"),
                                                QStringLiteral("1.8.9"))
                  .isEmpty(),
              "V5e 认不出来的加载器不给 id（不编一个出来，由调用方照实说）");

        // 认不出来的加载器键不许瞎翻译：编一个出来会让导入方去装一个不存在的东西。
        check(ModpackExport::modrinthDependencyKey(QStringLiteral("OptiFine")).isEmpty() &&
                  ModpackExport::modrinthDependencyKey(QStringLiteral("liteloader")).isEmpty(),
              "V5e Modrinth 依赖表：认不出来的加载器返回空串（宁可不写）");
        check(ModpackExport::modrinthDependencyKey(ModpackImport::fabricLoaderKey()) ==
                      QStringLiteral("fabric-loader") &&
                  ModpackExport::modrinthDependencyKey(ModpackImport::forgeLoaderKey()) ==
                      QStringLiteral("forge") &&
                  ModpackExport::modrinthDependencyKey(ModpackImport::neoforgeLoaderKey()) ==
                      QStringLiteral("neoforge") &&
                  ModpackExport::modrinthDependencyKey(ModpackImport::quiltLoaderKey()) ==
                      QStringLiteral("quilt-loader"),
              "V5e Modrinth 依赖表：四个键与 ModpackImport 那套一字不差");

        // 值不值得拿去反查：只对"像资源"的文件算哈希。这一条是**代价**上的取舍：
        // 放进来的是 config/ 底下成千上万个小文件（几十万个字节的哈希、一次接口请求都没有）。
        const auto becomesCandidate = [](const QString &path) {
            return ModpackExport::looksLikeResolvableResource(path);
        };
        check(becomesCandidate(QStringLiteral("mods/sodium.jar")) &&
                  becomesCandidate(QStringLiteral("mods/sub/nested.jar")) &&
                  becomesCandidate(QStringLiteral("mods/foo.jar.disabled")) &&
                  becomesCandidate(QStringLiteral("resourcepacks/包.zip")) &&
                  becomesCandidate(QStringLiteral("shaderpacks/光影.zip")) &&
                  becomesCandidate(QStringLiteral("datapacks/数据包.zip")) &&
                  becomesCandidate(QStringLiteral("coremods/old.jar")),
              "V5e 候选：资源目录下的 jar/zip/… 都拿去反查");
        check(!becomesCandidate(QStringLiteral("config/随便.toml")) &&
                  !becomesCandidate(QStringLiteral("saves/世界/level.dat")) &&
                  !becomesCandidate(QStringLiteral("options.txt")) &&
                  !becomesCandidate(QStringLiteral("mods.txt")) &&
                  !becomesCandidate(QStringLiteral("随便.jar")) &&
                  !becomesCandidate(QStringLiteral("mods/笔记.txt")),
              "V5e 候选：config / 存档 / 根目录下的 jar / 不在资源目录里的 txt 都不问接口");
    }

    // --- V5f. 导出：实例目录里哪些文件进包（排除表 + 递归枚举） ---------------
    //
    // 这一节盯的是"打包时会不会把不该给别人的东西发出去"。最有分量的一条是**凭据**：
    // 别的启动器把账号放在实例根底下（`launcher_accounts.json` 那一串），打包是最容易
    // 把登录信息泄出去的一条路。另有一条是**根目录下的同一个名字不算数**（`mods/icon.png`
    // 是 mod 自己的资源，不能因为撞名就被排掉）。
    {
        const QString tree = sandbox + "/export-tree/我的实例";
        QDir(tree).removeRecursively();
        QDir().mkpath(tree);
        // 该进包的
        writeFileAt(tree + "/mods/sodium.jar", QByteArrayLiteral("假 mod"));
        writeFileAt(tree + "/mods/sub/nested.jar", QByteArrayLiteral("嵌套的"));
        writeFileAt(tree + "/config/模组配置.toml", QByteArrayLiteral("a=1"));
        writeFileAt(tree + "/options.txt", QByteArrayLiteral("fov:70"));
        writeFileAt(tree + "/mods/icon.png", QByteArrayLiteral("mod 自己的图标"));
        writeFileAt(tree + "/mods/logs/我的.log", QByteArrayLiteral("mod 自己的日志"));
        writeFileAt(tree + "/.packignore", QByteArrayLiteral("saves\n"));
        // 不该进包的：启动器自己 / 别的启动器 / 系统的垃圾 / 运行时文件
        writeFileAt(tree + "/wtfml.meta", QByteArrayLiteral("{\"instanceId\":\"x\"}"));
        writeFileAt(tree + "/icon.png", QByteArrayLiteral("启动器缓存的那张图"));
        writeFileAt(tree + "/我的实例.jar", QByteArrayLiteral("这个实例的版本 jar"));
        writeFileAt(tree + "/我的实例.json", QByteArrayLiteral("{}"));
        writeFileAt(tree + "/launcher_accounts.json", QByteArrayLiteral("{\"accounts\":{}}"));
        writeFileAt(tree + "/launcher_msa_credentials.bin", QByteArrayLiteral("二进制"));
        writeFileAt(tree + "/usernamecache.json", QByteArrayLiteral("{}"));
        writeFileAt(tree + "/.DS_Store", QByteArrayLiteral("junk"));
        writeFileAt(tree + "/.hmcl/账号.json", QByteArrayLiteral("{\"账户\""));
        writeFileAt(tree + "/logs/最新.log", QByteArrayLiteral("日志"));
        writeFileAt(tree + "/crash-reports/崩了.txt", QByteArrayLiteral("崩溃"));
        writeFileAt(tree + "/natives/glfw.dll", QByteArrayLiteral("dll"));
        writeFileAt(tree + "/libraries/某个库.jar", QByteArrayLiteral("库"));
        writeFileAt(tree + "/.mixin.out/调试.txt", QByteArrayLiteral("调试"));
        writeFileAt(tree + "/.fabric/remapped.jar", QByteArrayLiteral("重映射过的副本"));
        writeFileAt(tree + "/saves/我的世界/level.dat", QByteArrayLiteral("存档"));
        writeFileAt(tree + "/screenshots/一张图.png", QByteArrayLiteral("截图"));

        // 先单独钉排除表（纯函数，能一条一条说清楚为什么）
        const auto reasonOf = [](const QString &path, const ModpackExport::IncludeOptions &opt) {
            return ModpackExport::instanceExclusionReason(path, QStringLiteral("我的实例"), opt);
        };
        const ModpackExport::IncludeOptions defaults;
        check(!reasonOf(QStringLiteral("launcher_accounts.json"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral("launcher_msa_credentials.bin"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral("usernamecache.json"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral(".hmcl/账号.json"), defaults).isEmpty(),
              "V5f 凭据与别的启动器的账号状态一条都不进包");
        check(!reasonOf(QStringLiteral("wtfml.meta"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral("icon.png"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral("我的实例.jar"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral("我的实例.json"), defaults).isEmpty(),
              "V5f 启动器自己的状态与这个实例的版本文件不进包");
        check(!reasonOf(QStringLiteral("logs/最新.log"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral("crash-reports/x.txt"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral("natives/glfw.dll"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral("libraries/某个库.jar"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral(".mixin.out/x.txt"), defaults).isEmpty() &&
                  !reasonOf(QStringLiteral(".fabric/remapped.jar"), defaults).isEmpty(),
              "V5f 日志 / 崩溃报告 / natives / libraries / 缓存目录都不进包");
        check(reasonOf(QStringLiteral("mods/logs/我的.log"), defaults).isEmpty() &&
                  reasonOf(QStringLiteral("mods/icon.png"), defaults).isEmpty() &&
                  reasonOf(QStringLiteral("mods/sodium.jar"), defaults).isEmpty(),
              "V5f 排除表只按**顶层**那一段判：`mods/logs/…`、`mods/icon.png` 是 mod 自己的东西");
        // 存档与截图：默认不进（PCL 那套默认），勾上就进。
        ModpackExport::IncludeOptions withSaves = defaults;
        withSaves.saves = true;
        withSaves.screenshots = true;
        check(!reasonOf(QStringLiteral("saves/我的世界/level.dat"), defaults).isEmpty() &&
                  reasonOf(QStringLiteral("saves/我的世界/level.dat"), withSaves).isEmpty() &&
                  !reasonOf(QStringLiteral("screenshots/一张图.png"), defaults).isEmpty() &&
                  reasonOf(QStringLiteral("screenshots/一张图.png"), withSaves).isEmpty(),
              "V5f 存档与截图默认不进包，勾上之后进");

        // 再整棵走一遍
        const ModpackExport::CollectResult collected =
            ModpackExport::collectInstanceFiles(tree, defaults);
        QStringList paths;
        for (const ModpackExport::InstanceFile &file : collected.files) {
            paths.append(file.path);
        }
        check(collected.problem.isEmpty(), "V5f 实例目录枚举没报错", collected.problem);
        // 进包的**恰好**是这五条。写成全等（不是"包含"）是有意的：多出来一条
        // （比如哪个不该进包的漏了）和少一条都该红。
        const QStringList expected = {QStringLiteral("config/模组配置.toml"),
                                      QStringLiteral("mods/icon.png"),
                                      QStringLiteral("mods/logs/我的.log"),
                                      QStringLiteral("mods/sodium.jar"),
                                      QStringLiteral("mods/sub/nested.jar"),
                                      QStringLiteral("options.txt")};
        // 期望值本身就是排好序的，所以这一条同时钉住「内容对」和「顺序是排过的」。
        check(paths == expected, "V5f 枚举出来的正好是这六条，且按路径排过序（多一条少一条都算错）",
              paths.join(QLatin1Char(',')));
        // 再跑一遍：两次导出的条目顺序必须一样（包的字节内容不可复现无所谓，
        // 但"哪些文件、什么顺序"得定死，不然出问题没法对）。
        const ModpackExport::CollectResult again =
            ModpackExport::collectInstanceFiles(tree, defaults);
        QStringList againPaths;
        for (const ModpackExport::InstanceFile &file : again.files) {
            againPaths.append(file.path);
        }
        check(againPaths == paths, "V5f 同一个实例枚举两次，结果一字不差");
        check(collected.skippedDirs.contains(QStringLiteral("logs")) &&
                  collected.skippedDirs.contains(QStringLiteral("saves")) &&
                  collected.skippedDirs.contains(QStringLiteral(".hmcl")) &&
                  !collected.skippedDirs.contains(QStringLiteral("mods")) &&
                  !collected.skippedDirs.contains(QStringLiteral("config")),
              "V5f 被排掉的顶层目录也记下来了（界面上要照实说哪些没进包）",
              collected.skippedDirs.join(QLatin1Char(',')));
        // ★ 2026-09-27：这个数从 **9 变成 18**。从前它只数"被排除表直接拦下来的文件"，
        //   而被排掉的**目录里面**的东西一个都没数 —— 可 logs / crash-reports / natives /
        //   libraries / saves / screenshots 这一档全是整个目录被排掉，于是报告里那句
        //   「没进包：存档、截图（共 N 个文件）」几乎永远是「共 0 个文件」。这个数的意义
        //   就是让用户知道"少了多少东西"，所以两半都要数：9（顶层文件）+ 9（被排掉的
        //   目录里的，见下面那一条）。真实实例里 saves/ 一个目录就是三百个文件。
        check(collected.skippedFileCount == 18,
              "V5f 被排掉的文件个数 = 顶层文件 9（启动器状态 2 + 版本文件 2 + 凭据 2 + "
              "账号缓存 1 + 打包设置 1 + 系统垃圾 1）+ 被排掉的目录里的 9",
              QString::number(collected.skippedFileCount));
        // 两半分开钉一次：把存档与截图勾上，那两个目录就不被排掉了 ⇒ 它们里面各那一个
        // 文件（`saves/我的世界/level.dat`、`screenshots/一张图.png`）也不该再数进去 ——
        // 18 - 2 = 16。这一条钉的是"目录里那些确实是被目录那一条带走的"，而不是碰巧
        // 从别处凑出来的 18。顺带覆盖**递归**：level.dat 在一个子目录里（我的世界/）。
        const ModpackExport::CollectResult withSavesCollected =
            ModpackExport::collectInstanceFiles(tree, withSaves);
        check(withSavesCollected.skippedFileCount == 16,
              "V5f 勾上存档与截图之后，被排掉的个数正好少那两个目录里的文件（18 - 2）",
              QString::number(withSavesCollected.skippedFileCount));
        // 目录不存在时是「读不了」（problem 有话说），**不是**「这个实例是空的」——
        // 后者会导出一个空包，用户拿到手才发现什么都没有。
        const ModpackExport::CollectResult missing =
            ModpackExport::collectInstanceFiles(sandbox + "/export-tree/没有这个目录", defaults);
        check(!missing.problem.isEmpty() && missing.files.isEmpty(),
              "V5f 实例目录不存在时如实报「读不了」，而不是当成空实例", missing.problem);
        QDir(sandbox + "/export-tree").removeRecursively();
    }

    // --- V5g. 导出：一个文件读两趟，三个哈希一起出来 -------------------------
    //
    // 这一节压的是 hashFile 与 curseForgeFingerprint 那两份代码算出来的指纹**必须一样**
    // （它们是两份实现），以及 sha1/sha512 与 Qt 自己的结果一致。
    {
        const QString work = sandbox + "/export-hash";
        QDir(work).removeRecursively();
        QDir().mkpath(work);
        QByteArray content;  // 里面撒上空白，让"剔空白"这条真的起作用
        for (int i = 0; i < 5000; ++i) {
            content.append(static_cast<char>((i * 53 + 7) & 0xFF));
            if (i % 11 == 0) {
                content.append(QByteArrayLiteral(" \t"));
            }
        }
        const QString path = work + "/某个文件.bin";
        writeFileAt(path, content);

        ModpackExport::FileHashes hashes;
        QString hashError;
        const bool hashOk = ModpackExport::hashFile(path, true, &hashes, &hashError);
        check(hashOk, "V5g hashFile 算得出来", hashError);
        check(hashes.sha1 == QString::fromLatin1(
                                 QCryptographicHash::hash(content, QCryptographicHash::Sha1)
                                     .toHex()),
              "V5g sha1 与 Qt 算的一致（喂了两遍的话这里就对不上）");
        check(hashes.sha512 == QString::fromLatin1(
                                   QCryptographicHash::hash(content, QCryptographicHash::Sha512)
                                       .toHex()),
              "V5g sha512 与 Qt 算的一致");
        quint32 standalone = 0;
        QString fpError;
        const bool fpOk = ModpackExport::curseForgeFingerprint(path, &standalone, &fpError);
        check(fpOk && hashes.fingerprintOk && hashes.fingerprint == standalone,
              "V5g hashFile 里的指纹与 curseForgeFingerprint 一致（两份代码同一份算法）",
              fpOk ? QStringLiteral("%1 / %2").arg(hashes.fingerprint).arg(standalone) : fpError);
        // 只算 sha1/sha512 那一档（Modrinth 那条路）：指纹该是"没算"，不是"算出来个 0"。
        ModpackExport::FileHashes shaOnly;
        check(ModpackExport::hashFile(path, false, &shaOnly, &hashError) &&
                  shaOnly.sha1 == hashes.sha1 && !shaOnly.fingerprintOk &&
                  shaOnly.fingerprint == 0,
              "V5g 不要指纹时不碰指纹（fingerprintOk 是假，不是给个 0 冒充）");
        QDir(work).removeRecursively();
    }

    // --- V5h. 导出：反查那一发的形状与回复的读法 -----------------------------
    //
    // 两个夹具都是**真接口录下来的回复**（`meta/modrinth-version-files.json` 是拿 JEI 的
    // sha1 问 `/v2/version_files` 的原文，`meta/curseforge-fingerprints.json` 是拿同一个
    // 文件的指纹问 `/v1/fingerprints` 的原文）。所以这一节验的是"真东西读得懂"，
    // 不是"我们自己造的假回复读得懂"。
    {
        // 请求体：形状写错的话接口回 400，而 400 的正文只有一句 `{"error":"…"}`，
        // 看着和"这个包坏了"一模一样 —— 所以这两发的形状得钉住。
        const QByteArray modrinthBody = ModpackExport::modrinthVersionFilesRequestBody(
            {QStringLiteral("c19b8bfb43a753ad8c27612d516ce61c58b0d2e6")});
        const QJsonObject modrinthJson = QJsonDocument::fromJson(modrinthBody).object();
        check(modrinthJson.value(QStringLiteral("algorithm")).toString() ==
                      QStringLiteral("sha1") &&
                  modrinthJson.value(QStringLiteral("hashes")).toArray().size() == 1 &&
                  modrinthJson.value(QStringLiteral("hashes")).toArray().at(0).toString() ==
                      QStringLiteral("c19b8bfb43a753ad8c27612d516ce61c58b0d2e6"),
              "V5h Modrinth 的请求体是 {\"hashes\":[…],\"algorithm\":\"sha1\"}",
              QString::fromUtf8(modrinthBody));
        check(ModpackExport::modrinthVersionFilesRequestBody({}).isEmpty(),
              "V5h 空表不拼请求体（那一发不该发出去）");

        const QByteArray cfBody = ModpackExport::curseForgeFingerprintsRequestBody({3309664856u});
        const QJsonArray cfList =
            QJsonDocument::fromJson(cfBody).object().value(QStringLiteral("fingerprints")).toArray();
        // ★ 2026-09-27 改：从前这一条钉的是**字符串**，还附了一句"发成数字那边回 400" ——
        //   那句话把因果说反了，钉住的正是那个洞。实测（拿用户真实例里的文件问的真网络）：
        //   `{"fingerprints":["3816865428"]}` → 400（`invalid type: string … expected i64`）、
        //   `{"fingerprints":[3816865428]}` → 200。所以现在钉的是**数字**。
        check(cfList.size() == 1 && cfList.at(0).isDouble() &&
                  static_cast<quint32>(cfList.at(0).toDouble()) == 3309664856u,
              "★★ V5h CurseForge 的请求体里指纹是**数学意义上的数字**（int64）—— 发成字符串"
              "那一支整个不回话：字节看着没问题、只是那几格没图标，唯一会说话的是 400 的正文",
              QString::fromUtf8(cfBody));
        check(ModpackExport::curseForgeFingerprintsRequestBody({}).isEmpty(),
              "V5h 空表不拼请求体");

        // 读真回复：Modrinth 那一份
        const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";
        QString modrinthSha1;
        QString curseForgeSha1;
        QFile modrinthFile(metaDir + "/modrinth-version-files.json");
        const bool haveModrinthFixture = modrinthFile.open(QIODevice::ReadOnly);
        check(haveModrinthFixture,
              "V5h 读到了 Modrinth 真回复的夹具（meta/modrinth-version-files.json）");
        if (haveModrinthFixture) {
            QString parseProblem;
            const QHash<QString, ModpackExport::ModrinthHit> hits =
                ModpackExport::parseModrinthVersionFiles(modrinthFile.readAll(), &parseProblem);
            modrinthFile.close();
            const QString jeiSha1 = QStringLiteral("c19b8bfb43a753ad8c27612d516ce61c58b0d2e6");
            check(parseProblem.isEmpty() && hits.contains(jeiSha1),
                  "V5h Modrinth 真回复读得懂，且键就是**我们发过去的那个 sha1**", parseProblem);
            if (hits.contains(jeiSha1)) {
                const ModpackExport::ModrinthHit hit = hits.value(jeiSha1);
                modrinthSha1 = hit.sha1;
                check(hit.sha1 == jeiSha1 && hit.sha512.size() == 128 &&
                          hit.url.startsWith(QStringLiteral("https://cdn.modrinth.com/")) &&
                          hit.size == 2338315 && hit.filename.endsWith(QStringLiteral(".jar")),
                      "V5h 命中的那一条：sha1/sha512/地址/字节数/文件名都对得上",
                      hit.url);
                check(hit.projectId == QStringLiteral("u6dRKJwZ") &&
                          hit.versionNumber == QStringLiteral("31.7.0.37"),
                      "V5h 项目号与版本号（只为了在结果里报数）",
                      hit.projectId + QLatin1Char('|') + hit.versionNumber);
            }
            // 认不出来的哈希不该凭空冒出来
            check(hits.size() == 1, "V5h 回复里有几条就几条（不凭空造）",
                  QString::number(hits.size()));
        }
        // 读真回复：CurseForge 那一份
        QFile cfFile(metaDir + "/curseforge-fingerprints.json");
        const bool haveCfFixture = cfFile.open(QIODevice::ReadOnly);
        check(haveCfFixture,
              "V5h 读到了 CurseForge 真回复的夹具（meta/curseforge-fingerprints.json）");
        if (haveCfFixture) {
            QString parseProblem;
            const QHash<quint32, ModpackExport::CurseForgeHit> hits =
                ModpackExport::parseCurseForgeFingerprints(cfFile.readAll(), &parseProblem);
            cfFile.close();
            check(parseProblem.isEmpty() && hits.contains(3309664856u),
                  "V5h CurseForge 真回复读得懂，键是那个文件自己的 fileFingerprint", parseProblem);
            if (hits.contains(3309664856u)) {
                const ModpackExport::CurseForgeHit hit = hits.value(3309664856u);
                curseForgeSha1 = hit.sha1;
                // 项目号取的是 file.modId、文件号取 file.id —— **不是**外面那一层 `id`
                // （那是项目号，按它归档会和文件号混起来）。
                check(hit.projectId == 238222 && hit.fileId == 8971390 && hit.available &&
                          hit.size == 2338315,
                      "V5h 命中的那一条：项目号/文件号/isAvailable/字节数都对得上",
                      QStringLiteral("%1/%2").arg(hit.projectId).arg(hit.fileId));
                check(hit.fileName == QStringLiteral("jei-26.3-neoforge-31.7.0.37.jar") &&
                          hit.downloadUrl.startsWith(QStringLiteral("https://")),
                      "V5h 文件名与下载地址", hit.downloadUrl);
            }
        }
        // 两个夹具问的是**同一个文件**（JEI 那一份 jar），所以两条路认出来的 sha1 必须一样 ——
        // 这正好也说明两个解析器取的是同一个东西，不是各读各的字段。
        check(!modrinthSha1.isEmpty() && modrinthSha1 == curseForgeSha1,
              "V5h 两条反查路认出来的 sha1 一致（同一份文件）",
              modrinthSha1 + QLatin1Char('/') + curseForgeSha1);
        // 空回复 / 坏回复 / 接口报错：三档都得是「能分辨」的，不能都退化成「没找到」。
        QString problem;
        check(ModpackExport::parseModrinthVersionFiles(QByteArrayLiteral("{}"), &problem).isEmpty() &&
                  problem.isEmpty(),
              "V5h 空 map 是「一个都没认出来」，不是「读不懂」（问题要能分开）", problem);
        check(ModpackExport::parseModrinthVersionFiles(QByteArrayLiteral("不是 json"), &problem)
                      .isEmpty() &&
                  !problem.isEmpty(),
              "V5h 读不懂的回复要有一句话", problem);
        check(ModpackExport::parseCurseForgeFingerprints(
                  QByteArrayLiteral("{\"error\":\"Invalid API key\"}"), &problem)
                      .isEmpty() &&
                  problem.contains(QStringLiteral("Invalid API key")),
              "V5h 接口报错时把那句话原样带出来（别换成我们自己的猜测）", problem);
        check(ModpackExport::parseModrinthVersionFiles(QByteArrayLiteral("{\"不是哈希\":{}}"), &problem)
                      .isEmpty(),
              "V5h 键不是哈希时一条都不认（不猜）");
        check(ModpackExport::isPoisonFingerprint(811513880u) &&
                  !ModpackExport::isPoisonFingerprint(3309664856u),
              "V5h 毒指纹 811513880 认得出来（接口偶尔把它当匹配上了，见到当没找到）");
        // 那一刀切在**解析**这一层：回复里那条记录自己的 `fileFingerprint` 是毒指纹时，
        // 它不代表任何一个具体文件 —— 键就是这个值，收进表里等于给某个"恰好算出这个
        // 指纹"的文件安排了一个假匹配。
        const QByteArray poisonReply = QByteArrayLiteral(
            "{\"data\":{\"exactMatches\":[{\"id\":238222,\"file\":{\"id\":8971390,\"modId\":238222,"
            "\"fileFingerprint\":811513880,\"isAvailable\":true,\"fileName\":\"x.jar\","
            "\"downloadUrl\":\"https://example.com/x.jar\",\"fileLength\":10,\"hashes\":[]}}],"
            "\"unmatchedFingerprints\":[],\"exactFingerprints\":[]}}");
        const QHash<quint32, ModpackExport::CurseForgeHit> poisonHits =
            ModpackExport::parseCurseForgeFingerprints(poisonReply, nullptr);
        check(poisonHits.isEmpty(),
              "V5h 毒指纹那条记录**不进表**（它不是「我们发过去的某个指纹」）",
              QString::number(poisonHits.size()));
    }

    // --- V5i. 导出：枚举 → 算哈希 → 反查 → 拼清单 这一整趟 --------------------
    //
    // 反查那一发是**注入进来的**（产品里是 HttpClient，这里是假的），所以整趟离线可跑。
    // 这里要钉的三句话：①认出来的进清单、不进 overrides；②认不出来的一个不丢、
    // 全在 overrides 里；③反查没成**不是错误**（照旧导得出包，只是全进 overrides）。
    {
        const QString tree = sandbox + "/export-plan/我的实例";
        QDir(tree).removeRecursively();
        QDir().mkpath(tree);
        const QByteArray bytesMatched = QByteArrayLiteral("AAA 认得出");
        const QByteArray bytesUnknown = QByteArrayLiteral("BBB 认不出");
        writeFileAt(tree + "/mods/认得出来.jar", bytesMatched);
        writeFileAt(tree + "/mods/认不出来.jar", bytesUnknown);
        writeFileAt(tree + "/config/配置.toml", QByteArrayLiteral("a=1"));
        writeFileAt(tree + "/options.txt", QByteArrayLiteral("fov:70"));
        writeFileAt(tree + "/logs/不该进包.log", QByteArrayLiteral("日志"));
        writeFileAt(tree + "/我的实例.jar", QByteArrayLiteral("版本文件"));

        const auto sha1OfBytes = [](const QByteArray &bytes) {
            QCryptographicHash hash(QCryptographicHash::Sha1);
            hash.addData(QByteArrayView(bytes));
            return QString::fromLatin1(hash.result().toHex());
        };
        const auto sha512OfBytes = [](const QByteArray &bytes) {
            QCryptographicHash hash(QCryptographicHash::Sha512);
            hash.addData(QByteArrayView(bytes));
            return QString::fromLatin1(hash.result().toHex());
        };
        const QString sha1Matched = sha1OfBytes(bytesMatched);
        const QString sha1Unknown = sha1OfBytes(bytesUnknown);

        ModpackExport::ExportRequest request;
        request.format = ModpackExport::Format::Modrinth;
        request.instanceDir = tree;
        request.name = QStringLiteral("我的整合包");
        request.version = QStringLiteral("1.2.3");
        request.summary = QStringLiteral("一句话简介");
        request.gameVersion = QStringLiteral("1.21.1");
        request.loaderKey = ModpackImport::fabricLoaderKey();
        request.loaderVersion = QStringLiteral("0.16.14");

        QStringList askedSha1;
        int queryCalls = 0;
        const ModpackExport::ModrinthQuery fakeModrinth =
            [&](const QStringList &sha1s, QHash<QString, ModpackExport::ModrinthHit> *out,
                QString *problemOut) {
                ++queryCalls;
                askedSha1 = sha1s;
                if (problemOut != nullptr) {
                    problemOut->clear();
                }
                ModpackExport::ModrinthHit hit;
                hit.projectId = QStringLiteral("u6dRKJwZ");
                hit.versionNumber = QStringLiteral("1.2.3");
                hit.filename = QStringLiteral("认得出来.jar");
                hit.sha1 = sha1Matched;
                hit.sha512 = sha512OfBytes(bytesMatched);
                hit.url = QStringLiteral(
                    "https://cdn.modrinth.com/data/u6dRKJwZ/versions/abc/认得出来.jar");
                hit.size = bytesMatched.size();
                hit.environment = QStringLiteral("client_only");
                out->insert(sha1Matched, hit);
                return true;
            };

        // 进度：记下每一次（done, total, 当前那个文件）。最后一次是反查那一发
        // （没有具体文件，`current` 是空串）——界面靠它切到"正在问接口"。
        QList<QString> progressLines;
        int lastDone = -1;
        int lastTotal = -1;
        const ModpackExport::ExportProgress progress = [&](int done, int total,
                                                          const QString &current) {
            lastDone = done;
            lastTotal = total;
            progressLines.append(QStringLiteral("%1/%2 %3").arg(done).arg(total).arg(current));
        };

        const ModpackExport::ExportPlan plan =
            ModpackExport::buildExportPlan(request, fakeModrinth, ModpackExport::CurseForgeQuery(),
                                          progress);
        check(plan.problem.isEmpty() && !plan.cancelled && !plan.lookupFailed,
              "V5i 整趟跑完没有停下来（枚举/哈希/反查都成了）", plan.problem);
        check(queryCalls == 1, "V5i 反查是**一发**（不是每个文件一发）",
              QString::number(queryCalls));
        check(plan.queried == 2, "V5i 问的是那两个资源文件（config/options.txt 不该去问）",
              QString::number(plan.queried));
        QStringList askedSorted = askedSha1;
        askedSorted.sort();
        QStringList expectedAsked = {sha1Matched, sha1Unknown};
        expectedAsked.sort();
        check(askedSorted == expectedAsked,
              "V5i 发过去的就是本地算出来的**那两个 sha1**（一条不多一条不少）",
              askedSorted.join(QLatin1Char(',')));
        check(plan.matched == 1 && plan.notDistributable == 0,
              "V5i 认出来一条", QString::number(plan.matched));
        check(lastDone == lastTotal && lastTotal == 2,
              "V5i 进度走到了头（total 就是要算哈希的文件数）",
              QStringLiteral("%1/%2").arg(lastDone).arg(lastTotal));
        check(!progressLines.isEmpty() && progressLines.last().endsWith(QLatin1Char(' ')),
              "V5i 最后一发进度没有文件名（那是「正在问接口」那一档）",
              progressLines.join(QLatin1Char('|')));

        // ① 认出来的进清单，而且**不在** overrides 里
        check(plan.spec.files.size() == 1, "V5i 清单里就那一条",
              QString::number(plan.spec.files.size()));
        if (plan.spec.files.size() == 1) {
            const ModpackExport::MatchedFile &matched = plan.spec.files.first();
            check(matched.path == QStringLiteral("mods/认得出来.jar") &&
                      matched.sha1 == sha1Matched &&
                      matched.sha512 == sha512OfBytes(bytesMatched) &&
                      matched.size == bytesMatched.size() &&
                      matched.urls.size() == 1,
                  "V5i 认出来的那条：路径 / sha1 / sha512 / 字节数 / 地址都对得上",
                  matched.path);
            check(matched.envClient == QStringLiteral("required") &&
                      matched.envServer == QStringLiteral("unsupported"),
                  "V5i 接口说 `client_only` 时写 env（只写这一种，见 applyEnvironment）",
                  matched.envClient + QLatin1Char('|') + matched.envServer);
        }
        QStringList overridePaths;
        for (const ModpackExport::InstanceFile &file : plan.overrides) {
            overridePaths.append(file.path);
        }
        const QStringList expectedOverrides = {QStringLiteral("config/配置.toml"),
                                               QStringLiteral("mods/认不出来.jar"),
                                               QStringLiteral("options.txt")};
        check(overridePaths == expectedOverrides,
              "V5i 认不出来的**一个不丢**、全在 overrides 里，且按路径排过序（认出来的不在里面）",
              overridePaths.join(QLatin1Char(',')));
        check(!plan.collect.skippedDirs.isEmpty() &&
                  plan.collect.skippedDirs.contains(QStringLiteral("logs")),
              "V5i 被排掉的目录照实带出来（界面上要说哪些没进包）");

        // 清单往返：我们自己写得出来，自己也得读得回来
        const ModpackImport::Result back =
            ModpackImport::parseModrinthIndex(ModpackExport::buildModrinthIndex(plan.spec));
        check(back.ok && back.pack.fileCount() == 1 &&
                  back.pack.files.first().path == QStringLiteral("mods/认得出来.jar"),
              "V5i 这一趟的产物自己的解析器读得回来（导出/导入是同一件事的两个方向）",
              back.problem);
        check(ModpackExport::reimportable(plan.spec),
              "V5i 有清单条目 ⇒ 这是个我们自己装得回来的包");

        // ② 反查没成：**不是错误**，但一个文件都不许丢 —— 那些"本来能认出来"的现在
        //    也只能进 overrides（断网也能出包，这是 PCL 那套的取舍）。
        const ModpackExport::ModrinthQuery deadQuery =
            [](const QStringList &, QHash<QString, ModpackExport::ModrinthHit> *,
               QString *problemOut) {
                if (problemOut != nullptr) {
                    *problemOut = QStringLiteral("连不上 Modrinth。");
                }
                return false;
            };
        const ModpackExport::ExportPlan offline =
            ModpackExport::buildExportPlan(request, deadQuery, ModpackExport::CurseForgeQuery());
        check(offline.lookupFailed && offline.lookupProblem == QStringLiteral("连不上 Modrinth。") &&
                  offline.problem.isEmpty(),
              "V5i 反查没成如实报出来，但**不算错误**（清单/overrides 照旧拼得出来）",
              offline.lookupProblem);
        QStringList offlineOverrides;
        for (const ModpackExport::InstanceFile &file : offline.overrides) {
            offlineOverrides.append(file.path);
        }
        check(offline.matched == 0 && offline.spec.files.isEmpty() &&
                  offlineOverrides.contains(QStringLiteral("mods/认得出来.jar")) &&
                  offlineOverrides.size() == 4,
              "V5i 反查没成时那份「本来认得出」的文件也进 overrides（一份都不丢）",
              offlineOverrides.join(QLatin1Char(',')));
        check(!ModpackExport::reimportable(offline.spec),
              "V5i 反查没成之后清单是空的 ⇒ 调用点必须拿 reimportable() 拦一下"
              "（我们自己的解析器拒收空清单：ModpackImport.cpp:379）");

        // ③ 取消：一个文件都还没读就停 —— 反查那一发**不许发出去**，清单一条都没有。
        //    这时候整份 plan 作废（`overrides` 里可能有半截东西，见 .hpp 那句），
        //    所以这里不去数 overrides，只钉"叫停之后收手了没有"。
        int cancelQueryCalls = 0;
        const ModpackExport::ModrinthQuery countingQuery =
            [&cancelQueryCalls](const QStringList &, QHash<QString, ModpackExport::ModrinthHit> *,
                                QString *) {
                ++cancelQueryCalls;
                return true;
            };
        const ModpackExport::ExportPlan stopped =
            ModpackExport::buildExportPlan(request, countingQuery, ModpackExport::CurseForgeQuery(),
                                           ModpackExport::ExportProgress(),
                                           []() { return true; });
        check(stopped.cancelled && stopped.spec.files.isEmpty() && stopped.spec.refs.isEmpty() &&
                  stopped.queried == 0 && cancelQueryCalls == 0 && !stopped.lookupFailed,
              "V5i 用户叫停之后立刻收手（一个哈希都不算、反查不发、清单是空的），"
              "且这不是「反查失败」那一档",
              QStringLiteral("%1 / 问了 %2 个").arg(cancelQueryCalls).arg(stopped.queried));

        QDir(sandbox + "/export-plan").removeRecursively();
    }

    // --- V5j. 导出：CurseForge 那一条路（号 + 关分发 + 毒指纹） ---------------
    {
        const QString tree = sandbox + "/export-cf/我的实例";
        QDir(tree).removeRecursively();
        QDir().mkpath(tree);
        const QByteArray bytesOk = QByteArrayLiteral("CCC 能下");
        const QByteArray bytesClosed = QByteArrayLiteral("DDD 关了分发");
        writeFileAt(tree + "/mods/能下的.jar", bytesOk);
        writeFileAt(tree + "/mods/关了分发的.jar", bytesClosed);

        quint32 fpOk = 0;
        quint32 fpClosed = 0;
        QString hashProblem;
        check(ModpackExport::curseForgeFingerprint(tree + "/mods/能下的.jar", &fpOk, &hashProblem) &&
                  ModpackExport::curseForgeFingerprint(tree + "/mods/关了分发的.jar", &fpClosed,
                                                       &hashProblem),
              "V5j 两个文件的指纹都算出来了", hashProblem);

        ModpackExport::ExportRequest request;
        request.format = ModpackExport::Format::CurseForge;
        request.instanceDir = tree;
        request.name = QStringLiteral("我的整合包");
        request.version = QStringLiteral("1.2.3");
        request.author = QStringLiteral("某人");
        request.gameVersion = QStringLiteral("1.21.1");
        request.loaderKey = ModpackImport::neoforgeLoaderKey();
        request.loaderVersion = QStringLiteral("21.1.210");

        int queryCalls = 0;
        QList<quint32> askedFingerprints;
        const ModpackExport::CurseForgeQuery fakeCurseForge =
            [&](const QList<quint32> &fingerprints, QHash<quint32, ModpackExport::CurseForgeHit> *out,
                QString *problemOut) {
                ++queryCalls;
                askedFingerprints = fingerprints;
                if (problemOut != nullptr) {
                    problemOut->clear();
                }
                ModpackExport::CurseForgeHit ok;
                ok.projectId = 394468;
                ok.fileId = 5123456;
                ok.available = true;
                ok.fileName = QStringLiteral("能下的.jar");
                ok.downloadUrl = QStringLiteral("https://edge.forgecdn.net/files/5123/456/x.jar");
                out->insert(fpOk, ok);
                ModpackExport::CurseForgeHit closed;
                closed.projectId = 238222;
                closed.fileId = 8971390;
                closed.available = false;  // 作者关了第三方分发
                // ★ 2026-09-27：**接口是明说这一句的**（回复里有 `isAvailable`，值是假）。
                //   这一位不设的话，那一份就落进"接口没说"那一档去了（见
                //   notDistributableUnknown）—— 两种来路分开报，是这一节要钉的东西之一。
                closed.availableKnown = true;
                closed.fileName = QStringLiteral("关了分发的.jar");
                out->insert(fpClosed, closed);
                return true;
            };

        const ModpackExport::ExportPlan plan = ModpackExport::buildExportPlan(
            request, ModpackExport::ModrinthQuery(), fakeCurseForge);
        check(queryCalls == 1 && askedFingerprints.size() == 2,
              "V5j CurseForge 也是一发问完（指纹按本地算出来的那两个）",
              QString::number(askedFingerprints.size()));
        check(plan.matched == 1 && plan.notDistributable == 1,
              "V5j 认出来一条、另一条「认出来了但作者关了分发」（分开报数）",
              QStringLiteral("%1 / %2").arg(plan.matched).arg(plan.notDistributable));
        check(plan.spec.refs.size() == 1 && plan.spec.refs.first().projectId == 394468 &&
                  plan.spec.refs.first().fileId == 5123456,
              "V5j 清单里只有两个号（CF 那边没有文件名/地址/哈希）");
        QStringList cfOverrides;
        for (const ModpackExport::InstanceFile &file : plan.overrides) {
            cfOverrides.append(file.path);
        }
        check(cfOverrides == QStringList{QStringLiteral("mods/关了分发的.jar")},
              "V5j 关了分发的那份退回 overrides（写进清单等于给出一个装不上的包）",
              cfOverrides.join(QLatin1Char(',')));
        // 往返：号是那两个号，加载器那一行也是 CF 认得的那一行
        const ModpackImport::Result back = ModpackImport::parseCurseForgeManifest(
            ModpackExport::buildCurseForgeManifest(plan.spec));
        check(back.ok && back.pack.pendingRefs.size() == 1 &&
                  back.pack.pendingRefs.first().projectId == 394468 &&
                  back.pack.pendingRefs.first().fileId == 5123456 &&
                  back.pack.loaderKey == ModpackImport::neoforgeLoaderKey() &&
                  back.pack.loaderVersion == QStringLiteral("21.1.210"),
              "V5j CF 清单往返：号与加载器那一行都对得上", back.problem);
        check(ModpackExport::reimportable(plan.spec),
              "V5j 有 refs ⇒ 我们自己装得回来");

        QDir(sandbox + "/export-cf").removeRecursively();
    }

    // --- V5s. 导出：名字长到清单写不下的那一条，必须退回 overrides ---------------
    //
    // 读侧对清单里**每一条**路径都跑 isSafeRelativePath()（ModpackImport.cpp:313），
    // 不过就是**整包拒绝**（"所以整个包都没有导入"）。所以产出这一侧不许写出那样一条。
    // 从前写得出：实例里有一个嵌套很深、拼起来超过 240 个字符的文件时，我们导出的包
    // 连自己都装不回来，而且**当场看不出来**（清单写得出来、zip 打得出来）。
    // 退回 overrides 之后文件一个不少 —— 那一条路不经过这个判据。
    {
        const QString tree = sandbox + "/export-long/我的实例";
        QDir(tree).removeRecursively();
        QDir().mkpath(tree);
        const QByteArray bytesOk = QByteArrayLiteral("AAA 正常的那一个");
        const QByteArray bytesLong = QByteArrayLiteral("BBB 名字超长的那一个");
        writeFileAt(tree + "/mods/认得出来.jar", bytesOk);
        // 整条相对路径 = 5 + 120 + 1 + 120 + 1 + 6 = 253 个字符（> 240），而**每一段**
        // 都在名字允许的长度里 —— 超的是"拼起来以后"那一条，也就只有长度那一条判据拦得住
        // 它（段那几条都在 InstanceFiles::validatePathSegment 里，那里没有长度限制）。
        const QString longPath = QStringLiteral("mods/") + QString(120, QLatin1Char('x')) +
                                 QLatin1Char('/') + QString(120, QLatin1Char('y')) +
                                 QStringLiteral("/长名字.jar");
        writeFileAt(tree + QStringLiteral("/") + longPath, bytesLong);
        check(longPath.length() > 240, "V5s 造出来的那条路径真的超过 240 个字符",
              QString::number(longPath.length()));

        const auto sha1Of = [](const QByteArray &bytes) {
            QCryptographicHash hash(QCryptographicHash::Sha1);
            hash.addData(QByteArrayView(bytes));
            return QString::fromLatin1(hash.result().toHex());
        };
        const auto sha512Of = [](const QByteArray &bytes) {
            QCryptographicHash hash(QCryptographicHash::Sha512);
            hash.addData(QByteArrayView(bytes));
            return QString::fromLatin1(hash.result().toHex());
        };
        const QString sha1Ok = sha1Of(bytesOk);
        const QString sha1Long = sha1Of(bytesLong);

        ModpackExport::ExportRequest request;
        request.format = ModpackExport::Format::Modrinth;
        request.instanceDir = tree;
        request.name = QStringLiteral("我的整合包");
        request.version = QStringLiteral("1.2.3");
        request.gameVersion = QStringLiteral("1.21.1");
        request.loaderKey = ModpackImport::fabricLoaderKey();
        request.loaderVersion = QStringLiteral("0.16.14");

        // 反查**两条都答得出来** —— 这一节要钉的不是"认不认得出"，而是"认出来了也不许写"。
        const ModpackExport::ModrinthQuery query =
            [&](const QStringList &, QHash<QString, ModpackExport::ModrinthHit> *out, QString *) {
                const auto put = [&](const QString &sha1, const QString &sha512, qint64 size) {
                    ModpackExport::ModrinthHit hit;
                    hit.projectId = QStringLiteral("abcd1234");
                    hit.sha1 = sha1;
                    hit.sha512 = sha512;
                    hit.url = QStringLiteral("https://cdn.modrinth.com/data/abcd1234/versions/x/a.jar");
                    hit.size = size;
                    out->insert(sha1, hit);
                };
                put(sha1Ok, sha512Of(bytesOk), bytesOk.size());
                put(sha1Long, sha512Of(bytesLong), bytesLong.size());
                return true;
            };

        const ModpackExport::ExportPlan plan =
            ModpackExport::buildExportPlan(request, query, ModpackExport::CurseForgeQuery());
        check(plan.problem.isEmpty() && plan.lookupFailed == false,
              "V5s 整趟跑完没有停下来", plan.problem);
        check(plan.queried == 2 && plan.matched == 1 && plan.spec.files.size() == 1 &&
                  plan.spec.files.first().path == QStringLiteral("mods/认得出来.jar"),
              "V5s 只有那条短的写进清单（超长的那条**认出来了也不许写**）",
              QStringLiteral("%1 / %2").arg(plan.queried).arg(plan.matched));
        QStringList overridePaths;
        for (const ModpackExport::InstanceFile &file : plan.overrides) {
            overridePaths.append(file.path);
        }
        check(overridePaths == QStringList{longPath},
              "V5s 超长的那条退回 overrides（跟着包走，一个文件都不丢）",
              QString::number(overridePaths.size()));
        // 直接问那句判据本身（纯函数）：这两条一真一假，才是"退回去"这个动作的来路。
        ModpackExport::MatchedFile longEntry;
        longEntry.path = longPath;
        longEntry.sha1 = sha1Long;
        longEntry.sha512 = sha512Of(bytesLong);
        longEntry.urls.append(QStringLiteral("https://cdn.modrinth.com/data/abcd1234/versions/x/a.jar"));
        check(!ModpackExport::writableAsIndexFile(longEntry),
              "V5s writableAsIndexFile 说这条不能写进清单（路径过不了读侧那条判据）");
        // 反证：真写进去的话，**读侧就是整包拒绝** —— 这一条把"为什么必须退回"钉在读侧
        // 那句实现上（哪天读侧把长度那一条去掉了，这里会红，因为拒绝不再发生）。
        // NOTE: 是拿**这一趟真写出来的那份清单**改的（不是手搓一份）：手搓的话，
        //       "被拒"可能来自别的缺项（少个 dependencies 之类），那就证明不了这一条。
        //       也不能拿 badSpec 走 buildModrinthIndex —— 那个函数自己也会先问
        //       writableAsIndexFile，会把这条**跳过不写**（见它里面那段），于是清单里
        //       根本没有这一条，验的是一句空话。
        QJsonObject tampered =
            QJsonDocument::fromJson(ModpackExport::buildModrinthIndex(plan.spec)).object();
        QJsonArray tamperedFiles = tampered.value(QStringLiteral("files")).toArray();
        QJsonObject hashes;
        hashes.insert(QStringLiteral("sha1"), sha1Long);
        hashes.insert(QStringLiteral("sha512"), sha512Of(bytesLong));
        QJsonObject longEntryJson;
        longEntryJson.insert(QStringLiteral("path"), longPath);
        longEntryJson.insert(QStringLiteral("hashes"), hashes);
        longEntryJson.insert(
            QStringLiteral("downloads"),
            QJsonArray{QStringLiteral("https://cdn.modrinth.com/data/abcd1234/versions/x/a.jar")});
        tamperedFiles.append(longEntryJson);
        tampered.insert(QStringLiteral("files"), tamperedFiles);
        const ModpackImport::Result rejected = ModpackImport::parseModrinthIndex(
            QJsonDocument(tampered).toJson(QJsonDocument::Compact));
        check(!rejected.ok,
              "V5s 反证：这样的路径一旦写进清单，读侧整包拒绝（所以产出这一侧必须拦住）",
              rejected.problem);
        // 而真正导出的那一份清单读得回来（清单里没有那条超长路径）
        const ModpackImport::Result back =
            ModpackImport::parseModrinthIndex(ModpackExport::buildModrinthIndex(plan.spec));
        check(back.ok && back.pack.fileCount() == 1,
              "V5s 这一趟的产物自己的解析器读得回来", back.problem);

        QDir(sandbox + "/export-long").removeRecursively();
    }

    // --- V5t. 导出（CF）：没说能不能分发 ≠ 作者关了分发；改过名/禁用着的退回 overrides
    //
    // 三条都是"报告里那句话必须对得上盘上的事实"：
    //   ① 回复里**没有** `isAvailable` 这一项时，`toBool(false)` 也是假，但那是"接口没说"，
    //      不是"作者关了第三方分发" —— 两种分开报；
    //   ② 用户自己改过名（`改过名.jar`）或者禁用着（`禁用着的.jar.disabled`）的 mod，
    //      写进 CF 清单等于让收包的人那边落回**作者给的原名**：禁用着的那个会变成启用的。
    //      它们只有原样 copy 才留得住状态 ⇒ 退回 overrides；
    //   ③ 接口根本没接上时 `queried` 是 **0**（一个字节都没发出去），不是"本来打算问几个"。
    {
        const QString tree = sandbox + "/export-cf-state/我的实例";
        QDir(tree).removeRecursively();
        QDir().mkpath(tree);
        const QByteArray bytesOk = QByteArrayLiteral("AAA 能下的");
        const QByteArray bytesClosed = QByteArrayLiteral("BBB 作者关了分发");
        const QByteArray bytesSilent = QByteArrayLiteral("CCC 接口没提这一项");
        const QByteArray bytesOff = QByteArrayLiteral("DDD 用户禁用着的");
        const QByteArray bytesRenamed = QByteArrayLiteral("EEE 用户改过名的");
        writeFileAt(tree + "/mods/能下的.jar", bytesOk);
        writeFileAt(tree + "/mods/关了分发的.jar", bytesClosed);
        writeFileAt(tree + "/mods/没说.jar", bytesSilent);
        writeFileAt(tree + "/mods/禁用着的.jar.disabled", bytesOff);
        writeFileAt(tree + "/mods/改过名.jar", bytesRenamed);

        const auto fingerprintOf = [&](const QByteArray &bytes, const QString &name) {
            quint32 value = 0;
            QString problem;
            if (!ModpackExport::curseForgeFingerprint(tree + QStringLiteral("/mods/") + name, &value,
                                                      &problem)) {
                check(false, "V5t 指纹算得出来", problem);
            }
            return value;
        };
        const quint32 fpOk = fingerprintOf(bytesOk, QStringLiteral("能下的.jar"));
        const quint32 fpClosed = fingerprintOf(bytesClosed, QStringLiteral("关了分发的.jar"));
        const quint32 fpSilent = fingerprintOf(bytesSilent, QStringLiteral("没说.jar"));
        const quint32 fpOff = fingerprintOf(bytesOff, QStringLiteral("禁用着的.jar.disabled"));
        const quint32 fpRenamed = fingerprintOf(bytesRenamed, QStringLiteral("改过名.jar"));

        ModpackExport::ExportRequest request;
        request.format = ModpackExport::Format::CurseForge;
        request.instanceDir = tree;
        request.name = QStringLiteral("我的整合包");
        request.version = QStringLiteral("1.2.3");
        request.gameVersion = QStringLiteral("1.21.1");
        request.loaderKey = ModpackImport::forgeLoaderKey();
        request.loaderVersion = QStringLiteral("47.2.0");

        int queryCalls = 0;
        const ModpackExport::CurseForgeQuery query =
            [&](const QList<quint32> &, QHash<quint32, ModpackExport::CurseForgeHit> *out, QString *) {
                ++queryCalls;
                const auto put = [&](quint32 key, int projectId, int fileId, const QString &fileName,
                                     bool available, bool availableKnown) {
                    ModpackExport::CurseForgeHit hit;
                    hit.projectId = projectId;
                    hit.fileId = fileId;
                    hit.fileName = fileName;
                    hit.available = available;
                    hit.availableKnown = availableKnown;
                    out->insert(key, hit);
                };
                put(fpOk, 394468, 5123456, QStringLiteral("能下的.jar"), true, true);
                // 作者关了分发：接口**明说**了（有 `isAvailable`，值是假）。
                put(fpClosed, 238222, 8971390, QStringLiteral("关了分发的.jar"), false, true);
                // 接口**没说**：回复里连这一项都没有（缺席 ⇒ toBool(false) 也是假）。
                put(fpSilent, 111111, 2222222, QStringLiteral("没说.jar"), false, false);
                // 这两条接口都说能下（`fileName` = 作者给的原名），但**用户盘上的名字不一样**：
                // 一个是禁用着（后缀），一个是改过名。
                put(fpOff, 333333, 4444444, QStringLiteral("禁用着的.jar"), true, true);
                put(fpRenamed, 555555, 6666666, QStringLiteral("原来的名字.jar"), true, true);
                return true;
            };

        const ModpackExport::ExportPlan plan =
            ModpackExport::buildExportPlan(request, ModpackExport::ModrinthQuery(), query);
        check(plan.problem.isEmpty() && !plan.lookupFailed && queryCalls == 1 && plan.queried == 5,
              "V5t 一发问完五个（queried 是**发出去那些**）",
              QStringLiteral("%1 / 问了 %2").arg(queryCalls).arg(plan.queried));
        check(plan.matched == 1 && plan.notDistributable == 1 &&
                  plan.notDistributableUnknown == 1 && plan.keptLocalState == 2,
              "V5t 四种原因分开报：认出来 1 / 作者关了 1 / 接口没说 1 / 名字带状态 2",
              QStringLiteral("%1 / %2 / %3 / %4")
                  .arg(plan.matched)
                  .arg(plan.notDistributable)
                  .arg(plan.notDistributableUnknown)
                  .arg(plan.keptLocalState));
        check(plan.spec.refs.size() == 1 && plan.spec.refs.first().projectId == 394468,
              "V5t 清单里只有那条能下的（另外四种都没写）",
              QString::number(plan.spec.refs.size()));
        QStringList overridePaths;
        for (const ModpackExport::InstanceFile &file : plan.overrides) {
            overridePaths.append(file.path);
        }
        check(overridePaths.size() == 4 &&
                  overridePaths.contains(QStringLiteral("mods/关了分发的.jar")) &&
                  overridePaths.contains(QStringLiteral("mods/没说.jar")) &&
                  overridePaths.contains(QStringLiteral("mods/禁用着的.jar.disabled")) &&
                  overridePaths.contains(QStringLiteral("mods/改过名.jar")) &&
                  !overridePaths.contains(QStringLiteral("mods/能下的.jar")),
              "V5t 那四种全退回 overrides（原样带着用户那个名字），认出来的那条不在里面",
              overridePaths.join(QLatin1Char(',')));
        // ③ 接口没接上：一个字节都没发出去 ⇒ queried 必须是 0。从前它在这里就已经是 5 了
        //    （「本来打算问几个」），于是报告里那句「问过 5 个文件，认出来 0 个」会让人去查
        //    网络、查限流，而真相是这一趟根本没联网。
        const ModpackExport::ExportPlan noQuery = ModpackExport::buildExportPlan(
            request, ModpackExport::ModrinthQuery(), ModpackExport::CurseForgeQuery());
        check(noQuery.queried == 0 && noQuery.lookupFailed && noQuery.matched == 0 &&
                  noQuery.spec.refs.isEmpty() && noQuery.overrides.size() == 5,
              "V5t 接口没接上：queried 是 0（不是「本来打算问几个」），文件一个不丢",
              QStringLiteral("queried=%1 / overrides=%2")
                  .arg(noQuery.queried)
                  .arg(noQuery.overrides.size()));

        QDir(sandbox + "/export-cf-state").removeRecursively();
    }

    // --- V5k. 导出：落成一个 zip，再用**我们自己的导入路**读回来 ---------------
    //
    // 这一节是整条链上最像"真跑一次"的地方：写文件 → createZip → 用 ZipUtil::readEntry
    // 读清单、用 ZipUtil::extractSubtrees 解 overrides（那正是整合包导入用的那两条路）。
    // 条目名拼错了是**静默**的（我们自己读得回来），所以这里除了"读得回来"还要直接去
    // zip 的字节里找一遍 `overrides/` —— 反斜杠那条在 .NET 那一侧看不见。
    {
        const QString work = sandbox + "/export-zip";
        QDir(work).removeRecursively();
        const QString tree = work + "/我的实例";
        QDir().mkpath(tree);
        writeFileAt(tree + "/mods/认不出来.jar", QByteArrayLiteral("BBB 认不出"));
        writeFileAt(tree + "/config/配置.toml", QByteArrayLiteral("a=1"));
        writeFileAt(tree + "/options.txt", QByteArrayLiteral("fov:70"));
        writeFileAt(work + "/staging/modrinth.index.json",
                    QByteArrayLiteral("{\"formatVersion\":1}"));

        ModpackExport::ExportRequest request;
        request.format = ModpackExport::Format::Modrinth;
        request.instanceDir = tree;
        request.name = QStringLiteral("我的整合包");
        request.version = QStringLiteral("1.2.3");
        request.gameVersion = QStringLiteral("1.21.1");
        request.loaderKey = ModpackImport::fabricLoaderKey();
        request.loaderVersion = QStringLiteral("0.16.14");
        // 反查一律"没成"：这一节要看的是**一个文件都不丢**地打进 overrides。
        const ModpackExport::ExportPlan plan = ModpackExport::buildExportPlan(
            request, ModpackExport::ModrinthQuery(), ModpackExport::CurseForgeQuery());
        check(plan.overrides.size() == 3, "V5k 三个文件都进 overrides",
              QString::number(plan.overrides.size()));

        // 清单那一条从盘上那份来（这里用个占位字节，内容和这一节无关）
        const QList<ZipUtil::ZipSource> entries =
            ModpackExport::archiveEntries(plan, work + "/staging/modrinth.index.json");
        check(entries.size() == 4 && entries.first().entryName == QStringLiteral("modrinth.index.json"),
              "V5k 条目表：清单在第一条，后面跟着 overrides 里那三个",
              QString::number(entries.size()));
        check(entries.at(1).entryName == QStringLiteral("overrides/config/配置.toml"),
              "V5k 条目名是 `overrides/<相对路径>`（`/` 分隔）", entries.at(1).entryName);

        const QString zipPath = work + "/我的整合包.mrpack";
        QString zipError;
        check(ZipUtil::createZip(zipPath, entries, &zipError), "V5k createZip 打出来了", zipError);
        QFile zipFile(zipPath);
        const bool haveZip = zipFile.open(QIODevice::ReadOnly);
        check(haveZip && zipFile.size() > 0, "V5k 盘上那个 zip 不是空的",
              QString::number(zipFile.size()));
        const QByteArray zipBytes = haveZip ? zipFile.readAll() : QByteArray();
        // zip 中央目录里的条目名是**原样的字节**：找得到 `overrides/` 说明写进去的确实是
        // 正斜杠。这条断言之所以必要，是因为刚才那条（readEntry 读得回来）**在反斜杠的
        // 情况下也绿** —— .NET 读的时候会归一。
        check(zipBytes.contains(QByteArrayLiteral("overrides/config/")) &&
                  zipBytes.contains(QByteArrayLiteral("modrinth.index.json")),
              "V5k zip 字节里条目名是正斜杠的 `overrides/…`（反斜杠那种别的启动器认不出）");

        // 第一条路：清单读得回来
        QByteArray manifest;
        QString readError;
        const ZipUtil::EntryStatus status =
            ZipUtil::readEntry(zipPath, QStringLiteral("modrinth.index.json"), &manifest, &readError,
                               QStringLiteral("读清单"));
        check(status == ZipUtil::EntryStatus::Ok &&
                  manifest == QByteArrayLiteral("{\"formatVersion\":1}"),
              "V5k 清单在 zip 根、读得回来", readError);

        // 第二条路：overrides 解出来（**这条就是整合包导入走的那条**）
        const QString unpacked = work + "/解开";
        int extracted = 0;
        QString extractError;
        check(ZipUtil::extractSubtrees({zipPath}, unpacked, {QStringLiteral("overrides/")},
                                       &extracted, &extractError),
              "V5k overrides 解得开（走导入那一条路）", extractError);
        check(extracted == 3, "V5k 解出来三个覆盖文件", QString::number(extracted));
        QFile backConfig(unpacked + "/config/配置.toml");
        QFile backOptions(unpacked + "/options.txt");
        check(backConfig.open(QIODevice::ReadOnly) && backConfig.readAll() == QByteArrayLiteral("a=1") &&
                  backOptions.open(QIODevice::ReadOnly) &&
                  backOptions.readAll() == QByteArrayLiteral("fov:70"),
              "V5k 解出来的内容与实例里那份一字不差（前缀被剥掉了）");
        check(!QFile::exists(unpacked + "/modrinth.index.json") &&
                  !QFile::exists(unpacked + "/overrides/options.txt"),
              "V5k 不属于 overrides/ 的条目一个都没落进实例目录（连前缀那一层都不留）");

        // 失败那一路：来源缺一个 → 报错 + **半成品删掉**（盘上留着一个坏包最坏）
        QList<ZipUtil::ZipSource> bad = entries;
        bad.append({QStringLiteral("overrides/没有这个文件.txt"), tree + "/没有这个文件.txt"});
        const QString badZip = work + "/坏包.mrpack";
        QString badError;
        check(!ZipUtil::createZip(badZip, bad, &badError) && !badError.isEmpty(),
              "V5k 来源文件不存在时如实报错", badError);
        check(!QFile::exists(badZip), "V5k 失败之后盘上不留半成品");
        // 条目名里带反斜杠的那种**在写之前**就拦下来（写进去就晚了，见 .hpp）
        QString slashError;
        check(!ZipUtil::createZip(work + "/斜杠.mrpack",
                                  {{QStringLiteral("overrides\\x.txt"), tree + "/options.txt"}},
                                  &slashError) &&
                  !QFile::exists(work + "/斜杠.mrpack"),
              "V5k 条目名带反斜杠的当场拒绝，不是写完了才说", slashError);

        QDir(work).removeRecursively();
    }

    // --- V5l. 清单的名字与正文是同一套（buildIndexFile 那个唯一分岔） -----------
    //
    // 这一节盯的是一个**静默**的错法：文件名写 `manifest.json`、正文却是 Modrinth 那一份。
    // 那种包自己打得出来、.NET 也读得回来（它不看内容），只有别人的启动器会当场说不认识。
    {
        ModpackExport::Spec modrinth;
        modrinth.format = ModpackExport::Format::Modrinth;
        modrinth.name = QStringLiteral("我的整合包");
        modrinth.version = QStringLiteral("1.2.3");
        modrinth.gameVersion = QStringLiteral("1.21.1");
        modrinth.loaderKey = ModpackImport::fabricLoaderKey();
        modrinth.loaderVersion = QStringLiteral("0.16.14");
        ModpackExport::MatchedFile file;
        file.path = QStringLiteral("mods/认得出来.jar");
        file.sha1 = QStringLiteral("c19b8bfb43a753ad8c27612d516ce61c58b0d2e6");
        file.sha512 = QString(128, QLatin1Char('a'));
        file.urls.append(QStringLiteral("https://cdn.modrinth.com/data/u6dRKJwZ/versions/abc/x.jar"));
        file.size = 12345;
        modrinth.files.append(file);

        check(ModpackExport::buildIndexFile(modrinth) ==
                  ModpackExport::buildModrinthIndex(modrinth),
              "V5l Modrinth 那一档走的就是 modrinth.index.json 那一份正文");
        const ModpackImport::Result round =
            ModpackImport::parseModrinthIndex(ModpackExport::buildIndexFile(modrinth));
        check(round.ok, "V5l 它自己解析得回来（名字和正文认的是同一个枚举）", round.problem);

        ModpackExport::Spec curseforge;
        curseforge.format = ModpackExport::Format::CurseForge;
        curseforge.name = QStringLiteral("我的整合包");
        curseforge.version = QStringLiteral("1.2.3");
        curseforge.gameVersion = QStringLiteral("1.21.1");
        curseforge.loaderKey = ModpackImport::neoforgeLoaderKey();
        curseforge.loaderVersion = QStringLiteral("21.1.210");
        ModpackExport::MatchedRef ref;
        ref.projectId = 394468;
        ref.fileId = 5123456;
        curseforge.refs.append(ref);

        check(ModpackExport::buildIndexFile(curseforge) ==
                  ModpackExport::buildCurseForgeManifest(curseforge),
              "V5l CurseForge 那一档走的就是 manifest.json 那一份正文");
        const ModpackImport::Result round2 =
            ModpackImport::parseCurseForgeManifest(ModpackExport::buildIndexFile(curseforge));
        check(round2.ok, "V5l CF 那份也自己解析得回来", round2.problem);

        check(ModpackExport::indexFileName(ModpackExport::Format::Modrinth) ==
                      QStringLiteral("modrinth.index.json") &&
                  ModpackExport::indexFileName(ModpackExport::Format::CurseForge) ==
                      QStringLiteral("manifest.json"),
              "V5l 两份规范的文件名都钉着（改名字的只有 writers 那一处）");
    }

    // --- V5m. 这个实例装的是什么加载器（导出清单里那一行的唯一出处） -----------
    //
    // 判据的第一条路是**盘上的 id**，第二条路是 wtfml.meta 里我们自己记的显示名。这一节
    // 把"认得出来""认得出来但写不下""认不出来""确实是原版"四档都钉住 —— 因为第一档错
    // 了只是包差一点，第三档错了会把一个装了几百个模组的实例导成纯原版包（用户装回来
    // 会发现模组都在、游戏起不来，而包看上去是好的）。
    {
        const QString versionsRoot = sandbox + "/versions";
        const QString idChain = QStringLiteral("V5m-链上认");
        const QString idMeta = QStringLiteral("V5m-meta认");
        const QString idOptifine = QStringLiteral("V5m-OptiFine");
        const QString idQuilt = QStringLiteral("V5m-Quilt");
        const QString idVanilla = QStringLiteral("V5m-原版");
        const QString idMetaBad = QStringLiteral("V5m-meta不认识");
        const QString idCycleA = QStringLiteral("V5m-环A");
        const QString idCycleB = QStringLiteral("V5m-环B");

        // 实例 → 加载器版本 → 原版：三层链（真机上的形状就是这么来的）
        writeFileAt(versionsRoot + "/" + idChain + "/" + idChain + ".json",
                    QByteArrayLiteral("{\"id\":\"V5m-链上认\","
                                      "\"inheritsFrom\":\"fabric-loader-0.16.14-1.21.1\"}"));
        writeFileAt(versionsRoot + "/fabric-loader-0.16.14-1.21.1/"
                                 "fabric-loader-0.16.14-1.21.1.json",
                    QByteArrayLiteral("{\"id\":\"fabric-loader-0.16.14-1.21.1\","
                                      "\"inheritsFrom\":\"1.21.1\"}"));
        writeFileAt(versionsRoot + "/1.21.1/1.21.1.json", QByteArrayLiteral("{\"id\":\"1.21.1\"}"));

        // 第一条路不认识任何东西，只有 meta 里记着加载器（用户手写过的 meta 就是这个形状）
        writeFileAt(versionsRoot + "/" + idMeta + "/" + idMeta + ".json",
                    QByteArrayLiteral("{\"id\":\"V5m-meta认\",\"inheritsFrom\":\"1.21.1\"}"));
        writeFileAt(versionsRoot + "/" + idMeta + "/wtfml.meta",
                    QByteArrayLiteral("{\"loaderName\":\"Forge\",\"loaderVersion\":\"47.4.10\","
                                      "\"realVersion\":\"1.21.1\"}"));

        // OptiFine / Quilt：认得出来，但都没有能写进清单的键
        writeFileAt(versionsRoot + "/" + idOptifine + "/" + idOptifine + ".json",
                    QByteArrayLiteral("{\"id\":\"V5m-OptiFine\","
                                      "\"inheritsFrom\":\"1.18.2-OptiFine_HD_U_H9\"}"));
        writeFileAt(versionsRoot + "/" + idQuilt + "/" + idQuilt + ".json",
                    QByteArrayLiteral("{\"id\":\"V5m-Quilt\","
                                      "\"inheritsFrom\":\"quilt-loader-0.20.0-1.20.1\"}"));

        // 确实是原版：链上没有加载器，meta 里也没有 loaderName
        writeFileAt(versionsRoot + "/" + idVanilla + "/" + idVanilla + ".json",
                    QByteArrayLiteral("{\"id\":\"V5m-原版\",\"inheritsFrom\":\"1.21.1\"}"));
        writeFileAt(versionsRoot + "/" + idVanilla + "/wtfml.meta",
                    QByteArrayLiteral("{\"realVersion\":\"1.21.1\"}"));

        // meta 里写了一个我们不认识的名字
        writeFileAt(versionsRoot + "/" + idMetaBad + "/" + idMetaBad + ".json",
                    QByteArrayLiteral("{\"id\":\"V5m-meta不认识\",\"inheritsFrom\":\"1.21.1\"}"));
        writeFileAt(versionsRoot + "/" + idMetaBad + "/wtfml.meta",
                    QByteArrayLiteral("{\"loaderName\":\"LiteLoader\",\"loaderVersion\":\"1.12\"}"));

        // 继承链成环：不许死循环，也不许因为"走不动了"就报错
        writeFileAt(versionsRoot + "/" + idCycleA + "/" + idCycleA + ".json",
                    QByteArrayLiteral("{\"id\":\"V5m-环A\",\"inheritsFrom\":\"V5m-环B\"}"));
        writeFileAt(versionsRoot + "/" + idCycleB + "/" + idCycleB + ".json",
                    QByteArrayLiteral("{\"id\":\"V5m-环B\",\"inheritsFrom\":\"V5m-环A\"}"));

        VersionManager vm;
        const auto ask = [&vm](const QString &instanceId, QString *key, QString *version) {
            key->clear();
            version->clear();
            return vm.instanceLoaderInfo(instanceId, key, version);
        };

        {
            QString key;
            QString version;
            const QString problem = ask(idChain, &key, &version);
            check(problem.isEmpty() && key == ModpackImport::fabricLoaderKey() &&
                      version == QStringLiteral("0.16.14"),
                  "V5m 链上的 fabric-loader-<版本>-<游戏版本> 拆得开",
                  QStringLiteral("%1 / %2 %3").arg(problem, key, version));
        }
        {
            // Fabric 那条要**从左边切第一刀**：游戏版本里真能带 `-`，加载器版本不会。
            const QString id = QStringLiteral("V5m-带横杠");
            writeFileAt(versionsRoot + "/" + id + "/" + id + ".json",
                        QByteArrayLiteral("{\"id\":\"V5m-带横杠\","
                                          "\"inheritsFrom\":\"fabric-loader-0.16.14-1.21-pre1\"}"));
            QString key;
            QString version;
            check(ask(id, &key, &version).isEmpty() && key == ModpackImport::fabricLoaderKey() &&
                      version == QStringLiteral("0.16.14"),
                  "V5m 游戏版本里带横杠时，切出来的加载器版本还是 0.16.14",
                  QStringLiteral("%1 / %2").arg(key, version));
        }
        {
            QString key;
            QString version;
            const QString problem = ask(idMeta, &key, &version);
            check(problem.isEmpty() && key == ModpackImport::forgeLoaderKey() &&
                      version == QStringLiteral("47.4.10"),
                  "V5m 链上没有、meta 里记着的那一档也认得出来（Forge 47.4.10）",
                  QStringLiteral("%1 / %2 %3").arg(problem, key, version));
        }
        {
            QString key;
            QString version;
            const QString problem = ask(idVanilla, &key, &version);
            check(problem.isEmpty() && key.isEmpty() && version.isEmpty(),
                  "V5m 确实是原版的实例：空键 + 空版本 + 没有抱怨（那是正常结果）", problem);
        }
        {
            QString key;
            QString version;
            const QString problem = ask(idOptifine, &key, &version);
            check(!problem.isEmpty() && key.isEmpty(),
                  "V5m OptiFine 认得出来但**拒绝导出**（两种清单里都没有它那一格）", problem);
            check(problem.contains(QStringLiteral("OptiFine")),
                  "V5m 那句话里点明了是 OptiFine（而不是一句通用的失败）", problem);
        }
        {
            QString key;
            QString version;
            const QString problem = ask(idQuilt, &key, &version);
            check(!problem.isEmpty() && key.isEmpty(),
                  "V5m Quilt 也拒绝导出（清单写得下，我们装不了）", problem);
        }
        {
            QString key;
            QString version;
            const QString problem = ask(idMetaBad, &key, &version);
            check(!problem.isEmpty() && problem.contains(QStringLiteral("LiteLoader")),
                  "V5m meta 里那个不认识的名字照实报出来（不静默当成纯原版）", problem);
        }
        {
            QString key;
            QString version;
            const QString problem = ask(idCycleA, &key, &version);
            check(problem.isEmpty() && key.isEmpty(),
                  "V5m 继承链成环时不死循环、也不报错（该认的上面几层已经认过了）", problem);
        }
    }

    // --- V5o. PCL / HMCL 那类"合并过的"实例：基于哪个原版 + 装的是什么加载器 --------
    //
    // 2026-09-26 用户在真机上撞的那一条：日志里只有一句「导出失败：读不出 海波篮子 基于哪个
    // 原版」。真因是那个实例是 PCL 装的 —— 整份 json 都合进了实例目录（`inheritsFrom` 是
    // 空的，`id` 就是用户起的名字），所以 V5m 那几条按 id 认的路一步都走不出去；而它的加载器
    // （`net.fabricmc:fabric-loader:0.19.5`）和原版（`clientVersion: 26.2`）就明明白白写在
    // 那份 json 自己身上。**真机上大多数实例都是这个形状**，所以这不是一条边界用例。
    //
    // 这一节钉两件**方向相反**的事：
    //   ① 这两格读得出来（读不出来，那些实例一个都导不出去）；
    //   ② 读不出来时**一个字都不许猜** —— 目录名以数字开头但带空格（`1.20.2-Fabric 0.17.2`）
    //      不许顶成游戏版本；认不出加载器时不许悄悄当成纯原版（那正是这个功能最怕的失败：
    //      包看上去是好的、装回来模组都在、游戏起不来）。
    {
        const QString versionsRoot = sandbox + "/versions";
        const auto writeJson = [&versionsRoot](const QString &id, const QByteArray &body) {
            writeFileAt(versionsRoot + "/" + id + "/" + id + ".json", body);
        };
        const auto writeMeta = [&versionsRoot](const QString &id, const QByteArray &body) {
            writeFileAt(versionsRoot + "/" + id + "/wtfml.meta", body);
        };

        VersionManager vm;
        const auto loaderOf = [&vm](const QString &id, QString *key, QString *version) {
            key->clear();
            version->clear();
            return vm.instanceLoaderInfo(id, key, version);
        };

        // ① 真机上那个实例，一比一抄下来的形状：合过的 json、id 是名字、没有 inheritsFrom。
        const QString idPcl = QStringLiteral("海波篮子");
        writeJson(idPcl, QByteArrayLiteral("{\"id\":\"海波篮子\",\"clientVersion\":\"26.2\","
                                           "\"mainClass\":\"net.fabricmc.loader.impl.launch.knot."
                                           "KnotClient\",\"libraries\":["
                                           "{\"name\":\"net.fabricmc:intermediary:26.2\"},"
                                           "{\"name\":\"net.fabricmc:fabric-loader:0.19.5\"},"
                                           "{\"name\":\"org.ow2.asm:asm:9.7\"}]}"));
        // meta 里只有 instanceId（我们导入时写的那一份），既没有 realVersion 也没有 loaderName
        writeMeta(idPcl,
                  QByteArrayLiteral("{\"instanceId\":\"535107a2-4b43-4915-bd38-c7d85ebf3586\"}"));
        check(vm.instanceGameVersion(idPcl) == QStringLiteral("26.2"),
              "V5o PCL 那种合过的 json：原版从 clientVersion 读得出来（26.2）",
              vm.instanceGameVersion(idPcl));
        {
            QString key;
            QString version;
            const QString problem = loaderOf(idPcl, &key, &version);
            check(problem.isEmpty() && key == ModpackImport::fabricLoaderKey() &&
                      version == QStringLiteral("0.19.5"),
                  "V5o PCL 那种合过的 json：加载器从 libraries 认出来了（fabric 0.19.5）",
                  QStringLiteral("%1 / %2 %3").arg(problem, key, version));
        }

        // ② 目录名以数字开头、但不是版本号（真机上有 `1.20.2-Fabric 0.17.2` 这种）。
        //    这条钉的是判据本身：**"以数字开头"不够**。
        const QString idSpacey = QStringLiteral("1.20.2-Fabric 0.17.2");
        writeJson(idSpacey, QByteArrayLiteral("{\"id\":\"1.20.2-Fabric 0.17.2\",\"libraries\":["
                                             "{\"name\":\"net.fabricmc:fabric-loader:0.17.2\"}]}"));
        check(vm.instanceGameVersion(idSpacey).isEmpty(),
              "V5o 目录名以数字开头但带空格 ⇒ 不许顶成游戏版本（写进清单就是个假版本号）",
              vm.instanceGameVersion(idSpacey));
        {
            QString key;
            QString version;
            // 同一个实例的加载器照旧认得出：原版那一格没读出来，不代表加载器也不认。
            check(loaderOf(idSpacey, &key, &version).isEmpty() &&
                      key == ModpackImport::fabricLoaderKey() &&
                      version == QStringLiteral("0.17.2"),
                  "V5o 原版那格读不出来时，加载器那一格照旧照实认（fabric 0.17.2）",
                  QStringLiteral("%1 / %2").arg(key, version));
        }

        // ③ 纯原版：目录名就是版本号，json 里什么都没有。
        const QString idVanilla = QStringLiteral("1.21.4");
        writeJson(idVanilla, QByteArrayLiteral("{\"id\":\"1.21.4\"}"));
        check(vm.instanceGameVersion(idVanilla) == QStringLiteral("1.21.4"),
              "V5o 纯原版实例：目录名 / 它自己那份 json 的 id 就是版本号", vm.instanceGameVersion(idVanilla));
        {
            QString key;
            QString version;
            check(loaderOf(idVanilla, &key, &version).isEmpty() && key.isEmpty(),
                  "V5o 纯原版实例：空键 + 空版本 + 没有抱怨（那是正常结果）",
                  QStringLiteral("%1 / %2").arg(key, version));
        }

        // ④ 目录名完全不像版本号（真机上有 `原版ATT2地图（无模组）` 这种）：宁可返回空串
        //    （调用点会拦住并报一句），也不许编一个版本号出来。
        const QString idOdd = QStringLiteral("历史存档（无模组）");
        writeJson(idOdd, QByteArrayLiteral("{\"id\":\"历史存档（无模组）\"}"));
        check(vm.instanceGameVersion(idOdd).isEmpty(),
              "V5o 目录名完全不像版本号 ⇒ 返回空串（不编、也不报错）", vm.instanceGameVersion(idOdd));

        // ⑤ 薄 json（我们自己的整合包导入就是这个形状）：inheritsFrom 走到原版那一份。
        const QString idThin = QStringLiteral("V5o-薄");
        writeJson(idThin, QByteArrayLiteral("{\"id\":\"V5o-薄\",\"inheritsFrom\":\"1.21.4\"}"));
        check(vm.instanceGameVersion(idThin) == QStringLiteral("1.21.4"),
              "V5o 薄 json 顺着 inheritsFrom 走到原版那一份", vm.instanceGameVersion(idThin));

        // ⑥ realVersion 仍然排在 clientVersion 前面（它是装的时候从清单里抄的真值）。
        const QString idReal = QStringLiteral("V5o-realVersion");
        writeJson(idReal, QByteArrayLiteral("{\"id\":\"V5o-realVersion\",\"clientVersion\":\"26.2\"}"));
        writeMeta(idReal, QByteArrayLiteral("{\"realVersion\":\"1.21.1\"}"));
        check(vm.instanceGameVersion(idReal) == QStringLiteral("1.21.1"),
              "V5o meta 里的 realVersion 优先于 json 里的 clientVersion",
              vm.instanceGameVersion(idReal));

        // ⑦ realVersion 是能手改的文本：它自己不像版本号时作废，往下问 clientVersion。
        const QString idRealBad = QStringLiteral("V5o-realVersion坏");
        writeJson(idRealBad,
                  QByteArrayLiteral("{\"id\":\"V5o-realVersion坏\",\"clientVersion\":\"1.20.2\"}"));
        writeMeta(idRealBad, QByteArrayLiteral("{\"realVersion\":\"1.20.2-Fabric 0.17.2\"}"));
        check(vm.instanceGameVersion(idRealBad) == QStringLiteral("1.20.2"),
              "V5o meta 里那个不像版本号的 realVersion 作废，clientVersion 顶上",
              vm.instanceGameVersion(idRealBad));

        // ---- 加载器：从 libraries 的 maven 坐标认（形状都照真机上量过的那几种抄）----
        const auto loaderCase = [&](const QString &id, const QByteArray &libraries) {
            writeJson(id, QByteArrayLiteral("{\"id\":\"") + id.toUtf8() +
                              QByteArrayLiteral("\",\"libraries\":") + libraries +
                              QByteArrayLiteral("}"));
        };
        const auto expectLoader = [&](const QString &id, const QString &wantKey,
                                      const QString &wantVersion, const QString &title) {
            QString key;
            QString version;
            const QString problem = loaderOf(id, &key, &version);
            check(problem.isEmpty() && key == wantKey && version == wantVersion, title,
                  QStringLiteral("%1 / %2 %3").arg(problem, key, version));
        };

        const QString idOldForge = QStringLiteral("V5o-旧Forge");
        loaderCase(idOldForge, QByteArrayLiteral("[{\"name\":\"net.minecraftforge:forge:1.12.2-"
                                                "14.23.5.2860\"}]"));
        expectLoader(idOldForge, ModpackImport::forgeLoaderKey(), QStringLiteral("14.23.5.2860"),
                     "V5o 1.12 那种 forge 坐标：切掉的是原版那一段，不是加载器版本");

        // GTNH 那种后面还挂着一个游戏版本的坐标：**从左边切第一刀**（切最后一个横杠是反的）。
        const QString idGtnh = QStringLiteral("V5o-GTNH");
        loaderCase(idGtnh, QByteArrayLiteral("[{\"name\":\"net.minecraftforge:forge:"
                                            "1.7.10-10.13.4.1614-1.7.10\"}]"));
        expectLoader(idGtnh, ModpackImport::forgeLoaderKey(),
                     QStringLiteral("10.13.4.1614-1.7.10"),
                     "V5o GTNH 那种带尾巴的 forge 坐标切得开（10.13.4.1614-1.7.10）");

        const QString idNewForge = QStringLiteral("V5o-新Forge");
        writeJson(idNewForge,
                  QByteArrayLiteral("{\"id\":\"V5o-新Forge\",\"libraries\":[{\"name\":"
                                    "\"net.minecraftforge:fmlloader:1.20.1-47.2.0\"}],"
                                    "\"arguments\":{\"game\":[\"--fml.forgeVersion\",\"47.2.0\"]}}"));
        expectLoader(idNewForge, ModpackImport::forgeLoaderKey(), QStringLiteral("47.2.0"),
                     "V5o 1.13 以后的 forge 走 fmlloader 那一格（47.2.0）");

        // 只有加载器自己声明的启动参数、没有坐标：那也是证据（和 id 那条路不同的一条法）。
        const QString idArgOnly = QStringLiteral("V5o-只认参数");
        writeJson(idArgOnly, QByteArrayLiteral("{\"id\":\"V5o-只认参数\",\"arguments\":{\"game\":"
                                              "[\"--fml.forgeVersion\",\"47.3.33\"]}}"));
        expectLoader(idArgOnly, ModpackImport::forgeLoaderKey(), QStringLiteral("47.3.33"),
                     "V5o 只有 --fml.forgeVersion 时也认（47.3.33）");

        const QString idNeo = QStringLiteral("V5o-NeoForge");
        writeJson(idNeo,
                  QByteArrayLiteral("{\"id\":\"V5o-NeoForge\",\"libraries\":[{\"name\":"
                                    "\"net.neoforged.fancymodloader:loader:4.0.41\"}],"
                                    "\"arguments\":{\"game\":[\"--fml.neoForgeVersion\","
                                    "\"21.1.184\"]}}"));
        {
            QString key;
            QString version;
            const QString problem = loaderOf(idNeo, &key, &version);
            check(problem.isEmpty() && key == ModpackImport::neoforgeLoaderKey() &&
                      version == QStringLiteral("21.1.184"),
                  "V5o NeoForge 的版本号取自 --fml.neoForgeVersion（21.1.184）",
                  QStringLiteral("%1 / %2 %3").arg(problem, key, version));
            // 那条参数就是为这一格存在的：4.0.41 是 fancymodloader 的版本，**不是** neoforge 的。
            check(version != QStringLiteral("4.0.41"),
                  "V5o 写进清单的不是 fancymodloader 那个 4.0.41");
        }

        // 认得出来是 NeoForge、但读不出是哪一版 ⇒ **停下来报一句**，不许拿 4.0.41 顶上。
        const QString idNeoNoVer = QStringLiteral("V5o-NeoForge没号");
        loaderCase(idNeoNoVer,
                   QByteArrayLiteral("[{\"name\":\"net.neoforged.fancymodloader:loader:4.0.41\"}]"));
        {
            QString key;
            QString version;
            const QString problem = loaderOf(idNeoNoVer, &key, &version);
            check(!problem.isEmpty() && key.isEmpty() &&
                      problem.contains(QStringLiteral("NeoForge")),
                  "V5o 认得出是 NeoForge、读不出哪一版时：报一句、不导出（不拿 4.0.41 顶）",
                  problem);
        }

        // OptiFine / Quilt：认得出来，但都没有能写进清单的键 —— 这一档混进纯原版就是灾难。
        const QString idOf = QStringLiteral("V5o-OptiFine");
        loaderCase(idOf, QByteArrayLiteral("[{\"name\":\"optifine:OptiFine:1.20.1_HD_U_I6\"}]"));
        {
            QString key;
            QString version;
            const QString problem = loaderOf(idOf, &key, &version);
            check(!problem.isEmpty() && key.isEmpty() &&
                      problem.contains(QStringLiteral("OptiFine")),
                  "V5o 合过的 json 里装了 OptiFine：照旧拒绝导出（那两句说明只有一个出处）",
                  problem);
        }
        const QString idQuilt = QStringLiteral("V5o-Quilt");
        loaderCase(idQuilt, QByteArrayLiteral("[{\"name\":\"org.quiltmc:quilt-loader:0.20.0\"}]"));
        {
            QString key;
            QString version;
            const QString problem = loaderOf(idQuilt, &key, &version);
            check(!problem.isEmpty() && key.isEmpty() &&
                      problem.contains(QStringLiteral("Quilt")),
                  "V5o 合过的 json 里装了 Quilt：也拒绝导出（清单写得下、我们装不了）", problem);
        }

        // 两种都装（Fabric + OptiFine 是真机上很常见的一种）：OptiFine 那一档优先，
        // 和 id 那条路同一个顺序。
        const QString idBoth = QStringLiteral("V5o-Fabric加OptiFine");
        loaderCase(idBoth,
                   QByteArrayLiteral("[{\"name\":\"net.fabricmc:fabric-loader:0.16.14\"},"
                                     "{\"name\":\"optifine:OptiFine:1.20.1_HD_U_I6\"}]"));
        {
            QString key;
            QString version;
            const QString problem = loaderOf(idBoth, &key, &version);
            check(!problem.isEmpty() && problem.contains(QStringLiteral("OptiFine")),
                  "V5o Fabric 与 OptiFine 同时装着时报 OptiFine 那一句（顺序也和 id 那条路一致）",
                  problem);
        }

        // mainClass **不是**判据：Forge 与 NeoForge 共用 BootstrapLauncher，而 1.12.2 的
        // 纯原版用的就是 launchwrapper。拿它当判据的话，纯原版会被认成装了加载器。
        const QString idMainOnly = QStringLiteral("V5o-只看mainClass");
        writeJson(idMainOnly,
                  QByteArrayLiteral("{\"id\":\"V5o-只看mainClass\",\"mainClass\":"
                                    "\"cpw.mods.bootstraplauncher.BootstrapLauncher\"}"));
        {
            QString key;
            QString version;
            const QString problem = loaderOf(idMainOnly, &key, &version);
            check(problem.isEmpty() && key.isEmpty(),
                  "V5o mainClass 不参与判断（BootstrapLauncher 被 Forge/NeoForge 共用、"
                  "launchwrapper 纯原版也在用）",
                  QStringLiteral("%1 / %2").arg(key, version));
        }
    }

    // --- V5u. 实例设置里「数据包」那一页该不该出现（纯函数，2026-09-27 加） ------
    //
    // 用户 2026-09-27 补的一句：「对于没有数据包的版本，数据包也默认隐藏且不可勾选」。
    // 判据落在 `VersionManager::gameVersionSupportsDatapacks()` 上，**纯函数**（喂版本号
    // 与 releaseTime 两串文字），所以这一节不碰盘、不联网，喂多少种版本号都行。
    //
    // 数据包是快照 `17w43a`（2017-10-25）引进的。两格判据按**先准后糙**排：
    //   ① 盘上那份**合并过的** json 有 `releaseTime` ⇒ 和 2017-11-01 比。这一格离线也准，
    //      快照 / `a1.2.6` / `b1.7.3` 那种"版本号看着不像数字"的也分得对；
    //   ② 没有 ⇒ 看版本号本身，以数字开头的按 `主.次 >= (1,13)` 比；
    //   ③ 两条都问不出来 ⇒ **给**（宁可多一页，不要静默藏掉一页）。
    //
    // ★ 这一节另一半钉的是**"哪一格说了算"**：releaseTime 在的时候**盖过**版本号本身，
    //   而且两格都不许悄悄把"读不出来"当成"没有"。
    {
        const auto supports = [](const QString &id, const QString &stamp) {
            return VersionManager::gameVersionSupportsDatapacks(id, stamp);
        };

        // ① releaseTime 说了算 —— 而且用的是**真清单里那种形状**（`+00:00` 那个后缀）。
        //    这一格要是解析不出来，整条规则会**静默**退到版本号那一档（1.12.2 照样对、
        //    快照就全错），症状是"看着都对、就是那几个版本多出一页"。
        check(!supports(QStringLiteral("1.12.2"),
                        QStringLiteral("2017-09-18T11:05:56+00:00")),
              "V5u 1.12.2 那一份的 releaseTime 早于 2017-11-01 ⇒ 没有数据包那一页");
        check(supports(QStringLiteral("1.13"),
                       QStringLiteral("2018-07-18T15:22:36+00:00")),
              "V5u 1.13（数据包引进之后的第一个正式版）⇒ 有");
        check(!supports(QStringLiteral("1.20.1"), QStringLiteral("2010-01-01T00:00:00+00:00")),
              "V5u releaseTime 在手时**盖过**版本号本身：1.20.1 配一个 2010 的时间戳 ⇒ "
              "按时间戳判（判成没有）");
        // 界线本身：`17w43a` 就是把数据包引进来的那一个快照，而它的日期在 2017-11-01
        // **之前**。这一条故意钉住"按日期切"这个口径 —— 不为几个界上的快照编例外表。
        check(!supports(QStringLiteral("17w43a"),
                        QStringLiteral("2017-10-25T15:00:00+00:00")),
              "V5u 界线就是界线：17w43a 自己的 releaseTime 早于 2017-11-01 ⇒ 判成没有"
              "（界上那几个快照不值得为它编一张例外表）");
        // 版本号看着不像数字的那些：只有 releaseTime 这一格分得对。
        check(!supports(QStringLiteral("a1.2.6"),
                        QStringLiteral("2010-10-30T00:00:00+00:00")),
              "V5u a1.2.6：版本号那一格认不出来，靠 releaseTime 判 ⇒ 没有");
        check(!supports(QStringLiteral("b1.7.3"),
                        QStringLiteral("2011-07-08T00:00:00+00:00")),
              "V5u b1.7.3 同理 ⇒ 没有（版本号那一格认不出来，2011 那一份的时间戳照实读）");
        check(supports(QStringLiteral("b1.7.3"),
                       QStringLiteral("2020-01-01T00:00:00+00:00")),
              "V5u 同一个 b1.7.3 换一个 2020 的时间戳 ⇒ 有 —— releaseTime 那一格说了算，"
              "版本号长得像不像数字它都不管");

        // ② 没有 releaseTime：退回版本号本身（以数字开头的按 主.次 >= (1,13) 比）。
        check(!supports(QStringLiteral("1.12.2"), QString()),
              "V5u 没有 releaseTime 时看版本号：1.12.2 ⇒ 没有");
        check(!supports(QStringLiteral("1.7.10"), QString()),
              "V5u 1.7.10 ⇒ 没有");
        check(supports(QStringLiteral("1.13"), QString()), "V5u 1.13 ⇒ 有（下界含在内）");
        check(supports(QStringLiteral("1.13.1"), QString()), "V5u 1.13.1 ⇒ 有");
        check(supports(QStringLiteral("1.20.1"), QString()), "V5u 1.20.1 ⇒ 有");
        check(supports(QStringLiteral("2.0"), QString()), "V5u 主版本高于 1 ⇒ 有");
        // 真机上大量的实例目录名是 `1.12.2-Forge` 这种：版本号那一截取到第一个不是数字
        // 也不是点号的字符为止，别把 `-Forge` 当成版本的一部分。
        check(!supports(QStringLiteral("1.12.2-Forge"), QString()),
              "V5u 实例目录名那种写法（1.12.2-Forge）：版本号那一截读到 1.12.2 为止 ⇒ 没有");
        check(supports(QStringLiteral("1.20.1-Fabric 0.16.14"), QString()),
              "V5u 同理（1.20.1-Fabric 0.16.14）⇒ 有");
        // 明知的不精确，写在 NOTE 里也钉在测试里：周快照那个数字是**年份**，会被读成
        // "主版本 13/26"。真机上这类实例盘上都有 releaseTime，走不到这一档。
        check(supports(QStringLiteral("13w41a"), QString()),
              "V5u 13w41a 这种周快照在「没有 releaseTime」这一档会被判成有 —— 这是明知的"
              "不精确（那个数字是年份），真机上它们都带 releaseTime");
        // ③ 两条都问不出来 ⇒ 给。
        check(supports(QString(), QString()),
              "V5u 两格都空 ⇒ **给**（宁可多一页，别静默藏掉用户真需要的一页）");
        check(supports(QStringLiteral("a1.2.6"), QString()),
              "V5u 版本号不像数字 + 没有 releaseTime ⇒ 给（同上：不猜「没有」）");
        // 认不出来的 releaseTime 当作"没有这一格"，别静默当成"早于界线"。
        check(!supports(QStringLiteral("1.12.2"), QStringLiteral("不是时间")),
              "V5u releaseTime 认不出来时当作没有这一格，退到版本号那一档（1.12.2 ⇒ 没有）");
        check(supports(QStringLiteral("1.20.1"), QStringLiteral("不是时间")),
              "V5u 同上：1.20.1 ⇒ 有（认不出来的时间戳不许把结果拽成「没有」）");

        // ④ meta 里那个键的名字只有一个出处（写盘/读盘/验证工程都走它）。
        check(VersionManager::settingsPagesField() == QStringLiteral("settingsPages"),
              "V5u 「哪几页收起来了」那个键的名字走 settingsPagesField() 那一个出处",
              VersionManager::settingsPagesField());
    }

    // --- V5p. 版本号那一格的判据（纯函数，喂**真清单夹具**） ---------------------
    //
    // 规矩：**清单在手时以清单为准，清单没取到时看长相**。两边各自防一种错：
    //   ① 清单在手时不看长相 ⇒ 老版本号认不出来。`rd-132211`（Minecraft 最早的开发版之一）
    //      **不以数字开头**，而真机上就躺着一份 —— 2026-09-26 拿只读探针
    //      `mw_check instance-scan <数据目录>` 扫出来的，它导不出整合包没有道理。
    //   ② 清单在手时也不放过"长相" ⇒ 反过来那一半：`20w14∞`（正式 id 是 `20w14infinite`）、
    //      `26.2hyperland`（私服客户端）长得都像版本号，可 Mojang 没有这两个 id，写进清单
    //      收包的人那边装不回来 —— 也是同一个病（包看上去是好的）。
    //   ③ 清单没取到（离线第一趟）⇒ 退回长相那条，宁可放行也不让"离线时一个都导不出去"。
    //   ④ 两条都挡着的：`原版ATT2地图（无模组）` 和 `1.20.2-Fabric 0.17.2` 这种明显的假版本号。
    {
        // 真清单夹具：走产品自己那条解析路（`DownloadManager::parseVersionManifest`），
        // 不在这儿另写一份 —— 和 Y 那一节同一个理由。
        QList<MinecraftVersion> manifest;
        {
            QFile fixture(QStringLiteral(REPO_ROOT_PATH) +
                          QStringLiteral("/tests/meta/manifest.json"));
            if (fixture.open(QIODevice::ReadOnly)) {
                DownloadManager downloadManager;
                downloadManager.parseVersionManifest(
                    QJsonDocument::fromJson(fixture.readAll()));
                manifest = downloadManager.getAvailableVersions();
            }
            check(manifest.size() > 500, "V5p 真清单夹具读进来了（下面几条判据都指望它）",
                  QString::number(manifest.size()));
        }

        const QList<MinecraftVersion> empty;
        check(VersionManager::isKnownGameVersion(QStringLiteral("1.20.1"), manifest),
              "V5p 真清单里有的普通版本号认得出（1.20.1）");
        check(VersionManager::isKnownGameVersion(QStringLiteral("rd-132211"), manifest),
              "★ V5p **不以数字开头的老版本号**靠清单认得出（rd-132211）——"
              "光看长相这一档会被整个漏掉");
        check(!VersionManager::isKnownGameVersion(QStringLiteral("20w14∞"), manifest),
              "★ V5p **长得像版本号但 Mojang 没这个 id** 的照旧不许（20w14∞：正式 id 是 "
              "20w14infinite）—— 清单在手时长相不算数");
        check(VersionManager::isKnownGameVersion(QStringLiteral("20w14∞"), empty),
              "★ V5p 但清单没取到时就放行它（离线那一档宁可放行，也不能一个实例都导不出去）");
        check(!VersionManager::isKnownGameVersion(QStringLiteral("原版ATT2地图（无模组）"), manifest),
              "★ V5p 目录名不像版本号、清单里也没有 ⇒ 不许（写进清单是个假版本号）");
        check(!VersionManager::isKnownGameVersion(QStringLiteral("1.20.2-Fabric 0.17.2"), manifest),
              "★ V5p **以数字开头但不是版本号**的目录名同样不许（带空格的这条判据就是为它写的）");

        // 清单没取到那一档：行为**退化**成改前那样（能认的照认，认不出的照不认）。
        check(VersionManager::isKnownGameVersion(QStringLiteral("1.20.1"), empty),
              "V5p 清单没取到时：长得像版本号的照认（1.20.1）");
        check(!VersionManager::isKnownGameVersion(QStringLiteral("rd-132211"), empty),
              "V5p 清单没取到时：rd-132211 认不出来（**只是退化**：调用点会报一句、不写假版本号）");
        check(!VersionManager::isKnownGameVersion(QStringLiteral(""), empty) &&
                  !VersionManager::isKnownGameVersion(QStringLiteral("   "), manifest),
              "V5p 空串 / 纯空白一律不许");
        check(VersionManager::isKnownGameVersion(QStringLiteral(" 1.20.1 "), manifest),
              "V5p 两头带空白的先 trim 再判（那份 json 是能手改的文本）");
        // "清单比实例旧"这一种：新快照不在夹具里 ⇒ 清单在手时**报一句**（重启取了新清单就好），
        // 而不是硬写一个自己都不认识的号进清单。
        check(!VersionManager::isKnownGameVersion(QStringLiteral("26.9-snapshot-9"), manifest) &&
                  VersionManager::isKnownGameVersion(QStringLiteral("26.9-snapshot-9"), empty),
              "V5p 比清单还新的快照：清单在手时不放行（报一句，重启就恢复）、没清单时放行");
    }

    // --- V5n. 后半段：清单进暂存目录 → 打成一个 zip → 改名到目标 -----------------
    //
    // 这一节要的东西比 V5k 多一层：**上面那一趟 plan 是真的跑出来的**（假接口喂一条命中），
    // 然后由 VersionManager 自己写清单、打包。钉的是三件事：①打出来的包我们自己读得回来
    // （名字、清单、overrides 三样都对）；②失败/取消时盘上不留半成品，也不碰用户原来那份；
    // ③覆盖已存在的目标文件这条路是通的（用户点"替换"之后不该报错）。
    {
        const QString work = sandbox + "/export-archive";
        QDir(work).removeRecursively();
        const QString tree = work + "/我的实例";
        QDir().mkpath(tree);
        const QByteArray bytesMatched = QByteArrayLiteral("AAA 认得出");
        const QByteArray bytesUnknown = QByteArrayLiteral("BBB 认不出");
        writeFileAt(tree + "/mods/认得出来.jar", bytesMatched);
        writeFileAt(tree + "/config/配置.toml", bytesUnknown);

        const auto sha1OfBytes = [](const QByteArray &bytes) {
            QCryptographicHash hash(QCryptographicHash::Sha1);
            hash.addData(QByteArrayView(bytes));
            return QString::fromLatin1(hash.result().toHex());
        };
        const auto sha512OfBytes = [](const QByteArray &bytes) {
            QCryptographicHash hash(QCryptographicHash::Sha512);
            hash.addData(QByteArrayView(bytes));
            return QString::fromLatin1(hash.result().toHex());
        };
        const QString sha1Matched = sha1OfBytes(bytesMatched);

        ModpackExport::ExportRequest request;
        request.format = ModpackExport::Format::Modrinth;
        request.instanceDir = tree;
        request.name = QStringLiteral("我的整合包");
        request.version = QStringLiteral("1.2.3");
        request.gameVersion = QStringLiteral("1.21.1");
        request.loaderKey = ModpackImport::fabricLoaderKey();
        request.loaderVersion = QStringLiteral("0.16.14");

        const ModpackExport::ModrinthQuery fakeModrinth =
            [&](const QStringList &sha1s, QHash<QString, ModpackExport::ModrinthHit> *out,
                QString *problemOut) {
                if (problemOut != nullptr) {
                    problemOut->clear();
                }
                ModpackExport::ModrinthHit hit;
                hit.projectId = QStringLiteral("u6dRKJwZ");
                hit.versionNumber = QStringLiteral("1.2.3");
                hit.filename = QStringLiteral("认得出来.jar");
                hit.sha1 = sha1Matched;
                hit.sha512 = sha512OfBytes(bytesMatched);
                hit.url = QStringLiteral(
                    "https://cdn.modrinth.com/data/u6dRKJwZ/versions/abc/认得出来.jar");
                hit.size = bytesMatched.size();
                for (const QString &sha1 : sha1s) {
                    if (sha1 == sha1Matched) {
                        out->insert(sha1Matched, hit);
                    }
                }
                return true;
            };

        const ModpackExport::ExportPlan plan = ModpackExport::buildExportPlan(
            request, fakeModrinth, ModpackExport::CurseForgeQuery());
        check(plan.spec.files.size() == 1 && plan.overrides.size() == 1,
              "V5n 前提：一条认出来了、一条没有（两条路都要走到）",
              QStringLiteral("%1 / %2").arg(plan.spec.files.size()).arg(plan.overrides.size()));

        VersionManager vm;
        const QString target = work + "/打包测试.mrpack";
        const QString problem = vm.writePackArchive(plan, target);
        check(problem.isEmpty(), "V5n 打包成功", problem);
        check(QFile::exists(target), "V5n 目标文件在盘上");
        check(!QFile::exists(target + QStringLiteral(".part")),
              "V5n 改成目标名之后不留 .part");

        // ① 清单读得回来，而且是**我们自己的解析器**读得回来（这一条才是"装得回去"）
        QByteArray manifest;
        QString readError;
        const ZipUtil::EntryStatus status = ZipUtil::readEntry(
            target, ModpackExport::indexFileName(ModpackExport::Format::Modrinth), &manifest,
            &readError, QStringLiteral("读清单"));
        check(status == ZipUtil::EntryStatus::Ok && !manifest.isEmpty(),
              "V5n 清单在 zip 根、名字就是 modrinth.index.json", readError);
        const ModpackImport::Result round = ModpackImport::parseModrinthIndex(manifest);
        check(round.ok, "V5n 打出来的包我们自己解析得回来", round.problem);
        if (round.ok) {
            check(round.pack.name == QStringLiteral("我的整合包") &&
                      round.pack.gameVersion == QStringLiteral("1.21.1") &&
                      round.pack.loaderKey == ModpackImport::fabricLoaderKey() &&
                      round.pack.loaderVersion == QStringLiteral("0.16.14"),
                  "V5n 包名 / 游戏版本 / 加载器那一行都对",
                  QStringLiteral("%1 %2 %3").arg(round.pack.name, round.pack.gameVersion,
                                                 round.pack.loaderKey));
            check(round.pack.files.size() == 1 &&
                      round.pack.files.first().path == QStringLiteral("mods/认得出来.jar"),
                  "V5n 认出来的那条在清单里，路径是它在实例里的相对路径",
                  QString::number(round.pack.files.size()));
        }

        // ② 认不出来的那条原样躺在 overrides 里，字节一字不差
        const QString unpacked = work + "/解开";
        int extracted = 0;
        QString extractError;
        check(ZipUtil::extractSubtrees({target}, unpacked, {QStringLiteral("overrides/")},
                                       &extracted, &extractError),
              "V5n overrides 解得开（导入走的那条路）", extractError);
        QFile backUnknown(unpacked + "/config/配置.toml");
        check(extracted == 1 && backUnknown.open(QIODevice::ReadOnly) &&
                  backUnknown.readAll() == bytesUnknown,
              "V5n 认不出来的那个文件一个字节都没丢", QString::number(extracted));

        // ③ 覆盖一份已经存在的目标：用户点"替换"之后必须成（Windows 上 rename 不覆盖）
        writeFileAt(target, QByteArrayLiteral("这是用户原来的东西"));
        check(QFile::exists(target), "V5n 前提：目标位置上现在有一个别的文件");
        const QString overwrite = vm.writePackArchive(plan, target);
        check(overwrite.isEmpty(), "V5n 覆盖一份已存在的目标也成", overwrite);
        QByteArray replaced;
        check(ZipUtil::readEntry(target, ModpackExport::indexFileName(ModpackExport::Format::Modrinth),
                                 &replaced, &readError, QStringLiteral("读清单")) ==
                  ZipUtil::EntryStatus::Ok &&
                  replaced == manifest,
              "V5n 覆盖之后盘上那份是新包（原来那份已经不在了）");

        // ④ 取消 / 出问题 / 没有实例目录：一律不写盘
        ModpackExport::ExportPlan cancelled = plan;
        cancelled.cancelled = true;
        const QString cancelTarget = work + "/取消的.mrpack";
        check(!vm.writePackArchive(cancelled, cancelTarget).isEmpty() &&
                  !QFile::exists(cancelTarget) &&
                  !QFile::exists(cancelTarget + QStringLiteral(".part")),
              "V5n 用户叫停时什么都不写（连 .part 都不留）");
        ModpackExport::ExportPlan noDir = plan;
        noDir.instanceDir.clear();
        const QString noDirTarget = work + "/没有实例目录.mrpack";
        check(!vm.writePackArchive(noDir, noDirTarget).isEmpty() &&
                  !QFile::exists(noDirTarget),
              "V5n 计划里没有实例目录时如实报错，不打一个缺东西的残包");

        // ⑤ CurseForge 那一档：清单的名字和正文都得跟着换
        ModpackExport::ExportPlan cfPlan = plan;
        cfPlan.spec.format = ModpackExport::Format::CurseForge;
        cfPlan.spec.files.clear();
        ModpackExport::MatchedRef cfRef;
        cfRef.projectId = 394468;
        cfRef.fileId = 5123456;
        cfPlan.spec.refs.append(cfRef);
        const QString cfTarget = work + "/cf包.zip";
        const QString cfProblem = vm.writePackArchive(cfPlan, cfTarget);
        check(cfProblem.isEmpty(), "V5n CurseForge 那一档也打得出来", cfProblem);
        QByteArray cfManifest;
        check(ZipUtil::readEntry(cfTarget, QStringLiteral("manifest.json"), &cfManifest, &readError,
                                 QStringLiteral("读清单")) == ZipUtil::EntryStatus::Ok &&
                  ModpackImport::parseCurseForgeManifest(cfManifest).ok,
              "V5n 那一个包里装的是 manifest.json（不是 modrinth.index.json），自己解析得回来",
              readError);

        QDir(work).removeRecursively();
    }

    // --- V5q. 条目表长到命令行塞不下时也要打得出来 -----------------------------
    //
    // 2026-09-26 在真实例上撞的（用户的「海波篮子」「永利制造翻译测试版」都是这个死法）：
    // createZip 原来把整张 `@('条目名','盘上路径')` 表**拼进脚本正文**，而脚本是经
    // `-EncodedCommand` 用**命令行**递给 PowerShell 的 —— Windows 一条命令行只有 32767 个
    // 字符，Base64（×4/3）再加 UTF-16LE（×2）之后脚本只剩一万二千来个字符。133 个模组的
    // 实例光那张表就一万七千多字符 ⇒ CreateProcess 直接失败，用户看到「打包失败」
    // （日志里是「解压没跑起来（Process failed to start: 文件名或扩展名太长。）」，
    // 连主语都是错的 —— 见 runPowershell 的 what 参数）。
    //
    // **小夹具看不见这个**：V5n 那两条条目、T21 那几个文件，拼出来的命令行都短得很。
    // 所以这一节**故意摆两百条**、名字照真实例的长度来，并且顺手把"表本身超过命令行能装
    // 下的量"这条前提也钉住 —— 谁要是把条目数改小，前提那条会先红。
    {
        const QString work = sandbox + "/export-long-table";
        QDir(work).removeRecursively();
        QDir().mkpath(work + "/src");

        QList<ZipUtil::ZipSource> entries;
        int tableChars = 0;
        for (int i = 0; i < 200; ++i) {
            const QString name =
                QStringLiteral("某个名字挺长的模组文件-%1.jar").arg(i, 3, 10, QLatin1Char('0'));
            ZipUtil::ZipSource entry;
            entry.entryName = QStringLiteral("overrides/mods/") + name;
            entry.sourcePath = work + QStringLiteral("/src/") + name;
            writeFileAt(entry.sourcePath, QByteArrayLiteral("bytes-") + QByteArray::number(i));
            entries.append(entry);
            // 老实现拼出来的那一行（`@('名','路径'),`）大约是多长：这条前提算的就是它。
            tableChars += entry.entryName.size() + entry.sourcePath.size() + 7;
        }
        check(entries.size() == 200 && tableChars > 12000,
              "V5q 前提：这张表本身就超过了一条命令行能装下的量（老实现拼进脚本必然起不来）",
              QStringLiteral("%1 条 / %2 字符").arg(entries.size()).arg(tableChars));

        const QString target = work + QStringLiteral("/两百条.mrpack");
        QString problem;
        const bool built = ZipUtil::createZip(target, entries, &problem);
        check(built && QFile::exists(target),
              "★ V5q 两百条条目也打得出来（表留在命令行上时这里是「文件名或扩展名太长」）",
              problem);

        // 真读回来一遍：这是导入那条路用的同一个口，条目数对不上就说明包是残的。
        int extracted = -1;
        QString extractError;
        const bool readBack =
            ZipUtil::extractSubtrees({target}, work + QStringLiteral("/out"),
                                     {QStringLiteral("overrides")}, &extracted, &extractError);
        check(readBack && extracted == 200,
              "★ V5q 两百条一条不落地解得回来（条目名里的中文与长度都没被压坏）",
              QStringLiteral("%1 条 %2").arg(extracted).arg(extractError));

        QByteArray got;
        QString entryError;
        const QString firstName = QStringLiteral("overrides/mods/某个名字挺长的模组文件-007.jar");
        check(ZipUtil::readEntry(target, firstName, &got, &entryError,
                                 QStringLiteral("读条目")) == ZipUtil::EntryStatus::Ok &&
                  got == QByteArrayLiteral("bytes-7"),
              "V5q 随便挑一条，名字与字节都对得上", entryError);

        QDir(work).removeRecursively();
    }

    // --- V5r. 只读探针：把**用户真那个实例**就地打一遍（要环境变量才跑） --------------
    //
    // V5q 是"照真实例的量级编一份"，这一节是"就地拿真的那份"—— 用户那两台机器上的死法
    // 只有真的那份文件清单能复现（133 个模组、真名字、真路径长度）。
    //
    // 默认**不跑**：路径写在别人的机器上不存在，做成常驻断言就是一条必然假红。要跑就：
    //   WTFML_PROBE_DIRS=<一行一个实例目录的 UTF-8 清单>  WTFML_PROBE_OUT=<产物落点>
    // 名字走**清单文件**而不是环境变量：实例名里全是中文，而 Windows 上 qgetenv 拿的是
    // 本地 8 位（GBK），从环境变量读中文路径必然踩编码。
    //
    // **被探的那棵目录一个字节都不写**（只枚举 + 只读），产物（zip）落进 WTFML_PROBE_OUT。
    {
        const QString probeList = QString::fromLocal8Bit(qgetenv("WTFML_PROBE_DIRS"));
        const QString probeOut = QString::fromLocal8Bit(qgetenv("WTFML_PROBE_OUT"));
        if (!probeList.isEmpty() && !probeOut.isEmpty()) {
            QFile listFile(probeList);
            const bool haveList = listFile.open(QIODevice::ReadOnly);
            if (!haveList) {
                out() << "  PROBE 读不了清单 " << probeList << "\n";
            } else {
                QDir().mkpath(probeOut);
                const QStringList dirs =
                    QString::fromUtf8(listFile.readAll())
                        .split(QLatin1Char('\n'), Qt::SkipEmptyParts);
                for (const QString &line : dirs) {
                    const QString instanceDir = line.trimmed();
                    if (instanceDir.isEmpty()) {
                        continue;
                    }
                    // 反查一律"没成"：这一节量的是**打包**（一个文件都不许丢），不是认不认得出。
                    const ModpackExport::ModrinthQuery deadQuery =
                        [](const QStringList &, QHash<QString, ModpackExport::ModrinthHit> *,
                           QString *) { return false; };
                    ModpackExport::ExportRequest request;
                    request.format = ModpackExport::Format::Modrinth;
                    request.instanceDir = instanceDir;
                    request.name = QDir(instanceDir).dirName();
                    request.version = QStringLiteral("1.0.0");
                    request.gameVersion = QStringLiteral("1.20.1");
                    request.loaderKey = ModpackImport::fabricLoaderKey();
                    request.loaderVersion = QStringLiteral("0.16.14");
                    const ModpackExport::ExportPlan plan = ModpackExport::buildExportPlan(
                        request, deadQuery, ModpackExport::CurseForgeQuery());
                    // 清单要**先落到盘上**（打包那一步只认盘上那份，和生产那条路一样）。
                    QTemporaryDir staging;
                    const QString manifestPath = QDir(staging.path()).absoluteFilePath(
                        ModpackExport::indexFileName(plan.spec.format));
                    writeFileAt(manifestPath, ModpackExport::buildIndexFile(plan.spec));
                    const QList<ZipUtil::ZipSource> entries =
                        ModpackExport::archiveEntries(plan, manifestPath);
                    int tableChars = 0;
                    for (const ZipUtil::ZipSource &entry : entries) {
                        tableChars += entry.entryName.size() + entry.sourcePath.size() + 7;
                    }
                    const QString target =
                        probeOut + QLatin1Char('/') + request.name + QStringLiteral(".mrpack.part");
                    QFile::remove(target);
                    QElapsedTimer timer;
                    timer.start();
                    QString problem;
                    const bool built = ZipUtil::createZip(target, entries, &problem);
                    const qint64 elapsed = timer.elapsed();
                    QFile written(target);
                    const qint64 zipBytes = written.size();
                    out() << "  PROBE " << request.name << " : " << (built ? "OK" : "FAIL")
                          << "  条目 " << entries.size() << " / overrides " << plan.overrides.size()
                          << " / 认出来 " << plan.matched << "  表 " << tableChars << " 字符"
                          << "  " << zipBytes << " 字节  " << elapsed << " ms\n";
                    if (!built) {
                        out() << "        " << problem << "\n";
                        continue;
                    }
                    // 三条抽查：头一条、中间一条、末一条 overrides，名字与字节都要和盘上那份
                    // 一字不差（条目名拼错是**静默**的，只有比字节才看得见）。
                    const QList<qsizetype> spots = {0, plan.overrides.size() / 2,
                                                    plan.overrides.size() - 1};
                    for (const qsizetype index : spots) {
                        if (index < 0 || index >= plan.overrides.size()) {
                            continue;
                        }
                        const ModpackExport::InstanceFile &one = plan.overrides.at(index);
                        const QString entryName = QStringLiteral("overrides/") + one.path;
                        QByteArray got;
                        QString entryError;
                        const ZipUtil::EntryStatus status =
                            ZipUtil::readEntry(target, entryName, &got, &entryError,
                                               QStringLiteral("读条目"));
                        QFile source(instanceDir + QLatin1Char('/') + one.path);
                        const bool sourceOpen = source.open(QIODevice::ReadOnly);
                        const bool same = sourceOpen && source.readAll() == got;
                        out() << "        抽查 " << entryName << " : "
                              << (status == ZipUtil::EntryStatus::Ok ? "读到了" : "读不到")
                              << " / " << (same ? "字节一致" : "字节不一致") << "（" << got.size()
                              << " 字节）\n";
                    }
                }
            }
        }
    }

    // --- V5v. 用户挑的那张背景图是怎么收进数据目录的（主题那两张图） -----------------
    //
    // 2026-09-28 用户原话：「能给主页左侧自定义图像吗？其他页面的背景能换图吗」。设置页
    // 里那两行「选择图片…」按下去之后走的就是 `ThemeImage::store()`：**把他挑的那张拷一份
    // 进数据目录**，而不是记着他自己那个路径（三条理由写在 `src/util/ThemeImage.hpp` 的
    // 文件头里：图会被挪走、图可能在慢盘上、一张手机照片解出来是 48 MB 位图）。
    //
    // 这一整节在**临时数据根目录**里跑（`AppPaths::setMinecraftDir()` 一处切换，和
    // runIconCacheTests 那一段同一形状）：下面这些断言全都要"看着 cache/theme 里现在有哪
    // 几个文件"，不隔离就是拿用户盘上已经存着的那张图做实验。跑完必须还原 —— 所以这一节里
    // **一条 return 都不许有**（连"读不到夹具就 return"那种也不行，夹具那一条只在有它时再往下）。
    {
        const QString originalDir = AppPaths::minecraftDir();
        QTemporaryDir themeRoot;
        QTemporaryDir sourceRoot;
        check(themeRoot.isValid() && sourceRoot.isValid(),
              "V5v 两个临时目录建出来了（临时数据根目录 + 放源图的那个）");
        AppPaths::setMinecraftDir(themeRoot.path());
        const QString src = sourceRoot.path();
        const QString slotA = QStringLiteral("homeLeft");
        const QString slotB = QStringLiteral("pageBackground");
        const QString slotC = QStringLiteral("titleBar");
        QString error;

        // 前提：这会儿 cache/theme **还不存在**。下面第一条 store() 能成，才说明那个目录是
        // 它自己按需建的（写盘前那一次 mkpath），不是靠谁先替它摆好了。
        check(!QFileInfo::exists(AppPaths::themeImageDir()),
              "V5v 前提：cache/theme 这会儿还不存在");

        // 源图三张，各有各要证的那一条：带透明的 PNG（必须存成 .png）、不带透明的 JPEG
        //（存成 .jpg）、3000 px 宽的大图（长边必须被缩到 2560 以内）。
        const QString alphaPng = src + QStringLiteral("/带透明.png");
        const QString plainJpg = src + QStringLiteral("/不透明.jpg");
        const QString bigJpg = src + QStringLiteral("/大图.jpg");
        {
            QImage withAlpha(64, 32, QImage::Format_ARGB32);
            withAlpha.fill(QColor(255, 0, 0, 128));
            check(withAlpha.save(alphaPng, "PNG"), "V5v 造出一张带透明的 PNG");
            QImage opaque(64, 32, QImage::Format_RGB32);
            opaque.fill(QColor(0, 0, 255));
            check(opaque.save(plainJpg, "JPG", 92), "V5v 造出一张不带透明的 JPEG");
            QImage big(3000, 1500, QImage::Format_RGB32);
            big.fill(QColor(0, 128, 0));
            check(big.save(bigJpg, "JPG", 92), "V5v 造出一张 3000x1500 的大图");
        }

        // ① 带透明的那张：落点固定 `<数据目录>/cache/theme/<槽位>.png`。
        const QString storedPng = ThemeImage::store(slotA, alphaPng, &error);
        check(!storedPng.isEmpty() && error.isEmpty(), "V5v 带透明的 PNG 收得进来", error);
        check(storedPng == AppPaths::themeImageDir() + QLatin1Char('/') + slotA +
                               QStringLiteral(".png") &&
                  !storedPng.contains(QLatin1Char('\\')),
              "V5v 落点是 <数据目录>/cache/theme/<槽位>.png（正斜杠，槽位名就是文件名）",
              storedPng);
        {
            const QImage back(storedPng);
            check(!back.isNull() && back.size() == QSize(64, 32),
                  "V5v 收进来那一份读得回来、尺寸没变",
                  QStringLiteral("%1x%2").arg(back.width()).arg(back.height()));
        }

        // ② 不带透明的那张存成 .jpg（省下一半以上的地方）。
        const QString storedJpg = ThemeImage::store(slotB, plainJpg, &error);
        check(storedJpg == AppPaths::themeImageDir() + QLatin1Char('/') + slotB +
                               QStringLiteral(".jpg"),
              "V5v 不带透明的存成 .jpg", storedJpg);

        // ③ 名字撒谎的那张：同一段 JPEG 字节换个 .png 的名字挑进来，**后缀仍然跟着内容走**。
        //    这一条是"用户把桌面上的图重命名过"的日常 —— 认名字的话这里就存出一份 .png。
        const QString lyingPng = src + QStringLiteral("/名字是png其实是jpeg.png");
        QFile::copy(plainJpg, lyingPng);
        const QString storedLying = ThemeImage::store(slotB, lyingPng, &error);
        check(storedLying == storedJpg &&
                  !QFileInfo::exists(AppPaths::themeImageDir() + QLatin1Char('/') + slotB +
                                     QStringLiteral(".png")),
              "★ V5v 扩展名跟着内容走：名字叫 .png 的 JPEG 也没留下一份 .png",
              storedLying);

        // ④ 大图 + "一个槽位只有一份"：换过扩展名的那份旧图必须被删掉，不能攒着。
        const QString storedBig = ThemeImage::store(slotA, bigJpg, &error);
        check(!storedBig.isEmpty(), "V5v 大图也收得进来", error);
        {
            const QImage back(storedBig);
            check(back.size() == QSize(2560, 1280),
                  "★ V5v 长边被缩到 2560（3000 原样就是 48 MB 位图换一块 1200 px 宽的底）",
                  QStringLiteral("%1x%2").arg(back.width()).arg(back.height()));
        }
        check(!QFileInfo::exists(AppPaths::themeImageDir() + QLatin1Char('/') + slotA +
                                 QStringLiteral(".png")) &&
                  QFileInfo::exists(storedBig),
              "★ V5v 同一个槽位换图之后盘上只剩一份（先是 .png，这回是 .jpg，旧那份删掉了）",
              storedBig);

        // ⑤ 挑了一张坏的（一段文字当图片）：如实拒绝，而且**原来那张一个字节都不许动**
        //    —— 用户手滑挑错一次，不该顺手把他现在用的那张也弄没。
        const QString notImage = src + QStringLiteral("/不是图片.png");
        writeFileAt(notImage, QByteArrayLiteral("这不是一张图片，只是一段文字。"));
        QByteArray keepBytes;
        {
            QFile keeper(storedBig);
            if (keeper.open(QIODevice::ReadOnly)) {
                keepBytes = keeper.readAll();
            }
        }
        check(!keepBytes.isEmpty(), "V5v 前提：记下了现在那一份的字节");
        const QString broken = ThemeImage::store(slotA, notImage, &error);
        check(broken.isEmpty() && error.contains(QStringLiteral("不是一张能打开的图片")),
              "V5v 一段文字当成图挑进来时如实拒绝（给用户的话里说清了是哪一张）", error);
        QByteArray afterBytes;
        {
            QFile keeper(storedBig);
            if (keeper.open(QIODevice::ReadOnly)) {
                afterBytes = keeper.readAll();
            }
        }
        check(afterBytes == keepBytes,
              "★ V5v 挑坏图那一发没能动到原来那张（字节一模一样）");

        // ⑥ 太大：**只 resize、内容一个字节都不写**（全是 0 也够了 —— 这一条判的是文件大小，
        //    而且判在解码之前，所以它挡的正是"手滑选了个视频/压缩包"）。
        const QString huge = src + QStringLiteral("/太大.png");
        {
            QFile file(huge);
            if (file.open(QIODevice::WriteOnly)) {
                file.resize(ThemeImage::kMaxSourceBytes + 1);
            }
        }
        check(QFileInfo(huge).size() > ThemeImage::kMaxSourceBytes,
              "V5v 前提：造出一个超过 64 MB 的源文件",
              QStringLiteral("%1 字节").arg(QFileInfo(huge).size()));
        const QString tooBig = ThemeImage::store(slotA, huge, &error);
        check(tooBig.isEmpty() && error.contains(QStringLiteral("太大")) &&
                  QFileInfo::exists(storedBig),
              "V5v 超过 64 MB 的源文件当场拒绝（拒绝的那一发也没动原来那张）", error);

        // ⑦ 源文件根本不在（用户挑完就把图删了 / 挪走了）。
        const QString missing =
            ThemeImage::store(slotA, src + QStringLiteral("/根本没这个文件.png"), &error);
        check(missing.isEmpty() && !error.isEmpty(), "V5v 源文件不在时如实拒绝", error);

        // ⑧ 槽位名不安全：这是我们自己那张表给的字符串，这一道防的是"以后有人拿用户输入喂进来"。
        const QString escape = ThemeImage::store(QStringLiteral("../跑出去"), alphaPng, &error);
        check(escape.isEmpty() && !error.isEmpty(),
              "V5v 槽位名里带 ../ 时拒绝（不拿它去拼路径）", error);
        check(!QFileInfo::exists(themeRoot.path() + QStringLiteral("/cache/跑出去.png")) &&
                  !QFileInfo::exists(themeRoot.path() + QStringLiteral("/跑出去.png")),
              "★ V5v 那一发一个文件都没写出去（槽位名要是被当路径用，它就跑出 cache/theme 了）");

        // ⑨ 这份 Qt 自己解不了的那种（**webp**）：挑图那个对话框的筛选里写着 `*.webp`，
        //    它就得真的打得开 —— 走的是 `ImageDecode`（WIC）那第二条路。夹具就是 ZC 段
        //    用的同一份（从 Modrinth CDN 上真取下来的 96px 缩略图）。
        QByteArray webpBytes;
        {
            QFile fixture(QStringLiteral(REPO_ROOT_PATH) + "/tests/meta/icon-sample.webp");
            if (fixture.open(QIODevice::ReadOnly)) {
                webpBytes = fixture.readAll();
            }
        }
        check(!webpBytes.isEmpty(), "V5v 读到了 webp 夹具（meta/icon-sample.webp）");
        if (!webpBytes.isEmpty()) {
            const QString webpPath = src + QStringLiteral("/浏览器存下来的.webp");
            writeFileAt(webpPath, webpBytes);
            const QString storedWebp = ThemeImage::store(slotC, webpPath, &error);
            if (ImageDecode::webpAvailable()) {
                check(!storedWebp.isEmpty() && QFileInfo::exists(storedWebp),
                      "★ V5v webp 也收得进来（Qt 认不得，退给 WIC 那条路）", error);
                const QImage back(storedWebp);
                check(back.size() == QSize(96, 96),
                      "V5v webp 收进来的那一份读得回来、尺寸对",
                      QStringLiteral("%1x%2").arg(back.width()).arg(back.height()));
            } else {
                // 这台机器没有那个编解码器（Win10 上多半没有，见 ImageDecode.hpp）：如实拒绝
                // —— 那时候**硬解出个什么来**才是最糟的（存进去一张残图，屏幕上还说是好的）。
                check(storedWebp.isEmpty() && !error.isEmpty(),
                      "V5v 这台机器解不了 webp 时如实拒绝", error);
            }
        }

        // ⑩ remove()：删点名的那一个、不碰别的槽位、没有就什么都不做（不崩、不乱删）。
        ThemeImage::remove(slotA);
        check(!QFileInfo::exists(storedBig), "V5v remove() 把点名那个槽位的那一份删掉了");
        check(QFileInfo::exists(storedJpg), "V5v remove() 不碰别的槽位（另一张还在）");
        ThemeImage::remove(slotA);
        ThemeImage::remove(QStringLiteral("../跑出去"));
        check(QFileInfo::exists(storedJpg),
              "V5v 再删一次 / 槽位名不安全的那一发都什么都不做（盘上一个文件没少）");

        ThemeImage::remove(slotB);
        ThemeImage::remove(slotC);
        check(QDir(AppPaths::themeImageDir()).entryList(QDir::Files).isEmpty(),
              "V5v 三个槽位都清干净了，cache/theme 里一份图都不剩");

        AppPaths::setMinecraftDir(originalDir);
        check(AppPaths::minecraftDir() == originalDir, "V5v 数据根目录还原回去了");
    }

    // --- V6. 真清单（779 MB 那个 ATT2 的 modrinth.index.json） -----------------
    {
        const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";
        QFile fixture(metaDir + "/modrinth-index-att2.json");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "V6 读到了真清单 fixture（meta/modrinth-index-att2.json）");
        if (!haveFixture) {
            return;
        }
        const QByteArray json = fixture.readAll();
        fixture.close();

        const ModpackImport::Result r = ModpackImport::parseModrinthIndex(json);
        check(r.ok, "V6 真的那一份清单解析通过", r.problem);
        if (!r.ok) {
            return;
        }
        const ModpackImport::Pack &pack = r.pack;
        check(pack.gameVersion == QStringLiteral("1.20.2") &&
                  pack.loaderKey == QStringLiteral("fabric-loader") &&
                  pack.loaderVersion == QStringLiteral("0.16.14"),
              "V6 依赖表读对了：1.20.2 + fabric-loader 0.16.14",
              QStringLiteral("%1 / %2 %3").arg(pack.gameVersion, pack.loaderKey,
                                               pack.loaderVersion));
        check(pack.files.size() >= 100 && pack.filesSkipped == 0,
              "V6 一百多条文件全在，一条都没被误判成该跳过",
              QStringLiteral("留下 %1、跳过 %2").arg(pack.files.size()).arg(pack.filesSkipped));

        // 这一条是这一节里最值钱的：真实的 150 条路径，逐条过判据。判据要是严错了一点
        // （比如把"名字里带点"当非法），真包会被整包拒绝 —— 而那个症状是"用户选了自己
        // 的整合包，启动器说这个包的文件清单不安全"。
        int unsafe = 0;
        QString firstUnsafe;
        int longest = 0;
        for (const ModpackImport::PackFile &file : pack.files) {
            if (!ModpackImport::isSafeRelativePath(file.path)) {
                ++unsafe;
                if (firstUnsafe.isEmpty()) {
                    firstUnsafe = file.path;
                }
            }
            if (file.path.size() > longest) {
                longest = static_cast<int>(file.path.size());
            }
        }
        check(unsafe == 0, "V6 真清单里 150 条路径一条都没被判成不安全",
              unsafe == 0 ? QStringLiteral("最长的 %1 个字符").arg(longest)
                          : QStringLiteral("%1 条，第一条是 %2").arg(unsafe).arg(firstUnsafe));

        // 界面预填的那个名字（包名推出来的）必须过得了数据层的校验，否则用户一进
        // 输入框就撞一句报错，而他什么都没输。
        const QString suggested = ModpackImport::suggestInstanceName(pack.name);
        check(InstanceFiles::validateRenameTarget(suggested, QString()).isEmpty(),
              "V6 从真包名推出来的实例名过得了校验",
              QStringLiteral("「%1」→「%2」").arg(pack.name, suggested));
    }
}

/// 一个只答 CurseForge 那两条路的假接口（127.0.0.1、随机端口）。
///
/// ZG7 用它把**中间那一发**钉住 —— 上面几节钉的都是两头（清单进 / 答复出），而"地址拼成
/// 什么样、正文写成什么样、带了哪个头、答复怎么落回 pack"只有在这里量得出来。它不碰外网，
/// 在哪台机器上跑都是同一个结果。
///
/// NOTE: 正文必须**按 Content-Length 收全了再答**，答完带着 `Connection: close` 关掉。
///       理由：HttpClient 那一侧用的是同一个 QNAM（VersionManager::loaderNetworkManager），
///       Qt 会把连接留着复用，而"一个连接上只答一发"那种图省事的写法（本文件里 V6f 那两
///       个假镜像就是这个形状 —— 它们**故意**不答）在第二个请求上会一声不响地不答，那一发
///       就得等满 15 秒超时，整节的结论全变。
struct FakeCurseForgeApi {
    QTcpServer server;
    int filesStatus = 200;
    QByteArray filesBody;
    int modsStatus = 200;
    QByteArray modsBody;
    int filesHits = 0;
    int modsHits = 0;
    QStringList paths;    ///< 每一发问的那条路径（按到的次序）
    QList<QByteArray> bodies;
    QStringList apiKeys;  ///< 每一发带的 x-api-key（**没带 = 空串**，这一档要能分出来）

    bool start() {
        QObject::connect(&server, &QTcpServer::newConnection, &server, [this]() {
            while (QTcpSocket *socket = server.nextPendingConnection()) {
                socket->setParent(&server);
                QObject::connect(socket, &QTcpSocket::readyRead, socket,
                                 [this, socket]() { onReadyRead(socket); });
            }
        });
        return server.listen(QHostAddress::LocalHost, 0);
    }

    QString baseUrl() const {
        // 结尾**不带**斜杠：和产品自己拼地址的写法一致（curseForgeApiBase 结尾会去掉它）。
        return QStringLiteral("http://127.0.0.1:%1/v1").arg(server.serverPort());
    }

    void onReadyRead(QTcpSocket *socket) {
        QByteArray buffer = socket->property("buffer").toByteArray() + socket->readAll();
        const int headerEnd = buffer.indexOf("\r\n\r\n");
        if (headerEnd < 0) {
            socket->setProperty("buffer", buffer);  // 头还没到齐
            return;
        }
        const QByteArray head = buffer.left(headerEnd);
        const QByteArray rest = buffer.mid(headerEnd + 4);
        int length = 0;
        QString apiKey;
        QString path;
        for (const QByteArray &line : head.split('\n')) {
            const QByteArray trimmed = line.trimmed();
            const int colon = trimmed.indexOf(':');
            if (colon > 0) {
                const QByteArray name = trimmed.left(colon).trimmed().toLower();
                const QString value = QString::fromUtf8(trimmed.mid(colon + 1)).trimmed();
                if (name == QByteArrayLiteral("content-length")) {
                    length = value.toInt();
                } else if (name == QByteArrayLiteral("x-api-key")) {
                    apiKey = value;
                }
            } else if (trimmed.startsWith(QByteArrayLiteral("POST "))) {
                path = QString::fromUtf8(trimmed.split(' ').value(1));
            }
        }
        if (rest.size() < length) {
            socket->setProperty("buffer", buffer);  // 正文还没到齐
            return;
        }
        socket->setProperty("buffer", QByteArray());

        const bool isFiles = path.endsWith(QStringLiteral("/mods/files"));
        if (isFiles) {
            ++filesHits;
        } else {
            ++modsHits;
        }
        paths << path;
        bodies << rest.left(length);
        apiKeys << apiKey;

        const int status = isFiles ? filesStatus : modsStatus;
        const QByteArray payload = isFiles ? filesBody : modsBody;
        socket->write(QByteArrayLiteral("HTTP/1.1 ") + QByteArray::number(status) + ' ' +
                      (status == 200 ? QByteArrayLiteral("OK") : QByteArrayLiteral("Error")) +
                      QByteArrayLiteral("\r\nContent-Type: application/json\r\nContent-Length: ") +
                      QByteArray::number(payload.size()) +
                      QByteArrayLiteral("\r\nConnection: close\r\n\r\n") + payload);
        socket->flush();
        socket->disconnectFromHost();
    }
};

static void runCurseForgeTests() {
    section("ZG. CurseForge 的整合包：号 → 文件 → 落点（纯函数，全程不联网）");

    // ---------------------------------------------------------------------
    // 这个格式和 Modrinth 那一份最要紧的差别：**清单里一条地址都没有**，只有
    // `projectID` / `fileID` 两个号（真清单长这样：{"projectID":238222,"fileID":8971390,
    // "required":true}）。所以这一条路是两段：解析清单读号（ZG2）、拿号换文件（ZG3）、
    // 拿 modId 问类目决定落哪个目录（ZG4）。中间那一发网络请求在 VersionManager 里
    // （resolveCurseForgeFiles），这一节钉的是它两头的纯函数 —— 而"号写错了、正文错位、
    // 名字不安全"这些错全都发生在这两头，且都不报错（只是静默装错东西）。
    // ---------------------------------------------------------------------

    // --- ZG1. 加载器那一行怎么拆 ---------------------------------------------
    {
        // CurseForge 把名字和版本拼在一个串里：`forge-47.2.0`。拆错了的症状是
        // "装了个加载器、但版本不对"，而游戏起不来时那句话说的是"模组加载器没找到"。
        struct Case {
            const char *raw;
            const char *key;
            const char *version;
            bool known;
        };
        const Case cases[] = {
            {"forge-47.2.0", "forge", "47.2.0", true},
            {"fabric-0.15.11", "fabric-loader", "0.15.11", true},   // 注意：键要翻成
            {"neoforge-20.4.1", "neoforge", "20.4.1", true},        // Modrinth 那套名字
            {"quilt-0.20.0", "quilt-loader", "0.20.0", true},
            {"forge", "forge", "", true},                            // 老包只写名字
            {"neoForge-20.4.1-beta", "neoforge", "20.4.1-beta", true},  // 大小写 + 后缀
            {"liteloader-1.12.2", "liteloader", "1.12.2", false},    // 认不出来
        };
        int bad = 0;
        QString detail;
        for (const Case &c : cases) {
            QString key;
            QString version;
            const bool known = ModpackImport::curseForgeLoaderKey(QString::fromLatin1(c.raw), &key,
                                                                  &version);
            if (known != c.known || key != QString::fromLatin1(c.key) ||
                version != QString::fromLatin1(c.version)) {
                ++bad;
                if (detail.isEmpty()) {
                    detail = QStringLiteral("%1 → %2 / %3 / %4")
                                 .arg(QString::fromLatin1(c.raw), key, version,
                                      known ? QStringLiteral("认得") : QStringLiteral("不认得"));
                }
            }
        }
        check(bad == 0, "ZG1 七种写法都拆对了（名字 / 版本 / 认不认得）", detail);

        // 这一条是**独立的**：认不出来的加载器**也要给出键**。给空串的话，下游
        // unsupportedLoaderText() 会把 `liteloader-1.12.2` 当成"纯原版整合包"放行 ——
        // 装出来一堆 mod 躺在 mods/ 里、游戏按原版起，而且一路上一个问题都不报。
        QString unknownKey;
        QString unknownVersion;
        ModpackImport::curseForgeLoaderKey(QStringLiteral("liteloader-1.12.2"), &unknownKey,
                                          &unknownVersion);
        check(!unknownKey.isEmpty(),
              "ZG1 认不出来的加载器也给得出键（空串在下游 = 纯原版包 = 装出来进不去）",
              unknownKey);

        // 空串进来：什么都不炸，键是空的、版本是空的。
        QString emptyKey = QStringLiteral("没被清掉");
        QString emptyVersion = QStringLiteral("没被清掉");
        check(!ModpackImport::curseForgeLoaderKey(QString(), &emptyKey, &emptyVersion) &&
                  emptyKey.isEmpty() && emptyVersion.isEmpty(),
              "ZG1 空串 → 不认得 + 两个出参都是空的（不清空会让调用方读到上一条的值）");

        // 出参允许传 null（调用方只关心"认不认得"的时候）—— 崩在那一句上就太难查了。
        check(!ModpackImport::curseForgeLoaderKey(QStringLiteral("rift-1.0"), nullptr, nullptr),
              "ZG1 两个出参都给 nullptr 也不崩");
    }

    // --- ZG2. 解析 manifest.json --------------------------------------------
    {
        // 一份**照真包写的**清单：字段名一个字母都不差（projectID / fileID 这两个的
        // 大写 ID 是 CurseForge 自己的写法，写错一个大小写就等于这个包一条文件都没有）。
        const QByteArray manifest = R"json({
            "minecraft": {
                "version": "1.20.1",
                "modLoaders": [{"id": "forge-47.2.0", "primary": true}]
            },
            "manifestType": "minecraftModpack",
            "manifestVersion": 1,
            "name": "Test Pack",
            "version": "1.4.2",
            "author": "someone",
            "files": [
                {"projectID": 238222, "fileID": 8971390, "required": true},
                {"projectID": 306612, "fileID": 1000001, "required": false},
                {"projectID": 306612, "fileID": 1000001, "required": true}
            ],
            "overrides": "overrides"
        })json";

        const ModpackImport::Result r = ModpackImport::parseCurseForgeManifest(manifest);
        check(r.ok, "ZG2 一份合法清单解析通过", r.problem);
        if (r.ok) {
            const ModpackImport::Pack &pack = r.pack;
            check(pack.format == ModpackImport::Format::CurseForge &&
                      pack.gameVersion == QStringLiteral("1.20.1") &&
                      pack.name == QStringLiteral("Test Pack") &&
                      pack.version == QStringLiteral("1.4.2"),
                  "ZG2 格式 / 游戏版本 / 包名 / 包版本都对",
                  QStringLiteral("%1 | %2").arg(pack.gameVersion, pack.name));
            check(pack.loaderKey == QStringLiteral("forge") &&
                      pack.loaderVersion == QStringLiteral("47.2.0"),
                  "ZG2 加载器那一行翻译成了本启动器认的键",
                  pack.loaderKey + QStringLiteral(" ") + pack.loaderVersion);
            // **`files` 一定是空的** —— 地址要等接口那一发。这条断言是这条路的核心约定：
            // 谁要是"顺手"在这里塞一个空 PackFile 进去，数据层那道"没换过就别装"的闸
            // 就永远不响，用户拿到的会是一个只有加载器的空实例。
            check(pack.files.isEmpty() && pack.pendingRefs.size() == 2,
                  "ZG2 号都在 pendingRefs 里、files 是空的（地址要等接口那一发）",
                  QStringLiteral("files %1 / refs %2")
                      .arg(pack.files.size())
                      .arg(pack.pendingRefs.size()));
            check(pack.fileCount() == 2,
                  "ZG2 重复的那个 fileID 只算一条（同一条要下两遍 = 两份作业抢一个路径）",
                  QString::number(pack.fileCount()));
            check(pack.overridesDir == QStringLiteral("overrides") &&
                      pack.clientOverridesDir.isEmpty(),
                  "ZG2 覆盖目录按清单写的那一个；CurseForge 没有 client-overrides 这个规矩",
                  pack.overridesDir + QStringLiteral(" / ") + pack.clientOverridesDir);
            check(pack.pendingRefs.value(0).projectId == 238222 &&
                      pack.pendingRefs.value(0).fileId == 8971390,
                  "ZG2 两个号都读出来了（projectID / fileID 的大小写写错就一条都不剩）");
        }

        const auto problemOf = [](const QByteArray &json) {
            const ModpackImport::Result res = ModpackImport::parseCurseForgeManifest(json);
            return res.ok ? QString() : res.problem;
        };
        check(problemOf(QByteArray("这不是 json")).contains(QStringLiteral("读不懂")),
              "ZG2 不是 json：说「读不懂」");
        check(problemOf(QByteArray("{}")).contains(QStringLiteral("manifestVersion")),
              "ZG2 缺 manifestVersion/files：说它不是整合包清单");
        check(problemOf(R"json({"manifestVersion":1,"files":[],
                                "manifestType":"factorioModpack",
                                "minecraft":{"version":"1.20.1"}})json")
                  .contains(QStringLiteral("Minecraft")),
              "ZG2 manifestType 写着别的游戏：说「这不是 Minecraft 的整合包」");
        // **缺** manifestType 不拒（手改过的老包常常没有这一条，而它不影响能不能装）。
        const ModpackImport::Result noType = ModpackImport::parseCurseForgeManifest(
            R"json({"manifestVersion":1,"minecraft":{"version":"1.20.1"},
                    "files":[{"projectID":1,"fileID":2}]})json");
        check(noType.ok, "ZG2 缺 manifestType 照样解析（那两条骨架字段才是判据）", noType.problem);
        check(problemOf(R"json({"manifestVersion":1,"files":[{"projectID":1,"fileID":2}],
                                "minecraft":{"modLoaders":[{"id":"fabric-0.15.11"}]}})json")
                  .contains(QStringLiteral("minecraft.version")),
              "ZG2 没写基于哪个版本：拒绝（连装个纯原版都不知道装哪个）");
        check(problemOf(R"json({"manifestVersion":1,"files":[],"minecraft":{"version":"1.21"}})json")
                  .contains(QStringLiteral("空的")),
              "ZG2 一条文件都没有：拒绝（装出来会是个空实例）");

        // 加载器那一条：`primary` 在第二条时不许挑第一条（真包里有写好几条的）。
        const ModpackImport::Result multi = ModpackImport::parseCurseForgeManifest(
            R"json({"manifestVersion":1,"files":[{"projectID":1,"fileID":2}],
                    "minecraft":{"version":"1.20.1",
                    "modLoaders":[{"id":"fabric-0.15.11"},{"id":"forge-47.2.0","primary":true}]}})json");
        check(multi.ok && multi.pack.loaderKey == QStringLiteral("forge"),
              "ZG2 modLoaders 写了好几条时挑 primary 那一条（不是第一条）",
              multi.ok ? multi.pack.loaderKey : multi.problem);
        // 一条都没有 = 纯原版整合包，不是错误。
        const ModpackImport::Result vanilla = ModpackImport::parseCurseForgeManifest(
            R"json({"manifestVersion":1,"files":[{"projectID":1,"fileID":2}],
                    "minecraft":{"version":"1.20.1","modLoaders":[]}})json");
        check(vanilla.ok && vanilla.pack.loaderKey.isEmpty(),
              "ZG2 一条加载器都没有：纯原版整合包，放行", vanilla.problem);

        // 覆盖目录名是**外部输入**（它会被拼成一条路径前缀）。不安全时退回默认名，
        // 而不是把整包拒掉 —— 少解几个 config 是小事，写到实例目录外面是大事。
        const ModpackImport::Result evil = ModpackImport::parseCurseForgeManifest(
            R"json({"manifestVersion":1,"files":[{"projectID":1,"fileID":2}],
                    "minecraft":{"version":"1.20.1"},"overrides":"../evil"})json");
        check(evil.ok && evil.pack.overridesDir == QStringLiteral("overrides"),
              "ZG2 overrides 写着 ../evil：退回默认那一个，包照样能装",
              evil.ok ? evil.pack.overridesDir : evil.problem);
        // 真包里有自己起名的（`overrides-1.20.1` 那种），安全的要原样用。
        const ModpackImport::Result named = ModpackImport::parseCurseForgeManifest(
            R"json({"manifestVersion":1,"files":[{"projectID":1,"fileID":2}],
                    "minecraft":{"version":"1.20.1"},"overrides":"overrides-1.20.1"})json");
        check(named.ok && named.pack.overridesDir == QStringLiteral("overrides-1.20.1"),
              "ZG2 清单自己起的覆盖目录名（overrides-1.20.1）原样用",
              named.ok ? named.pack.overridesDir : named.problem);

        // 号是 0 / 负数 / 字符串的条目一律丢（丢一条只是少一个文件，`toInt()` 丢进来的
        // 0 会让接口那一发带着一个无效号去问，而那一发失败会**整包停下**）。
        const ModpackImport::Result junk = ModpackImport::parseCurseForgeManifest(
            R"json({"manifestVersion":1,"minecraft":{"version":"1.20.1"},
                    "files":[{"projectID":0,"fileID":5},{"projectID":3,"fileID":-1},
                             {"projectID":"4","fileID":"6"},{"projectID":7,"fileID":8},
                             "不是对象"]})json");
        check(junk.ok && junk.pack.pendingRefs.size() == 1 &&
                  junk.pack.pendingRefs.value(0).projectId == 7,
              "ZG2 号是 0 / 负数 / 字符串的条目一律丢掉（不是当成 0 号去问）",
              junk.ok ? QString::number(junk.pack.pendingRefs.size()) : junk.problem);
    }

    // --- ZG3. 请求体 + 接口答复 ----------------------------------------------
    {
        // 请求体的形状写错（键名、号是数字还是字符串）时接口回 400，而 400 的正文里只有
        // 一句 {"error":"…"} —— 看着和"这个包坏了"一模一样。所以键名和类型在这儿钉住。
        const QList<ModpackImport::PackRef> refs = {{238222, 8971390}, {306612, 1000001}};
        const QJsonObject filesBody =
            QJsonDocument::fromJson(ModpackImport::curseForgeFilesRequestBody(refs)).object();
        const QJsonArray fileIds = filesBody.value(QStringLiteral("fileIds")).toArray();
        check(filesBody.size() == 1 && fileIds.size() == 2 && fileIds.at(0).isDouble() &&
                  fileIds.at(0).toInt() == 8971390 && fileIds.at(1).toInt() == 1000001,
              "ZG3 问文件那一发的正文是 {\"fileIds\":[数字…]}（键名和类型都要对）",
              QString::fromUtf8(QJsonDocument(filesBody).toJson(QJsonDocument::Compact)));

        const QJsonObject modsBody = QJsonDocument::fromJson(
            ModpackImport::curseForgeModsRequestBody({238222, 306612})).object();
        const QJsonArray modIds = modsBody.value(QStringLiteral("modIds")).toArray();
        check(modsBody.size() == 1 && modIds.size() == 2 && modIds.at(0).isDouble(),
              "ZG3 问类目那一发的正文是 {\"modIds\":[数字…]}",
              QString::fromUtf8(QJsonDocument(modsBody).toJson(QJsonDocument::Compact)));

        // 一份照真响应写的答复：**顺序和问的相反**，而且其中一个作者关了第三方分发
        // （`downloadUrl` 是 null）、一个查不到。真响应里的 hashes 数组常常 md5 在前。
        const QByteArray reply = R"json({"data":[
            {"id":1000001,"modId":306612,"fileName":"b.jar","fileLength":2048,
             "downloadUrl":null,
             "hashes":[{"value":"bbbb","algo":1},{"value":"cccc","algo":2}]},
            {"id":8971390,"modId":238222,"fileName":"a.jar","fileLength":1024,
             "downloadUrl":"https://edge.forgecdn.net/files/8971/390/a.jar",
             "hashes":[{"value":"dddd","algo":2},{"value":"aaaa","algo":1}]}
        ]})json";
        const QList<ModpackImport::PackRef> asked = {{238222, 8971390},
                                                     {306612, 1000001},
                                                     {999, 555}};  // 最后一个查不到
        const ModpackImport::CurseForgeFiles parsed =
            ModpackImport::parseCurseForgeFileInfo(reply, asked);
        check(parsed.problem.isEmpty() && parsed.resolved.size() == 1 &&
                  parsed.notDistributable == 1 && parsed.missing == 1,
              "ZG3 三条问出去：换到 1 条、1 条作者不许代下、1 条查不到（三类分得开）",
              parsed.problem.isEmpty()
                  ? QStringLiteral("换到 %1 / 不许 %2 / 查不到 %3")
                        .arg(parsed.resolved.size())
                        .arg(parsed.notDistributable)
                        .arg(parsed.missing)
                  : parsed.problem);
        if (parsed.resolved.size() == 1) {
            const ModpackImport::CurseForgeFile &file = parsed.resolved.first();
            // **这一条是这一节里最值钱的**：正文的次序和问的次序相反，按位置取会把
            // a.jar 的地址安到 b.jar 上（症状是"装完有几个 mod 是错的"，比少装可怕）。
            check(file.file.path == QStringLiteral("a.jar") && file.modId == 238222 &&
                      file.file.size == 1024 &&
                      file.file.urls.value(0).contains(QStringLiteral("a.jar")),
                  "ZG3 答复的次序被打乱也认得出哪条是哪条（按 fileId 归档，不按位置）",
                  file.file.path + QStringLiteral(" / ") + file.file.urls.join(QStringLiteral(",")));
            // `hashes` 里 algo==1 那条才是 sha1；拿 hashes[0] 的话这一条拿到的是 md5
            // （下载完每一条都会被判成"校验不过"，而字节数是对的 —— 极难查）。
            check(file.file.sha1 == QStringLiteral("aaaa"),
                  "ZG3 sha1 取的是 algo==1 那一条，不是数组的第 0 条", file.file.sha1);
        }
        check(parsed.projectIds.size() == 1 && parsed.projectIds.value(0) == 238222,
              "ZG3 只有换到了的才需要去问类目（不许代下 / 查不到的那两个不用问）",
              QStringLiteral("%1 个").arg(parsed.projectIds.size()));

        // 文件名是**外部输入**，它要拼进路径。往外跳的那两条当场算"查不到"，而
        // **整包不拒绝**（和 Modrinth 那份清单不同：那边路径是作者写在清单里的）。
        const QByteArray evilNames = R"json({"data":[
            {"id":1,"modId":10,"fileName":"../evil.jar","fileLength":1,
             "downloadUrl":"https://example.invalid/1","hashes":[]},
            {"id":2,"modId":11,"fileName":"a/../../b.jar","fileLength":1,
             "downloadUrl":"https://example.invalid/2","hashes":[]},
            {"id":3,"modId":12,"fileName":"ok.jar","fileLength":1,
             "downloadUrl":"https://example.invalid/3","hashes":[]},
            {"id":4,"modId":13,"fileName":"sub/dir.jar","fileLength":1,
             "downloadUrl":"https://example.invalid/4","hashes":[]}
        ]})json";
        const ModpackImport::CurseForgeFiles sec = ModpackImport::parseCurseForgeFileInfo(
            evilNames, {{10, 1}, {11, 2}, {12, 3}, {13, 4}});
        QStringList secPaths;
        for (const ModpackImport::CurseForgeFile &entry : sec.resolved) {
            secPaths << entry.file.path;
        }
        check(sec.problem.isEmpty() && sec.missing == 2 && sec.resolved.size() == 2 &&
                  secPaths.contains(QStringLiteral("ok.jar")) &&
                  secPaths.contains(QStringLiteral("sub/dir.jar")),
              "ZG3 往外跳的两条（../evil.jar、a/../../b.jar）算查不到，另两条照收",
              QStringLiteral("坏 %1 / 好 %2「%3」")
                  .arg(sec.missing)
                  .arg(sec.resolved.size())
                  .arg(secPaths.join(QStringLiteral(", "))));
        // 名字里带一段目录**是放行的**（判据只问"能不能安全地拼进实例目录"，不问
        // "它长不长成一个文件名"）：它会落在 `mods/sub/dir.jar`。这一条是**反过来**钉
        // 上面那条 —— 免得哪天把"名字里有斜杠"一律当成攻击，拒掉正常的内容。
        check(secPaths.contains(QStringLiteral("sub/dir.jar")),
              "ZG3 名字里带一段目录（sub/dir.jar）放行，不当成攻击", secPaths.join(QStringLiteral(", ")));

        // 字节数越界（或者干脆不是数）= 不知道字节数（-1）。越界的 double 转 qint64 是
        // 未定义行为，而那个负数会变成一个永远下不完的作业。
        const QByteArray weirdSize = R"json({"data":[
            {"id":1,"modId":10,"fileName":"a.jar","fileLength":1e30,
             "downloadUrl":"https://example.invalid/1","hashes":[]},
            {"id":2,"modId":11,"fileName":"b.jar",
             "downloadUrl":"https://example.invalid/2","hashes":[]}
        ]})json";
        const ModpackImport::CurseForgeFiles sizes =
            ModpackImport::parseCurseForgeFileInfo(weirdSize, {{10, 1}, {11, 2}});
        check(sizes.resolved.size() == 2 && sizes.resolved.value(0).file.size == -1 &&
                  sizes.resolved.value(1).file.size == -1,
              "ZG3 字节数越界 / 缺这一项 → 当「不知道」（-1），不是强转成一个负数",
              QStringLiteral("%1 / %2")
                  .arg(sizes.resolved.value(0).file.size)
                  .arg(sizes.resolved.value(1).file.size));

        // 接口出错时正文里只有一句 error（没有 data）。那句话**要原样带给用户** ——
        // 我们猜不出来它为什么拒。
        // NOTE: 这一段的正文**不能写成 R"json(…)json" 再交给 QByteArrayLiteral()** ——
        //       那是宏，一进预处理器的参数扫描就把带自定义定界符的原始字符串看错了
        //       （报的是"unterminated raw string"，指着一行完全正常的写法）。转义写法。
        const QByteArray deniedBody = QByteArrayLiteral("{\"error\":\"Invalid API key\"}");
        const ModpackImport::CurseForgeFiles denied =
            ModpackImport::parseCurseForgeFileInfo(deniedBody, asked);
        check(denied.problem.contains(QStringLiteral("Invalid API key")) &&
                  denied.resolved.isEmpty(),
              "ZG3 接口回的是 {\"error\":…}：把接口那句话原样带出去", denied.problem);
        check(!ModpackImport::parseCurseForgeFileInfo(QByteArray("不是 json"), asked)
                   .problem.isEmpty(),
              "ZG3 答复读不懂：problem 非空（这一档会让整件事停下来）");
    }

    // --- ZG4. 落点：哪一类文件进哪个目录 -------------------------------------
    {
        // 判据是**类目号**，不是文件名的后缀（.zip 既可能是资源包也可能是存档，而
        // fileName 是接口给的、可以随便起）。认不出来的一律落 mods/。
        check(ModpackImport::curseForgeFilePath(6) == QStringLiteral("mods/") &&
                  ModpackImport::curseForgeFilePath(12) == QStringLiteral("resourcepacks/") &&
                  ModpackImport::curseForgeFilePath(6552) == QStringLiteral("shaderpacks/") &&
                  ModpackImport::curseForgeFilePath(17) == QStringLiteral("saves/") &&
                  ModpackImport::curseForgeFilePath(0) == QStringLiteral("mods/") &&
                  ModpackImport::curseForgeFilePath(12345) == QStringLiteral("mods/"),
              "ZG4 六种类目号各自落在对的目录，认不出来的一律 mods/");
        check(ModpackImport::curseForgeFilePath(4471).isEmpty(),
              "ZG4 嵌套的整合包（4471）回空串 = 这一条不下",
              ModpackImport::curseForgeFilePath(4471));

        const auto makeFile = [](const QString &name, int modId) {
            ModpackImport::CurseForgeFile file;
            file.file.path = name;
            file.file.urls.append(QStringLiteral("https://example.invalid/") + name);
            file.modId = modId;
            return file;
        };
        const QList<ModpackImport::CurseForgeFile> resolved = {
            makeFile(QStringLiteral("a.jar"), 100),          // 模组
            makeFile(QStringLiteral("pack.zip"), 101),       // 资源包
            makeFile(QStringLiteral("shader.zip"), 102),     // 光影
            makeFile(QStringLiteral("world.zip"), 103),      // 存档
            makeFile(QStringLiteral("nested.zip"), 104),     // 嵌套整合包
            makeFile(QStringLiteral("unknown.jar"), 105),    // 类目号问不到
        };
        QHash<int, int> classIds;
        classIds.insert(100, 6);
        classIds.insert(101, 12);
        classIds.insert(102, 6552);
        classIds.insert(103, 17);
        classIds.insert(104, 4471);
        // 105 故意不放进表里 —— 第二发失败时就是这样。

        const ModpackImport::CurseForgePlacement placed =
            ModpackImport::placeCurseForgeFiles(resolved, classIds);
        check(placed.files.size() == 5 && placed.skipped == 1 && placed.missing == 0,
              "ZG4 六个文件：五个落好、嵌套整合包记一笔跳过（不拦整件事）",
              QStringLiteral("落 %1 / 跳 %2 / 丢 %3")
                  .arg(placed.files.size())
                  .arg(placed.skipped)
                  .arg(placed.missing));
        QStringList landed;
        for (const ModpackImport::PackFile &file : placed.files) {
            landed << file.path;
        }
        check(landed.contains(QStringLiteral("mods/a.jar")) &&
                  landed.contains(QStringLiteral("resourcepacks/pack.zip")) &&
                  landed.contains(QStringLiteral("shaderpacks/shader.zip")) &&
                  landed.contains(QStringLiteral("saves/world.zip")) &&
                  landed.contains(QStringLiteral("mods/unknown.jar")),
              "ZG4 路径逐条都对（包括问不到类目的那条落到 mods/）",
              landed.join(QStringLiteral(" | ")));

        // 文件名长到加上目录之后过不了判据：这一条记 missing（不是硬塞进去）。
        // **这个数是量出来的、不是随手写的**：240 是整条路径的上限（isSafeRelativePath），
        // 名字本身正好 240（判得过），加上 `mods/` 那 5 个字符就是 245（判不过）——
        // 差 5 个字符，而它决定的是"超长文件名是少一个 mod"还是"下到一半崩在写盘上"。
        const QString huge = QString(236, QLatin1Char('x')) + QStringLiteral(".jar");
        check(ModpackImport::isSafeRelativePath(huge),
              "ZG4 那条超长名字**本身**是合法的（不然这一条测的就不是「拼完再判」）",
              QString::number(huge.length()));
        const ModpackImport::CurseForgePlacement longPaths =
            ModpackImport::placeCurseForgeFiles({makeFile(huge, 100)}, classIds);
        check(longPaths.files.isEmpty() && longPaths.missing == 1,
              "ZG4 拼上目录之后超长的路径记 missing（不是硬塞进下载队列）",
              QStringLiteral("落 %1 / 丢 %2").arg(longPaths.files.size()).arg(longPaths.missing));

        // 两个项目给出同名文件：只留一条（两条同时写一个路径是数据竞争）。
        const ModpackImport::CurseForgePlacement dupe = ModpackImport::placeCurseForgeFiles(
            {makeFile(QStringLiteral("same.jar"), 100), makeFile(QStringLiteral("same.jar"), 100)},
            classIds);
        check(dupe.files.size() == 1, "ZG4 同名文件只留下一条",
              QStringLiteral("留下 %1 条").arg(dupe.files.size()));

        // 空表进来 = 空表出去（这一发一条都没换到时就是这样，调用方按"多少个都不下"处理）。
        const ModpackImport::CurseForgePlacement empty =
            ModpackImport::placeCurseForgeFiles({}, classIds);
        check(empty.files.isEmpty() && empty.skipped == 0 && empty.missing == 0,
              "ZG4 空表进空表出");
    }

    // --- ZG5. 问哪一台接口 ---------------------------------------------------
    {
        // 官方那份要 `x-api-key`（不带 = 403，2026-09-25 实测），所以默认走一台不要 key 的
        // **社区镜像**。这一条链的取舍写在 curseForgeApiBase() 上面：key 编进 exe 就等于公开。
        //
        // ★ 这里**不写死镜像的域名**：它已经换过一次（`api.curse.tools` 整个 403 →
        //   现在这台 `mod.mcimirror.top/curseforge`，见 .cpp 里那段实测），写死的话下次再换
        //   就得记着改这一条 —— 而漏改它**还是绿的**（两边都错得一样，正是 Z7e 那条注释
        //   说的假绿）。要钉的是**性质**，不是那一串字符：
        //     · 非空（不是"忘了给默认值"）；
        //     · https；
        //     · **不是官方那一台**（是的话说明这一档根本没走镜像，而是把官方的地址填了进来，
        //       而官方不带 key 一律 403 ⇒ 整个 CurseForge 那一栏会全空）。
        //   这台镜像**当下通不通**由联网探针管（mw_check `cf-resolve-live`），不归这里。
        const QString noKeyBase = ModpackImport::curseForgeApiBase(QString());
        check(!noKeyBase.isEmpty() && noKeyBase.startsWith(QStringLiteral("https://")) &&
                  !noKeyBase.contains(QStringLiteral("api.curseforge.com")),
              "ZG5 没填 key：走一台不要 key 的社区镜像（不是官方那一台）", noKeyBase);
        // ★ 尾巴上那段 `/v1` **一个字符都不能少**：这个函数的约定是"返回到 `/v1` 为止"，
        //   调用点只往后接 `/mods/search` / `/mods/files` / `/mods/{id}/files`。少了它每一发
        //   都是 404，而**症状和"服务挂了"一模一样**（那一栏什么都搜不出来 / 导入说换不到文件）。
        //   2026-09-26 就是这么踩的：换镜像那一笔把 `/v1` 漏在地址外面了，而这一条链在两个
        //   验证工程里**全是拿假接口验的**（假接口的 base 本身就带 `/v1`）⇒ 四个验证工程
        //   全绿、真网络每一发 404，只有 `cf-resolve-live` 那一跑看得出来。
        //   所以这条断言钉的不是"哪台机器"，是**那台机器后面必须接上 `/v1` 这一段**。
        check(noKeyBase.endsWith(QStringLiteral("/v1")),
              "ZG5 默认那台也带 `/v1` 那一段（少它每一发都是 404，而症状看着像服务挂了）",
              noKeyBase);
        check(ModpackImport::curseForgeApiBase(QStringLiteral("abc")) ==
                  QStringLiteral("https://api.curseforge.com/v1"),
              "ZG5 填了 key：改走官方",
              ModpackImport::curseForgeApiBase(QStringLiteral("abc")));
        // 验证工程的口子优先级最高（离线端到端就靠它把接口指到本机）。
        check(ModpackImport::curseForgeApiBase(QStringLiteral("abc"),
                                               QStringLiteral("http://127.0.0.1:8123/v1")) ==
                  QStringLiteral("http://127.0.0.1:8123/v1"),
              "ZG5 覆盖地址比 key 还优先（验证工程拿它指到本机）");
        // 结尾那个 `/` 去掉：拼地址的地方一律自己带它，用户多打一个不该 404。
        check(ModpackImport::curseForgeApiBase(QString(), QStringLiteral("http://127.0.0.1:8123/v1/")) ==
                  QStringLiteral("http://127.0.0.1:8123/v1"),
              "ZG5 覆盖地址结尾多一个斜杠也认（不然拼出来是两个斜杠）",
              ModpackImport::curseForgeApiBase(
                  QString(), QStringLiteral("http://127.0.0.1:8123/v1/")));
        // 只有空白的 key 等于没填（从网页上复制很容易带一个尾随空格）。
        check(ModpackImport::curseForgeApiBase(QStringLiteral("   ")) == noKeyBase,
              "ZG5 只有空白的 key 当没填（带空格的 key 会一路变成 403）");
    }

    // --- ZG6. 「这个格式还没支持」那句话里不许再有 CurseForge -----------------
    {
        // 这一条钉的是"删干净了"：那个分支留着的话，它的症状是**明明支持却说不行**
        // （两条路都已经走不到了，所以只有靠这条断言防它回来）。
        const QString text = ModpackImport::unsupportedFormatText(ModpackImport::Format::CurseForge);
        check(!text.contains(QStringLiteral("还没")),
              "ZG6 认不出格式那句话里不再说 CurseForge「还没做那一步」", text.left(40));
        // 两句必须一模一样 = 这个函数已经不看格式了（还是两支的话，上面那条会漏掉另一支）。
        check(text == ModpackImport::unsupportedFormatText(ModpackImport::Format::Unknown),
              "ZG6 两种格式给出同一句话（那个函数已经不看参数了）");
        // 那句话本身得有用：两个清单文件名叫什么都得写着。
        check(text.contains(ModpackImport::modrinthIndexName()) &&
                  text.contains(ModpackImport::curseForgeManifestName()),
              "ZG6 那句话把两个清单文件名都写出来（用户才知道自己手上的是不是整合包）", text);
    }

    // --- ZG7. 数据层端到端：号真的发到那台机器上，换回来的东西真的落回 pack ------------
    //
    // 上面几节全是纯函数（两头）。这一节跑**中间那一发**：`VersionManager::resolveCurseForgeFiles`
    // 拼出来的地址、写出来的正文、带上的头，以及答复怎么变成 `pack.files`。
    // 接口是本机的假服务器（`Launcher/CurseForgeApiBase` 就是为这个留的口子，产品从不写它）。
    //
    // 这一节要防的错，全都是"纯函数全绿、但整件事不成"的那种：地址少一个 `/` 变成 404、
    // 正文的键名写成 `fileIDs`、带了 key 却不发 `x-api-key`（官方 403）、
    // 失败时把 pendingRefs 清了（用户再点一次就永远换不回来）。
    {
        // 一份**照真清单写的**包：两条文件，一个模组一个资源包（好验落点分得开）。
        const QByteArray manifestJson = R"json({
            "manifestVersion": 1,
            "manifestType": "minecraftModpack",
            "name": "端到端假包",
            "version": "1.0",
            "minecraft": {"version": "1.20.1",
                          "modLoaders": [{"id": "forge-47.2.0", "primary": true}]},
            "files": [
                {"projectID": 238222, "fileID": 8971390, "required": true},
                {"projectID": 101, "fileID": 55, "required": true}
            ]
        })json";

        const auto freshPack = [&manifestJson](ModpackImport::Pack *out) {
            const ModpackImport::Result parsed =
                ModpackImport::parseCurseForgeManifest(manifestJson);
            if (!parsed.ok) {
                return false;
            }
            *out = parsed.pack;
            return true;
        };
        const auto jsonOf = [](const QByteArray &bytes) {
            return QJsonDocument::fromJson(bytes).object();
        };

        FakeCurseForgeApi api;
        api.filesBody = R"json({"data":[
            {"id":8971390,"modId":238222,"fileName":"a.jar","fileLength":1024,
             "downloadUrl":"https://edge.forgecdn.net/files/8971/390/a.jar",
             "hashes":[{"value":"aa11","algo":1}]},
            {"id":55,"modId":101,"fileName":"pack.zip","fileLength":2048,
             "downloadUrl":"https://edge.forgecdn.net/files/0/55/pack.zip",
             "hashes":[{"value":"bb22","algo":1}]}
        ]})json";
        api.modsBody = R"json({"data":[{"id":238222,"classId":6},{"id":101,"classId":12}]})json";
        check(api.start(), "ZG7 本机假接口起来了（起不来这一节就没意义，直接算失败）");
        if (api.server.isListening()) {
            // ---- ZG7a 顺利的那一条：两发都发出去、两发都答回来、落地 ----
            {
                VersionManager manager;
                // 这一句就是"把接口指到本机上"的全部（产品自己从不写这个键）。
                manager.setCurseForgeApiBaseOverride(api.baseUrl());
                ModpackImport::Pack pack;
                check(freshPack(&pack), "ZG7 前提：那份清单解析得出来");
                check(pack.pendingRefs.size() == 2 && pack.files.isEmpty(),
                      "ZG7 前提：解析完就是「两个号、零条地址」");

                const QString problem = manager.resolveCurseForgeFiles(&pack);
                check(problem.isEmpty(), "ZG7a 换地址这一发没报错", problem);
                check(api.filesHits == 1 && api.modsHits == 1,
                      "ZG7a 两发都发出去了（号→文件 一发，类目 一发）",
                      QStringLiteral("files %1 / mods %2").arg(api.filesHits).arg(api.modsHits));
                check(api.paths.value(0) == QStringLiteral("/v1/mods/files") &&
                          api.paths.value(1) == QStringLiteral("/v1/mods"),
                      "ZG7a 两条路径拼对了（少一个斜杠就是 404，那看着像「这个包坏了」）",
                      api.paths.join(QStringLiteral(", ")));
                const QJsonArray fileIds = jsonOf(api.bodies.value(0))
                                               .value(QStringLiteral("fileIds")).toArray();
                const QJsonArray modIds = jsonOf(api.bodies.value(1))
                                              .value(QStringLiteral("modIds")).toArray();
                check(fileIds.size() == 2 && fileIds.at(0).toInt() == 8971390 &&
                          fileIds.at(1).toInt() == 55,
                      "ZG7a 早一发问的就是清单里那两个 fileID（按清单的次序）",
                      QString::fromUtf8(api.bodies.value(0)));
                check(modIds.size() == 2 && modIds.at(0).toInt() == 238222,
                      "ZG7a 后一发问的是那两个 projectID", QString::fromUtf8(api.bodies.value(1)));
                check(api.apiKeys.value(0).isEmpty() && api.apiKeys.value(1).isEmpty(),
                      "ZG7a 没填 key 时**不发** x-api-key 那个头（社区反代不看它）",
                      api.apiKeys.value(0));

                check(pack.files.size() == 2 && pack.pendingRefs.isEmpty(),
                      "ZG7a 换回来的两条落到 files 里、号清空了",
                      QStringLiteral("files %1 / refs %2")
                          .arg(pack.files.size())
                          .arg(pack.pendingRefs.size()));
                QStringList landedPaths;
                for (const ModpackImport::PackFile &file : pack.files) {
                    landedPaths << file.path;
                }
                // 落点是按**类目号**分的（6 是模组、12 是资源包），不是按扩展名。
                check(landedPaths.contains(QStringLiteral("mods/a.jar")) &&
                          landedPaths.contains(QStringLiteral("resourcepacks/pack.zip")),
                      "ZG7a 一个落 mods/、一个落 resourcepacks/（按接口说的类目分）",
                      landedPaths.join(QStringLiteral(", ")));
                if (pack.files.size() == 2) {
                    const ModpackImport::PackFile &first = pack.files.value(0);
                    check(first.urls.value(0) ==
                              QStringLiteral("https://edge.forgecdn.net/files/8971/390/a.jar") &&
                              first.sha1 == QStringLiteral("aa11") && first.size == 1024,
                          "ZG7a 地址 / sha1 / 字节数三样都进了下载那一层（校验照旧一个字不用改）",
                          QStringLiteral("%1 | %2 | %3")
                              .arg(first.urls.value(0), first.sha1)
                              .arg(first.size));
                }
                check(pack.filesNotDistributable == 0 && pack.filesMissing == 0 &&
                          pack.filesSkipped == 0,
                      "ZG7a 一个「没换到」都没有（三种计数分开走，这里该是三个 0）");

                // 再调一次：**一个请求都不发**。上面界面那一半会对着同一个包再问一次，
                // 靠的就是这一条早退（判据是 pendingRefs 空不空）——
                // 没有它，每点一次确认框就多一发请求（还是对着别人那份反代打的）。
                const QString again = manager.resolveCurseForgeFiles(&pack);
                check(again.isEmpty() && api.filesHits == 1 && api.modsHits == 1,
                      "ZG7a 换过一次的包再调一次：一个请求都不发（不然确认框点几次打几发）",
                      QStringLiteral("files %1 / mods %2").arg(api.filesHits).arg(api.modsHits));
            }

            // ---- ZG7b 填了 key：那一发必须带 x-api-key（不带 = 官方 403）----
            {
                FakeCurseForgeApi keyed;
                keyed.filesBody = api.filesBody;
                keyed.modsBody = api.modsBody;
                check(keyed.start(), "ZG7b 第二个假接口起来了");
                if (keyed.server.isListening()) {
                    VersionManager manager;
                    manager.setCurseForgeApiKey(QStringLiteral("只有这一份的 key"));
                    manager.setCurseForgeApiBaseOverride(keyed.baseUrl());
                    ModpackImport::Pack pack;
                    freshPack(&pack);
                    const QString problem = manager.resolveCurseForgeFiles(&pack);
                    check(problem.isEmpty() && keyed.filesHits == 1,
                          "ZG7b 带了 key 的那一发照旧问得成", problem);
                    check(keyed.apiKeys.value(0) == QStringLiteral("只有这一份的 key"),
                          "ZG7b 发出去的 x-api-key 就是用户填的那一份（一个字都不能变，"
                          "多一个空格就是 403）",
                          keyed.apiKeys.value(0));
                }
            }

            // ---- ZG7c 早一发失败：整件事停下，一个字节都不装 ----
            {
                FakeCurseForgeApi failing;
                failing.filesStatus = 500;
                failing.filesBody =
                    QByteArrayLiteral("{\"error\":\"Invalid API key\"}");
                check(failing.start(), "ZG7c 会失败的假接口起来了");
                if (failing.server.isListening()) {
                    VersionManager manager;
                    manager.setCurseForgeApiBaseOverride(failing.baseUrl());
                    ModpackImport::Pack pack;
                    freshPack(&pack);
                    const QString problem = manager.resolveCurseForgeFiles(&pack);
                    check(!problem.isEmpty(), "ZG7c 早一发失败 → 有话说（不是静默地装个空实例）");
                    // 接口自己那句话要**原样带给用户**：我们猜不出来它为什么拒。
                    check(problem.contains(QStringLiteral("HTTP 500")) &&
                              problem.contains(QStringLiteral("Invalid API key")),
                          "ZG7c 那句话里带着 HTTP 码和接口的原话", problem);
                    // 反代是**别人的服务** ⇒ 必须给出一条用户自己走得了的路。
                    check(problem.contains(QStringLiteral("CurseForge API key")),
                          "ZG7c 那句话里指出了「可以填自己的 key」这条出路", problem);
                    check(pack.files.isEmpty() && pack.pendingRefs.size() == 2,
                          "ZG7c 换不成时 files 还是空的、号**一个都没清**（用户再点一次还能再换）",
                          QStringLiteral("files %1 / refs %2")
                              .arg(pack.files.size())
                              .arg(pack.pendingRefs.size()));
                    check(failing.modsHits == 0,
                          "ZG7c 早一发就停了，**没有**接着问类目（省一发，也免得把话说岔）");
                }
            }

            // ---- ZG7d 429：走"限流"那句话，不把官方那个错误码端给用户 ----
            {
                FakeCurseForgeApi throttled;
                throttled.filesStatus = HttpClient::kStatusTooManyRequests;
                check(throttled.start(), "ZG7d 会回 429 的假接口起来了");
                if (throttled.server.isListening()) {
                    VersionManager manager;
                    manager.setCurseForgeApiBaseOverride(throttled.baseUrl());
                    ModpackImport::Pack pack;
                    freshPack(&pack);
                    const QString problem = manager.resolveCurseForgeFiles(&pack);
                    check(problem.contains(QStringLiteral("HTTP 429")) &&
                              problem.contains(QStringLiteral("请求太频繁")),
                          "ZG7d 429 走「限流」那句话（唯一出处是 HttpClient::throttledText）",
                          problem);
                }
            }

            // ---- ZG7e 类目那一发失败：只降级，不拦整件事 ----
            {
                FakeCurseForgeApi half;
                half.filesBody = api.filesBody;
                half.modsStatus = 500;
                half.modsBody = QByteArrayLiteral("{\"error\":\"boom\"}");
                check(half.start(), "ZG7e 只有类目那一发会失败的假接口起来了");
                if (half.server.isListening()) {
                    QStringList told;
                    VersionManager manager;
                    QObject::connect(&manager, &VersionManager::modpackImportMessage, &manager,
                                     [&told](const QString &message) { told << message; });
                    manager.setCurseForgeApiBaseOverride(half.baseUrl());
                    ModpackImport::Pack pack;
                    freshPack(&pack);
                    const QString problem = manager.resolveCurseForgeFiles(&pack);
                    // 缺的只是"落到哪个目录"，文件本身下得下来 —— 停在这里等于因为一个
                    // "放哪儿"的问题把一个能装的包拒了。
                    check(problem.isEmpty() && pack.files.size() == 2,
                          "ZG7e 类目那一发没成**不拦整件事**，两个文件照收", problem);
                    QStringList fallbackPaths;
                    for (const ModpackImport::PackFile &file : pack.files) {
                        fallbackPaths << file.path;
                    }
                    check(fallbackPaths.contains(QStringLiteral("mods/a.jar")) &&
                              fallbackPaths.contains(QStringLiteral("mods/pack.zip")),
                          "ZG7e 认不出类目的一律落 mods/（不是丢掉，也不是猜一个目录）",
                          fallbackPaths.join(QStringLiteral(", ")));
                    check(told.size() == 1 && told.value(0).contains(QStringLiteral("mods/")),
                          "ZG7e 降级这件事要在日志里留一句（不然用户只看到资源包进了 mods/）",
                          told.join(QStringLiteral(" / ")));
                }
            }
        }
    }
}

// =========================================================================
// Z 节：下载页「模组 / 整合包 / 资源包 / 光影」那一层（ResourceCatalog）。
//
// 全是纯函数：一段 JSON 进去、一个结果出来，不联网不碰盘。喂的两份夹具是**真响应原样存下来的**
// （meta/modrinth-search-mod.json = 一次真搜索的三条；meta/modrinth-versions-iris.json =
// Iris 在 1.21.1 + fabric 下的 12 个版本）—— 这一节要证的恰恰是"真响应里那几个字段我们读对了"，
// 自己编一段 JSON 只能证明"我按我以为的格式读了一遍"。
//
// 拼地址那几条**不走"URL 里有没有这段话"那种子串断言**，而是把参数解码回来再当 JSON 读一遍：
// 子串断言在"少了一层方括号"这种错法上照样过（`[["project_type:mod"]]` 去掉一层之后，
// 里面那截字还是原样在的），而那个错在真接口上不报错、只是筛选静默失效。
// =========================================================================

/// 取 URL 里某个查询参数，**按百分号解码回原样**（拼地址那几条断言要读回原值）。
///
/// NOTE: 这里是自己切 `&` / `=` 再 QUrl::fromPercentEncoding，**不是** QUrlQuery。
///       实测（2026-09-23）QUrlQuery 把 `%3A` 解回了 `:`，却把 `%5B` / `%5D` 原样留着 ——
///       它只解"它认为必须解"的那些，于是读回来的是半解码的东西，看着像产品把地址拼错了
///       （三条断言就是这么假红的）。要测的是"拼进去的原值能不能原样读回来"，那就自己解，
///       别用一个自带一套规矩的解析器去验另一个拼串的人。
static QString urlParam(const QString &url, const QString &key) {
    const int question = url.indexOf(QLatin1Char('?'));
    if (question < 0) {
        return QString();
    }
    const QStringList pairs = url.mid(question + 1).split(QLatin1Char('&'));
    for (const QString &pair : pairs) {
        const int equals = pair.indexOf(QLatin1Char('='));
        if (equals > 0 && pair.left(equals) == key) {
            return QUrl::fromPercentEncoding(pair.mid(equals + 1).toUtf8());
        }
    }
    return QString();
}

/// 把一段字符串当 JSON 读（上面那几条断言用它验 facets / game_versions 的形状）。
static QJsonDocument jsonOf(const QString &text) {
    return QJsonDocument::fromJson(text.toUtf8());
}

static void runResourceCatalogTests() {
    const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";

    // ---------------------------------------------------------------------
    section("Z1. 几类资源的键 / 目标目录 / 名字");
    // ---------------------------------------------------------------------

    // 这几个键要和下载页左栏那份分类表里对应的几条**逐字相同**（界面上"点的是哪一类"和
    // "去问哪一类"靠这个字符串对起来）。那份表在 ui/MainWindowUI.hpp，要 QtWidgets 才编得动，
    // verify 这边链不进来 —— 所以那个等号由 ui_check 钉，这里钉的是 API 那边认的那几个词。
    //
    // NOTE: 2026-09-25 加了「数据包」（用户原话「下载那一栏少了个数据包类型，把它放在模组和
    //       资源包中间加上」）—— API 那边认的词是 Modrinth 自己的 `datapack`（不是
    //       `datapacks`，那个是我们落盘用的目录名，两回事）。
    check(ResourceCatalog::kindKey(ResourceCatalog::Kind::Mod) == QStringLiteral("mod") &&
              ResourceCatalog::kindKey(ResourceCatalog::Kind::Modpack) ==
                  QStringLiteral("modpack") &&
              ResourceCatalog::kindKey(ResourceCatalog::Kind::DataPack) ==
                  QStringLiteral("datapack") &&
              ResourceCatalog::kindKey(ResourceCatalog::Kind::Shader) == QStringLiteral("shader") &&
              ResourceCatalog::kindKey(ResourceCatalog::Kind::ResourcePack) ==
                  QStringLiteral("resourcepack"),
          "Z1 五个键就是 API 认的那五个词");

    // 反向要认回来（界面拿的是分类键，不是枚举）。
    int roundTrip = 0;
    for (ResourceCatalog::Kind kind : ResourceCatalog::allKinds()) {
        ResourceCatalog::Kind back = ResourceCatalog::Kind::Mod;
        if (ResourceCatalog::kindFromCategoryKey(ResourceCatalog::kindKey(kind), &back) &&
            back == kind) {
            ++roundTrip;
        }
    }
    check(roundTrip == 5, "Z1 键绕一圈能认回原来的那一类",
          QStringLiteral("认回来 %1/5").arg(roundTrip));

    // 「游戏」那一页也走这条认路，它不是能搜的那几类之一 —— 认不出来时要如实回 false，
    // 不能默认成"那就按模组算"（那会变成"点游戏页却搜出模组"）。
    ResourceCatalog::Kind untouched = ResourceCatalog::Kind::Shader;
    check(!ResourceCatalog::kindFromCategoryKey(QStringLiteral("game"), &untouched) &&
              untouched == ResourceCatalog::Kind::Shader,
          "Z1 「game」认不出来，且没动传进去的那个值");

    check(ResourceCatalog::folderForKind(ResourceCatalog::Kind::Mod) == QStringLiteral("mods") &&
              ResourceCatalog::folderForKind(ResourceCatalog::Kind::DataPack) ==
                  QStringLiteral("datapacks") &&
              ResourceCatalog::folderForKind(ResourceCatalog::Kind::ResourcePack) ==
                  QStringLiteral("resourcepacks") &&
              ResourceCatalog::folderForKind(ResourceCatalog::Kind::Shader) ==
                  QStringLiteral("shaderpacks"),
          "Z1 模组/数据包/资源包/光影各自的目标目录");
    // 整合包**没有**目标目录：它下回来是个 .mrpack，接着走导入那条路，往哪放是清单说了算。
    // 回空串不是偷懒，是"这一类不走这条安装路"的信号。
    check(ResourceCatalog::folderForKind(ResourceCatalog::Kind::Modpack).isEmpty(),
          "Z1 整合包没有目标目录（它走导入那条路）");

    check(ResourceCatalog::kindLabel(ResourceCatalog::Kind::Mod) == QStringLiteral("模组") &&
              ResourceCatalog::kindLabel(ResourceCatalog::Kind::Modpack) ==
                  QStringLiteral("整合包") &&
              ResourceCatalog::kindLabel(ResourceCatalog::Kind::DataPack) ==
                  QStringLiteral("数据包") &&
              ResourceCatalog::kindLabel(ResourceCatalog::Kind::Shader) == QStringLiteral("光影") &&
              ResourceCatalog::kindLabel(ResourceCatalog::Kind::ResourcePack) ==
                  QStringLiteral("资源包"),
          "Z1 五个名字（和下载页左栏那几个字一样）");

    // ---------------------------------------------------------------------
    section("Z2. 搜索地址怎么拼（纯函数，不联网）");
    // ---------------------------------------------------------------------

    const QString plain = ResourceCatalog::searchUrl(ResourceCatalog::Kind::Mod,
                                                    QString(), 0, 20);
    check(plain.startsWith(QStringLiteral("https://api.modrinth.com/v2/search?")),
          "Z2 搜索打在 /v2/search 上");

    // 只按类型筛时 facets 是**一层**：`[["project_type:mod"]]`。
    {
        const QJsonDocument doc = jsonOf(urlParam(plain, QStringLiteral("facets")));
        const QJsonArray outer = doc.array();
        const bool shape = outer.size() == 1 && outer.at(0).isArray() &&
                           outer.at(0).toArray().size() == 1 &&
                           outer.at(0).toArray().at(0).toString() ==
                               QStringLiteral("project_type:mod");
        check(shape, "Z2 只按类型筛：facets 是 [ [ project_type:mod ] ]",
              urlParam(plain, QStringLiteral("facets")));
    }

    // 加了游戏版本和加载器就是**两层里三段**（两层 = "且"，这是 Modrinth 的语法糖）。
    {
        const QString filtered = ResourceCatalog::searchUrl(ResourceCatalog::Kind::Shader,
                                                            QString(), 0, 20,
                                                            QStringLiteral("1.21.1"),
                                                            QStringLiteral("iris"));
        const QJsonArray outer = jsonOf(urlParam(filtered, QStringLiteral("facets"))).array();
        QStringList all;
        for (const QJsonValue &group : outer) {
            for (const QJsonValue &value : group.toArray()) {
                all.append(value.toString());
            }
        }
        check(outer.size() == 3 &&
                  all.contains(QStringLiteral("project_type:shader")) &&
                  all.contains(QStringLiteral("versions:1.21.1")) &&
                  all.contains(QStringLiteral("categories:iris")),
              "Z2 类型 + 游戏版本 + 加载器 = 三段筛选",
              all.join(QLatin1Char(' ')));
    }

    check(urlParam(plain, QStringLiteral("offset")) == QStringLiteral("0") &&
              urlParam(plain, QStringLiteral("limit")) == QStringLiteral("20"),
          "Z2 offset / limit 进得去");
    // 空搜索词按下载量排（"最热门的模组"），有搜索词按相关度排 —— 不然搜「sodium」
    // 的头一条会是名字里带 sodium 但没人用的东西。
    check(urlParam(plain, QStringLiteral("index")) == QStringLiteral("downloads") &&
              urlParam(ResourceCatalog::searchUrl(ResourceCatalog::Kind::Mod,
                                                  QStringLiteral("sodium"), 0, 20),
                       QStringLiteral("index")) == QStringLiteral("relevance"),
          "Z2 空搜索按下载量排、有搜索词按相关度排");

    // 搜索词里的 `&` `=` 必须编码掉。不编码的话拼出来的地址会在第一个 `&` 那里断掉，
    // 用户以为自己搜的是 A 实际搜的是 B —— 而且**不报错**，只是结果不对。
    {
        const QString weird = ResourceCatalog::searchUrl(ResourceCatalog::Kind::Mod,
                                                        QStringLiteral("a&b=c"), 0, 20);
        check(urlParam(weird, QStringLiteral("query")) == QStringLiteral("a&b=c") &&
                  weird.contains(QStringLiteral("query=a%26b%3Dc")),
              "Z2 搜索词里的 & 和 = 编码掉了，读回来还是原样");
        // 参数个数靠 `&` 分隔：多出来一个裸 `&` 就是"搜索词把它劈成两段了"。
        int amps = 0;
        for (const QChar &ch : weird) {
            if (ch == QLatin1Char('&')) {
                ++amps;
            }
        }
        check(amps == 4, "Z2 五个参数正好四个分隔符（没有裸 & 混进来）",
              QStringLiteral("数到 %1 个 &").arg(amps));
    }

    check(ResourceCatalog::searchUrl(ResourceCatalog::Kind::Mod, QString(), 40, 20)
              .contains(QStringLiteral("offset=40")),
          "Z2 翻页的 offset 真的换了");

    // ---------------------------------------------------------------------
    section("Z3. 读真搜索响应（meta/modrinth-search-mod.json）");
    // ---------------------------------------------------------------------

    QByteArray searchJson;
    {
        QFile fixture(metaDir + "/modrinth-search-mod.json");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "Z3 读到了真搜索夹具");
        if (haveFixture) {
            searchJson = fixture.readAll();
            fixture.close();
        }
    }
    ResourceCatalog::SearchResult search = ResourceCatalog::parseSearch(searchJson);

    check(search.ok && search.problem.isEmpty(), "Z3 真响应读得动",
          search.problem);
    check(search.totalHits == 105 && search.hits.size() == 3 && search.limit == 3,
          "Z3 一共多少条 / 这一页几条 都读对了",
          QStringLiteral("total %1、这一页 %2、limit %3")
              .arg(search.totalHits)
              .arg(search.hits.size())
              .arg(search.limit));

    if (search.hits.size() >= 3) {
        const ResourceCatalog::Hit &first = search.hits.at(0);
        check(first.projectId == QStringLiteral("AANobbMI") &&
                  first.slug == QStringLiteral("sodium") &&
                  first.title == QStringLiteral("Sodium") &&
                  first.author == QStringLiteral("jellysquid3"),
              "Z3 第一条的身份字段（Sodium）",
              QStringLiteral("%1 / %2 / %3").arg(first.projectId, first.slug, first.title));
        check(first.downloads == 229545638,
              "Z3 下载量没被 int 截断（2.29 亿 > 32 位）",
              QString::number(first.downloads));
        // 加载器要从那一堆分类标签里挑出来 —— Sodium 的 categories 里还混着 optimization。
        const QStringList loaders = first.loaders();
        check(loaders.contains(QStringLiteral("fabric")) &&
                  loaders.contains(QStringLiteral("neoforge")) &&
                  loaders.contains(QStringLiteral("quilt")) &&
                  !loaders.contains(QStringLiteral("optimization")),
              "Z3 加载器从 categories 里挑得出来，普通标签没混进去",
              loaders.join(QLatin1Char(' ')));
        check(first.gameVersions.contains(QStringLiteral("1.21.1")) &&
                  first.gameVersions.size() > 30,
              "Z3 它支持哪些游戏版本读到了（选游戏版本那一步要用）",
              QStringLiteral("%1 个版本").arg(first.gameVersions.size()));

        // 「选游戏版本」那一列要**新的在前**。而接口给的这份是**旧的在前**（实测 Sodium
        // 从 1.16.3 排到 26.3）—— 和版本接口那边正好相反，所以顺序必须钉住：
        // 反错方向不会报错，只会让用户在一列几十行的最底下找最新版本。
        // 这一条量的是**次序**，所以走 `showSnapshots = true` 那一档：折过之后再比"条数一样、
        // 头对尾"是量不出什么的。折叠本身在 Z8h 里单独验。
        const QStringList choices = ResourceCatalog::gameVersionChoices(first.gameVersions, true);
        check(choices.size() == first.gameVersions.size() &&
                  choices.first() == first.gameVersions.last() &&
                  choices.last() == first.gameVersions.first() &&
                  choices.first() == QStringLiteral("26.3"),
              "Z3 选游戏版本那一列是新的在前（接口给的是旧的在前）",
              choices.isEmpty() ? QString() : choices.first());
    }

    // 图标有**两条**地址：接口给的那条（大多是 webp 缩略图，小 7 倍）原样存进 hit.iconUrl，
    // 自己按 id 拼的那条 PNG 当兜底。这一层不判"这台机器解不解得动" —— 那是 ImageDecode /
    // ResourceStore 的事（见文件头那张表）。
    check(ResourceCatalog::iconUrlForProject(QStringLiteral("AANobbMI")) ==
              QStringLiteral("https://cdn.modrinth.com/data/AANobbMI/icon.png"),
          "Z3 兜底那条是按 project_id 拼出来的 PNG");
    check(ResourceCatalog::iconUrlForProject(QString()).isEmpty(),
          "Z3 没有 id 时不拼出一个空地址");

    // 这三条用的是真响应，里面**两种形状都有**：前两条是 `…_96.webp`，第三条
    // （Bh37bMuy）接口直接给的就是 `…/icon.png`。所以要**按每一条自己判** —— 假定
    // "接口给的一定是 webp"的话，第三条会被送去解 webp，而它本来就是一张 PNG
    //（这正是 isWebpUrl 存在的理由，见 ResourceCatalog.hpp）。
    if (search.hits.size() >= 3) {
        const ResourceCatalog::Hit &sodium = search.hits.at(0);
        check(sodium.iconUrl ==
                  QStringLiteral("https://cdn.modrinth.com/data/AANobbMI/"
                                 "295862f4724dc3f78df3447ad6072b2dcd3ef0c9_96.webp"),
              "Z3 接口给的图标地址**原样**存着（Sodium 那条是带 hash 的 webp 缩略图）",
              sodium.iconUrl);
        check(sodium.iconPngUrl().endsWith(QStringLiteral("/AANobbMI/icon.png")) &&
                  !sodium.iconPngUrl().contains(QStringLiteral(".webp")),
              "Z3 兜底那条仍然是 PNG", sodium.iconPngUrl());
        check(ResourceCatalog::isWebpUrl(sodium.iconUrl),
              "Z3 认出 Sodium 那条是 webp", sodium.iconUrl);
        check(!ResourceCatalog::isWebpUrl(search.hits.at(2).iconUrl) &&
                  search.hits.at(2).iconUrl.endsWith(QStringLiteral("/icon.png")),
              "Z3 第三条接口给的就是 PNG，不能也当成 webp",
              search.hits.at(2).iconUrl);
    }

    // ---------------------------------------------------------------------
    section("Z3b. 接口给的图标地址：只认我们自己那个域名");
    // ---------------------------------------------------------------------

    // 这个串是**外部输入**（从接口正文里读的），而它的下一个用途是"拿去发一个请求"。
    // 所以三件事都要过：https、host 全等 cdn.modrinth.com、以及空串一律当"没给"。
    check(ResourceCatalog::isUsableIconUrl(
              QStringLiteral("https://cdn.modrinth.com/data/AANobbMI/icon.png")),
          "Z3b 正常的一条放行");
    check(ResourceCatalog::isUsableIconUrl(
              QStringLiteral("https://cdn.modrinth.com/data/a/1_96.webp")),
          "Z3b webp 那条也放行（放行的是域名，不是格式）");
    check(!ResourceCatalog::isUsableIconUrl(QString()),
          "Z3b 没给地址 = 不能用（调用方退回自己拼的那条）");
    check(!ResourceCatalog::isUsableIconUrl(
              QStringLiteral("http://cdn.modrinth.com/data/a/icon.png")),
          "Z3b 明文 http 不放行");
    // 这一条是"看着像"的那种：光用 endsWith / contains 判域名的话它会被放行。
    check(!ResourceCatalog::isUsableIconUrl(
              QStringLiteral("https://cdn.modrinth.com.别的.com/data/a/icon.png")),
          "Z3b cdn.modrinth.com.别的.com 不放行（比的是 host 全等）");
    check(!ResourceCatalog::isUsableIconUrl(
              QStringLiteral("https://api.modrinth.com/data/a/icon.png")),
          "Z3b 别的 modrinth 子域不放行");
    check(!ResourceCatalog::isUsableIconUrl(
              QStringLiteral("https://example.com/data/a/icon.png")) &&
              !ResourceCatalog::isUsableIconUrl(
                  QStringLiteral("file:///C:/Windows/System32/calc.exe")),
          "Z3b 别的域名 / 本地文件路径都不放行");

    // 没给 icon_url 的项目（或者给了条别的域名的）→ Hit::iconUrl 是空的，界面走
    // iconPngUrl() 那条。**这一条不能把整个搜索判成失败** —— 少一张图标而已。
    {
        const QByteArray thin = QByteArrayLiteral(
            "{\"hits\":[{\"project_id\":\"AAA\",\"title\":\"x\","
            "\"icon_url\":\"https://evil.example.com/i.png\"},"
            "{\"project_id\":\"BBB\",\"title\":\"y\"}],"
            "\"total_hits\":2,\"offset\":0,\"limit\":2}");
        const ResourceCatalog::SearchResult result = ResourceCatalog::parseSearch(thin);
        check(result.ok && result.hits.size() == 2 &&
                  result.hits.at(0).iconUrl.isEmpty() && result.hits.at(1).iconUrl.isEmpty(),
              "Z3b 别的域名的 / 压根没给的 icon_url 一律当「没给」，搜索照样是成功的");
        check(result.hits.at(1).iconPngUrl().endsWith(QStringLiteral("/BBB/icon.png")),
              "Z3b 当没给之后，兜底那条还是拼得出来");
    }

    // ---------------------------------------------------------------------
    section("Z3c. 批量问图标地址（`GET /projects?ids=…`）");
    // ---------------------------------------------------------------------

    // ★ 2026-09-27 加的（用户原话「模组的图标没有正确加载」）。要这一发的理由见
    //   ResourceCatalog.hpp 里 `iconUrlForProject()` 那段实测：**自己拼的那条
    //   `<id>/icon.png` 只是老项目的别名**，20 个真模组里 11 个回 404。真正那条地址在
    //   带哈希的文件名底下，除了接口没人说得出来。
    check(ResourceCatalog::projectsRequestUrl({QStringLiteral("AANobbMI"),
                                               QStringLiteral("P7dR8mSH")}) ==
              QStringLiteral("https://api.modrinth.com/v2/projects?ids="
                             "%5B%22AANobbMI%22%2C%22P7dR8mSH%22%5D"),
          "★ Z3c ids 那一段是**百分号编码过的 JSON 数组**（写成 `ids=AANobbMI,P7dR8mSH` "
          "这一家不认；这一串 2026-09-27 拿真接口核过：回 200、两个项目都在）",
          ResourceCatalog::projectsRequestUrl({QStringLiteral("AANobbMI"),
                                               QStringLiteral("P7dR8mSH")}));
    check(ResourceCatalog::projectsRequestUrl({QStringLiteral("AANobbMI")},
                                              QStringLiteral("http://127.0.0.1:9/v2")) ==
              QStringLiteral("http://127.0.0.1:9/v2/projects?ids=%5B%22AANobbMI%22%5D"),
          "Z3c 验证工程那个 override 是指根地址（和 /version_files 那一发同一条规矩）");
    check(ResourceCatalog::projectsRequestUrl({}).isEmpty(),
          "★ Z3c 一个号都没有时**不拼地址**（拼出来是个 `ids=[]`，白发一发还白等一次超时）");

    // 答复是一个**数组**（不是搜索那种 `{hits:[…]}`）——按对象读会一条都读不出来，
    // 而"没有图标"和"读不懂"在屏幕上是一个样子。
    {
        const QByteArray reply = QByteArrayLiteral(
            "[{\"id\":\"AANobbMI\",\"icon_url\":\"https://cdn.modrinth.com/data/AANobbMI/"
            "295862f4724dc3f78df3447ad6072b2dcd3ef0c9_96.webp\"},"
            "{\"id\":\"P7dR8mSH\",\"icon_url\":\"https://cdn.modrinth.com/data/P7dR8mSH/"
            "icon.png\"},"
            "{\"id\":\"NOPE0001\",\"icon_url\":\"https://evil.example.com/i.png\"},"
            "{\"id\":\"NOPE0002\"}]");
        const QHash<QString, QString> icons = ResourceCatalog::parseProjectIconUrls(reply);
        check(icons.value(QStringLiteral("AANobbMI")) ==
                  QStringLiteral("https://cdn.modrinth.com/data/AANobbMI/"
                                 "295862f4724dc3f78df3447ad6072b2dcd3ef0c9_96.webp") &&
                  icons.value(QStringLiteral("P7dR8mSH")) ==
                      QStringLiteral("https://cdn.modrinth.com/data/P7dR8mSH/icon.png"),
              "★ Z3c 接口给的那条地址原样读出来（各项目一个哈希，自己拼不出来）");
        check(icons.contains(QStringLiteral("NOPE0001")) &&
                  icons.value(QStringLiteral("NOPE0001")).isEmpty(),
              "★ Z3c 别家域名的 `icon_url` **当没给**（外部输入，过域名闸 —— 见 isUsableIconUrl）");
        check(icons.contains(QStringLiteral("NOPE0002")) &&
                  icons.value(QStringLiteral("NOPE0002")).isEmpty(),
              "Z3c 没带 `icon_url` 的项目 = 没有图标地址（那一格画占位拼图，不是错）");
        check(icons.size() == 4,
              "Z3c 四个项目都在表里（少一个 = 那个项目永远只有占位图，而找不出原因）",
              QString::number(icons.size()));
    }
    check(ResourceCatalog::parseProjectIconUrls(QByteArrayLiteral("{\"hits\":[]}")).isEmpty(),
          "★ Z3c 回了个**对象**（不是数组）时一条都不读 —— 形状不对就是没读到，不猜");
    check(ResourceCatalog::parseProjectIconUrls(QByteArrayLiteral("不是 JSON")).isEmpty() &&
              ResourceCatalog::parseProjectIconUrls(QByteArray()).isEmpty(),
          "Z3c 读不懂 / 空正文 → 空表（不是崩、也不是塞一条空的进来）");

    // ---------------------------------------------------------------------
    section("Z4. 读不动 / 没搜到 是两句话");
    // ---------------------------------------------------------------------

    // 「没搜到」不是错（下面 Z4b），但「没搜成」必须如实报，不能返回一个空列表 ——
    // 空列表到界面上就是"什么都没搜到"，用户会去改搜索词，而真正的问题在网络那头。
    {
        const ResourceCatalog::SearchResult empty =
            ResourceCatalog::parseSearch(QStringLiteral("{}").toUtf8());
        check(!empty.ok && !empty.problem.isEmpty(),
              "Z4 回了个空对象：报错，不是「没搜到」", empty.problem);

        const ResourceCatalog::SearchResult broken =
            ResourceCatalog::parseSearch(QByteArray("<html>502 Bad Gateway</html>"));
        check(!broken.ok && !broken.problem.isEmpty(),
              "Z4 回了一段 HTML（网关挡了）：报错", broken.problem);

        // 真接口出错时回的是 `{"error":..,"description":..}`。把那句话原样带给用户 ——
        // 它比我们编的"搜索失败"有用得多。
        const ResourceCatalog::SearchResult apiError = ResourceCatalog::parseSearch(
            QByteArray(R"({"error":"invalid_input","description":"Invalid facets"})"));
        check(!apiError.ok && apiError.problem.contains(QStringLiteral("Invalid facets")),
              "Z4 接口自己说的话带出来了", apiError.problem);

        // 真回了个空数组 = 问到了、就是没有。这是 ok。
        const ResourceCatalog::SearchResult none = ResourceCatalog::parseSearch(
            QByteArray(R"({"hits":[],"offset":0,"limit":20,"total_hits":0})"));
        check(none.ok && none.hits.isEmpty() && none.totalHits == 0,
              "Z4b 空 hits 算「问到了、没有」（ok=true）", none.problem);
    }

    // ---------------------------------------------------------------------
    section("Z5. 下载量那串字（唯一一处换单位）");
    // ---------------------------------------------------------------------

    check(ResourceCatalog::formatDownloads(0) == QStringLiteral("0") &&
              ResourceCatalog::formatDownloads(9999) == QStringLiteral("9999") &&
              ResourceCatalog::formatDownloads(10000) == QStringLiteral("1.0 万") &&
              ResourceCatalog::formatDownloads(1234567) == QStringLiteral("123.5 万") &&
              ResourceCatalog::formatDownloads(99990000) == QStringLiteral("9999.0 万") &&
              ResourceCatalog::formatDownloads(229545638) == QStringLiteral("2.3 亿"),
          "Z5 万 / 亿 两个坎上的输出",
          QStringLiteral("%1 | %2 | %3 | %4")
              .arg(ResourceCatalog::formatDownloads(10000),
                   ResourceCatalog::formatDownloads(1234567),
                   ResourceCatalog::formatDownloads(99990000),
                   ResourceCatalog::formatDownloads(229545638)));
    check(ResourceCatalog::formatDownloads(-1).isEmpty(),
          "Z5 负数（接口没给）回空串，不回「-1」");

    // ---------------------------------------------------------------------
    section("Z6. 版本列表地址与真版本列表（meta/modrinth-versions-iris.json）");
    // ---------------------------------------------------------------------

    {
        const QString url = ResourceCatalog::versionsUrl(QStringLiteral("YL57xq9U"),
                                                        QStringLiteral("1.21.1"),
                                                        QStringLiteral("fabric"));
        const QJsonDocument gv = jsonOf(urlParam(url, QStringLiteral("game_versions")));
        const QJsonDocument ld = jsonOf(urlParam(url, QStringLiteral("loaders")));
        check(gv.isArray() && gv.array().size() == 1 &&
                  gv.array().at(0).toString() == QStringLiteral("1.21.1") &&
                  ld.isArray() && ld.array().size() == 1 &&
                  ld.array().at(0).toString() == QStringLiteral("fabric"),
              "Z6 版本地址按游戏版本 + 加载器筛",
              url);

        // 没选游戏版本时**不问**筛条件（界面在用户还没选版本时不该把范围缩掉）。
        const QString bare = ResourceCatalog::versionsUrl(QStringLiteral("YL57xq9U"),
                                                          QString());
        check(bare.endsWith(QStringLiteral("/project/YL57xq9U/version")),
              "Z6 不筛的时候地址上不带问号", bare);
    }

    QByteArray versionsJson;
    {
        QFile fixture(metaDir + "/modrinth-versions-iris.json");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "Z6 读到了真版本列表夹具");
        if (haveFixture) {
            versionsJson = fixture.readAll();
            fixture.close();
        }
    }
    const QList<ResourceCatalog::VersionEntry> versions =
        ResourceCatalog::parseVersions(versionsJson);

    check(versions.size() == 12, "Z6 12 个版本一条不多一条不少",
          QStringLiteral("%1 条").arg(versions.size()));

    if (versions.size() == 12) {
        // **顺序**：接口给的是**新的在前**。一开始按"大概是从旧到新"的直觉写了个反向，
        // 那样列表头条会是最老的那个版本，而且不报错 —— 所以这条要钉住。
        bool descending = true;
        for (int i = 1; i < versions.size(); ++i) {
            if (versions.at(i).datePublished >= versions.at(i - 1).datePublished) {
                descending = false;
            }
        }
        check(descending && versions.first().datePublished > versions.last().datePublished,
              "Z6 顺序是新在前（别再反向遍历一次）",
              QStringLiteral("%1 → %2").arg(versions.first().versionNumber,
                                            versions.last().versionNumber));

        const ResourceCatalog::VersionEntry &newest = versions.first();
        check(newest.id == QStringLiteral("bAo1Qhte") &&
                  newest.versionNumber == QStringLiteral("1.8.14-beta.1+1.21.1-fabric") &&
                  newest.versionType == QStringLiteral("beta"),
              "Z6 最新那条的身份字段",
              QStringLiteral("%1 (%2)").arg(newest.versionNumber, newest.versionType));
        check(newest.gameVersions.contains(QStringLiteral("1.21.1")) &&
                  newest.loaders.contains(QStringLiteral("fabric")),
              "Z6 它自己写着支持 1.21.1 / fabric",
              newest.gameVersions.join(QLatin1Char(' ')));

        // 每一条都得有一个能下的文件 —— 界面上"点不动"比"下错了"更难查。
        int withFile = 0;
        int badSha = 0;
        for (const ResourceCatalog::VersionEntry &version : versions) {
            const ResourceCatalog::FileEntry *file = version.primaryFile();
            if (file == nullptr || file->url.isEmpty() || file->filename.isEmpty() ||
                file->size <= 0) {
                continue;
            }
            ++withFile;
            if (file->sha1.size() != 40) {
                ++badSha;
            }
        }
        check(withFile == 12, "Z6 12 条都能挑出一个要下的文件",
              QStringLiteral("%1/12").arg(withFile));
        // sha1 要留着 —— 下载那边就是靠它校验"下全了没有"（这是"重下=校验跳过"那条的判据）。
        check(badSha == 0, "Z6 每条都带 40 位的 sha1",
              QStringLiteral("%1 条不对").arg(badSha));

        // 前置模组：Iris 最新那条钉着 Sodium（required）。这一轮不出按钮，但数据得先读对 ——
        // 读错了等症状暴露的时候，是在"装完启动崩"那里，离这里很远。
        const QList<ResourceCatalog::Dependency> deps =
            ResourceCatalog::requiredDependenciesOf(versions, newest.id);
        check(deps.size() == 1 && deps.at(0).projectId == QStringLiteral("AANobbMI") &&
                  deps.at(0).required(),
              "Z6 前置模组读出来了（Iris → Sodium）",
              deps.isEmpty() ? QStringLiteral("一条都没有")
                             : deps.at(0).projectId);
        // 钉错的版本号不该"顺手返回第一条"——那会给用户装一个不匹配的前置。
        check(ResourceCatalog::requiredDependenciesOf(versions,
                                                     QStringLiteral("不存在的一版"))
                  .isEmpty(),
              "Z6 版本号对不上时回空清单，不猜一条");
    }

    // 读不动就回空列表：界面那边是"这个资源在 1.21.1 上没有版本"，不是崩。
    check(ResourceCatalog::parseVersions(QByteArray("not json")).isEmpty(),
          "Z6b 版本列表读不动时回空列表");

    // primaryFile 的两条兜底：都没有 primary 时回第一条，空清单回 nullptr。
    {
        ResourceCatalog::VersionEntry noPrimary;
        ResourceCatalog::FileEntry a;
        a.filename = QStringLiteral("a.jar");
        ResourceCatalog::FileEntry b;
        b.filename = QStringLiteral("b.jar");
        noPrimary.files = {a, b};
        const bool first = noPrimary.primaryFile() != nullptr &&
                           noPrimary.primaryFile()->filename == QStringLiteral("a.jar");
        ResourceCatalog::VersionEntry empty;
        check(first && empty.primaryFile() == nullptr,
              "Z6c 没有 primary 时回第一条；没有文件时回 nullptr");
    }

    // ---------------------------------------------------------------------
    section("Z6d. 前置模组：缺哪些 / 去哪问 / 挑哪一版（一键下载那一批）");
    // ---------------------------------------------------------------------

    // 用户 2026-09-28：「在模组下载页，选择模组后显示其依赖，点击下载后弹出窗口，让用户
    // 可以点击一键下载所有缺少的依赖」。这一带钉的是**判断**那一半（纯函数），
    // 界面上那几个框怎么弹、下载批次怎么开在 MainWindow 里。
    {
        ModDependencies::Target target;
        target.instanceId = QStringLiteral("1.21.1-fabric");
        target.gameVersion = QStringLiteral("1.21.1");
        target.loader = QStringLiteral("fabric");

        // ① "装过的算不算装了"这件事的键，必须和图标缓存那张表**同一个拼法** ——
        //    对不上等于"装过的前置每次都当成没装、再下一遍"，而且不报错。
        check(target.installedKey(QStringLiteral("AANobbMI")) ==
                  ResourceCatalog::Hit{.projectId = QStringLiteral("AANobbMI"),
                                       .source = ResourceCatalog::Source::Modrinth}
                      .iconCacheId(),
              "Z6d 已装的键和 Hit::iconCacheId() 一字不差（两处同一个拼法）",
              target.installedKey(QStringLiteral("AANobbMI")));

        const ResourceCatalog::VersionEntry newest = versions.first();

        // ② 什么都没装：缺它声明的那一条（Iris 最新版钉着 Sodium）。
        const QList<ModDependencies::Lookup> missing =
            ModDependencies::missingRequiredDependencies(newest, {}, target);
        check(missing.size() == 1 &&
                  missing.first().dependency.projectId == QStringLiteral("AANobbMI") &&
                  missing.first().dependency.versionId == QStringLiteral("s7adptIg"),
              "Z6d 一条都没装时，缺的还是那一条（Sodium，且钉着版本）",
              QStringLiteral("%1 条").arg(missing.size()));
        // 地址和钥匙得**跟着目标实例筛**：带上游戏版本和加载器，否则会挑出一个别的加载器
        // 的前置装进这个实例（症状是"装上了、进去就崩"，离这里很远）。
        if (missing.size() == 1) {
            const QString url = missing.first().url;
            const QString key = missing.first().requestKey;
            const QJsonDocument gv = jsonOf(urlParam(url, QStringLiteral("game_versions")));
            const QJsonDocument ld = jsonOf(urlParam(url, QStringLiteral("loaders")));
            check(gv.isArray() && gv.array().size() == 1 &&
                      gv.array().at(0).toString() == QStringLiteral("1.21.1") &&
                      ld.isArray() && ld.array().size() == 1 &&
                      ld.array().at(0).toString() == QStringLiteral("fabric"),
                  "Z6d 去问前置版本列表时带着目标实例的游戏版本 + 加载器", url);
            // ★ 钥匙 = `versionsRequestKey()` **再加一个消费方后缀**。后缀那一截不是装饰：
            //   `ResourceStore::fetchVersions()` 按钥匙去重（同一把钥匙再来一发会把前一发
            //   abort 掉），而"详情页在读这个项目的版本"和"前置检查在读它"是两件事 ——
            //   不区分的话后发那一发把先发掐掉，先发那一趟永远等不到自己的回复
            //   （症状正是"按了没反应"）。
            check(key == ResourceCatalog::versionsRequestKey(QStringLiteral("AANobbMI"),
                                                            QStringLiteral("1.21.1"),
                                                            QStringLiteral("fabric")) +
                             QStringLiteral("|dependency"),
                  "Z6d 钥匙是 versionsRequestKey 加一个消费方后缀（自己拼会漏一处）", key);
            // 两个消费方**必须**是两把钥匙：同一把的话上面那个坑原样复现。
            check(ModDependencies::versionsKeyFor(QStringLiteral("dependency"),
                                                  QStringLiteral("AANobbMI"),
                                                  QStringLiteral("1.21.1"),
                                                  QStringLiteral("fabric")) !=
                      ModDependencies::versionsKeyFor(
                          QStringLiteral("update"), QStringLiteral("AANobbMI"),
                          QStringLiteral("1.21.1"), QStringLiteral("fabric")),
                  "Z6d 前置那一趟和更新检测那一趟的钥匙不是同一把（不然互相 abort）");
        }

        // ③ 已经装着了：一条都不缺。
        const QSet<QString> installed{target.installedKey(QStringLiteral("AANobbMI"))};
        check(ModDependencies::missingRequiredDependencies(newest, installed, target).isEmpty(),
              "Z6d 已经装过的前置不再下一次");

        // ④ ★ 但"装着的是**另一家**的同号项目"**不算装了**。两个来源的 id 各在自己那套里
        //    唯一，`238222` 这种纯数字 id 在 Modrinth 那条 base62 里也合法 —— 不带来源
        //    去比的话，这里会得出"已经装过了"、于是**一个前置都不下**，而用户手上那个
        //    mods/ 里根本没有它。
        const QSet<QString> otherSource{
            ResourceCatalog::Hit{.projectId = QStringLiteral("AANobbMI"),
                                 .source = ResourceCatalog::Source::CurseForge}
                .iconCacheId()};
        check(ModDependencies::missingRequiredDependencies(newest, otherSource, target).size() == 1,
              "Z6d 别家同号的项目不算「已经装了」（来源要进判据）");

        // ⑤ optional / 没写项目号的都不下（后者是接口给的烂数据）。
        ResourceCatalog::VersionEntry handmade;
        ResourceCatalog::Dependency optionalDep;
        optionalDep.projectId = QStringLiteral("aaaaaaa1");
        optionalDep.type = QStringLiteral("optional");
        ResourceCatalog::Dependency blankDep;
        blankDep.type = QStringLiteral("required");
        ResourceCatalog::Dependency requiredDep;
        requiredDep.projectId = QStringLiteral("bbbbbbb2");
        requiredDep.type = QStringLiteral("required");
        handmade.dependencies = {optionalDep, blankDep, requiredDep};
        const QList<ModDependencies::Lookup> onlyReal =
            ModDependencies::missingRequiredDependencies(handmade, {}, target);
        check(onlyReal.size() == 1 &&
                  onlyReal.first().dependency.projectId == QStringLiteral("bbbbbbb2"),
              "Z6d optional 和没写项目号的都不进这一批，只留下那一条真的",
              QStringLiteral("%1 条").arg(onlyReal.size()));

        // ⑥ ★ Fabric API 不列（用户 2026-10-13：「所有的 fabric 模组当然都要用 fabricAPI，
        //    这个是前置简直是废话，需要的前置列表里排除一下吧」）。两家各一个号，都要认。
        {
            ResourceCatalog::VersionEntry fabricMod;
            ResourceCatalog::Dependency mrApi;
            mrApi.projectId = QStringLiteral("P7dR8mSH");  // Modrinth: fabric-api
            mrApi.type = QStringLiteral("required");
            ResourceCatalog::Dependency cfApi;
            cfApi.projectId = QStringLiteral("306612");  // CurseForge: Fabric API
            cfApi.type = QStringLiteral("required");
            ResourceCatalog::Dependency cloth;
            cloth.projectId = QStringLiteral("9s6osm5g");  // Cloth Config：真该列出来的那种
            cloth.type = QStringLiteral("required");
            fabricMod.dependencies = {mrApi, cfApi, cloth};

            const QList<ResourceCatalog::Dependency> listed =
                ModDependencies::displayedRequiredDependencies(fabricMod);
            check(listed.size() == 1 &&
                      listed.first().projectId == QStringLiteral("9s6osm5g"),
                  "★★ Z6d Fabric API 不进「这一版要装的前置」—— Modrinth 和 CurseForge 两家的号都认",
                  QStringLiteral("%1 条").arg(listed.size()));

            // 隐藏只是展示规则：真安装判定不能跟着删。否则用户点
            // 「一起下载」也不会安装 Fabric API，最后得到一份缺真前置的实例。
            const QList<ModDependencies::Lookup> missingWithApi =
                ModDependencies::missingRequiredDependencies(fabricMod, {}, target);
            check(missingWithApi.size() == 3,
                  "★★ Z6d Fabric API 只在详情展示中隐藏，缺失判定仍保留真依赖",
                  QStringLiteral("%1 条").arg(missingWithApi.size()));

            // ★ 是**按号**排的，不是"看着像"就排：差一位的两个号一个都不能误伤。
            ResourceCatalog::VersionEntry lookalikes;
            ResourceCatalog::Dependency nearMr;
            nearMr.projectId = QStringLiteral("P7dR8mS");  // 少一位
            nearMr.type = QStringLiteral("required");
            ResourceCatalog::Dependency nearCf;
            nearCf.projectId = QStringLiteral("3066120");  // 多一位
            nearCf.type = QStringLiteral("required");
            lookalikes.dependencies = {nearMr, nearCf};
            check(ModDependencies::displayedRequiredDependencies(lookalikes).size() == 2,
                  "★ Z6d 排的是那两个**号**，不是「名字里带 fabric 的都排」"
                  "（差一位的号一个都不能误伤）",
                  QStringLiteral("%1 条")
                      .arg(ModDependencies::requiredDependenciesOf(lookalikes).size()));
        }
    }

    // 挑一版：钉了版本必须正好是那条、没钉取最新的一条；挑不出来要**说得出为什么**。
    {
        ModDependencies::Resolved picked;
        QString why;

        // 钉了版本、候选表里正好有它。
        ResourceCatalog::Dependency pinned;
        pinned.projectId = QStringLiteral("AANobbMI");
        pinned.versionId = QStringLiteral("s7adptIg");
        pinned.type = QStringLiteral("required");
        // 真列表里**没有** s7adptIg 这一版（Iris 那份是它自己的版本，不是 Sodium 的）——
        // 所以先用真列表钉"钉的版本找不到时不许退而求其次"。
        const bool found = ModDependencies::resolveDependency(pinned, versions, &picked, &why);
        check(!found && why.contains(QStringLiteral("s7adptIg")),
              "Z6d 作者钉的那一版不在列表里 -> 解不开（不许换成第一条），且理由里带着那个号",
              why);

        // 自己造一张候选表：三条，第 0 条就是钉的那一条。
        ResourceCatalog::VersionEntry v0;
        v0.id = QStringLiteral("s7adptIg");
        v0.versionNumber = QStringLiteral("0.6.13");
        ResourceCatalog::FileEntry f0;
        f0.url = QStringLiteral("https://example.invalid/sodium-0.6.13.jar");
        f0.filename = QStringLiteral("sodium-0.6.13.jar");
        f0.sha1 = QStringLiteral("1111111111111111111111111111111111111111");
        v0.files = {f0};
        ResourceCatalog::VersionEntry v1;
        v1.id = QStringLiteral("older001");
        v1.versionNumber = QStringLiteral("0.6.12");
        ResourceCatalog::FileEntry f1;
        f1.url = QStringLiteral("https://example.invalid/sodium-0.6.12.jar");
        f1.filename = QStringLiteral("sodium-0.6.12.jar");
        f1.sha1 = QStringLiteral("2222222222222222222222222222222222222222");
        v1.files = {f1};
        const QList<ResourceCatalog::VersionEntry> candidates{v0, v1};

        why.clear();
        check(ModDependencies::resolveDependency(pinned, candidates, &picked, &why) &&
                  picked.version.id == QStringLiteral("s7adptIg") &&
                  picked.file.filename == QStringLiteral("sodium-0.6.13.jar"),
              "Z6d 钉了版本且找得到 -> 就下那一版那个文件", why);

        // 没钉（"哪个版本都行"）-> 取**列表第一条**。这份列表接口给的就是新的在前。
        ResourceCatalog::Dependency loose;
        loose.projectId = QStringLiteral("AANobbMI");
        loose.type = QStringLiteral("required");
        why.clear();
        check(ModDependencies::resolveDependency(loose, candidates, &picked, &why) &&
                  picked.version.id == QStringLiteral("s7adptIg"),
              "Z6d 没钉版本 -> 拿列表第一条（接口给的就是新的在前）", why);
        // ★ 这一条钉的是"不按版本号比大小"：把两条**倒过来**摆，挑出来的必须还是第一条
        //   （`0.6.12` 那条）。按版本号挑的话这一条会红 —— 而那个比较器（"1.9 比 1.10 旧"）
        //   写错了不会有任何东西报警。
        const QList<ResourceCatalog::VersionEntry> reversed{v1, v0};
        why.clear();
        check(ModDependencies::resolveDependency(loose, reversed, &picked, &why) &&
                  picked.version.id == QStringLiteral("older001"),
              "Z6d 盯的是**次序**不是版本号大小：倒过来摆就挑另一条", why);

        // 挑出来的那一条没有可下载的文件：CurseForge 那种"作者关掉了第三方分发"的形态 ——
        // 那时候要给的是那边写好的那句话，不是"找不到版本"。
        ResourceCatalog::VersionEntry noUrl;
        noUrl.id = QStringLiteral("nofile01");
        noUrl.versionNumber = QStringLiteral("1.0");
        ResourceCatalog::FileEntry blocked;
        blocked.filename = QStringLiteral("blocked.jar");
        blocked.unavailableNote = QStringLiteral("作者关掉了这个文件的第三方分发。");
        noUrl.files = {blocked};
        why.clear();
        check(!ModDependencies::resolveDependency(loose, {noUrl}, &picked, &why) &&
                  why == blocked.unavailableNote,
              "Z6d 挑出来的那一版没有地址 -> 解不开，理由就是那边写好的那句", why);

        why.clear();
        check(!ModDependencies::resolveDependency(loose, {}, &picked, &why) && !why.isEmpty(),
              "Z6d 一条候选都没有 -> 解不开（空表不等于「已是最新」那种「没问题」）", why);
    }

    // buildPlan：一批答案 -> 要下的 + 解不开的（那几句是给用户看的，得带上是哪个前置）。
    {
        ModDependencies::Target target;
        target.gameVersion = QStringLiteral("1.21.1");
        target.loader = QStringLiteral("fabric");
        const QList<ModDependencies::Lookup> missing =
            ModDependencies::missingRequiredDependencies(versions.first(), {}, target);
        check(missing.size() == 1, "Z6d buildPlan 的输入（那条 Sodium）");

        if (missing.size() == 1) {
            const QString key = missing.first().requestKey;

            // ① 答案缺席 = 那一发没回来，和"它没有版本"**不是同一句话**。
            const ModDependencies::Plan none = ModDependencies::buildPlan(missing, {});
            check(none.downloads.isEmpty() && none.unresolved.size() == 1 &&
                      none.unresolved.first().contains(QStringLiteral("没问到")),
                  "Z6d 那一发没回来 -> 进「解不开」，理由说的是「没问到」",
                  none.unresolved.join(QStringLiteral(" | ")));

            // ② 有答案：挑出要下的那一条，而且名字用的是接口那份（不是项目号）。
            ResourceCatalog::VersionEntry sodium;
            sodium.id = QStringLiteral("s7adptIg");
            sodium.versionNumber = QStringLiteral("0.6.13");
            ResourceCatalog::FileEntry file;
            file.url = QStringLiteral("https://example.invalid/sodium-0.6.13.jar");
            file.filename = QStringLiteral("sodium-0.6.13.jar");
            sodium.files = {file};
            const QHash<QString, QList<ResourceCatalog::VersionEntry>> answers{
                {key, {sodium}}};
            const QHash<QString, QString> titles{
                {QStringLiteral("AANobbMI"), QStringLiteral("Sodium")}};
            const ModDependencies::Plan plan =
                ModDependencies::buildPlan(missing, answers, titles);
            check(plan.downloads.size() == 1 && plan.unresolved.isEmpty() &&
                      plan.downloads.first().file.filename ==
                          QStringLiteral("sodium-0.6.13.jar") &&
                      plan.downloads.first().title == QStringLiteral("Sodium"),
                  "Z6d 有答案 -> 一版一文件，名字是接口那份",
                  plan.downloads.isEmpty() ? QString() : plan.downloads.first().title);

            // ③ 名字取不到时退成项目号（列出来总比"有一个前置没找到"强）。
            const ModDependencies::Plan unnamed = ModDependencies::buildPlan(missing, {});
            check(unnamed.unresolved.size() == 1 &&
                      unnamed.unresolved.first().startsWith(QStringLiteral("AANobbMI")),
                  "Z6d 名字取不到就用项目号，不写一个没有主语的句子",
                  unnamed.unresolved.join(QStringLiteral(" | ")));
        }
    }

    // 那几句话本身（界面和验证都读它，别在别处再写一遍）。
    {
        const QString prompt = ModDependencies::dependencyPromptText(
            ResourceCatalog::Kind::Mod,
            {QStringLiteral("Sodium"), QStringLiteral("Fabric API")});
        // 正文 = 句头 + 名单 + 「要一起下载吗？」。名单**一条一行、前面带短横**（用户
        // 2026-10-09 原话「模组名称，一行一个」）。旧版那句"这几个还没装"里的**计数**已经
        // 不写了 —— 名单里几条一眼就看得见，而截断那一档写的是"还有 N 个未列出"。
        check(prompt.contains(QStringLiteral("- Sodium\n- Fabric API")) &&
                  prompt.contains(ModDependencies::dependencyPromptHead(ResourceCatalog::Kind::Mod)) &&
                  prompt.trimmed().endsWith(QStringLiteral("要一起下载吗？")),
              "Z6d 弹窗正文 = 句头 + 一条一行的名单 + 那句问句", prompt);
        check(ModDependencies::dependencyPromptText(ResourceCatalog::Kind::Mod, {}).isEmpty(),
              "Z6d 一条都不缺时那句话是空串（空表不该弹这个框）");
        check(ModDependencies::dependencyAllButtonText() == QStringLiteral("一起下载") &&
                  ModDependencies::dependencyOnlyThisButtonText() == QStringLiteral("只下这个"),
              "Z6d 两颗按钮的字（用户要的「一键下载」就在这一颗上）",
              ModDependencies::dependencyAllButtonText());
        check(ModDependencies::unresolvedNoteText({}).isEmpty() &&
                  ModDependencies::unresolvedNoteText({QStringLiteral("Sodium：没问到")})
                      .contains(QStringLiteral("Sodium：没问到")),
              "Z6d 没解开那几条的原话会被列出来；空表回空串");

        // ---- 句头认类别（2026-10-09：光影包也查前置）----
        check(ModDependencies::dependencyPromptHead(ResourceCatalog::Kind::Mod) ==
                      QStringLiteral("此模组缺失必要的前置：") &&
                  ModDependencies::dependencyPromptHead(ResourceCatalog::Kind::Shader) ==
                      QStringLiteral("此光影包缺失必要的前置："),
              "★ Z6d 句头分模组 / 光影包两句（说成「此模组」的框摆在一个光影包前面就是错的）",
              ModDependencies::dependencyPromptHead(ResourceCatalog::Kind::Shader));
        check(ModDependencies::dependencyPromptText(ResourceCatalog::Kind::Shader,
                                                    {QStringLiteral("Iris")})
                  .startsWith(ModDependencies::dependencyPromptHead(ResourceCatalog::Kind::Shader)),
              "★ Z6d 光影那一份正文用的就是光影的句头（正文和句头不许各写一份）",
              ModDependencies::dependencyPromptText(ResourceCatalog::Kind::Shader,
                                                    {QStringLiteral("Iris")}));

        // ---- 名单的截断规则（用户 2026-10-09 点名，两条边界都要钉）----
        //
        // 原话：「如果多于 3 个的话写 还有 x 个未列出...（当然如果刚好还剩一个就列出来了
        // 不要搞一行显示 1 个未列出这种高血压操作）」。翻成判据：
        //   · **总数 ≤ 4 ⇒ 全列**（4 条这一档就是"刚好还剩一个"，它走全列）；
        //   · **总数 > 4 ⇒ 列前 3 条 + 「还有 N 个未列出…」**。
        // 所以「还有 1 个未列出」**永远画不出来** —— 下面最后一档就是拿它反着量的。
        const auto names = [](int n) {
            QStringList out;
            for (int i = 0; i < n; ++i) {
                out.append(QStringLiteral("Dep%1").arg(i));
            }
            return out;
        };
        const auto listingOf = [&names](int n) {
            return ModDependencies::dependencyPromptText(ResourceCatalog::Kind::Mod, names(n));
        };
        // 1 条：列出来，而且**不出现**「未列出」。
        check(listingOf(1).contains(QStringLiteral("- Dep0")) &&
                  !listingOf(1).contains(QStringLiteral("未列出")),
              "★ Z6d 只缺 1 条时就是那一条（1 条也不许写成「还有 1 个未列出」）", listingOf(1));
        // 4 条：全列（"刚好还剩一个"那一档走全列，这是用户点名不许省的那一侧）。
        check(listingOf(4).contains(QStringLiteral("- Dep3")) &&
                  !listingOf(4).contains(QStringLiteral("未列出")),
              "★ Z6d 缺 4 条时**一条不省**全列出来（这一档就是用户说的「刚好还剩一个」）",
              listingOf(4));
        // 5 条：前 3 条 + 「还有 2 个未列出…」，后两条**不在**名单里。
        const QString five = listingOf(5);
        check(five.contains(QStringLiteral("- Dep0")) && five.contains(QStringLiteral("- Dep2")) &&
                  !five.contains(QStringLiteral("- Dep3")) &&
                  !five.contains(QStringLiteral("- Dep4")) &&
                  five.contains(QStringLiteral("还有 2 个未列出…")),
              "★ Z6d 缺 5 条时列前 3 +「还有 2 个未列出…」（第 4、5 条不再占行）", five);
        // 反着量一次：**任何一档都不许**给出「还有 1 个未列出」（用户点名的那句高血压话）。
        for (int n = 0; n <= 8; ++n) {
            check(!listingOf(n).contains(QStringLiteral("还有 1 个未列出")),
                  QStringLiteral("★ Z6d 缺 %1 条时都不出现「还有 1 个未列出」（用户点名不要的那一行）")
                      .arg(n),
                  listingOf(n));
        }

        // ---- 弹窗里那行灰字（用户：「弹窗里灰字写可以在设置里面关掉弹窗」）----
        const QString note = ModDependencies::dependencyPromptNoteText();
        check(!note.isEmpty() && note.contains(QStringLiteral("设置")) &&
                  note.contains(QStringLiteral("缺失前置提醒")),
              "★ Z6d 灰字说清了「能在设置里关掉」，而且**点名了那一项**（不然用户在设置里找不着）",
              note);

        // ---- 「还没看过这个实例装了什么」那一版 ----
        // 两版的**区别只有一句话**：这一版在句头后面补上「还没看过这个实例里装了什么，
        // 不知道你有没有」—— 名字照样一条一行，截断规则同一套。空表同样回空串。
        const QString unknown =
            ModDependencies::dependencyPromptUnknownText(ResourceCatalog::Kind::Mod, names(1));
        check(ModDependencies::dependencyPromptUnknownText(ResourceCatalog::Kind::Mod, {}).isEmpty() &&
                  unknown.contains(QStringLiteral("- Dep0")) &&
                  unknown.contains(QStringLiteral("不知道你有没有")) &&
                  unknown.startsWith(
                      ModDependencies::dependencyPromptHead(ResourceCatalog::Kind::Mod)),
              "★ Z6d 不知道装没装的那一版补一句「不知道你有没有」，名单照旧（不替用户认下来）",
              unknown);
        // 名单截断那一套两版**共用**（同一支 dependencyNameLines）—— 拿 5 条在这版也量一次。
        check(ModDependencies::dependencyPromptUnknownText(ResourceCatalog::Kind::Mod, names(5))
                  .contains(QStringLiteral("还有 2 个未列出…")),
              "★ Z6d 截断规则两版共用（不知道装没装那一版同样是前 3 +「还有 2 个未列出…」）",
              ModDependencies::dependencyPromptUnknownText(ResourceCatalog::Kind::Mod, names(5)));
    }

    // ---------------------------------------------------------------------
    section("Z6e. 更新检测：盘上这一条是不是最新");
    // ---------------------------------------------------------------------

    // 用户 2026-09-28：「实例设置那里做一个更新检测」。判据**只有一条**：盘上那个文件的
    // sha1 落在列表的第几条上（第 0 条 = 最新的那条）。**不许**按版本号比大小 ——
    // 那个比较器（"1.9 比 1.10 旧"）写错了不会有任何东西报警。
    {
        ModDependencies::InstalledItem item;
        item.path = QStringLiteral("D:/mc/versions/1.21.1-fabric/mods/iris.jar");
        item.iconKey = QStringLiteral("modrinth-YL57xq9U");
        item.title = QStringLiteral("Iris Shaders");

        // 盘上就是最新的那一条。
        item.sha1 = versions.first().primaryFile()->sha1;
        const ModDependencies::UpdateVerdict newest =
            ModDependencies::judgeUpdate(item, versions);
        check(newest.state == ModDependencies::UpdateState::UpToDate && newest.newerCount == 0 &&
                  newest.latestVersionId == versions.first().id,
              "Z6e 盘上就是最新的那一条 -> 已是最新", newest.reason);

        // 盘上是最老的那一条：比它新的有 11 条。
        item.sha1 = versions.last().primaryFile()->sha1;
        const ModDependencies::UpdateVerdict oldest =
            ModDependencies::judgeUpdate(item, versions);
        check(oldest.state == ModDependencies::UpdateState::Outdated &&
                  oldest.newerCount == versions.size() - 1 &&
                  oldest.latestVersionId == versions.first().id &&
                  !oldest.latestFileName.isEmpty(),
              "Z6e 盘上是最老的那一条 -> 有新版本，数出比它新的有几条",
              QStringLiteral("%1 条新 / 最新 %2")
                  .arg(oldest.newerCount)
                  .arg(oldest.latestVersionNumber));

        // ★ 三档都**不许**混：说不清的两种绝不能被当成"已是最新"（那是"告诉用户没事、
        //   其实没查成"，比不报更糟）。
        ModDependencies::InstalledItem noHash = item;
        noHash.sha1.clear();
        const ModDependencies::UpdateVerdict unknownHash =
            ModDependencies::judgeUpdate(noHash, versions);
        check(unknownHash.state == ModDependencies::UpdateState::Unknown &&
                  !unknownHash.reason.isEmpty(),
              "Z6e 本地那个文件算不出 sha1 -> 说不清（不是「已是最新」）", unknownHash.reason);

        ModDependencies::InstalledItem stranger = item;
        stranger.sha1 = QString(40, QLatin1Char('f'));
        const ModDependencies::UpdateVerdict unknownFile =
            ModDependencies::judgeUpdate(stranger, versions);
        check(unknownFile.state == ModDependencies::UpdateState::Unknown &&
                  !unknownFile.reason.isEmpty(),
              "Z6e 这个 sha1 一条都没落上 -> 说不清（筛过 / 作者删了 / 用户改过，三合一）",
              unknownFile.reason);

        item.sha1 = versions.first().primaryFile()->sha1;
        const ModDependencies::UpdateVerdict noList =
            ModDependencies::judgeUpdate(item, {});
        check(noList.state == ModDependencies::UpdateState::Unknown && !noList.reason.isEmpty(),
              "Z6e 那一发没回来（空列表）-> 说不清", noList.reason);

        // 大小写不敏感地比：两边都是小写，但这是**外部输入**（接口正文 / 本地算的），
        // 差一个大小写就变成"说不清"，而屏幕上看不出任何异常。
        ModDependencies::InstalledItem upper = item;
        upper.sha1 = upper.sha1.toUpper();
        check(ModDependencies::judgeUpdate(upper, versions).state ==
                  ModDependencies::UpdateState::UpToDate,
              "Z6e sha1 比的时候不看大小写");

        check(ModDependencies::updateUpToDateText() == QStringLiteral("已是最新") &&
                  ModDependencies::updateOutdatedText() == QStringLiteral("有新版本") &&
                  !ModDependencies::updateUnknownText().isEmpty(),
              "Z6e 三档在报告里各是各的一句",
              ModDependencies::updateUnknownText());
        check(ModDependencies::updateSummaryText(5, 2).contains(QStringLiteral("5")) &&
                  ModDependencies::updateSummaryText(5, 2).contains(QStringLiteral("2")),
              "Z6e 报告开头那两个数（查了几个 / 几个有新版本）",
              ModDependencies::updateSummaryText(5, 2));
    }

    // ---------------------------------------------------------------------
    section("Z6f. 更新检测：批量那一发（`/version_files/update`）");
    // ---------------------------------------------------------------------
    //
    // 用户 2026-10-11：「还有个无法正常获取更新的问题」（他自己点名的是**模组更新**）。
    // 真机上量出来的样子是：一个 352 个模组的实例，一项目一发版本列表 = **623 发请求**
    //（同一个文件在 Modrinth 和 CurseForge **两家都认出来**时是两条记录，两条各问一发），
    // 实测整批 429（Cloudflare 的 `error code: 1015`）/ CF 那边 151 发 `GOAWAY`，
    // 报告里于是每条都是"说不清"。
    //
    // 改法两半：① Modrinth 那一拨换成 `POST /version_files/update`（一次一串 sha1，
    // 352 个模组 = 3 发）；② **一个文件只查一家**（两家都有时走 Modrinth，Modrinth 那一发
    // 没给出答案时才退回问 CurseForge）。②那一半的状态机在 `MainWindow` 上，由 mw_check 的
    // T28/T32 钉着；这一段钉的是**纯函数那一半**。
    {
        const QString shaA = QString(40, QLatin1Char('a'));
        const QString shaB = QString(40, QLatin1Char('b'));

        // ---------- ① 请求体 ----------
        //
        // ★ 空哈希表：**不许**发（空表的回复必然是空表，白花一发）。
        check(ResourceCatalog::versionFilesUpdateRequestBody({}, QStringLiteral("1.20.1"),
                                                             QStringLiteral("forge"))
                  .isEmpty(),
              "Z6f 一个哈希都没有 -> 请求体是空的（那一发不该发出去）");
        check(ResourceCatalog::versionFilesUpdateRequestBody({QStringLiteral("   "),
                                                              QString()},
                                                             QStringLiteral("1.20.1"),
                                                             QStringLiteral("forge"))
                  .isEmpty(),
              "Z6f 全是空白 sha1 -> 也当成空表（发上去只是白占一格）");

        const QByteArray body = ResourceCatalog::versionFilesUpdateRequestBody(
            {shaA, QStringLiteral("  ") + shaB + QStringLiteral(" "), QString()},
            QStringLiteral("1.20.1"), QStringLiteral("Forge"));
        const QJsonObject bodyObject = QJsonDocument::fromJson(body).object();
        const QJsonArray bodyHashes = bodyObject.value(QStringLiteral("hashes")).toArray();
        check(bodyObject.value(QStringLiteral("algorithm")).toString() == QStringLiteral("sha1"),
              "Z6f 请求体里那一格写着 algorithm=sha1（少它那一发会被接口回 400）",
              QString::fromUtf8(body));
        check(bodyHashes.size() == 2 &&
                  bodyHashes.at(0).toString() == shaA && bodyHashes.at(1).toString() == shaB,
              "Z6f 两个真空哈希原样进去了、空白和空串被剔掉（顺序照给的顺序）",
              QStringLiteral("%1 个").arg(bodyHashes.size()));
        // ★★ 加载器那一格**必须翻一道**：`dependencyTargetFor()` 给的是显示名（「Forge」），
        //    而这一发只认小写那个词 —— 递错的症状是"一个哈希都匹配不上"（不是报错）：
        //    整批模组会被退回问 CurseForge，而屏幕上看像"这一批没查到"。
        //    见 `ResourceCatalog::versionFilesUpdateRequestBody()` 里那段。
        check(bodyObject.value(QStringLiteral("loaders")).toArray() ==
                  QJsonArray{QStringLiteral("forge")},
              "★★ Z6f 加载器递显示名「Forge」也被翻成 loaders=[forge] —— 这一格是"
              "**唯一**能做到「递错就一个都筛不出来」的地方",
              QString::fromUtf8(body));
        check(bodyObject.value(QStringLiteral("game_versions")).toArray() ==
                  QJsonArray{QStringLiteral("1.20.1")},
              "Z6f 游戏版本那一格是小写键 `game_versions`、值是个数组");
        // 认不出来的加载器词（用户盘上的 OptiFine 就是这一档）：**那一格整个不出现**
        //（= 不筛），别拼一个筛不出来的词上去。
        const QJsonObject optifineBody = QJsonDocument::fromJson(
            ResourceCatalog::versionFilesUpdateRequestBody({shaA}, QStringLiteral("1.20.1"),
                                                           QStringLiteral("OptiFine"))).object();
        check(!optifineBody.contains(QStringLiteral("loaders")),
              "Z6f 认不出来的加载器（「OptiFine」）-> `loaders` 那一格**整个不出现**（不筛，"
              "不是拼一个筛不出来的词上去）",
              QString::fromUtf8(QJsonDocument(optifineBody).toJson(QJsonDocument::Compact)));
        // 两个筛都不给 = 一个筛都不发（"随便哪一版"）。
        const QJsonObject bareBody = QJsonDocument::fromJson(
            ResourceCatalog::versionFilesUpdateRequestBody({shaA}, QString(), QString())).object();
        check(!bareBody.contains(QStringLiteral("game_versions")) &&
                  !bareBody.contains(QStringLiteral("loaders")),
              "Z6f 不给游戏版本/加载器 -> 那两个键都不出现（空 = 不筛，和 versionsUrl 同一条）");
        check(ResourceCatalog::versionFilesUpdateUrl(QStringLiteral("http://127.0.0.1:9/v2")) ==
                  QStringLiteral("http://127.0.0.1:9/v2/version_files/update"),
              "Z6f 地址：`<base>/version_files/update`（验证工程那个口子优先）");

        // ---------- ② 解析 ----------
        check(ResourceCatalog::parseVersionFilesUpdate(QByteArrayLiteral("not json")).isEmpty() &&
                  ResourceCatalog::parseVersionFilesUpdate(QByteArrayLiteral("[]")).isEmpty(),
              "Z6f 读不懂（不是对象）-> 空表（一条都不许当成「已是最新」）");
        const QByteArray reply = QByteArrayLiteral("{") + QByteArrayLiteral("\"") +
                                 shaA.toUpper().toUtf8() + QByteArrayLiteral("\":{\"id\":"
                                 "\"VNEW\",\"version_number\":\"2.0\",\"game_versions\":"
                                 "[\"1.20.1\"],\"loaders\":[\"forge\"],\"files\":[{\"hashes\":"
                                 "{\"sha1\":\"1111111111111111111111111111111111111111\"},"
                                 "\"url\":\"https://cdn.modrinth.com/data/mod-b-2.0.jar\","
                                 "\"filename\":\"模组乙-2.0.jar\",\"size\":10}]},") +
                                 QByteArrayLiteral("\"deadbeef\":\"这不是对象\"}");
        const QHash<QString, ResourceCatalog::VersionEntry> parsed =
            ResourceCatalog::parseVersionFilesUpdate(reply);
        check(parsed.size() == 1,
              "Z6f 回复里那一格不是对象的条目**被跳过**（不是崩、也不是当成一条空版本）",
              QStringLiteral("%1 条").arg(parsed.size()));
        const ResourceCatalog::VersionEntry entry = parsed.value(shaA);
        check(entry.id == QStringLiteral("VNEW") &&
                  entry.versionNumber == QStringLiteral("2.0") && entry.files.size() == 1 &&
                  entry.files.first().filename == QStringLiteral("模组乙-2.0.jar") &&
                  entry.files.first().sha1 == QString(40, QLatin1Char('1')),
              "Z6f 读出来的那一版字段齐（和 parseVersions 用的是**同一个读取器**）",
              QStringLiteral("%1 / %2").arg(entry.id, entry.versionNumber));
        check(parsed.contains(shaA),
              "★ Z6f 键**按小写收**：接口回的是大写哈希，查的时候用小写的也拿得到"
              "（本地那个 sha1 一律是小写，差一个大小写就变成「说不清」）");

        // ---------- ③ 判：`judgeUpdateAgainstLatest` ----------
        ModDependencies::InstalledItem item;
        item.path = QStringLiteral("D:/mc/versions/1.20.1-forge/mods/模组乙.jar");
        item.iconKey = QStringLiteral("modrinth-UPDPROJ");
        item.title = QStringLiteral("模组乙");

        // 盘上这一份的 sha1 **不在**最新那一版的文件里 -> 有新版本。
        item.sha1 = shaB;
        const ModDependencies::UpdateVerdict outdated =
            ModDependencies::judgeUpdateAgainstLatest(item, entry);
        check(outdated.state == ModDependencies::UpdateState::Outdated &&
                  outdated.newerCount >= 1 &&
                  outdated.latestVersionId == QStringLiteral("VNEW") &&
                  outdated.latestFileName == QStringLiteral("模组乙-2.0.jar"),
              "Z6f 盘上那一份不在最新那一版的文件里 -> 有新版本（「最新那一版」就是接口给的"
              "那一条）",
              QStringLiteral("%1 / %2").arg(outdated.latestVersionNumber, outdated.latestFileName));

        // 盘上这一份**就是**最新那一版的文件 -> 已是最新（逐字和 judgeUpdate 那一条同一句话）。
        item.sha1 = QStringLiteral("1111111111111111111111111111111111111111");
        const ModDependencies::UpdateVerdict newest =
            ModDependencies::judgeUpdateAgainstLatest(item, entry);
        check(newest.state == ModDependencies::UpdateState::UpToDate && newest.newerCount == 0,
              "Z6f 盘上就是最新那一版的文件 -> 已是最新");
        item.sha1 = item.sha1.toUpper();
        check(ModDependencies::judgeUpdateAgainstLatest(item, entry).state ==
                  ModDependencies::UpdateState::UpToDate,
              "Z6f sha1 比的时候不看大小写");

        ModDependencies::InstalledItem noHash = item;
        noHash.sha1.clear();
        check(ModDependencies::judgeUpdateAgainstLatest(noHash, entry).state ==
                  ModDependencies::UpdateState::Unknown,
              "Z6f 本地那个文件算不出 sha1 -> 说不清（不是「已是最新」）");

        // ★★ 接口对它**什么都没给**（那一批自己 429 了 / 这个项目在这个游戏版本+加载器下
        //    没有版本）：`problem` 里那句话就是这几条"说不清"的理由 —— 从前它被吞成
        //    "网络或接口没成"，于是用户看到的每一条都是"网络没成"，在那儿反复重试网络，
        //    而真因是"一次问得太多"。
        const QString throttled = QStringLiteral("问得太勤了，等一会儿再试。");
        const ModDependencies::UpdateVerdict noAnswer =
            ModDependencies::judgeUpdateAgainstLatest(item, ResourceCatalog::VersionEntry(),
                                                      throttled);
        check(noAnswer.state == ModDependencies::UpdateState::Unknown &&
                  noAnswer.reason == throttled,
              "★★ Z6f 接口那一发自己报的那句话（「问得太勤了…」）就是这一条说不清的理由 "
              "—— 真因不许被吞成「没问到版本列表」",
              noAnswer.reason);
        const ModDependencies::UpdateVerdict emptyAnswer =
            ModDependencies::judgeUpdateAgainstLatest(item, ResourceCatalog::VersionEntry());
        check(emptyAnswer.state == ModDependencies::UpdateState::Unknown &&
                  !emptyAnswer.reason.isEmpty() && emptyAnswer.reason != noAnswer.reason,
              "Z6f 没报错、接口就是没给这一条 -> 另一句话（「这个项目在这个游戏版本/加载器"
              "下没有版本」），和「那一发没成」分得开",
              emptyAnswer.reason);
        const ModDependencies::UpdateVerdict singleNoAnswer =
            ModDependencies::judgeUpdate(item, {}, throttled);
        check(singleNoAnswer.state == ModDependencies::UpdateState::Unknown &&
                  singleNoAnswer.reason == throttled,
              "★★ Z6f 一项目一发那条路同样不许吞（从前这里一律写「没问到版本列表（网络或"
              "接口没成）」，429 在报告里和「网断了」长得一模一样）",
              singleNoAnswer.reason);

        // ---------- ④ 钥匙 ----------
        const QString key = ModDependencies::latestVersionsKeyFor(QStringLiteral("update"),
                                                                  QStringLiteral("1.20.1"),
                                                                  QStringLiteral("forge"));
        check(!key.isEmpty() &&
                  key != ModDependencies::latestVersionsKeyFor(QStringLiteral("update"),
                                                                QStringLiteral("1.21"),
                                                                QStringLiteral("forge")) &&
                  key != ModDependencies::latestVersionsKeyFor(QStringLiteral("update"),
                                                                QStringLiteral("1.20.1"),
                                                                QStringLiteral("fabric")) &&
                  key != ModDependencies::latestVersionsKeyFor(QStringLiteral("dependency"),
                                                                QStringLiteral("1.20.1"),
                                                                QStringLiteral("forge")),
              "Z6f 批量那一发的钥匙：游戏版本 / 加载器 / 消费方**各差一个字就是另一把**"
              "（少一样的话，前一发回来的会被当成「我现在等的那一发」）",
              key);
    }

    // ---------------------------------------------------------------------
    section("Z6g. 更新检测：**问版本列表时带不带加载器**（2026-10-11）");
    // ---------------------------------------------------------------------
    //
    // 用户 2026-10-11：「看上去依然获取不到有效更新」（同一个实例里**资源包和光影包
    // 一条都判不出来**，报告里全是"说不清"）。
    //
    // 真因不是网络：那个筛一旦带上，**只对模组是对的**。当场拿用户盘上那些文件的 sha1
    // 各问一次 `POST /v2/version_files/update`（同一条命令、只改 `loaders` 那一格）：
    //   · `loaders:["fabric"]` ⇒ `{}`（一个都不答）；
    //   · 去掉 `loaders` ⇒ 当场答（`BlockPixel` / `Visible Ores` / `Translations for
    //     Sodium` 都是这样）；
    //   · 光影那条在 Modrinth 上写的是 `["iris","optifine"]`（拿 `Complementary` 的
    //     项目号 `R6NEzAwj` 实测），资源包写的是 `["minecraft"]` —— **没有一个**是实例
    //     的加载器。
    // 叶子判据就是这一支纯函数（产品的两处调用点都读它，不许就地写"哪几类带"）。
    {
        check(ModDependencies::kindUsesLoader(ResourceCatalog::Kind::Mod) &&
                  ModDependencies::kindUsesLoader(ResourceCatalog::Kind::Modpack),
              "★★ Z6g 模组（和整合包）**要带**加载器 —— 同一个模组的 Fabric / Forge 两版"
              "是两条版本线，不带的话「最新」可能是另一个加载器的 jar（装进去就崩）");
        check(!ModDependencies::kindUsesLoader(ResourceCatalog::Kind::ResourcePack) &&
                  !ModDependencies::kindUsesLoader(ResourceCatalog::Kind::Shader) &&
                  !ModDependencies::kindUsesLoader(ResourceCatalog::Kind::DataPack),
              "★★ Z6g 资源包 / 光影包 / 数据包**一个都不带** —— 带上去不会报错、只是"
              "一个都不匹配（真机症状：那一类每一条都是「说不清」）");
        // 逐类过一遍 `allKinds()`：后加一类时**不许**悄悄落进「带上去」那一档
        //（带错了的症状是「这一类一条都判不出来」），这一条会当场红。
        QStringList withLoader;
        for (const ResourceCatalog::Kind kind : ResourceCatalog::allKinds()) {
            if (ModDependencies::kindUsesLoader(kind)) {
                withLoader.append(ResourceCatalog::kindKey(kind));
            }
        }
        // 排序再比：`allKinds()` 的顺序是**下载页左栏那一份**（整合包在前），它是那一栏的
        // 规格、不该被这一条断言反过来钉住。
        withLoader.sort();
        check(withLoader == QStringList{QStringLiteral("mod"), QStringLiteral("modpack")},
              "★ Z6g 会带上加载器的**只有这两类**（新加一类资源时默认落到「不带」那一档，"
              "想带就得来这儿改一个字 —— 悄悄带上去会让那一类一条都判不出来）",
              withLoader.join(QStringLiteral(" / ")));

        // 那一位的**默认值**：`InstalledItem` 是各处就地拼出来的（产品的反查那一趟、
        // 前置那一趟、这一节的样本），默认 true 才不会有旧调用点静默变成「不带」。
        ModDependencies::InstalledItem item;
        check(item.loaderApplies,
              "Z6g `InstalledItem::loaderApplies` 默认是 true（旧调用点不填时按模组那一档"
              "走，不会静默变成「不带」）");
    }

    // ---------------------------------------------------------------------
    section("Z7. 第二个来源（CurseForge）：来源本身 + 那一行筛选项");
    // ---------------------------------------------------------------------

    // 用户 2026-09-25 要的「按版本 / 模组加载器 / 来源 / 类型 / 名称搜索」里，"来源"和"类型"
    // 两栏的**所有出处**都在这儿：哪几个来源、每一栏有哪些项、以及"哪一类根本没有这一栏"
    // （Modrinth 的数据包）。界面上那四个下拉框是照这几张表填的 —— 表错了，界面上看不出
    // 任何异常，只是搜出来的东西不对。
    check(ResourceCatalog::allSources().size() == 2 &&
              ResourceCatalog::sourceKey(ResourceCatalog::Source::Modrinth) ==
                  QStringLiteral("modrinth") &&
              ResourceCatalog::sourceKey(ResourceCatalog::Source::CurseForge) ==
                  QStringLiteral("curseforge"),
          "Z7a 两个来源、两个稳定的键");
    // 这两个是专有名词，界面上不许翻译（下面这一条钉的是"没被翻过"）。
    check(ResourceCatalog::sourceLabel(ResourceCatalog::Source::Modrinth) ==
                  QStringLiteral("Modrinth") &&
              ResourceCatalog::sourceLabel(ResourceCatalog::Source::CurseForge) ==
                  QStringLiteral("CurseForge"),
          "Z7a 下拉框里那两行字就是原名");

    {
        ResourceCatalog::Source back = ResourceCatalog::Source::CurseForge;
        bool every = true;
        for (ResourceCatalog::Source source : ResourceCatalog::allSources()) {
            every = every && ResourceCatalog::sourceFromKey(ResourceCatalog::sourceKey(source), &back) &&
                    back == source;
        }
        ResourceCatalog::Source untouched = ResourceCatalog::Source::CurseForge;
        check(every && !ResourceCatalog::sourceFromKey(QStringLiteral("spigot"), &untouched) &&
                  untouched == ResourceCatalog::Source::CurseForge,
              "Z7a 键往返都认；认不出来时不动 out（和 kindFromCategoryKey 一个规矩）");
    }

    // --- Z7b. 类型那一栏的选项表 ---------------------------------------------
    {
        int emptyTables = 0;
        bool allTablesOk = true;
        QString badTable;
        for (ResourceCatalog::Source source : ResourceCatalog::allSources()) {
            for (ResourceCatalog::Kind kind : ResourceCatalog::allKinds()) {
                const QList<ResourceCatalog::FilterOption> options =
                    ResourceCatalog::categoryOptions(source, kind);
                if (options.isEmpty()) {
                    ++emptyTables;
                    // **只有一种情况该是空表**：Modrinth 的数据包（它的分类表里没有
                    // datapack 那一档）。别的组合空了 = 界面上凭空少一个框。
                    if (!(source == ResourceCatalog::Source::Modrinth &&
                          kind == ResourceCatalog::Kind::DataPack)) {
                        allTablesOk = false;
                        badTable = ResourceCatalog::sourceKey(source) +
                                   QLatin1Char('/') + ResourceCatalog::kindKey(kind);
                    }
                    continue;
                }
                // 第一项**永远是「全部」**（界面上那一格直接照抄这张表，不用自己补）。
                if (!options.first().isAll()) {
                    allTablesOk = false;
                    badTable = ResourceCatalog::sourceKey(source) + QLatin1Char('/') +
                               ResourceCatalog::kindKey(kind) + QStringLiteral(" 缺「全部」");
                    continue;
                }
                // 每一栏里那些键**两两不同**（撞了的话后一个永远选不中，而界面上看着
                // 两个选项都在）。标签也得都有 —— 空标签在下来框里是一行空白。
                QSet<QString> seen;
                for (int i = 0; i < options.size(); ++i) {
                    const ResourceCatalog::FilterOption &option = options.at(i);
                    if (option.label.isEmpty() ||
                        (!option.isAll() && seen.contains(option.key))) {
                        allTablesOk = false;
                        badTable = ResourceCatalog::sourceKey(source) + QLatin1Char('/') +
                                   ResourceCatalog::kindKey(kind) + QLatin1Char(' ') + option.key;
                        break;
                    }
                    seen.insert(option.key);
                }
            }
        }
        check(allTablesOk && emptyTables == 1,
              "Z7b 每一栏的键两两不同、第一项是「全部」；空表只有 Modrinth 的数据包那一格",
              badTable.isEmpty() ? QStringLiteral("空表 %1 张").arg(emptyTables) : badTable);
        check(ResourceCatalog::categoryOptions(ResourceCatalog::Source::CurseForge,
                                               ResourceCatalog::Kind::DataPack)
                  .size() > 1,
              "Z7b CurseForge 那边的数据包**有**类型可选（两边的母集不一样）");
    }

    // --- Z7c. 模组加载器那一栏 -----------------------------------------------
    {
        const QList<ResourceCatalog::FilterOption> modrinth =
            ResourceCatalog::loaderOptions(ResourceCatalog::Source::Modrinth);
        const QList<ResourceCatalog::FilterOption> forge =
            ResourceCatalog::loaderOptions(ResourceCatalog::Source::CurseForge);
        check(modrinth.size() == 5 && forge.size() == 5 && modrinth.first().isAll() &&
                  forge.first().isAll(),
              "Z7c 两个来源各四个加载器 + 「全部」");
        // 键**不一样**（Modrinth 要词、CurseForge 要数字），标签顺序**一样** ——
        // 顺序不一样的话，用户在两个来源之间来回切时那个下拉框里的行会跳。
        QStringList modrinthLabels;
        QStringList forgeLabels;
        for (int i = 1; i < modrinth.size(); ++i) {
            modrinthLabels.append(modrinth.at(i).label);
            forgeLabels.append(forge.at(i).label);
        }
        check(modrinth.at(1).key == QStringLiteral("fabric") &&
                  modrinth.at(2).key == QStringLiteral("forge") &&
                  modrinth.at(3).key == QStringLiteral("neoforge") &&
                  modrinth.at(4).key == QStringLiteral("quilt") &&
                  forge.at(1).key == QStringLiteral("4") && forge.at(2).key == QStringLiteral("1") &&
                  forge.at(3).key == QStringLiteral("6") && forge.at(4).key == QStringLiteral("5"),
              "Z7c 两边的键各是各的（词 vs 数字）",
              forge.at(1).key + QLatin1Char('/') + forge.at(2).key + QLatin1Char('/') +
                  forge.at(3).key + QLatin1Char('/') + forge.at(4).key);
        check(modrinthLabels == forgeLabels, "Z7c 两边的行李顺序一样（切来源时那格不跳）",
              modrinthLabels.join(QLatin1Char(',')) + QStringLiteral(" vs ") +
                  forgeLabels.join(QLatin1Char(',')));
    }

    // --- Z7d. 类目号：搜的是哪一类、装的是哪个目录，两边得是同一套号 ----------
    //
    // 这两个号一旦不一致，症状是"搜出来的是模组、装进去却是资源包"——**中间不会有任何
    // 东西报警**：搜索回的是 Modrinth/CurseForge 的项目，落点是 ModpackImport 那张表。
    check(ResourceCatalog::curseForgeClassId(ResourceCatalog::Kind::Mod) == 6 &&
              ResourceCatalog::curseForgeClassId(ResourceCatalog::Kind::DataPack) == 6945 &&
              ResourceCatalog::curseForgeClassId(ResourceCatalog::Kind::ResourcePack) == 12 &&
              ResourceCatalog::curseForgeClassId(ResourceCatalog::Kind::Shader) == 6552 &&
              ResourceCatalog::curseForgeClassId(ResourceCatalog::Kind::Modpack) == 4471,
          "Z7d 五个类目号（6945 数据包那条原来在 ModpackImport 里是**缺**的）");
    check(ModpackImport::curseForgeFilePath(ResourceCatalog::curseForgeClassId(
              ResourceCatalog::Kind::Mod)) == ResourceCatalog::folderForKind(
              ResourceCatalog::Kind::Mod) + QLatin1Char('/') &&
              ModpackImport::curseForgeFilePath(ResourceCatalog::curseForgeClassId(
                  ResourceCatalog::Kind::DataPack)) ==
                  ResourceCatalog::folderForKind(ResourceCatalog::Kind::DataPack) +
                      QLatin1Char('/') &&
              ModpackImport::curseForgeFilePath(ResourceCatalog::curseForgeClassId(
                  ResourceCatalog::Kind::ResourcePack)) ==
                  ResourceCatalog::folderForKind(ResourceCatalog::Kind::ResourcePack) +
                      QLatin1Char('/') &&
              ModpackImport::curseForgeFilePath(ResourceCatalog::curseForgeClassId(
                  ResourceCatalog::Kind::Shader)) ==
                  ResourceCatalog::folderForKind(ResourceCatalog::Kind::Shader) +
                      QLatin1Char('/'),
          "Z7d 「从下载页下」和「从整合包里来」落的是同一个目录",
          ModpackImport::curseForgeFilePath(6945));
    // 嵌套的整合包不代装（那一条是"落点为空"的约定，下载页那条路也认它）。
    check(ModpackImport::curseForgeFilePath(ResourceCatalog::curseForgeClassId(
              ResourceCatalog::Kind::Modpack))
              .isEmpty(),
          "Z7d 整合包这一类没有落点（它走导入那条路）");

    // ---------------------------------------------------------------------
    section("Z7e. CurseForge 的搜索地址（纯函数，不联网）");
    // ---------------------------------------------------------------------

    const QString fakeBase = QStringLiteral("http://127.0.0.1:9/v1");
    {
        const QString url = ResourceCatalog::searchUrl(
            ResourceCatalog::Kind::Mod, QStringLiteral("jei"), 20, 20,
            QStringLiteral("1.21.1"), QStringLiteral("4"), ResourceCatalog::Source::CurseForge,
            QStringLiteral("6814"), fakeBase);
        check(url.startsWith(fakeBase + QStringLiteral("/mods/search?")),
              "Z7e 地址前缀就是我们给的那台接口（验证工程拿它指到本机）", url);
        // 一个筛子都不能白传：这一家的 `/mods/search` **没有 project_type 这个概念**，
        // 少传 classId 会把九类东西全混在一起回给你（不报错）。
        check(urlParam(url, QStringLiteral("gameId")) == QStringLiteral("432") &&
                  urlParam(url, QStringLiteral("classId")) == QStringLiteral("6") &&
                  urlParam(url, QStringLiteral("searchFilter")) == QStringLiteral("jei") &&
                  urlParam(url, QStringLiteral("gameVersion")) == QStringLiteral("1.21.1") &&
                  urlParam(url, QStringLiteral("modLoaderType")) == QStringLiteral("4") &&
                  urlParam(url, QStringLiteral("categoryId")) == QStringLiteral("6814") &&
                  urlParam(url, QStringLiteral("index")) == QStringLiteral("20") &&
                  urlParam(url, QStringLiteral("pageSize")) == QStringLiteral("20"),
              "Z7e 六个筛子 + 分页都拼进去了", url);
        // ★ 名字那一段必须叫 `searchFilter`，**不能是 `search`**。这一条是补上去的：
        //   2026-09-26 之前我们发的是 `search=`，这一家**一个字都不筛**、也不报错，安安静静
        //   把"这一类里最热门的"那一批回给你（`totalCount` 是整类的 10000，而不是 "jei"
        //   那 377 条）—— 界面上看起来"搜出来了"，其实搜什么都是同一批。
        //   **它不报错**，所以只能靠"地址里那一段叫什么"来钉住（正面一条 + 反面一条）。
        //   （更早那句"实测 Popularity 会把搜索词无视掉"是同一个错的另一副面孔：词压根没
        //   送到，换哪个排序都一样。更正之后 sortField=6 只是为了"按总下载量"。）
        check(urlParam(url, QStringLiteral("search")).isEmpty(),
              "Z7e 地址里**没有**裸的 `search=` 那一段（发它等于没搜）", url);
        // 排序：一个值就够（TotalDownloads），但**方向必须是 desc**
        //（这一家的默认方向是 asc，那样头一条是"这一类里最没人用的"）。
        check(urlParam(url, QStringLiteral("sortField")) == QStringLiteral("6") &&
                  urlParam(url, QStringLiteral("sortOrder")) == QStringLiteral("desc"),
              "Z7e 排序用 TotalDownloads + 倒序", url);

        // 每个筛子空着 = 那一段**根本不出现**（不是发一个空值上去）。加载器那一格尤其：
        // 空串传上去会变成 `modLoaderType=`，这一家怎么处理那个值不该由我们赌。
        const QString bare = ResourceCatalog::searchUrl(
            ResourceCatalog::Kind::Shader, QString(), 0, 20, QString(), QString(),
            ResourceCatalog::Source::CurseForge, QString(), fakeBase);
        check(urlParam(bare, QStringLiteral("classId")) == QStringLiteral("6552") &&
                  urlParam(bare, QStringLiteral("gameVersion")).isEmpty() &&
                  urlParam(bare, QStringLiteral("modLoaderType")).isEmpty() &&
                  urlParam(bare, QStringLiteral("categoryId")).isEmpty() &&
                  urlParam(bare, QStringLiteral("searchFilter")).isEmpty(),
              "Z7e 不筛的项一段都不拼（那一类自己的 classId 永远在）", bare);

        // 不给地址时走的是**那唯一一处默认**（社区镜像，不要 key）——这里比的是
        // ModpackImport::curseForgeApiBase() 的返回值，不是写死一个域名：写死的话，
        // 哪天默认换了地方，这条断言就成了"两边都错得一样"的假绿。
        const QString defaultUrl = ResourceCatalog::searchUrl(
            ResourceCatalog::Kind::Mod, QString(), 0, 20, QString(), QString(),
            ResourceCatalog::Source::CurseForge, QString(), QString());
        check(defaultUrl.startsWith(ModpackImport::curseForgeApiBase(QString(), QString()) +
                                    QStringLiteral("/mods/search?")),
              "Z7e 不指定接口时走 curseForgeApiBase 那一处（域名不在这个文件里）",
              defaultUrl);

        // 版本列表那一发（`/mods/{id}/files`）：参数名和搜索那一边**一样**（谁的就是谁的），
        // 加载器也同样要数字。
        const QString files = ResourceCatalog::versionsUrl(
            QStringLiteral("238222"), QStringLiteral("1.21.1"), QStringLiteral("4"),
            ResourceCatalog::Source::CurseForge, fakeBase);
        check(files.startsWith(fakeBase + QStringLiteral("/mods/238222/files?")) &&
                  urlParam(files, QStringLiteral("gameVersion")) == QStringLiteral("1.21.1") &&
                  urlParam(files, QStringLiteral("modLoaderType")) == QStringLiteral("4"),
              "Z7e 版本列表：问哪个项目的哪个游戏版本", files);
    }

    // ---------------------------------------------------------------------
    section("Z7e2. 加载器那一格：显示名 / 数字键 → 那一边要的词形（2026-10-10 补）");
    // ---------------------------------------------------------------------

    {
        // ★★ 这一格是**静默失灵**那一类：两边要的不是一套词（CurseForge 要 `modLoaderType`
        //    的数字、Modrinth 要 `fabric` 这个词），拼错了那边**不报错**，只是什么都筛不
        //    出来 —— 而"什么都没筛出来"和"这个资源一个版本都没有"在界面上是同一句话。
        //
        //    修之前：`instanceLoaderName()` 给的是**显示名**（「Fabric」），主程序直接把它
        //    递进了这一格 ⇒ 给一个 Fabric 实例问前置，回来的可能是任意加载器的版本。
        //    所以三个来源（数字键 / 显示名 / 小写词）都得认，认不出来必须回空串。
        check(ResourceCatalog::loaderRequestValue(QStringLiteral("4"),
                                                  ResourceCatalog::Source::CurseForge) ==
                      QStringLiteral("4") &&
                  ResourceCatalog::loaderRequestValue(QStringLiteral("Fabric"),
                                                      ResourceCatalog::Source::CurseForge) ==
                      QStringLiteral("4") &&
                  ResourceCatalog::loaderRequestValue(QStringLiteral("fabric"),
                                                      ResourceCatalog::Source::CurseForge) ==
                      QStringLiteral("4"),
              "★★ Z7e2 CurseForge：数字键 / 显示名 / 小写词**三个都翻成 `4`**"
              "（下拉框给的是键、`instanceLoaderName()` 给的是显示名，两条路都得通）");
        check(ResourceCatalog::loaderRequestValue(QStringLiteral("fabric"),
                                                  ResourceCatalog::Source::Modrinth) ==
                      QStringLiteral("fabric") &&
                  ResourceCatalog::loaderRequestValue(QStringLiteral("NeoForge"),
                                                      ResourceCatalog::Source::Modrinth) ==
                      QStringLiteral("neoforge"),
              "★ Z7e2 Modrinth：要的就是那个词，显示名也认");
        check(ResourceCatalog::loaderRequestValue(QStringLiteral("  Quilt  "),
                                                  ResourceCatalog::Source::CurseForge) ==
                      QStringLiteral("5") &&
                  ResourceCatalog::loaderRequestValue(QStringLiteral("OPTIFINE"),
                                                      ResourceCatalog::Source::CurseForge)
                      .isEmpty() &&
                  ResourceCatalog::loaderRequestValue(QString(),
                                                      ResourceCatalog::Source::CurseForge)
                      .isEmpty(),
              "★★ Z7e2 认不出来的（`OptiFine`）和空串都回**空串 = 这一段根本不拼**"
              "（拼上去那边不报错，只是变成「这个资源一个版本都没有」）；"
              "两头的空白也不影响认");
    }

    // ---------------------------------------------------------------------
    section("Z7f. 读真搜索响应（meta/curseforge-search-mod.json）");
    // ---------------------------------------------------------------------

    {
        QByteArray json;
        QFile fixture(metaDir + "/curseforge-search-mod.json");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "Z7f 读到了真搜索响应夹具");
        if (haveFixture) {
            json = fixture.readAll();
            fixture.close();
        }

        const ResourceCatalog::SearchResult result = ResourceCatalog::parseCurseForgeSearch(json);
        check(result.ok && result.hits.size() == 2, "Z7f 两条都读出来了", result.problem);
        // 总数在 `pagination.totalCount`（不是 Modrinth 那个 total_hits）。
        check(result.totalHits == 10000,
              "Z7f 总数读的是 pagination.totalCount",
              QStringLiteral("%1").arg(result.totalHits));

        if (result.hits.size() == 2) {
            // 第一条（`"Arizona" Music Disc`）：一个 id、一个作者、一个加载器、一条版本。
            const ResourceCatalog::Hit &first = result.hits.at(0);
            check(first.source == ResourceCatalog::Source::CurseForge &&
                      first.projectId == QStringLiteral("1546263") &&
                      first.title == QStringLiteral("\"Arizona\" Music Disc") &&
                      first.slug == QStringLiteral("arizona-music-disc") &&
                      first.author == QStringLiteral("birdmuncher") &&
                      first.downloads == 642,
                  "Z7f 第一条的身份字段（`id` 在那边是数字，这里存成字符串）",
                  first.projectId + QStringLiteral(" / ") + first.title);
            // 名字在 `name` 里、简介在 `summary` 里 —— 两个键名和 Modrinth 都不一样，
            // 读错了的症状是**列表一整列空白**（不报错）。
            check(!first.description.isEmpty(), "Z7f 简介读的是 summary");
            // 加载器：搜索响应里根本不在 categories 里（那是「Cosmetic」这种分类标签），
            // 它在 `latestFilesIndexes[].modLoader` 那个数字上 —— 所以 `loaders()` 能给出
            // 东西，靠的是解析时把它换成了名字（explicitLoaders）。
            check(first.categories.contains(QStringLiteral("Cosmetic")) &&
                      first.loaders() == QStringList{QStringLiteral("forge")},
                  "Z7f 加载器从 modLoader 数字来，不是从 categories 现推",
                  first.categories.join(QLatin1Char(',')) + QStringLiteral(" | ") +
                      first.loaders().join(QLatin1Char(',')));
            // 图标：两条都在 media.forgecdn.net 上（放行的域名是按来源挑的），
            // 缓存 id 带来源前缀（两个 id 空间会撞：`238222` 在 Modrinth 也是合法 id）。
            check(first.iconUrl.startsWith(QStringLiteral("https://media.forgecdn.net/")) &&
                      first.iconPngUrl().startsWith(QStringLiteral("https://media.forgecdn.net/")) &&
                      first.iconCacheId() == QStringLiteral("curseforge-1546263"),
                  "Z7f 图标两条地址 + 缓存 id 带来源", first.iconCacheId());
        }

        if (result.hits.size() == 2) {
            // 第二条：`latestFilesIndexes` 里是**乱序**的 1.21 / 1.21.8 / 1.21.5 / … （真响应
            // 就这样），而且混着 1.21.10 / 1.21.11 —— 这一条正是那个比较器存在的理由：
            // 按字符串排会把 1.21.10 排到 1.21.2 前面。
            const ResourceCatalog::Hit &second = result.hits.at(1);
            const QStringList oldest = ResourceCatalog::gameVersionsOldestFirst(
                {QStringLiteral("1.21"), QStringLiteral("1.21.8"), QStringLiteral("1.21.5"),
                 QStringLiteral("1.21.1"), QStringLiteral("1.21.10"), QStringLiteral("1.21.2")});
            check(second.loaders() == QStringList{QStringLiteral("fabric")},
                  "Z7f 第二条是 Fabric 的（modLoader=4）",
                  second.loaders().join(QLatin1Char(',')));
            check(second.gameVersions.size() == 12 &&
                      second.gameVersions.first() == QStringLiteral("1.21") &&
                      second.gameVersions.last() == QStringLiteral("1.21.11"),
                  "Z7f 12 个游戏版本去重后**旧的在前**（接口给的是乱的）",
                  second.gameVersions.join(QLatin1Char(' ')));
            // 界面上第二层要的是**新的在前**：这半边靠 gameVersionChoices 统一翻一次。
            // 这一串里全是正式版（1.21.x），所以折与不折是同一份 —— Z8h 才用带快照的表验折。
            const QStringList choices = ResourceCatalog::gameVersionChoices(second.gameVersions, false);
            check(choices.first() == QStringLiteral("1.21.11") &&
                      choices.last() == QStringLiteral("1.21"),
                  "Z7f 界面上那一串是新的在前（和 Modrinth 那份落到同一个方向）",
                  choices.join(QLatin1Char(' ')));
            // 直接钉那个比较器（上面那条脏数据只是它的一个真实样本）。
            check(oldest == QStringList({QStringLiteral("1.21"), QStringLiteral("1.21.1"),
                                         QStringLiteral("1.21.2"), QStringLiteral("1.21.5"),
                                         QStringLiteral("1.21.8"), QStringLiteral("1.21.10")}),
                  "Z7g 1.10 比 1.2 新（按数字段比，不是按字符串比）",
                  oldest.join(QLatin1Char(' ')));
            check(ResourceCatalog::gameVersionsOldestFirst(
                      {QStringLiteral("1.21.1"), QStringLiteral("1.9"),
                       QStringLiteral("1.21"), QStringLiteral("1.10")}) ==
                      QStringList({QStringLiteral("1.9"), QStringLiteral("1.10"),
                                   QStringLiteral("1.21"), QStringLiteral("1.21.1")}),
                  "Z7g 1.9 < 1.10 < 1.21 < 1.21.1");
            // ★ 2026-09-26 补的三条（P4）。这个比较器改之前**不是全序**：
            //   1.9 < 1.10（数比）· 1.10 < 1.10-pre1（字符串比）· 1.10-pre1 < 1.9（字符串比），
            //   三条同时成立 = 一个圈，而它喂的是 std::stable_sort（未定义行为）。
            //   判据用"**六种入参次序排出来必须是同一个答案**"：比较器不是全序时，
            //   stable_sort 分区时"看谁先"会随入参次序变，排出来的东西就跟着变。
            {
                const QString v19 = QStringLiteral("1.9");
                const QString v110 = QStringLiteral("1.10");
                const QString v110pre = QStringLiteral("1.10-pre1");
                const QStringList expectedOldest{v19, v110, v110pre};
                const QList<QStringList> orders{
                    {v19, v110, v110pre}, {v19, v110pre, v110}, {v110, v19, v110pre},
                    {v110, v110pre, v19}, {v110pre, v19, v110}, {v110pre, v110, v19}};
                int agreed = 0;
                for (const QStringList &order : orders) {
                    if (ResourceCatalog::gameVersionsOldestFirst(order) == expectedOldest) {
                        ++agreed;
                    }
                }
                check(agreed == orders.size(),
                      "Z7h 那三段的圈没了：六种入参次序排出同一个答案（1.9 < 1.10 < 1.10-pre1）",
                      QStringLiteral("%1/6 种一致").arg(agreed));
                check(ResourceCatalog::gameVersionsOldestFirst(
                          {QStringLiteral("1.20.6"), QStringLiteral("1.20.5-pre1"),
                           QStringLiteral("1.20.5")}) ==
                          QStringList({QStringLiteral("1.20.5"),
                                       QStringLiteral("1.20.5-pre1"),
                                       QStringLiteral("1.20.6")}),
                      "Z7h 5-pre1 和 6 按**数**比（1.20.5-pre1 在 1.20.6 前面），"
                      "改动前后一致");
                check(ResourceCatalog::gameVersionsOldestFirst(
                          {QStringLiteral("Forge"), QStringLiteral("1.21"),
                           QStringLiteral("1.9")}) ==
                          QStringList({QStringLiteral("1.9"), QStringLiteral("1.21"),
                                       QStringLiteral("Forge")}),
                      "Z7h 一个数字都不带的段（CurseForge 的加载器名）排在数字版本后面");
            }
            // 读不动 / 不是一份搜索响应：两条话要分得开（和 Z4 同一个规矩）。
            const ResourceCatalog::SearchResult notSearch = ResourceCatalog::parseCurseForgeSearch(
                QByteArray(R"({"error":"Forbidden","description":null})"));
            check(!notSearch.ok && notSearch.problem.contains(QStringLiteral("Forbidden")),
                  "Z7f 接口出错时把它自己的那句话带出来", notSearch.problem);
            check(!ResourceCatalog::parseCurseForgeSearch(QByteArray("<html>403</html>")).ok,
                  "Z7f 一段 HTML：报错，不是「没搜到」");
        }
    }

    // ---------------------------------------------------------------------
    section("Z7h. 读真文件列表（meta/curseforge-files-jei.json）");
    // ---------------------------------------------------------------------

    {
        QByteArray json;
        QFile fixture(metaDir + "/curseforge-files-jei.json");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "Z7h 读到了真文件列表夹具");
        if (haveFixture) {
            json = fixture.readAll();
            fixture.close();
        }

        // 根是对象（`{"data":[…]}`）—— parseVersions **自己**认出来并转到那一家那半边，
        // 调用方不必先判来源（判的话，"哪个接口回哪种形状"就抄到调用点上了）。
        const QList<ResourceCatalog::VersionEntry> versions =
            ResourceCatalog::parseVersions(json);
        check(versions.size() == 2, "Z7h 两条（那边一条就是一个文件）",
              QStringLiteral("%1 条").arg(versions.size()));
        if (versions.size() == 2) {
            const ResourceCatalog::VersionEntry &first = versions.first();
            check(first.id == QStringLiteral("8964987") &&
                      first.versionType == QStringLiteral("beta") &&
                      first.datePublished.startsWith(QStringLiteral("2026-09-24")),
                  "Z7h 身份 / releaseType 翻成了和 Modrinth 一样的词",
                  first.id + QLatin1Char(' ') + first.versionType + QLatin1Char(' ') +
                      first.datePublished);
            // `gameVersions` 那一串里混着 `Client` / `Server` / `Forge`（真响应就长这样）：
            // 游戏版本挑出来、加载器翻成小写放进 loaders、另两个**两边都不进**。
            check(first.gameVersions ==
                      QStringList({QStringLiteral("1.21"), QStringLiteral("1.21.1")}) &&
                      first.loaders == QStringList{QStringLiteral("forge")},
                  "Z7h Client / Server 不许混进游戏版本，Forge 翻成小写进加载器",
                  first.gameVersions.join(QLatin1Char(' ')) + QStringLiteral(" | ") +
                      first.loaders.join(QLatin1Char(',')));
            const ResourceCatalog::FileEntry *file = first.primaryFile();
            check(file != nullptr &&
                      file->filename == QStringLiteral("jei-1.21.1-forge-19.57.0.449.jar") &&
                      file->size == 2246008 && file->sha1.size() == 40 &&
                      file->url.startsWith(QStringLiteral("https://edge.forgecdn.net/")) &&
                      file->unavailableNote.isEmpty(),
                  "Z7h 要下的那个文件：名字 / 字节数 / sha1（algo==1 那条）/ 地址",
                  file == nullptr ? QStringLiteral("没有文件") : file->filename);
            // 顺序：那一家回的也是新的在前（和 Modrinth 一样，界面不用按来源分叉）。
            check(versions.first().datePublished > versions.last().datePublished,
                  "Z7h 顺序是新的在前",
                  versions.first().datePublished + QStringLiteral(" / ") +
                      versions.last().datePublished);
        }

        // `downloadUrl` 是 **null** = 作者关掉了第三方分发。这一条真响应里没有样本
        //（JEI 开着），所以自己造一条 —— 它是**许可**，不是"技术上做不到"：
        // 界面上必须说清"作者不让代下"，而不是"没有可下载的文件"（后者会让用户一遍遍重试）。
        const QByteArray notDistributable = QByteArrayLiteral(
            "{\"data\":[{\"id\":123,\"fileName\":\"secret.jar\",\"fileLength\":10,"
            "\"downloadUrl\":null,\"gameVersions\":[\"1.21.1\",\"Forge\"],"
            "\"hashes\":[{\"value\":\"x\",\"algo\":2}],\"releaseType\":1}]}");
        const QList<ResourceCatalog::VersionEntry> locked =
            ResourceCatalog::parseCurseForgeVersions(notDistributable);
        check(locked.size() == 1 && locked.first().primaryFile() != nullptr &&
                  locked.first().primaryFile()->url.isEmpty() &&
                  !locked.first().primaryFile()->unavailableNote.isEmpty(),
              "Z7h downloadUrl 是 null：地址留空 + 带一句说得通的话",
              locked.isEmpty() ? QString()
                               : locked.first().primaryFile()->unavailableNote);
        // md5 那条**不能**当 sha1 用（algo 2 是 md5）。上面那份夹具两条都有，读对了才是
        // 40 位；这一份只有 md5，读出来必须是空的（不然下载校验会一路失败）。
        check(locked.size() == 1 && locked.first().primaryFile() != nullptr &&
                  locked.first().primaryFile()->sha1.isEmpty(),
              "Z7h 只有 md5 时 sha1 留空（`algo == 1` 那条才是 sha1）");
    }
}

// =========================================================================
// Z8 节：**资源详情页**那一页要的那几件（都是纯函数，离线钉得住）。
//
// 那一页（ui/ResourceDetailPage）自己只负责画：分组怎么分、chip 筛什么、时间那句怎么说、
// 渠道那一档是哪一档，全在 ResourceCatalog 里 —— 那也正是这一节要钉的。
//
// 为什么要一节专门的：这几句话**错了不会报错**，只会让人看到一份"少了几个版本"的列表
//（筛错了）、或者一条看不见的渠道标签（档位认错了）。两类都能在这一节里量出来。
// =========================================================================

static void runResourceDetailTests() {
    const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";

    // ---------------------------------------------------------------------
    section("Z8a. 「多久以前」那几档（「现在」由调用方钉死，不然每一条都会漂）");
    // ---------------------------------------------------------------------

    {
        // 固定一个"现在"，然后每档各喂一条。用**同一个** now 去算，边界才不会随当下时间漂。
        const QDateTime now = QDateTime::fromString(QStringLiteral("2026-09-26T12:00:00Z"),
                                                    Qt::ISODate);
        check(now.isValid(), "Z8a 那个固定的「现在」读得出来");
        const auto ago = [&now](qint64 seconds) {
            return now.addSecs(-seconds).toUTC().toString(Qt::ISODate);
        };
        struct Row {
            qint64 seconds;
            const char *want;
        };
        const Row rows[] = {
            {30, "刚刚"},
            {5 * 60, "5 分钟前"},
            {3 * 3600, "3 小时前"},
            {5 * 86400, "5 天前"},
            {40LL * 86400, "1 个月前"},
            {400LL * 86400, "1 年前"},
        };
        int good = 0;
        QStringList seen;
        for (const Row &row : rows) {
            const QString got = ResourceCatalog::relativeTimeText(ago(row.seconds), now);
            seen.append(got);
            if (got == QString::fromUtf8(row.want)) {
                ++good;
            }
        }
        check(good == 6, "Z8a 六档各说各的话", seen.join(QStringLiteral(" / ")));

        // 空串 / 读不懂 / 是**将来**时间：一律回空串（调用点把空串理解成"这一截不显示"）。
        // 将来时间也回空串是刻意的 —— 那说明这台机器的钟或者接口的时间戳有一个是错的，
        // 说「-3 天前」比不说更让人困惑。
        const QString noTime = ResourceCatalog::relativeTimeText(QString());
        const QString garbage = ResourceCatalog::relativeTimeText(QStringLiteral("昨天"));
        const QString future =
            ResourceCatalog::relativeTimeText(now.addDays(3).toUTC().toString(Qt::ISODate), now);
        check(noTime.isEmpty() && garbage.isEmpty() && future.isEmpty(),
              "Z8a 空串 / 读不懂 / 将来时间都回空串（那一截就不显示）",
              QStringLiteral("[%1][%2][%3]").arg(noTime, garbage, future));
    }

    // ---------------------------------------------------------------------
    section("Z8b. 发布渠道：那两个字 + 那**一档**（详情页左边那个方块）");
    // ---------------------------------------------------------------------

    {
        check(ResourceCatalog::releaseChannelNote(QStringLiteral("beta")) ==
                      QStringLiteral("测试版") &&
                  ResourceCatalog::releaseChannelNote(QStringLiteral("alpha")) ==
                      QStringLiteral("早期测试版"),
              "Z8b 测试版 / 早期测试版各两个字");
        // release 和"认不出来"都回空串：正式版是绝大多数，那两个字不是信息。
        check(ResourceCatalog::releaseChannelNote(QStringLiteral("release")).isEmpty() &&
                  ResourceCatalog::releaseChannelNote(QString()).isEmpty() &&
                  ResourceCatalog::releaseChannelNote(QStringLiteral("rc")).isEmpty(),
              "Z8b 正式版和认不出来的都不写字");

        // ★ 档位：0 绿 / 1 橙 / 2 红（详情页 ResourceDetailMarks::channelColor 按它取色）。
        const int release = ResourceCatalog::releaseChannelRank(QStringLiteral("release"));
        const int beta = ResourceCatalog::releaseChannelRank(QStringLiteral("beta"));
        const int alpha = ResourceCatalog::releaseChannelRank(QStringLiteral("alpha"));
        const int unknown = ResourceCatalog::releaseChannelRank(QStringLiteral("rc"));
        const int empty = ResourceCatalog::releaseChannelRank(QString());
        check(release == 0 && beta == 1 && alpha == 2,
              "Z8b 三档的次序就是 release / beta / alpha",
              QStringLiteral("%1 %2 %3").arg(release).arg(beta).arg(alpha));
        // ★ 认不出来回 **-1**，不是 0。回 0 等于把一条不知道是什么渠道的版本画成绿色的
        //   "正式版" —— 那是把"不知道"说成了"很稳"。
        check(unknown == -1 && empty == -1,
              "Z8b 认不出来回 -1（不是 0：那会把它画成绿色的正式版）",
              QStringLiteral("%1 / %2").arg(unknown).arg(empty));
        // 和上面那两个字必须是同一套判据（一个说字、一个说档；错开的话界面上会出现
        // "写着测试版、方块却是绿的"）。
        check((release == 0) == ResourceCatalog::releaseChannelNote(QStringLiteral("release"))
                                    .isEmpty(),
              "Z8b 档位和那两个字说的是同一件事（正式版：无字 + 第 0 档）");
    }

    // ---------------------------------------------------------------------
    section("Z8c. 加载器显示名（认不出来原样还回去）");
    // ---------------------------------------------------------------------

    check(ResourceCatalog::loaderDisplayName(QStringLiteral("fabric")) ==
                  QStringLiteral("Fabric") &&
              ResourceCatalog::loaderDisplayName(QStringLiteral("NeoForge")) ==
                  QStringLiteral("NeoForge") &&
              ResourceCatalog::loaderDisplayName(QStringLiteral("optifine")) ==
                  QStringLiteral("optifine"),
          "Z8c 四个加载器有自己的写法；没见过的原样还回去（不编、也不空）");

    // ---------------------------------------------------------------------
    section("Z8d. 版本行那一行小字（喂真夹具）");
    // ---------------------------------------------------------------------

    QByteArray versionsJson;
    {
        QFile fixture(metaDir + "/modrinth-versions-iris.json");
        if (fixture.open(QIODevice::ReadOnly)) {
            versionsJson = fixture.readAll();
            fixture.close();
        }
    }
    const QList<ResourceCatalog::VersionEntry> versions =
        ResourceCatalog::parseVersions(versionsJson);
    check(versions.size() == 12, "Z8d 真夹具读回来 12 条",
          QStringLiteral("%1 条").arg(versions.size()));

    if (versions.size() == 12) {
        // 那一行是**拼出来的**：加载器 / 文件名 / 下载量 / 更新于 / 渠道，各缺各的不写。
        // 逐条查一遍"每一截该在的都在、不该在的都不在"比对着一条写死那句话结实得多
        //（明天接口多一格、少一格，这里不会变成一条假的失败）。
        int complete = 0;
        bool betaHasNote = false;
        bool releaseHasNoNote = true;
        for (const ResourceCatalog::VersionEntry &version : versions) {
            const QString line = ResourceCatalog::versionRowSubText(version);
            const ResourceCatalog::FileEntry *file = version.primaryFile();
            const bool ok = !line.isEmpty() && file != nullptr &&
                            line.contains(file->filename) &&
                            line.contains(ResourceCatalog::loaderDisplayName(
                                version.loaders.value(0)));
            if (ok) {
                ++complete;
            }
            if (version.versionType == QStringLiteral("beta") && line.contains(QStringLiteral("测试版"))) {
                betaHasNote = true;
            }
            if (version.versionType == QStringLiteral("release") &&
                ResourceCatalog::releaseChannelNote(version.versionType).isEmpty()) {
                releaseHasNoNote = !line.contains(QStringLiteral("测试版")) &&
                                   !line.contains(QStringLiteral("早期测试版"));
            }
        }
        check(complete == 12, "Z8d 12 条的小字里都有加载器和文件名", QStringLiteral("%1/12").arg(complete));
        // 夹具里那一条 beta（Z6 钉过它就是最新那条）：「测试版」三个字必须真的出现在那一行。
        check(betaHasNote, "Z8d 测试版那一行的末尾确实写着「测试版」");
        check(releaseHasNoNote, "Z8d 正式版那一行**不写**渠道（那两个字不是信息）");
    }

    // ---------------------------------------------------------------------
    section("Z8e. 分组：一组 = 一个游戏版本 + 一个加载器");
    // ---------------------------------------------------------------------

    if (versions.size() == 12) {
        const QList<ResourceCatalog::VersionGroup> groups =
            ResourceCatalog::groupVersions(versions, false);
        check(!groups.isEmpty(), "Z8e 分得出组", QStringLiteral("%1 组").arg(groups.size()));

        // 每一个版本都**恰好**进一个组（不是"每个声明过的游戏版本各进一次"——那样同一条会在
        // 一屏里出现好几遍，用户数不清自己到底有几个版本）。
        int inGroups = 0;
        for (const ResourceCatalog::VersionGroup &group : groups) {
            inGroups += group.versions.size();
        }
        check(inGroups == versions.size(), "Z8e 12 条一条不多一条不少地全在组里",
              QStringLiteral("%1/12").arg(inGroups));

        // 组头那行字：加载器 + 游戏版本（两个都没有时是「其它版本」）。
        int titled = 0;
        for (const ResourceCatalog::VersionGroup &group : groups) {
            const QString title = group.title();
            const bool ok = !title.isEmpty() &&
                            (group.loader.isEmpty()
                                 ? title == (group.gameVersion.isEmpty() ? QStringLiteral("其它版本")
                                                                         : group.gameVersion)
                                 : title.endsWith(group.gameVersion) &&
                                       title.startsWith(
                                           ResourceCatalog::loaderDisplayName(group.loader)));
            if (ok) {
                ++titled;
            }
        }
        check(titled == groups.size(), "Z8e 每个组头都是「加载器 游戏版本」那两截",
              QStringLiteral("%1/%2").arg(titled).arg(groups.size()));

        // 组的顺序：游戏版本新的在前。夹具这一份是新在前排好的（Z6 钉过），而分组是按输入
        // 次序走一遍、遇到的第一个（游戏版本 + 加载器）对开第一组 —— 所以**最新那条版本
        // 落的那一组就是头一组**。（比大小的那个 compareVersionText 是 ResourceCatalog 内部
        // 的东西、不对外，所以这儿换一条等价的说法来钉顺序。）
        if (!groups.isEmpty()) {
            bool firstGroupHoldsNewest = false;
            for (const ResourceCatalog::VersionEntry &version : groups.first().versions) {
                if (version.id == versions.first().id) {
                    firstGroupHoldsNewest = true;
                }
            }
            check(firstGroupHoldsNewest, "Z8e 头一组装的就是最新那条版本（新的在前）",
                  groups.first().title());
        }
    }

    // ---------------------------------------------------------------------
    section("Z8f. ★ chip 筛的是**这一版声明过的游戏版本**，不是它落在哪个组里");
    // ---------------------------------------------------------------------

    if (versions.size() == 12) {
        const QList<ResourceCatalog::VersionGroup> groups =
            ResourceCatalog::groupVersions(versions, false);

        // 找一条"声明了不止一个游戏版本"的版本（夹具里有）：它只会落在其中一档的组里，
        // 而选了另一档时它照样该在。这正是那两步不能合并的理由。
        const ResourceCatalog::VersionEntry *multi = nullptr;
        for (const ResourceCatalog::VersionEntry &version : versions) {
            if (version.gameVersions.size() > 1) {
                multi = &version;
                break;
            }
        }
        check(multi != nullptr, "Z8f 夹具里有一条声明了多个游戏版本的版本");
        if (multi != nullptr) {
            // 它落的那一组是哪一档：**从分组结果里读**，不猜。声明表的顺序不等于新旧顺序
            // （夹具里就是旧的在前），谁是最新那一档由 compareVersionText 说了算。
            QString groupedUnder;
            for (const ResourceCatalog::VersionGroup &group : groups) {
                for (const ResourceCatalog::VersionEntry &version : group.versions) {
                    if (version.id == multi->id && groupedUnder.isEmpty()) {
                        groupedUnder = group.gameVersion;
                    }
                }
            }
            // 它声明过、但**不是**它落的那一档：拿这一档去筛。
            QString other;
            for (const QString &gameVersion : multi->gameVersions) {
                if (gameVersion != groupedUnder) {
                    other = gameVersion;
                }
            }
            check(!groupedUnder.isEmpty() && !other.isEmpty(),
                  "Z8f 它声明了两档、只落在其中一档（组归属 ≠ 全部声明）",
                  groupedUnder + " / " + other);
            if (!other.isEmpty()) {
                // ★ 按"另一档"筛，它必须在结果里 —— 只看"落在哪个组里"的写法会把它漏掉，
                //   而界面上看起来只是"这个模组少列了几版"，没有人会报错。
                const QList<ResourceCatalog::VersionEntry> filtered =
                    ResourceCatalog::versionsForGameVersion(versions, other, false);
                bool found = false;
                for (const ResourceCatalog::VersionEntry &version : filtered) {
                    if (version.id == multi->id) {
                        found = true;
                    }
                }
                check(found, "★ Z8f 按另一档筛，它**在**（筛看 gameVersions，不看组归属）",
                      QStringLiteral("%1 档筛出 %2 条").arg(other).arg(filtered.size()));
                // 反过来：只筛出真的声明了那一档的（筛出来的每一条都声明过它）。
                int allDeclare = 0;
                for (const ResourceCatalog::VersionEntry &version : filtered) {
                    if (version.gameVersions.contains(other)) {
                        ++allDeclare;
                    }
                }
                check(allDeclare == filtered.size(),
                      "Z8f 筛出来的每一条都真的声明过那一档",
                      QStringLiteral("%1/%2").arg(allDeclare).arg(filtered.size()));
                // 而且这一档确实筛掉了一些（不然这条测试什么也没验到）。
                check(filtered.size() < versions.size(),
                      "Z8f 这一档确实筛掉了一些（不是「全都支持」）",
                      QStringLiteral("%1/%2").arg(filtered.size()).arg(versions.size()));
            }
        }

        // 空串 = 「全部」那一颗：原样还回去（不是"筛一个空串"——那会一条都不剩）。
        const QList<ResourceCatalog::VersionEntry> all =
            ResourceCatalog::versionsForGameVersion(versions, QString(), false);
        check(all.size() == versions.size() && all.first().id == versions.first().id,
              "Z8f chip「全部」= 不筛（原样那一份）");
        // 一个谁都没声明过的版本号 → 空表（界面上那一句「这个游戏版本上没有可下载的版本」）。
        check(ResourceCatalog::versionsForGameVersion(versions, QStringLiteral("26.2hyperland"),
                                                      false)
                  .isEmpty(),
              "Z8f 谁都没声明过的版本 → 空表");
    }

    // ---------------------------------------------------------------------
    section("Z8f2. ★ 当前实例那个加载器排前面（同一档游戏版本里的第三个排序键）");
    // ---------------------------------------------------------------------
    //
    // 用户原话：「点开某个模组等的时候…对应的模组加载器的版本放在前面…展示为对应版本适用的」。
    // 排序键一共三档，**次序不能换**：
    //   ① 游戏版本（新的在前）—— 换了的话，点名 neoforge 就会把 1.20.1 那一组顶到 1.21.4
    //      前面去，用户一眼看见的是"这个模组只支持老版本"；
    //   ② 同一档游戏版本里，被点名的加载器在前（没点名时是 loaderOrderIndex 那个老次序）；
    //   ③ 输入次序（`std::stable_sort` 保住的）。
    //
    // 这一节拿一份**合成**清单来钉，不借 Z8d 那份真夹具：要钉的是"哪一组的键是什么"，
    // 手写的六条比真夹具里那 12 条看得清（而且真夹具里 fabric 本来就排在前面 —— 拿它
    // 钉"点名生效了吗"是钉不住的，换个加载器才行）。
    {
        // 输入次序就是下面这个次序（分组是"按输入走一遍、遇到的第一个对开第一组"）。
        const auto entryOf = [](const QString &id, const QString &gameVersion,
                                const QString &loader) {
            ResourceCatalog::VersionEntry entry;
            entry.id = id;
            entry.gameVersions = QStringList{gameVersion};
            entry.loaders = QStringList{loader};
            return entry;
        };
        const QList<ResourceCatalog::VersionEntry> pool = {
            entryOf(QStringLiteral("forge-a"), QStringLiteral("1.21.4"), QStringLiteral("forge")),
            entryOf(QStringLiteral("forge-a2"), QStringLiteral("1.21.4"), QStringLiteral("forge")),
            entryOf(QStringLiteral("fabric-b"), QStringLiteral("1.21.4"), QStringLiteral("fabric")),
            entryOf(QStringLiteral("neo-c"), QStringLiteral("1.21.4"), QStringLiteral("neoforge")),
            entryOf(QStringLiteral("fabric-d"), QStringLiteral("1.20.1"), QStringLiteral("fabric")),
            entryOf(QStringLiteral("forge-e"), QStringLiteral("1.20.1"), QStringLiteral("forge")),
            entryOf(QStringLiteral("quilt-f"), QStringLiteral("1.21.4"), QStringLiteral("quilt")),
        };
        // 组的身份就写成「加载器/游戏版本」—— 两张表并排比一眼就能看出哪一组挪了位。
        const auto keysOf = [](const QList<ResourceCatalog::VersionGroup> &groups) {
            QStringList keys;
            for (const ResourceCatalog::VersionGroup &group : groups) {
                keys << (group.loader + QLatin1Char('/') + group.gameVersion);
            }
            return keys;
        };

        const QStringList plain = keysOf(ResourceCatalog::groupVersions(pool, false));
        check(plain == QStringList{QStringLiteral("fabric/1.21.4"), QStringLiteral("forge/1.21.4"),
                                   QStringLiteral("neoforge/1.21.4"), QStringLiteral("quilt/1.21.4"),
                                   QStringLiteral("fabric/1.20.1"), QStringLiteral("forge/1.20.1")},
              "Z8f2 前提：不点名时是那个老次序（游戏版本新的在前，同一档里按固定那张表）",
              plain.join(QStringLiteral(", ")));

        // ★ 点名 forge：同一档游戏版本里它就得到最前面 —— 而**游戏版本那一档不动**。
        const QStringList wanted =
            keysOf(ResourceCatalog::groupVersions(pool, false, QStringLiteral("forge")));
        check(wanted ==
                  QStringList{QStringLiteral("forge/1.21.4"), QStringLiteral("fabric/1.21.4"),
                              QStringLiteral("neoforge/1.21.4"), QStringLiteral("quilt/1.21.4"),
                              QStringLiteral("forge/1.20.1"), QStringLiteral("fabric/1.20.1")},
              "★ Z8f2 点名 forge：它到了每一档游戏版本的最前面（别的组跟着顺、组数不多不少）",
              wanted.join(QStringLiteral(", ")));
        check(wanted.size() == plain.size(),
              "★ Z8f2 排前面**只是挪位置**，不是把别的组筛掉（用户要的是「放前面」）",
              QStringLiteral("%1 vs %2").arg(wanted.size()).arg(plain.size()));
        // ★ 这条才是"三档键次序不能换"的判据：1.20.1 那个 forge 组**排在所有 1.21.4 组后面**。
        //   它要是跑到最前面，用户看见的第一屏就是"这个模组只支持 1.20.1"。
        const int oldForge = wanted.indexOf(QStringLiteral("forge/1.20.1"));
        const int newestQuilt = wanted.indexOf(QStringLiteral("quilt/1.21.4"));
        check(oldForge > newestQuilt && newestQuilt >= 0,
              "★★ Z8f2 而不许把**老那一档**的加载器组顶到新版本前面（游戏版本永远是第一排序键）",
              QStringLiteral("forge/1.20.1 在第 %1 位、quilt/1.21.4 在第 %2 位")
                  .arg(oldForge)
                  .arg(newestQuilt));

        // 传进来的是**显示名**（「Forge」）或带空白时也认。调用点那一侧写的是
        // loaderGroupKey(instanceLoaderName(...))，本来就是小写；这里钉的是"这一层自己
        // 兜得住"—— 哪天有人图省事把显示名直接递进来，不会静默地按"没点名"处理
        //（那种错的形状是"排前面没生效"，屏幕上一点异常都没有）。
        check(keysOf(ResourceCatalog::groupVersions(pool, false, QStringLiteral("Forge"))) == wanted,
              "Z8f2 点名那串大小写不一样也认（「Forge」和 forge 同一组）");
        check(keysOf(ResourceCatalog::groupVersions(pool, false, QStringLiteral("  forge  "))) ==
                  wanted,
              "Z8f2 两头带空白也认（调用点那边 trim 过，这一层自己也兜一下）");
        // 认不出来的加载器（比如实例装的是 OptiFine）⇒ 全组都按老次序，一个字都不动。
        check(keysOf(ResourceCatalog::groupVersions(pool, false, QStringLiteral("optifine"))) == plain,
              "★ Z8f2 点名一个这里没有的加载器 = 没点名（不许把整张表搅乱）");
        check(keysOf(ResourceCatalog::groupVersions(pool, false, QString())) == plain,
              "Z8f2 不传这一位（默认那个空串）也是没点名 —— 老调用点行为一个字不变");

        // 同一组里**条目的次序**不动（stable_sort 那个"稳"说的就是这一条）：两条同组时
        // 进来什么次序，出去还是什么次序（接口给的那份通常已经是新的在前）。
        for (const ResourceCatalog::VersionGroup &group : ResourceCatalog::groupVersions(
                 pool, false, QStringLiteral("forge"))) {
            if (group.loader == QStringLiteral("forge") && group.gameVersion == QStringLiteral("1.21.4")) {
                check(group.versions.size() == 2 && group.versions.first().id == QStringLiteral("forge-a"),
                      "Z8f2 同一组里两条的次序照旧（新的在前，排序不许把它翻过来）",
                      QStringLiteral("%1 条，头一条 %2")
                          .arg(group.versions.size())
                          .arg(group.versions.value(0).id));
            }
        }
    }

    // ---------------------------------------------------------------------
    section("Z8g. 头卡那行元信息 + 那两颗按钮的地址");
    // ---------------------------------------------------------------------

    {
        ResourceCatalog::Hit hit;
        hit.source = ResourceCatalog::Source::Modrinth;
        hit.projectId = QStringLiteral("AANobbMI");
        hit.slug = QStringLiteral("sodium");
        hit.title = QStringLiteral("Sodium");
        hit.explicitLoaders = QStringList{QStringLiteral("fabric"), QStringLiteral("neoforge")};
        hit.downloads = 231000000;
        // "5 天前"：和 Z8a 一样把"现在"钉死做不到（这一句读的是当下时间），所以喂一条
        // 相对当下算出来的时间戳 —— 差几毫秒不会跨档。
        hit.updatedIso = QDateTime::currentDateTimeUtc().addDays(-5).toString(Qt::ISODate);
        const QString line = ResourceCatalog::hitMetaLine(hit);
        check(line.contains(QStringLiteral("Fabric / NeoForge")) && line.contains(QStringLiteral("下载")) &&
                  line.contains(QStringLiteral("更新于 5 天前")) &&
                  line.endsWith(QStringLiteral("Modrinth")),
              "Z8g 四截都在、且按「 · 」拼起来", line);

        // 缺的那几截就不写：一个加载器都没有（数据包那类）、下载量 0（接口没给）、
        // 时间读不懂。**来源那一截总在** —— 这一行是"这是哪一家来的"。
        ResourceCatalog::Hit bare;
        bare.source = ResourceCatalog::Source::CurseForge;
        bare.title = QStringLiteral("某某");
        const QString bareLine = ResourceCatalog::hitMetaLine(bare);
        check(bareLine == QStringLiteral("CurseForge"),
              "Z8g 什么都没有时只剩来源那一截（不写「下载 0 次」，也不写「-3 天前」）", bareLine);

        // 那两颗「转到 XXX」的网址：两家形状不一样，类名错了回 404 而**不报错**。
        check(ResourceCatalog::projectPageUrl(ResourceCatalog::Source::Modrinth,
                                              ResourceCatalog::Kind::Mod,
                                              QStringLiteral("sodium")) ==
                  QStringLiteral("https://modrinth.com/mod/sodium"),
              "Z8g Modrinth 那条地址");
        check(ResourceCatalog::projectPageUrl(ResourceCatalog::Source::CurseForge,
                                              ResourceCatalog::Kind::Mod,
                                              QStringLiteral("jei")) ==
                  QStringLiteral("https://www.curseforge.com/minecraft/mc-mods/jei"),
              "Z8g CurseForge 那条地址（目录名是 mc-mods，不是我们那份 kindKey）");
        // slug 空 = 拼不出来 → 空串（那一页就不画那颗按钮：摆一颗点了没反应的比不摆糟）。
        check(ResourceCatalog::projectPageUrl(ResourceCatalog::Source::Modrinth,
                                              ResourceCatalog::Kind::Mod, QString())
                  .isEmpty(),
              "Z8g 没有 slug 就不拼地址（那颗按钮不画）");
        // MC 百科那边是按名字搜（它没有"按对面的 id 直接跳"的路）。
        const QString mcmod = ResourceCatalog::mcmodSearchUrl(QStringLiteral("钠 Sodium"));
        check(mcmod.startsWith(QStringLiteral("https://")) && mcmod.contains(QStringLiteral("%20")),
              "Z8g MC 百科那条是「按名字搜」的地址，名字照原样转义", mcmod);
    }

    // ---------------------------------------------------------------------
    section("Z8g2. ★★ 一条 Hit 写进 json 再读回来，一个字段都不许丢");
    // ---------------------------------------------------------------------

    // ★★ 2026-10-10（用户原话：「模组图标做本地缓存功能，不要每次都拉取」）：盘上那份
    // 缓存（`<数据目录>/cache/instance-icons/<实例>.json`）里存的就是这条 Hit —— 它是
    // 「第一次查出来那个资源长什么样」的唯一载体。少写一栏的症状不是报错，而是**那一页
    // 顶着一个空标题 / 那一格退回占位拼图**（"缓存命中了但画不出来"），而且只在**第二次
    // 启动**才现形 —— 所以这一节逐个字段对着钉。
    {
        ResourceCatalog::Hit hit;
        hit.projectId = QStringLiteral("AANobbMI");
        hit.slug = QStringLiteral("sodium");
        hit.title = QStringLiteral("钠 Sodium");
        hit.description = QStringLiteral("渲染优化 · 帧数翻倍"); // 带空格 / 点 / 中文
        hit.author = QStringLiteral("jellysquid3");
        hit.downloads = 231000000LL;
        hit.categories = QStringList{QStringLiteral("optimization"),
                                     QStringLiteral("technology")};
        hit.gameVersions = QStringList{QStringLiteral("1.21.1"), QStringLiteral("1.21")};
        hit.source = ResourceCatalog::Source::CurseForge;
        hit.explicitLoaders = QStringList{QStringLiteral("fabric"), QStringLiteral("quilt")};
        hit.iconUrl = QStringLiteral("https://media.forgecdn.net/avatars/238/222/256/256.jpeg");
        hit.iconFallbackUrl = QStringLiteral("https://media.forgecdn.net/avatars/238/222/t.png");
        hit.updatedIso = QStringLiteral("2026-09-01T12:34:56Z");

        const ResourceCatalog::Hit back =
            ResourceCatalog::hitFromJson(ResourceCatalog::hitToJson(hit));
        check(back.projectId == hit.projectId && back.slug == hit.slug &&
                  back.title == hit.title && back.description == hit.description &&
                  back.author == hit.author && back.downloads == hit.downloads,
              "Z8g2 名字那一批字段往返不走样",
              QStringLiteral("%1 / %2 / %3").arg(back.projectId, back.title, back.description));
        check(back.categories == hit.categories && back.gameVersions == hit.gameVersions &&
                  back.explicitLoaders == hit.explicitLoaders,
              "Z8g2 三个清单（分类 / 游戏版本 / 加载器）**次序也照原样**",
              back.gameVersions.join(QStringLiteral(", ")));
        check(back.source == hit.source && back.iconUrl == hit.iconUrl &&
                  back.iconFallbackUrl == hit.iconFallbackUrl && back.updatedIso == hit.updatedIso,
              "Z8g2 来源 / 两条图标地址 / 更新时间也在",
              QStringLiteral("source=%1").arg(ResourceCatalog::sourceKey(back.source)));
        // **缓存键**（`<来源前缀>-<项目号>`）—— 图标那一格是按它找盘的。这一栏丢了的话，
        // 缓存里读出来的这条会去问一个不存在的键：每一格都变成重新下载。
        check(back.iconCacheId() == hit.iconCacheId() &&
                  back.iconCacheId() == QStringLiteral("curseforge-AANobbMI"),
              "Z8g2 而且缓存键一字不差（= 来源前缀 + 项目号）", back.iconCacheId());
    }
    {
        // 空的那一份（接口只给了个号、别的什么都没说）：往返之后还是空的 ——
        // **不许凭空长出东西来**（比如把 downloads 变成 0、或者给出一个野来源）。
        ResourceCatalog::Hit bare;
        bare.projectId = QStringLiteral("P7dR8mSH");
        const ResourceCatalog::Hit back =
            ResourceCatalog::hitFromJson(ResourceCatalog::hitToJson(bare));
        check(back.projectId == bare.projectId && back.slug.isEmpty() &&
                  back.title.isEmpty() && back.description.isEmpty() &&
                  back.author.isEmpty() && back.downloads == 0 && back.categories.isEmpty() &&
                  back.gameVersions.isEmpty() && back.explicitLoaders.isEmpty() &&
                  back.iconUrl.isEmpty() && back.iconFallbackUrl.isEmpty() &&
                  back.updatedIso.isEmpty(),
              "Z8g2 空的那一份往返之后还是空的（不凭空长字段出来）",
              back.title);
        check(back.source == ResourceCatalog::Source::Modrinth,
              "Z8g2 没写来源时按 Modrinth 读（老缓存 / 手写的那一份不该被认成别家）",
              ResourceCatalog::sourceKey(back.source));
    }
    {
        // 读一份**缺字段 / 字段类型不对**的 json：一律当"没有那一栏"，不许崩、不许抛。
        // （盘上那份是上一次运行的自己写的，但用户可能手改、也可能来自更老的版本。）
        const QJsonObject junk{
            {QStringLiteral("projectId"), QStringLiteral("AANobbMI")},
            {QStringLiteral("title"), 42},                       // 该是字符串，给了数字
            {QStringLiteral("gameVersions"), QStringLiteral("1.21")}, // 该是数组，给了字符串
            {QStringLiteral("downloads"), QStringLiteral("很多")},    // 该是数字，给了字符串
            {QStringLiteral("source"), QStringLiteral("no-such-source")}, // 认不出来的来源
        };
        const ResourceCatalog::Hit back = ResourceCatalog::hitFromJson(junk);
        check(back.projectId == QStringLiteral("AANobbMI") && back.title.isEmpty() &&
                  back.gameVersions.isEmpty() && back.downloads == 0,
              "Z8g2 类型对不上的那几栏一律当没有（读盘的东西不能因为一份坏 json 就炸）",
              QStringLiteral("title=%1 downloads=%2").arg(back.title).arg(back.downloads));
        check(back.source == ResourceCatalog::Source::Modrinth,
              "Z8g2 认不出来的来源退回 Modrinth（不是「没有来源」这种第三态）",
              ResourceCatalog::sourceKey(back.source));
    }

    // ---------------------------------------------------------------------
    section("Z8h. ★ 快照版归到对应的大版本（26.2-rc1 → 26.2）");
    // ---------------------------------------------------------------------

    // 用户原话：「把快照版本的模组放到对应的大版本里（如 26.2rc1 放在 26.2 里）」，外加
    // 详情页上方那颗「显示快照版」勾选框。这一节分三层钉：认不认得出是快照 → 折不折得动 →
    // 那排 chip / 按 chip 筛 / 组头三处说的**是不是同一个值**（三处传岔了的症状是"点了 26.2
    // 少了几个版本"，而那排 chip 本身看着完全正常，见 ResourceCatalog.hpp 那三段注释）。
    {
        // 认得出的两类：尾巴上带 -preN / -rcN 的（新老两套命名都长这样）、老式快照号
        //（两位年 + 'w' + 两位周 + 一个小写字母）。
        const QStringList snapshots = {QStringLiteral("26.2-rc1"),
                                       QStringLiteral("1.21.4-pre3"),
                                       QStringLiteral("24w14a"),
                                       QStringLiteral("13w41b"),
                                       // 2026-09-27 加的两套：以前一条都不认
                                       //（见 ResourceCatalog.cpp 里 snapshotShapeOf）。
                                       QStringLiteral("26.2-snapshot-1"),
                                       QStringLiteral("1.14 Pre-Release 3")};
        int recognized = 0;
        for (const QString &version : snapshots) {
            if (ResourceCatalog::isSnapshotGameVersion(version)) {
                ++recognized;
            }
        }
        check(recognized == snapshots.size(), "Z8h 六颗快照都认得出",
              QStringLiteral("%1/%2").arg(recognized).arg(snapshots.size()));

        // **认不出来的一律不算快照**。判错的代价不对称：把一条正式版说成快照，它会被折进
        // 大版本（用户在那排 chip 里找不到它，而这件事在界面上没有任何提示）；反过来只是
        // 多摆一颗。愚人节/实验版（20w14∞、26.2hyperland）和那些带尾巴的正式版全在这儿。
        const QStringList notSnapshots = {QStringLiteral("1.21.4"),
                                          QStringLiteral("26.2"),
                                          QString(),
                                          QStringLiteral("1.14.3 - Combat Test"),
                                          QStringLiteral("26.2hyperland"),
                                          QStringLiteral("20w14∞"),
                                          // 愚人节版。折出来是 `1.RV` —— 一个谁也不是的
                                          // 大版本，摆在那一排里用户点进去什么都搜不到
                                          //（见 .cpp 里 isPlainVersionStem）。
                                          QStringLiteral("1.RV-Pre1"),
                                          // 尾巴不是"末尾那一段"：`pre3` 后面还挂着一截。
                                          QStringLiteral("1.21.4-pre3-1")};
        int wrongly = 0;
        QString wrongSample;
        for (const QString &version : notSnapshots) {
            if (ResourceCatalog::isSnapshotGameVersion(version)) {
                ++wrongly;
                if (wrongSample.isEmpty()) {
                    wrongSample = version;
                }
            }
        }
        check(wrongly == 0, "Z8h 正式版和愚人节版一颗都不许被认成快照（认错就藏起来了）",
              wrongSample.isEmpty() ? QString() : wrongSample);

        check(ResourceCatalog::majorGameVersionOf(QStringLiteral("26.2-rc1")) ==
                  QStringLiteral("26.2"),
              "Z8h 26.2-rc1 折成 26.2");
        check(ResourceCatalog::majorGameVersionOf(QStringLiteral("1.21.4-pre3")) ==
                  QStringLiteral("1.21.4"),
              "Z8h 1.21.4-pre3 折成 1.21.4");
        check(ResourceCatalog::majorGameVersionOf(QStringLiteral("1.21.4")) ==
                  QStringLiteral("1.21.4"),
              "Z8h 正式版原样还回去（调用方不必先判一次「这是不是快照」）");
        check(ResourceCatalog::majorGameVersionOf(QStringLiteral("24w14a")) ==
                  QStringLiteral("24w14a"),
              "Z8h 老式快照号折不动，原样还回去");
        // "折不动"这件事**只有一个判据**（折完还是快照），两处都得按它判 —— 谁要是改成
        // "看它有没有 '-'"，24w14a 就会被当成折过了，于是它会顶着 `24w14a` 这颗 chip 露在
        // 一个叫「显示快照版」的勾选框没勾的界面上。
        check(ResourceCatalog::isSnapshotGameVersion(
                  ResourceCatalog::majorGameVersionOf(QStringLiteral("24w14a"))),
              "Z8h 「折不动」的判据：折完还是快照");

        // ---- 2026-09-27：真清单说了算 ----
        //
        // 上面那几颗是**手写**的，而手写的永远只覆盖得到"作者想得到的写法" —— 新式快照号
        // （`26.2-snapshot-1`）漏掉就是这么漏的：它既没有 -pre/-rc、长度也不是 6，六年前
        // 写下的两条判据一条都套不上。所以这一条拿**真清单**（915 条）过：凡是长得像快照
        // 的那两族（`-snapshot-` / `pre-release`），每一条都必须认得出、折得出，而且折出来
        // 的那个大版本**必须在清单里真有一条**（不然等于凭空造一个版本摆给用户）。
        //
        // NOTE: 愚人节版（20w14∞、24w14potato、3D Shareware v1.34）天然不在这两族里 ——
        //       它们的名字里没有这两个词，所以"按设计不算快照"这件事不受这一条影响。
        {
            // 这里**自己读一遍**夹具（不复用上面 Y 那一节解析出来的那份）：它俩离得远，
            // 中间还隔着几十节，借一个"这一节还看得见吗"的变量比读一遍文件难查得多。
            const QJsonObject root =
                loadJson(QStringLiteral(REPO_ROOT_PATH) + "/tests/meta/manifest.json");
            const QJsonArray entries = root.value(QStringLiteral("versions")).toArray();
            QSet<QString> allIds;
            for (const QJsonValue &value : entries) {
                allIds.insert(value.toObject().value(QStringLiteral("id")).toString());
            }
            int newStyle = 0;
            QString badSample;
            for (const QJsonValue &value : entries) {
                const QJsonObject entry = value.toObject();
                if (entry.value(QStringLiteral("type")).toString() != QStringLiteral("snapshot")) {
                    continue;
                }
                const QString id = entry.value(QStringLiteral("id")).toString();
                const QString lower = id.toLower();
                if (!lower.contains(QStringLiteral("-snapshot-")) &&
                    !lower.contains(QStringLiteral("pre-release"))) {
                    continue;
                }
                ++newStyle;
                const QString folded = ResourceCatalog::majorGameVersionOf(id);
                const bool ok = ResourceCatalog::isSnapshotGameVersion(id) && folded != id &&
                                !ResourceCatalog::isSnapshotGameVersion(folded) &&
                                allIds.contains(folded);
                if (!ok && badSample.isEmpty()) {
                    badSample = QStringLiteral("%1 → %2").arg(id, folded);
                }
            }
            check(newStyle == 40, "Z8h 真清单里长得像新族快照的有 40 条",
                  QString::number(newStyle));
            check(badSample.isEmpty(),
                  "★ Z8h 这 40 条**每一条**都认得出、折得出、折出来的大版本清单里真有",
                  badSample);
        }

        // 那一排 chip。接口给的 `Hit::gameVersions` 是**旧的在前**（见 Z3），所以这一串写
        // 成旧的在前；倒着画出来的第一颗应该是最新的那个大版本。
        ResourceCatalog::Hit hit;
        hit.gameVersions = QStringList{
            QStringLiteral("1.20.1"),  QStringLiteral("1.21.4-pre3"), QStringLiteral("1.21.4"),
            QStringLiteral("26.2"),    QStringLiteral("26.2-rc1"),    QStringLiteral("26.2-rc2"),
            QStringLiteral("24w14a")};
        const QStringList folded = ResourceCatalog::gameVersionChoices(hit.gameVersions, false);
        check(folded == QStringList({QStringLiteral("26.2"), QStringLiteral("1.21.4"),
                                     QStringLiteral("1.20.1")}),
              "★ Z8h 不勾时：rc1 和 rc2 并成一颗 26.2、24w14a 不摆（它折不动）",
              folded.join(QLatin1Char(' ')));
        const QStringList raw = ResourceCatalog::gameVersionChoices(hit.gameVersions, true);
        check(raw.size() == hit.gameVersions.size() &&
                  raw.first() == hit.gameVersions.last() &&
                  raw.last() == hit.gameVersions.first(),
              "Z8h 勾上时：每一条声明过的各摆一颗，一条不多一条不少（新的在前）",
              QStringLiteral("%1/%2").arg(raw.size()).arg(hit.gameVersions.size()));

        // 按 chip 筛。`onlyRc` 只声明了 26.2-rc1 —— 它正是"折"这件事的样本。
        ResourceCatalog::VersionEntry onlyRc;
        onlyRc.id = QStringLiteral("only-rc");
        onlyRc.gameVersions = QStringList{QStringLiteral("26.2-rc1")};
        ResourceCatalog::VersionEntry onlyFinal;
        onlyFinal.id = QStringLiteral("only-final");
        onlyFinal.gameVersions = QStringList{QStringLiteral("26.2")};
        ResourceCatalog::VersionEntry oldStyle;
        oldStyle.id = QStringLiteral("old-style");
        oldStyle.gameVersions = QStringList{QStringLiteral("24w14a")};
        const QList<ResourceCatalog::VersionEntry> pool = {onlyRc, onlyFinal, oldStyle};

        check(ResourceCatalog::versionsForGameVersion(pool, QStringLiteral("26.2"), false).size() == 2,
              "★ Z8h 不勾时点 26.2：只声明了 26.2-rc1 的那一版**也在**（26.2 代表整条线）");
        check(ResourceCatalog::versionsForGameVersion(pool, QStringLiteral("26.2"), true).size() == 1,
              "Z8h 勾上时点 26.2：只剩真声明过 26.2 的那一版（rc 去点它自己那一颗）");
        check(ResourceCatalog::versionsForGameVersion(pool, QStringLiteral("26.2-rc1"), true).size() ==
                  1,
              "Z8h 勾上时 26.2-rc1 自己是摆出来的一颗，点得开");
        check(ResourceCatalog::versionsForGameVersion(pool, QString(), false).size() == pool.size(),
              "Z8h 「全部」那一颗两种模式下都是不筛（折不动的那条也照样在里面）");

        // 组头。分组就是"这个模组落在哪个大版本下"这件事的出处 —— chip 折了而组头不折的话，
        // 用户点 26.2 进去看见的是「Fabric 26.2-rc1」那一组，两处各说各的。
        const QList<ResourceCatalog::VersionGroup> groupsFolded =
            ResourceCatalog::groupVersions({onlyRc}, false);
        check(groupsFolded.size() == 1 &&
                  groupsFolded.first().gameVersion == QStringLiteral("26.2") &&
                  groupsFolded.first().title() == QStringLiteral("26.2"),
              "★ Z8h 不勾时组头也折（只声明到 26.2-rc1 的版本落在 26.2 那一组）",
              groupsFolded.isEmpty() ? QString() : groupsFolded.first().title());
        const QList<ResourceCatalog::VersionGroup> groupsRaw =
            ResourceCatalog::groupVersions({onlyRc}, true);
        check(groupsRaw.size() == 1 &&
                  groupsRaw.first().gameVersion == QStringLiteral("26.2-rc1"),
              "Z8h 勾上时组头原样写 26.2-rc1",
              groupsRaw.isEmpty() ? QString() : groupsRaw.first().title());

        // 拨那颗勾选框之后**该按哪一颗**。这一件事看着小，但它是这个功能里唯一会"把用户
        // 甩下车"的地方：用户在 26.2 上看着若干个版本，一勾/一摘之后那排 chip 是另一份表
        // 了 —— 要是直接把旧 key 塞回去，chip 一颗都不亮（`applyChipChecked` 找不到那一颗），
        // 列表却被新 key 筛过了，界面上就是"整排 chip 都不亮 + 列表少了一半"。
        //
        // 三种情形分开钉（① 还在、② 折一下、③ 挑最新那条快照），外加两种"对不上就回全部"。
        check(ResourceCatalog::gameVersionAfterToggle(hit.gameVersions, true,
                                                      QStringLiteral("26.2")) ==
                  QStringLiteral("26.2"),
              "★ Z8h 勾上前后的 26.2 都还在：这一颗不动（不必挑快照）");
        check(ResourceCatalog::gameVersionAfterToggle(hit.gameVersions, true,
                                                      QStringLiteral("1.20.1")) ==
                  QStringLiteral("1.20.1"),
              "Z8h 正式版的 key 两种模式下都在，原样留着");
        check(ResourceCatalog::gameVersionAfterToggle(hit.gameVersions, false,
                                                      QStringLiteral("26.2-rc1")) ==
                  QStringLiteral("26.2"),
              "★ Z8h 勾→不勾：26.2-rc1 折成 26.2（那条线还在他眼皮底下，不甩回全部）");
        check(ResourceCatalog::gameVersionAfterToggle(hit.gameVersions, false,
                                                      QStringLiteral("24w14a")) == QString(),
              "Z8h 不勾之后 24w14a 那颗根本不摆 ⇒ 回「全部」（不能停在一颗不存在的 chip 上）");
        check(ResourceCatalog::gameVersionAfterToggle(hit.gameVersions, false, QString()) == QString(),
              "Z8h 「全部」拨了还是「全部」");

        // ③ 不勾 → 勾：挑这条线上**最新的那一条快照**（他原来点的那颗 26.2 在不勾时代表
        // 整条线，"翻看快照"最想要的就是这条线里最新的那颗）。
        const QStringList onlyRcDeclared = {QStringLiteral("1.20.1"), QStringLiteral("26.2-rc1")};
        check(ResourceCatalog::gameVersionAfterToggle(onlyRcDeclared, true, QStringLiteral("26.2")) ==
                  QStringLiteral("26.2-rc1"),
              "★ Z8h 不勾→勾：只声明了 26.2-rc1 的那条线，勾上落在 26.2-rc1 这一颗上");
        const QStringList twoRcs = {QStringLiteral("26.2-rc1"), QStringLiteral("26.2-rc2")};
        check(ResourceCatalog::gameVersionAfterToggle(twoRcs, true, QStringLiteral("26.2")) ==
                  QStringLiteral("26.2-rc2"),
              "Z8h 这条线上有两颗快照时挑最新的那一颗（26.2-rc2）");
        // 反过来：这条线上**另有一个真·26.2** 的时候，26.2 这颗在勾上之后照样在 ⇒ 留在它
        // 身上（情形 ① 先于 ③ 判，不然会把用户从正式版拽到它旁边的 rc 上）。
        const QStringList withFinal = {QStringLiteral("26.2"), QStringLiteral("26.2-rc2")};
        check(ResourceCatalog::gameVersionAfterToggle(withFinal, true, QStringLiteral("26.2")) ==
                  QStringLiteral("26.2"),
              "★ Z8h 26.2 自己也声明过时留在 26.2（不许被「挑最新的快照」顶到 rc 上）");

        // 对不上的 key 一律回「全部」。这条路平时走不到（调用方传的是页面当下那一颗），但
        // 传岔了的话症状是"chip 全不亮 + 列表对着一个用户看不见的版本筛"。
        check(ResourceCatalog::gameVersionAfterToggle(hit.gameVersions, true, QStringLiteral("9.9.9"))
                  == QString(),
              "Z8h 对不上的 key 回「全部」");
        check(ResourceCatalog::gameVersionAfterToggle(QStringList(), false, QStringLiteral("26.2")) ==
                  QString(),
              "Z8h 清单是空的（接口没给版本）时也回「全部」，不崩");
    }
}

// =========================================================================
// ZB 节：下载页图标的**盘上那一份缓存**、它的**凭据**、以及那一发请求本身
//（都是 ResourceStore 的静态部分）。
//
// 纯函数 + 文件层，不联网：这一节一次都不构造 ResourceStore（一构造就建
// QNetworkAccessManager），所以图标那条真网络路仍然只有 mw_check 的 resource-live 覆盖。
//
// 为什么这些非得钉住：图标这一路 2026-09-23 实测从国内**根本走不通** ——
// `cdn.modrinth.com` 对每一张图只回一个 307，真正的字节在 `cdn-alt.modrinth.com` 上，
// 而那个域名连不上。于是"盘上那份缓存"就变成用户还能看到图的唯一来源，它拼错路径，
// 症状只是"图标又变慢了"，没有任何东西会报错。
//
// 2026-09-23 用户改的规矩（同一天的第二批）：**缓存不过期** —— 没有"存了多久算旧"这条线
// 了（原来那个七天判据已经删掉），盘上有一份就一直用；换新版靠**每次打开核对一遍**：
// 带上次存下来的凭据去问一句"变了没有"，没变（304）就一个字节都不动。
//
// 所以这一节现在钉的是三件事：那份字节读得回来、那条**凭据**存得住读得回、以及**那一发
// 请求到底带不带条件头**（真值表在 ZB3）。第二、三件是这次改动最要紧的两个地方 ——
// 凭据读没了 = "核对"退化成每次整张重下（用户那句"如果严重占用网络就不做了"正好踩在这）；
// 条件头发错了（比如两个空头也照发）= 主机怎么答都不好说，而这**不会报任何错**。
// =========================================================================

/// 一张现造的、解得出像素的 PNG（这一节要拿它当真图标字节用）。
static QByteArray solidPngBytes(const QColor &color, int side = 32) {
    QImage image(side, side, QImage::Format_ARGB32);
    image.fill(color);
    QByteArray bytes;
    QBuffer buffer(&bytes);
    buffer.open(QIODevice::WriteOnly);
    image.save(&buffer, "PNG");
    buffer.close();
    return bytes;
}

/// 一个只答一种话的假图标服务器（127.0.0.1、随机端口）。
///
/// 记着"来问过几次"和"那一发带了哪些条件头"—— ZB8 要验的东西全在这两件事上。用它的
/// 理由和 V6f 那个假镜像一样：**不碰外网**，在哪台机器上跑都是同一个结果；而"核对那一发"
/// 是这次改动最要紧的那条路，光靠真网络那条探针（mw_check icon-live，只报数不断言）
/// 是钉不住的。
struct FakeIconServer {
    QTcpServer server;
    QByteArray body;      ///< 200 时发回去的正文
    QByteArray headers;   ///< 200 时额外带的头（ETag / Last-Modified 那两条）
    int status = 200;
    int requests = 0;
    QString lastIfNoneMatch;
    QString lastIfModifiedSince;

    bool start() {
        QObject::connect(&server, &QTcpServer::newConnection, &server, [this]() {
            while (QTcpSocket *socket = server.nextPendingConnection()) {
                socket->setParent(&server);
                QObject::connect(socket, &QTcpSocket::readyRead, socket, [this, socket]() {
                    if (socket->property("answered").toBool()) {
                        return; // 一个连接上只答一发（这一发不带正文，读一次就够）
                    }
                    socket->setProperty("answered", true);
                    const QByteArray request = socket->readAll();
                    ++requests;
                    const int headerEnd = request.indexOf("\r\n\r\n");
                    const QByteArray head = headerEnd > 0 ? request.left(headerEnd) : request;
                    for (const QByteArray &line : head.split('\n')) {
                        const QByteArray trimmed = line.trimmed();
                        const int colon = trimmed.indexOf(':');
                        if (colon <= 0) {
                            continue;
                        }
                        const QByteArray name = trimmed.left(colon).trimmed().toLower();
                        const QString value =
                            QString::fromUtf8(trimmed.mid(colon + 1)).trimmed();
                        if (name == "if-none-match") {
                            lastIfNoneMatch = value;
                        } else if (name == "if-modified-since") {
                            lastIfModifiedSince = value;
                        }
                    }
                    QByteArray response = QByteArrayLiteral("HTTP/1.1 ") +
                                          QByteArray::number(status) +
                                          (status == 304 ? QByteArrayLiteral(" Not Modified\r\n")
                                                         : QByteArrayLiteral(" OK\r\n"));
                    if (status == 304) {
                        // 没变：一个字节的正文都没有。**这一条正是"不严重占网络"的全部根据。**
                        response += QByteArrayLiteral("Content-Length: 0\r\n\r\n");
                    } else {
                        response += headers;
                        response += QByteArrayLiteral("Content-Length: ") +
                                    QByteArray::number(body.size()) + QByteArrayLiteral("\r\n\r\n");
                        response += body;
                    }
                    socket->write(response);
                    socket->flush();
                });
            }
        });
        return server.listen(QHostAddress::LocalHost, 0);
    }
};

static void runIconCacheTests() {
    const QString originalDir = AppPaths::minecraftDir();
    QTemporaryDir rootA;
    QTemporaryDir rootB;
    check(rootA.isValid() && rootB.isValid(), "ZB0 两个临时数据根目录建出来了");

    // ---------------------------------------------------------------------
    section("ZB1. 缓存路径怎么拼（以及哪些 id 宁可不缓存）");
    // ---------------------------------------------------------------------

    AppPaths::setMinecraftDir(rootA.path());
    const QString path = ResourceStore::iconCachePath(QStringLiteral("AANobbMI"));
    check(QFileInfo(path).absolutePath() ==
              QDir::cleanPath(rootA.path() + QStringLiteral("/cache/icons")),
          "ZB1 图标缓存落在 <数据目录>/cache/icons 下",
          QFileInfo(path).absolutePath());
    // 后缀是 `.icon` 不是 `.png`：这一格里两种字节都会落进来（能解 webp 的机器走那条小的，
    // 存的就是 webp）。叫 .png 是句假话，而这个假话会害到下一个按后缀认格式的人。
    check(QFileInfo(path).fileName() == QStringLiteral("AANobbMI.icon"),
          "ZB1 文件名就是 project_id + .icon（里面可能是 png 也可能是 webp）");

    // 这个 id 是从**接口正文**里来的，按外部输入对待：能拼出路径的那些一律不接受。
    // `..` 最要命 —— 它每一个字符都在放行集里，却指向上一层目录。
    const QStringList badIds = {QStringLiteral(".."),  QStringLiteral("."),
                                QStringLiteral("../evil"), QStringLiteral("a/b"),
                                QStringLiteral("a\\b"), QStringLiteral("a:b"),
                                QStringLiteral("a b"),  QStringLiteral("模组"),
                                QString()};
    int rejected = 0;
    for (const QString &id : badIds) {
        if (ResourceStore::iconCachePath(id).isEmpty()) {
            ++rejected;
        }
    }
    check(rejected == badIds.size(), "ZB1 不安全/空的 project_id 一律不拼路径",
          QStringLiteral("%1/%2 被挡下").arg(rejected).arg(badIds.size()));

    // ---------------------------------------------------------------------
    section("ZB2. 凭据（ETag / Last-Modified）：存得住、读得回、空的不留文件");
    // ---------------------------------------------------------------------

    // 凭据是**跟着一条地址**的（2026-09-25 补的第三行）。同一个 project 有两条地址
    //（接口那条 96px webp / 自己拼的 icon.png），这条测试全程用同一条，另有一段专门
    // 验"地址对不上 = 当没有凭据"。
    const QString kMetaId = QStringLiteral("EEEfff");
    const QString kMetaUrl = QStringLiteral("https://cdn.modrinth.com/data/EEEfff/icon-96.webp");
    const QString kMetaOtherUrl = QStringLiteral("https://cdn.modrinth.com/data/EEEfff/icon.png");
    check(ResourceStore::iconMetaPath(kMetaId) ==
              ResourceStore::iconCachePath(kMetaId) + QStringLiteral(".meta"),
          "ZB2 凭据就躺在图标那份旁边（同名 + .meta）");
    // 没存过 = 没有凭据。这不是错误，是"下一发老老实实要整张"。
    check(ResourceStore::loadIconValidators(kMetaId, kMetaUrl).isEmpty() &&
              ResourceStore::iconMetaPath(QStringLiteral("../evil")).isEmpty(),
          "ZB2 没存过时读回空的；不安全的 id 连路径都不拼");

    ResourceStore::IconValidators both;
    both.etag = QStringLiteral("\"5f3c1a2b-9\"");
    both.lastModified = QStringLiteral("Tue, 23 Sep 2026 04:11:07 GMT");
    check(ResourceStore::saveIconValidators(kMetaId, both, kMetaUrl), "ZB2 两条凭据都写下去了");
    const ResourceStore::IconValidators back =
        ResourceStore::loadIconValidators(kMetaId, kMetaUrl);
    // **逐字**比对：这两条是要原样塞回请求头里的，少一个引号、多一个空格，主机那边就是
    // 另一句话（ETag 是强比对，差一个字节就等于"变了"）。
    check(back.etag == both.etag && back.lastModified == both.lastModified,
          "ZB2 读回来一模一样（引号和逗号原样在）",
          back.etag + QStringLiteral(" / ") + back.lastModified);

    // 只有一条凭据也是常态（有些主机只给 ETag）—— 存下去、读回来也得对得上：
    // 少写的另一条读出来是空的，不能让上一条的残值串到这一条上。
    ResourceStore::IconValidators onlyEtag;
    onlyEtag.etag = QStringLiteral("\"only\"");
    check(ResourceStore::saveIconValidators(kMetaId, onlyEtag, kMetaUrl) &&
              ResourceStore::loadIconValidators(kMetaId, kMetaUrl).etag == onlyEtag.etag &&
              ResourceStore::loadIconValidators(kMetaId, kMetaUrl).lastModified.isEmpty(),
          "ZB2 只存 ETag 时另一条读回来是空的");

    // 两条都空：**从前是"把文件删掉"，2026-10-10 起改成照样写**
    //（用户那句「模组图标做本地缓存功能，不要每次都拉取」⇒ 那份 meta 现在多装着
    // "上一次核对是什么时候"，见 IconValidators::checkedAtMs —— 主机不给凭据的那些源
    // 照样该被那道时间闸管着，删了文件这一位就没了）。
    //
    // 判据因此收成两条：① 保存成功；② **读回来还是"没有凭据"**（这一点一个字都不能变 ——
    // 空的 ETag 发出去就是一个空条件头）。
    check(ResourceStore::saveIconValidators(kMetaId, ResourceStore::IconValidators(), kMetaUrl),
          "ZB2 两条都空时保存 = 成功");
    {
        const ResourceStore::IconValidators empty =
            ResourceStore::loadIconValidators(kMetaId, kMetaUrl);
        check(empty.etag.isEmpty() && empty.lastModified.isEmpty(),
              "ZB2 ……而且读回来还是「没有凭据」（一个空条件头都不许发出去）");
        // ★ 第四行那一位得**真的写下去了**（它是那道「攒够 7 天才核一次」的闸的判据）——
        //   不写的话，主机不给凭据的那些图标每次启动都要白敲一遍门。
        check(empty.checkedAtMs > 0, "ZB2 ……并且盖上了「刚核过」那个时间戳（第四行）",
              QStringLiteral("%1").arg(empty.checkedAtMs));
    }

    // 一份**空**的 meta（0 字节）= 没有凭据、一个条件头都不发。这是"两条都空不留文件"
    // 那条规矩的另一半 —— 盘上真躺着一个空文件时（旧版本留的、或者被别的东西写坏了），
    // 读出来必须是"没有"，不能变成"凭据是一条空串"（空串会变成一个语法不成形的条件头）。
    writeFileAt(ResourceStore::iconMetaPath(kMetaId), QByteArray());
    const ResourceStore::IconValidators emptyFile =
        ResourceStore::loadIconValidators(kMetaId, kMetaUrl);
    check(emptyFile.isEmpty() &&
              QString::fromUtf8(ResourceStore::iconRequest(kMetaId, emptyFile)
                                    .rawHeader("If-None-Match"))
                  .isEmpty(),
          "ZB2 空文件 = 没有凭据（不会发出一个空的条件头）");

    // 正文读不懂（被别的东西写过、写了一半）也**不崩**：这个格式就是两行纯文本，
    // 第一行是什么就当 ETag 是什么。一条对不上的凭据是无害的 —— 主机不认它，照旧把整张
    // 发回来，下面那条"字节一样 = 没变"照样接得住。真正危险的是**拿别人的凭据去问**
    //（那一份字节已经不在了、凭据还在），那条由 dropIconFromCache 一起删来保证，
    // 断言在 ZB4 里。
    writeFileAt(ResourceStore::iconMetaPath(kMetaId), QByteArray("这不是凭据\n"));
    const ResourceStore::IconValidators garbage =
        ResourceStore::loadIconValidators(kMetaId, kMetaUrl);
    check(garbage.etag == QStringLiteral("这不是凭据") && garbage.lastModified.isEmpty(),
          "ZB2 读不懂的正文：第一行当 ETag、其余当没有（不崩、不凭空多一条）", garbage.etag);

    // ---------------------------------------------------------------------
    section("ZB2b. 凭据跟的是**哪条地址**（2026-09-25 补的第三行）");
    // ---------------------------------------------------------------------

    // 缓存和凭据都只按 project_id 存，而同一个 project 有**两条**图标地址（接口那条 96px
    // 的 webp、自己拼的 icon.png，见 requestIcon）。不记"这条凭据是哪条地址给的"，换一条
    // 地址时就会**拿着 A 的 ETag 去问 B**：主机不认时白带一个条件头（还得整张重下），
    // 万一两条地址的 ETag 撞上就是一条 304 —— 这一格从此画着"另一条地址的那张图"，
    // 而且看起来一个错都没有。
    check(ResourceStore::saveIconValidators(kMetaId, both, kMetaUrl),
          "ZB2b 凭据跟着地址一起存下去");
    check(ResourceStore::loadIconValidators(kMetaId, kMetaUrl).etag == both.etag,
          "ZB2b 同一条地址读得回来");
    check(ResourceStore::loadIconValidators(kMetaId, kMetaOtherUrl).isEmpty(),
          "ZB2b 换了一条地址 = 当没有凭据（不拿 A 的 ETag 去问 B）");
    // 存下去那两行本身的形状也得看一眼：**必须**有地址那一条 —— 少了它上面那条断言
    // 之所以过只是因为"没记地址"，而不是因为"记下了 B"。这两件事差着一个 304。
    {
        QFile metaFile(ResourceStore::iconMetaPath(kMetaId));
        const bool opened = metaFile.open(QIODevice::ReadOnly);
        const QList<QByteArray> metaLines =
            opened ? metaFile.readAll().split('\n') : QList<QByteArray>();
        if (opened) {
            metaFile.close();
        }
        check(metaLines.size() > 2 &&
                  QString::fromUtf8(metaLines.at(2)).trimmed() == kMetaUrl,
              "ZB2b 第三行真的写着这条地址（不是「没记」，是「记的是它」）");
    }

    // 老版本（2026-09-25 之前）写的那些 meta 只有两行 —— 第三行读出来是空的。那种是
    // **"没记地址"**，不是"记的是别的地址"：照样得能用。少写一行就把用户的凭据整份作废，
    // 是这次改动最容易顺手犯的错（代价是所有人下次启动都把整本图标重下一遍）。
    writeFileAt(ResourceStore::iconMetaPath(kMetaId),
                QByteArray("\"old-etag\"\nTue, 23 Sep 2026 04:11:07 GMT\n"));
    const ResourceStore::IconValidators legacy = ResourceStore::loadIconValidators(kMetaId, kMetaUrl);
    check(legacy.etag == QStringLiteral("\"old-etag\"") &&
              legacy.lastModified == QStringLiteral("Tue, 23 Sep 2026 04:11:07 GMT"),
          "ZB2b 两行的老 meta（没记地址）照样用，不因为缺第三行就作废", legacy.etag);

    // ---------------------------------------------------------------------
    section("ZB3. 那一发请求到底带什么头（哪条凭据发哪个头）");
    // ---------------------------------------------------------------------

    // 这个函数是纯的（造一个 QNetworkRequest 再把头发读回来），所以"哪条凭据发哪个头"
    // 这张真值表可以在这儿逐条钉住 —— 而它是这次改动里最容易写错、错了又不报错的地方。
    const QString kUrl = QStringLiteral("https://cdn.modrinth.com/data/AANobbMI/icon.png");
    const auto headerOf = [](const QNetworkRequest &request, const char *name) {
        return QString::fromUtf8(request.rawHeader(name));
    };

    const QNetworkRequest plainRequest = ResourceStore::iconRequest(kUrl, ResourceStore::IconValidators());
    check(headerOf(plainRequest, "If-None-Match").isEmpty() &&
              headerOf(plainRequest, "If-Modified-Since").isEmpty(),
          "ZB3 没有凭据 = 一个条件头都不发（空头不是\"没有凭据\"那句话）");
    // 地址和身份这两条跟凭据无关，任何时候都得在。
    check(plainRequest.url().toString() == kUrl && !headerOf(plainRequest, "User-Agent").isEmpty(),
          "ZB3 地址原样没动、身份头照发");
    // 图标那一发**比别处短**（它是装饰，"半小时不出来"和"这一页被拖住"是两回事）——
    // 不写死 8000，钉的是那条**关系**：比默认那个短、而且是个真的数。
    check(plainRequest.transferTimeout() > 0 &&
              plainRequest.transferTimeout() < HttpClient::kDefaultTimeoutMs,
          "ZB3 图标那一发的超时比默认那个短",
          QStringLiteral("%1 ms").arg(plainRequest.transferTimeout()));

    ResourceStore::IconValidators etagOnly;
    etagOnly.etag = QStringLiteral("\"abc123\"");
    const QNetworkRequest etagRequest = ResourceStore::iconRequest(kUrl, etagOnly);
    check(headerOf(etagRequest, "If-None-Match") == etagOnly.etag &&
              headerOf(etagRequest, "If-Modified-Since").isEmpty(),
          "ZB3 只有 ETag 时只发 If-None-Match", headerOf(etagRequest, "If-None-Match"));

    ResourceStore::IconValidators timeOnly;
    timeOnly.lastModified = QStringLiteral("Tue, 23 Sep 2026 04:11:07 GMT");
    const QNetworkRequest timeRequest = ResourceStore::iconRequest(kUrl, timeOnly);
    check(headerOf(timeRequest, "If-Modified-Since") == timeOnly.lastModified &&
              headerOf(timeRequest, "If-None-Match").isEmpty(),
          "ZB3 只有 Last-Modified 时只发 If-Modified-Since");

    const QNetworkRequest bothRequest = ResourceStore::iconRequest(kUrl, both);
    check(headerOf(bothRequest, "If-None-Match") == both.etag &&
              headerOf(bothRequest, "If-Modified-Since") == both.lastModified,
          "ZB3 两条都有 = 两条都发，值一字不改");

    // ---------------------------------------------------------------------
    section("ZB3b. 问项目名字那一发的头（CurseForge 那条 400 的真因）");
    // ---------------------------------------------------------------------
    //
    // 2026-09-28 用户报的 bug：「这个前置模组缺失的提示为数字而非模组名称」。查下来根子
    // 在这里：CurseForge 那条"按 id 问项目"是 `POST /mods`，而**漏了 `Content-Type` 时
    // 那台社区镜像回 400**（实测矩阵：`application/json` → 200、不带 → 400、`text/plain`
    // → 400）。400 在界面上长得和"这个项目没了"一模一样 —— 于是名字一条都没到，前置那
    // 个框里只剩下一串项目号。
    //
    // 所以这一节钉两件事：**那一发的头表**（纯函数，一毫秒）+ **端到端跑一遍**（本地假
    // 服务器：不带那个头就回 400，带了才回 200 和一份真形状的 json —— 这一条才是"下次谁
    // 再把那个参数删了"能当场变红的那条）。
    {
        // 这一节自己带一份（`kUrl` / `headerOf` 是 ZB3 那个块里的局部量，出了那个花括号
        // 就不在了；两处同名不同块，不冲突）。
        const QString kUrl = QStringLiteral("https://api.curseforge.com/v1/mods");
        const auto headerOf = [](const QNetworkRequest &request, const char *name) {
            return QString::fromUtf8(request.rawHeader(name));
        };

        const QNetworkRequest withType = ResourceStore::resourceRequest(
            kUrl, {}, QByteArrayLiteral("application/json"));
        check(headerOf(withType, "Content-Type") == QStringLiteral("application/json"),
              "ZB3b 给了类型就一字不差地发出去", headerOf(withType, "Content-Type"));
        check(headerOf(withType, "User-Agent") == QStringLiteral("WTFML"),
              "ZB3b User-Agent 还是那一份");

        // 空 = "这一发没有正文"，于是**一个 Content-Type 都不加**。那个空头不是"没有类型"，
        // 它是一句不成形的话（有些网关会照着它回 400）——所以这里两种写法都不许有。
        const QNetworkRequest withoutType = ResourceStore::resourceRequest(kUrl);
        check(!withoutType.hasRawHeader("Content-Type") &&
                  headerOf(withoutType, "Content-Type").isEmpty(),
              "ZB3b 没给类型时一个 Content-Type 都不发（空的那个也不行）");

        // 自定义头（CurseForge 的 `x-api-key` 就走这一路）原样落上去。
        const QList<QPair<QByteArray, QByteArray>> extraHeaders = {
            {QByteArrayLiteral("x-api-key"), QByteArrayLiteral("$2a$10$pretend")}};
        const QNetworkRequest withExtra =
            ResourceStore::resourceRequest(kUrl, extraHeaders, QByteArrayLiteral("application/json"));
        check(headerOf(withExtra, "x-api-key") == QStringLiteral("$2a$10$pretend"),
              "ZB3b 自定义头原样带上");

        // 超时走 Qt 自己那条（不再另搭 QTimer），值是 HttpClient 那一份 —— 两处必须一样，
        // 不然"这一发到底几秒算超时"就有两个答案。
        check(withType.transferTimeout() == HttpClient::kDefaultTimeoutMs,
              "ZB3b transferTimeout 就是 HttpClient 那一份",
              QString::number(withType.transferTimeout()));
    }
    {
        // --- 端到端：**不带 `Content-Type` 就回 400** 的假 CurseForge ---
        //
        // 判据刻意做成"服务端真的照那条规矩判"：假服务器把收到的头原样记下来，缺那个头就
        // 答 400（真镜像就是这么干的，实测过）。于是这一条用例红了只有两个可能：要么产品
        // 那一发没带头、要么那台接口的规矩变了 —— 两种都该有人看一眼。
        struct FakeCurseForge {
            QTcpServer server;
            int requests = 0;
            QString lastContentType;
            bool sawContentType = false;
            QString lastPath;

            bool start() {
                QObject::connect(&server, &QTcpServer::newConnection, &server, [this]() {
                    while (QTcpSocket *socket = server.nextPendingConnection()) {
                        socket->setParent(&server);
                        QObject::connect(socket, &QTcpSocket::readyRead, socket, [this, socket]() {
                            if (socket->property("answered").toBool()) {
                                return;
                            }
                            socket->setProperty("answered", true);
                            // 正文一起读掉再答（不读的话那条连接上还挂着未读数据，
                            // 有些平台上写完就断了）。
                            const QByteArray request = socket->readAll();
                            ++requests;
                            const int headerEnd = request.indexOf("\r\n\r\n");
                            const QByteArray head = headerEnd > 0 ? request.left(headerEnd) : request;
                            lastContentType.clear();
                            sawContentType = false;
                            const QList<QByteArray> lines = head.split('\n');
                            for (const QByteArray &line : lines) {
                                const QByteArray trimmed = line.trimmed();
                                const int colon = trimmed.indexOf(':');
                                if (colon <= 0) {
                                    continue;
                                }
                                const QByteArray name = trimmed.left(colon).trimmed().toLower();
                                if (name == "content-type") {
                                    sawContentType = true;
                                    lastContentType =
                                        QString::fromUtf8(trimmed.mid(colon + 1)).trimmed();
                                }
                            }
                            if (!lines.isEmpty()) {
                                lastPath = QString::fromUtf8(lines.first().trimmed());
                            }
                            // 实测那条规矩：没有 `application/json` 就 400。
                            const bool accepted =
                                lastContentType.compare(QStringLiteral("application/json"),
                                                        Qt::CaseInsensitive) == 0;
                            const QByteArray body =
                                accepted
                                    ? QByteArrayLiteral(
                                          "{\"data\":[{\"id\":238222,\"slug\":\"jei\","
                                          "\"name\":\"Just Enough Items\","
                                          "\"summary\":\"看配方的\",\"downloadCount\":1,"
                                          "\"authors\":[{\"name\":\"mezz\"}],"
                                          "\"categories\":[],\"latestFilesIndexes\":[]}]}")
                                    : QByteArrayLiteral("{\"error\":\"Content-Type 不对\"}");
                            QByteArray response =
                                QByteArrayLiteral("HTTP/1.1 ") +
                                (accepted ? QByteArrayLiteral("200 OK\r\n")
                                          : QByteArrayLiteral("400 Bad Request\r\n"));
                            response += QByteArrayLiteral(
                                "Content-Type: application/json\r\nContent-Length: ");
                            response += QByteArray::number(body.size());
                            response += QByteArrayLiteral("\r\n\r\n");
                            response += body;
                            socket->write(response);
                            socket->flush();
                        });
                    }
                });
                return server.listen(QHostAddress::LocalHost, 0);
            }
        };

        FakeCurseForge fake;
        const bool listening = fake.start();
        check(listening, "ZB3b 本地假 CurseForge 起来了（起不来这条用例就没意义）");
        if (listening) {
            ResourceStore store;
            store.setCurseForgeApiBaseOverride(
                QStringLiteral("http://127.0.0.1:%1/v1").arg(fake.server.serverPort()));

            QEventLoop loop;
            QList<ResourceCatalog::Hit> hits;
            QString problem;
            bool answered = false;
            QObject::connect(&store, &ResourceStore::projectsFinished, &loop,
                             [&](const QString &, const QList<ResourceCatalog::Hit> &result,
                                 const QString &resultProblem) {
                                 hits = result;
                                 problem = resultProblem;
                                 answered = true;
                                 loop.quit();
                             });
            store.fetchProjects(ResourceCatalog::projectsRequestKey(QStringList{QStringLiteral("238222")},
                                                                   ResourceCatalog::Source::CurseForge),
                                QStringList{QStringLiteral("238222")},
                                ResourceCatalog::Source::CurseForge);
            QTimer::singleShot(10000, &loop, &QEventLoop::quit);  // 卡住时别把整套挂在这儿
            loop.exec();

            check(fake.requests == 1, "ZB3b 那一发真的发出去了",
                  QString::number(fake.requests));
            check(fake.sawContentType &&
                      fake.lastContentType.compare(QStringLiteral("application/json"),
                                                   Qt::CaseInsensitive) == 0,
                  "ZB3b 那一发带着 application/json（缺了它假服务器回 400）",
                  fake.lastContentType);
            check(problem.isEmpty(),
                  "ZB3b 那一发没被拒（problem 空 = 没走到「没取到」那一路）", problem);
            check(answered && hits.size() == 1 && hits.first().title == QStringLiteral("Just Enough Items"),
                  "ZB3b 名字真的读回来了（**不是**退成项目号）",
                  hits.isEmpty() ? QStringLiteral("(一条都没有)") : hits.first().title);
            check(hits.size() == 1 &&
                      hits.first().projectId == QStringLiteral("238222"),
                  "ZB3b 回来的那条挂着的还是那个项目号",
                  hits.isEmpty() ? QStringLiteral("(一条都没有)") : hits.first().projectId);
        }
    }

    // ---------------------------------------------------------------------
    section("ZB4. 存了能不能读回来（含读到坏字节那种）");
    // ---------------------------------------------------------------------

    const QByteArray bytes = QByteArrayLiteral("\x89PNG\r\n\x1a\n-not-really-a-png");
    check(ResourceStore::saveIconToCache(QStringLiteral("AAAbbb"), bytes),
          "ZB4 写进盘上去了");
    check(QFile::exists(ResourceStore::iconCachePath(QStringLiteral("AAAbbb"))),
          "ZB4 文件真的在");

    QByteArray readBack;
    check(ResourceStore::loadIconFromCache(QStringLiteral("AAAbbb"), &readBack),
          "ZB4 读得回来");
    check(readBack == bytes, "ZB4 字节一模一样");

    // 没缓存过的那条：回 false，而且**不许动**调用方手上那个值（它可能就是靠"没动"
    // 来判断"这次没有"的）。
    readBack = QByteArrayLiteral("别动我");
    check(!ResourceStore::loadIconFromCache(QStringLiteral("没缓存过"), &readBack) &&
              readBack == QByteArrayLiteral("别动我"),
          "ZB4 没缓存过时回 false，且没动传进去的值");

    // 坏字节：缓存层**不看内容**（那是 ImageDecode / 界面那一侧的事），所以它照样回 true……
    check(ResourceStore::loadIconFromCache(QStringLiteral("AAAbbb"), &readBack),
          "ZB4 坏字节也照读（缓存层不看内容）");
    // ……而"读出来发现不是图"之后走的是删掉重来那条路。
    //
    // 这里顺手放上一条**凭据**：drop 必须把那份 meta 一起删掉。光删图不删凭据的话，
    // 下一次会拿着一条"对应着另一份字节"的 ETag 去问，主机答 304，于是这一格永远画不出
    // 东西来 —— 而且**看起来一个错都没有**（那是这次改动里最像样的一个坑）。
    check(ResourceStore::saveIconValidators(QStringLiteral("AAAbbb"), both, kUrl),
          "ZB4 给这份图标配一条凭据");
    ResourceStore::dropIconFromCache(QStringLiteral("AAAbbb"));
    check(!ResourceStore::loadIconFromCache(QStringLiteral("AAAbbb"), &readBack) &&
              !QFile::exists(ResourceStore::iconCachePath(QStringLiteral("AAAbbb"))),
          "ZB4 删掉之后读不到了、盘上也没了");
    check(!QFile::exists(ResourceStore::iconMetaPath(QStringLiteral("AAAbbb"))) &&
              ResourceStore::loadIconValidators(QStringLiteral("AAAbbb"), kUrl).isEmpty(),
          "ZB4 ……凭据跟着一起删（不删的话下次会问出一条 304 把这一格焊死）");

    // 盘上那份**存了多久都不算过期** —— 这正是用户 2026-09-23 那条规矩。没有配套的断言
    // 的话，"哪天有人又加回一条时间线"是查不出来的（界面上只是"图标忽然又下了一遍"）。
    // 判据只能这么写：把文件的修改时间往前拨一大截，读回来照样是它、照样能画。
    check(ResourceStore::saveIconToCache(QStringLiteral("CCCDdd"), bytes), "ZB4 再存一份");
    const QString oldPath = ResourceStore::iconCachePath(QStringLiteral("CCCDdd"));
    {
        QFile backdated(oldPath);
        const bool opened = backdated.open(QIODevice::ReadOnly | QIODevice::WriteOnly);
        check(opened && backdated.setFileTime(QDateTime::currentDateTime().addYears(-5),
                                              QFileDevice::FileModificationTime),
              "ZB4 把那份的修改时间拨到五年前");
        if (opened) {
            backdated.close();
        }
    }
    readBack.clear();
    check(ResourceStore::loadIconFromCache(QStringLiteral("CCCDdd"), &readBack) &&
              readBack == bytes,
          "ZB4 五年前存的那份照样读得出来（缓存不过期）");

    // ---------------------------------------------------------------------
    section("ZB5. 缓存跟着「当前游戏文件夹」走");
    // ---------------------------------------------------------------------

    check(ResourceStore::saveIconToCache(QStringLiteral("DDDeee"), bytes), "ZB5 在 A 里存一份");
    check(ResourceStore::saveIconValidators(QStringLiteral("DDDeee"), both, kUrl),
          "ZB5 凭据也在 A 里存一份");
    AppPaths::setMinecraftDir(rootB.path());
    check(!ResourceStore::loadIconFromCache(QStringLiteral("DDDeee"), &readBack),
          "ZB5 换到 B 这份数据目录就读不到了（各存一份，不是全局共用）");
    check(ResourceStore::loadIconValidators(QStringLiteral("DDDeee"), kUrl).isEmpty(),
          "ZB5 凭据也跟着走：B 里没有 A 存的那条");
    check(ResourceStore::saveIconToCache(QStringLiteral("DDDeee"), bytes), "ZB5 在 B 里也存一份");
    AppPaths::setMinecraftDir(rootA.path());
    check(ResourceStore::loadIconFromCache(QStringLiteral("DDDeee"), &readBack) &&
              readBack == bytes,
          "ZB5 换回 A 那份还是原来那张");

    // ---------------------------------------------------------------------
    section("ZB6. 哪几种失败算「这一路整条不通」");
    // ---------------------------------------------------------------------

    // 0 = 压根没连上（断网 / DNS / 超时）—— 这才是那道闸要挡的。
    check(ResourceStore::isHostLevelIconFailure(0), "ZB6 没连上（0）= 主机级");
    check(ResourceStore::isHostLevelIconFailure(500), "ZB6 5xx = 主机级");
    check(ResourceStore::isHostLevelIconFailure(503), "ZB6 503 = 主机级");
    // 404 = 这个资源没有图标；429 = 你问得太勤了 —— 两条都说明**主机是活的**。
    check(!ResourceStore::isHostLevelIconFailure(404),
          "ZB6 404（作者没传图标）不算主机级");
    check(!ResourceStore::isHostLevelIconFailure(HttpClient::kStatusTooManyRequests),
          "ZB6 429（限流）不算主机级");
    check(!ResourceStore::isHostLevelIconFailure(200) &&
              !ResourceStore::isHostLevelIconFailure(302),
          "ZB6 成功/跳转更不算");
    // 304：**"没变"，而且主机明明答话了**。判成主机级失败的后果是它去推那道"放弃"的闸
    // （三次 304 就整页不再问）；而 304 恰恰是"一切正常、就是不用动"那个答案。
    check(!ResourceStore::isHostLevelIconFailure(HttpClient::kStatusNotModified),
          "ZB6 304（没变）不算主机级失败：它说的是一切正常");
    // 那道闸必须"连着"够数才放下来：一两张失败就放弃的话，偶尔丢一张图也会把整页的
    // 图标全掐掉。
    check(ResourceStore::kIconGiveUpAfter >= 2, "ZB6 那道闸要连着失败好几张才放下来",
          QStringLiteral("kIconGiveUpAfter = %1").arg(ResourceStore::kIconGiveUpAfter));

    AppPaths::setMinecraftDir(originalDir); // 收摊：后面那些节读的还是原来那份沙盒
    check(AppPaths::minecraftDir() == originalDir, "ZB7 数据根目录换回来了");
}

// =========================================================================
// ZC. 一串字节 → 一张图（src/util/ImageDecode）
//
// 这一节验的是"图标怎么解"这件事的**两半**：Qt 自己认得的那一半（png / jpg / gif…）和
// Qt 不认得的 webp（走系统 WIC）。第二半有个特殊之处：**它在这台机器上有没有，是个运行时
// 事实**（那个编解码器是微软单独发的扩展包，Win11 默认带着、Win10 上要装商店那个
// 「WebP 图像扩展」），所以断言必须按 webpAvailable() 分两支 —— 只写一支的话，换一台机器
// 跑出来就是红的，而那不是回归。
// =========================================================================

static void runImageDecodeTests() {
    const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";

    // ---------------------------------------------------------------------
    section("ZC1. Qt 自己认得的那一半：按内容判，不按后缀判");
    // ---------------------------------------------------------------------

    // 自己现搭一张 PNG（不落盘，走 QBuffer）当夹具 —— 这一条要证的只是"这条路通"，
    // 造一张比去 meta/ 里挂一份更干净。
    QImage source(96, 96, QImage::Format_ARGB32);
    source.fill(QColor(0x11, 0x22, 0x33));
    QByteArray pngBytes;
    {
        QBuffer buffer(&pngBytes);
        buffer.open(QIODevice::WriteOnly);
        check(source.save(&buffer, "PNG"), "ZC1 现造一张 96x96 的 PNG 成功了");
    }
    check(pngBytes.startsWith(QByteArrayLiteral("\x89PNG")), "ZC1 造出来的确实是 PNG 字节");

    const QImage decodedPng = ImageDecode::decode(pngBytes);
    check(decodedPng.size() == QSize(96, 96), "ZC1 PNG 解得回来，尺寸对",
          QStringLiteral("%1x%2").arg(decodedPng.width()).arg(decodedPng.height()));
    // 像素值也要对：尺寸对而内容错（比如换成全黑）是最查不出来的那种错。
    check(decodedPng.pixel(48, 48) == quint32(0xFF112233),
          "ZC1 像素也没错位（0xFF112233）",
          QStringLiteral("0x%1").arg(decodedPng.pixel(48, 48), 8, 16, QLatin1Char('0')));

    // 解不出来的那些一律回 **null**（不是抛异常，也不是 1x1 的空图）—— 调用方（
    // ResourceStore）正是靠 isNull() 判"这一发没拿到图"，回一张 1x1 的空图会被当成成功。
    check(ImageDecode::decode(QByteArray()).isNull(),
          "ZC1 空的一串 = 没有图（不是一张空图）");
    check(ImageDecode::decode(QByteArrayLiteral("这不是任何一张图的字节")).isNull(),
          "ZC1 一段解不出图的字节 = null");
    check(ImageDecode::decode(QByteArrayLiteral("<html>502 Bad Gateway</html>")).isNull(),
          "ZC1 网关挡回来的那段 HTML = null（界面上就是画占位方块）");

    // ---------------------------------------------------------------------
    section("ZC2. webp：这台机器解不解得动，解出来的对不对");
    // ---------------------------------------------------------------------

    const bool webp = ImageDecode::webpAvailable();
    out() << "     （这台机器 webpAvailable() = " << (webp ? "true" : "false") << "）\n";

    QByteArray webpBytes;
    {
        QFile fixture(metaDir + "/icon-sample.webp");
        const bool haveFixture = fixture.open(QIODevice::ReadOnly);
        check(haveFixture, "ZC2 读到了真 webp 夹具（meta/icon-sample.webp）");
        if (haveFixture) {
            webpBytes = fixture.readAll();
            fixture.close();
        }
    }
    // 4800 字节 —— 那份夹具是从 Modrinth CDN 上真取下来的 96px 缩略图（同一张图的
    // icon.png 是 35218 字节，差 7 倍）。字节数也钉一下：换了夹具的话这里会先红。
    check(webpBytes.size() == 4800 && webpBytes.startsWith(QByteArrayLiteral("RIFF")) &&
              webpBytes.mid(8, 4) == QByteArrayLiteral("WEBP"),
          "ZC2 夹具就是那份 4800 字节的 webp",
          QStringLiteral("%1 字节").arg(webpBytes.size()));

    // 这一条是"这份 Qt 自己解不了它"的**活证据**（不是从别处抄来的结论）：要是哪天 Qt
    // 装上了 webp 插件，这里会先红 —— 那时 ImageDecode 里那条 WIC 分支就成了多余的东西。
    check(QImage().loadFromData(webpBytes) == false,
          "ZC2 这份 Qt 自己解不了 webp（所以才有 ImageDecode 这一层）");

    const QImage webpImage = ImageDecode::decode(webpBytes);
    if (webp) {
        check(webpImage.size() == QSize(96, 96), "ZC2 解得动：96x96",
              QStringLiteral("%1x%2").arg(webpImage.width()).arg(webpImage.height()));
        // 中心像素：WIC 交给我们的那块内存是 **BGRA**（探针打出来是 `66 C8 7A FF`），
        // 而 QImage::Format_ARGB32 的 0xAARRGGBB 里 R 在高位 —— 也就是 0xFF7AC866。
        // 这一条同时钉住三件事：真的解出了像素、**通道没交换**（交换了会是 0xFF66C87A）、
        // alpha 没被乘进颜色里（Premultiplied 的话这个像素是纯色，看不出来，但换一张
        // 半透明的图就会差 —— 见 ImageDecode.cpp 里那条注）。
        check(webpImage.pixel(48, 48) == quint32(0xFF7AC866),
              "ZC2 中心像素对（BGRA → ARGB32 通道没交换）",
              QStringLiteral("0x%1").arg(webpImage.pixel(48, 48), 8, 16, QLatin1Char('0')));
    } else {
        // 没有那个编解码器时**如实回 null**：ResourceStore 拿到 null 就走"退回 PNG 那条
        // 地址"（见 startIconRequest）。这里要是硬解出点什么来才糟糕。
        check(webpImage.isNull(),
              "ZC2 这台机器没有 webp 编解码器：如实回 null（界面会退回 PNG，不是报错）");
    }
}

// =========================================================================
// ZD. 设置页「启动选项」那三项（设置 → 命令行这一条链）
//
// 2026-09-24 加的这一组设置，三件事各验各的那一半：
//   * 「显示游戏日志」：这里只验**它存得下来、读得回来**（默认关）。"开了之后真会弹窗"
//     那半边在 mw_check 里 —— 那条路要真的把 MainWindow 立起来、还得有会话输出。
//   * 「进程优先级」：存的是**字符串**，所以"五个值怎么写进去、怎么读回来"是这里的事。
//   * 「游戏窗口大小」：上下限钳位，外加它真的变成命令行上的 --width/--height。
//
// NOTE: 有一件事这一节**证不到**，如实写在这儿：applyProcessPriority() 调的是 Win32 的
//       SetPriorityClass()，它躲在 LauncherManager.cpp 的匿名命名空间里、还要一个真进程
//       句柄。能验的那一半（档位 → 字符串 → 档位、认不出来的值兜到 Normal）在下面；
//       另一半（那句 Win32 调用到底有没有生效）只能真机上开任务管理器看一眼。
//
// NOTE: 窗口大小那几条为什么这么绕（合成一份 json、而不是只喂真夹具）：真夹具里那条
//       `--width` 规则挂在 `has_custom_resolution` 上，而启动器一律传空 feature 集合，
//       所以那条规则**根本没命中过** —— 只喂真夹具的话，"我们发的那一对"和"json 那条
//       被丢掉了"这两件事里任何一件坏掉，结果都是"恰好一条 --width"，红不了。所以要再
//       造一份**把那个值写死成别的数字**的 json：谁发的这一对，从这里就分得出来了。
// =========================================================================

static void runLaunchOptionsTests(const QString &sandbox) {
    const QString metaDir = QStringLiteral(REPO_ROOT_PATH) + "/tests/meta";
    const QString settingsDir = sandbox + "/wtfml-launch-options-settings";
    QDir(settingsDir).removeRecursively();
    QDir().mkpath(settingsDir);

    QSettings::setDefaultFormat(QSettings::IniFormat);
    QSettings::setPath(QSettings::IniFormat, QSettings::UserScope, settingsDir);
    const QString iniPath = settingsDir + QStringLiteral("/WTFML/WTFML.ini");

    // ---------------------------------------------------------------------
    section("ZD1. 三项设置的默认值（全新沙盒）");
    // ---------------------------------------------------------------------
    {
        LauncherSettings fresh;
        check(!fresh.showGameLog(), "ZD1 默认不开「显示游戏日志」");
        // 854x480 是**原版自己的默认窗口大小**（1.12.2 的 Main 里那对 defaultsTo(854, 480)）。
        // 钉它是因为这条默认值承担着一个承诺：谁都不动这一项时，启动器发出去的两个参数
        // 就等于游戏本来要用的值 —— "加了这个功能"不该让任何人的窗口大小变一下。
        check(fresh.gameWindowWidth() == 854 && fresh.gameWindowHeight() == 480,
              "ZD1 默认窗口大小就是原版那个 854x480",
              QStringLiteral("%1x%2").arg(fresh.gameWindowWidth()).arg(fresh.gameWindowHeight()));
        check(fresh.processPriority() == ProcessPriority::Normal,
              "ZD1 默认优先级是 Normal（不是 High —— 猜高的代价是拖慢用户的机器）");
        // 顶上那行字：**空串是默认档**（= 条上那五个字母），不是"没有名字"。
        // 所以这里钉的是"全新沙盒读出来是空的" —— 里面要是被塞了个 "WTFML"，
        // 用户以后改名字就分不出"我改过"和"我没改过"了（条上那个默认值只有一个出处：
        // TitleBar::defaultBrandText()，不在这一层抄一份）。
        check(fresh.titleText().isEmpty(),
              "ZD1 默认没改过名字（空串 = 条上用默认那五个字母）",
              QStringLiteral("[%1]").arg(fresh.titleText()));
    }

    // ---------------------------------------------------------------------
    section("ZD2. 三项跨实例读得回来；手改 ini 也得兜住");
    // ---------------------------------------------------------------------
    {
        LauncherSettings settings;
        settings.setShowGameLog(true);
        settings.setGameWindowSize(1280, 720);
        settings.setProcessPriority(ProcessPriority::BelowNormal);
        settings.setTitleText(QStringLiteral("我的启动器"));

        // 换个实例读：验的是真落了盘，不是留在成员变量里
        LauncherSettings reopened;
        check(reopened.showGameLog(), "ZD2 「显示游戏日志」跨实例读得回来");
        check(reopened.gameWindowWidth() == 1280 && reopened.gameWindowHeight() == 720,
              "ZD2 窗口大小跨实例读得回来",
              QStringLiteral("%1x%2")
                  .arg(reopened.gameWindowWidth())
                  .arg(reopened.gameWindowHeight()));
        check(reopened.processPriority() == ProcessPriority::BelowNormal,
              "ZD2 优先级跨实例读得回来（不是退回 Normal —— 那会让用户以为设置没生效）");
        check(reopened.titleText() == QStringLiteral("我的启动器"),
              "ZD2 顶上那行字跨实例读得回来", reopened.titleText());

        // 这一项的两条整理（去空白 / 截长度）在 setter 和 load 两处都要做 —— 因为它会被
        // **画在条上**：带空格的" WTFML "看着就是没对齐，超长的名字会撞上中间那四颗导航
        // 按钮。下面三组：setter 侧、load 侧（手改 ini）。
        settings.setTitleText(QStringLiteral("   两头有空格   "));
        check(settings.titleText() == QStringLiteral("两头有空格"),
              "ZD2 setter 去掉两头的空白（名字是从条最左边开始画的）",
              QStringLiteral("[%1]").arg(settings.titleText()));
        settings.setTitleText(QString(40, QLatin1Char('W')));
        check(settings.titleText().size() == LauncherSettings::titleTextMaxLength(),
              "ZD2 setter 按上限截断",
              QStringLiteral("%1 个字").arg(settings.titleText().size()));
        settings.setTitleText(QStringLiteral("我的启动器"));

        // 存进去的值也可能是手改的，所以**读回来那一侧也要钳位**：这两个数会原样进游戏
        // 命令行，放一个 0 或者 99999 出去，游戏那边要么当没给、要么拿一个荒唐的窗口。
        {
            QSettings raw;
            raw.setValue(QStringLiteral("Launcher/WindowWidth"), 100);      // 低于下限
            raw.setValue(QStringLiteral("Launcher/WindowHeight"), 99999);  // 高于上限
            raw.setValue(QStringLiteral("Launcher/ProcessPriority"), QStringLiteral("turbo"));
            // 顶上那行字：手改成一个又长又带空格的名字（这条会原样画到条上，不能信）。
            raw.setValue(QStringLiteral("Launcher/TitleText"),
                         QStringLiteral("   ") + QString(40, QLatin1Char('X')) + QStringLiteral("  "));
            raw.sync();
        }
        LauncherSettings clamped;
        check(clamped.gameWindowWidth() == LauncherSettings::gameWindowMinWidth(),
              "ZD2 手改成过小的宽度后 load 会钳到下限",
              QString::number(clamped.gameWindowWidth()));
        check(clamped.gameWindowHeight() == LauncherSettings::gameWindowMaxHeight(),
              "ZD2 手改成过大的高度后 load 会钳到上限",
              QString::number(clamped.gameWindowHeight()));
        check(clamped.processPriority() == ProcessPriority::Normal,
              "ZD2 手改成认不出来的优先级后兜到 Normal");
        check(clamped.titleText() == QString(LauncherSettings::titleTextMaxLength(),
                                             QLatin1Char('X')),
              "ZD2 手改的名字读回来先去掉空白、再截到上限",
              QStringLiteral("[%1] %2 个字")
                  .arg(clamped.titleText())
                  .arg(clamped.titleText().size()));

        // setter 那一侧同样钳：界面上是 SpinBox 管着，但 setter 不能假设调用方是界面。
        settings.setGameWindowSize(1, 1);
        check(settings.gameWindowWidth() == LauncherSettings::gameWindowMinWidth() &&
                  settings.gameWindowHeight() == LauncherSettings::gameWindowMinHeight(),
              "ZD2 setter 也钳（1x1 → 下限那一对）",
              QStringLiteral("%1x%2")
                  .arg(settings.gameWindowWidth())
                  .arg(settings.gameWindowHeight()));
        settings.setGameWindowSize(99999, 99999);
        check(settings.gameWindowWidth() == LauncherSettings::gameWindowMaxWidth() &&
                  settings.gameWindowHeight() == LauncherSettings::gameWindowMaxHeight(),
              "ZD2 上限那一侧也钳",
              QStringLiteral("%1x%2")
                  .arg(settings.gameWindowWidth())
                  .arg(settings.gameWindowHeight()));

        check(QFileInfo::exists(iniPath), "ZD2 沙盒那份 ini 真的写出来了", iniPath);
    }

    // ---------------------------------------------------------------------
    section("ZD3. 优先级的持久化字符串：五个值往返 + 认不出来兜 Normal");
    // ---------------------------------------------------------------------
    {
        // 这几个串是**持久化格式的一部分**：改掉它们，用户盘上已经存好的值就会被当成
        // "认不出来"、静默退回 Normal —— 用户看到的是"设了高，重启又变回正常"。
        const QList<QPair<ProcessPriority, QString>> table = {
            {ProcessPriority::Low, QStringLiteral("low")},
            {ProcessPriority::BelowNormal, QStringLiteral("belowNormal")},
            {ProcessPriority::Normal, QStringLiteral("normal")},
            {ProcessPriority::AboveNormal, QStringLiteral("aboveNormal")},
            {ProcessPriority::High, QStringLiteral("high")},
        };
        QStringList seenKeys;
        for (const auto &row : table) {
            const QString key = LauncherSettings::processPriorityKey(row.first);
            check(key == row.second, QString("ZD3 %1 存进去就是 %2").arg(row.second, row.second),
                  key);
            check(LauncherSettings::processPriorityFromKey(row.second) == row.first,
                  QString("ZD3 %1 读得回来").arg(row.second));
            seenKeys << key;
        }
        // 「两两不同」这条是house rule：以前撞过一次角色编号（两个用途共用一个号码），
        // 症状是"看起来全绿、界面上却少了一个东西"。枚举到字符串这一层同样会撞。
        check(QSet<QString>(seenKeys.begin(), seenKeys.end()).size() == table.size(),
              "ZD3 五个持久化字符串两两不同", seenKeys.join(QStringLiteral(" | ")));

        // 认不出来的值：空串、大小写不对的、彻底没见过的。
        for (const QString &junk : {QString(), QStringLiteral("HIGH"),
                                    QStringLiteral("turbo"), QStringLiteral("0")}) {
            check(LauncherSettings::processPriorityFromKey(junk) == ProcessPriority::Normal,
                  QString("ZD3 认不出来的值（%1）兜到 Normal").arg(junk.isEmpty() ? QStringLiteral("<空>")
                                                                            : junk));
        }
    }

    // ---------------------------------------------------------------------
    section("ZD4. 窗口大小真的会进命令行（--width / --height）");
    // ---------------------------------------------------------------------
    {
        LauncherManager launcher;
        GlobalJavaSettings jvm;

        const auto countFlag = [](const QStringList &list, const QString &flag) {
            int n = 0;
            for (const QString &a : list) {
                if (a == flag) {
                    ++n;
                }
            }
            return n;
        };
        const auto valueOfFlag = [](const QStringList &list, const QString &flag) {
            const int i = list.indexOf(flag);
            return (i >= 0 && i + 1 < list.size()) ? list.at(i + 1) : QString();
        };

        const QJsonObject modern = loadJson(metaDir + "/1.19.json");
        check(!modern.isEmpty(), "ZD4 前提：读到了 1.19 那份夹具");

        // ---- (a) 真夹具（那条规则挂在 has_custom_resolution 上，我们传空 feature）----
        {
            // 前提也要钉：这条规则**在夹具里**。夹具哪天换了，红的应该是这一条，
            // 而不是让下面几条悄悄变成"在验一段没人走的代码"。
            bool hasRule = false;
            const QJsonArray game =
                modern.value(QStringLiteral("arguments")).toObject().value(QStringLiteral("game")).toArray();
            for (const QJsonValue &v : game) {
                const QJsonObject entry = v.toObject();
                if (!entry.value(QStringLiteral("rules")).toArray().isEmpty() &&
                    entry.value(QStringLiteral("value")).toArray().contains(
                        QStringLiteral("--width"))) {
                    hasRule = true;
                }
            }
            check(hasRule,
                  "ZD4 前提：1.19 夹具里确实有一条挂在规则上的 --width");
        }

        {
            const QStringList args = launcher.generateJvmArguments(
                QString(), QStringLiteral("1.19"), QStringLiteral("1"), modern, jvm, true, 17,
                QStringList(),                 QString(), QString(),
                GameWindowSettings{GameWindowMode::Windowed, 1280, 720});
            check(countFlag(args, QStringLiteral("--width")) == 1,
                  "ZD4 传了窗口大小 → 命令线上恰好一条 --width",
                  QString::number(countFlag(args, QStringLiteral("--width"))));
            check(countFlag(args, QStringLiteral("--height")) == 1,
                  "ZD4 --height 也恰好一条");
            check(valueOfFlag(args, QStringLiteral("--width")) == QStringLiteral("1280") &&
                      valueOfFlag(args, QStringLiteral("--height")) == QStringLiteral("720"),
                  "ZD4 两个值就是我们给的那一对",
                  valueOfFlag(args, QStringLiteral("--width")) + QStringLiteral("x") +
                      valueOfFlag(args, QStringLiteral("--height")));
        }

        // ---- (b) 没传窗口设置：发的是**原版默认那一对**（854×480）----
        //
        // NOTE: 加了「窗口模式」之后这一条的判据变了。原来这两个数默认为 0、判的是
        //       "一条都不发"；现在默认构造就是原版那个默认窗口大小（854×480），所以默认
        //       那一趟是**照发**。两条都对用户是同一件事（游戏开出来还是那个 854×480），
        //       但"什么都不发"和"发一对 854×480"在命令行上不是一回事 —— 而 json 自己带的
        //       那对 --width 只在 has_custom_resolution 那类规则成立时才出现，靠它兜底不
        //       可靠，所以这一档我们**明着发**。
        {
            const QStringList args = launcher.generateJvmArguments(
                QString(), QStringLiteral("1.19"), QStringLiteral("1"), modern, jvm, true, 17);
            check(valueOfFlag(args, QStringLiteral("--width")) == QStringLiteral("854") &&
                      valueOfFlag(args, QStringLiteral("--height")) == QStringLiteral("480"),
                  "ZD4 没传窗口设置 → 发的是原版默认那一对（854×480）",
                  valueOfFlag(args, QStringLiteral("--width")) + QStringLiteral("x") +
                      valueOfFlag(args, QStringLiteral("--height")));
        }

        // ---- (b2) 两格不是正数：一条都不发 ----
        //
        // 这是"调用方明确说不给"的那一档（原来那条"默认 0"的判据搬到了这里）。发一个 0
        // 出去的后果是 joptsimple 抛异常、游戏根本起不来 —— 宁可不发。
        {
            const QStringList args = launcher.generateJvmArguments(
                QString(), QStringLiteral("1.19"), QStringLiteral("1"), modern, jvm, true, 17,
                QStringList(), QString(), QString(),
                GameWindowSettings{GameWindowMode::Windowed, 0, 0});
            check(countFlag(args, QStringLiteral("--width")) == 0 &&
                      countFlag(args, QStringLiteral("--height")) == 0,
                  "ZD4 调用方给的是 0×0 → 一条都不发（发一个 0 出去游戏起不来）");
        }

        // ---- (c) 把 json 那一对**写死成别的数字**：还是一条，而且是我们那条 ----
        // 这一条才是真正分得清"谁发的"的那条：json 那条真被丢掉的话，留下的值只可能是
        // 1280；它要是漏出来，值就是 640/480（或者两条 --width）。
        {
            QJsonArray game =
                modern.value(QStringLiteral("arguments")).toObject().value(QStringLiteral("game")).toArray();
            for (int i = 0; i < game.size(); ++i) {
                const QJsonObject entry = game.at(i).toObject();
                if (!entry.value(QStringLiteral("rules")).toArray().isEmpty() &&
                    entry.value(QStringLiteral("value")).toArray().contains(
                        QStringLiteral("--width"))) {
                    QJsonObject literal = entry;
                    QJsonArray literalValue;
                    literalValue << QStringLiteral("--width") << QStringLiteral("640")
                                 << QStringLiteral("--height") << QStringLiteral("480");
                    literal[QStringLiteral("value")] = literalValue;
                    game.replace(i, literal);
                }
            }
            QJsonObject arguments = modern.value(QStringLiteral("arguments")).toObject();
            arguments[QStringLiteral("game")] = game;
            QJsonObject literalJson = modern;
            literalJson[QStringLiteral("arguments")] = arguments;

            const QStringList args = launcher.generateJvmArguments(
                QString(), QStringLiteral("1.19"), QStringLiteral("1"), literalJson, jvm, true, 17,
                QStringList(),                 QString(), QString(),
                GameWindowSettings{GameWindowMode::Windowed, 1280, 720});
            check(countFlag(args, QStringLiteral("--width")) == 1,
                  "ZD4 json 里写死一对 --width 640 时，最终仍只有一条（同一个开关发两次 "
                  "joptsimple 会直接报错退出）",
                  QString::number(countFlag(args, QStringLiteral("--width"))));
            check(valueOfFlag(args, QStringLiteral("--width")) == QStringLiteral("1280"),
                  "ZD4 留下的是**我们**那条（json 里那条被 isVanillaGameArgument 丢掉了）",
                  valueOfFlag(args, QStringLiteral("--width")));
        }

        // ---- (d) 老格式（minecraftArguments）：1.12.2 那一代真机走的就是这条路 ----
        // 1.12.2 的 minecraftArguments 里压根没有 width/height，游戏自己的 main 从 1.6 起
        // 就认 --width/--height（那对 defaultsTo(854, 480) 就是默认窗口大小的出处）。
        {
            const QJsonObject legacy = loadJson(metaDir + "/1.12.2.json");
            const QString legacyArgs = legacy.value(QStringLiteral("minecraftArguments")).toString();
            check(!legacyArgs.isEmpty(),
                  "ZD4 前提：1.12.2 那份夹具确实走老格式的 minecraftArguments");
            // 这条前提才是下面那条断言的用处所在：这份 json **没有**声明窗口大小，所以
            // 命令线上那一对只可能是启动器自己发的（不是 json 那条漏出来了）。
            check(!legacyArgs.contains(QStringLiteral("--width")),
                  "ZD4 前提：而且它自己没声明 --width（那一条就只可能是我们发的）");

            const QStringList args = launcher.generateJvmArguments(
                QString(), QStringLiteral("1.12.2"), QStringLiteral("1"), legacy, jvm, true, 8,
                QStringList(),                 QString(), QString(),
                GameWindowSettings{GameWindowMode::Windowed, 1024, 768});
            check(countFlag(args, QStringLiteral("--width")) == 1 &&
                      valueOfFlag(args, QStringLiteral("--width")) == QStringLiteral("1024"),
                  "ZD4 老格式也发我们那一对",
                  valueOfFlag(args, QStringLiteral("--width")));
        }

        // ---- (e) 老格式且 json 自己带了一对：加进去的必须是**另一对数字** ----
        // 这是 contains("--width") 那个守卫的用处：json 里已经有的话就不能再加一遍。
        // 数字故意取得和我们要发的不同，这样"到底留下谁"是有区别的。
        {
            QJsonObject legacy = loadJson(metaDir + "/1.12.2.json");
            const QString base =
                legacy.value(QStringLiteral("minecraftArguments")).toString();
            legacy[QStringLiteral("minecraftArguments")] =
                base + QStringLiteral(" --width 1280 --height 720");

            const QStringList args = launcher.generateJvmArguments(
                QString(), QStringLiteral("1.12.2"), QStringLiteral("1"), legacy, jvm, true, 8,
                QStringList(),                 QString(), QString(),
                GameWindowSettings{GameWindowMode::Windowed, 1024, 768});
            check(countFlag(args, QStringLiteral("--width")) == 1,
                  "ZD4 json 自带 --width 时不会发第二遍（joptsimple 见重复选项直接退出）",
                  QString::number(countFlag(args, QStringLiteral("--width"))));
            check(valueOfFlag(args, QStringLiteral("--width")) == QStringLiteral("1024"),
                  "ZD4 而且留下的是我们那一对，不是 json 里那个 1280",
                  valueOfFlag(args, QStringLiteral("--width")));
        }

        // ---- (f) 那两个 resolution_* 占位符真的是填进去的 ----
        // LauncherManager 里填它们是为了**万一**有老版本的 minecraftArguments 直接写着
        // `${resolution_width}`（那种拼法见过）：留一个没替换的 ${...} 在命令行上，
        // 游戏拿到的就是一个字面量的 "${resolution_width}"。
        //
        // 这里只能拿一个**我们自己编的**参数名来探（`--wtfmlProbe`）：原版那几个名字
        // （--width/--height）会被 isVanillaGameArgument 连同占位符一起丢掉，那条路正是
        // 上面 (e) 验的。也就是说这条探针验的是"占位符填进去了没有"，不是"原版那条会生效"。
        {
            QJsonObject legacy = loadJson(metaDir + "/1.12.2.json");
            const QString base =
                legacy.value(QStringLiteral("minecraftArguments")).toString();
            legacy[QStringLiteral("minecraftArguments")] =
                base + QStringLiteral(" --wtfmlProbe ${resolution_width}");

            const QStringList args = launcher.generateJvmArguments(
                QString(), QStringLiteral("1.12.2"), QStringLiteral("1"), legacy, jvm, true, 8,
                QStringList(),                 QString(), QString(),
                GameWindowSettings{GameWindowMode::Windowed, 1024, 768});
            const int probeIndex = args.indexOf(QStringLiteral("--wtfmlProbe"));
            check(probeIndex >= 0 && probeIndex + 1 < args.size() &&
                      args.at(probeIndex + 1) == QStringLiteral("1024"),
                  "ZD4 ${resolution_width} 被替换成了我们给的宽度",
                  probeIndex >= 0 && probeIndex + 1 < args.size()
                      ? args.at(probeIndex) + QLatin1Char(' ') + args.at(probeIndex + 1)
                      : QStringLiteral("<没有 --wtfmlProbe 这一条>"));
            // 顺带把"一个 ${...} 都不许漏"钉死：漏一个的症状是游戏拿到一句字面量。
            QString unresolved;
            for (const QString &a : args) {
                if (a.contains(QStringLiteral("${resolution_"))) {
                    unresolved = a;
                    break;
                }
            }
            check(unresolved.isEmpty(),
                  "ZD4 命令线上不留没替换的 ${resolution_*} 占位符", unresolved.left(160));
        }
    }

    // ---------------------------------------------------------------------
    section("ZD5. 窗口那三档：代号往返、合成、以及各档发什么参数");
    // ---------------------------------------------------------------------
    // 这一节全是**纯函数**（除了最后那几条 LauncherSettings 的持久化），所以断的是
    // 「哪一档发哪几个参数」这一条契约本身。它和 ZD4 的关系：ZD4 验的是"那些参数最后
    // 有没有真的拼进命令行、会不会和 json 自带的那条打架"，这一节验的是"该发哪几个"。
    {
        // ---- (a) 代号（持久化格式的一部分）往返 ----
        const GameWindowMode modes[] = {GameWindowMode::Windowed, GameWindowMode::Maximized,
                                        GameWindowMode::Fullscreen};
        bool roundTripOk = true;
        QStringList tokens;
        for (GameWindowMode mode : modes) {
            const QString token = gameWindowModeToken(mode);
            tokens << token;
            GameWindowMode back = GameWindowMode::Windowed;
            if (!gameWindowModeFromToken(token, &back) || back != mode) {
                roundTripOk = false;
            }
        }
        check(roundTripOk, "ZD5 三档的代号各自往返得回来", tokens.join(QStringLiteral(",")));
        check(tokens == QStringList({QStringLiteral("windowed"), QStringLiteral("maximized"),
                                     QStringLiteral("fullscreen")}),
              "ZD5 代号就是盘上约定那三个串（改掉它们等于让用户存好的档位静默退回默认）",
              tokens.join(QStringLiteral(",")));
        {
            // 认不出来时**一个字节都不许动 out** —— 调用方是靠"没动"来判断要不要退回兜底值
            // 的。写成"顺手把 out 设成小窗"也能过大多数断言，但那让调用方失去这个判断能力。
            GameWindowMode sentinel = GameWindowMode::Fullscreen;
            check(!gameWindowModeFromToken(QStringLiteral("最大窗口"), &sentinel) &&
                      sentinel == GameWindowMode::Fullscreen,
                  "ZD5 认不出来的代号返回 false，而且不碰 out（调用方自己给兜底）");
            check(!gameWindowModeFromToken(QString(), &sentinel),
                  "ZD5 空串也认不出来");
            check(!gameWindowModeFromToken(QStringLiteral("windowed"), nullptr),
                  "ZD5 out 传空指针时不炸、回 false");
        }

        // ---- (b) meta 里那三个键名（读侧写侧的唯一出处）----
        check(gameWindowModeMetaField() == QStringLiteral("windowMode") &&
                  gameWindowWidthMetaField() == QStringLiteral("windowWidth") &&
                  gameWindowHeightMetaField() == QStringLiteral("windowHeight"),
              "ZD5 meta 里那三个键名是约定的那一个",
              gameWindowModeMetaField() + QStringLiteral("/") + gameWindowWidthMetaField() +
                  QStringLiteral("/") + gameWindowHeightMetaField());

        // ---- (c) meta ↔ 覆盖层：读得出来、写得回去、垃圾当没写 ----
        {
            QJsonObject meta;
            meta[gameWindowModeMetaField()] = QStringLiteral("fullscreen");
            meta[gameWindowWidthMetaField()] = 1920;
            meta[gameWindowHeightMetaField()] = 1080;
            const GameWindowOverride read = gameWindowOverrideFromJson(meta);
            check(read.mode.has_value() && *read.mode == GameWindowMode::Fullscreen &&
                      read.width.value_or(0) == 1920 && read.height.value_or(0) == 1080,
                  "ZD5 三个键都写了 → 三项覆盖都读出来了");
            check(gameWindowOverrideToJson(read) == meta,
                  "ZD5 读出来再写回去，逐键相同（读侧写侧是同一个键名表）");

            // 一半写一半没写：没写的那一半必须是"跟随全局"，不是"0"。
            QJsonObject half;
            half[gameWindowWidthMetaField()] = 1024;
            const GameWindowOverride halfRead = gameWindowOverrideFromJson(half);
            check(!halfRead.mode.has_value(),
                  "ZD5 只写了宽 → 模式那一项没有值（= 跟随全局）");
            check(halfRead.width.has_value() && *halfRead.width == 1024 &&
                      !halfRead.height.has_value(),
                  "ZD5 只写了宽 → 高那一项也没有值（不会被当成 0）");

            // 类型不对/认不出来的，一律当没写。
            QJsonObject junk;
            junk[gameWindowModeMetaField()] = QStringLiteral("最大窗口");
            junk[gameWindowWidthMetaField()] = QStringLiteral("1920");  // 字符串不是数
            junk[gameWindowHeightMetaField()] = 1080.5;                 // 半个像素
            const GameWindowOverride junkRead = gameWindowOverrideFromJson(junk);
            check(!junkRead.mode.has_value() && !junkRead.width.has_value() &&
                      !junkRead.height.has_value(),
                  "ZD5 认不出来的档位 / 字符串宽度 / 小数高度，三样都当没写");

            // 没值的那几项写成 Null（= 删键），这正是「跟随全局」要的结果。
            const QJsonObject empty = gameWindowOverrideToJson(GameWindowOverride());
            check(empty.value(gameWindowModeMetaField()).isNull() &&
                      empty.value(gameWindowWidthMetaField()).isNull() &&
                      empty.value(gameWindowHeightMetaField()).isNull(),
                  "ZD5 一个覆盖都没有时三格都是 Null（updateVersionMeta 把它当删键）");
        }

        // ---- (d) 合成：覆盖压全局，缺的那一项跟随 ----
        {
            GameWindowSettings global;
            global.mode = GameWindowMode::Windowed;
            global.width = 854;
            global.height = 480;

            const GameWindowSettings untouched = resolveGameWindow(global, GameWindowOverride());
            check(untouched.mode == GameWindowMode::Windowed && untouched.width == 854 &&
                      untouched.height == 480,
                  "ZD5 一个键都不覆盖 → 逐项等于全局（加这一档之前的行为）");

            GameWindowOverride partial;
            partial.mode = GameWindowMode::Fullscreen;
            partial.width = 1920;  // 高度故意不给
            const GameWindowSettings merged = resolveGameWindow(global, partial);
            check(merged.mode == GameWindowMode::Fullscreen && merged.width == 1920 &&
                      merged.height == 480,
                  "ZD5 覆盖了模式和宽 → 那两项用覆盖、没覆盖的高跟随全局",
                  QStringLiteral("%1x%2").arg(merged.width).arg(merged.height));

            // ★ 覆盖里的数**要钳位**（meta 是手写的文件，这两个数会原样进命令行）。
            GameWindowOverride wild;
            wild.width = -1920;
            wild.height = 999999;
            const GameWindowSettings clamped = resolveGameWindow(global, wild);
            check(clamped.width == LauncherSettings::gameWindowMinWidth() &&
                      clamped.height == LauncherSettings::gameWindowMaxHeight(),
                  "ZD5 覆盖里的负数/天文数字被钳进合法区间（那两个数会原样进命令行）",
                  QStringLiteral("%1x%2").arg(clamped.width).arg(clamped.height));
        }

        // ---- (e) 各档发什么参数 ----
        {
            const ScreenWorkArea screen{1920, 1040};

            const QStringList windowed = gameWindowArguments(
                GameWindowSettings{GameWindowMode::Windowed, 1280, 720}, screen);
            check(windowed == QStringList({QStringLiteral("--width"), QStringLiteral("1280"),
                                           QStringLiteral("--height"), QStringLiteral("720")}),
                  "ZD5 小窗：只发 --width/--height，不发 --fullscreen",
                  windowed.join(QStringLiteral(" ")));

            const QStringList fullscreen = gameWindowArguments(
                GameWindowSettings{GameWindowMode::Fullscreen, 1280, 720}, screen);
            check(fullscreen.size() == 5 && fullscreen.first() == QStringLiteral("--fullscreen"),
                  "ZD5 全屏：--fullscreen 排在最前面（原版真参数）",
                  fullscreen.join(QStringLiteral(" ")));
            check(fullscreen.contains(QStringLiteral("--width")) &&
                      fullscreen.contains(QStringLiteral("1280")),
                  "ZD5 全屏**照样**发那一对大小（那是 F11 退出全屏后回到多大）",
                  fullscreen.join(QStringLiteral(" ")));

            // 最大化：没有屏幕可量（<= 0 是"调用方没给"的哨兵）时退回用户那两格 ——
            // 宁可开一个用户填过大小的窗口，也不要因为取不到屏幕就发一对 0 出去。
            const QStringList noScreen = gameWindowArguments(
                GameWindowSettings{GameWindowMode::Maximized, 1280, 720}, ScreenWorkArea());
            check(noScreen == QStringList({QStringLiteral("--width"), QStringLiteral("1280"),
                                           QStringLiteral("--height"),
                                           QStringLiteral("720")}),
                  "ZD5 最大化但拿不到屏幕：退回用户填的那一对（不发 0 出去）",
                  noScreen.join(QStringLiteral(" ")));
            check(!noScreen.contains(QStringLiteral("--fullscreen")),
                  "ZD5 最大化**不是**全屏（原版没有最大化参数，见 .hpp 那一节）");

            // 两格不是正数时一条都不发（老规矩）。
            check(gameWindowArguments(GameWindowSettings{GameWindowMode::Windowed, 0, 0}, screen)
                      .isEmpty(),
                  "ZD5 宽高是 0 → 一条都不发（宁可不发，也不发一个 0）");
            const QStringList onlyFullscreen = gameWindowArguments(
                GameWindowSettings{GameWindowMode::Fullscreen, 0, 0}, screen);
            check(onlyFullscreen == QStringList({QStringLiteral("--fullscreen")}),
                  "ZD5 全屏 + 宽高为 0：只剩 --fullscreen 一条（全屏那一档本身不靠那两个数）",
                  onlyFullscreen.join(QStringLiteral(" ")));
        }

        // ---- (f) 「最大化」要照屏幕工作区算：量不出边框就原样 ----
        //
        // NOTE: verify 这一份是**纯 Core** 的（没链 Widgets），所以 maximizedContentSize()
        //       里"起一个探测窗口量边框"那一段是编不进来的 —— 这里量的是它那条**兜底**
        //       行为（拿不到边框时原样返回工作区）。带上窗口系统的那条路在 mw_check /
        //       ui_shot 里跑（那边走的是同一个函数、同一个分支判据）。
        {
            const ScreenWorkArea same = maximizedContentSize(ScreenWorkArea{1920, 1040});
            check(same.width <= 1920 && same.width > 0 && same.height <= 1040 && same.height > 0,
                  "ZD5 量不出边框时最多退回工作区原样（不会变成 0 或者负数）",
                  QStringLiteral("%1x%2").arg(same.width).arg(same.height));
            const ScreenWorkArea none = maximizedContentSize(ScreenWorkArea());
            check(none.width == 0 && none.height == 0,
                  "ZD5 没给工作区（哨兵 0）→ 原样返回 0，调用方据此退回用户那两格");
        }

        // ---- (g) 这一档设置存得下来（和 ZD2 那三项同一套）----
        {
            // 先把盘上那份清成默认：这一节排在 ZD2/ZD3 之后，而那两节已经写过别的值了。
            LauncherSettings settings;
            settings.setGameWindowMode(GameWindowMode::Maximized);
            settings.setGameWindowSize(1600, 900);
            LauncherSettings reopened;
            check(reopened.gameWindowMode() == GameWindowMode::Maximized,
                  "ZD5 窗口模式跨实例读得回来");
            check(reopened.gameWindowSettings().mode == GameWindowMode::Maximized &&
                      reopened.gameWindowSettings().width == 1600 &&
                      reopened.gameWindowSettings().height == 900,
                  "ZD5 gameWindowSettings() 把模式和分辨率捆成一份给出来");
            // 手改 ini 成一个认不出来的值 ⇒ 退回默认档（小窗），不猜也不报错。
            {
                QSettings ini(iniPath, QSettings::IniFormat);
                ini.setValue(QStringLiteral("Launcher/WindowMode"), QStringLiteral("最大窗口"));
                ini.sync();
            }
            LauncherSettings afterEdit;
            check(afterEdit.gameWindowMode() == GameWindowMode::Windowed,
                  "ZD5 盘上那个串认不出来 → 退回默认档（小窗 = 加这一档之前的行为）");
        }
    }

    // 收摊：换回原生形态并把沙盒删掉 —— 后面那些节读的还是真实注册表。
    QSettings::setDefaultFormat(QSettings::NativeFormat);
    QDir(settingsDir).removeRecursively();
}

// =========================================================================
// ZH. 服务器列表：真的连上去问一句（Server List Ping / 状态协议）
//
// 用户 2026-09-26 问的「服务器列表能实际 ping 服务器并显示服务器图标和 motd 吗」。这一
// 节分两半，因为两半的错法完全不同：
//
//   * **拆包那一半**（地址怎么拆、VarInt 怎么编怎么读、MOTD 怎么展平、图标那串 data URL
//     怎么解）全是纯函数，喂什么进来看什么出来；
//   * **协议那一半必须真连一次**。只验纯函数的话，"我们发出去的握手长什么样"和"服务器真
//     答回来一坨我们读不读得下来"这两件事一条都没碰到 —— 而真机上错的恰恰是这两件：握手
//     里写错一格（比如下一状态写成 2）服务器会等一个永远不来的登录包，一个字节都不答；
//     收包不按长度收全，带图标的响应会缺尾巴、解出来是一张破图。所以下面起一台**真**
//     QTcpServer 说这个协议，并且把它**收到的字节**逐字段拆开核对。
//
// NOTE: 假服务器**跑在自己的线程里**，这不是讲究：产品的 ServerPing::ping() 是同步的
//       （waitForConnected / waitForReadyRead 一路等到底），中间**不转 Qt 的事件循环**。
//       同一个线程里摆一台 QTcpServer，那一侧的新连接通知永远排不上队，看到的会是"连上了
//       但没人回答" —— 那正好是超时那一档的样子，而那是测试自己的错，不是产品的。
//
// NOTE: 这一节只碰 127.0.0.1，**一条都不出网**（所以断网的机器上也该全绿）。
// =========================================================================

/// 一台说 Server List Ping 的假服务器（127.0.0.1、随机端口），跑在自己的线程里。
///
/// 它只做两件事：**把收到的字节留着**（用来证我们发出去的那个握手是对的），以及按 mode
/// 回一句。它不解析收到的包 —— 拆包那件事产品自己会做，这里要是也写一份解析，两边一起
/// 错成同一个样子就谁也看不出来了。
class FakeStatusServer : public QThread {
public:
    /// 服务器怎么答这一发。
    enum Mode {
        Answer,      ///< 正常答：包里是 json 那段
        Silent,      ///< 收下、**一个字都不回**（"服务器没有回答"那一档）
        Garbage,     ///< 回一个包，正文不是 JSON
        HugeLength,  ///< 只回一个长度前缀，报一个天文数字（测那道上限闸）
        NotStatus,   ///< 包 id 不是 0x00
        ShortBody,   ///< 包自己那个长度是诚实的，坏的是里面"正文多长"那一格
    };

    explicit FakeStatusServer(Mode mode) : m_mode(mode) {}

    /// 响应里那段 JSON（Answer / Garbage / NotStatus / ShortBody 这几档用）。
    QByteArray json = QByteArrayLiteral("{}");
    /// 服务器**收到的**字节（原样，按到的次序）。
    QByteArray seen;
    /// 收到几个连接（"连不上"那几档根本不进这里）。
    int connections = 0;
    /// 起来之后监听的端口。
    quint16 port = 0;
    /// listen 成没成。
    bool listening = false;

    /// 起了、端口也拿到了才返回 —— 不然 port 还是 0，调用方会连到"随便一个端口"上去。
    void startAndWait() {
        start();
        m_ready.acquire();
    }

    void run() override {
        QTcpServer server;
        listening = server.listen(QHostAddress::LocalHost, 0);
        if (!listening) {
            m_ready.release();
            return;
        }
        port = server.serverPort();
        m_ready.release();

        // 等一个连接：**用这条线程自己的事件循环**（这条线程上没有别的事要转，所以这样最
        // 稳），外面套一个硬上限 —— 这一条要是等不着，整节就没法往下走。
        {
            QEventLoop loop;
            QObject::connect(&server, &QTcpServer::newConnection, &loop, &QEventLoop::quit);
            QTimer::singleShot(3000, &loop, &QEventLoop::quit);
            if (!server.hasPendingConnections()) {
                loop.exec();
            }
        }
        QTcpSocket *socket = server.nextPendingConnection();
        if (socket == nullptr) {
            return;
        }
        ++connections;

        // 收"握手 + 状态请求"这两个包。这里**不解析**，只等它们到齐 —— 客户端是两发一起
        // 写出去的，所以一次 readAll 就把两个包一起拿到了。
        //
        // NOTE: 退出条件必须写成"读到了、而且对面接着没别的了"，**不能**写成"读到够 N 个
        //       字节"：握手一共才 22 个字节，写成 `seen.size() < 48` 的话每一次都会在这儿
        //       干等满那个上限，于是下面量"耗时"的每一条断言（latency、当场放弃那两条）
        //       量到的全是这段死等的时间 —— 实测就是 1.6 秒，看起来像产品慢。
        QElapsedTimer clock;
        clock.start();
        while (clock.elapsed() < 2000) {
            if (!socket->waitForReadyRead(120)) {
                if (!seen.isEmpty()) {
                    break;
                }
                continue;  // 还没拿到任何东西，接着等（最多 2 秒）
            }
            seen += socket->readAll();
        }

        if (m_mode == Silent) {
            // 收下、不回：让客户端自己等到超时（那一档验的就是这个）。
            socket->waitForDisconnected(3000);
            delete socket;
            return;
        }

        socket->write(replyBytes());
        socket->waitForBytesWritten(1000);
        socket->flush();
        // 客户端读完就关；给它一点时间把包收全，然后收摊。
        socket->waitForDisconnected(1500);
        delete socket;
    }

private:
    /// 一个完整的响应包（VarInt 长度前缀 + 正文）。
    QByteArray replyBytes() const {
        QByteArray body;
        switch (m_mode) {
        case Garbage:
            body = ServerPing::varIntBytes(0x00) + ServerPing::varIntBytes(json.size()) + json;
            break;
        case NotStatus:
            body = ServerPing::varIntBytes(0x01) + ServerPing::varIntBytes(json.size()) + json;
            break;
        case ShortBody:
            // 包自己那个长度是**诚实的**（客户端会老老实实收全），坏的是里面"正文多长"那
            // 一格 —— 这两种长度是两回事，只有分别喂得出来才分得清。
            body = ServerPing::varIntBytes(0x00) + ServerPing::varIntBytes(9999) + json;
            break;
        case HugeLength:
            // 只发前缀，一个字节正文都不发：客户端应当**看到这个数就放弃**，而不是等一堆
            // 永远不来的字节（那正好是"超时"这条路上最难看的一种死法）。
            return ServerPing::varIntBytes(kTooBigForTest);
        case Answer:
        case Silent:
        default:
            body = ServerPing::varIntBytes(0x00) + ServerPing::varIntBytes(json.size()) + json;
            break;
        }
        return ServerPing::varIntBytes(body.size()) + body;
    }

    /// 比产品那道 1 MiB 的上限（ServerPing.cpp 里那个 kMaxPacketBytes）大就行 —— 这里写
    /// 4 MiB，离上限足够远，将来上限调大一点这条也不会跟着红。
    static constexpr int kTooBigForTest = 4 * 1024 * 1024;

    Mode m_mode;
    QSemaphore m_ready;
};

/// 收摊：等假服务器那条线程跑完。
///
/// NOTE: **必须等**。一个还在跑的 QThread 被析构掉（"QThread: Destroyed while thread is
///       still running"）会直接把进程带崩，而这儿崩掉的话后面那些节一条都跑不到 —— 看
///       起来会像是"这次改动把别的东西弄坏了"。run() 里每一段都有上限，所以正常情况下
///       这里一定等得到。
static void waitFakeServer(FakeStatusServer &server) {
    if (!server.wait(12000)) {
        check(false, "ZH 假服务器那条线程没停下来（最多等 12 秒）");
        server.terminate();
        server.wait(3000);
    }
}

/// 几台假服务器互相等的那个闸（ZH10 用）：每一台连上来时报一次到，然后**等到大家都到齐**。
///
/// 这是"多线程一起问"这件事唯一能被**确定地**验出来的构造：量耗时是环境说了算的
/// （本机连一个没人听的回环端口要等满整个超时，ZH7 实测过），而"你等我、我等你"这件事
/// 串行跑**根本不可能**成立 —— 第 1 台永远等不来第 2 台。
class GateBarrier {
public:
    explicit GateBarrier(int expected) : m_expected(expected) {}

    /// 报一个到，然后等大家都到齐（最多 @p ms 毫秒）。
    /// @return 到齐了没有。**等不到时调用方必须做点看得见的坏事**（这里是"不回话"），
    ///         否则"没到齐"会被下一句照常回的那一答盖过去，整节就变成了一个假绿。
    bool arriveAndWait(int ms) {
        QMutexLocker locker(&m_mutex);
        ++m_arrived;
        if (m_arrived >= m_expected) {
            m_condition.wakeAll();
            return true;
        }
        return m_condition.wait(&m_mutex, ms);
    }

    int arrived() {
        QMutexLocker locker(&m_mutex);
        return m_arrived;
    }

private:
    QMutex m_mutex;
    QWaitCondition m_condition;
    const int m_expected;
    int m_arrived = 0;
};

/// 一台"要等到大家一起连上来才回话"的假服务器（ZH10 用）。
///
/// 它和 FakeStatusServer 是两路：那一台是"按 mode 答一发给一台客户端"，这一台的重点全在
/// **它什么时候才答**。答的那句话里带着自己的号（`{"description":"gate-<n>"}`），所以
/// 每一条结果都能认出是不是自己那一台 —— 并发之后结果回来的次序不再等于下标次序，
/// 这一点得有东西钉住。
class GatedStatusServer : public QThread {
public:
    GatedStatusServer(GateBarrier *gate, int id) : m_gate(gate), m_id(id) {}

    /// 起来之后监听的端口。
    quint16 port = 0;
    bool listening = false;

    /// 起了、端口也拿到了才返回（同 FakeStatusServer::startAndWait）。
    void startAndWait() {
        start();
        m_ready.acquire();
    }

    void run() override {
        QTcpServer server;
        listening = server.listen(QHostAddress::LocalHost, 0);
        if (!listening) {
            m_ready.release();
            return;
        }
        port = server.serverPort();
        m_ready.release();

        QEventLoop loop;
        QObject::connect(&server, &QTcpServer::newConnection, &loop, &QEventLoop::quit);
        // 上限掐得比产品那道 ping 超时（默认 4 秒）短一截：这一格里等不到就该走"没到齐"，
        // 让它和"对面连都不来连"这两件事在时间上分得开。
        QTimer::singleShot(3000, &loop, &QEventLoop::quit);
        if (!server.hasPendingConnections()) {
            loop.exec();
        }
        QTcpSocket *socket = server.nextPendingConnection();
        if (socket == nullptr) {
            return;
        }

        // 先把"握手 + 状态请求"收下再进闸门 —— 对面是两发一起写出去的，收完这两个包
        // 这一台才算"真的连上来了"。
        QElapsedTimer clock;
        clock.start();
        QByteArray seen;
        while (clock.elapsed() < 2000) {
            if (!socket->waitForReadyRead(120)) {
                if (!seen.isEmpty()) {
                    break;
                }
                continue;
            }
            seen += socket->readAll();
        }

        // ★ 这一节的全部要害就在这一句：**等别的几台也连上来**。
        const bool allHere = m_gate->arriveAndWait(2500);
        if (!allHere) {
            // 等不到 = 对面不可能是同时在问。**一个字都不回**：让那一条走到超时，
            // 于是"串行"这件事变成一条红的断言，而不是"慢一点但是过了"。
            socket->waitForDisconnected(500);
            delete socket;
            return;
        }

        const QByteArray json =
            QStringLiteral("{\"description\":\"gate-%1\"}").arg(m_id).toUtf8();
        const QByteArray body =
            ServerPing::varIntBytes(0x00) + ServerPing::varIntBytes(json.size()) + json;
        socket->write(ServerPing::varIntBytes(body.size()) + body);
        socket->waitForBytesWritten(1000);
        socket->flush();
        socket->waitForDisconnected(1500);
        delete socket;
    }

private:
    QSemaphore m_ready;
    GateBarrier *m_gate;
    int m_id;
};

static void runServerPingTests() {
    // ---------------------------------------------------------------------
    section("ZH1. 地址怎么拆（主机名 / :端口 / [IPv6]:端口）");
    // ---------------------------------------------------------------------

    {
        const ServerPing::Address plain = ServerPing::splitAddress(QStringLiteral("example.com"));
        check(plain.valid && plain.host == QStringLiteral("example.com") &&
                  plain.port == ServerPing::kDefaultPort,
              "ZH1 不写端口 = 默认 25565",
              QStringLiteral("%1:%2").arg(plain.host).arg(plain.port));

        const ServerPing::Address withPort =
            ServerPing::splitAddress(QStringLiteral("  mc.hypixel.net:25566  "));
        check(withPort.valid && withPort.host == QStringLiteral("mc.hypixel.net") &&
                  withPort.port == 25566,
              "ZH1 两头空白去掉、端口照写",
              QStringLiteral("%1:%2").arg(withPort.host).arg(withPort.port));

        const ServerPing::Address v6 = ServerPing::splitAddress(QStringLiteral("[::1]:25566"));
        check(v6.valid && v6.host == QStringLiteral("::1") && v6.port == 25566,
              "ZH1 [IPv6]:端口 —— 方括号**要去掉**（Qt 的 connectToHost 收的是裸地址）",
              QStringLiteral("%1:%2").arg(v6.host).arg(v6.port));

        const ServerPing::Address v6NoPort = ServerPing::splitAddress(QStringLiteral("[::1]"));
        check(v6NoPort.valid && v6NoPort.host == QStringLiteral("::1") &&
                  v6NoPort.port == ServerPing::kDefaultPort,
              "ZH1 光一个 [IPv6] = 默认端口",
              QStringLiteral("%1:%2").arg(v6NoPort.host).arg(v6NoPort.port));

        // 这一条是这一节最值钱的一条反面：裸的 IPv6 按"最后一个冒号"拆出来是主机 `::`、
        // 端口 `1` —— 一个看着完全合法、其实谁也不是的地址，而且报错会变成"这台服务器连
        // 不上"，真正的原因（这行地址少了方括号）一个字都不会出现。
        const ServerPing::Address bareV6 = ServerPing::splitAddress(QStringLiteral("::1"));
        check(!bareV6.valid, "ZH1 没加方括号的 IPv6 = 看不懂（不猜成主机 ::、端口 1）",
              QStringLiteral("拆成了「%1」:%2").arg(bareV6.host).arg(bareV6.port));

        check(!ServerPing::splitAddress(QStringLiteral("[::1")).valid,
              "ZH1 方括号没关上 = 看不懂");
        check(!ServerPing::splitAddress(QStringLiteral(":25565")).valid,
              "ZH1 只有端口没主机 = 看不懂");
        check(!ServerPing::splitAddress(QStringLiteral("example.com:65536")).valid,
              "ZH1 端口 65536 = 看不懂（上限是 65535）");
        check(!ServerPing::splitAddress(QStringLiteral("example.com:0")).valid,
              "ZH1 端口 0 = 看不懂（**不当成默认端口**）");
        check(!ServerPing::splitAddress(QStringLiteral("example.com:minecraft")).valid,
              "ZH1 端口不是数字 = 看不懂");
        check(!ServerPing::splitAddress(QString()).valid &&
                  !ServerPing::splitAddress(QStringLiteral("   ")).valid,
              "ZH1 空串 / 只有空白 = 看不懂");

        const ServerPing::Address maxPort = ServerPing::splitAddress(QStringLiteral("example.com:65535"));
        check(maxPort.valid && maxPort.port == 65535, "ZH1 65535 是合法的（边界这一头）");

        const ServerPing::Address trailingColon = ServerPing::splitAddress(QStringLiteral("example.com:"));
        check(trailingColon.valid && trailingColon.port == ServerPing::kDefaultPort,
              "ZH1 末尾一个光秃秃的冒号 = 没写端口（不是看不懂）",
              QStringLiteral("%1:%2").arg(trailingColon.host).arg(trailingColon.port));
    }

    // ---------------------------------------------------------------------
    section("ZH2. VarInt：协议里每一个数字的写法");
    // ---------------------------------------------------------------------

    {
        check(ServerPing::varIntBytes(0) == QByteArrayLiteral("\x00") &&
                  ServerPing::varIntBytes(127) == QByteArrayLiteral("\x7f"),
              "ZH2 0 和 127 都是一个字节");
        check(ServerPing::varIntBytes(128) == QByteArrayLiteral("\x80\x01"),
              "ZH2 128 是 0x80 0x01（一个字节放不下了）",
              ServerPing::varIntBytes(128).toHex(' '));
        check(ServerPing::varIntBytes(25565) == QByteArrayLiteral("\xdd\xc7\x01"),
              "ZH2 25565（默认端口那个数）是 DD C7 01",
              ServerPing::varIntBytes(25565).toHex(' '));
        // 负数：协议里我们唯一会发的负数是"我是什么版本"那个 -1（我不说），补码编出来是
        // 5 个字节 —— 少编一个字节的话服务器读到的就是别的数。
        check(ServerPing::varIntBytes(-1) == QByteArrayLiteral("\xff\xff\xff\xff\x0f"),
              "ZH2 -1 是 5 个字节（FF FF FF FF 0F）",
              ServerPing::varIntBytes(-1).toHex(' '));

        // 编了再读回来是同一个数 —— 负的也一样（协议里的 VarInt 就是 32 位补码）。这一条
        // 顺带把"5 个字节那个上限"从两头都压住了：2097151 正好 3 个字节、2097152 要 4 个。
        const int values[] = {0,     1,       127,    128,   25565,
                              2097151, 2097152, 2147483647, -1, -2147483648};
        bool allRoundTrip = true;
        QString firstBad;
        for (const int value : values) {
            const QByteArray bytes = ServerPing::varIntBytes(value);
            int offset = 0;
            int back = 12345;
            if (!ServerPing::readVarInt(bytes, &offset, &back) || back != value ||
                offset != bytes.size()) {
                allRoundTrip = false;
                if (firstBad.isEmpty()) {
                    firstBad = QStringLiteral("%1 变成 %2").arg(value).arg(back);
                }
            }
        }
        check(allRoundTrip, "ZH2 10 个数（含两头极端值）编了再读回来都是原来那个", firstBad);

        // 读不动的两种：**字节不够一个 VarInt**，和连着 5 个字节还带着"后面还有"那一位。
        // 两种都只是"现在读不了"，所以 offset 和 out 都不许动 —— 半推半就会让调用方拿着
        // 一个"读到一半的位置"去解下一个字段，那是最难查的一类错。
        const QByteArray partial = QByteArrayLiteral("\x80\x80");
        int offset = 0;
        int value = 12345;
        check(!ServerPing::readVarInt(partial, &offset, &value) && offset == 0 && value == 12345,
              "ZH2 半截 VarInt = 读不动，而且 offset 和 out 都不动");

        offset = 0;
        check(!ServerPing::readVarInt(QByteArrayLiteral("\x80\x80\x80\x80\x80\x80"), &offset, &value),
              "ZH2 连着 6 个 0x80 = 读不动（VarInt 最多 5 字节）");

        // 从中间读：包里每个字段都紧接在前一个后面，offset 是进出自。
        const QByteArray mid = QByteArrayLiteral("\xff") + ServerPing::varIntBytes(300);
        offset = 1;
        check(ServerPing::readVarInt(mid, &offset, &value) && value == 300 && offset == mid.size(),
              "ZH2 从 offset 处读，读完成功推到最后",
              QStringLiteral("值 %1、offset %2/%3").arg(value).arg(offset).arg(mid.size()));

        offset = 0;
        check(!ServerPing::readVarInt(mid, nullptr, &value) &&
                  !ServerPing::readVarInt(mid, &offset, nullptr),
              "ZH2 指针给 nullptr = 读不到（不是崩）");
    }

    // ---------------------------------------------------------------------
    section("ZH3. MOTD：三种 JSON 形态展平成一行，再把颜色码洗掉");
    // ---------------------------------------------------------------------

    {
        check(ServerPing::motdText(QJsonValue(QStringLiteral("一句纯文本"))) ==
                  QStringLiteral("一句纯文本"),
              "ZH3 description 就是一段字符串：原样");

        // 真机上最常见的形态：{text, extra:[…]}，而且 extra 里对象和字符串混着。
        QJsonObject mixed;
        mixed[QStringLiteral("text")] = QStringLiteral("前半");
        QJsonArray extra;
        QJsonObject tail;
        tail[QStringLiteral("text")] = QStringLiteral("后半");
        tail[QStringLiteral("color")] = QStringLiteral("red");
        extra.append(tail);
        extra.append(QStringLiteral("再来一段"));
        mixed[QStringLiteral("extra")] = extra;
        check(ServerPing::motdText(QJsonValue(mixed)) == QStringLiteral("前半后半再来一段"),
              "ZH3 {text, extra:[…]} 展平成一行（extra 里对象和字符串混着）",
              ServerPing::motdText(QJsonValue(mixed)));

        // extra 里还能再嵌 extra（真机上有这种）。
        QJsonObject innermost;
        innermost[QStringLiteral("text")] = QStringLiteral("里");
        QJsonObject middle;
        middle[QStringLiteral("text")] = QStringLiteral("中");
        middle[QStringLiteral("extra")] = QJsonArray{innermost};
        QJsonObject outermost;
        outermost[QStringLiteral("text")] = QStringLiteral("外");
        outermost[QStringLiteral("extra")] = QJsonArray{middle};
        check(ServerPing::motdText(QJsonValue(outermost)) == QStringLiteral("外中里"),
              "ZH3 extra 里嵌 extra 也一路递归下去");

        // 1.20.3 之后 description 也可能是数组。
        check(ServerPing::motdText(QJsonValue(QJsonArray{QStringLiteral("一"), QStringLiteral("二")})) ==
                  QStringLiteral("一二"),
              "ZH3 description 是数组（1.20.3+ 那种）也认");

        check(ServerPing::motdText(QJsonValue()) == QString() &&
                  ServerPing::motdText(QJsonValue(12)) == QString() &&
                  ServerPing::motdText(QJsonValue(QJsonObject())) == QString() &&
                  ServerPing::motdText(QJsonValue(QJsonObject{{QStringLiteral("color"),
                                                               QStringLiteral("red")}})) == QString(),
              "ZH3 没给 description / 给了个数字 / 空对象 / 只有颜色的对象 = 空串（不崩）");

        // 颜色码：`§` 是**两字符一对**。只丢 `§` 的话，屏幕上会留下一串孤零零的 a l r
        // —— 那正是"洗过了但没洗干净"的样子。
        const QString colored = QStringLiteral("§a欢迎 §l来到 §r这里");
        check(ServerPing::cleanMotd(colored) == QStringLiteral("欢迎 来到 这里"),
              "ZH3 §a / §l / §r 连着**后面那个字符**一起丢",
              ServerPing::cleanMotd(colored));
        check(ServerPing::cleanMotd(QStringLiteral("末尾一个§")) == QStringLiteral("末尾一个"),
              "ZH3 末尾孤零零一个 § 直接丢掉（不越界）");

        const QString multiline = QStringLiteral("  前面\n\n后面\t尾巴  ");
        check(ServerPing::cleanMotd(multiline) == QStringLiteral("前面 后面 尾巴"),
              "ZH3 换行/制表压成空格、连着几个空格收成一个、两头去掉",
              ServerPing::cleanMotd(multiline));
    }

    // ---------------------------------------------------------------------
    section("ZH4. 图标那串 data URL");
    // ---------------------------------------------------------------------

    QByteArray iconPng;
    {
        // 现造一张（不落盘，走 QBuffer）—— 要证的只是"这条路通"，去 meta/ 里挂一份反而绕。
        QImage source(64, 64, QImage::Format_ARGB32);
        source.fill(QColor(0x33, 0x66, 0x99));
        QBuffer buffer(&iconPng);
        buffer.open(QIODevice::WriteOnly);
        const bool saved = source.save(&buffer, "PNG");
        buffer.close();
        check(saved && iconPng.startsWith(QByteArrayLiteral("\x89PNG")),
              "ZH4 现造一张 64x64 的 PNG 当图标",
              QStringLiteral("%1 字节").arg(iconPng.size()));

        const QString base64 = QString::fromLatin1(iconPng.toBase64());
        check(ServerPing::decodeFavicon(QStringLiteral("data:image/png;base64,") + base64) == iconPng,
              "ZH4 data:image/png;base64,… 解出来和原来那张**逐字节一样**");

        check(ServerPing::decodeFavicon(QStringLiteral("data:image/jpeg;base64,") + base64).isEmpty() &&
                  ServerPing::decodeFavicon(QStringLiteral("https://example.com/icon.png")).isEmpty() &&
                  ServerPing::decodeFavicon(QStringLiteral("data:image/png;base64,")).isEmpty() &&
                  ServerPing::decodeFavicon(QString()).isEmpty(),
              "ZH4 别的形态一律回空（不猜）：jpeg 前缀 / 一条 http 地址 / 只有前缀 / 空串");
    }

    // ---------------------------------------------------------------------
    section("ZH5. 连不上的话怎么说（自己写的那张表）");
    // ---------------------------------------------------------------------

    {
        check(ServerPing::connectionErrorText(QAbstractSocket::ConnectionRefusedError)
                  .contains(QStringLiteral("没有回应")),
              "ZH5 连接被拒 = 「没有回应（对面没开，或者端口不对）」",
              ServerPing::connectionErrorText(QAbstractSocket::ConnectionRefusedError));
        check(ServerPing::connectionErrorText(QAbstractSocket::HostNotFoundError)
                  .contains(QStringLiteral("找不到")),
              "ZH5 域名解析不了 = 「找不到这台主机」",
              ServerPing::connectionErrorText(QAbstractSocket::HostNotFoundError));
        check(ServerPing::connectionErrorText(QAbstractSocket::SocketTimeoutError)
                  .contains(QStringLiteral("超时")) &&
                  ServerPing::connectionErrorText(QAbstractSocket::NetworkError)
                      .contains(QStringLiteral("超时")),
              "ZH5 超时和网络错误合一句");
        check(ServerPing::connectionErrorText(QAbstractSocket::RemoteHostClosedError)
                  .contains(QStringLiteral("断了")),
              "ZH5 对面挂了 = 「对面把连接断了」");
        check(ServerPing::connectionErrorText(QAbstractSocket::SocketAccessError)
                  .contains(QStringLiteral("防火墙")),
              "ZH5 本机不让连 = 「本机不让连（防火墙或者权限）」");
        check(ServerPing::connectionErrorText(QAbstractSocket::UnknownSocketError) ==
                  QStringLiteral("连不上"),
              "ZH5 认不出来的错兜到一句「连不上」");

        // 这一条钉的是"我们没有走到 Qt 的 errorString() 上"：那是 Qt 翻译文件里的英文
        // 句子，而我们的部署**不带**那些 .qm 文件（--no-translations），真机上会是一句
        // 英文 —— 用户看到的是"Connection refused"。
        const int codes[] = {QAbstractSocket::ConnectionRefusedError,
                             QAbstractSocket::HostNotFoundError,
                             QAbstractSocket::SocketTimeoutError,
                             QAbstractSocket::NetworkError,
                             QAbstractSocket::RemoteHostClosedError,
                             QAbstractSocket::SocketAccessError,
                             QAbstractSocket::UnknownSocketError};
        QString withLatin;
        for (const int code : codes) {
            const QString text = ServerPing::connectionErrorText(code);
            if (text.isEmpty()) {
                withLatin = QStringLiteral("空串");
                break;
            }
            for (const QChar ch : text) {
                if (ch.unicode() < 0x80 && ch.isLetter()) {
                    withLatin = text;
                    break;
                }
            }
            if (!withLatin.isEmpty()) {
                break;
            }
        }
        check(withLatin.isEmpty(), "ZH5 每一条都是中文（一个 ASCII 字母都没有）", withLatin);
    }

    // ---------------------------------------------------------------------
    section("ZH6. 真连一次：我们发的、服务器答的，逐字段核对");
    // ---------------------------------------------------------------------

    FakeStatusServer answer(FakeStatusServer::Answer);
    {
        // 一份"像真服务器答的" JSON：MOTD 是 {text, extra} 那种形态、带颜色码、带换行、
        // 带图标、带人数和版本名 —— 每一项都对应下面一条断言。
        QJsonObject motdText;
        motdText[QStringLiteral("text")] = QStringLiteral("§a欢迎 §l来到 ");
        QJsonArray extra;
        QJsonObject colored;
        colored[QStringLiteral("text")] = QStringLiteral("WTFML 服");
        colored[QStringLiteral("color")] = QStringLiteral("red");
        extra.append(colored);
        extra.append(QStringLiteral("\n第二行"));
        motdText[QStringLiteral("extra")] = extra;

        QJsonObject players;
        players[QStringLiteral("online")] = 12;
        players[QStringLiteral("max")] = 100;

        QJsonObject version;
        version[QStringLiteral("name")] = QStringLiteral("Paper 1.21.4");
        version[QStringLiteral("protocol")] = 769;

        QJsonObject root;
        root[QStringLiteral("description")] = motdText;
        root[QStringLiteral("players")] = players;
        root[QStringLiteral("version")] = version;
        root[QStringLiteral("favicon")] = QStringLiteral("data:image/png;base64,") +
                                           QString::fromLatin1(iconPng.toBase64());

        answer.json = QJsonDocument(root).toJson(QJsonDocument::Compact);
        answer.startAndWait();
        check(answer.listening && answer.port != 0, "ZH6 假服务器起来了",
              QStringLiteral("127.0.0.1:%1").arg(answer.port));

        QElapsedTimer wall;
        wall.start();
        const ServerPing::Status status =
            ServerPing::ping(QStringLiteral("127.0.0.1:%1").arg(answer.port));
        const qint64 wallMs = wall.elapsed();

        check(status.ok, "ZH6 这一趟**通了**", status.error);
        check(status.error.isEmpty(), "ZH6 通了的时候 error 是空串", status.error);
        check(status.latencyMs >= 0 && status.latencyMs <= wallMs,
              "ZH6 记下的耗时在 0 和这一趟真实耗时之间",
              QStringLiteral("记 %1 ms，外圈量到 %2 ms").arg(status.latencyMs).arg(wallMs));
        check(status.motd == QStringLiteral("欢迎 来到 WTFML 服 第二行"),
              "ZH6 MOTD：展平 + 洗完之后就是那两行字",
              QStringLiteral("「%1」").arg(status.motd));
        check(status.versionName == QStringLiteral("Paper 1.21.4"),
              "ZH6 服务器自报的版本名读出来了", status.versionName);
        check(status.playersOnline == 12 && status.playersMax == 100,
              "ZH6 人数 12/100",
              QStringLiteral("%1/%2").arg(status.playersOnline).arg(status.playersMax));
        check(status.iconPng == iconPng, "ZH6 图标逐字节一样",
              QStringLiteral("%1 字节").arg(status.iconPng.size()));
        QImage iconImage;
        const bool iconDecoded = iconImage.loadFromData(status.iconPng);
        check(iconDecoded && iconImage.size() == QSize(64, 64),
              "ZH6 那串字节真解得成一张 64x64 的图（界面那一层拿到手就是这么用的）",
              QStringLiteral("%1x%2").arg(iconImage.width()).arg(iconImage.height()));

        waitFakeServer(answer);
        check(answer.connections == 1, "ZH6 服务器那边正好收到一个连接",
              QStringLiteral("%1 个").arg(answer.connections));

        // ---- 发出去的那两个包，按字段拆开核对 ----
        const QByteArray seen = answer.seen;
        int pos = 0;
        int packetLength = 0;
        bool shapeOk = ServerPing::readVarInt(seen, &pos, &packetLength) && packetLength > 0;
        const int bodyStart = pos;
        int packetId = -1;
        int protocol = 0;
        QString hostInHandshake;
        int portInHandshake = -1;
        int nextState = -1;
        if (shapeOk) {
            shapeOk = ServerPing::readVarInt(seen, &pos, &packetId) && packetId == 0x00;
        }
        if (shapeOk) {
            shapeOk = ServerPing::readVarInt(seen, &pos, &protocol);
        }
        if (shapeOk) {
            int hostLength = 0;
            shapeOk = ServerPing::readVarInt(seen, &pos, &hostLength) && hostLength >= 0 &&
                      pos + hostLength <= seen.size();
            if (shapeOk) {
                hostInHandshake = QString::fromUtf8(seen.mid(pos, hostLength));
                pos += hostLength;
            }
        }
        if (shapeOk) {
            shapeOk = pos + 2 <= seen.size();
            if (shapeOk) {
                portInHandshake = (static_cast<unsigned char>(seen.at(pos)) << 8) |
                                  static_cast<unsigned char>(seen.at(pos + 1));
                pos += 2;
            }
        }
        if (shapeOk) {
            shapeOk = ServerPing::readVarInt(seen, &pos, &nextState);
        }
        check(shapeOk, "ZH6 握手包拆得开（长度 / id 0x00 / 版本 / 主机 / 端口 / 下一状态）",
              QStringLiteral("收到 %1 字节").arg(seen.size()));
        check(pos == bodyStart + packetLength,
              "ZH6 握手包自己那个长度 = 它正文的真实长度",
              QStringLiteral("说 %1，实际 %2").arg(packetLength).arg(pos - bodyStart));
        check(protocol == -1,
              "ZH6 协议版本发的是 -1（我不说，让它照自己的版本答）",
              QString::number(protocol));
        check(hostInHandshake == QStringLiteral("127.0.0.1"),
              "ZH6 握手里的主机名就是我们要连的那个", hostInHandshake);
        // 端口在协议里是**大端 uint16**，不是 VarInt —— 写成 VarInt 的话 25565 会变成
        // 三个字节，服务器读这个字段时把后面那些字节也吃进去，整个包就错位了。
        check(portInHandshake == answer.port, "ZH6 端口是大端 uint16（不是 VarInt）",
              QStringLiteral("收到 %1，期望 %2").arg(portInHandshake).arg(answer.port));
        check(nextState == 1,
              "ZH6 下一状态是 1（status）—— 写成 2 就是「我要进游戏」，服务器会等一个永远"
              "不来的登录包，一个字节都不答",
              QString::number(nextState));

        const int requestStart = pos;
        int requestLength = 0;
        int requestId = -1;
        const bool requestOk = ServerPing::readVarInt(seen, &pos, &requestLength) &&
                               ServerPing::readVarInt(seen, &pos, &requestId) &&
                               requestLength == 1 && requestId == 0x00;
        check(requestOk, "ZH6 紧跟着的是状态请求（长度 1、id 0x00、空正文）",
              QStringLiteral("长度 %1、id %2").arg(requestLength).arg(requestId));
        check(pos == seen.size(),
              "ZH6 两个包之后我们**一个字节都没多发**（只读，不往服务器写别的）",
              QStringLiteral("收到 %1 字节，用完 %2（状态请求从 %3 开始）")
                  .arg(seen.size())
                  .arg(pos)
                  .arg(requestStart));
    }

    // ---------------------------------------------------------------------
    section("ZH7. 连不上的样子（端口没人听 / 地址看不懂）");
    // ---------------------------------------------------------------------

    {
        // 拿一个**刚被放开**的端口（listen 一下就关）：本机上连它一定被拒。
        quint16 freePort = 0;
        {
            QTcpServer probe;
            if (probe.listen(QHostAddress::LocalHost, 0)) {
                freePort = probe.serverPort();
                probe.close();
            }
        }
        check(freePort != 0, "ZH7 拿到一个刚放开的端口", QString::number(freePort));

        QElapsedTimer refusedWall;
        refusedWall.start();
        const ServerPing::Status refused =
            ServerPing::ping(QStringLiteral("127.0.0.1:%1").arg(freePort));
        const qint64 refusedMs = refusedWall.elapsed();

        check(!refused.ok, "ZH7 对面没开 = 没通",
              QStringLiteral("「%1」，用了 %2 ms").arg(refused.error).arg(refusedMs));
        // 这一条**只**钉"报的是一句人话"：这台机器上连一个没人听的端口回来的是「超时」而
        // 不是「没有回应」（连接请求像是被本机的某个过滤器吃掉而不是被回了一个 RST，所以
        // 等满了那 4 秒）。两句都是人话，产品这一侧要保证的是"不是 ok、也不是一句英文"；
        // 具体哪个 socket 错误翻哪句话，由 ZH5 那张表逐条钉。写成非「没有回应」不可的话，
        // 换一台机器跑就是红的，而那不是回归。
        check(refused.error.contains(QStringLiteral("没有回应")) ||
                  refused.error.contains(QStringLiteral("超时")) ||
                  refused.error.contains(QStringLiteral("断了")),
              "ZH7 报出来的是一句人话（没有回应 / 超时 / 对面把连接断了）",
              QStringLiteral("「%1」").arg(refused.error));
        // ★ `timedOut` 那一位和那句话**说的是同一件事**（界面上就是照这一位把那一格缩成
        //   「超时」两个字的，见 ServerRowStatus::timedOut）。这一台机器上"连一个刚放开的
        //   端口"未必报超时（见上面那段 NOTE），所以这里钉的是**两者一致**，不是"必须报超时"。
        check(refused.timedOut == refused.error.contains(QStringLiteral("超时")),
              "★ ZH7 `timedOut` 和那句话说的是同一件事（界面上照着它缩成「超时」）",
              QStringLiteral("timedOut=%1、话是「%2」")
                  .arg(refused.timedOut ? QStringLiteral("真") : QStringLiteral("假"),
                       refused.error));
        check(refused.latencyMs < 0 && refused.motd.isEmpty() && refused.iconPng.isEmpty() &&
                  refused.playersOnline == -1,
              "ZH7 没通的时候：耗时 -1、MOTD 和图标都是空、人数还是 -1（不是半份结果）");

        // 地址看不懂那一档**一个字节都不往网上发**：不这么写的话，用户把地址打错了会得到
        // "这台服务器连不上"，而真正的原因（这行地址本身是坏的）一个字都看不见。
        const ServerPing::Status broken = ServerPing::ping(QStringLiteral("127.0.0.1:0"));
        check(!broken.ok && broken.error.contains(QStringLiteral("看不懂")),
              "ZH7 地址看不懂 = 直接说地址有问题", broken.error);
    }

    // ---------------------------------------------------------------------
    section("ZH8. 连上了但没人回答：超时那一档（顺带量一次那个旋钮）");
    // ---------------------------------------------------------------------

    {
        // 那个旋钮的下限：0 会让每一次 waitFor* 立刻返回，"连不上"和"连上了但还没答"就
        // 分不开了，所以钳到 1。
        const int saved = ServerPing::timeoutMs();
        ServerPing::setTimeoutMs(0);
        check(ServerPing::timeoutMs() == 1, "ZH8 超时设成 0 会被钳到 1 毫秒",
              QString::number(ServerPing::timeoutMs()));

        FakeStatusServer silent(FakeStatusServer::Silent);
        silent.startAndWait();
        check(silent.listening, "ZH8 那台「收下不回」的服务器起来了",
              QStringLiteral("127.0.0.1:%1").arg(silent.port));

        ServerPing::setTimeoutMs(200);
        QElapsedTimer wall;
        wall.start();
        const ServerPing::Status status =
            ServerPing::ping(QStringLiteral("127.0.0.1:%1").arg(silent.port));
        const qint64 wallMs = wall.elapsed();
        ServerPing::setTimeoutMs(saved);

        // 这一档必须说成"连上了但它没答话"，**不能**说成"网络不通"：连接明明建起来了，
        // 说网络不通会把人往查网线的方向带。Qt 在 waitForReadyRead 超时时也会把 error()
        // 设成 SocketTimeoutError，所以产品那一侧是**按走到哪一步**分的话术，不是照 error()
        // 翻表 —— 这条断言钉的就是那个区分。
        check(!status.ok && status.error.contains(QStringLiteral("超时")) &&
                  status.error.contains(QStringLiteral("没有回答")),
              "ZH8 没人回答 = 「超时（连上了，但服务器没有回答）」",
              QStringLiteral("「%1」").arg(status.error));
        // ★ 界面上那一格对超时只写两个字（用户 2026-09-27：「超时的只写超时」），判据是
        //   这一位 —— 所以它必须是**真的判定出来的**，而不是界面上拿 error 那句话的前缀猜的。
        //   上面那一句留着全话、这一位是"缩成两个字"的依据，两条缺一不可。
        check(status.timedOut,
              "★ ZH8 这一档的 `timedOut` 是**真**的（界面上据此只写「超时」两个字）");
        check(silent.connections == 1,
              "ZH8 对面**确实收到了这个连接**（不是连都没连上）",
              QStringLiteral("%1 个连接").arg(silent.connections));
        check(!silent.seen.isEmpty(),
              "ZH8 两个包在超时之前就发出去了（不是压根没发）",
              QStringLiteral("%1 字节").arg(silent.seen.size()));
        // NOTE: 下界**故意不是 200**。要钉的是"这个旋钮真的管用"（没等满默认那 4 秒、
        //       也不是压根没等），而 Windows 上 `waitForReadyRead(200)` 回来的墙钟时间
        //       **就是会少一两毫秒**（计时器粒度 + 那句超时本身算在等待里面）——
        //       2026-09-27 实测拿到过 199 ms，照着 `>= 200` 写就是一条间歇性假红。
        //       真要坏（旋钮没接上）的话量到的是个位数，180 这条线照样抓得住。
        check(wallMs >= 180 && wallMs < 3000,
              "ZH8 200 毫秒那个旋钮真的管用（没等满默认的 4 秒、也不是压根没等）",
              QStringLiteral("实际等了 %1 ms").arg(wallMs));
        check(ServerPing::timeoutMs() == saved, "ZH8 旋钮换回来了（后面那些节用的是默认值）",
              QStringLiteral("%1 ms").arg(ServerPing::timeoutMs()));

        waitFakeServer(silent);
    }

    // ---------------------------------------------------------------------
    section("ZH9. 服务器答得不对的四种样子");
    // ---------------------------------------------------------------------

    {
        FakeStatusServer garbage(FakeStatusServer::Garbage);
        garbage.json = QByteArrayLiteral("<html>502 Bad Gateway</html>");
        garbage.startAndWait();
        const ServerPing::Status bad =
            ServerPing::ping(QStringLiteral("127.0.0.1:%1").arg(garbage.port));
        check(!bad.ok && bad.error.contains(QStringLiteral("不是一段 JSON")),
              "ZH9 正文不是 JSON（比如中间隔了个网关）", QStringLiteral("「%1」").arg(bad.error));
        waitFakeServer(garbage);

        // 长度前缀报一个天文数字：**看到这个数就该放弃**，不是等一堆永远不来的字节。
        FakeStatusServer huge(FakeStatusServer::HugeLength);
        huge.startAndWait();
        QElapsedTimer hugeWall;
        hugeWall.start();
        const ServerPing::Status oversized =
            ServerPing::ping(QStringLiteral("127.0.0.1:%1").arg(huge.port));
        const qint64 hugeMs = hugeWall.elapsed();
        check(!oversized.ok && oversized.error.contains(QStringLiteral("长度不对")),
              "ZH9 长度前缀说这个包有 4 MiB = 「长度不对」",
              QStringLiteral("「%1」").arg(oversized.error));
        check(hugeMs < 1500,
              "ZH9 而且是**当场**放弃的（没有等它 4 秒超时）",
              QStringLiteral("用了 %1 ms").arg(hugeMs));
        waitFakeServer(huge);

        FakeStatusServer notStatus(FakeStatusServer::NotStatus);
        notStatus.json = QByteArrayLiteral("{}");
        notStatus.startAndWait();
        const ServerPing::Status wrongId =
            ServerPing::ping(QStringLiteral("127.0.0.1:%1").arg(notStatus.port));
        check(!wrongId.ok && wrongId.error.contains(QStringLiteral("不是状态包")),
              "ZH9 包 id 不是 0x00 = 「不是状态包」",
              QStringLiteral("「%1」").arg(wrongId.error));
        waitFakeServer(notStatus);

        FakeStatusServer shortBody(FakeStatusServer::ShortBody);
        shortBody.json = QByteArrayLiteral("{}");
        shortBody.startAndWait();
        const ServerPing::Status truncated =
            ServerPing::ping(QStringLiteral("127.0.0.1:%1").arg(shortBody.port));
        check(!truncated.ok && truncated.error.contains(QStringLiteral("正文长度不对")),
              "ZH9 包是收全了，但里面说正文有 9999 字节 = 「正文长度不对」",
              QStringLiteral("「%1」").arg(truncated.error));
        waitFakeServer(shortBody);
    }

    // ---------------------------------------------------------------------
    section("ZH10. 几台一起问（并发）：三台假服务器互相等，串行必红");
    // ---------------------------------------------------------------------
    //
    // 【这一节要证明的事】用户 2026-09-27：「能多线程一起 ping 吗，一个个 ping 效率有点
    // 低」。判据不能是"量一遍耗时"——那是**环境说了算**的（本机连一个没人听的回环端口
    // 要等满整个超时，ZH7 实测过），机器一忙就会假红。所以这里换成一个**只能靠并发通过**
    // 的构造：三台假服务器**互相等**，每一台都要等到另外两台也连上来才回话。
    //
    //   并发跑（产品的样子）：三台几乎同时连上 → 闸门一开 → 三台一起回话 → 三条都通；
    //   串行跑（改回去的样子）：第 1 台等到闸门超时、一个字都不回 → 断在它这儿；后面两台
    //                              根本没人来连。于是这一节**必红**，一点都不含糊。
    //
    // 顺带把"结果按 index 认人"也钉住：并发之后 oneFinished 回来的次序**不再等于** 0、1、2，
    // 接的人要是按"先后"去推，屏幕上会出现"这台的 MOTD 挂在那一台底下"。每台把自己的号
    // 写在 MOTD 里，于是张冠李戴是一条能红的断言。
    {
        const int savedTimeout = ServerPing::timeoutMs();
        check(ServerPing::kMaxConcurrentPings > 1,
              "★ ZH10 并发上限不止 1（不然下面那三条是白写的）",
              QStringLiteral("kMaxConcurrentPings=%1").arg(ServerPing::kMaxConcurrentPings));

        GateBarrier gate(3);
        QList<GatedStatusServer *> servers;
        QStringList addresses;
        for (int i = 0; i < 3; ++i) {
            auto *server = new GatedStatusServer(&gate, i);
            server->startAndWait();
            servers.append(server);
            addresses.append(QStringLiteral("127.0.0.1:%1").arg(server->port));
        }
        check(servers.at(0)->listening && servers.at(1)->listening && servers.at(2)->listening,
              "ZH10 三台假服务器都起来了");

        QHash<int, ServerPing::Status> results;
        bool finished = false;
        ServerPing::Pinger pinger;
        // 两个信号都是**从工作线程发出来的**，所以下面必须转主线程的事件循环才收得到
        // ——这一步顺带也就把"跨线程排队投递真的通了"验了（Status 没登记元类型的话，
        // 这里会一条都收不到，而那是**静默**的）。
        //
        // ★ 这两个 connect **必须带第三个参数那个上下文对象**（这里就是 `&pinger`）。
        //   不带的话走的是那个三参数的 functor 重载，它内部写死的是 **Qt::DirectConnection**
        //   —— 于是 lambda 会在**工作线程**上跑，往主线程这两个变量上写。那样写出来的
        //   测试是**碰运气**绿的：主线程那个 while 有时看得见、有时看不见（这里真踩到过：
        //   同一份代码一次全绿、下一次这一条红）。带上上下文之后按 AutoConnection 走，
        //   发送方在工作线程、接收方在主线程 ⇒ 排队投递，正好也就是产品那边走的那条路。
        QObject::connect(&pinger, &ServerPing::Pinger::oneFinished, &pinger,
                         [&results](int index, const ServerPing::Status &status) {
                             results.insert(index, status);
                         });
        // 收尾那一发到的时候**手上已经有几条**：这是"allFinished 真的是最后一条线程发的"
        // 那件事的判据（见下面那条 ★★）。要抓的那个方向写反是 `QAtomicInt::deref()` ——
        // 它等价于 `--i != 0`（减完**还有人在**就回真），于是"最先收摊的那条线程"抢先把
        // allFinished 发出去，接的人当这一趟完了：屏幕上只有最先回来的那一台有结果。
        int arrivedAtFinish = -1;
        int finishCount = 0;
        QObject::connect(&pinger, &ServerPing::Pinger::allFinished, &pinger,
                         [&finished, &results, &arrivedAtFinish, &finishCount]() {
                             arrivedAtFinish = results.size();
                             ++finishCount;
                             finished = true;
                         });

        QElapsedTimer clock;
        clock.start();
        pinger.start(addresses);
        while (!finished && clock.elapsed() < 20000) {
            QCoreApplication::processEvents(QEventLoop::AllEvents, 50);
        }

        check(finished, "★ ZH10 这一趟跑完了（allFinished 从工作线程投递到了主线程）");
        check(results.size() == 3, "ZH10 三台各回了一条结果",
              QStringLiteral("%1 条").arg(results.size()));

        QStringList failed;
        for (int i = 0; i < 3; ++i) {
            const ServerPing::Status status = results.value(i);
            if (!status.ok) {
                failed.append(QStringLiteral("第 %1 台：%2").arg(i).arg(status.error));
            }
        }
        check(failed.isEmpty(),
              "★★ ZH10 三台是**同时在问**的：每一台都拿回了答案"
              "（这三台要等到大家一起连上来才回话 —— 串行跑的话第 1 台永远等不来第 2 台，"
              "它一个字都不会回，这一条必红）",
              failed.join(QStringLiteral(" / ")));

        QStringList mismatched;
        for (int i = 0; i < 3; ++i) {
            const QString expected = QStringLiteral("gate-%1").arg(i);
            if (results.value(i).motd != expected) {
                mismatched.append(QStringLiteral("第 %1 条收到「%2」")
                                      .arg(i)
                                      .arg(results.value(i).motd));
            }
        }
        check(mismatched.isEmpty(),
              "★★ ZH10 而且**按 index 认人是对的**：第 i 条拿回的正是第 i 台那句话"
              "（并发之后回来的次序不再等于下标次序，按先后去推就会张冠李戴）",
              mismatched.join(QStringLiteral(" / ")));
        check(arrivedAtFinish == 3,
              "★★ ZH10 收尾那一发是**最后一条线程**发的：allFinished 到的时候三台的答复都"
              "已经在手上了（那一位的意思是「这一趟完了」，早发出去的话接的人以为跑完了 ——"
              " 症状是屏幕上只有最先回来的那一台有结果，其余几台永远停在「还没测」，而按钮"
              "已经变回「测速」、看着像跑完了）",
              QStringLiteral("allFinished 到的时候手上是 %1 条").arg(arrivedAtFinish));
        check(finishCount == 1,
              "★ ZH10 而 allFinished 只发一次（几条线程各发一次的话，接的人会以为跑完好几趟"
              " —— 这一次是三条线程抢着收尾）",
              QStringLiteral("发了 %1 次").arg(finishCount));
        check(gate.arrived() == 3, "ZH10 三台都真的报到了（字面意思上的「一起」）",
              QStringLiteral("到了 %1 台").arg(gate.arrived()));

        for (GatedStatusServer *server : servers) {
            if (!server->wait(8000)) {
                check(false, "ZH10 假服务器那条线程没停下来（最多等 8 秒）");
                server->terminate();
                server->wait(3000);
            }
            delete server;
        }
        ServerPing::setTimeoutMs(savedTimeout);
    }
}

// ---------------------------------------------------------------------------
// ZK 节用的那几支：**手搓 NBT 字节**。
//
// 故意不借 `NbtTree::serialize` 造夹具 —— 借产品自己的序列化器造夹具，验的就变成"它自己
// 和自己一致"。手搓的这一份同时就是"游戏写出来的那份形状"的样本，字段顺序照真机上那几份
// `servers.dat`（`hidden` → `ip` → `name` → `icon`）。
// ---------------------------------------------------------------------------
namespace {

/// NBT 的一格：类型 + 名字（u16 长度 + UTF-8）+ 载荷。
QByteArray nbtTag(quint8 type, const QByteArray &name, const QByteArray &payload) {
    QByteArray out;
    out.append(static_cast<char>(type));
    out.append(static_cast<char>((name.size() >> 8) & 0xFF));
    out.append(static_cast<char>(name.size() & 0xFF));
    out.append(name);
    out.append(payload);
    return out;
}

/// TAG_String 的载荷：u16 长度 + UTF-8 字节。
QByteArray nbtString(const QString &text) {
    const QByteArray utf8 = text.toUtf8();
    QByteArray out;
    out.append(static_cast<char>((utf8.size() >> 8) & 0xFF));
    out.append(static_cast<char>(utf8.size() & 0xFF));
    out.append(utf8);
    return out;
}

/// TAG_Int 的载荷（大端）。
QByteArray nbtInt(qint32 value) {
    QByteArray out;
    out.append(static_cast<char>((value >> 24) & 0xFF));
    out.append(static_cast<char>((value >> 16) & 0xFF));
    out.append(static_cast<char>((value >> 8) & 0xFF));
    out.append(static_cast<char>(value & 0xFF));
    return out;
}

/// 一个复合标签的载荷：里面那几格 + 结尾的 TAG_End。
QByteArray nbtCompoundBody(const QList<QByteArray> &tags) {
    QByteArray out;
    for (const QByteArray &tag : tags) {
        out.append(tag);
    }
    out.append('\0');
    return out;
}

/// 一格 `TAG_List<TAG_Compound>` 的载荷 —— 表里每一条**不带名字也不带类型**（NBT 的规矩，
/// 类型和条数写在表头）。
QByteArray nbtServerList(const QList<QByteArray> &items) {
    QByteArray out;
    out.append('\x0a');  // 元素类型 = TAG_Compound
    out.append(nbtInt(static_cast<qint32>(items.size())));
    for (const QByteArray &item : items) {
        out.append(item);
    }
    return out;
}

/// 一条服务器。`hasName` / `hasIp` 为假 = 盘上根本没有那一格（1.12.2 那种老 fixture 里就
/// 没有 `name`；没有 `ip` 的那一条则**根本不会出现在界面上**，见 ZK7）。
struct NbtServerItem {
    QString name;
    QString ip;
    bool hasName = true;
    bool hasIp = true;
    bool hidden = false;
    bool hasHidden = false;
    QString icon;
};

QByteArray nbtServerItem(const NbtServerItem &item) {
    QList<QByteArray> tags;
    if (item.hasHidden) {
        tags.append(nbtTag(0x01, QByteArrayLiteral("hidden"),
                           QByteArray(1, static_cast<char>(item.hidden ? 1 : 0))));
    }
    if (item.hasIp) {
        tags.append(nbtTag(0x08, QByteArrayLiteral("ip"), nbtString(item.ip)));
    }
    if (item.hasName) {
        tags.append(nbtTag(0x08, QByteArrayLiteral("name"), nbtString(item.name)));
    }
    if (!item.icon.isEmpty()) {
        tags.append(nbtTag(0x08, QByteArrayLiteral("icon"), nbtString(item.icon)));
    }
    return nbtCompoundBody(tags);
}

/// 一整份 `servers.dat`：**无名**根复合标签 → 一格 `servers`。
QByteArray nbtServersDat(const QList<NbtServerItem> &items) {
    QList<QByteArray> encoded;
    for (const NbtServerItem &item : items) {
        encoded.append(nbtServerItem(item));
    }
    return nbtTag(0x0A, QByteArray(),
                  nbtCompoundBody({nbtTag(0x09, QByteArrayLiteral("servers"),
                                          nbtServerList(encoded))}));
}

bool writeBytesAt(const QString &path, const QByteArray &bytes) {
    QFile file(path);
    if (!file.open(QIODevice::WriteOnly)) {
        return false;
    }
    return file.write(bytes) == bytes.size();
}

QByteArray readBytesAt(const QString &path) {
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
        return QByteArray();
    }
    return file.readAll();
}

/// 按名字取一格字符串（不在 / 不是字符串 → 空串）。ZK7 / ZK8 要直接看盘上那棵树。
QString nbtFieldText(const NbtTree::Node &compound, const QString &name) {
    const NbtTree::Node *node = NbtTree::field(compound, name);
    return (node != nullptr && node->type == NbtTree::Type::String) ? node->text : QString();
}

/// 一个复合标签里那几格的名字，按**盘上的顺序**。
QStringList nbtFieldNames(const NbtTree::Node &compound) {
    QStringList names;
    for (const NbtTree::Field &field : compound.fields) {
        names.append(field.first);
    }
    return names;
}

}  // namespace

// ---------------------------------------------------------------------------
// ZK 节：`servers.dat` 的写侧（`ServerListFile` 的**改 / 加 / 删**三个入口）。
//
// 用户 2026-10-10 原话：「在服务器列表那里做一个编辑地址和名称的功能」。读那一半仍旧走
// `NbtUtil`（只读那条设计决定一个字没松），这一节钉的是**写**。
//
// ZK12 往后是同一页的另两件事（用户原话：「编辑要能改名字改地址以及删除，服务器那个页面里
// 放一个添加服务器的按钮，允许添加」）：加（`addEntry`）和删（`removeEntry`）。三个入口
// **共用同一个开头**（`loadServers()` + `findEntryIndex()`），所以这里钉的很多条其实是在
// 钉那个开头 —— 那正是"认不出就不写"只有一处实现的好处。
//
// 最值钱的一条是 ★「**认的是值不是下标**」：`NbtUtil::readServerList()` 会跳过没有 `ip` 的
// 元素，于是"界面上第 N 行"和"盘上第 N 个元素"不是一回事 —— 照下标去改就是**改错行**，而且
// 改完在界面上看不出来（名字和地址都还是"合法"的，只是长在了别人身上）。所以夹具里故意把
// 一条没有 `ip` 的塞在最前面，改完回盘上逐格看是谁被改了。
//
// 另一半是「**拒写就得是一个字节都不动**」：每一条拒写的路都当场比对整份字节。
// ---------------------------------------------------------------------------
static void runServerListEditTests() {
    QTemporaryDir dir;
    check(dir.isValid(), "ZK0 建得出一个临时目录来摆夹具");
    if (!dir.isValid()) {
        return;
    }
    const QString datPath = dir.filePath(QStringLiteral("servers.dat"));

    // 夹具三条：第一条是"游戏真写出来的那个形状"（hidden/ip/name/icon 四格全在）；第二条
    // 只有 name + ip；第三条**没有 name**（1.12.2 那种老 fixture）。
    const QList<NbtServerItem> fixture{
        NbtServerItem{QStringLiteral("A服"), QStringLiteral("a.example.com:25565"), true, true, true,
                      true, QStringLiteral("iVBORw0KGgo=")},
        NbtServerItem{QStringLiteral("B服"), QStringLiteral("b.example.com"), true, true, false,
                      false, QString()},
        NbtServerItem{QString(), QStringLiteral("c.example.com"), false, true, false, false,
                      QString()},
    };
    QList<NbtServerItem> current = fixture;

    check(writeBytesAt(datPath, nbtServersDat(fixture)), "ZK0 夹具落盘了");

    // ---------------------------------------------------------------------
    section("ZK1. 先证明夹具是「游戏会写的那种文件」");
    // ---------------------------------------------------------------------
    {
        QList<NbtUtil::ServerEntry> rows;
        QString problem;
        const NbtUtil::Status status = ServerListFile::read(datPath, &rows, &problem);
        check(status == NbtUtil::Status::Ok && rows.size() == 3,
              "ZK1 三条都读出来了（夹具是合法的 servers.dat）",
              QStringLiteral("status=%1 rows=%2 %3")
                  .arg(static_cast<int>(status))
                  .arg(rows.size())
                  .arg(problem));
        check(rows.size() == 3 && rows.at(0).name == QStringLiteral("A服") &&
                  rows.at(0).address == QStringLiteral("a.example.com:25565") &&
                  rows.at(1).name == QStringLiteral("B服") &&
                  rows.at(2).name.isEmpty() &&
                  rows.at(2).address == QStringLiteral("c.example.com"),
              "ZK1 名字 / 地址逐条对得上（第三条没有 name ⇒ 空串）");
    }

    // ---------------------------------------------------------------------
    section("ZK2. 改一条：成功，而且没碰的地方一个字节都不变");
    // ---------------------------------------------------------------------
    {
        QString problem;
        const bool ok = ServerListFile::updateEntry(datPath, QStringLiteral("A服"),
                                                    QStringLiteral("a.example.com:25565"),
                                                    QStringLiteral("新名字"),
                                                    QStringLiteral("new.example.com"), &problem);
        check(ok, "ZK2 改名 + 改地址成功", problem);

        current[0].name = QStringLiteral("新名字");
        current[0].ip = QStringLiteral("new.example.com");
        // 逐字节比一把：只有那两格的值变了 —— `hidden` 还是 Byte 0、`icon` 还是那一串、
        // 字段顺序一格都没动。这就是"整棵树原样写回去"那句话在盘上的样子。
        check(readBytesAt(datPath) == nbtServersDat(current),
              "ZK2 写回去的字节 = 只把那两格换掉的期望值（别的逐字节不变）");

        QList<NbtUtil::ServerEntry> rows;
        ServerListFile::read(datPath, &rows, nullptr);
        check(rows.size() == 3 && rows.at(0).name == QStringLiteral("新名字") &&
                  rows.at(0).address == QStringLiteral("new.example.com"),
              "ZK2 读回来就是改完的样子");
    }

    // ---------------------------------------------------------------------
    section("ZK3. 名字对不上 ⇒ 退一步按地址认");
    // ---------------------------------------------------------------------
    {
        QString problem;
        const bool ok = ServerListFile::updateEntry(datPath, QStringLiteral("B服改成别的了"),
                                                    QStringLiteral("b.example.com"),
                                                    QStringLiteral("B2"),
                                                    QStringLiteral("b.example.com"), &problem);
        check(ok, "ZK3 名字没对上、但地址在盘上只有一条 ⇒ 认那一条", problem);
        current[1].name = QStringLiteral("B2");

        QList<NbtUtil::ServerEntry> rows;
        ServerListFile::read(datPath, &rows, nullptr);
        check(rows.size() > 1 && rows.at(1).name == QStringLiteral("B2"),
              "ZK3 换掉的是那一条的名字",
              rows.size() > 1 ? rows.at(1).name : QStringLiteral("<条数不对>"));
        check(readBytesAt(datPath) == nbtServersDat(current), "ZK3 同样只有那两格变了");
    }

    // ---------------------------------------------------------------------
    section("ZK4 / ZK5. 拒写的两条：找不到那一条 / 新地址是空的");
    // ---------------------------------------------------------------------
    {
        const QByteArray before = readBytesAt(datPath);
        QString problem;
        const bool notFound = ServerListFile::updateEntry(
            datPath, QStringLiteral("谁"), QStringLiteral("nope.example.com"),
            QStringLiteral("算了"), QStringLiteral("nope2.example.com"), &problem);
        check(!notFound && !problem.isEmpty(), "ZK4 地址在盘上找不到 ⇒ 拒绝，并给一句话", problem);
        check(readBytesAt(datPath) == before, "ZK4 拒写之后盘上逐字节还是原来那份");

        problem.clear();
        const bool emptyAddress = ServerListFile::updateEntry(
            datPath, QStringLiteral("B2"), QStringLiteral("b.example.com"), QStringLiteral("B2"),
            QStringLiteral("   "), &problem);
        check(!emptyAddress && !problem.isEmpty(), "ZK5 地址空 ⇒ 拒绝（地址是这一条唯一的实质内容）",
              problem);
        check(readBytesAt(datPath) == before, "ZK5 拒写之后盘上逐字节还是原来那份");
    }

    // ---------------------------------------------------------------------
    section("ZK6. 同一个地址出现两条、名字又没对上 ⇒ 认不准，不猜");
    // ---------------------------------------------------------------------
    {
        const QByteArray dup = nbtServersDat({
            NbtServerItem{QStringLiteral("一"), QStringLiteral("dup.example.com"), true, true,
                          false, false, QString()},
            NbtServerItem{QStringLiteral("二"), QStringLiteral("dup.example.com"), true, true,
                          false, false, QString()},
        });
        check(writeBytesAt(datPath, dup), "ZK6 两条同地址的夹具落盘了");

        QString problem;
        const bool ok = ServerListFile::updateEntry(datPath, QStringLiteral("对不上的名字"),
                                                    QStringLiteral("dup.example.com"),
                                                    QStringLiteral("改"),
                                                    QStringLiteral("dup.example.com"), &problem);
        check(!ok && problem.contains(QStringLiteral("2")),
              "ZK6 地址重了 2 次、名字又没对上 ⇒ 拒绝，并说清是几次", problem);
        check(readBytesAt(datPath) == dup, "ZK6 拒写之后盘上逐字节还是那两条");

        check(writeBytesAt(datPath, nbtServersDat(current)), "ZK6 把夹具换回来");
    }

    // ---------------------------------------------------------------------
    section("ZK7. ★ 认的是值不是下标：没有 ip 的那一条排在最前面");
    // ---------------------------------------------------------------------
    {
        const QList<NbtServerItem> withGhost{
            NbtServerItem{QStringLiteral("我在界面上一行都不占"), QString(), true, false, false,
                          false, QString()},  // 没有 ip ⇒ readServerList 跳过它
            NbtServerItem{QStringLiteral("真服"), QStringLiteral("real.example.com"), true, true,
                          false, false, QString()},
            NbtServerItem{QStringLiteral("尾"), QStringLiteral("tail.example.com"), true, true,
                          false, false, QString()},
        };
        check(writeBytesAt(datPath, nbtServersDat(withGhost)), "ZK7 带一条没有 ip 的夹具落盘了");

        QList<NbtUtil::ServerEntry> rows;
        ServerListFile::read(datPath, &rows, nullptr);
        check(rows.size() == 2 && rows.at(0).name == QStringLiteral("真服"),
              "ZK7 界面上只有两行（没有 ip 的那条不出现）", QString::number(rows.size()));

        QString problem;
        // 界面上第 0 行是「真服」，而**盘上第 0 个元素是那条没有 ip 的** —— 照下标改就会
        // 改到它头上，它在界面上根本看不见，改完谁也不知道。
        const bool ok = ServerListFile::updateEntry(
            datPath, QStringLiteral("真服"), QStringLiteral("real.example.com"),
            QStringLiteral("真服II"), QStringLiteral("real2.example.com"), &problem);
        check(ok, "ZK7 改界面上的第 0 行（盘上是第 1 个元素）", problem);

        NbtTree::Document doc;
        QString why;
        const bool parsed = NbtTree::parse(readBytesAt(datPath), &doc, &why);
        check(parsed, "ZK7 写出来的东西还解得开", why);
        const NbtTree::Node *servers =
            parsed ? NbtTree::field(&doc.root, QStringLiteral("servers")) : nullptr;
        if (servers == nullptr || servers->items.size() != 3) {
            check(false, "ZK7 写出来的 servers 表还是三条");
        } else {
            check(nbtFieldNames(servers->items.at(0)) == QStringList{QStringLiteral("name")},
                  "ZK7 盘上第 0 个元素（没有 ip 的那条）**一格都没动**",
                  nbtFieldNames(servers->items.at(0)).join(QStringLiteral(", ")));
            check(nbtFieldText(servers->items.at(1), QStringLiteral("name")) ==
                          QStringLiteral("真服II") &&
                      nbtFieldText(servers->items.at(1), QStringLiteral("ip")) ==
                          QStringLiteral("real2.example.com"),
                  "ZK7 改的是盘上第 1 个元素（界面上第 0 行）");
            check(nbtFieldText(servers->items.at(2), QStringLiteral("name")) == QStringLiteral("尾"),
                  "ZK7 后面那一条也没被碰");
        }
    }

    // ---------------------------------------------------------------------
    section("ZK8. 盘上没有 name 那一格 ⇒ 按空串认，写的时候补建一格");
    // ---------------------------------------------------------------------
    {
        const QList<NbtServerItem> oldStyle{
            NbtServerItem{QString(), QStringLiteral("c.example.com"), false, true, false, true,
                          QString()},
        };
        check(writeBytesAt(datPath, nbtServersDat(oldStyle)),
              "ZK8 没有 name 那一格的老 fixture 落盘了");

        QString problem;
        const bool ok = ServerListFile::updateEntry(
            datPath, QString(), QStringLiteral("c.example.com"), QStringLiteral("起名字了"),
            QStringLiteral("c.example.com"), &problem);
        check(ok, "ZK8 名字是空串的那一条（盘上没有 name 格）也能改", problem);

        NbtTree::Document doc;
        QString why;
        const bool parsed = NbtTree::parse(readBytesAt(datPath), &doc, &why);
        const NbtTree::Node *servers =
            parsed ? NbtTree::field(&doc.root, QStringLiteral("servers")) : nullptr;
        check(parsed && servers != nullptr && servers->items.size() == 1,
              "ZK8 写出来的东西解得开、还是一条", why);
        if (servers != nullptr && servers->items.size() == 1) {
            const NbtTree::Node &only = servers->items.at(0);
            check(nbtFieldNames(only) == QStringList{QStringLiteral("hidden"),
                                                     QStringLiteral("ip"),
                                                     QStringLiteral("name")},
                  "ZK8 补建的 name 落在末尾（顺序 = hidden/ip/name —— 和真机那份一样）",
                  nbtFieldNames(only).join(QStringLiteral(", ")));
            check(nbtFieldText(only, QStringLiteral("name")) == QStringLiteral("起名字了"),
                  "ZK8 name 那一格真的写进去了");
            const NbtTree::Node *hidden = NbtTree::field(only, QStringLiteral("hidden"));
            check(hidden != nullptr && hidden->type == NbtTree::Type::Byte && hidden->number == 0,
                  "ZK8 旁边那一格 hidden 还活着、还是 Byte 0");
        }
    }

    // ---------------------------------------------------------------------
    section("ZK9. 原来是 gzip ⇒ 写回去还是 gzip");
    // ---------------------------------------------------------------------
    {
        // 游戏读的是 `NbtIo.readCompressed`，所以"顺手帮你压一下"或者"顺手解开"两种都不是
        // 用户要的 —— 换了形状会让游戏当场把这个文件当成坏的。
        const QString plainPath = dir.filePath(QStringLiteral("plain.dat"));
        const QString gzPath = dir.filePath(QStringLiteral("gzip.dat"));
        check(writeBytesAt(plainPath, nbtServersDat(fixture)), "ZK9 裸的那一份落盘了");
        QString why;
        check(ZipUtil::gzipFrom(plainPath, gzPath, &why), "ZK9 压成了 gzip", why);
        const QByteArray gzBefore = readBytesAt(gzPath);
        check(gzBefore.size() >= 2 && static_cast<uchar>(gzBefore.at(0)) == 0x1F &&
                  static_cast<uchar>(gzBefore.at(1)) == 0x8B,
              "ZK9 夹具确实是 gzip（1f 8b）");

        QString problem;
        const bool ok = ServerListFile::updateEntry(
            gzPath, QStringLiteral("B服"), QStringLiteral("b.example.com"), QStringLiteral("B压"),
            QStringLiteral("b.example.com"), &problem);
        check(ok, "ZK9 gzip 的那一份也能改", problem);

        const QByteArray gzAfter = readBytesAt(gzPath);
        check(gzAfter.size() >= 2 && static_cast<uchar>(gzAfter.at(0)) == 0x1F &&
                  static_cast<uchar>(gzAfter.at(1)) == 0x8B,
              "ZK9 写回去**还是 gzip**（不是顺手解压成裸 NBT）");

        const QString outPath = dir.filePath(QStringLiteral("out.dat"));
        check(ZipUtil::gunzipTo(gzPath, outPath, &why), "ZK9 解回来看看里面", why);
        QList<NbtUtil::ServerEntry> rows;
        const NbtUtil::Status status = ServerListFile::read(outPath, &rows, nullptr);
        check(status == NbtUtil::Status::Ok && rows.size() == 3 &&
                  rows.size() > 1 && rows.at(1).name == QStringLiteral("B压"),
              "ZK9 解开之后那一格真的变了，别的地方没动", QString::number(rows.size()));
    }

    // ---------------------------------------------------------------------
    section("ZK10. 拒写的另外两条：文件不在 / 根里没有 servers");
    // ---------------------------------------------------------------------
    {
        QString problem;
        const bool nowhere = ServerListFile::updateEntry(
            dir.filePath(QStringLiteral("nope/servers.dat")), QStringLiteral("A"),
            QStringLiteral("a"), QStringLiteral("B"), QStringLiteral("b"), &problem);
        check(!nowhere && problem.contains(QStringLiteral("servers.dat")),
              "ZK10 文件不在 ⇒ 拒绝，并说清是哪一个文件", problem);

        const QByteArray notServers = nbtTag(
            0x0A, QByteArray(),
            nbtCompoundBody({nbtTag(0x08, QByteArrayLiteral("foo"), nbtString(QStringLiteral("bar")))}));
        const QString oddPath = dir.filePath(QStringLiteral("odd.dat"));
        check(writeBytesAt(oddPath, notServers), "ZK10 一份没有 servers 那格的 NBT 落盘了");
        problem.clear();
        const bool ok = ServerListFile::updateEntry(oddPath, QString(), QStringLiteral("a"),
                                                    QStringLiteral("b"), QStringLiteral("c"),
                                                    &problem);
        check(!ok && !problem.isEmpty(), "ZK10 根里没有 servers 那一格 ⇒ 拒绝", problem);
        check(readBytesAt(oddPath) == notServers, "ZK10 拒写之后那一份逐字节没动");
    }

    // ---------------------------------------------------------------------
    section("ZK11. 读那一半就是 NbtUtil（不多不少）");
    // ---------------------------------------------------------------------
    {
        QList<NbtUtil::ServerEntry> rows;
        QString problem;
        check(ServerListFile::read(dir.filePath(QStringLiteral("missing/servers.dat")), &rows,
                                   &problem) == NbtUtil::Status::Missing,
              "ZK11 文件不在 ⇒ Missing（不是 Unreadable，也不是一张空的 Ok 表）");
    }

    // ---------------------------------------------------------------------
    section("ZK12. 往已有的那一份里加一条：接在表尾，别的条目逐字节不动");
    // ---------------------------------------------------------------------
    {
        const QString addPath = dir.filePath(QStringLiteral("add.dat"));
        check(writeBytesAt(addPath, nbtServersDat(fixture)), "ZK12 夹具落盘了");
        const int sizeBefore = readBytesAt(addPath).size();

        QString problem;
        const bool ok = ServerListFile::addEntry(addPath, QStringLiteral("D服"),
                                                 QStringLiteral("d.example.com:25565"), &problem);
        check(ok, "ZK12 加一条成功", problem);

        QList<NbtServerItem> expected = fixture;
        expected.append(
            NbtServerItem{QStringLiteral("D服"), QStringLiteral("d.example.com:25565")});
        check(readBytesAt(addPath) == nbtServersDat(expected),
              "ZK12 接在表尾，前三条逐字节没动（含 icon / hidden 那些没认的格）");
        check(readBytesAt(addPath).size() > sizeBefore, "ZK12 文件真的变长了");

        QList<NbtUtil::ServerEntry> rows;
        const NbtUtil::Status status = ServerListFile::read(addPath, &rows, nullptr);
        check(status == NbtUtil::Status::Ok && rows.size() == 4 &&
                  rows.at(3).name == QStringLiteral("D服") &&
                  rows.at(3).address == QStringLiteral("d.example.com:25565"),
              "ZK12 读回来多出来的就是最后那一条", QString::number(rows.size()));
    }

    // ---------------------------------------------------------------------
    section("ZK13. 文件不在 ⇒ 建一份新的，而且**是 gzip**");
    // ---------------------------------------------------------------------
    {
        // 这个实例从来没加过服务器时 `servers.dat` 就是不在的，而那正是"添加"最常见的
        // 第一次 —— 所以这一档**不是失败**（"改"和"删"那两条路上它是）。
        const QString freshPath = dir.filePath(QStringLiteral("brandnew.dat"));
        QFile::remove(freshPath);

        QString problem;
        const bool ok = ServerListFile::addEntry(freshPath, QStringLiteral("第一台"),
                                                 QStringLiteral("first.example.com"), &problem);
        check(ok, "ZK13 文件不在时也能加", problem);

        const QByteArray bytes = readBytesAt(freshPath);
        check(bytes.size() >= 2 && static_cast<uchar>(bytes.at(0)) == 0x1F &&
                  static_cast<uchar>(bytes.at(1)) == 0x8B,
              "ZK13 新写出来的那一份是 gzip（游戏读的是 NbtIo.readCompressed）");

        // 解开之后逐字节比：形状 = 无名根 + 一格 servers（夹具就是这么造的）。
        const QString outPath = dir.filePath(QStringLiteral("brandnew-out.dat"));
        QString why;
        check(ZipUtil::gunzipTo(freshPath, outPath, &why), "ZK13 解回来看看里面", why);
        const QList<NbtServerItem> want{NbtServerItem{QStringLiteral("第一台"),
                                                      QStringLiteral("first.example.com")}};
        check(readBytesAt(outPath) == nbtServersDat(want),
              "ZK13 解出来就是那份夹具的形状（无名根 + servers 一格）");

        QList<NbtUtil::ServerEntry> rows;
        const NbtUtil::Status status = ServerListFile::read(freshPath, &rows, nullptr);
        check(status == NbtUtil::Status::Ok && rows.size() == 1 &&
                  rows.at(0).name == QStringLiteral("第一台") &&
                  rows.at(0).address == QStringLiteral("first.example.com"),
              "ZK13 读回来就是刚加的那一条", QString::number(rows.size()));
    }

    // ---------------------------------------------------------------------
    section("ZK14. 删一条：剩下的逐条对得上；删到空表仍然合法");
    // ---------------------------------------------------------------------
    {
        const QString rmPath = dir.filePath(QStringLiteral("rm.dat"));
        check(writeBytesAt(rmPath, nbtServersDat(fixture)), "ZK14 夹具落盘了");

        QString problem;
        check(ServerListFile::removeEntry(rmPath, QStringLiteral("B服"),
                                          QStringLiteral("b.example.com"), &problem),
              "ZK14 删中间那一条", problem);
        const QList<NbtServerItem> afterMiddle{fixture.at(0), fixture.at(2)};
        check(readBytesAt(rmPath) == nbtServersDat(afterMiddle),
              "ZK14 少了那一条，别的逐字节不变");

        // 第三条**没有 name**（1.12.2 那种）：按地址认，照样删得掉 —— 这条钉的是
        // "认值不认下标"在**删**这边的等价物。
        problem.clear();
        check(ServerListFile::removeEntry(rmPath, QString(), QStringLiteral("c.example.com"),
                                          &problem),
              "ZK14 只有 ip 没有 name 的那一条也能按地址删掉", problem);

        problem.clear();
        check(ServerListFile::removeEntry(rmPath, QStringLiteral("A服"),
                                          QStringLiteral("a.example.com:25565"), &problem),
              "ZK14 删掉最后一条", problem);

        problem.clear();
        QList<NbtUtil::ServerEntry> rows;
        const NbtUtil::Status status = ServerListFile::read(rmPath, &rows, &problem);
        check(status == NbtUtil::Status::Ok && rows.isEmpty(),
              "ZK14 删到空 ⇒ 仍然读得动，只是 0 条（不是坏文件）", problem);

        // 空表**也带着元素类型** —— 游戏就是靠它认这张表的。
        NbtTree::Document doc;
        QString why;
        check(NbtTree::parse(readBytesAt(rmPath), &doc, &why), "ZK14 那份还能 parse 回来", why);
        const NbtTree::Node *servers = NbtTree::field(doc.root, QStringLiteral("servers"));
        check(servers != nullptr && servers->type == NbtTree::Type::List &&
                  servers->items.isEmpty() && servers->itemType == NbtTree::Type::Compound,
              "ZK14 留下的是「元素类型是复合标签的空表」（不是把文件删了）");
    }

    // ---------------------------------------------------------------------
    section("ZK15. 拒写的两条：地址是空的 / 那份读不懂");
    // ---------------------------------------------------------------------
    {
        const QString guardPath = dir.filePath(QStringLiteral("guard.dat"));
        check(writeBytesAt(guardPath, nbtServersDat(fixture)), "ZK15 夹具落盘了");
        const QByteArray before = readBytesAt(guardPath);

        QString problem;
        check(!ServerListFile::addEntry(guardPath, QStringLiteral("X"), QStringLiteral("   "),
                                        &problem),
              "ZK15 地址是空的 ⇒ 拒绝", problem);
        check(readBytesAt(guardPath) == before, "ZK15 拒写之后逐字节没动（一）");

        problem.clear();
        check(!ServerListFile::removeEntry(guardPath, QStringLiteral("不存在"),
                                           QStringLiteral("nowhere.example.com"), &problem),
              "ZK15 盘上没有那一条 ⇒ 拒绝", problem);
        check(readBytesAt(guardPath) == before, "ZK15 拒写之后逐字节没动（二）");

        // 一份读不懂的 servers.dat：**不覆盖**。覆盖等于把用户的东西扔掉。
        const QByteArray garbage = QByteArrayLiteral("this is not nbt at all");
        const QString brokenPath = dir.filePath(QStringLiteral("broken.dat"));
        check(writeBytesAt(brokenPath, garbage), "ZK15 一份坏文件落盘了");
        problem.clear();
        check(!ServerListFile::addEntry(brokenPath, QStringLiteral("X"),
                                        QStringLiteral("x.example.com"), &problem),
              "ZK15 读不懂的那一份 ⇒ 加不进去", problem);
        check(readBytesAt(brokenPath) == garbage, "ZK15 坏文件逐字节没动");
    }

    // ---------------------------------------------------------------------
    section("ZK16. gzip 的那一份：加 / 删之后**还是 gzip**");
    // ---------------------------------------------------------------------
    {
        const QString plainPath = dir.filePath(QStringLiteral("gz-plain.dat"));
        const QString gzPath = dir.filePath(QStringLiteral("gz-round.dat"));
        check(writeBytesAt(plainPath, nbtServersDat(fixture)), "ZK16 先造一份裸的");
        QString why;
        check(ZipUtil::gzipFrom(plainPath, gzPath, &why), "ZK16 压成 gzip", why);

        QString problem;
        check(ServerListFile::addEntry(gzPath, QStringLiteral("E服"),
                                       QStringLiteral("e.example.com"), &problem),
              "ZK16 gzip 的那一份也能加", problem);
        problem.clear();
        check(ServerListFile::removeEntry(gzPath, QStringLiteral("B服"),
                                          QStringLiteral("b.example.com"), &problem),
              "ZK16 gzip 的那一份也能删", problem);

        const QByteArray bytes = readBytesAt(gzPath);
        check(bytes.size() >= 2 && static_cast<uchar>(bytes.at(0)) == 0x1F &&
                  static_cast<uchar>(bytes.at(1)) == 0x8B,
              "ZK16 写回去**还是 gzip**（不是顺手解压成裸 NBT）");

        const QString outPath = dir.filePath(QStringLiteral("gz-round-out.dat"));
        check(ZipUtil::gunzipTo(gzPath, outPath, &why), "ZK16 解回来看看", why);
        const QList<NbtServerItem> want{fixture.at(0), fixture.at(2),
                                        NbtServerItem{QStringLiteral("E服"),
                                                      QStringLiteral("e.example.com")}};
        check(readBytesAt(outPath) == nbtServersDat(want),
              "ZK16 解开之后 = 加一条、删一条的样子（其余逐字节不变）");
    }
}

// ---------------------------------------------------------------------------
// ZL 节：quick play 那两个参数（`QuickPlay`）。
//
// 用户 2026-10-10 原话：「世界和服务器都做一个临时占位（加入选中的世界（仅限有这个参数的
// 版本）/服务器）先试试看能不能生效」。
//
// 这一节钉三件事：
//   1. **判据的形状**（`supports()`）—— 认的是版本 json 的 `arguments.game` 里有没有写着
//      这个名字，**不是版本号**。真 json（`meta/26.2.json`）是照游戏自己的选项表生成的，
//      所以"和真写的那一份对得上"这件事只有拿真 json 才验得出来；
//   2. ★ **要问合并过的那一份** —— 加载器版本的 profile 里一条 quick play 都没有（全在父
//      版本那份里），拿没合并的那份问，Forge / Fabric 的实例会一个都答"不支持"；
//   3. 这一对参数**必须由启动器自己发**（json 自己声明的那一条会被整条丢掉）。
// ---------------------------------------------------------------------------
static void runQuickPlayTests(const QString &metaDir) {
    const QuickPlay::Kind single = QuickPlay::Kind::Singleplayer;
    const QuickPlay::Kind multi = QuickPlay::Kind::Multiplayer;

    // ---------------------------------------------------------------------
    section("ZL1. 参数名 / 拼出来的 token");
    // ---------------------------------------------------------------------
    {
        check(QuickPlay::argumentName(single) == QStringLiteral("--quickPlaySingleplayer") &&
                  QuickPlay::argumentName(multi) == QStringLiteral("--quickPlayMultiplayer"),
              "ZL1 两位的参数名（唯一出处）");

        check(QuickPlay::arguments(QuickPlay::Target()).isEmpty(),
              "ZL1 没有这一发 ⇒ 命令行上多不出任何东西（绝大多数启动的处境）");

        const QStringList tokens =
            QuickPlay::arguments(QuickPlay::Target{multi, QStringLiteral("mc.example.com:25566")});
        check(tokens.size() == 2 && tokens.at(0) == QStringLiteral("--quickPlayMultiplayer") &&
                  tokens.at(1) == QStringLiteral("mc.example.com:25566"),
              "ZL1 有那一发 ⇒ 先名字后值，两个 token", tokens.join(QStringLiteral(" ")));
    }

    // ---------------------------------------------------------------------
    section("ZL2 / ZL3. 认哪几种写法");
    // ---------------------------------------------------------------------
    {
        // 照抄真 json（26.2 那份）里的原样。
        const QJsonObject entry = QJsonDocument::fromJson(R"({
            "rules": [{"action": "allow", "features": {"is_quick_play_singleplayer": true}}],
            "value": ["--quickPlaySingleplayer", "${quickPlaySingleplayer}"]
        })").object();
        const QJsonObject realShape{{QStringLiteral("arguments"),
                                     QJsonObject{{QStringLiteral("game"), QJsonArray{entry}}}}};
        check(QuickPlay::supports(realShape, single), "ZL2 真形状（对象 + rules + value 数组）⇒ 支持");
        check(!QuickPlay::supports(realShape, multi),
              "ZL2 只写了单人那一条 ⇒ 多人**不支持**（两位各算各的）");

        const auto withGame = [](const QJsonArray &game) {
            return QJsonObject{
                {QStringLiteral("arguments"), QJsonObject{{QStringLiteral("game"), game}}}};
        };

        QJsonArray bare;
        bare.append(QStringLiteral("--quickPlayMultiplayer"));
        check(QuickPlay::supports(withGame(bare), multi), "ZL3 裸字符串条目也认");

        QJsonArray singleValue;
        singleValue.append(QJsonObject{{QStringLiteral("value"), QStringLiteral("--quickPlayMultiplayer")}});
        check(QuickPlay::supports(withGame(singleValue), multi), "ZL3 value 是单个字符串也认");

        QJsonArray inArray;
        inArray.append(QStringLiteral("--quickPlaySingleplayer"));
        check(QuickPlay::supports(
                  withGame({QJsonObject{{QStringLiteral("value"), inArray}}}), single),
              "ZL3 数组里混着别的写法也认");

        check(QuickPlay::supports(
                  QJsonObject{{QStringLiteral("minecraftArguments"),
                               QStringLiteral("-Xmx1G --quickPlayMultiplayer ${quickPlayMultiplayer}")}},
                  multi),
              "ZL3 老格式那串空格分隔的也扫一遍");
    }

    // ---------------------------------------------------------------------
    section("ZL4. 反面：空 json / 只有 feature 名");
    // ---------------------------------------------------------------------
    {
        check(!QuickPlay::supports(QJsonObject(), single) &&
                  !QuickPlay::supports(QJsonObject(), multi),
              "ZL4 空 json ⇒ 两位都不支持");

        // ★ 判据是 **value 里那个名字**，不是 rules 里那个 feature 名。这一条故意只写
        //   feature 名：把判据写成"rules 里出现过 is_quick_play_*"的实现会在这儿假绿。
        const QJsonObject onlyFeature = QJsonDocument::fromJson(R"({
            "arguments": {"game": [
                {"rules": [{"action": "allow", "features": {"is_quick_play_singleplayer": true}}],
                 "value": ["--somethingElse", "${somethingElse}"]}
            ]}
        })").object();
        check(!QuickPlay::supports(onlyFeature, single),
              "ZL4 只有 feature 名、value 里没有这个 flag ⇒ 不支持");
    }

    // ---------------------------------------------------------------------
    section("ZL5. 真 json：1.20 之后那份有、1.19 那份没有");
    // ---------------------------------------------------------------------
    {
        const QJsonObject modern = loadJson(metaDir + QStringLiteral("/26.2.json"));
        check(!modern.isEmpty(), "ZL5 读到了真 json 夹具（meta/26.2.json）");
        if (!modern.isEmpty()) {
            check(QuickPlay::supports(modern, single) && QuickPlay::supports(modern, multi),
                  "ZL5 1.20 之后那份真 json 里两位都在");
        }

        const QJsonObject old = loadJson(metaDir + QStringLiteral("/1.19.json"));
        check(!old.isEmpty(), "ZL5 读到了 1.19 那份夹具（quick play 之前的最后一个正式版）");
        if (!old.isEmpty()) {
            check(!QuickPlay::supports(old, single) && !QuickPlay::supports(old, multi),
                  "ZL5 1.19 ⇒ 两位都不支持（发了游戏会当场退出的那一档）");
        }
    }

    // ---------------------------------------------------------------------
    section("ZL6. ★ 要问**合并过**的那一份");
    // ---------------------------------------------------------------------
    {
        const QJsonObject vanilla = loadJson(metaDir + QStringLiteral("/26.2.json"));
        check(!vanilla.isEmpty(), "ZL6 父版本那份真 json 读到了");
        if (!vanilla.isEmpty()) {
            // 子 profile 照真 Forge 那份的形状造：有 id / mainClass / inheritsFrom，
            // 自己的 `arguments.game` 里**没有** quick play。
            const QJsonObject loader{
                {QStringLiteral("id"), QStringLiteral("26.2-forge-99.0.0")},
                {QStringLiteral("inheritsFrom"), QStringLiteral("26.2")},
                {QStringLiteral("mainClass"),
                 QStringLiteral("cpw.mods.bootstraplauncher.BootstrapLauncher")},
                {QStringLiteral("arguments"),
                 QJsonObject{{QStringLiteral("game"), QJsonArray{QStringLiteral("--fml.forgeVersion")}}}},
            };
            check(!QuickPlay::supports(loader, single),
                  "ZL6 子 profile 自己那一份 ⇒ 不认（quick play 不在它身上）");
            const QJsonObject merged = VersionInheritance::merge(loader, vanilla);
            check(QuickPlay::supports(merged, single) && QuickPlay::supports(merged, multi),
                  "ZL6 合并过的那一份两位都认 —— 这就是产品取的是合并后 json 的理由");
        }
    }

    // ---------------------------------------------------------------------
    section("ZL7 / ZL8. 那句话，以及这一对参数必须我们发");
    // ---------------------------------------------------------------------
    {
        const QString saySingle = QuickPlay::unsupportedText(single);
        const QString sayMulti = QuickPlay::unsupportedText(multi);
        check(!saySingle.isEmpty() && !sayMulti.isEmpty() && saySingle != sayMulti,
              "ZL7 两位各有一句人话，而且不是同一句");
        check(saySingle.contains(QuickPlay::argumentName(single)) &&
                  sayMulti.contains(QuickPlay::argumentName(multi)),
              "ZL7 那句话里点名了是哪一条参数");

        check(VersionArguments::isVanillaGameArgument(QuickPlay::argumentName(single)) &&
                  VersionArguments::isVanillaGameArgument(QuickPlay::argumentName(multi)),
              "ZL8 两位在 isVanillaGameArgument 名单里（json 自己声明的那条会被丢掉 ⇒ 必须我们发）");
    }

    // ---------------------------------------------------------------------
    section("ZL9. ★ 这一对参数**真的接进了命令行**（判据层写对了 ≠ 接上了）");
    // ---------------------------------------------------------------------
    //
    // 上面 ZL1~ZL8 全在 `QuickPlay` 那个纯函数里 —— 它们全绿也**证明不了**命令行上真有
    // 那一条：`LauncherManager::generateJvmArguments()` 里少写一句 `args << …`，上面的
    // 断言一条都不会红（这正是 `--fml.*` 当年踩过的那个坑：判据写好了、参数一条都没发出去）。
    // 所以这一节拿**真的那个函数**拼一次命令行。
    //
    // NOTE: 拿的是真 json 夹具（`meta/26.2.json`，真支持这两位），不是手搓的一份 ——
    //       手搓的会绕开"json 自己声明的那条在 isVanillaGameArgument 名单上、必须由我们发"
    //       那件事（见 ZL8），而那件事恰恰是这条接线存在的理由。
    {
        const QJsonObject vanilla = loadJson(metaDir + QStringLiteral("/26.2.json"));
        check(!vanilla.isEmpty(), "ZL9 前提：拿到那份真 json");
        if (!vanilla.isEmpty()) {
            LauncherManager mgr;
            EffectiveJavaSettings java;
            java.xms = 512;
            java.xmx = 2048;
            const QString assetIndex =
                vanilla.value(QStringLiteral("assetIndex")).toObject().value(QStringLiteral("id")).toString();
            // 同一份 json、同一套 Java 值，**只有最后一格不同** —— 这样"多出来的那两条"
            // 只可能来自 quick play 这一发。
            const auto commandLine = [&](const QuickPlay::Target &target) {
                return mgr.generateJvmArguments(QString(), QStringLiteral("26.2"), assetIndex,
                                                vanilla, java, /*offlineMode=*/true, 21,
                                                QStringList(), QStringLiteral("Tester"), QString(),
                                                GameWindowSettings(), ScreenWorkArea(), target);
            };

            const QStringList plain = commandLine(QuickPlay::Target());
            check(!plain.contains(QuickPlay::argumentName(single)) &&
                      !plain.contains(QuickPlay::argumentName(multi)),
                  "★ ZL9 没排这一发的时候，那两条**一条都不在命令行上**"
                  "（绝大多数启动的处境；json 自己声明的那条必须被丢掉）");

            // ★★ 存档：参数名后面**紧跟**的就是那个值（不是隔着别的 token）。
            const QString worldName = QStringLiteral("我的世界 A");
            const QStringList singleArgs = commandLine(
                QuickPlay::Target{single, worldName});
            const int atSingle = singleArgs.indexOf(QuickPlay::argumentName(single));
            check(atSingle >= 0 && atSingle + 1 < singleArgs.size() &&
                      singleArgs.at(atSingle + 1) == worldName,
                  "★★ ZL9 「加入选中的世界」真的接上了：`--quickPlaySingleplayer` 后面紧跟那个世界名",
                  QStringLiteral("下标 %1 / 共 %2 条 / 后一格「%3」")
                      .arg(atSingle)
                      .arg(singleArgs.size())
                      .arg(atSingle >= 0 && atSingle + 1 < singleArgs.size()
                               ? singleArgs.at(atSingle + 1)
                               : QStringLiteral("<没有>")));
            check(!singleArgs.contains(QuickPlay::argumentName(multi)),
                  "★ ZL9 单人那一发不该顺手把多人那条也带上（两位各算各的）");

            // ★★ 服务器：`host:port` 原样过去（游戏自己认得这个写法）。
            const QString address = QStringLiteral("mc.example.com:25566");
            const QStringList multiArgs =
                commandLine(QuickPlay::Target{multi, address});
            const int atMulti = multiArgs.indexOf(QuickPlay::argumentName(multi));
            check(atMulti >= 0 && atMulti + 1 < multiArgs.size() &&
                      multiArgs.at(atMulti + 1) == address,
                  "★★ ZL9 「加入服务器」真的接上了：`--quickPlayMultiplayer` 后面紧跟那个 host:port",
                  QStringLiteral("下标 %1 / 后一格「%2」")
                      .arg(atMulti)
                      .arg(atMulti >= 0 && atMulti + 1 < multiArgs.size()
                               ? multiArgs.at(atMulti + 1)
                               : QStringLiteral("<没有>")));
            check(multiArgs.size() == plain.size() + 2,
                  "★ ZL9 就多那两条，不多不少",
                  QStringLiteral("%1 → %2").arg(plain.size()).arg(multiArgs.size()));
        }
    }
}

// ---------------------------------------------------------------------------
// ZI 节：「导出错误报告…」写出来的那一份文本。
//
// 用户原话：「把日志和错误报告导出功能加上，就在那个日志窗口下方，右下角放着」。
//
// 这一份文本**是要发给别人的**（拖进群里、贴进 issue），所以它长什么样得能被钉死 ——
// 而它偏偏又最容易"悄悄变样"（改一句措辞、多一个字段，谁也不会当场看出来）。所以这一节
// 把整份报告逐行钉住：头部那几行的顺序与形状、退出码那一行**只在真的收到过的时候**写、
// 空的那一段写一句"一行都没有"、以及两种文件名的清洗。
//
// NOTE: 时间是从外面传进去的（`ErrorReport` 不读时钟），所以 `生成时间：` 那一行在这里
//       是个定值 —— 这一条是整个文件里唯一能钉住"时间那一格长什么样"的办法。
static void runErrorReportTests() {
    // ---------------------------------------------------------------------
    section("ZI1. 头部那几行（顺序、形状、哪些空着就不写）");
    // ---------------------------------------------------------------------
    const QDateTime now = QDateTime::fromString(QStringLiteral("2026-09-28 21:03:11"),
                                                QStringLiteral("yyyy-MM-dd HH:mm:ss"));

    ErrorReport::Facts full;
    full.launcherVersion = QStringLiteral("0.9.3");
    full.instanceName = QStringLiteral("我的整合包");
    full.instanceId = QStringLiteral("1.20.1-forge");
    full.accountName = QStringLiteral("Steve");
    full.systemDescription = ErrorReport::systemDescription();
    full.processId = 12345;
    full.startedAt = now.addSecs(-600);
    full.finished = true;
    full.crashed = false;
    full.exitCode = 0;

    const QString fullHeader = ErrorReport::header(full, now);
    const QStringList fullLines = fullHeader.split(QLatin1Char('\n'));
    check(fullLines.size() == 10, "ZI1 该写的行一行不多一行不少（标题 + 9 个字段）",
          QString::number(fullLines.size()));
    check(fullLines.value(0) == QStringLiteral("WTFML 错误报告"),
          "ZI1 第一行就是那句话", fullLines.value(0));
    check(fullLines.contains(QStringLiteral("生成时间：2026-09-28 21:03:11")),
          "ZI1 生成时间按外面传的那个走（这一格不读时钟）");
    check(fullLines.contains(QStringLiteral("启动器版本：0.9.3")), "ZI1 启动器版本那一行");
    check(fullHeader.contains(QStringLiteral("系统：") + ErrorReport::systemDescription()),
          "ZI1 系统那一行用的就是 systemDescription()");
    // 实例**两行都写**：显示名是人认的，id 是盘上那个目录名 —— 自定义过名字时两者不一样，
    // 拿到报告的人要照着 id 去找是哪一个。
    check(fullLines.contains(QStringLiteral("实例：我的整合包")), "ZI1 实例显示名那一行");
    check(fullLines.contains(QStringLiteral("实例 id：1.20.1-forge")), "ZI1 实例 id 那一行");
    check(fullLines.contains(QStringLiteral("账号：Steve")), "ZI1 账号那一行");
    check(fullLines.contains(QStringLiteral("进程 ID：12345")), "ZI1 进程 ID 那一行");
    check(fullLines.contains(QStringLiteral("启动时间：2026-09-28 20:53:11")),
          "ZI1 启动时间那一行");
    check(fullLines.contains(QStringLiteral("退出码：0")), "ZI1 正常退出就是那个数");

    // 异常终止：那个数是**负数**，光看它认不出是崩溃，所以后面必须跟一句。
    full.crashed = true;
    full.exitCode = -1073741819;
    check(ErrorReport::header(full, now).contains(
              QStringLiteral("退出码：-1073741819（异常终止）")),
          "ZI1 崩溃时退出码后面跟一句「（异常终止）」");

    // ★ 游戏还在跑的时候**不许编一个退出码出来**。编出来的"退出码：0"是最坏的一种假话：
    //   看报告的人会照着它去排除"崩溃"这个方向。
    full.finished = false;
    full.crashed = false;
    full.exitCode = 0;
    const QString liveHeader = ErrorReport::header(full, now);
    check(liveHeader.contains(QStringLiteral("退出码：（导出时游戏还在运行）")),
          "ZI1 还没退出时那一行明说「还在运行」");
    check(!liveHeader.contains(QStringLiteral("退出码：0")),
          "ZI1 而且**不许**顺手写个 0 出来（那是最坏的一种假话）");

    // 拿不到的那些字段：整行**不写**（留一个 `账号：` 比不写更难看，也更容易被当成"真有个
    // 空名字的账号"）。
    ErrorReport::Facts bare;
    bare.finished = true;
    const QString bareHeader = ErrorReport::header(bare, now);
    check(!bareHeader.contains(QStringLiteral("账号")) &&
              !bareHeader.contains(QStringLiteral("启动器版本")) &&
              !bareHeader.contains(QStringLiteral("系统")) &&
              !bareHeader.contains(QStringLiteral("实例")) &&
              !bareHeader.contains(QStringLiteral("进程 ID")) &&
              !bareHeader.contains(QStringLiteral("启动时间")),
          "ZI1 拿不到的字段整行不写（不是写个空的冒号在那儿）");
    check(bareHeader.contains(QStringLiteral("生成时间：")) &&
              bareHeader.contains(QStringLiteral("退出码：")),
          "ZI1 但时间和退出码那两行任何时候都在");

    // ---------------------------------------------------------------------
    section("ZI2. 整份报告：两段、分隔线、以及「一行都没有」那句");
    // ---------------------------------------------------------------------
    check(ErrorReport::sectionDivider(QStringLiteral("x")) ==
              QStringLiteral("------------------------------ x ------------------------------"),
          "ZI2 分隔线的形状");

    full.finished = true;
    full.crashed = false;
    full.exitCode = 0;
    full.errorLines = 2;
    full.totalLines = 5;
    const QString withErrors =
        ErrorReport::text(full, now,
                          QStringLiteral("[21:03:11] [Render thread/ERROR] 炸了\n"
                                         "[21:03:11] [Render thread/ERROR] 又炸了\n"),
                          QStringLiteral("[21:03:10] 起\n[21:03:11] 中\n"));
    check(withErrors.startsWith(ErrorReport::header(full, now)), "ZI2 报告从头部开始");
    check(withErrors.contains(QStringLiteral("错误与致命（共 2 行）")), "ZI2 错误那一段的标题");
    check(withErrors.contains(QStringLiteral("完整日志（共 5 行）")), "ZI2 日志那一段的标题");
    check(withErrors.contains(QLatin1Char('\n') +
                              ErrorReport::sectionDivider(QStringLiteral("完整日志（共 5 行）"))),
          "ZI2 分隔线**另起一行**（不是粘在最后一行后面）");
    check(withErrors.endsWith(QStringLiteral("中\n")), "ZI2 末尾收在一个换行上");

    // 两段文本末尾那半行可能不带换行（`logTextFrom()` 就是这么给的）—— 缺了要补一个。
    const QString halfLine = ErrorReport::text(full, now, QStringLiteral("一行错误"),
                                               QStringLiteral("一行日志"));
    check(halfLine.contains(QStringLiteral("一行错误\n")), "ZI2 摘录末尾补了换行");
    check(halfLine.endsWith(QStringLiteral("一行日志\n")), "ZI2 日志末尾也补了换行");

    // ★ 一行错误都没有时**照样写上那一段**：空着的话看的人分不清"没出错"和"导出漏了"。
    full.errorLines = 0;
    const QString noErrors =
        ErrorReport::text(full, now, QString(), QStringLiteral("[21:03:10] 一切正常\n"));
    check(noErrors.contains(QStringLiteral("错误与致命（共 0 行）")),
          "ZI2 没错误时那一段的标题照旧（写的是 0 行）");
    check(noErrors.contains(QStringLiteral("这一趟没有 ERROR 以上的输出")),
          "ZI2 而且明说「这一段里一行都没有」（不是空着）");
    check(noErrors.contains(QStringLiteral("[21:03:10] 一切正常")),
          "ZI2 日志那一段照旧在");

    // ---------------------------------------------------------------------
    section("ZI3. 两种文件名的推荐值（实例名里的坏字符要换掉）");
    // ---------------------------------------------------------------------
    check(ErrorReport::suggestedFileName(QStringLiteral("我的整合包"), now) ==
              QStringLiteral("错误报告-我的整合包-20260928-210311.txt"),
          "ZI3 报告文件名",
          ErrorReport::suggestedFileName(QStringLiteral("我的整合包"), now));
    check(ErrorReport::suggestedLogFileName(QStringLiteral("我的整合包"), now) ==
              QStringLiteral("日志-我的整合包-20260928-210311.log"),
          "ZI3 日志文件名",
          ErrorReport::suggestedLogFileName(QStringLiteral("我的整合包"), now));
    // 冒号、斜杠这些在文件名里是不许出现的 —— 不换掉的话用户的感受是"导出失败了"，
    // 而原因只是名字里有个冒号。
    check(ErrorReport::suggestedFileName(QStringLiteral("a/b:c*d?e\"f<g>h|i\\j"), now) ==
              QStringLiteral("错误报告-a_b_c_d_e_f_g_h_i_j-20260928-210311.txt"),
          "ZI3 名字里的坏字符换成下划线",
          ErrorReport::suggestedFileName(QStringLiteral("a/b:c*d?e\"f<g>h|i\\j"), now));
    // 实例名拿不到时**不留一个空档**：`错误报告--2026…` 看着像坏了。
    check(ErrorReport::suggestedFileName(QString(), now) ==
              QStringLiteral("错误报告-20260928-210311.txt"),
          "ZI3 名字空着时不留双横杠",
          ErrorReport::suggestedFileName(QString(), now));
    check(!ErrorReport::systemDescription().isEmpty() &&
              ErrorReport::systemDescription().contains(QSysInfo::currentCpuArchitecture()),
          "ZI3 系统那一行里带着架构",
          ErrorReport::systemDescription());

    // ---------------------------------------------------------------------
    section("ZI4. 「游戏异常退出」那一份多出来的三行 + 「可能的原因」那一节（§4.3）");
    // ---------------------------------------------------------------------
    // 这三行是 §4.3 点名要收的那几样（Java 版本 / 加载器版本 / 内存参数）。**只有那一路
    // 会填** —— 日志窗那颗「导出错误报告」手上没有这几个值，留空（上面 ZI1 那个 10 行的
    // 断言就是"留空 = 一行都不多"）。
    ErrorReport::Facts crash = full;
    crash.crashed = true;
    crash.exitCode = -1073741819;
    crash.finished = true;
    crash.javaVersion = QStringLiteral("17（D:/Java/jdk17/bin/java.exe）");
    crash.loaderVersion = QStringLiteral("Fabric 0.15.11");
    crash.memoryArgs = QStringLiteral("-Xmx 4096 MB / -Xms 512 MB（本机共 32768 MB）");
    const QString crashHeader = ErrorReport::header(crash, now);
    const QStringList crashLines = crashHeader.split(QLatin1Char('\n'));
    check(crashLines.size() == 13, "★ ZI4 填了那三样就多三行（10 + 3）",
          QString::number(crashLines.size()));
    check(crashLines.contains(QStringLiteral("加载器：Fabric 0.15.11")), "ZI4 加载器那一行");
    check(crashLines.contains(QStringLiteral("Java：17（D:/Java/jdk17/bin/java.exe）")),
          "ZI4 Java 那一行");
    check(crashLines.contains(
              QStringLiteral("内存：-Xmx 4096 MB / -Xms 512 MB（本机共 32768 MB）")),
          "ZI4 内存那一行");
    // 顺序：三行**接在账号后面**（上面那几行是人认这个实例，下面这几行才是这一趟的环境）。
    check(crashHeader.indexOf(QStringLiteral("账号：")) < crashHeader.indexOf(QStringLiteral("加载器："))
              && crashHeader.indexOf(QStringLiteral("加载器："))
                     < crashHeader.indexOf(QStringLiteral("Java："))
              && crashHeader.indexOf(QStringLiteral("Java："))
                     < crashHeader.indexOf(QStringLiteral("内存："))
              && crashHeader.indexOf(QStringLiteral("内存："))
                     < crashHeader.indexOf(QStringLiteral("进程 ID：")),
          "★ ZI4 三行接在账号后面、进程 ID 前面");

    // 「可能的原因」那一节：排在两段日志**前面**（看报告的人第一眼要知道的是"大概是什么事"），
    // 逐条前面带一个「· 」。一句都没有时**整个不写** —— 不写"暂时无法判断"那种废话。
    crash.hints = QStringList{QStringLiteral("这条是第一条。"), QStringLiteral("这条是第二条。")};
    const QString withHints =
        ErrorReport::text(crash, now, QStringLiteral("[21:03:11] 炸了\n"),
                          QStringLiteral("[21:03:10] 起\n"));
    check(withHints.contains(
              ErrorReport::sectionDivider(QStringLiteral("可能的原因（按规则判的，不是猜的）"))),
          "★ ZI4 有提示时才有那一节");
    check(withHints.indexOf(QStringLiteral("可能的原因")) < withHints.indexOf(QStringLiteral("错误与致命")),
          "★ ZI4 那一节排在错误摘录**前面**");
    check(withHints.contains(QStringLiteral("· 这条是第一条。\n· 这条是第二条。\n")),
          "ZI4 逐条写成「· 那句话」");
    crash.hints = QStringList();
    check(!ErrorReport::text(crash, now, QStringLiteral("x\n"), QStringLiteral("y\n"))
               .contains(QStringLiteral("可能的原因")),
          "★ ZI4 一句提示都没有时那一节整个不写");
}

// =========================================================================
// ZJ. 「复制实例」和「导入世界 / 世界改名」（2026-09-28）
//
// 这一节盯的是**真的动盘**那两件事：
//   · `VersionManager::copyInstance()` —— 实例设置的概览里那一颗「复制实例」。
//   · `WorldFiles::copyWorldInto()` / `renameWorld()` —— 存档那一页顶上那颗「导入世界」
//     和行尾那支笔里的「重命名…」。
//
// 为什么在这一层测而不是在 mw_check 里：那两颗按钮的前一站是**原生选择框**
// （QFileDialog），验证工程驱动不了它。所以真正动手的那一半被切成了"收几个字符串"的纯
// 函数 —— 和 deleteInstance() / exportLaunchScript() 那两处同一个切法。
//
// NOTE: 这一节自己开两个临时游戏文件夹（源一个、目标一个），跑完把数据根目录换回去。
//       不往共享沙盒里写东西：这一节要造的是一整份实例和一个世界，留在共享沙盒里会
//       给后面（以及下一次重跑）的节留下没预料到的包袱。
// =========================================================================

/// 造一个最小可用的实例目录（jar + json + meta + 一点嵌套内容）。
/// @param versionRoot `<某游戏文件夹>/versions`
/// @param id 目录名（= 实例 id）
/// @param metaBytes 写进 `wtfml.meta` 的字节；空串 = 不写这个文件
static QString makeInstanceDir(const QString &versionRoot, const QString &id,
                               const QByteArray &metaBytes = QByteArray()) {
    const QString dir = versionRoot + QLatin1Char('/') + id;
    writeFileAt(dir + QLatin1Char('/') + id + QStringLiteral(".jar"), "fake-jar-bytes");
    writeFileAt(dir + QLatin1Char('/') + id + QStringLiteral(".json"),
                R"({"id":"1.20.1","mainClass":"net.minecraft.client.main.Main"})");
    writeFileAt(dir + QStringLiteral("/mods/sodium.jar"), "mod-bytes");
    writeFileAt(dir + QStringLiteral("/saves/我的世界/level.dat"), "level-bytes");
    if (!metaBytes.isEmpty()) {
        writeFileAt(dir + QStringLiteral("/wtfml.meta"), metaBytes);
    }
    return dir;
}

/// 一个目录里某项还在不在（顺手把 `QFileInfo::exists` 的"文件或目录"语义写清楚）。
static bool existsAt(const QString &path) {
    return QFileInfo::exists(path);
}

/// 读盘上一份 `wtfml.meta`（路径自己拼，不走 AppPaths —— 目标在另一个游戏文件夹里）。
static QJsonObject readMetaAt(const QString &dir) {
    QFile file(dir + QStringLiteral("/wtfml.meta"));
    if (!file.open(QIODevice::ReadOnly)) {
        return QJsonObject();
    }
    return QJsonDocument::fromJson(file.readAll()).object();
}

static void runTaskLedgerTests() {
    // ---------------------------------------------------------------------
    section("AL1. percentOf：测不出就回 -1，绝不编一个百分比（§3.4）");
    // ---------------------------------------------------------------------
    {
        const auto make = [](qint64 done, qint64 total) {
            Tasks::TaskSnapshot task;
            task.doneUnits = done;
            task.totalUnits = total;
            return task;
        };
        check(Tasks::percentOf(make(0, 0)) == -1, "总数 0 ⇒ 不可测（-1）",
              QString::number(Tasks::percentOf(make(0, 0))));
        check(Tasks::percentOf(make(5, 0)) == -1, "总数 0 但已经下了几个 ⇒ 还是不可测",
              QString::number(Tasks::percentOf(make(5, 0))));
        check(Tasks::percentOf(make(3, -10)) == -1, "负的总数 ⇒ 不可测",
              QString::number(Tasks::percentOf(make(3, -10))));
        check(Tasks::percentOf(make(1, 3)) == 33, "1/3 ⇒ 33（向下取整，不四舍五入）",
              QString::number(Tasks::percentOf(make(1, 3))));
        check(Tasks::percentOf(make(3, 3)) == 100 && Tasks::percentOf(make(400, 1000)) == 40,
              "3/3 ⇒ 100、400/1000 ⇒ 40",
              QStringLiteral("%1 / %2")
                  .arg(Tasks::percentOf(make(3, 3)))
                  .arg(Tasks::percentOf(make(400, 1000))));
        check(Tasks::percentOf(make(9999, 1000)) == 100, "完成数比总数还大 ⇒ 钳到 100",
              QString::number(Tasks::percentOf(make(9999, 1000))));
        check(Tasks::percentOf(make(-5, 100)) == 0, "负的完成数 ⇒ 钳到 0",
              QString::number(Tasks::percentOf(make(-5, 100))));
    }

    // ---------------------------------------------------------------------
    section("AL2. summaryPriority：收起态那一格的先后（§3.1 那一串逐条对上）");
    // ---------------------------------------------------------------------
    {
        const auto p = [](Tasks::TaskKind kind, Tasks::TaskState state, bool unread = false) {
            Tasks::TaskSnapshot task;
            task.kind = kind;
            task.state = state;
            return Tasks::summaryPriority(task, unread);
        };
        using K = Tasks::TaskKind;
        using S = Tasks::TaskState;
        check(p(K::Download, S::WaitingUser) == 0, "卡在等用户 ⇒ 第一档（0）",
              QString::number(p(K::Download, S::WaitingUser)));
        check(p(K::Download, S::Failed, /*unread=*/true) == 1, "**没看过**的失败 ⇒ 第二档（1）",
              QString::number(p(K::Download, S::Failed, true)));
        check(p(K::Launch, S::Running) == 2, "正在启动 ⇒ 2",
              QString::number(p(K::Launch, S::Running)));
        check(p(K::Install, S::Running) == 3 && p(K::Import, S::Running) == 3,
              "安装 / 导入整合包同一档（3）",
              QStringLiteral("%1 / %2")
                  .arg(p(K::Install, S::Running))
                  .arg(p(K::Import, S::Running)));
        check(p(K::Download, S::Running) == 4, "下载 ⇒ 4",
              QString::number(p(K::Download, S::Running)));
        check(p(K::Export, S::Running) == 5, "导出 ⇒ 5",
              QString::number(p(K::Export, S::Running)));
        check(p(K::Java, S::Running) == 6 && p(K::Integrity, S::Running) == 6 &&
                  p(K::Other, S::Running) == 6,
              "Java / 体检 / 其它同一档（6）");
        // 看过的失败退到最后一档：它还在（在"刚完成"那个窗口里），只是不再抢那一格。
        check(p(K::Download, S::Failed, /*unread=*/false) == 8,
              "**看过**的失败退到最后一档（8）", QString::number(p(K::Download, S::Failed)));
        check(p(K::Launch, S::Succeeded) == 8, "成功那档也是 8（只靠时间窗决定露不露）",
              QString::number(p(K::Launch, S::Succeeded)));
        // WaitingUser 优先于 kind：同一个 Download，卡住等用户就排到最前面。
        check(p(K::Other, S::WaitingUser) < p(K::Launch, S::Running),
              "「等用户」比「正在启动」还靠前（不管它是哪一类任务）");
    }

    // ---------------------------------------------------------------------
    section("AL3. collapsedSummary：收起态显示谁（唯一出处）");
    // ---------------------------------------------------------------------
    {
        const QDateTime now = QDateTime::fromString(QStringLiteral("2026-10-12 12:00:00"),
                                                    QStringLiteral("yyyy-MM-dd HH:mm:ss"));
        const qint64 windowMs = 8000;
        const auto at = [&now](int secondsBefore) { return now.addSecs(-secondsBefore); };

        // 空账本 ⇒ 一条都没有，红点也不该有。
        {
            const Tasks::TaskSummary s = Tasks::collapsedSummary({}, {}, now, windowMs);
            check(s.id == Tasks::invalidTaskId() && !s.hasFailure && s.extraCount == 0,
                  "AL3 一项都没有 ⇒ 无效号、没有红点、「另有 0 项」那句话也不该有",
                  QString::number(s.id));
        }

        // 三件活动任务：Download(4) / Launch(2) / Install(3) ⇒ 显示启动那件，另有 2 项。
        {
            QList<Tasks::TaskSnapshot> tasks;
            Tasks::TaskSnapshot dl;
            dl.id = 1;
            dl.kind = Tasks::TaskKind::Download;
            dl.state = Tasks::TaskState::Running;
            dl.title = QStringLiteral("下载 A");
            dl.startedAt = at(30);
            dl.doneUnits = 400;
            dl.totalUnits = 1000;
            Tasks::TaskSnapshot launch;
            launch.id = 2;
            launch.kind = Tasks::TaskKind::Launch;
            launch.state = Tasks::TaskState::Running;
            launch.title = QStringLiteral("启动 B");
            launch.startedAt = at(10);
            Tasks::TaskSnapshot install;
            install.id = 3;
            install.kind = Tasks::TaskKind::Install;
            install.state = Tasks::TaskState::Running;
            install.title = QStringLiteral("安装 C");
            install.startedAt = at(20);
            tasks << dl << launch << install;

            const Tasks::TaskSummary s = Tasks::collapsedSummary(tasks, {}, now, windowMs);
            check(s.id == 2 && s.title == QStringLiteral("启动 B"),
                  "AL3 三件一起跑 ⇒ 显示优先级最高的那件（启动）", s.title);
            check(s.extraCount == 2, "AL3 除了显示的那件还有 2 项在跑",
                  QStringLiteral("另有 %1 项").arg(s.extraCount));
            check(s.percent == -1, "AL3 启动那件没报过总数 ⇒ 百分比不可测",
                  QString::number(s.percent));

            // 同档取**后发起**的：两件 Download，后起的那件该被显示。
            QList<Tasks::TaskSnapshot> two = {dl};
            Tasks::TaskSnapshot dl2 = dl;
            dl2.id = 9;
            dl2.startedAt = at(1);
            dl2.title = QStringLiteral("下载 D");
            two << dl2;
            check(Tasks::collapsedSummary(two, {}, now, windowMs).id == 9,
                  "AL3 同一档里取**后发起**的那件（用户刚点的那件事）",
                  QString::number(Tasks::collapsedSummary(two, {}, now, windowMs).id));

            // 卡在等用户那件排第一 —— 哪怕它是档位最低的那一类（Download）。
            // NOTE: 改的是 `tasks` 里那一份（`dl` 早在上面就被按值拷进去了，改它没用）。
            tasks[0].state = Tasks::TaskState::WaitingUser;
            const Tasks::TaskSummary s3 = Tasks::collapsedSummary(tasks, {}, now, windowMs);
            check(s3.id == 1, "AL3 「等用户」那件压过启动 / 安装 / 下载",
                  QString::number(s3.id));
        }

        // 未读失败的红点：和**显示的是哪一件**无关（正在下载而上一件失败了，两个信号都在）。
        {
            QList<Tasks::TaskSnapshot> tasks;
            Tasks::TaskSnapshot running;
            running.id = 1;
            running.kind = Tasks::TaskKind::Download;
            running.state = Tasks::TaskState::Running;
            running.startedAt = at(5);
            Tasks::TaskSnapshot failed;
            failed.id = 2;
            failed.kind = Tasks::TaskKind::Install;
            failed.state = Tasks::TaskState::Failed;
            failed.finishedAt = at(1);
            tasks << running << failed;

            const QSet<Tasks::TaskId> unread{2};
            const Tasks::TaskSummary s = Tasks::collapsedSummary(tasks, unread, now, windowMs);
            check(s.hasFailure, "AL3 有未读的失败 ⇒ 红点亮着");
            check(s.id == 2, "AL3 未读的失败比正在跑的下载更该被看见（它排在下载前面）",
                  QString::number(s.id));
            const Tasks::TaskSummary read = Tasks::collapsedSummary(tasks, {}, now, windowMs);
            check(!read.hasFailure && read.id == 1,
                  "AL3 看过了之后：红点灭掉、这一格回到那件正在跑的下载",
                  QString::number(read.id));
        }

        // 「刚完成」只在时间窗里露面，而且**必须有**结束时间戳。
        {
            Tasks::TaskSnapshot done;
            done.id = 5;
            done.kind = Tasks::TaskKind::Download;
            done.state = Tasks::TaskState::Succeeded;
            done.startedAt = at(60);
            const QList<Tasks::TaskSnapshot> tasks{done};

            done.finishedAt = at(1);
            check(Tasks::collapsedSummary({done}, {}, now, windowMs).id == 5,
                  "AL3 刚完成 1 秒 ⇒ 还在窗口里，露着");
            check(Tasks::collapsedSummary({done}, {}, now, 0).id == Tasks::invalidTaskId(),
                  "AL3 时间窗给 0 ⇒ 已完成的一律不显示");
            check(Tasks::collapsedSummary({done}, {}, now, 500).id == Tasks::invalidTaskId(),
                  "AL3 已经过去 1000 ms、窗口只有 500 ms ⇒ 收进历史（不显示了）");

            done.finishedAt = QDateTime();  // 无效时间戳（例：读盘回来那件「已中断」的）
            check(Tasks::collapsedSummary({done}, {}, now, windowMs).id == Tasks::invalidTaskId(),
                  "AL3 没有结束时间戳 ⇒ **不**当成「刚完成」（那种「不知道什么时候完的」不占这一格）");
            done.finishedAt = now.addSecs(30);  // 未来（时钟回拨那类）
            check(Tasks::collapsedSummary({done}, {}, now, windowMs).id == Tasks::invalidTaskId(),
                  "AL3 结束时间戳在**未来** ⇒ 也不当「刚完成」");
        }

        // 中断那件：状态是终态，但没时间戳 ⇒ 收起态不显示它（它靠「未读」或面板露面）。
        {
            Tasks::TaskSnapshot interrupted;
            interrupted.id = 7;
            interrupted.kind = Tasks::TaskKind::Install;
            interrupted.state = Tasks::TaskState::Interrupted;
            check(Tasks::collapsedSummary({interrupted}, {}, now, windowMs).id ==
                      Tasks::invalidTaskId(),
                  "AL3 读回来的「已中断」（没有结束时间戳）不占收起态那一格");
        }
    }

    // ---------------------------------------------------------------------
    section("AM1. TaskManager：终态只落一次（§3.4「重复信号不生成重复完成」）");
    // ---------------------------------------------------------------------
    {
        QTemporaryDir dir;
        check(dir.isValid(), "AM1 建得出一个临时目录来放历史文件");
        if (!dir.isValid()) {
            return;
        }
        Tasks::TaskManager manager;
        manager.setHistoryPath(dir.filePath(QStringLiteral("wtfml.tasks")));

        int finishedSignals = 0;
        int changedSignals = 0;
        int historySignals = 0;
        QObject::connect(&manager, &Tasks::TaskManager::taskFinished,
                         [&finishedSignals](Tasks::TaskId, bool) { ++finishedSignals; });
        QObject::connect(&manager, &Tasks::TaskManager::taskChanged,
                         [&changedSignals](Tasks::TaskId) { ++changedSignals; });
        QObject::connect(&manager, &Tasks::TaskManager::historyChanged,
                         [&historySignals]() { ++historySignals; });

        const Tasks::TaskId a = manager.begin(Tasks::TaskKind::Download, QStringLiteral("下载 A"));
        check(a != Tasks::invalidTaskId() && manager.has(a), "AM1 发出来的号是有效的",
              QString::number(a));
        check(changedSignals == 1, "AM1 新建那一项也发了一次 taskChanged",
              QString::number(changedSignals));

        check(manager.succeed(a), "AM1 第一次收尾成功");
        check(!manager.succeed(a), "AM1 **第二次**收尾回 false");
        check(finishedSignals == 1, "AM1 taskFinished 只发了一次（不是两发）",
              QString::number(finishedSignals));
        check(historySignals == 1, "AM1 historyChanged 也只发了一次",
              QString::number(historySignals));
        check(manager.snapshot(a).state == Tasks::TaskState::Succeeded,
              "AM1 状态没被第二发改写");
        // 失败也不能把一次已经收好的尾改写成失败。
        check(!manager.fail(a, QStringLiteral("晚了")), "AM1 收过尾之后再 fail 也是 false");
        check(manager.snapshot(a).state == Tasks::TaskState::Succeeded &&
                  manager.snapshot(a).errorSummary.isEmpty(),
              "AM1 最后一步：状态还是成功、没被塞进一句错因");

        // 终态是不可变快照：执行器排队中的迟到信号不能把已完成行改回去。
        Tasks::TaskCapabilities lateCapabilities;
        lateCapabilities.canCancel = true;
        check(!manager.setDetail(a, QStringLiteral("迟到的详情"))
                  && !manager.setProgress(a, 9, 10)
                  && !manager.setBytes(a, 90, 100)
                  && !manager.setStepState(a, 0, Tasks::TaskStepState::Failed)
                  && !manager.setCapabilities(a, lateCapabilities),
              "AM1 收尾后所有进度类更新都被拒绝（终态不可变）");
        check(manager.snapshot(a).detail.isEmpty() && !manager.snapshot(a).capabilities.canCancel,
              "AM1 迟到信号没有改动已完成快照");

        // 收尾那一下会把完成数补齐（"完成了"就该是 100%）。
        const Tasks::TaskId b = manager.begin(Tasks::TaskKind::Download, QStringLiteral("下载 B"));
        manager.setProgress(b, 3, 10);
        manager.succeed(b);
        check(manager.snapshot(b).doneUnits == 10, "AM1 成功收尾时完成数补齐到总数",
              QString::number(manager.snapshot(b).doneUnits));
    }

    // ---------------------------------------------------------------------
    section("AM2. TaskManager：一模一样的一帧不用再喊一遍 / 无效号什么都不做");
    // ---------------------------------------------------------------------
    {
        QTemporaryDir dir;
        if (!dir.isValid()) {
            check(false, "AM2 建临时目录");
            return;
        }
        Tasks::TaskManager manager;
        manager.setHistoryPath(dir.filePath(QStringLiteral("wtfml.tasks")));
        const Tasks::TaskId a = manager.begin(Tasks::TaskKind::Download, QStringLiteral("下载"));

        check(manager.setProgress(a, 400, 1000), "AM2 第一次记进度 ⇒ true");
        check(!manager.setProgress(a, 400, 1000), "AM2 一模一样的一帧 ⇒ false（不白喊一遍）");
        check(manager.setProgress(a, 401, 1000), "AM2 数变了 ⇒ 又回 true");
        check(!manager.setBytes(a, 0, 0), "AM2 字节那一对也是同一套（0/0 是第一帧，写不进去）",
              "初始就是 0/0，所以第一次 setBytes(0,0) 也该是 false");
        check(manager.setBytes(a, 1024, 2048), "AM2 字节第一次有值 ⇒ true");

        // 越界的步骤下标 / 无效号：都不许崩、都回 false。
        check(!manager.setStepState(a, 0, Tasks::TaskStepState::Done),
              "AM2 没有那一步（steps 是空的）⇒ false，不崩");
        check(!manager.setDetail(Tasks::invalidTaskId(), QStringLiteral("x")),
              "AM2 无效号 ⇒ false");
        check(!manager.succeed(Tasks::invalidTaskId()), "AM2 无效号收尾 ⇒ false");
        check(!manager.cancel(999999), "AM2 压根不存在的号 ⇒ false");
    }

    // ---------------------------------------------------------------------
    section("AM3. 落盘 / 读回：盘上只有摘要，号从盘上续，没跑完的算已中断");
    // ---------------------------------------------------------------------
    {
        QTemporaryDir dir;
        if (!dir.isValid()) {
            check(false, "AM3 建临时目录");
            return;
        }
        const QString path = dir.filePath(QStringLiteral("wtfml.tasks"));
        {
            Tasks::TaskManager manager;
            manager.setHistoryPath(path);
            const Tasks::TaskId one = manager.begin(Tasks::TaskKind::Install, QStringLiteral("安装 X"),
                                                    QStringLiteral("inst-1"));
            manager.setProgress(one, 5, 10);
            manager.setDetail(one, QStringLiteral("正在下载资源对象…"));
            manager.succeed(one);
            const Tasks::TaskId two = manager.begin(Tasks::TaskKind::Download, QStringLiteral("下载 Y"));
            manager.cancel(two);
        }
        check(QFile::exists(path), "AM3 历史文件落到盘上了", path);

        const QList<Tasks::TaskSnapshot> again = Tasks::load(path);
        check(again.size() == 2, "AM3 读回来两条", QString::number(again.size()));
        const auto byId = [&again](Tasks::TaskId id) {
            for (const Tasks::TaskSnapshot &t : again) {
                if (t.id == id) {
                    return t;
                }
            }
            return Tasks::TaskSnapshot();
        };
        check(byId(1).title == QStringLiteral("安装 X") &&
                  byId(1).kind == Tasks::TaskKind::Install &&
                  byId(1).state == Tasks::TaskState::Succeeded,
              "AM3 标题 / 种类 / 状态都原样读回来");
        check(byId(1).targetId == QStringLiteral("inst-1"), "AM3 目标 id 也在",
              byId(1).targetId);
        check(byId(2).state == Tasks::TaskState::Cancelled, "AM3 取消那件也读得回来");
        // 摘要**只**存那几样：详情 / 进度 / 能力位都不在上面（见 TaskHistory.hpp 的"不存"那段）。
        check(byId(1).detail.isEmpty() && byId(1).totalUnits == 0 && byId(1).steps.isEmpty() &&
                  !byId(1).capabilities.canCancel,
              "AM3 盘上只有摘要：详情 / 进度 / 步骤 / 能力位都不往上写",
              QStringLiteral("detail=「%1」 total=%2 steps=%3")
                  .arg(byId(1).detail)
                  .arg(byId(1).totalUnits)
                  .arg(byId(1).steps.size()));

        // 号从**盘上最大的那个**续：读回之后新发的号必须比它大（不然会撞上一条旧历史）。
        {
            Tasks::TaskManager manager;
            manager.setHistoryPath(path);
            const int loaded = manager.loadHistory();
            check(loaded == 2, "AM3 loadHistory 回读到 2 条", QString::number(loaded));
            const Tasks::TaskId next = manager.begin(Tasks::TaskKind::Download,
                                                     QStringLiteral("新的"));
            check(next > 2, "AM3 新发的号在盘上那些之后（不撞号）",
                  QStringLiteral("新号 %1（盘上最大 2）").arg(next));
        }

        // 「没跑完的读回来算已中断」：另起一个账本写一份**没跑完**的（begin 之后就丢下）。
        const QString halfPath = dir.filePath(QStringLiteral("half.tasks"));
        {
            Tasks::TaskManager writer;
            writer.setHistoryPath(halfPath);
            writer.begin(Tasks::TaskKind::Launch, QStringLiteral("启动 Z"));
            writer.saveHistory();
        }
        const QList<Tasks::TaskSnapshot> halfDone = Tasks::load(halfPath);
        check(halfDone.size() == 1 && halfDone.first().state == Tasks::TaskState::Interrupted,
              "AM3 盘上写着 Running（上次没跑完）⇒ 读回来是 Interrupted",
              QString::number(int(halfDone.isEmpty() ? Tasks::TaskState::Queued
                                                     : halfDone.first().state)));
        check(!halfDone.isEmpty() && !halfDone.first().finishedAt.isValid(),
              "AM3 已中断那一件**没有**结束时间戳（不许编一个「刚刚完成」出来）");
    }

    // ---------------------------------------------------------------------
    section("AM4. markInterrupted / clearFinished / 启动器级固定落点");
    // ---------------------------------------------------------------------
    {
        // markInterrupted：只动非终态那几件；终态一个字节都不碰。
        QList<Tasks::TaskSnapshot> tasks;
        Tasks::TaskSnapshot running;
        running.id = 1;
        running.state = Tasks::TaskState::Running;
        running.finishedAt = QDateTime::fromString(QStringLiteral("2026-10-12 10:00:00"),
                                                   QStringLiteral("yyyy-MM-dd HH:mm:ss"));
        Tasks::TaskSnapshot waiting;
        waiting.id = 2;
        waiting.state = Tasks::TaskState::WaitingUser;
        Tasks::TaskSnapshot succeeded;
        succeeded.id = 3;
        succeeded.state = Tasks::TaskState::Succeeded;
        succeeded.finishedAt = QDateTime::fromString(QStringLiteral("2026-10-12 09:00:00"),
                                                     QStringLiteral("yyyy-MM-dd HH:mm:ss"));
        tasks << running << waiting << succeeded;
        Tasks::markInterrupted(tasks);
        check(tasks.at(0).state == Tasks::TaskState::Interrupted &&
                  tasks.at(1).state == Tasks::TaskState::Interrupted,
              "AM4 非终态那两件都成了已中断");
        check(!tasks.at(0).finishedAt.isValid(),
              "AM4 原来那个时间戳也被清掉（它说的是「上次开始」，不是「什么时候完的」）");
        check(tasks.at(2).state == Tasks::TaskState::Succeeded &&
                  tasks.at(2).finishedAt.isValid(),
              "AM4 已经收尾的那件一个字节都不动",
              tasks.at(2).finishedAt.toString(Qt::ISODate));

        // clearFinished：终态的走掉、活动状态留下。
        QTemporaryDir dir;
        if (!dir.isValid()) {
            check(false, "AM4 建临时目录");
            return;
        }
        Tasks::TaskManager manager;
        manager.setHistoryPath(dir.filePath(QStringLiteral("wtfml.tasks")));
        const Tasks::TaskId active = manager.begin(Tasks::TaskKind::Download,
                                                   QStringLiteral("还在跑"));
        const Tasks::TaskId done = manager.begin(Tasks::TaskKind::Download,
                                                 QStringLiteral("跑完了"));
        manager.succeed(done);
        check(manager.finished().size() == 1 && manager.active().size() == 1,
              "AM4 清之前：一件已完成、一件在跑");
        int historySignals = 0;
        QObject::connect(&manager, &Tasks::TaskManager::historyChanged,
                         [&historySignals]() { ++historySignals; });
        manager.clearFinished();
        check(manager.finished().isEmpty() && manager.active().size() == 1 &&
                  manager.has(active) && !manager.has(done),
              "AM4 清之后：已完成那件没了、「在跑」那件还在");
        check(historySignals == 1, "AM4 清了一回 ⇒ historyChanged 发一次",
              QString::number(historySignals));
        manager.clearFinished();  // 已经没有已完成的了
        check(historySignals == 1,
              "AM4 再清一次（没有可清的了）⇒ 一个信号都不发、也不白落一次盘",
              QString::number(historySignals));

        // 任务账本属于启动器，不属于当前选中的某一份 .minecraft。
        check(Tasks::defaultHistoryPath() ==
                  AppPaths::defaultMinecraftDir() + QStringLiteral("/wtfml.tasks"),
              "AM4 默认落点 = <启动器自带数据目录>/wtfml.tasks", Tasks::defaultHistoryPath());
        const QString originalRoot = AppPaths::minecraftDir();
        AppPaths::setMinecraftDir(dir.filePath(QStringLiteral("另一份游戏目录")));
        check(Tasks::defaultHistoryPath() ==
                  AppPaths::defaultMinecraftDir() + QStringLiteral("/wtfml.tasks"),
              "AM4 切换当前游戏文件夹不会改变任务账本路径", Tasks::defaultHistoryPath());
        AppPaths::setMinecraftDir(originalRoot == AppPaths::defaultMinecraftDir() ? QString()
                                                                                  : originalRoot);
        Tasks::TaskManager lazy;
        check(lazy.historyPath() == Tasks::defaultHistoryPath(),
              "AM4 没被指过路 ⇒ historyPath() 使用启动器级默认账本", lazy.historyPath());
        const QString other = dir.filePath(QStringLiteral("换个地方.tasks"));
        lazy.setHistoryPath(other);
        check(lazy.historyPath() == other, "AM4 指过之后就按指的来", lazy.historyPath());
        lazy.setHistoryPath(QString());
        check(lazy.historyPath() == Tasks::defaultHistoryPath(),
              "AM4 指回空串 = 回到默认那一份（不是「写到空路径去」）", lazy.historyPath());
    }
}

static void runCopyInstanceAndWorldTests() {
    const QString originalDir = AppPaths::minecraftDir();
    QTemporaryDir sourceRoot;
    QTemporaryDir destRoot;
    QTemporaryDir scratch;
    check(sourceRoot.isValid() && destRoot.isValid() && scratch.isValid(),
          "ZJ0 三个临时目录建出来了");

    AppPaths::setMinecraftDir(sourceRoot.path());

    // ---------------------------------------------------------------------
    section("ZJ1. looksLikeWorld：凭什么认一个目录是「世界」");
    // ---------------------------------------------------------------------
    {
        const QString world = scratch.path() + QStringLiteral("/有leveldat");
        QDir().mkpath(world + QStringLiteral("/region"));
        writeFileAt(world + QStringLiteral("/level.dat"), "nbt");
        check(WorldFiles::looksLikeWorld(world), "ZJ1 有 level.dat 就算世界");

        const QString bare = scratch.path() + QStringLiteral("/没leveldat");
        QDir().mkpath(bare + QStringLiteral("/region"));
        check(!WorldFiles::looksLikeWorld(bare),
              "ZJ1 没 level.dat 的不算（region/ 空着不算数：刚建好的世界 region 就是空的）");

        // ★ 这一条是"用户挑错了"那一档里最容易漏的：他把 `level.dat` **这个文件**选进来了
        //   （原生选择框在 Windows 上是可以选文件的）。判据只看"这个路径下面有没有
        //   level.dat"，`<...>/level.dat/level.dat` 当然不存在 ⇒ 判 false，正是要的结果。
        check(!WorldFiles::looksLikeWorld(world + QStringLiteral("/level.dat")),
              "ZJ1 传进来一个文件（level.dat 本身）也不算世界");
    }

    // ---------------------------------------------------------------------
    section("ZJ2. nameProblem：世界目录名和实例目录名同一套规矩");
    // ---------------------------------------------------------------------
    check(WorldFiles::nameProblem(QStringLiteral("我的世界")).isEmpty(),
          "ZJ2 普通中文名字过");
    check(!WorldFiles::nameProblem(QStringLiteral("a/b")).isEmpty(), "ZJ2 带分隔符不过");
    check(!WorldFiles::nameProblem(QStringLiteral("a\\b")).isEmpty(), "ZJ2 带反斜杠不过");
    check(!WorldFiles::nameProblem(QString()).isEmpty(), "ZJ2 空名字不过");
    check(!WorldFiles::nameProblem(QStringLiteral("CON")).isEmpty(),
          "ZJ2 Windows 保留设备名不过（建不出目录来）");
    check(!WorldFiles::nameProblem(QStringLiteral("以点结尾.")).isEmpty(), "ZJ2 尾随点不过");
    check(!WorldFiles::nameProblem(QString(65, QLatin1Char('x'))).isEmpty(), "ZJ2 超过 64 个字符不过");
    // 复用 InstanceFiles::validateDirName() 的**证据**：两边对同一个输入给出同一句话
    // ——"同一套规矩"这句话只有这么钉才不是一句空话。
    check(WorldFiles::nameProblem(QStringLiteral("CON")) ==
              InstanceFiles::validateDirName(QStringLiteral("CON")),
          "ZJ2 和 InstanceFiles::validateDirName 逐字同源（不是各写一套）");

    // ---------------------------------------------------------------------
    section("ZJ3. copyWorldInto：把一个世界拷进 saves/");
    // ---------------------------------------------------------------------
    const QString saves = scratch.path() + QStringLiteral("/saves");
    const QString worldSrc = scratch.path() + QStringLiteral("/外面的世界");
    QDir().mkpath(saves);
    QDir().mkpath(worldSrc + QStringLiteral("/region"));
    writeFileAt(worldSrc + QStringLiteral("/level.dat"), "level-bytes");
    writeFileAt(worldSrc + QStringLiteral("/region/r.0.mca"), "region-bytes");
    writeFileAt(worldSrc + QStringLiteral("/.hidden"), "hidden-bytes");
    {
        QString error;
        check(WorldFiles::copyWorldInto(worldSrc, saves, QStringLiteral("搬进来的"), &error),
              "ZJ3 正常拷一份成功", error);
        const QString dest = saves + QStringLiteral("/搬进来的");
        check(existsAt(dest + QStringLiteral("/level.dat")) &&
                  existsAt(dest + QStringLiteral("/region/r.0.mca")),
              "ZJ3 level.dat 和 region 里的东西都过去了");
        // 隐藏文件（带隐藏属性位、或者名字以点开头）漏掉的症状是"世界能开，但少东西"
        // —— 而用户看不出少的是哪一个。这一位在删树那头也要，拷这一头同样要。
        check(existsAt(dest + QStringLiteral("/.hidden")), "ZJ3 隐藏文件也过去了（一个不落）");
        QFile f(dest + QStringLiteral("/region/r.0.mca"));
        QByteArray got;
        if (f.open(QIODevice::ReadOnly)) {
            got = f.readAll();
        }
        check(got == QByteArray("region-bytes"), "ZJ3 拷过去的字节逐字节一致");
        check(WorldFiles::looksLikeWorld(dest), "ZJ3 拷出来的那一份自己也是一个世界");
    }
    {
        // 重名：**绝不能**合并。这里连"原来那份一个字节都没动"一起钉住 —— 挡住重名的
        // 意义就在这儿，只判"返回了 false"的话，把旧内容覆盖掉也算通过。
        writeFileAt(saves + QStringLiteral("/搬进来的/其他文件.txt"), "老内容");
        QString error;
        check(!WorldFiles::copyWorldInto(worldSrc, saves, QStringLiteral("搬进来的"), &error),
              "ZJ3 目标重名就拒绝");
        check(error.contains(QStringLiteral("已经有一个叫")), "ZJ3 说清了是被重名挡住", error);
        QFile f(saves + QStringLiteral("/搬进来的/其他文件.txt"));
        QByteArray got;
        if (f.open(QIODevice::ReadOnly)) {
            got = f.readAll();
        }
        check(got == QByteArray("老内容"), "ZJ3 被挡住时原来那一份一个字节都没动");
    }
    {
        // 名字不合法 / 源不是世界 / saves 不存在：三条都在**碰盘之前**挡掉。
        QString error;
        check(!WorldFiles::copyWorldInto(worldSrc, saves, QStringLiteral("a/b"), &error),
              "ZJ3 名字带分隔符拒绝");
        check(!error.isEmpty(), "ZJ3 且给了一句原因", error);
        check(!WorldFiles::copyWorldInto(worldSrc, saves, QString(), &error), "ZJ3 空名字拒绝");

        const QString notWorld = scratch.path() + QStringLiteral("/不是世界");
        QDir().mkpath(notWorld);
        check(!WorldFiles::copyWorldInto(notWorld, saves, QStringLiteral("试试"), &error),
              "ZJ3 源里没有 level.dat 拒绝（拿整个 .minecraft 当世界拷进来是最常见的点错）");
        check(error.contains(QStringLiteral("level.dat")), "ZJ3 原因里点名了 level.dat", error);
        check(!existsAt(saves + QStringLiteral("/试试")), "ZJ3 而且没在 saves 里留下一个空壳");

        const QString noSaves = scratch.path() + QStringLiteral("/根本没有saves");
        check(!WorldFiles::copyWorldInto(worldSrc, noSaves, QStringLiteral("试试"), &error),
              "ZJ3 目的地 saves 不存在也拒绝（不替他造一个）");
        check(!existsAt(noSaves), "ZJ3 而且没把那个 saves 建出来");
        check(!WorldFiles::copyWorldInto(saves + QStringLiteral("/搬进来的/level.dat"), saves,
                                         QStringLiteral("试试"), &error),
              "ZJ3 源传进来一个文件也拒绝");
    }

    // ---------------------------------------------------------------------
    section("ZJ4. renameWorld：改一个世界的目录名");
    // ---------------------------------------------------------------------
    {
        const QString dir = scratch.path() + QStringLiteral("/改名靶子");
        QDir().mkpath(dir + QStringLiteral("/region"));
        writeFileAt(dir + QStringLiteral("/level.dat"), "level-bytes");
        QString error;
        check(WorldFiles::renameWorld(dir, QStringLiteral("改过的"), &error), "ZJ4 改名成功", error);
        check(!existsAt(dir), "ZJ4 老目录不在了");
        check(existsAt(scratch.path() + QStringLiteral("/改过的/level.dat")),
              "ZJ4 新目录在、里面的东西也跟着过去了");
    }
    {
        const QString a = scratch.path() + QStringLiteral("/甲");
        const QString b = scratch.path() + QStringLiteral("/乙");
        QDir().mkpath(a);
        QDir().mkpath(b);
        writeFileAt(a + QStringLiteral("/level.dat"), "a");
        writeFileAt(b + QStringLiteral("/level.dat"), "b");
        QString error;
        check(!WorldFiles::renameWorld(a, QStringLiteral("乙"), &error), "ZJ4 重名拒绝");
        check(error.contains(QStringLiteral("已经有一个叫")), "ZJ4 原因说清了重名", error);
        check(existsAt(a + QStringLiteral("/level.dat")), "ZJ4 被挡住时老目录原样还在");
        QFile f(b + QStringLiteral("/level.dat"));
        QByteArray got;
        if (f.open(QIODevice::ReadOnly)) {
            got = f.readAll();
        }
        check(got == QByteArray("b"), "ZJ4 被挡住时同名的那一份也没被动过");

        // 名字逐字一样 = 用户没改（那一格回车了一遍）。**算成功、不动盘**，不是报错。
        check(WorldFiles::renameWorld(a, QStringLiteral("甲"), &error),
              "ZJ4 名字没变算成功（那不是「重名」，是没改）", error);
        check(existsAt(a), "ZJ4 而且那个目录还在原地");
        check(!WorldFiles::renameWorld(a, QStringLiteral("a/b"), &error),
              "ZJ4 不合法的名字拒绝");
        check(!WorldFiles::renameWorld(scratch.path() + QStringLiteral("/没有这个"), QStringLiteral("x"),
                                       &error),
              "ZJ4 源已经不在盘上时拒绝");
    }
    {
        // 只差大小写：Windows 的文件系统不区分大小写，`Foo` → `foo` 改的是**磁盘上那个
        // 名字的显示大小写**，是合法操作。判据里那一句「恰好等于现名的那一项不参与重名
        // 比较」就是为它留的 —— 少了那一句，这里会被自己挡住。
        const QString dir = scratch.path() + QStringLiteral("/CaseOnly");
        QDir().mkpath(dir);
        writeFileAt(dir + QStringLiteral("/level.dat"), "x");
        QString error;
        check(WorldFiles::renameWorld(dir, QStringLiteral("caseonly"), &error),
              "ZJ4 只差大小写的改名是合法的", error);
        check(QDir(scratch.path()).entryList(QDir::Dirs | QDir::NoDotAndDotDot)
                  .contains(QStringLiteral("caseonly")),
              "ZJ4 盘上那个名字的大小写真的变了",
              QDir(scratch.path()).entryList(QDir::Dirs | QDir::NoDotAndDotDot).join(QLatin1Char(',')));
    }

    // ---------------------------------------------------------------------
    section("ZJ5. VersionManager::copyInstance：多出一份实例");
    // ---------------------------------------------------------------------
    AppPaths::setMinecraftDir(sourceRoot.path());
    const QString srcId = QStringLiteral("源实例");
    const QString srcDir = makeInstanceDir(sourceRoot.path() + QStringLiteral("/versions"), srcId,
                                           R"({"name":"源实例","instanceId":"source-uuid-1111","loaderName":"Fabric"})");
    const QString destRootPath = destRoot.path();
    VersionManager vm;
    {
        QString error;
        check(vm.copyInstance(srcId, destRootPath, QStringLiteral("副本"), &error),
              "ZJ5 正常复制成功", error);
        const QString dest = destRootPath + QStringLiteral("/versions/副本");
        check(existsAt(dest), "ZJ5 副本落在 <目标游戏文件夹>/versions/<名字> 下");
        check(existsAt(dest + QStringLiteral("/副本.jar")) &&
                  existsAt(dest + QStringLiteral("/副本.json")),
              "ZJ5 jar / json 跟着目录名改了（不改的话列表里根本认不出它）");
        check(!existsAt(dest + QLatin1Char('/') + srcId + QStringLiteral(".jar")) &&
                  !existsAt(dest + QLatin1Char('/') + srcId + QStringLiteral(".json")),
              "ZJ5 老名字那一份没留下（是改名不是多拷一份）");
        check(existsAt(dest + QStringLiteral("/mods/sodium.jar")) &&
                  existsAt(dest + QStringLiteral("/saves/我的世界/level.dat")),
              "ZJ5 嵌套目录也原样带过去了（模组、存档一起走）");
        check(existsAt(srcDir + QLatin1Char('/') + srcId + QStringLiteral(".jar")),
              "ZJ5 源一个字节都没动（这一条是整件事的底线）");

        const QJsonObject meta = readMetaAt(dest);
        check(meta.value(QStringLiteral("name")).toString() == QStringLiteral("副本"),
              "ZJ5 副本的 wtfml.meta 里显示名换成新的了",
              meta.value(QStringLiteral("name")).toString());
        const QString newId = meta.value(QStringLiteral("instanceId")).toString();
        check(!newId.isEmpty() && newId != QStringLiteral("source-uuid-1111"),
              "ZJ5 副本拿到一个**全新的**稳定 id（沿用源的话分组/图标会把两份认成一份）", newId);
        check(meta.value(QStringLiteral("loaderName")).toString() == QStringLiteral("Fabric"),
              "ZJ5 别的字段原样留着（只动 name 和 instanceId）");
        check(readMetaAt(srcDir).value(QStringLiteral("instanceId")).toString() ==
                  QStringLiteral("source-uuid-1111"),
              "ZJ5 源那份 meta 也没被动过");
    }
    {
        // 目标文件夹里还没有 versions/ —— 要自己建出来（用户挑一个从没跑过游戏的新文件夹
        // 是常态）。这一条和上面那个"已经有了"是两回事。
        const QString fresh = scratch.path() + QStringLiteral("/新游戏文件夹");
        QDir().mkpath(fresh);
        QString error;
        check(vm.copyInstance(srcId, fresh, QStringLiteral("第一份"), &error),
              "ZJ5 目标里还没有 versions/ 时也成（自己建出来）", error);
        check(existsAt(fresh + QStringLiteral("/versions/第一份/第一份.jar")),
              "ZJ5 而且落在新建的 versions/ 下面");
    }
    {
        QString error;
        check(!vm.copyInstance(srcId, destRootPath, QStringLiteral("副本"), &error),
              "ZJ5 目标重名拒绝");
        check(error.contains(QStringLiteral("已经有一个叫")), "ZJ5 原因说清了重名", error);

        // 挑的就是自己那一份所在的那个游戏文件夹 + 同一个名字：真正的原因是"那就是它自己"，
        // 不能报成"已经有一个叫 X 的实例了"（用户会以为盘上真有两份）。
        check(!vm.copyInstance(srcId, sourceRoot.path(), srcId, &error),
              "ZJ5 目标是源自己那一份拒绝");
        check(error.contains(QStringLiteral("就是这一份自己")), "ZJ5 而且原因说的是这话", error);

        // ★★ 目标落在**源实例目录自己里面** → 拒（2026-09-29 补的第四道闸）。这一条在数据
        //    层是兜底（界面那一层也有一条，用的是同一个 InstanceFiles::pathIsSameOrInside），
        //    但**必须自己站得住**：不然将来任何一个别的调用点喂进来一个这样的目标，下面那步
        //    mkpath(versionsDir) 就会在源实例目录内部造出一个 `versions/`，紧接着"先 mkpath
        //    目标、再列源目录"的复制会把它自己刚造的这一层也列进去 —— **自己抄自己、每层再
        //    深一层**，一声不响地写到盘满。
        check(!vm.copyInstance(srcId, srcDir, QStringLiteral("里面"), &error),
              "★★ ZJ5 目标就是源实例目录自己拒绝（判据比的是规范化之后的真路径）");
        // 注意别把整个句子当成一截 —— 实例名是插在中间那句里的（「不能把「X」复制到它自己
        // 里面去」），所以只挑不被名字隔开的那半截来比。
        check(error.contains(QStringLiteral("复制到它自己里面去")),
              "ZJ5 而且原因说的是这话", error);
        check(!existsAt(srcDir + QStringLiteral("/versions")),
              "★★ ZJ5 拒绝之后**源实例目录里没多出任何东西**（老代码会在这儿造出 "
              "`versions/`，那就是递归的第一层）");
        check(!vm.copyInstance(srcId, srcDir + QStringLiteral("/saves"), QStringLiteral("更里面"),
                               &error),
              "★★ ZJ5 挑的是它**底下**的子目录也一样拒（判的是「是不是在里面」）");
        check(!existsAt(srcDir + QStringLiteral("/saves/versions")),
              "★ ZJ5 同样是「盘上没多出东西来」");

        // ★★ 别名：拿一个**指着源实例目录的 junction** 当游戏文件夹。
        //
        //    这一条是 2026-09-29 实测补上的：`canonicalFilePath()` **不解 junction**
        //    （Windows 上它走 `slowCanonicalized()`、逐段判的是 `isSymLink()`，而 junction 在
        //    Qt 里是 `JunctionType`；见 InstanceFiles.cpp 里 resolveJunctions() 那一大段）。
        //    只靠 canonicalFilePath 的话，这一条会让复制真的跑起来（自己抄自己，直到撞上路径
        //    长度上限才失败）—— 那时 `!ok` 还是绿的，是个**假绿**，而盘上已经多出一层
        //    `versions/`。所以下面同时钉住"报的是哪一句"。
        //
        //    NOTE: junction 必须**最后**清掉、而且只能 rmdir（删链接本体，不动它那一头）；
        //          `QTemporaryDir::removeRecursively()` 是会**跟着** junction 往下删的。
        const QString aliasHost = scratch.path() + QStringLiteral("/别名宿主");
        QDir().mkpath(aliasHost);
        const QString aliasDir = aliasHost + QStringLiteral("/指到源实例");
        const bool madeAlias =
            QProcess::execute(QStringLiteral("cmd"),
                              {QStringLiteral("/c"), QStringLiteral("mklink"), QStringLiteral("/J"),
                               QDir::toNativeSeparators(aliasDir),
                               QDir::toNativeSeparators(srcDir)}) == 0
            && QFileInfo(aliasDir).isJunction();
        check(madeAlias, "★ ZJ5 先造出一个真 junction 指着源实例目录（mklink /J）");
        if (madeAlias) {
            // NOTE: 前置事实 —— canonicalFilePath **不**解 junction。这一条要是红了，
            //       说明 Qt 那边换了实现（那时候 resolveJunctions 可以删，但先得有人复核）。
            check(QDir::cleanPath(QFileInfo(aliasDir).canonicalFilePath())
                      != QDir::cleanPath(QFileInfo(srcDir).canonicalFilePath()),
                  "★ ZJ5 前置事实：canonicalFilePath 解不掉 junction（这一位就是那个洞的出处）",
                  QFileInfo(aliasDir).canonicalFilePath());
            check(!vm.copyInstance(srcId, aliasDir, QStringLiteral("别名副本"), &error),
                  "★★ ZJ5 目标是**指着源实例目录的 junction** 也拒（判的是它真指着哪儿）", error);
            check(error.contains(QStringLiteral("复制到它自己里面去")),
                  "★ ZJ5 而且拒的是那一道闸，不是「跑下去撞了墙才失败」", error);
            check(!existsAt(srcDir + QStringLiteral("/versions")),
                  "★★ ZJ5 拒绝之后源实例目录里还是没多出东西来（假绿的出处就在这一格）");
            QProcess::execute(QStringLiteral("cmd"),
                              {QStringLiteral("/c"), QStringLiteral("rmdir"),
                               QDir::toNativeSeparators(aliasDir)});
        }

        check(!vm.copyInstance(srcId, destRootPath, QStringLiteral("a/b"), &error),
              "ZJ5 名字不合法拒绝");
        check(!vm.copyInstance(srcId, destRootPath, QString(), &error), "ZJ5 空名字拒绝");
        check(!vm.copyInstance(QString(), destRootPath, QStringLiteral("x"), &error),
              "ZJ5 空的源 id 拒绝（拼出来是 versions/ 本身）");
        check(!vm.copyInstance(srcId, scratch.path() + QStringLiteral("/不在盘上"), QStringLiteral("x"),
                               &error),
              "ZJ5 目标游戏文件夹不存在拒绝");
        check(!vm.copyInstance(srcId, QString(), QStringLiteral("x"), &error),
              "ZJ5 空的「复制到哪儿」拒绝 —— 空串会被 QDir 当成当前工作目录，那不是用户挑的地方");
    }
    {
        // ★★ 最后一步失败时**把自己刚拷出来的半份删掉**（和整合包导入那条"失败不删半成品"
        //    故意相反）。造法：源里那份 wtfml.meta 是坏 JSON ⇒ 拷完树、改完 jar/json 之后
        //    卡在第 4 步。这一条同时钉住两件事：那一趟**返回 false**，以及目标目录
        //    **没留在盘上**（判据必须看盘，不能只看返回值 —— 半份留着才是真正的坑）。
        const QString badId = QStringLiteral("坏meta");
        makeInstanceDir(sourceRoot.path() + QStringLiteral("/versions"), badId,
                        QByteArray("{ 这不是 JSON"));
        QString error;
        check(!vm.copyInstance(badId, destRootPath, QStringLiteral("半份"), &error),
              "ZJ5 源那份 meta 是坏 JSON 时这一趟失败");
        check(error.contains(QStringLiteral("合法的 JSON")), "ZJ5 原因说清了是 meta 读不懂", error);
        check(!existsAt(destRootPath + QStringLiteral("/versions/半份")),
              "ZJ5 失败之后那份没拷完的自己删掉了（saves 里不该留一个来路不明的目录）");
    }

    AppPaths::setMinecraftDir(originalDir);  // 收摊
    check(AppPaths::minecraftDir() == originalDir, "ZJ6 数据根目录换回来了");

    // =====================================================================
    //  ZK. 服务端那八档：装法、地址、以及"装完之后入口是什么"
    // =====================================================================
    //  这一节全是**纯函数**：地址怎么拼、接口回复怎么读、装一份服务端的计划长什么样。
    //  一个请求都不发、一个文件都不读、一个字节都不写盘。
    //
    //  NOTE: 断言里那些地址原串是 2026-09-28 逐条 curl 出来的（形状连同响应头一起记在
    //        ServerInstall.hpp 的文件头）。**上游改了它们这里会红，红得对** —— 这一层存在的
    //        意义就是"别让一个改过期的地址活到用户点下去那一刻"。
    section("ZK1. 八档的身份：代号往返、认不出来不碰 out、顺序就是界面上的顺序");
    {
        using namespace ServerInstall;
        const QList<Flavor> flavors = allFlavors();
        check(flavors.size() == 8, "ZK1 一共八档", QString::number(flavors.size()));

        QStringList roundTripBad;
        QStringList tokens;
        QStringList blankNames;
        bool allNamesOk = true;
        bool allNotesOk = true;
        for (Flavor flavor : flavors) {
            const QString token = flavorToken(flavor);
            tokens.append(token);
            if (flavorName(flavor).isEmpty()) {
                allNamesOk = false;
            }
            if (flavorNote(flavor).isEmpty()) {
                allNotesOk = false;
            }
            Flavor back = Flavor::Spigot;  // 先塞一个"错"的，看它会不会被写坏
            if (!flavorFromToken(token, &back) || back != flavor) {
                roundTripBad.append(token);
            }
        }
        check(roundTripBad.isEmpty(), "ZK1 八档代号逐条往返（token -> Flavor -> token）",
              roundTripBad.join(QStringLiteral(", ")));
        check(QSet<QString>(tokens.begin(), tokens.end()).size() == tokens.size(),
              "ZK1 八个代号互不相同（撞了的话盘上两份服务端会被认成同一档）",
              tokens.join(QStringLiteral(" ")));
        check(allNamesOk, "ZK1 八档都有界面上那个名字");
        check(allNotesOk, "ZK1 八档都有那行小字（界面别自己另写一套 —— 这是唯一出处）");

        Flavor kept = Flavor::Purpur;
        check(!flavorFromToken(QStringLiteral("Vanilla"), &kept) && kept == Flavor::Purpur,
              "ZK1 大小写不对就不认（代号是持久化格式，不能「宽容」到把两种写法都收下）");
        check(!flavorFromToken(QString(), &kept) && kept == Flavor::Purpur,
              "ZK1 空串回 false，而且**不碰 out**");
        check(flavorFromToken(QStringLiteral("paper"), nullptr),
              "ZK1 out 给 nullptr 也不崩（只想知道「认不认得」时会这么用）");

        check(flavors.first() == Flavor::Vanilla && flavors.last() == Flavor::Spigot,
              "ZK1 首尾是原版和 Spigot —— allFlavors() 这个顺序就是界面上列出来的顺序");
    }

    section("ZK2. 装法：八档各是哪一种，那句小字是什么");
    {
        using namespace ServerInstall;
        check(installMethod(Flavor::Vanilla) == InstallMethod::DirectJar &&
                  installMethod(Flavor::Paper) == InstallMethod::DirectJar &&
                  installMethod(Flavor::Purpur) == InstallMethod::DirectJar &&
                  installMethod(Flavor::Fabric) == InstallMethod::DirectJar,
              "ZK2 原版 / Paper / Purpur / Fabric：下下来那个 jar 就能跑");
        check(installMethod(Flavor::Forge) == InstallMethod::RunInstaller &&
                  installMethod(Flavor::NeoForge) == InstallMethod::RunInstaller &&
                  installMethod(Flavor::Quilt) == InstallMethod::RunInstaller,
              "ZK2 Forge / NeoForge / Quilt：下下来的是安装器，要在安装目录里跑一次");
        check(installMethod(Flavor::Spigot) == InstallMethod::BuildRequired,
              "ZK2 Spigot：官方不发成品，得现编");

        const QString direct = installMethodText(InstallMethod::DirectJar);
        const QString run = installMethodText(InstallMethod::RunInstaller);
        const QString build = installMethodText(InstallMethod::BuildRequired);
        check(!direct.isEmpty() && !run.isEmpty() && !build.isEmpty() && direct != run &&
                  run != build && direct != build,
              "ZK2 三句话都不空、互相不一样");
    }

    section("ZK3. 地址怎么拼（原串是 2026-09-28 实测量到的）");
    {
        using namespace ServerInstall;
        check(paperBuildsUrl(QStringLiteral("1.21.4")) ==
                  QStringLiteral("https://fill.papermc.io/v3/projects/paper/versions/1.21.4/builds"),
              "ZK3 Paper 构建列表（旧接口 api.papermc.io/v2 已经 410 下线，别照老教程写）",
              paperBuildsUrl(QStringLiteral("1.21.4")));
        check(paperProjectUrl() == QStringLiteral("https://fill.papermc.io/v3/projects/paper"),
              "ZK3 Paper 工程信息");
        check(purpurVersionsUrl() == QStringLiteral("https://api.purpurmc.org/v2/purpur"),
              "ZK3 Purpur 版本清单");
        check(purpurLatestUrl(QStringLiteral("1.21.4")) ==
                  QStringLiteral("https://api.purpurmc.org/v2/purpur/1.21.4/latest"),
              "ZK3 Purpur 最新一条");
        check(purpurDownloadUrl(QStringLiteral("1.21.4"), QStringLiteral("latest")) ==
                  QStringLiteral("https://api.purpurmc.org/v2/purpur/1.21.4/latest/download"),
              "ZK3 Purpur 下载：latest 真的能这么用（实测 200）",
              purpurDownloadUrl(QStringLiteral("1.21.4"), QStringLiteral("latest")));
        check(purpurDownloadUrl(QStringLiteral("1.21.4"), QStringLiteral("2416")) ==
                  QStringLiteral("https://api.purpurmc.org/v2/purpur/1.21.4/2416/download"),
              "ZK3 Purpur 下载：具体构建号");

        const QString fabricJar = fabricServerJarUrl(QStringLiteral("1.21.4"),
                                                     QStringLiteral("0.16.9"),
                                                     QStringLiteral("1.0.1"));
        check(fabricJar == QStringLiteral("https://meta.fabricmc.net/v2/versions/loader/"
                                          "1.21.4/0.16.9/1.0.1/server/jar"),
              "ZK3 Fabric 服务端 jar", fabricJar);
        check(fabricJar.contains(QStringLiteral("/loader/1.21.4/0.16.9/1.0.1/")) &&
                  fabricJar.endsWith(QStringLiteral("/server/jar")),
              "ZK3 ★ Fabric 那条里游戏版本、加载器、安装器三段都在 —— 少任何一段上游就是 404"
              "（少了 loader 段和少了 installer 段两种都实测过）");
        check(fabricInstallerListUrl() ==
                  QStringLiteral("https://meta.fabricmc.net/v2/versions/installer"),
              "ZK3 Fabric 安装器列表");

        check(quiltInstallerMetadataUrl() ==
                  QStringLiteral("https://maven.quiltmc.org/repository/release/org/quiltmc/"
                                 "quilt-installer/maven-metadata.xml"),
              "ZK3 Quilt 安装器清单");
        check(quiltInstallerUrl(QStringLiteral("0.15.1")) ==
                  QStringLiteral("https://maven.quiltmc.org/repository/release/org/quiltmc/"
                                 "quilt-installer/0.15.1/quilt-installer-0.15.1.jar"),
              "ZK3 Quilt 安装器 jar");

        check(spigotBuildToolsUrl() ==
                  QStringLiteral("https://hub.spigotmc.org/jenkins/job/BuildTools/"
                                 "lastSuccessfulBuild/artifact/target/BuildTools.jar"),
              "ZK3 Spigot 的 BuildTools（「最后一次成功的构建」—— 今天编和下周编不是同一个文件）",
              spigotBuildToolsUrl());
    }

    section("ZK4. Paper 的构建列表怎么读（形状是 2026-09-28 实测的）");
    {
        using namespace ServerInstall;
        const auto makeBuild = [](int id, const char *channel, const char *name, const char *sha,
                                  double size) {
            const QString fileName = QString::fromLatin1(name);
            const QJsonObject file{
                {QStringLiteral("name"), fileName},
                {QStringLiteral("url"), QStringLiteral("https://fill-data.example/") + fileName},
                {QStringLiteral("checksums"),
                 QJsonObject{{QStringLiteral("sha256"), QString::fromLatin1(sha)}}},
                {QStringLiteral("size"), size}};
            return QJsonObject{
                {QStringLiteral("id"), id},
                {QStringLiteral("channel"), QString::fromLatin1(channel)},
                {QStringLiteral("downloads"),
                 QJsonObject{{QStringLiteral("server:default"), file}}}};
        };

        QJsonArray raw;
        raw.append(makeBuild(1, "ALPHA", "paper-1.21.4-1.jar", "aaa", 52673513));
        raw.append(makeBuild(2, "ALPHA", "paper-1.21.4-2.jar", "bbb", 52673514));
        raw.append(makeBuild(3, "STABLE", "paper-1.21.4-3.jar", "ccc", 52673515));
        // 上游真会给这种：那个构建的东西被撤了，downloads 是空的。
        raw.append(QJsonObject{{QStringLiteral("id"), 4},
                               {QStringLiteral("channel"), QStringLiteral("STABLE")},
                               {QStringLiteral("downloads"), QJsonObject{}}});

        const QList<Build> list = paperBuildsFromJson(raw);
        check(list.size() == 3, "ZK4 没有可下文件的那一条被跳过", QString::number(list.size()));
        check(!list.isEmpty() && list.first().number == 3 && list.last().number == 1,
              "ZK4 排成新到旧（上游回的是升序：实测 224 条，头一条 id=1）",
              list.isEmpty() ? QString()
                             : QStringLiteral("%1 .. %2").arg(list.first().number).arg(list.last().number));
        check(!list.isEmpty() && list.first().sha256 == QStringLiteral("ccc") &&
                  list.first().size == 52673515 &&
                  list.first().fileName == QStringLiteral("paper-1.21.4-3.jar"),
              "ZK4 校验值 / 大小 / 上游那个文件名三样都读出来了",
              list.isEmpty() ? QString() : list.first().sha256);
        check(!list.isEmpty() && list.first().channel == QStringLiteral("STABLE"),
              "ZK4 频道原样留着（界面上要标「这是测试版」就靠它）");

        const Build mixed{0, QStringLiteral("stable"), {}, QStringLiteral("u"), {}, {}, -1};
        check(!list.isEmpty() && paperBuildIsStable(list.first()) && paperBuildIsStable(mixed),
              "ZK4 判 stable 不看大小写（上游现在写的大写，别为这个留个坑）");
        check(!paperBuildIsStable(Build{0, QStringLiteral("ALPHA"), {}, QStringLiteral("u"), {}, {}, -1}),
              "ZK4 ALPHA 不是稳定档");

        check(pickPaperBuild(list, true).number == 3, "ZK4 挑稳定档：最新那条 STABLE");
        check(pickPaperBuild(list, false).number == 3, "ZK4 挑最新档：就是最新那条");

        // 新游戏版本刚上的那几天上游只有 ALPHA（真会这样）：
        QJsonArray alphaOnly;
        alphaOnly.append(makeBuild(1, "ALPHA", "paper-x-1.jar", "a", 1));
        const QList<Build> alphaList = paperBuildsFromJson(alphaOnly);
        check(pickPaperBuild(alphaList, true).number == 1,
              "ZK4 只有 ALPHA 时「稳定档」退回最新那条 —— 不许挑不出来（挑不出来这一档就整个废掉）");
        check(!pickPaperBuild(QList<Build>(), true).ok() &&
                  !pickPaperBuild(QList<Build>(), false).ok(),
              "ZK4 空列表 -> 空那一条，ok() 为 false");

        const QJsonObject project{
            {QStringLiteral("project"),
             QJsonObject{{QStringLiteral("id"), QStringLiteral("paper")}}},
            {QStringLiteral("versions"),
             QJsonObject{
                 {QStringLiteral("1.21"),
                  QJsonArray{QStringLiteral("1.21.11"), QStringLiteral("1.21.4"),
                             QStringLiteral("1.21.4")}},
                 {QStringLiteral("1.20"),
                  QJsonArray{QStringLiteral("1.20.6"), QStringLiteral("1.20.1")}}}}};
        const QStringList versions = paperVersionsFromJson(project);
        check(versions.size() == 4, "ZK4 工程信息摊平成一维并去掉重复",
              versions.join(QStringLiteral(" ")));
        // ★ 这条是**自己排出来的**，不是原序：上游那个对象走到这一层时键已经按字典序排过
        //   （QJsonObject 就是这么存的），照原序摊平出来是 `1.20.6 1.20.1 1.21.11 1.21.4`
        //   —— 正好是反的。真实数据里 `1.21` 还会排在 `26.1` 前面（字典序 `1` < `2`），
        //   拿它当"新到旧"用会挑中最老的版本。
        check(!versions.isEmpty() && versions.first() == QStringLiteral("1.21.11") &&
                  versions.last() == QStringLiteral("1.20.1"),
              "ZK4 ★ 摊平之后**自己排成新到旧**（1.21 那组排在 1.20 那组前面 —— "
              "字典序会把它排反）", versions.join(QStringLiteral(" ")));

        // 正式版排在它的 rc 前面：两个都解析成 [1,21,11]，只有 tie-break 能分开
        const QJsonObject withRc{
            {QStringLiteral("versions"),
             QJsonObject{{QStringLiteral("1.21"),
                          QJsonArray{QStringLiteral("1.21.11-rc3"), QStringLiteral("1.21.11")}}}}};
        const QStringList rcVersions = paperVersionsFromJson(withRc);
        check(rcVersions.size() == 2 && rcVersions.first() == QStringLiteral("1.21.11") &&
                  rcVersions.last() == QStringLiteral("1.21.11-rc3"),
              "ZK4 同一个版本号的正式版排在它的 rc 前面（沿用加载器那套 tie-break，"
              "界面上第一个不该是候选版）", rcVersions.join(QStringLiteral(" ")));
    }

    section("ZK5. Purpur 的两种回复：latest 那条和工程信息");
    {
        using namespace ServerInstall;
        const QJsonObject latest{{QStringLiteral("project"), QStringLiteral("purpur")},
                                 {QStringLiteral("version"), QStringLiteral("1.21.4")},
                                 {QStringLiteral("build"), QStringLiteral("2416")},
                                 {QStringLiteral("result"), QStringLiteral("SUCCESS")}};
        check(purpurBuildFromJson(latest) == QStringLiteral("2416"),
              "ZK5 从 latest 那条回复里读出构建号", purpurBuildFromJson(latest));

        QJsonObject numeric = latest;
        numeric.insert(QStringLiteral("build"), 2416);
        check(purpurBuildFromJson(numeric).isEmpty(),
              "ZK5 ★ build 写成数字而不是字符串时**当读不出来**，不许当成 2416 —— 按数字读会拼出"
              " /purpur/1.21.4/0/download，一路 404 而且看着像网络问题");

        QJsonObject failed = latest;
        failed.insert(QStringLiteral("result"), QStringLiteral("FAILURE"));
        check(purpurBuildFromJson(failed).isEmpty(),
              "ZK5 result 不是 SUCCESS 的那条不能下（上游会把失败那几条也报出来）");

        QJsonObject noBuild = latest;
        noBuild.remove(QStringLiteral("build"));
        check(purpurBuildFromJson(noBuild).isEmpty(), "ZK5 没有 build 字段那条也读不出来");
        check(purpurBuildFromJson(QJsonObject()).isEmpty(), "ZK5 空对象也读不出来（不崩）");

        const QJsonObject project{
            {QStringLiteral("project"), QStringLiteral("purpur")},
            {QStringLiteral("metadata"),
             QJsonObject{{QStringLiteral("current"), QStringLiteral("26.2")}}},
            {QStringLiteral("versions"),
             QJsonArray{QStringLiteral("1.21.11"), QStringLiteral("1.21.4"),
                        QStringLiteral("1.21.4"), QStringLiteral("1.8.9")}}};
        const QStringList versions = purpurVersionsFromJson(project);
        check(versions.size() == 3, "ZK5 Purpur 那份是**平铺**的一维数组（不是像 Paper 那样"
                                    "按大版本分组的），去重",
              versions.join(QStringLiteral(" ")));
        // ★ 上游那个数组是**按发布时间升序**的（实测尾部是 …1.21.11, 26.1.2, 26.2, 26.3），
        //   拿原序当"新到旧"用，界面上第一行会是它最老的那个版本。
        check(!versions.isEmpty() && versions.first() == QStringLiteral("1.21.11") &&
                  versions.last() == QStringLiteral("1.8.9"),
              "ZK5 ★ 排成新到旧（原序是升序，直接用就反了）",
              versions.join(QStringLiteral(" ")));
    }

    section("ZK6. Fabric 的安装器列表：挑一个出来才拼得出地址");
    {
        using namespace ServerInstall;
        const QJsonArray raw{
            QJsonObject{{QStringLiteral("url"),
                         QStringLiteral("https://maven.fabricmc.net/net/fabricmc/"
                                        "fabric-installer/1.1.2/fabric-installer-1.1.2.jar")},
                        {QStringLiteral("maven"),
                         QStringLiteral("net.fabricmc:fabric-installer:1.1.2")},
                        {QStringLiteral("version"), QStringLiteral("1.1.2")},
                        {QStringLiteral("stable"), true}},
            QJsonObject{{QStringLiteral("version"), QStringLiteral("1.1.1")},
                        {QStringLiteral("stable"), false}},
            QJsonObject{{QStringLiteral("stable"), true}}};  // 缺 version 的：跳过
        const LoaderVersionList installers = listFabricInstallerVersions(raw);
        check(installers.size() == 2, "ZK6 缺 version 的那一条被跳过",
              QString::number(installers.size()));
        check(!installers.isEmpty() && installers.first().version == QStringLiteral("1.1.2") &&
                  installers.first().stable,
              "ZK6 顺序原样保留（上游就是新到旧）+ stable 那个字段照读");
        check(pickFabricInstaller(raw, true) == QStringLiteral("1.1.2"),
              "ZK6 稳定档：第一条 stable 的");
        check(pickFabricInstaller(raw, false) == QStringLiteral("1.1.2"),
              "ZK6 最新档：就是第一条");

        const QJsonArray noStable{QJsonObject{{QStringLiteral("version"), QStringLiteral("2.0")},
                                              {QStringLiteral("stable"), false}}};
        check(pickFabricInstaller(noStable, true) == QStringLiteral("2.0"),
              "ZK6 一个 stable 都没有时退回最新那条 —— 挑不出来就拼不出地址，一整档废掉");
        check(pickFabricInstaller(QJsonArray(), true).isEmpty() &&
                  pickFabricInstaller(QJsonArray(), false).isEmpty(),
              "ZK6 空列表 -> 空串");
    }

    section("ZK7. Quilt 的安装器清单（maven 元数据）");
    {
        using namespace ServerInstall;
        const QByteArray xml = QByteArrayLiteral(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
            "<metadata>\n  <groupId>org.quiltmc</groupId>\n"
            "  <artifactId>quilt-installer</artifactId>\n  <versioning>\n"
            "    <latest>9.9.9</latest>\n    <release>9.9.9</release>\n    <versions>\n"
            "      <version>0.4.0</version>\n      <version>0.15.0</version>\n"
            "      <version>0.15.1</version>\n    </versions>\n  </versioning>\n</metadata>\n");
        const LoaderVersionList quilt = listQuiltInstallerVersions(xml);
        check(quilt.size() == 3, "ZK7 只扫 <version> 那一段（<latest>/<release> 不是版本号）",
              QStringLiteral("扫出 %1 条").arg(quilt.size()));
        check(!quilt.isEmpty() && quilt.first().version == QStringLiteral("0.15.1") &&
                  quilt.last().version == QStringLiteral("0.4.0"),
              "ZK7 排成新到旧（maven 清单是按发布时间排的，不排会挑中旧的那个）",
              quilt.isEmpty() ? QString() : quilt.first().version);
        check(!quilt.isEmpty() && quilt.first().version != QStringLiteral("9.9.9"),
              "ZK7 ★ <latest>/<release> 那两行不许被当成一个版本号收进来");

        const LoaderVersionList beta =
            listQuiltInstallerVersions(QByteArrayLiteral(
                "<versions><version>0.16.0-beta</version><version>0.16.0</version></versions>"));
        check(beta.size() == 2 && beta.first().stable && !beta.last().stable,
              "ZK7 stable 判据沿用 LoaderMeta 那一条：版本号里没有 - 也没有 +（不另写一套）；"
              "数字一样的两个**正式版排前面**（界面上第一个不该是 beta）",
              beta.isEmpty() ? QString() : beta.first().version);
        check(listQuiltInstallerVersions(QByteArrayLiteral("<metadata/>")).isEmpty(),
              "ZK7 一个 <version> 都没有 -> 空列表（不崩）");
    }

    section("ZK8. 八档各拼一份安装计划");
    {
        using namespace ServerInstall;
        Request base;
        base.gameVersion = QStringLiteral("1.21.4");
        base.loaderVersion = QStringLiteral("0.16.9");
        base.installerVersion = QStringLiteral("1.0.1");

        // ---- 原版 ----
        {
            Request request = base;
            request.flavor = Flavor::Vanilla;
            const Plan plan = planFor(request);
            check(plan.ok && plan.method == InstallMethod::DirectJar, "ZK8 原版：能装");
            check(plan.downloads.isEmpty(),
                  "ZK8 ★ 原版这一档的下载地址**不在这层**：它是版本 json 的一部分"
                  "（downloads.server，见 vanillaServerDownload）");
            check(plan.installedMarkers == QStringList{QStringLiteral("server.jar")} &&
                      plan.launchTokens == QStringList{QStringLiteral("-jar"),
                                                        QStringLiteral("server.jar"),
                                                        QStringLiteral("nogui")},
                  "ZK8 原版：装完看 server.jar，启动 java -jar server.jar nogui");
            check(!plan.firstLaunchNeedsNetwork, "ZK8 原版：那份 jar 是完整的，装完就能离线起");
            check(!plan.note.isEmpty(), "ZK8 原版：note 说清了地址去哪问", plan.note);
        }

        // ---- Paper ----
        {
            Request request = base;
            request.flavor = Flavor::Paper;
            request.buildId = QStringLiteral("232");
            const Plan plan = planFor(request);
            check(plan.ok && plan.method == InstallMethod::DirectJar, "ZK8 Paper：能装");
            check(plan.downloads.isEmpty(),
                  "ZK8 ★ Paper：给了构建号也**拼不出地址** —— 那条地址里的对象名带 sha256"
                  "（fill-data/objects/<sha256>/...），必须先把构建列表取回来");
            check(plan.installedMarkers == QStringList{QStringLiteral("server.jar")} &&
                      plan.launchTokens == QStringList{QStringLiteral("-jar"),
                                                        QStringLiteral("server.jar"),
                                                        QStringLiteral("nogui")},
                  "ZK8 Paper：装完看 server.jar，启动参数和原版一样");
            check(plan.note.contains(QStringLiteral("paperBuildsUrl")),
                  "ZK8 Paper：note 把「地址去哪问」点出来了（界面上要照着这句说）", plan.note);
        }

        // ---- Purpur ----
        {
            Request request = base;
            request.flavor = Flavor::Purpur;
            const Plan plan = planFor(request);
            check(plan.ok && plan.downloads.size() == 1 &&
                      plan.downloads.first().url ==
                          QStringLiteral("https://api.purpurmc.org/v2/purpur/1.21.4/latest/download") &&
                      plan.downloads.first().fileName == QStringLiteral("server.jar"),
                  "ZK8 Purpur：没给构建号就下 latest 那条（落地统一叫 server.jar）",
                  plan.downloads.isEmpty() ? QString() : plan.downloads.first().url);
            Request pinned = request;
            pinned.buildId = QStringLiteral("2416");
            const Plan pinnedPlan = planFor(pinned);
            check(pinnedPlan.downloads.size() == 1 &&
                      pinnedPlan.downloads.first().url ==
                          QStringLiteral("https://api.purpurmc.org/v2/purpur/1.21.4/2416/download"),
                  "ZK8 Purpur：给了构建号就下那一条",
                  pinnedPlan.downloads.isEmpty() ? QString() : pinnedPlan.downloads.first().url);
            check(plan.launchTokens == QStringList{QStringLiteral("-jar"),
                                                   QStringLiteral("server.jar"),
                                                   QStringLiteral("nogui")} &&
                      !plan.firstLaunchNeedsNetwork,
                  "ZK8 Purpur：那份 jar 是完整的服务端，装完就能离线起");
            check(!plan.downloads.isEmpty() && plan.downloads.first().sha1.isEmpty() &&
                      plan.downloads.first().sha256.isEmpty(),
                  "ZK8 ★ Purpur：两个校验字段都是空的（上游只在 latest 那条回复里给一个 md5）"
                  "—— 下载层要能接受「这一条没有校验值」，不能拿「没校验」当失败");
        }

        // ---- Fabric ----
        {
            Request request = base;
            request.flavor = Flavor::Fabric;
            const Plan plan = planFor(request);
            check(plan.ok && plan.downloads.size() == 1 &&
                      plan.downloads.first().url ==
                          QStringLiteral("https://meta.fabricmc.net/v2/versions/loader/"
                                         "1.21.4/0.16.9/1.0.1/server/jar"),
                  "ZK8 Fabric：那条三段都带的地址",
                  plan.downloads.isEmpty() ? QString() : plan.downloads.first().url);
            check(plan.downloads.size() == 1 &&
                      plan.downloads.first().fileName == QStringLiteral("fabric-server-launch.jar") &&
                      plan.downloads.first().size < 0,
                  "ZK8 ★ Fabric：落地叫 fabric-server-launch.jar；上游那条是 chunked，**没有大小**"
                  " ⇒ 进度只能报「已下多少」，算不出百分比");
            check(plan.launchTokens == QStringList{QStringLiteral("-jar"),
                                                   QStringLiteral("fabric-server-launch.jar"),
                                                   QStringLiteral("nogui")},
                  "ZK8 Fabric：启动参数");
            check(plan.firstLaunchNeedsNetwork,
                  "ZK8 ★ Fabric：下下来那份是**启动器**不是服务端，第一次跑要联网把库拉下来"
                  "（2026-09-28 真装实测：第一次跑下 8 个 loader 库 + 把原版 bundler jar "
                  "本地解开；第二次跑一条下载都没有 —— 落地名和字节都没被改过）");
            check(plan.method == InstallMethod::DirectJar,
                  "ZK8 Fabric：虽然第一次要联网，但对用户来说就是「下下来直接跑」"
                  "（不是 Forge 那种「先跑安装器」）");
        }

        // ---- Forge ----
        {
            Request request = base;
            request.flavor = Flavor::Forge;
            request.loaderVersion = QStringLiteral("47.4.10");
            const Plan plan = planFor(request);
            check(plan.ok && plan.method == InstallMethod::RunInstaller,
                  "ZK8 Forge：能装，装法是跑安装器");
            check(plan.downloads.size() == 1 &&
                      plan.downloads.first().url ==
                          LoaderMeta::forgeInstallerUrl(QStringLiteral("1.21.4"),
                                                        QStringLiteral("47.4.10")),
                  "ZK8 Forge：下的是 LoaderMeta 那条 maven 直链（不另拼一条 —— 两条迟早会漂开）",
                  plan.downloads.isEmpty() ? QString() : plan.downloads.first().url);
            check(plan.toolArguments == QStringList{QStringLiteral("--installServer"),
                                                    QStringLiteral(".")},
                  "ZK8 Forge：客户端那条路发的是 --installClient，服务端这条换成 --installServer",
                  plan.toolArguments.join(QLatin1Char(' ')));
            check(plan.toolRunDirectory.isEmpty(),
                  "ZK8 Forge：就在安装目录里跑（工具参数里那个 . 就是它）");
            check(plan.installedMarkers ==
                      QStringList{QStringLiteral("libraries/net/minecraftforge/forge/"
                                                 "1.21.4-47.4.10/win_args.txt"),
                                  QStringLiteral("user_jvm_args.txt")},
                  "ZK8 Forge：装完必须看到的那两张参数文件（路径是安装器自己定的，我们照着算）",
                  plan.installedMarkers.join(QStringLiteral(" | ")));
            check(plan.launchTokens ==
                      QStringList{QStringLiteral("@user_jvm_args.txt"),
                                  QStringLiteral("@libraries/net/minecraftforge/forge/"
                                                 "1.21.4-47.4.10/win_args.txt"),
                                  QStringLiteral("nogui")},
                  "ZK8 ★ Forge：入口不是 jar 是这两张 @ 参数文件；我们也不跑它的 run.bat"
                  "（内存要由实例设置说了算，就得自己拼这条命令）",
                  plan.launchTokens.join(QLatin1Char(' ')));
            check(!plan.launchTokens.isEmpty() &&
                      plan.launchTokens.first() == QStringLiteral("@user_jvm_args.txt") &&
                      plan.launchTokens.last() == QStringLiteral("nogui"),
                  "ZK8 ★ Forge：`@user_jvm_args.txt` 排在**第一个**，摆的顺序本身就是给驱动层"
                  "看的 —— 它把内存那几项接在**末尾**才盖得住那张文件里的 -Xmx"
                  "（同一个参数以最后出现的为准；接在前面，界面上那根内存滑杆就成了摆设）");
            check(!plan.firstLaunchNeedsNetwork,
                  "ZK8 Forge：库是**装的时候**下完的，装完就能离线起");
        }

        // ---- NeoForge ----
        {
            Request request = base;
            request.flavor = Flavor::NeoForge;
            request.loaderVersion = QStringLiteral("21.1.251");
            const Plan plan = planFor(request);
            check(plan.ok &&
                      plan.downloads.size() == 1 &&
                      plan.downloads.first().url ==
                          LoaderMeta::neoforgeInstallerUrl(QStringLiteral("21.1.251")),
                  "ZK8 NeoForge：安装器地址也复用 LoaderMeta",
                  plan.downloads.isEmpty() ? QString() : plan.downloads.first().url);
            check(plan.installedMarkers ==
                      QStringList{QStringLiteral("libraries/net/neoforged/neoforge/"
                                                 "21.1.251/win_args.txt"),
                                  QStringLiteral("user_jvm_args.txt")},
                  "ZK8 ★ NeoForge 那张参数文件的路径和 Forge **不一样**（没有游戏版本那一段："
                  "net/neoforged/neoforge/<版本>/），照 Forge 抄必错",
                  plan.installedMarkers.join(QStringLiteral(" | ")));
            check(plan.launchTokens ==
                      QStringList{QStringLiteral("@user_jvm_args.txt"),
                                  QStringLiteral("@libraries/net/neoforged/neoforge/"
                                                 "21.1.251/win_args.txt"),
                                  QStringLiteral("nogui")},
                  "ZK8 NeoForge：启动参数", plan.launchTokens.join(QLatin1Char(' ')));
            check(plan.toolArguments == QStringList{QStringLiteral("--installServer"),
                                                    QStringLiteral(".")},
                  "ZK8 NeoForge：装法和 Forge 同一句话");
        }

        // ---- Quilt ----
        {
            Request request = base;
            request.flavor = Flavor::Quilt;
            request.loaderVersion = QStringLiteral("0.27.1");
            request.installerVersion = QStringLiteral("0.15.1");
            const Plan plan = planFor(request);
            check(plan.ok && plan.method == InstallMethod::RunInstaller, "ZK8 Quilt：能装");
            check(plan.downloads.size() == 1 &&
                      plan.downloads.first().url ==
                          QStringLiteral("https://maven.quiltmc.org/repository/release/org/quiltmc/"
                                         "quilt-installer/0.15.1/quilt-installer-0.15.1.jar"),
                  "ZK8 Quilt：下的是安装器 jar");
            check(plan.toolArguments == QStringList{QStringLiteral("install"),
                                                    QStringLiteral("server"),
                                                    QStringLiteral("1.21.4"),
                                                    QStringLiteral("0.27.1"),
                                                    QStringLiteral("--install-dir=."),
                                                    QStringLiteral("--download-server")},
                  "ZK8 Quilt：install server <游戏版本> <加载器版本> --install-dir=<目录> "
                  "--download-server",
                  plan.toolArguments.join(QLatin1Char(' ')));
            check(plan.toolArguments.contains(QStringLiteral("--install-dir=.")) &&
                      !plan.toolArguments.contains(QStringLiteral("--install-dir")),
                  "ZK8 ★ Quilt 那个参数必须 `=` 连写成一段（分段写它不认，实测原话是 "
                  "`Option \"--install-dir\" must specify a value`）");
            check(plan.toolArguments.contains(QStringLiteral("--download-server")),
                  "ZK8 ★★ Quilt 必须带上 `--download-server`：不带的话装完的目录里**没有 "
                  "server.jar**，而它那份启动器**不会**自己去补 —— 实测是直接退出，"
                  "原话 `The Minecraft server .JAR is missing (…\\server.jar)!`，"
                  "用户看到的症状就是「装好了，一双击窗口闪一下没了」");
            check(plan.installedMarkers ==
                      QStringList{QStringLiteral("quilt-server-launch.jar"),
                                  QStringLiteral("server.jar")} &&
                      plan.launchTokens == QStringList{QStringLiteral("-jar"),
                                                       QStringLiteral("quilt-server-launch.jar"),
                                                       QStringLiteral("nogui")},
                  "ZK8 Quilt：产物 quilt-server-launch.jar，启动参数",
                  plan.installedMarkers.join(QStringLiteral(" | ")));
            check(plan.installedMarkers.contains(QStringLiteral("server.jar")),
                  "ZK8 ★ Quilt：「装好了没有」必须**连 server.jar 一起看**：只有 "
                  "quilt-server-launch.jar 的话安装器是跑完了，可那个目录还起不来"
                  "（缺游戏 jar 时它一句话不说就退出）");

            Request loose = request;
            loose.loaderVersion.clear();
            const Plan loosePlan = planFor(loose);
            check(loosePlan.ok && !loosePlan.toolArguments.contains(QStringLiteral("0.27.1")) &&
                      loosePlan.toolArguments.contains(QStringLiteral("--install-dir=.")) &&
                      loosePlan.toolArguments.contains(QStringLiteral("--download-server")),
                  "ZK8 Quilt：加载器版本可以不给（不给就是它自己挑最新那个），"
                  "两个选项一个不少",
                  loosePlan.toolArguments.join(QLatin1Char(' ')));
            check(!plan.firstLaunchNeedsNetwork,
                  "ZK8 ★★ Quilt 第一次启动**不联网**（2026-09-28 真装实测：44 条 Unpacking、"
                  "0 条下载 —— loader 的库是**安装器**下的，原版那部分是从本地 bundler jar "
                  "解开的）。★ 原来这一条写的是 true，那是照 Fabric 的形状推的、没实测；"
                  "两档在这件事上**不一样**，别互相抄");
        }

        // ---- Spigot ----
        {
            Request request = base;
            request.flavor = Flavor::Spigot;
            const Plan plan = planFor(request);
            check(plan.ok && plan.method == InstallMethod::BuildRequired,
                  "ZK8 Spigot：能装，装法是现编一份");
            check(plan.downloads.size() == 1 &&
                      plan.downloads.first().url == spigotBuildToolsUrl() &&
                      plan.downloads.first().fileName == QStringLiteral("BuildTools.jar"),
                  "ZK8 Spigot：先下 BuildTools");
            check(plan.toolArguments == QStringList{QStringLiteral("--rev"),
                                                    QStringLiteral("1.21.4")},
                  "ZK8 Spigot：--rev <游戏版本>", plan.toolArguments.join(QLatin1Char(' ')));
            check(plan.toolRunDirectory == QStringLiteral("BuildTools"),
                  "ZK8 Spigot：在子目录里编 —— BuildTools 会铺一整套 git 仓库和中间产物，"
                  "直接铺在服务端目录里那个目录就废了");
            check(plan.installedMarkers.isEmpty() && plan.launchTokens.isEmpty(),
                  "ZK8 ★ Spigot：产物名带 -R0.1-SNAPSHOT，**拼不出来** ⇒ 这两样都空着，"
                  "靠 pickSpigotJar 现场扫（缩回去自己编一个名字就是错的）");
            check(plan.firstLaunchNeedsNetwork, "ZK8 Spigot：编的过程中要联网（git + maven）");
            check(plan.note.contains(QStringLiteral("BuildTools")) &&
                      plan.note.contains(QStringLiteral("spigot-")),
                  "ZK8 Spigot：note 说清了产物在子目录里要搬上来、名字要扫", plan.note);
        }
    }

    section("ZK9. 缺参数：一句能直接给用户看的话");
    {
        using namespace ServerInstall;
        const auto planWith = [](Flavor flavor, const QString &game, const QString &loader,
                                 const QString &installer) {
            Request request;
            request.flavor = flavor;
            request.gameVersion = game;
            request.loaderVersion = loader;
            request.installerVersion = installer;
            return planFor(request);
        };

        // 八档全试一遍"没给游戏版本" —— 一档都不许漏（原版也要：它的服务端在版本 json 里）
        QStringList missingGame;
        for (Flavor flavor : allFlavors()) {
            const Plan plan =
                planWith(flavor, QString(), QStringLiteral("1.0"), QStringLiteral("1.0"));
            if (plan.ok || plan.problem != QStringLiteral("要先挑一个游戏版本")) {
                missingGame.append(flavorToken(flavor));
            }
        }
        check(missingGame.isEmpty(), "ZK9 八档全都：没给游戏版本就不 ok，而且那句话说的是这个",
              missingGame.join(QStringLiteral(", ")));

        {
            const Plan plan = planWith(Flavor::Forge, QStringLiteral("1.21.4"), QString(), QString());
            check(!plan.ok && plan.problem == QStringLiteral("要先挑一个 Forge 版本"),
                  "ZK9 Forge 缺加载器版本", plan.problem);
            check(plan.downloads.isEmpty() && plan.toolArguments.isEmpty() &&
                      plan.installedMarkers.isEmpty() && plan.launchTokens.isEmpty(),
                  "ZK9 不 ok 的那份计划里别的字段一个都不填（省得驱动层拿着半份计划往下走）");
        }
        {
            const Plan plan =
                planWith(Flavor::NeoForge, QStringLiteral("1.21.4"), QString(), QString());
            check(!plan.ok && plan.problem.contains(QStringLiteral("NeoForge")),
                  "ZK9 NeoForge 缺加载器版本时说的是它自己的名字（不是笼统的「加载器」）",
                  plan.problem);
        }
        {
            const Plan plan = planWith(Flavor::Fabric, QStringLiteral("1.21.4"),
                                       QStringLiteral("0.16.9"), QString());
            check(!plan.ok && plan.problem.contains(QStringLiteral("安装器版本")),
                  "ZK9 ★ Fabric 缺安装器版本是**单独一条**错 —— 那条地址少一段就是 404，"
                  "报成「没挑加载器」会把用户指到错的地方去",
                  plan.problem);
        }
        {
            const Plan plan = planWith(Flavor::Fabric, QStringLiteral("1.21.4"), QString(), QString());
            check(!plan.ok && plan.problem.contains(QStringLiteral("加载器")),
                  "ZK9 Fabric 两样都缺时报的是更靠前的那一步（加载器版本）", plan.problem);
        }
        {
            const Plan plan = planWith(Flavor::Quilt, QStringLiteral("1.21.4"),
                                       QStringLiteral("0.27.1"), QString());
            check(!plan.ok && plan.problem.contains(QStringLiteral("安装器版本")),
                  "ZK9 Quilt 缺安装器版本", plan.problem);
        }

        // 不需要加载器 / 安装器的那几档：一个游戏版本就够
        check(planWith(Flavor::Vanilla, QStringLiteral("1.21.4"), QString(), QString()).ok,
              "ZK9 原版只要一个游戏版本");
        check(planWith(Flavor::Paper, QStringLiteral("1.21.4"), QString(), QString()).ok,
              "ZK9 Paper 不要加载器也不要安装器（构建号不给就是最新那条）");
        check(planWith(Flavor::Spigot, QStringLiteral("1.21.4"), QString(), QString()).ok,
              "ZK9 Spigot 只要一个游戏版本");
    }

    section("ZK10. 那些「拼不出来」的：原版的服务端、Spigot 的产物名");
    {
        using namespace ServerInstall;
        // ---- 原版：地址在版本 json 的 downloads.server 里 ----
        const QJsonObject versionJson{
            {QStringLiteral("id"), QStringLiteral("1.21.4")},
            {QStringLiteral("downloads"),
             QJsonObject{
                 {QStringLiteral("server"),
                  QJsonObject{
                      {QStringLiteral("url"),
                       QStringLiteral("https://piston-data.mojang.com/v1/objects/abc/server.jar")},
                      {QStringLiteral("sha1"), QStringLiteral("d0ae1e2e1b9f1e0a")},
                      {QStringLiteral("size"), 55916448}}}}}};
        const Download jar = vanillaServerDownload(versionJson);
        check(jar.ok() && jar.fileName == QStringLiteral("server.jar") &&
                  jar.url.endsWith(QStringLiteral("/server.jar")) &&
                  jar.sha1 == QStringLiteral("d0ae1e2e1b9f1e0a") && jar.size == 55916448,
              "ZK10 原版：三个字段全从 json 里读（它那条**有** size，所以进度是算得出百分比的；"
              "Fabric 那条没有 —— 同一个下载器要能同时伺候这两种）",
              jar.url);
        check(!vanillaServerDownload(
                   QJsonObject{{QStringLiteral("id"), QStringLiteral("1.0")}})
                   .ok(),
              "ZK10 原版：json 里没有 downloads.server = 这个版本没有官方服务端"
              "（远古版本确实没有）");
        check(!vanillaServerDownload(QJsonObject()).ok(), "ZK10 原版：空 json 也不崩");
        check(!vanillaServerDownload(
                   QJsonObject{{QStringLiteral("downloads"),
                                QJsonObject{{QStringLiteral("server"),
                                             QJsonObject{{QStringLiteral("sha1"),
                                                          QStringLiteral("abc")}}}}}})
                   .ok(),
              "ZK10 原版：只有 sha1 没有 url 的那一条不算（ok() 判的是 url）");

        // ---- Spigot：产物名扫出来 ----
        const QStringList files{QStringLiteral("BuildTools.jar"),
                                QStringLiteral("spigot-1.21.4-R0.1-SNAPSHOT.jar"),
                                QStringLiteral("apache-maven-3.9.6"), QStringLiteral("work"),
                                QStringLiteral("spigot.jar")};
        check(pickSpigotJar(files) == QStringLiteral("spigot-1.21.4-R0.1-SNAPSHOT.jar"),
              "ZK10 Spigot：从一堆东西里扫出那个产物", pickSpigotJar(files));
        check(pickSpigotJar(QStringList{QStringLiteral("BuildTools.jar"), QStringLiteral("work")})
                  .isEmpty(),
              "ZK10 Spigot：没编出来就是空 —— 别把 BuildTools.jar 自己当成产物");
        check(pickSpigotJar(QStringList{QStringLiteral("spigot.jar")}).isEmpty(),
              "ZK10 Spigot：`spigot.jar` 不算（上游产物名一定带 `spigot-` 加版本后缀）；"
              "认宽了会把用户自己改名的那份当成刚编出来的");
        check(pickSpigotJar(QStringList()).isEmpty(), "ZK10 Spigot：空目录回空");
    }

    // =====================================================================
    //  ZL. 世界设置那条路：NbtTree（判据层）+ WorldFiles 的读写
    // =====================================================================
    //
    // 用户原话：「世界根据其存档文件在存档设置（那支笔）里面编辑游戏规则等，打开之前弹出
    // 坏档警告并提供备份按钮」。这一节量的是**判据那一半**：一棵树怎么读怎么写、"坏档"
    // 是谁说的、改一格会不会动到别的字节。界面上那一半（那支笔、那一页、那一句警告）在
    // mw_check 的 T27 那一节。
    //
    // NOTE: 树是**手工搭**出来的，不是从某个真存档里抄的。理由是这个模块的价值全在角落上
    //       ——"长度前缀越界""多出来一截""嵌套太深""改一格别的地方一个字节不变"，随便找一
    //       个真存档都撞不上这些；而撞得上它们的那些输入（一个被写坏的世界）恰恰是这一整
    //       条路存在的原因。
    section("ZL1. NbtTree：手工搭一棵树，写出去再读回来一个字节都不差");
    {
        const auto field = [](const QString &name, const NbtTree::Node &node) {
            NbtTree::Field item;
            item.first = name;
            item.second = node;
            return item;
        };
        const auto number = [](NbtTree::Type type, qint64 value) {
            NbtTree::Node node;
            node.type = type;
            node.number = value;
            return node;
        };
        const auto real = [](NbtTree::Type type, double value) {
            NbtTree::Node node;
            node.type = type;
            node.real = value;
            return node;
        };
        const auto string = [](const QString &value) {
            NbtTree::Node node;
            node.type = NbtTree::Type::String;
            node.text = value;
            return node;
        };
        const auto compound = [](const NbtTree::FieldList &fields) {
            NbtTree::Node node;
            node.type = NbtTree::Type::Compound;
            node.fields = fields;
            return node;
        };

        // ★ 世界名里塞两样"普通字符串不会碰到"的东西：
        //   - 一个补充平面上的字（U+1F600）：NBT 的字符串是**改过的 UTF-8**，这一档要写
        //     成 CESU-8 的那对代理项，写错的表现是"存完这一份，游戏读出来是个乱码"；
        //   - 一个真正的 NUL（U+0000）：它必须写成 `C0 80`，直接写 `00` 的话长度前缀还
        //     对得上、但游戏那边的读取会在那儿断掉。
        const char32_t trickyChars[4] = {U'我', U'\0', U'\U0001F600', U'界'};
        const QString trickyName = QString::fromUcs4(trickyChars, 4);

        NbtTree::Document document;
        document.rootName = QString();  // `level.dat` 的根是**无名**的 Compound
        document.root.type = NbtTree::Type::Compound;

        NbtTree::Node emptyList;
        emptyList.type = NbtTree::Type::List;
        emptyList.itemType = NbtTree::Type::Byte;  // 空表**也带着**它那一档的类型

        NbtTree::Node byteArray;
        byteArray.type = NbtTree::Type::ByteArray;
        byteArray.bytes = QByteArray("\x00\x01\xff", 3);

        NbtTree::Node intArray;
        intArray.type = NbtTree::Type::IntArray;
        intArray.ints = QList<qint32>{1, -2, 3};

        NbtTree::Node longArray;
        longArray.type = NbtTree::Type::LongArray;
        longArray.longs = QList<qint64>{1, -2};

        NbtTree::Node listOfCompound;
        listOfCompound.type = NbtTree::Type::List;
        listOfCompound.itemType = NbtTree::Type::Compound;
        listOfCompound.items.append(compound(NbtTree::FieldList{
            field(QStringLiteral("X"), number(NbtTree::Type::Int, 5))}));

        const NbtTree::FieldList data{
            field(QStringLiteral("LevelName"), string(trickyName)),
            field(QStringLiteral("LastPlayed"), number(NbtTree::Type::Long, 1758960000000LL)),
            field(QStringLiteral("DataVersion"), number(NbtTree::Type::Int, 3465)),
            field(QStringLiteral("Difficulty"), number(NbtTree::Type::Byte, 2)),
            field(QStringLiteral("allowCommands"), number(NbtTree::Type::Byte, 1)),
            field(QStringLiteral("hardcore"), number(NbtTree::Type::Byte, 0)),
            field(QStringLiteral("半个浮点"), real(NbtTree::Type::Float, 0.5)),
            field(QStringLiteral("十分之一"), real(NbtTree::Type::Double, 0.1)),
            field(QStringLiteral("字节数组"), byteArray),
            field(QStringLiteral("整数数组"), intArray),
            field(QStringLiteral("长整数数组"), longArray),
            field(QStringLiteral("空表"), emptyList),
            field(QStringLiteral("一个复合元素"), listOfCompound),
            field(QStringLiteral("Version"), compound(NbtTree::FieldList{
                      field(QStringLiteral("Name"), string(QStringLiteral("1.20.1"))),
                      field(QStringLiteral("Id"), number(NbtTree::Type::Int, 3465))})),
            field(QStringLiteral("GameRules"), compound(NbtTree::FieldList{
                      field(QStringLiteral("keepInventory"), string(QStringLiteral("true"))),
                      field(QStringLiteral("randomTickSpeed"), string(QStringLiteral("3"))),
                      field(QStringLiteral("doDaylightCycle"), string(QStringLiteral("false")))})),
            field(QStringLiteral("空复合"), compound(NbtTree::FieldList())),
        };
        document.root.fields = NbtTree::FieldList{field(QStringLiteral("Data"), compound(data))};

        const QByteArray bytes = NbtTree::serialize(document);
        check(!bytes.isEmpty(), "ZL1 一棵树写得出来字节");

        NbtTree::Document back;
        QString why;
        check(NbtTree::parse(bytes, &back, &why), "ZL1 再读回来不报错", why);
        // ★ 这一条是这个模块的**地基**：写出去 → 读回来 → 再写出去，两次的字节必须一样。
        //   它是"改一格别的地方一个字节不变"那条保证的来源（改完写回去的树就是从盘上那份
        //   读出来的同一棵，只有被改的那一格不一样）。
        check(NbtTree::serialize(back) == bytes,
              "★★ ZL1 读回来的那棵树再写出去，和原来那串字节**逐字节相同**");

        const NbtTree::Node *root = &back.root;
        check(root->type == NbtTree::Type::Compound, "ZL1 根是一张表");
        const NbtTree::Node *dataBack = NbtTree::descend(back.root, QStringLiteral("Data"));
        check(dataBack != nullptr && dataBack->type == NbtTree::Type::Compound,
              "ZL1 路径 descend(Data) 走到那张表上");
        check(NbtTree::descend(back.root, QStringLiteral("Data/Version/Name")) != nullptr,
              "ZL1 两段的路径也走得通（Version/Name）");
        check(NbtTree::descend(back.root, QStringLiteral("Data/没有这一格")) == nullptr,
              "ZL1 不存在的路径回 nullptr");
        check(NbtTree::descend(back.root, QStringLiteral("Data/LevelName/再往下")) == nullptr,
              "ZL1 走到一个**不是表**的格子上也回 nullptr（不硬往下钻）");

        // 每一项都按名字取一遍（顺序也一起钉住：NBT 的表是保序的，界面上的规则表就是按它排的）
        if (dataBack != nullptr) {
            QStringList names;
            for (const NbtTree::Field &item : dataBack->fields) {
                names << item.first;
            }
            check(names == QStringList({QStringLiteral("LevelName"), QStringLiteral("LastPlayed"),
                                        QStringLiteral("DataVersion"), QStringLiteral("Difficulty"),
                                        QStringLiteral("allowCommands"), QStringLiteral("hardcore"),
                                        QStringLiteral("半个浮点"), QStringLiteral("十分之一"),
                                        QStringLiteral("字节数组"), QStringLiteral("整数数组"),
                                        QStringLiteral("长整数数组"), QStringLiteral("空表"),
                                        QStringLiteral("一个复合元素"), QStringLiteral("Version"),
                                        QStringLiteral("GameRules"), QStringLiteral("空复合")}),
                  "★★ ZL1 项的顺序就是写进去的顺序（改完存回盘上，游戏的读取顺序也不变）",
                  names.join(QLatin1Char('/')));

            const NbtTree::Node *name = NbtTree::field(*dataBack, QStringLiteral("LevelName"));
            check(name != nullptr && name->text == trickyName,
                  "★★ ZL1 名字里那个补充平面的字和一个真 NUL 都原样回来了"
                  "（改过的 UTF-8：CESU-8 代理项 + `C0 80`）");
            if (name != nullptr) {
                check(!name->text.contains(QChar(0)) == false,
                      "ZL1 那个 NUL 还在（不是被截掉的半截字符串）");
            }
            const NbtTree::Node *played = NbtTree::field(*dataBack, QStringLiteral("LastPlayed"));
            check(played != nullptr && played->type == NbtTree::Type::Long &&
                      played->number == 1758960000000LL,
                  "ZL1 Long 原样");
            const NbtTree::Node *half = NbtTree::field(*dataBack, QStringLiteral("半个浮点"));
            check(half != nullptr && half->type == NbtTree::Type::Float && half->real == 0.5,
                  "ZL1 float 按位搬过去（不是转成 double 再转回来）");
            const NbtTree::Node *tenth = NbtTree::field(*dataBack, QStringLiteral("十分之一"));
            check(tenth != nullptr && tenth->real == 0.1,
                  "ZL1 double 也是按位搬的（0.1 这种二进制除不尽的照样精确）");
            const NbtTree::Node *blob = NbtTree::field(*dataBack, QStringLiteral("字节数组"));
            check(blob != nullptr && blob->bytes == QByteArray("\x00\x01\xff", 3),
                  "ZL1 字节数组里的 0x00 / 0xff 没被当成结束符吃掉");
            const NbtTree::Node *ints = NbtTree::field(*dataBack, QStringLiteral("整数数组"));
            check(ints != nullptr && ints->ints == QList<qint32>({1, -2, 3}), "ZL1 整数数组连负数一起原样");
            const NbtTree::Node *longs = NbtTree::field(*dataBack, QStringLiteral("长整数数组"));
            check(longs != nullptr && longs->longs == QList<qint64>({1, -2}), "ZL1 长整数数组原样");
            const NbtTree::Node *empty = NbtTree::field(*dataBack, QStringLiteral("空表"));
            // ★ 空列表的**元素类型**必须留着：靠"猜第一个元素的类型"来写的话，空表一律变成
            //   TAG_End，游戏读出来是两个不一样的东西。
            check(empty != nullptr && empty->type == NbtTree::Type::List &&
                      empty->items.isEmpty() && empty->itemType == NbtTree::Type::Byte,
                  "★★ ZL1 空列表的元素类型留住了（空表不是「没有类型」）");
            const NbtTree::Node *nested = NbtTree::field(*dataBack, QStringLiteral("一个复合元素"));
            check(nested != nullptr && nested->itemType == NbtTree::Type::Compound &&
                      nested->items.size() == 1,
                  "ZL1 表里套表（列表元素是复合）也回来了");
            check(NbtTree::descend(back.root, QStringLiteral("Data/空复合")) != nullptr,
                  "ZL1 一张空复合还在（不是被当成「读到尾巴」删掉）");
        }
        check(NbtTree::typeName(NbtTree::Type::Compound) == QStringLiteral("复合"),
              "ZL1 类型的中文名来自唯一出处", NbtTree::typeName(NbtTree::Type::Compound));
    }

    section("ZL2. NbtTree：解不动的那些，一颗子树都不留");
    {
        // 哨兵：失败时**不许动** out（调用方原来拿着一份就还是那一份）。
        NbtTree::Document sentinel;
        sentinel.rootName = QStringLiteral("哨兵");
        sentinel.root.type = NbtTree::Type::Compound;
        sentinel.root.fields = NbtTree::FieldList{};
        QString why;

        check(!NbtTree::parse(QByteArray(), &sentinel, &why), "ZL2 空的字节流解不动");
        check(!why.isEmpty(), "ZL2 而且给了一句原因", why);
        check(sentinel.rootName == QStringLiteral("哨兵"), "ZL2 失败时 out 一个字段都没被碰");

        // 一个"根是空表"的最小合法树：`0A 00 00 00`
        const QByteArray minimal("\x0A\x00\x00\x00", 4);
        NbtTree::Document small;
        check(NbtTree::parse(minimal, &small, &why), "ZL2 最小的那棵树（根是一张空表）解得动", why);

        check(!NbtTree::parse(minimal.left(3), &sentinel, &why), "ZL2 少一个字节就解不动（截断）");
        check(!NbtTree::parse(minimal + QByteArray("\x00", 1), &sentinel, &why),
              "ZL2 末尾多出来一截也解不动（不许「读到我认识的地方就停」）");

        // 类型字节不认识：`0D` 不在 0~12 里。
        check(!NbtTree::parse(QByteArray("\x0D\x00\x00\x00", 4), &sentinel, &why),
              "ZL2 类型字节不认识（13）当场拒绝");
        check(why.contains(QStringLiteral("13")) || !why.isEmpty(),
              "ZL2 而且那句话里点了是哪一个类型字节", why);

        // 长度前缀越界：一张表里一格 String，名字叫 a，正文说 100 个字节但只跟了 3 个。
        QByteArray overrun;
        overrun.append("\x0A\x00\x00", 3);          // 根：Compound，无名
        overrun.append("\x08\x00\x01", 3);          // String，名字长 1
        overrun.append("a", 1);                     // 名字
        overrun.append("\x00\x64", 2);              // 正文自称 100 字节
        overrun.append("abc", 3);                   // 只有 3 个
        overrun.append("\x00", 1);                  // 表收尾
        check(!NbtTree::parse(overrun, &sentinel, &why),
              "★★ ZL2 长度前缀比剩下的字节多 ⇒ 拒绝（不许照着这个数去分配内存）");

        // 负数项数：一张表，一格 List，元素类型 Byte，项数 0xFFFFFFFF。
        QByteArray negative;
        negative.append("\x0A\x00\x00", 3);
        negative.append("\x09\x00\x01", 3);         // List，名字长 1
        negative.append("l", 1);
        negative.append("\x01", 1);                 // 元素类型 Byte
        negative.append("\xFF\xFF\xFF\xFF", 4);     // 项数 = -1
        negative.append("\x00", 1);
        check(!NbtTree::parse(negative, &sentinel, &why),
              "★★ ZL2 负数项数当场拒绝（不拿它去 reserve 一大片）");

        // 嵌套太深：一条 100 层往里的链子。
        NbtTree::Document deep;
        deep.root.type = NbtTree::Type::Compound;
        NbtTree::Node *cursor = &deep.root;
        for (int i = 0; i < 100; ++i) {
            NbtTree::Field item;
            item.first = QStringLiteral("下一层");
            item.second.type = NbtTree::Type::Compound;
            cursor->fields.append(item);
            cursor = &cursor->fields.last().second;
        }
        check(!NbtTree::parse(NbtTree::serialize(deep), &sentinel, &why),
              "★★ ZL2 嵌套超过 kMaxDepth（64）拒绝 —— 递归解下去会把栈吃光", why);
        check(!NbtTree::parse(NbtTree::serialize(deep),
                              &sentinel, &why) &&
                  sentinel.rootName == QStringLiteral("哨兵"),
              "ZL2 太深的那次也没在 out 上留下半棵树");
    }

    section("ZL3. NbtTree：改一格的值（改不动就一个字节都不改）");
    {
        NbtTree::Node byte;
        byte.type = NbtTree::Type::Byte;
        byte.number = 7;
        check(NbtTree::valueText(byte) == QStringLiteral("7"), "ZL3 值印成一行字", NbtTree::valueText(byte));
        check(NbtTree::setValueText(&byte, QStringLiteral("9")), "ZL3 改得动");
        check(byte.number == 9, "ZL3 改完就是新值");
        check(!NbtTree::setValueText(&byte, QStringLiteral("abc")), "ZL3 不是一个数就不收");
        check(byte.number == 9, "★ ZL3 收不下的时候**原来的值一个字节都没动**");
        check(!NbtTree::setValueText(&byte, QStringLiteral("200")),
              "★ ZL3 超出一个 Byte 的范围（127）也收不下");
        check(byte.number == 9, "ZL3 同上，值还是没变");
        check(NbtTree::setValueText(&byte, QStringLiteral("-128")), "ZL3 下界 -128 收得下");
        check(!NbtTree::setValueText(&byte, QStringLiteral("-129")), "ZL3 再低一格就不收");

        NbtTree::Node longNode;
        longNode.type = NbtTree::Type::Long;
        check(NbtTree::setValueText(&longNode, QStringLiteral("9223372036854775807")),
              "ZL3 Long 的最大值收得下");
        check(!NbtTree::setValueText(&longNode, QStringLiteral("9223372036854775808")),
              "ZL3 再大一位收不下（不是悄悄截成最大值）");

        NbtTree::Node text;
        text.type = NbtTree::Type::String;
        text.text = QStringLiteral("原来那句");
        // NOTE: 这里要的是 70000 个**中文字**（每个 3 字节，编码之后 21 万字节 > 65535）。
        //       不能写 `QLatin1Char('字')` —— Latin-1 装不下，编译器会把它当成一个
        //       多字符常量（`-Wmultichar` + `-Woverflow`），char 里只剩最后一个字节。
        check(!NbtTree::setValueText(&text, QString(70000, QChar(0x5B57))) ,
              "★★ ZL3 编码之后超过 65535 字节的文字拒收（长度前缀是 quint16，收下就是写一份被截断的东西）");
        check(text.text == QStringLiteral("原来那句"), "ZL3 拒收之后那一格还是原来那句");
        check(NbtTree::setValueText(&text, QString()), "ZL3 空串收得下（清空是一个合法的值）");

        NbtTree::Node table;
        table.type = NbtTree::Type::Compound;
        check(!NbtTree::setValueText(&table, QStringLiteral("x")),
              "ZL3 整棵子树（表 / 列表 / 数组）不接「一行字」");
        NbtTree::Node *nullNode = nullptr;
        check(!NbtTree::setValueText(nullNode, QStringLiteral("x")), "ZL3 空指针不崩、回 false");
        check(NbtTree::integerBits(NbtTree::Type::Byte) == 8 &&
                  NbtTree::integerBits(NbtTree::Type::String) == 0,
              "ZL3 整数族的位宽（不是整数族回 0）");
        check(NbtTree::isFloatingPoint(NbtTree::Type::Double) &&
                  !NbtTree::isFloatingPoint(NbtTree::Type::Long),
              "ZL3 浮点族认得出来");
    }

    section("ZL4. NbtTree：游戏规则那一张表");
    {
        check(NbtTree::ruleKind(QStringLiteral("true")) == NbtTree::ValueKind::Bool &&
                  NbtTree::ruleKind(QStringLiteral("FALSE")) == NbtTree::ValueKind::Bool,
              "ZL4 是/否那一档大小写都认（盘上两种都真见过）");
        check(NbtTree::ruleKind(QStringLiteral("3")) == NbtTree::ValueKind::Int, "ZL4 整数认得出");
        check(NbtTree::ruleKind(QStringLiteral("-3")) == NbtTree::ValueKind::Int, "ZL4 负数也算整数");
        check(NbtTree::ruleKind(QStringLiteral("2.5")) == NbtTree::ValueKind::Text,
              "★ ZL4 小数归「别的」（游戏规则没有小数，按小数读进去游戏那边当坏值）");
        check(NbtTree::ruleKind(QString()) == NbtTree::ValueKind::Text, "ZL4 空串是「别的」");
        check(NbtTree::ruleKind(QStringLiteral(" 3")) == NbtTree::ValueKind::Int,
              "ZL4 两头有空白也算整数（读的时候就 trim）");
        check(NbtTree::ruleKind(QStringLiteral("mobGriefing")) == NbtTree::ValueKind::Text,
              "ZL4 别的字符串就是「别的」（有模组往这儿塞任意字符串）");
        check(NbtTree::valueKindName(NbtTree::ValueKind::Bool) !=
                  NbtTree::valueKindName(NbtTree::ValueKind::Int),
              "ZL4 三种形状的名字两两不同");

        bool flag = false;
        check(NbtTree::boolValue(QStringLiteral("true"), &flag) && flag, "ZL4 true 读成真");
        check(NbtTree::boolValue(QStringLiteral("False"), &flag) && !flag, "ZL4 false 读成假（不区分大小写）");
        check(!NbtTree::boolValue(QStringLiteral("是"), &flag), "ZL4 别的字认不成布尔");
        check(NbtTree::boolValue(QStringLiteral("true"), nullptr), "ZL4 out 传空也不崩");

        // ---- 一张手搭的表 ----
        NbtTree::Document document;
        document.root.type = NbtTree::Type::Compound;
        NbtTree::Node rules;
        rules.type = NbtTree::Type::Compound;
        rules.fields = NbtTree::FieldList{
            {QStringLiteral("keepInventory"), [] {
                 NbtTree::Node n;
                 n.type = NbtTree::Type::String;
                 n.text = QStringLiteral("true");
                 return n;
             }()},
            {QStringLiteral("randomTickSpeed"), [] {
                 NbtTree::Node n;
                 n.type = NbtTree::Type::String;
                 n.text = QStringLiteral("3");
                 return n;
             }()},
            // ★ 一条**值不是字符串**的（模组会写这种东西）：它要被跳过，而不是让整张表都读不出来。
            {QStringLiteral("模组塞的"), [] {
                 NbtTree::Node n;
                 n.type = NbtTree::Type::Int;
                 n.number = 1;
                 return n;
             }()},
        };
        NbtTree::Field dataField;
        dataField.first = QStringLiteral("Data");
        dataField.second.type = NbtTree::Type::Compound;
        dataField.second.fields = NbtTree::FieldList{
            {QStringLiteral("GameRules"), rules},
        };
        document.root.fields = NbtTree::FieldList{dataField};

        QList<NbtTree::GameRule> got;
        QString why;
        check(NbtTree::gameRulesOf(document.root, &got, &why), "ZL4 取出那张表", why);
        check(got.size() == 2, "★ ZL4 值不是字符串的那一条被**跳过**（不是让整张表读不出来）",
              QString::number(got.size()));
        check(got.size() == 2 && got[0].name == QStringLiteral("keepInventory") &&
                  got[0].value == QStringLiteral("true") && got[1].name == QStringLiteral("randomTickSpeed"),
              "★ ZL4 顺序就是盘上的顺序（界面要排是界面的事）");

        // 改一条**已经存在**的。
        check(NbtTree::setGameRule(&document.root, QStringLiteral("randomTickSpeed"),
                                   QStringLiteral("42"), &why),
              "ZL4 改一条已有的规则", why);
        got.clear();
        NbtTree::gameRulesOf(document.root, &got, &why);
        check(got.size() == 2 && got[1].value == QStringLiteral("42"), "ZL4 改完读出来就是新值");

        // ★ 不发明新的。
        const int before = NbtTree::descend(document.root, QStringLiteral("Data/GameRules")) != nullptr
                               ? NbtTree::descend(document.root, QStringLiteral("Data/GameRules"))->fields.size()
                               : -1;
        check(!NbtTree::setGameRule(&document.root, QStringLiteral("doFireTick"),
                                    QStringLiteral("false"), &why),
              "★★ ZL4 不发明新规则：名字不存在就拒绝");
        check(!why.isEmpty(), "ZL4 而且说明了是找不到这一条", why);
        const NbtTree::Node *after = NbtTree::descend(document.root, QStringLiteral("Data/GameRules"));
        check(after != nullptr && after->fields.size() == before,
              "★★ ZL4 拒绝之后表里**一条都没多出来**（用户点一下就给别人的存档塞一条，那不是编辑）");

        // 改一条值不是字符串的。
        check(!NbtTree::setGameRule(&document.root, QStringLiteral("模组塞的"),
                                    QStringLiteral("2"), &why),
              "ZL4 值不是字符串的那一条也不改（那是别人写的东西）");

        // 没有那一格的老存档。
        NbtTree::Document bare;
        bare.root.type = NbtTree::Type::Compound;
        check(!NbtTree::gameRulesOf(bare.root, &got, &why), "ZL4 没有那一格 ⇒ 取不出来");
        check(why.contains(QStringLiteral("游戏规则")), "ZL4 而且那句原因点名了是哪一格", why);
        check(!NbtTree::setGameRule(&bare.root, QStringLiteral("keepInventory"),
                                    QStringLiteral("true"), &why),
              "★ ZL4 没有那一格时也**不替它造一格**");

        // ★★ 2026-09-29：`MissingRule::Create` 那一档 —— 界面上"改一条盘上还没有的规则"
        //    走的就是它（用户原话「下面的世界设置不要要求进了世界才显示而是把所有的都列出来，
        //    并允许修改值」）。上面那几条量的是**默认那一档**（拒绝、一个字节都不改），
        //    这里量的是"谁要建谁自己说"。
        //
        //    NOTE: 下面这几棵树都是**新造的**，不在上面那几棵上接着改 —— 在"已经被拒绝过
        //          一次"的树上量"建出来了没有"，量到的是上一次留下的样子（那确实没变，
        //          但那是搭巧合，不是判据）。
        NbtTree::Document creatable;
        creatable.root.type = NbtTree::Type::Compound;
        {
            NbtTree::Field data;
            data.first = QStringLiteral("Data");
            data.second.type = NbtTree::Type::Compound;
            NbtTree::Node rules;
            rules.type = NbtTree::Type::Compound;
            data.second.fields = NbtTree::FieldList{{QStringLiteral("GameRules"), rules}};
            creatable.root.fields = NbtTree::FieldList{data};
        }
        check(NbtTree::setGameRule(&creatable.root, QStringLiteral("doFireTick"),
                                   QStringLiteral("false"), &why, NbtTree::MissingRule::Create),
              "★★ ZL4 `MissingRule::Create`：名字不在表里就**加一条**（默认那一档是拒绝）",
              why);
        got.clear();
        check(NbtTree::gameRulesOf(creatable.root, &got, &why) && got.size() == 1 &&
                  got[0].name == QStringLiteral("doFireTick") &&
                  got[0].value == QStringLiteral("false"),
              "★★ ZL4 加进去之后读得回来，值和名字都对", why);
        {
            const NbtTree::Node *added =
                NbtTree::descend(creatable.root, QStringLiteral("Data/GameRules/doFireTick"));
            check(added != nullptr && added->type == NbtTree::Type::String,
                  "★★ ZL4 建出来的是**字符串**那一档（`GameRules` 是一张「名字 → 字符串」的"
                  "表，加进去的必须也是字符串）");
        }

        // 连 `Data/GameRules` 那一格都没有的老档（工具做出来的、从没进过一次的）：`Create`
        // 把那一格一起建出来。这正是用户那句话里「不要要求进了世界才显示」的前提。
        NbtTree::Document noTable;
        noTable.root.type = NbtTree::Type::Compound;
        {
            NbtTree::Field data;
            data.first = QStringLiteral("Data");
            data.second.type = NbtTree::Type::Compound;
            noTable.root.fields = NbtTree::FieldList{data};
        }
        check(NbtTree::setGameRule(&noTable.root, QStringLiteral("keepInventory"),
                                   QStringLiteral("true"), &why, NbtTree::MissingRule::Create),
              "★★ ZL4 连 `Data/GameRules` 那一格都没有的老档也建得出来（一个刚建好、还没被"
              "游戏写过档的世界就是这样）",
              why);
        got.clear();
        check(NbtTree::gameRulesOf(noTable.root, &got, &why) && got.size() == 1,
              "★★ ZL4 新造出来那一格是可用的（读得出来）", why);

        // 但**连 `Data` 都不是复合标签**的时候仍然一个字节都不动：这份档的形状我们看不懂，
        // 看不懂就不碰（和 `parse()` 那条规矩一致）。
        NbtTree::Document weird;
        weird.root.type = NbtTree::Type::Compound;
        {
            NbtTree::Field data;
            data.first = QStringLiteral("Data");
            data.second.type = NbtTree::Type::Int;
            weird.root.fields = NbtTree::FieldList{data};
        }
        check(!NbtTree::setGameRule(&weird.root, QStringLiteral("keepInventory"),
                                    QStringLiteral("true"), &why, NbtTree::MissingRule::Create),
              "★★ ZL4 `Data` 不是复合标签 ⇒ 连 `Create` 那一档也拒绝（形状看不懂就不动它）");

        // 有一格**空的**表：取出来成功、零条（"这个老存档还没存过规则"和"坏了"是两回事）。
        NbtTree::Document emptyTable;
        emptyTable.root.type = NbtTree::Type::Compound;
        NbtTree::Field emptyData;
        emptyData.first = QStringLiteral("Data");
        emptyData.second.type = NbtTree::Type::Compound;
        NbtTree::Node emptyRules;
        emptyRules.type = NbtTree::Type::Compound;
        emptyData.second.fields = NbtTree::FieldList{{QStringLiteral("GameRules"), emptyRules}};
        emptyTable.root.fields = NbtTree::FieldList{emptyData};
        got.clear();
        check(NbtTree::gameRulesOf(emptyTable.root, &got, &why) && got.isEmpty(),
              "ZL4 空表取出来是「成功、零条」（不是失败）");
    }

    section("ZL5. WorldFiles::readWorldInfo / applyWorldInfo（纯函数，不碰盘）");
    {
        const auto stringNode = [](const QString &value) {
            NbtTree::Node n;
            n.type = NbtTree::Type::String;
            n.text = value;
            return n;
        };
        const auto byteNode = [](qint64 value) {
            NbtTree::Node n;
            n.type = NbtTree::Type::Byte;
            n.number = value;
            return n;
        };
        const auto intNode = [](qint64 value) {
            NbtTree::Node n;
            n.type = NbtTree::Type::Int;
            n.number = value;
            return n;
        };
        const auto longNode = [](qint64 value) {
            NbtTree::Node n;
            n.type = NbtTree::Type::Long;
            n.number = value;
            return n;
        };
        const auto compound = [](const NbtTree::FieldList &fields) {
            NbtTree::Node n;
            n.type = NbtTree::Type::Compound;
            n.fields = fields;
            return n;
        };
        const auto field = [](const QString &name, const NbtTree::Node &node) {
            NbtTree::Field item;
            item.first = name;
            item.second = node;
            return item;
        };

        NbtTree::Document document;
        document.root.type = NbtTree::Type::Compound;
        NbtTree::Node version = compound(NbtTree::FieldList{
            field(QStringLiteral("Name"), stringNode(QStringLiteral("1.20.1")))});
        NbtTree::Node rules = compound(NbtTree::FieldList{
            field(QStringLiteral("keepInventory"), stringNode(QStringLiteral("false"))),
            field(QStringLiteral("randomTickSpeed"), stringNode(QStringLiteral("3")))});
        document.root.fields = NbtTree::FieldList{field(
            QStringLiteral("Data"),
            compound(NbtTree::FieldList{
                field(QStringLiteral("LevelName"), stringNode(QStringLiteral("我的世界"))),
                field(QStringLiteral("LastPlayed"), longNode(1758960000000LL)),
                field(QStringLiteral("DataVersion"), intNode(3465)),
                field(QStringLiteral("Difficulty"), byteNode(2)),
                field(QStringLiteral("allowCommands"), byteNode(0)),
                field(QStringLiteral("hardcore"), byteNode(0)),
                field(QStringLiteral("Version"), version),
                field(QStringLiteral("GameRules"), rules)}))};

        WorldFiles::WorldInfo info;
        WorldFiles::readWorldInfo(document, true, &info);
        check(info.gzipped, "ZL5 那份是 gzip 包着的（原样带出来）");
        check(info.hasLevelName && info.levelName == QStringLiteral("我的世界"), "ZL5 世界名读出来了");
        check(info.hasVersionName && info.versionName == QStringLiteral("1.20.1"), "ZL5 版本名读出来了");
        check(info.hasLastPlayed && info.lastPlayedMs == 1758960000000LL, "ZL5 最后游玩时间读出来了");
        check(info.hasDataVersion && info.dataVersion == 3465, "ZL5 存档格式号读出来了");
        check(info.hasAllowCommands && !info.allowCommands, "ZL5 允许作弊读出来了（0 = 关）");
        check(info.hasHardcore && !info.hardcore, "ZL5 极限模式读出来了");
        check(info.hasDifficulty && info.difficulty == 2, "ZL5 难度读出来了");
        check(info.hasRules && info.rules.size() == 2, "ZL5 规则表读出来了", QString::number(info.rules.size()));

        // ---- 盘上没有的项**不发明** ----
        NbtTree::Document bare;
        bare.root.type = NbtTree::Type::Compound;
        bare.root.fields = NbtTree::FieldList{
            field(QStringLiteral("Data"), compound(NbtTree::FieldList{}))};
        WorldFiles::WorldInfo bareInfo;
        WorldFiles::readWorldInfo(bare, false, &bareInfo);
        check(!bareInfo.hasLevelName && !bareInfo.hasVersionName && !bareInfo.hasLastPlayed &&
                  !bareInfo.hasDataVersion && !bareInfo.hasAllowCommands && !bareInfo.hasHardcore &&
                  !bareInfo.hasDifficulty && !bareInfo.hasRules,
              "★★ ZL5 一个字段都没有的老存档：八位全是「没有」（**不许拿默认值顶替**）");
        check(!bareInfo.gzipped, "ZL5 不 gzip 的那份也如实报");

        // ---- 形状不对的：当"没有这一项"，不猜 ----
        NbtTree::Document weird;
        weird.root.type = NbtTree::Type::Compound;
        weird.root.fields = NbtTree::FieldList{field(
            QStringLiteral("Data"),
            compound(NbtTree::FieldList{
                field(QStringLiteral("allowCommands"), byteNode(2)),   // 只有 0/1 是真值
                field(QStringLiteral("hardcore"), byteNode(-1)),
                field(QStringLiteral("Difficulty"), byteNode(7)),      // 越界的难度
                field(QStringLiteral("LevelName"), byteNode(1)),       // 世界名不是文字
                field(QStringLiteral("LastPlayed"), stringNode(QStringLiteral("昨天"))),
                field(QStringLiteral("GameRules"),
                      stringNode(QStringLiteral("这不是一张表")))}))};
        WorldFiles::WorldInfo weirdInfo;
        WorldFiles::readWorldInfo(weird, true, &weirdInfo);
        check(!weirdInfo.hasAllowCommands, "★ ZL5 allowCommands = 2 当「没有这一项」（游戏只写 0/1）");
        check(!weirdInfo.hasHardcore, "★ ZL5 hardcore = -1 同上");
        check(!weirdInfo.hasDifficulty, "★ ZL5 难度 7 越界 ⇒ 「没有这一项」（界面上不许打「普通」）");
        check(!weirdInfo.hasLevelName, "ZL5 世界名那一格不是文字 ⇒ 没有");
        check(!weirdInfo.hasLastPlayed, "ZL5 最后游玩时间不是数字 ⇒ 没有");
        check(!weirdInfo.hasRules, "ZL5 GameRules 不是一张表 ⇒ 没有规则表");

        check(WorldFiles::difficultyName(0) == QStringLiteral("和平") &&
                  WorldFiles::difficultyName(1) == QStringLiteral("简单") &&
                  WorldFiles::difficultyName(2) == QStringLiteral("普通") &&
                  WorldFiles::difficultyName(3) == QStringLiteral("困难"),
              "ZL5 四档难度的名字");
        check(WorldFiles::difficultyName(4).isEmpty() && WorldFiles::difficultyName(-1).isEmpty(),
              "★★ ZL5 越界的难度**不给名字**（打「普通」就是在撒谎）");

        // ---- 写回去 ----
        WorldFiles::WorldInfo edited = info;
        edited.levelName = QStringLiteral("改过的世界");
        edited.allowCommands = true;
        edited.hardcore = true;
        edited.difficulty = 3;
        edited.rules[1].value = QStringLiteral("42");
        QString why;
        check(WorldFiles::applyWorldInfo(&document, edited, &why),
              "ZL5 改四项 + 一条规则，全写进去了", why);

        WorldFiles::WorldInfo reread;
        WorldFiles::readWorldInfo(document, true, &reread);
        check(reread.levelName == QStringLiteral("改过的世界"), "ZL5 世界名读回来是新的");
        check(reread.allowCommands, "ZL5 允许作弊读回来是新的");
        check(reread.hardcore, "ZL5 极限模式读回来是新的");
        check(reread.difficulty == 3, "ZL5 难度读回来是新的");
        check(reread.rules.size() == 2 && reread.rules[1].name == QStringLiteral("randomTickSpeed") &&
                  reread.rules[1].value == QStringLiteral("42"),
              "ZL5 规则读回来是新的");
        check(reread.hasLastPlayed && reread.lastPlayedMs == 1758960000000LL,
              "★ ZL5 没被改的那几格原样留着（我们只碰用户在页面上动过的地方）");
        check(reread.rules.size() == 2 && reread.rules[0].value == QStringLiteral("false"),
              "★ ZL5 没改的那条规则一个字都没动");

        // ★ 盘上没有的那一格：`hasXxx = false` 时**不许**顺手造一格出来。
        WorldFiles::WorldInfo invent = bareInfo;
        invent.hasLevelName = false;
        const int bareFields =
            NbtTree::descend(bare.root, QStringLiteral("Data")) != nullptr
                ? NbtTree::descend(bare.root, QStringLiteral("Data"))->fields.size()
                : -1;
        check(WorldFiles::applyWorldInfo(&bare, invent, &why), "ZL5 什么都没改的一趟当然成功");
        check(NbtTree::descend(bare.root, QStringLiteral("Data")) != nullptr &&
                  NbtTree::descend(bare.root, QStringLiteral("Data"))->fields.size() == bareFields,
              "★★ ZL5 什么都没改 ⇒ 一个字段都没多出来");

        // ★★ 2026-09-29：`MissingField::Create` 那一档 —— 界面上那四格**不再按"盘上有没有"
        //    灰掉**（用户原话「并允许修改值」），所以"盘上没有这一格"必须有个着落。
        //    上面那一条量的是**默认那一档**（`Refuse`，一个字段都不多）；这里量 `Create`。
        //
        //    NOTE: 判据里**连类型一起量** —— 建出来一个类型错的字段比"没建"更坏：游戏读到
        //          一个 Int 的 `LevelName` 会当成没有它，而"我们刚写进去了"这句话是真的。
        {
            // 一棵 `Data` 是空复合标签的树（= 一个老存档：这八格一格都没有）。
            NbtTree::Document fresh;
            fresh.root.type = NbtTree::Type::Compound;
            fresh.root.fields =
                NbtTree::FieldList{field(QStringLiteral("Data"), compound(NbtTree::FieldList{}))};
            WorldFiles::WorldInfo wanted;  // 八位全是 false
            wanted.hasLevelName = true;
            wanted.levelName = QStringLiteral("新起的名字");
            wanted.hasAllowCommands = true;
            wanted.allowCommands = true;
            wanted.hasDifficulty = true;
            wanted.difficulty = 3;
            check(WorldFiles::applyWorldInfo(&fresh, wanted, &why,
                                             WorldFiles::MissingField::Create),
                  "★★ ZL5 `MissingField::Create`：盘上没有那几格也写得进去（老档没有 "
                  "`allowCommands` 那一格是常事 —— 它是 1.8 才加的）",
                  why);
            const NbtTree::Node *createdName =
                NbtTree::descend(fresh.root, QStringLiteral("Data/LevelName"));
            check(createdName != nullptr && createdName->type == NbtTree::Type::String &&
                      createdName->text == QStringLiteral("新起的名字"),
                  "★★ ZL5 建出来的世界名是**字符串**那一档（类型错了游戏就当没有它）");
            const NbtTree::Node *createdAllow =
                NbtTree::descend(fresh.root, QStringLiteral("Data/allowCommands"));
            check(createdAllow != nullptr && createdAllow->type == NbtTree::Type::Byte &&
                      createdAllow->number == 1,
                  "★★ ZL5 建出来的「允许作弊」是 **Byte** 那一档（0/1）");
            const NbtTree::Node *createdDiff =
                NbtTree::descend(fresh.root, QStringLiteral("Data/Difficulty"));
            check(createdDiff != nullptr && createdDiff->type == NbtTree::Type::Byte &&
                      createdDiff->number == 3,
                  "★★ ZL5 建出来的难度也是 Byte，值就是刚才那个 3");
            check(NbtTree::descend(fresh.root, QStringLiteral("Data/hardcore")) == nullptr,
                  "★★ ZL5 而 `hasXxx = false` 的那几项**一个都没建** —— `Create` 是「允许建」，"
                  "不是「见到缺的就补」");
            WorldFiles::WorldInfo roundTrip;
            WorldFiles::readWorldInfo(fresh, false, &roundTrip);
            check(roundTrip.hasLevelName && roundTrip.levelName == QStringLiteral("新起的名字") &&
                      roundTrip.hasAllowCommands && roundTrip.allowCommands &&
                      roundTrip.hasDifficulty && roundTrip.difficulty == 3 &&
                      !roundTrip.hasHardcore,
                  "★★ ZL5 写下去再读回来，和要的一模一样（往返一趟对得上）");
        }

        // 连 `Data` 都不是复合标签的时候，`Create` 那一档也一个字节都不动。
        {
            NbtTree::Document odd;
            odd.root.type = NbtTree::Type::Compound;
            odd.root.fields =
                NbtTree::FieldList{field(QStringLiteral("Data"), intNode(7))};
            WorldFiles::WorldInfo wanted;
            wanted.hasLevelName = true;
            wanted.levelName = QStringLiteral("写不进去");
            check(!WorldFiles::applyWorldInfo(&odd, wanted, &why,
                                              WorldFiles::MissingField::Create),
                  "★★ ZL5 `Data` 不是复合标签 ⇒ `Create` 那一档也拒绝（形状看不懂就不动它）");
        }
    }

    section("ZL5b. WorldFiles::knownGameRules / allGameRules（界面上那一列是**全集**）");
    {
        // 用户 2026-09-29 原话：「下面的世界设置不要要求进了世界才显示而是把所有的都列出来，
        // 并允许修改值」。`level.dat` 里那份 `GameRules` 常常只有几条（工具做出来的档、从没
        // 进过一次的档**一条都没有**），所以界面上那一列是拿 `knownGameRules()`（启动器认识
        // 的规则全集）并出来的。这一段量的是那张表本身**站不站得住**。
        QString why;
        const auto compoundOf = [](const NbtTree::FieldList &fields) {
            NbtTree::Node node;
            node.type = NbtTree::Type::Compound;
            node.fields = fields;
            return node;
        };
        const auto fieldOf = [](const QString &name, const NbtTree::Node &node) {
            NbtTree::Field out;
            out.first = name;
            out.second = node;
            return out;
        };
        const QList<WorldFiles::GameRuleDefault> &catalog = WorldFiles::knownGameRules();
        check(catalog.size() >= 40,
              "★★ ZL5b 那张表里有原版那几十条规则（界面上的「列出来所有的」全靠它）",
              QStringLiteral("%1 条").arg(catalog.size()));

        // 名字不许重复（**大小写不敏感**：`GameRules` 是一张表，两个只差大小写的键在
        // 界面上一模一样，用户改哪一个都不知道）；默认值不许是"认不出形状"的那种
        // （那说明表里有个手滑写歪的字，界面上会变成一格随便填的框）。
        QSet<QString> seen;
        QStringList duplicated;
        QStringList oddValues;
        for (const WorldFiles::GameRuleDefault &item : catalog) {
            if (seen.contains(item.name.toLower())) {
                duplicated.append(item.name);
            }
            seen.insert(item.name.toLower());
            if (item.name.isEmpty() || NbtTree::ruleKind(item.value) == NbtTree::ValueKind::Text) {
                oddValues.append(item.name + QLatin1Char('=') + item.value);
            }
        }
        check(duplicated.isEmpty(),
              "★★ ZL5b 表里没有重名的规则（大小写不敏感 —— 两个只差大小写的键在界面上"
              "分不出来）",
              duplicated.join(QLatin1Char('/')));
        check(oddValues.isEmpty(),
              "★★ ZL5b 每一条的默认值都**认得出形状**（true/false 或者数字）—— 不是的话"
              "界面上会变成一格随便填的框，那说明表里有个写歪的字",
              oddValues.join(QLatin1Char('/')));

        // 盘上一条都没有：摆出来的就是全集本身。
        const QList<NbtTree::GameRule> nothing = WorldFiles::allGameRules({});
        check(nothing.size() == catalog.size(),
              "★★ ZL5b 盘上一条规则都没有时，列出来的就是全集（这正是用户那句话要的："
              "不用先进游戏玩一次）",
              QStringLiteral("%1 条").arg(nothing.size()));

        // 排序：大小写不敏感地排好（界面上那一列就是照这个顺序摆的，这一层不重排）。
        const auto sortedOk = [](const QList<NbtTree::GameRule> &list) {
            for (int i = 1; i < list.size(); ++i) {
                if (QString::compare(list[i - 1].name, list[i].name, Qt::CaseInsensitive) > 0) {
                    return false;
                }
            }
            return true;
        };
        check(sortedOk(nothing), "★ ZL5b 那个顺序是排好的（大小写不敏感）");

        // 盘上有值的那一条：**盘上那份说了算**（那是这个世界的真值）。
        QList<NbtTree::GameRule> onDisk;
        {
            NbtTree::GameRule keep;
            keep.name = QStringLiteral("keepInventory");
            keep.value = QStringLiteral("true");  // 默认值是 false
            onDisk.append(keep);
        }
        const QList<NbtTree::GameRule> merged = WorldFiles::allGameRules(onDisk);
        QString mergedKeep;
        for (const NbtTree::GameRule &rule : merged) {
            if (rule.name == QStringLiteral("keepInventory")) {
                mergedKeep = rule.value;
            }
        }
        check(merged.size() == catalog.size() && mergedKeep == QStringLiteral("true"),
              "★★ ZL5b 同一个名字两边都有时**盘上那份说了算**（那是这个世界的真值）",
              mergedKeep);

        // 盘上有、全集里没有的（模组写的、比这张表还新的）：**一条都不许少**。
        QList<NbtTree::GameRule> modded;
        {
            NbtTree::GameRule rule;
            rule.name = QStringLiteral("moddedRule");
            rule.value = QStringLiteral("whatever");
            modded.append(rule);
        }
        const QList<NbtTree::GameRule> withMod = WorldFiles::allGameRules(modded);
        bool found = false;
        for (const NbtTree::GameRule &rule : withMod) {
            if (rule.name == QStringLiteral("moddedRule") && rule.value == QStringLiteral("whatever")) {
                found = true;
            }
        }
        check(withMod.size() == catalog.size() + 1 && found,
              "★★ ZL5b 盘上有、全集里没有的那几条**原样留着**（少列一条就是瞒着用户 —— "
              "他看得见 mods 里那些模组，却看不见模组写进去的规则）",
              QStringLiteral("%1 条").arg(withMod.size()));
        check(sortedOk(withMod),
              "★ ZL5b 从盘上捡回来的那一条**插进了该在的位置**（不是甩到所有小写名字后面）");

        // ---- `applyChangedGameRules()`：只写点名的那些，可以新增 ----
        {
            NbtTree::Document target;
            target.root.type = NbtTree::Type::Compound;
            target.root.fields =
                NbtTree::FieldList{
                    fieldOf(QStringLiteral("Data"), compoundOf(NbtTree::FieldList{}))};
            QList<NbtTree::GameRule> changes;
            {
                NbtTree::GameRule a;
                a.name = QStringLiteral("doDaylightCycle");
                a.value = QStringLiteral("false");
                changes.append(a);
                NbtTree::GameRule b;
                b.name = QStringLiteral("randomTickSpeed");
                b.value = QStringLiteral("7");
                changes.append(b);
            }
            check(WorldFiles::applyChangedGameRules(&target, changes, &why),
                  "★★ ZL5b `applyChangedGameRules()` 把点名的两条都写进去了（连 "
                  "`Data/GameRules` 那一格都没有的档也建得出来）",
                  why);
            QList<NbtTree::GameRule> written;
            NbtTree::gameRulesOf(target.root, &written, &why);
            check(written.size() == 2 && written[0].name == QStringLiteral("doDaylightCycle") &&
                      written[0].value == QStringLiteral("false") &&
                      written[1].value == QStringLiteral("7"),
                  "★★ ZL5b 写进去的就是点名的**那两条**（不是整张全集 —— 一份 44 条的默认值"
                  "塞进用户的存档，那不是编辑）",
                  QStringLiteral("%1 条").arg(written.size()));
            // 空的那一发是空转：一条都不写（`Delta` 为空时走的就是这条路）。
            const NbtTree::Node *rulesNode =
                NbtTree::descend(target.root, QStringLiteral("Data/GameRules"));
            check(rulesNode != nullptr && WorldFiles::applyChangedGameRules(&target, {}, &why) &&
                      rulesNode->fields.size() == 2,
                  "★ ZL5b 一条都不点名的时候是**空转**（一条都不写）");
        }
    }

    section("ZL6. readLevelData / writeLevelData：盘上那一趟（gzip 进、gzip 出）");
    {
        // ---- 先把一棵树写成一个"真"的 level.dat（走 gzip，和盘上那份一样）----
        const auto makeWorldWith = [&](const QString &dirName) {
            const QString dir = scratch.path() + QStringLiteral("/") + dirName;
            QDir().mkpath(dir);
            NbtTree::Document document;
            document.root.type = NbtTree::Type::Compound;
            NbtTree::Field data;
            data.first = QStringLiteral("Data");
            data.second.type = NbtTree::Type::Compound;
            NbtTree::Node nameNode;
            nameNode.type = NbtTree::Type::String;
            nameNode.text = QStringLiteral("原本的名字");
            NbtTree::Node diffNode;
            diffNode.type = NbtTree::Type::Byte;
            diffNode.number = 1;
            NbtTree::Node keepNode;
            keepNode.type = NbtTree::Type::String;
            keepNode.text = QStringLiteral("false");
            NbtTree::Node rulesNode;
            rulesNode.type = NbtTree::Type::Compound;
            NbtTree::Field keepRule;
            keepRule.first = QStringLiteral("keepInventory");
            keepRule.second = keepNode;
            rulesNode.fields = NbtTree::FieldList{keepRule};
            NbtTree::Field nameField;
            nameField.first = QStringLiteral("LevelName");
            nameField.second = nameNode;
            NbtTree::Field diffField;
            diffField.first = QStringLiteral("Difficulty");
            diffField.second = diffNode;
            NbtTree::Field rulesField;
            rulesField.first = QStringLiteral("GameRules");
            rulesField.second = rulesNode;
            data.second.fields = NbtTree::FieldList{nameField, diffField, rulesField};
            document.root.fields = NbtTree::FieldList{data};

            const QString plain = dir + QStringLiteral("/plain.nbt.tmp");
            writeFileAt(plain, NbtTree::serialize(document));
            QString why;
            const bool ok = ZipUtil::gzipFrom(plain, dir + QStringLiteral("/level.dat"), &why);
            QFile::remove(plain);
            return ok;
        };

        const QString dirName = QStringLiteral("世界A");
        check(makeWorldWith(dirName), "ZL6 造了一个真存档（level.dat 是 gzip 的）");
        const QString worldDir = scratch.path() + QStringLiteral("/") + dirName;
        check(QFileInfo(WorldFiles::levelDataPath(worldDir)).exists(), "ZL6 level.dat 就在那个位置");

        WorldFiles::LevelData data;
        QString why;
        check(WorldFiles::readLevelData(worldDir, &data, &why), "ZL6 读得动", why);
        check(data.info.gzipped, "ZL6 认出来它是 gzip 的");
        check(data.info.hasLevelName && data.info.levelName == QStringLiteral("原本的名字"),
              "ZL6 读出来的名字对");
        check(data.info.hasDifficulty && data.info.difficulty == 1, "ZL6 读出来的难度对");
        check(data.info.rules.size() == 1 && data.info.rules[0].name == QStringLiteral("keepInventory"),
              "ZL6 读出来一条规则");

        // ★ 记下**没被改的那些字节**：写回去之后要比。
        const QByteArray before = NbtTree::serialize(data.document);

        data.info.levelName = QStringLiteral("改过的名字");
        data.info.rules[0].value = QStringLiteral("true");
        check(WorldFiles::applyWorldInfo(&data.document, data.info, &why), "ZL6 改两处", why);
        check(WorldFiles::writeLevelData(worldDir, data, &why), "ZL6 写回去", why);

        // 盘上那份要能再读回来，而且形状还是 gzip 的。
        WorldFiles::LevelData back;
        check(WorldFiles::readLevelData(worldDir, &back, &why), "ZL6 写完再读得动", why);
        check(back.info.gzipped, "★★ ZL6 写回去的还是 gzip（形状跟着读进来那一份，游戏才认得）");
        check(back.info.levelName == QStringLiteral("改过的名字"), "ZL6 新名字在盘上");
        check(back.info.rules.size() == 1 && back.info.rules[0].value == QStringLiteral("true"),
              "ZL6 新规则值在盘上");

        // ★★ 这一条是"只改用户动过的格子"那条承诺的**字节级**凭据：拿改之前那棵树和盘上
        //    这一份比，除了那两格，别的地方必须一模一样。
        NbtTree::Document expected = data.document;
        check(NbtTree::serialize(back.document) == NbtTree::serialize(expected),
              "★★ ZL6 写下去的就是「那棵树改了两格」（没有多出任何一格、顺序也没动）");
        check(!before.isEmpty(), "ZL6 改之前那棵树也写得出来（对照用）");

        // ---- 临时文件不许留下 ----
        // ★ 2026-09-28：以前只扫 `.wtfml-*`（那是改动前中间产物的名字）。现在落盘走
        //   `QSaveFile`，它在同一个目录里开的临时文件叫 `level.dat.XXXXXX` —— 换个名字
        //   就漏过了。所以这里改成**把整个目录列出来**：这个世界里除了 `level.dat`
        //   一个文件都不该有。名字变了这条还是拦得住。
        QStringList leftovers =
            QDir(worldDir).entryList(QDir::Files | QDir::Hidden | QDir::System);
        leftovers.removeAll(QStringLiteral("level.dat"));
        check(leftovers.isEmpty(),
              "★★ ZL6 世界目录里除了 level.dat 一个文件都没多出来（游戏会把它们当存档内容扫）",
              leftovers.join(QLatin1Char('/')));

        // ---- 坏档：一句话就说得清，而且**不许**动盘上那份 ----
        const QString badDir = scratch.path() + QStringLiteral("/坏档");
        QDir().mkpath(badDir);
        writeFileAt(WorldFiles::levelDataPath(badDir), QByteArrayLiteral("这不是 gzip，也不是 NBT"));
        WorldFiles::LevelData bad;
        bad.info.levelName = QStringLiteral("哨兵");
        check(!WorldFiles::readLevelData(badDir, &bad, &why), "★★ ZL6 一个坏文件读不动（这就是「坏档」的判据）");
        check(!why.isEmpty(), "ZL6 而且给了一句给人看的原因", why);
        check(bad.info.levelName == QStringLiteral("哨兵"),
              "ZL6 读失败时 out **一个字段都没被碰**（调用方拿着的那份还是那份）");

        // 一个截断的 gzip（头是对的、后面少了）：这是"存到一半断电"的样子。
        const QString cutDir = scratch.path() + QStringLiteral("/截断");
        QDir().mkpath(cutDir);
        QFile gz(WorldFiles::levelDataPath(worldDir));
        QByteArray gzBytes;
        if (gz.open(QIODevice::ReadOnly)) {
            gzBytes = gz.readAll();
        }
        writeFileAt(WorldFiles::levelDataPath(cutDir), gzBytes.left(gzBytes.size() / 2));
        WorldFiles::LevelData cut;
        check(!WorldFiles::readLevelData(cutDir, &cut, &why), "★★ ZL6 截断的 gzip 也读不动（半截的存档）");

        // 文件不在。
        WorldFiles::LevelData missing;
        check(!WorldFiles::readLevelData(scratch.path() + QStringLiteral("/没有这个目录"), &missing, &why),
              "ZL6 文件不在就说文件不在");

        // ---- 不 gzip 的那一份：**不算坏档**，而且写回去还是不加 gzip ----
        //
        // ★ 这一档是被"有没有 gzip 头"那条判据故意放行的：第三方工具（以及少数版本的
        //   服务端）会写不压缩的 level.dat。把它报成"这个存档可能坏了"，用户就得去处理一个
        //   根本没坏的东西。
        const QString rawDir = scratch.path() + QStringLiteral("/不压缩");
        QDir().mkpath(rawDir);
        NbtTree::Document rawDoc;
        rawDoc.root.type = NbtTree::Type::Compound;
        NbtTree::Field rawData;
        rawData.first = QStringLiteral("Data");
        rawData.second.type = NbtTree::Type::Compound;
        NbtTree::Node rawName;
        rawName.type = NbtTree::Type::String;
        rawName.text = QStringLiteral("不压缩的世界");
        rawData.second.fields = NbtTree::FieldList{{QStringLiteral("LevelName"), rawName}};
        rawDoc.root.fields = NbtTree::FieldList{rawData};
        writeFileAt(WorldFiles::levelDataPath(rawDir), NbtTree::serialize(rawDoc));

        WorldFiles::LevelData raw;
        check(WorldFiles::readLevelData(rawDir, &raw, &why),
              "★★ ZL6 一份**没有** gzip 头的 level.dat 照样读得动（不是「坏档」）", why);
        check(!raw.info.gzipped, "ZL6 而且如实说它不是 gzip 的");
        check(raw.info.levelName == QStringLiteral("不压缩的世界"), "ZL6 里面那格名字也读出来了");
        raw.info.levelName = QStringLiteral("不压缩的世界改过");
        WorldFiles::applyWorldInfo(&raw.document, raw.info, &why);
        check(WorldFiles::writeLevelData(rawDir, raw, &why), "ZL6 写回去", why);
        QFile rawFile(WorldFiles::levelDataPath(rawDir));
        QByteArray rawBytes;
        if (rawFile.open(QIODevice::ReadOnly)) {
            rawBytes = rawFile.readAll();
        }
        check(!rawBytes.startsWith("\x1f\x8b"), "★★ ZL6 写回去的那份**没有**被硬套上 gzip（形状跟着原来那份）");
        WorldFiles::LevelData rawBack;
        check(WorldFiles::readLevelData(rawDir, &rawBack, &why) &&
                  rawBack.info.levelName == QStringLiteral("不压缩的世界改过"),
              "ZL6 再把不压缩的那份读回来，改的地方在");
    }
}

// ============================================================================
// ZM. Java 8 的 ASCII 别名（"路径里有非 ASCII 字符就起不来"那个坑）
//
// 真机那趟（2026-09-28）里 `20w14∞` 和中文名的 1.8 整合包都只留下一句
// `找不到或无法加载主类`：Java 8 打不开带非 ASCII 字符的路径（这台机器开着 Windows 的
// "Beta: 使用 Unicode UTF-8"，Java 8 认定的编码却是 GBK）。产品侧的绕法是另建一套纯 ASCII
// 的路径（联接 + 硬链接），判据/建法都在 src/launcher/AsciiPathAlias.hpp 里。
//
// 这一节要**真建**：纯函数那半只证明"我按我写的规则挑了路径"，而"联接真的通向实例目录"
// 这件事只有写一个文件过去、再从另一边看见它才算数。
// ============================================================================
static void runAsciiAliasTests() {
    section("ZM. Java 8 的 ASCII 别名（非 ASCII 路径 ⇒ 联接 + 硬链接）");

    const QString originalDir = AppPaths::minecraftDir();

    // --- ZM1. 纯判据：谁要换、谁不换 ----------------------------------------
    check(AsciiPathAlias::hasNonAscii(QStringLiteral("20w14∞")), "ZM1 目录名里的 ∞ 算非 ASCII");
    check(AsciiPathAlias::hasNonAscii(QStringLiteral("魔改版ATT2-BC&A&IS(多周目)")),
          "ZM1 中文名算非 ASCII");
    check(!AsciiPathAlias::hasNonAscii(QStringLiteral("ATT2-BC&A&IS(1.8) [x] _ + ~ #")),
          "ZM1.5 ★ 判据是「> 0x7F」，不是「看着像特殊字符」—— 那一堆符号全是 ASCII，不许换");
    check(!AsciiPathAlias::hasNonAscii(QStringLiteral("1.21.4-Fabric 0.16.14")),
          "ZM1 纯 ASCII 的名字不算");
    check(!AsciiPathAlias::hasNonAscii(QString()), "ZM1 空串不算");

    const QString uniPath = QStringLiteral("D:/MC/versions/20w14∞");
    check(AsciiPathAlias::needed(8, {uniPath}), "ZM2 Java 8 + 非 ASCII ⇒ 要换");
    check(!AsciiPathAlias::needed(17, {uniPath}), "ZM2 Java 17 ⇒ 不换（它本来就认得 UTF-8）");
    check(!AsciiPathAlias::needed(0, {uniPath}),
          "ZM2 ★ 没探到 Java 版本 ⇒ **不换**（判错的代价不对称，见 .hpp）");
    check(!AsciiPathAlias::needed(8, {QStringLiteral("D:/MC/versions/1.20.1")}),
          "ZM2 全 ASCII ⇒ 不换（真机 70 个实例里 68 个走这条，行为必须逐字节不变）");
    check(!AsciiPathAlias::needed(8, {}), "ZM2 一条路径都没给 ⇒ 不换");

    // --- ZM3. 路径的形状（纯函数） -----------------------------------------
    QTemporaryDir temp;
    const QString root = temp.path() + QStringLiteral("/mc");
    AppPaths::setMinecraftDir(root);

    const QString unicodeId = QStringLiteral("20w14∞");
    const AsciiPathAlias::Paths alias = AsciiPathAlias::pathsFor(unicodeId);
    check(!AsciiPathAlias::hasNonAscii(alias.root),
          "ZM3 ★ 别名根是纯 ASCII 的（这不是讲究：数据目录自己带中文时整套就没用了，"
          "那种情况 ensure() 会直说）",
          alias.root);
    check(alias.root.startsWith(root + QStringLiteral("/cache/ascii/")),
          "ZM3 别名挂在 <数据目录>/cache/ascii 底下（不是 versions/ 里 —— 那底下每个子目录"
          "都会被当成实例，而且游戏自己会扫）",
          alias.root);
    const QString tail = alias.root.mid(alias.root.lastIndexOf(QLatin1Char('/')) + 1);
    check(tail.size() == 12 && !tail.contains(QRegularExpression(QStringLiteral("[^0-9a-f]"))),
          "ZM3 根目录名是 12 位十六进制（实例 id 的哈希）", tail);
    check(AsciiPathAlias::pathsFor(unicodeId).root == alias.root,
          "ZM3 ★ 同一个 id 每次算出来的根一样（所以不能用 qHash —— Qt 6 那个每次进程启动换种子）");
    check(AsciiPathAlias::pathsFor(QStringLiteral("另一份 1.8 包")).root != alias.root,
          "ZM3 两个 id 的根不一样（不会互相盖掉）");
    check(alias.jarFor(QStringLiteral("x.jar")) == alias.jarsDir + QStringLiteral("/x.jar"),
          "ZM3 jarFor() 就是 jarsDir + 文件名");

    // --- ZM4. 真建一遍：联接通不通、硬链接是不是同一份 ----------------------
    const QString instanceDir = AppPaths::versionDir(unicodeId);
    const QString realJar = instanceDir + QLatin1Char('/') + unicodeId + QStringLiteral(".jar");
    const QString realNatives = instanceDir + QStringLiteral("/natives");
    writeFileAt(realJar, QByteArray());
    writeFileAt(realNatives + QStringLiteral("/lwjgl64.dll"), QByteArray("dll"));
    check(!AsciiPathAlias::isReady(alias),
          "ZM4 还没建 ⇒ isReady() 是 false（命令行据此发原来那套路径）");
    QString problem = AsciiPathAlias::ensure(alias, unicodeId, realNatives);
    check(problem.isEmpty(), "ZM4 ensure() 建成功", problem);
    check(AsciiPathAlias::isReady(alias), "ZM4 建完 ⇒ isReady() 是 true");

    // 联接算不算通：**从别名里写一个文件**，看它出不出现在实例目录里。
    writeFileAt(alias.gameDir + QStringLiteral("/saves/probe.txt"), QByteArray("别名这条路是通的"));
    check(QFileInfo(instanceDir + QStringLiteral("/saves/probe.txt")).isFile(),
          "ZM4 ★★ --gameDir 那个联接真的通向实例目录（从别名写进去，实例目录里看得见）");
    check(QFileInfo(alias.gameDir + QStringLiteral("/natives/lwjgl64.dll")).isFile(),
          "ZM4 反过来也成立（实例自己的文件从别名里看得见）");
    check(QFileInfo(alias.nativesDir + QStringLiteral("/lwjgl64.dll")).isFile(),
          "ZM4 natives 那个联接也通（-Djava.library.path 指的就是它）");

    // 硬链接：同一份数据 —— 往别名那一份写，真 jar 跟着变。
    const QString aliasJar = alias.jarFor(unicodeId + QStringLiteral(".jar"));
    writeFileAt(aliasJar, QByteArray("abc"));
    check(QFileInfo(realJar).size() == 3,
          "ZM4 ★★ jars/ 里那份是**硬链接**（往别名写，真 jar 跟着变 —— 不是拷贝）");
    check(QFile::remove(aliasJar) && QFileInfo(realJar).size() == 3,
          "ZM4 删掉别名那一份，真 jar 还在（硬链接只删目录项）");

    // --- ZM5. 幂等 + 自愈 ---------------------------------------------------
    check(AsciiPathAlias::ensure(alias, unicodeId, realNatives).isEmpty() &&
              QFileInfo(aliasJar).isFile(),
          "ZM5 别名的 jar 被删掉之后，再 ensure() 一次就补回来");
    check(AsciiPathAlias::ensure(alias, unicodeId, realNatives).isEmpty(),
          "ZM5 连做两次 ensure() 都成功（幂等；每次启动都会走这条路）");
    check(!QDir(alias.jarsDir)
               .entryList(QStringList() << QStringLiteral("*.jar"), QDir::Files)
               .isEmpty(),
          "ZM5 jars/ 里至少有一个 jar（isReady() 的判据之一）");
    // ★ 每次启动都会走一遍 ensure()，所以"已经在的那一份"必须**原地留着**：建一套新的
    //   （删掉再建）会让联接的创建时间每次都变，而且万一那一刻有别的进程正拿着它、
    //   删除还会失败。判据是创建时间不变 —— 这不是讲究：改坏了不会有任何症状，
    //   只会在真机上留下"每次启动都重建一遍"的额外动作。
    {
        const QDateTime gameBorn = QFileInfo(alias.gameDir).birthTime();
        const QDateTime jarsBorn = QFileInfo(alias.jarsDir).birthTime();
        if (gameBorn.isValid() && jarsBorn.isValid()) {
            check(AsciiPathAlias::ensure(alias, unicodeId, realNatives).isEmpty(),
                  "ZM5' 第三趟 ensure() 也成功");
            check(QFileInfo(alias.gameDir).birthTime() == gameBorn,
                  "★ ZM5' 已经在的那套**原地留着**（没有删掉重建：game 联接的创建时间不变）",
                  QFileInfo(alias.gameDir).birthTime().toString(Qt::ISODate));
            check(QFileInfo(alias.jarsDir).birthTime() == jarsBorn,
                  "★ ZM5' jars/ 那个目录也没被重建（硬链接那一层同样只补缺的）",
                  QFileInfo(alias.jarsDir).birthTime().toString(Qt::ISODate));
        }
    }

    // --- ZM6. 过期的那一套会被清掉（改过名的实例留下的） --------------------
    // 拿**产品自己的** ensure() 造一套"别实例"的别名，再把那个实例删掉 —— 于是那套的
    // game 联接就悬空了（真机上"实例改名/被删"就是这个形状）。
    const QString otherId = QStringLiteral("另一个实例");
    const QString otherDir = AppPaths::versionDir(otherId);
    writeFileAt(otherDir + QLatin1Char('/') + otherId + QStringLiteral(".jar"), QByteArray("j"));
    const AsciiPathAlias::Paths otherAlias = AsciiPathAlias::pathsFor(otherId);
    check(AsciiPathAlias::ensure(otherAlias, otherId, QString()).isEmpty(),
          "ZM6 先给另一个实例建一套别名");
    QDir(otherDir).removeRecursively();
    check(AsciiPathAlias::ensure(alias, unicodeId, realNatives).isEmpty() &&
              !QFileInfo(otherAlias.root).exists(),
          "ZM6 ★ 另一套指向已消失实例的别名被顺手清掉了（不然会一直攒着）");
    check(QFileInfo(alias.root).isDir(), "ZM6 清的时候没碰自己这一套");

    // --- ZM7. 数据目录自己带非 ASCII 时：宁可直说，不建一套没用的 ----------
    const QString unicodeRoot = temp.path() + QStringLiteral("/我的游戏");
    AppPaths::setMinecraftDir(unicodeRoot);
    const AsciiPathAlias::Paths impossible = AsciiPathAlias::pathsFor(unicodeId);
    const QString refusal = AsciiPathAlias::ensure(impossible, unicodeId, QString());
    check(!refusal.isEmpty() && refusal.contains(QStringLiteral("非 ASCII")),
          "ZM7 ★ 数据目录自己不是 ASCII ⇒ ensure() 返回一句人话（要弹窗），不是静默建一套"
          "没用的别名", refusal);
    check(!QFileInfo(impossible.root).exists(),
          "ZM7 而且一个字节都没往盘上写");

    AppPaths::setMinecraftDir(originalDir);  // 收摊：后面那些节读的还是原来那一份
}

// ============================================================================
// ZN. 体检（VersionIntegrity）：只报不装的那套判据
//
// 待办里那条「独立的完整性校验入口」的判据层。**装一遍**那条路早就在了
// （VersionManager::repairVersionFiles，缺什么补什么），缺的是不装新的、只体检：
// 跑一趟，然后告诉用户"你这 3120 个文件里有 2 个要修"。
//
// 这一节全在一个**临时游戏文件夹**里跑（`AppPaths::setMinecraftDir()` 一处切换，跑完
// 换回去）：要造 jar / 库 / 资源索引 / 资源对象四档文件，留在共享沙箱里会给后面的节
// 留下没预料到的包袱。
//
// 这里亲手钉的是**判据**那一半（plan 出哪些条、check 怎么判、Report 怎么数）。清单和
// 实例对得上对不上（"体检说的文件就是这个实例装配时会去下的那些"）在 mw_check 的
// T19.15 —— 那边立着真 MainWindow、真 VersionManager。
// ============================================================================
static void runVersionIntegrityTests() {
    section("ZN. 体检（只报不装）：plan / check / Report");

    const QString originalDir = AppPaths::minecraftDir();
    QTemporaryDir temp;
    check(temp.isValid(), "ZN0 临时数据根目录建出来了");
    if (!temp.isValid()) {
        return;
    }
    AppPaths::setMinecraftDir(temp.path());

    const auto sha1Of = [](const QByteArray &bytes) {
        return QString::fromLatin1(QCryptographicHash::hash(bytes, QCryptographicHash::Sha1).toHex());
    };

    // ---------- ZN1. 清单：产品那两个 extract 函数 + plan() ----------
    // 手搓一份**合并过**的 json（形状照 meta 里那份真的抄），先交给产品自己的
    // extractLibraries() / extractAssetIndex() 解一遍再进 plan() —— 「哪些库算数、哪个
    // 资源索引」的唯一出处就是那两个函数，跳过它们这一节就变成自证了。
    const QByteArray jarBytes = QByteArrayLiteral("client-jar-body");
    const QByteArray libBytes = QByteArrayLiteral("lib-body");
    const QByteArray indexBytes = QByteArrayLiteral("{\"objects\":{}}");

    QJsonObject json;
    json[QStringLiteral("id")] = QStringLiteral("1.99.1");
    json[QStringLiteral("downloads")] = QJsonObject{
        {QStringLiteral("client"),
         QJsonObject{{QStringLiteral("url"), QStringLiteral("https://example.invalid/c.jar")},
                     {QStringLiteral("sha1"), sha1Of(jarBytes)},
                     {QStringLiteral("size"), static_cast<qint64>(jarBytes.size())}}}};
    json[QStringLiteral("libraries")] = QJsonArray{
        QJsonObject{
            {QStringLiteral("name"), QStringLiteral("synth:art:1.0")},
            {QStringLiteral("downloads"),
             QJsonObject{{QStringLiteral("artifact"),
                          QJsonObject{
                              {QStringLiteral("path"), QStringLiteral("synth/art/1.0/art-1.0.jar")},
                              {QStringLiteral("url"), QStringLiteral("https://example.invalid/a.jar")},
                              {QStringLiteral("sha1"), sha1Of(libBytes)},
                              {QStringLiteral("size"), static_cast<qint64>(libBytes.size())}}}}}},
        // 地址和 artifact 都没有的库：装配侧（extractLibraries）就不收它，清单里当然也不该有。
        QJsonObject{{QStringLiteral("name"), QStringLiteral("synth:noartifact:1.0")}}};
    json[QStringLiteral("assetIndex")] =
        QJsonObject{{QStringLiteral("id"), QStringLiteral("5")},
                    {QStringLiteral("sha1"), sha1Of(indexBytes)},
                    {QStringLiteral("size"), static_cast<qint64>(indexBytes.size())},
                    {QStringLiteral("url"), QStringLiteral("https://example.invalid/5.json")}};

    DownloadManager mgr;
    const QList<Library> productLibs = mgr.extractLibraries(json);
    check(productLibs.size() == 1, "ZN1 产品那两个解析里只有一个库带得下地址（另一个是幽灵）",
          QString::number(productLibs.size()));

    const QList<VersionIntegrity::ExpectedFile> files =
        VersionIntegrity::plan(json, QStringLiteral("1.99.1"), productLibs,
                               mgr.extractAssetIndex(json));
    // 索引是空的（这一份 objects 里一条都没有）⇒ 三条：jar / 库 / 索引文件。
    check(files.size() == 3, "ZN1 清单三条：客户端 jar、库、资源索引（objects 是空的）",
          QString::number(files.size()));
    if (files.size() == 3) {
        check(files.at(0).label == QStringLiteral("客户端 jar")
                  && files.at(0).path == InstanceFiles::jarPath(QStringLiteral("1.99.1"))
                  && files.at(0).sha1 == sha1Of(jarBytes)
                  && files.at(0).size == jarBytes.size(),
              "★ ZN1 jar 那一条：落点走 InstanceFiles::jarPath()（装出来的加载器版本没有"
              "自己的 jar，那个函数认得主人是父版本）",
              files.at(0).path);
        check(files.at(1).label == QStringLiteral("synth:art:1.0")
                  && files.at(1).path == AppPaths::libraryDir()
                                             + QStringLiteral("/synth/art/1.0/art-1.0.jar")
                  && files.at(1).sha1 == sha1Of(libBytes) && files.at(1).size == libBytes.size(),
              "ZN1 库那一条落在**共用的** <数据目录>/libraries 底下（不是实例目录里）",
              files.at(1).path);
        check(files.at(2).path == AppPaths::assetsDir() + QStringLiteral("/indexes/5.json")
                  && files.at(2).sha1 == sha1Of(indexBytes),
              "ZN1 资源索引那一条落在 <数据目录>/assets/indexes/<id>.json",
              files.at(2).path);
    }

    // 边界：url / id 有一个空的索引，装配侧一句都不下（downloadAssets 开头那条早退），
    // 所以清单里也不该有它 —— 列了就是无中生有的一条"缺文件"。
    {
        AssetIndex noUrl = mgr.extractAssetIndex(json);
        noUrl.url.clear();
        const QList<VersionIntegrity::ExpectedFile> onlyJarAndLib =
            VersionIntegrity::plan(json, QStringLiteral("1.99.1"), productLibs, noUrl);
        check(onlyJarAndLib.size() == 2,
              "ZN2 ★ 索引没有 url ⇒ 那一条不列（装配时根本不会去下它，报了就是假警报）",
              QString::number(onlyJarAndLib.size()));
        const QList<VersionIntegrity::ExpectedFile> noIndex =
            VersionIntegrity::plan(json, QStringLiteral("1.99.1"), productLibs, AssetIndex());
        check(noIndex.size() == 2, "ZN2 整个 assetIndex 都没有（老 json）⇒ 同样不列");
    }

    // plan() 自己的那两条判据（拿手搓的 Library 直接喂，绕开 extractLibraries）：
    // path 空的跳过（和 downloadLibraries 一样 —— 那种库装配时落不了盘）。
    {
        QList<Library> hand;
        Library noPath;
        noPath.name = QStringLiteral("synth:nopath:1.0");
        hand.append(noPath);
        Library noHash;
        noHash.name = QStringLiteral("synth:nohash:1.0");
        noHash.path = QStringLiteral("synth/nohash/1.0/nohash-1.0.jar");
        hand.append(noHash);
        const QList<VersionIntegrity::ExpectedFile> planned =
            VersionIntegrity::plan(QJsonObject(), QString(), hand, AssetIndex());
        check(planned.size() == 1 && planned.at(0).path == AppPaths::libraryDir()
                                                          + QStringLiteral("/synth/nohash/1.0/"
                                                                           "nohash-1.0.jar"),
              "ZN2 path 为空的库不进清单（装配侧也是这么跳的），没有 sha1 的照进",
              QString::number(planned.size()));
    }

    // ---------- ZN3. check()：六种结论各自怎么判 ----------
    const QString jarPath = InstanceFiles::jarPath(QStringLiteral("1.99.1"));
    const VersionIntegrity::ExpectedFile jarExpected{
        QStringLiteral("客户端 jar"), jarPath, sha1Of(jarBytes), static_cast<qint64>(jarBytes.size())};

    check(VersionIntegrity::check(jarExpected).status == VersionIntegrity::Status::Missing,
          "ZN3 盘上没有 ⇒ Missing");

    writeFileAt(jarPath, jarBytes);
    check(VersionIntegrity::check(jarExpected).ok(),
          "ZN3 内容逐字节一样 ⇒ Ok");

    // 「大小一样、内容不对」：这一档判的只能是 sha1（T19 那个夹具就是这个形状）。
    writeFileAt(jarPath, QByteArray(jarBytes.size(), 'x'));
    {
        const VersionIntegrity::Verdict verdict = VersionIntegrity::check(jarExpected);
        check(verdict.status == VersionIntegrity::Status::WrongSha1,
              "★ ZN3 字节数一样、内容不对 ⇒ WrongSha1（这一档只能是 sha1 判的：字节数那一关"
              "它已经过了）",
              verdict.detail());
        check(verdict.detail() == QStringLiteral("校验不过（内容与 sha1 对不上）"),
              "ZN3 那句话是给用户看的，钉住它", verdict.detail());
    }

    // 0 字节：**在比字节数之前**判 —— 这条判据和 fileAlreadyValid() 里那句同一个理由。
    writeFileAt(jarPath, QByteArray());
    {
        const VersionIntegrity::Verdict verdict = VersionIntegrity::check(jarExpected);
        check(verdict.status == VersionIntegrity::Status::Empty,
              "★ ZN3 0 字节判的是 Empty，不是 WrongSize（下载写了一半被中断留下的那种）",
              verdict.detail());
    }

    writeFileAt(jarPath, QByteArray(jarBytes.size() + 3, 'x'));
    {
        const VersionIntegrity::Verdict verdict = VersionIntegrity::check(jarExpected);
        check(verdict.status == VersionIntegrity::Status::WrongSize
                  && verdict.actualSize == jarBytes.size() + 3
                  && verdict.expectedSize == jarBytes.size(),
              "★ ZN3 字节数对不上就直接判大小，**不去算哈希**（省掉一次 41 MB 的读）",
              verdict.detail());
    }

    // 判据里没有字节数这一档（<= 0）时只比 sha1。
    {
        writeFileAt(jarPath, jarBytes);
        VersionIntegrity::ExpectedFile noSize = jarExpected;
        noSize.size = -1;
        check(VersionIntegrity::check(noSize).ok(),
              "ZN3 判据里没有字节数（-1）时照样能靠 sha1 判对");
        VersionIntegrity::ExpectedFile noHashNoSize = noSize;
        noHashNoSize.sha1.clear();
        check(VersionIntegrity::check(noHashNoSize).ok(),
              "★ ZN3 什么判据都没有的那一条**只要文件在、不是 0 字节**就算好"
              "（资源对象那一档就是这个形状）");
    }

    // NOTE: Unreadable 那一档这里够不着 —— 要造出一份"QFileInfo 说得清楚、真读又读不动"
    //       的文件得占住它（真机上就是"游戏正跑着，jar 被独占"）。这条留到真机上报错了
    //       再看：default 分支那句「读不动」就是为了它在那儿摆着。

    // ---------- ZN4. 资源对象：照索引 json 里那份 objects 表列 ----------
    // 索引 json 的落点由产品自己说了算（<数据目录>/assets/indexes/<id>.json），先按它算出来
    // 再写一份**真的**索引（上面那份 3 条清单用的还是个空的）。
    {
        const QString goodHash = sha1Of(QByteArrayLiteral("object-body"));
        const QString shortHash = QStringLiteral("abc");  // 长度不是 40 ⇒ 装配侧也跳过
        QJsonObject objects;
        objects[QStringLiteral("minecraft/sounds/bark.ogg")] =
            QJsonObject{{QStringLiteral("hash"), goodHash}, {QStringLiteral("size"), 11}};
        objects[QStringLiteral("minecraft/sounds/moo.ogg")] =
            QJsonObject{{QStringLiteral("hash"), shortHash}, {QStringLiteral("size"), 11}};
        writeFileAt(AppPaths::assetsDir() + QStringLiteral("/indexes/5.json"),
                    QJsonDocument(QJsonObject{{QStringLiteral("objects"), objects}})
                        .toJson(QJsonDocument::Compact));

        const QList<VersionIntegrity::ExpectedFile> withObjects =
            VersionIntegrity::plan(json, QStringLiteral("1.99.1"), productLibs,
                                   mgr.extractAssetIndex(json));
        // 索引 json 换了内容 ⇒ 它自己那一条的 sha1/size 也跟着对不上了，但**清单条数**不变:
        // 三条 + 一个资源对象（长度不对的那条被跳过）。
        check(withObjects.size() == 4,
              "★ ZN4 资源对象照 objects 表列出来了，长度不是 40 的那条跳过（装配侧也是）",
              QString::number(withObjects.size()));
        const VersionIntegrity::ExpectedFile &object = withObjects.at(3);
        check(object.path == AppPaths::assetsDir() + QStringLiteral("/objects/")
                                 + goodHash.left(2) + QLatin1Char('/') + goodHash,
              "★ ZN4 落点是 objects/<hash 前两位>/<hash>（和 parseAndDownloadAssets 同一条"
              "规矩）",
              object.path);
        check(object.sha1.isEmpty() && object.size == 11,
              "★ ZN4 判据里**故意没有 sha1**（文件名就是那个 sha1，再哈希一遍等于把最贵的那"
              "一步做两遍），但字节数比（索引里本来就有）");

        // 三档结论：在的、缺的、大小不对的。
        writeFileAt(object.path, QByteArrayLiteral("object-body"));  // 11 字节，对
        check(VersionIntegrity::check(object).ok(), "ZN4 资源对象在、字节数也对 ⇒ Ok");
        VersionIntegrity::ExpectedFile missingObject = object;
        missingObject.path = AppPaths::assetsDir() + QStringLiteral("/objects/ff/");
        missingObject.path += QString(40, QLatin1Char('f'));
        check(VersionIntegrity::check(missingObject).status
                  == VersionIntegrity::Status::Missing,
              "ZN4 不在 ⇒ Missing（那 3000 个对象里少几个是能启动失败的）");
        writeFileAt(object.path, QByteArrayLiteral("short"));
        check(VersionIntegrity::check(object).status == VersionIntegrity::Status::WrongSize,
              "★ ZN4 字节数不对 ⇒ WrongSize（这就是「写盘写到一半」在资源对象上的样子）");
    }

    // 索引文件自己缺了：清单里那条会报 Missing，而 objects **一条都不列**（不然会叠 3000
    // 条噪声，用户修索引就够了）。
    {
        QDir(AppPaths::assetsDir() + QStringLiteral("/indexes")).removeRecursively();
        const QList<VersionIntegrity::ExpectedFile> noIndexFile =
            VersionIntegrity::plan(json, QStringLiteral("1.99.1"), productLibs,
                                   mgr.extractAssetIndex(json));
        check(noIndexFile.size() == 3,
              "★ ZN4 索引 json 不在盘上 ⇒ objects 一条都不列（只有索引自己那一条）",
              QString::number(noIndexFile.size()));
    }

    // 索引在、但里面不是 json（下坏了的）：同样一条都不列，也不崩。
    {
        writeFileAt(AppPaths::assetsDir() + QStringLiteral("/indexes/5.json"),
                    QByteArrayLiteral("<html>404</html>"));
        const QList<VersionIntegrity::ExpectedFile> brokenIndex =
            VersionIntegrity::plan(json, QStringLiteral("1.99.1"), productLibs,
                                   mgr.extractAssetIndex(json));
        check(brokenIndex.size() == 3, "ZN4 索引是个 200+HTML 错误页 ⇒ 照样一条都不列");
    }

    // ---------- ZN5. Report：数得对、那句话拼得对 ----------
    {
        VersionIntegrity::Report report;
        report.checked = 3120;
        check(report.ok() && report.summary() == QStringLiteral("3120 个文件都完好"),
              "★ ZN5 全好的那一句是「N 个文件都完好」", report.summary());

        const auto make = [](VersionIntegrity::Status status) {
            VersionIntegrity::Verdict verdict;
            verdict.status = status;
            return verdict;
        };
        report.problems << make(VersionIntegrity::Status::Missing)
                        << make(VersionIntegrity::Status::Empty)
                        << make(VersionIntegrity::Status::WrongSha1);
        check(!report.ok() && report.missing() == 2 && report.corrupt() == 1,
              "★ ZN5 「缺」= Missing + Empty（两个都在里头）、「坏」= 剩下那些",
              QStringLiteral("missing=%1 corrupt=%2").arg(report.missing()).arg(report.corrupt()));
        check(report.summary()
                  == QStringLiteral("3120 个文件里 3 个要修：缺 2 个、坏 1 个"),
              "★ ZN5 summary() 那一句（界面直接拿它显示，「几个缺几个坏」不许在别处再数一遍）",
              report.summary());

        VersionIntegrity::Report failed;
        failed.error = QStringLiteral("读不出这个实例的 version.json，没法知道它该有哪些文件。");
        check(failed.summary() == failed.error && !failed.ok() && failed.checked == 0,
              "★ ZN5 没跑起来那一档：summary() 原样回 error（和「跑了、发现一堆问题」分开）",
              failed.summary());
    }

    // ---------- ZN6. 分组（coding plan §4.1：结果按客户端 / 库 / 资源索引 / 资源对象 分）----------
    {
        check(VersionIntegrity::allGroups().size() == 4, "ZN6 四组");
        check(VersionIntegrity::groupName(VersionIntegrity::Group::ClientJar)
                      == QStringLiteral("客户端")
                  && VersionIntegrity::groupName(VersionIntegrity::Group::Libraries)
                         == QStringLiteral("库")
                  && VersionIntegrity::groupName(VersionIntegrity::Group::AssetIndex)
                         == QStringLiteral("资源索引")
                  && VersionIntegrity::groupName(VersionIntegrity::Group::AssetObjects)
                         == QStringLiteral("资源对象"),
              "★ ZN6 四组的名字（报告页标题和那段纯文本都读它）");
        // groupIndex() 必须和 allGroups() 的顺序对得上（界面把"正在比哪一组"翻成"第几步"靠它）。
        for (VersionIntegrity::Group group : VersionIntegrity::allGroups()) {
            const int index = VersionIntegrity::groupIndex(group);
            check(index >= 0 && index < VersionIntegrity::allGroups().size()
                      && VersionIntegrity::allGroups().at(index) == group,
                  "ZN6 groupIndex() 回的下标在 allGroups() 里指回它自己",
                  QString::number(index));
        }

        // plan() 在**列清单那一刻**就盖好了组（上面 ZN1 那三条）。
        if (files.size() == 3) {
            check(files.at(0).group == VersionIntegrity::Group::ClientJar
                      && files.at(1).group == VersionIntegrity::Group::Libraries
                      && files.at(2).group == VersionIntegrity::Group::AssetIndex,
                  "★ ZN6 plan() 给每一条盖了组：jar / 库 / 索引各归各的那一格");
        }
        // check() 把组一路带到 Verdict 上（界面按组摊结果时读的就是它）。
        const VersionIntegrity::ExpectedFile missingJar{
            QStringLiteral("客户端 jar"),
            AppPaths::minecraftDir() + QStringLiteral("/nope.jar"), QString(), 100,
            VersionIntegrity::Group::ClientJar};
        const VersionIntegrity::Verdict verdict = VersionIntegrity::check(missingJar);
        check(verdict.group == VersionIntegrity::Group::ClientJar
                  && verdict.status == VersionIntegrity::Status::Missing,
              "★ ZN6 check() 把组带到 Verdict 上（缺文件那一档也带着）");
    }

    // ---------- ZN7. Report 按组数 + 那段纯文本（「复制报告」）----------
    {
        const auto problem = [](VersionIntegrity::Status status, VersionIntegrity::Group group,
                                const QString &label) {
            VersionIntegrity::Verdict verdict;
            verdict.status = status;
            verdict.group = group;
            verdict.label = label;
            verdict.path = QStringLiteral("D:/x/") + label;
            return verdict;
        };
        VersionIntegrity::Report report;
        report.checked = 3120;
        report.problems
            << problem(VersionIntegrity::Status::Missing, VersionIntegrity::Group::Libraries,
                       QStringLiteral("libA"))
            << problem(VersionIntegrity::Status::WrongSha1, VersionIntegrity::Group::Libraries,
                       QStringLiteral("libB"))
            << problem(VersionIntegrity::Status::Empty, VersionIntegrity::Group::AssetObjects,
                       QStringLiteral("objA"));

        check(report.missingIn(VersionIntegrity::Group::Libraries) == 1
                  && report.corruptIn(VersionIntegrity::Group::Libraries) == 1
                  && report.problemsIn(VersionIntegrity::Group::Libraries) == 2,
              "★ ZN7 「库」那一组：缺 1 个、坏 1 个、合计 2 个",
              QStringLiteral("m=%1 c=%2")
                  .arg(report.missingIn(VersionIntegrity::Group::Libraries))
                  .arg(report.corruptIn(VersionIntegrity::Group::Libraries)));
        check(report.problemsIn(VersionIntegrity::Group::ClientJar) == 0
                  && report.problemsIn(VersionIntegrity::Group::AssetIndex) == 0,
              "ZN7 没问题的组报 0（说的是「这组没有要修的」，不是「这组没有文件」）");
        check(report.missingIn(VersionIntegrity::Group::AssetObjects) == 1
                  && report.corruptIn(VersionIntegrity::Group::AssetObjects) == 0,
              "ZN7 资源对象那一组：缺 1 个");
        check(report.problemsInGroup(VersionIntegrity::Group::Libraries).size() == 2
                  && report.problemsInGroup(VersionIntegrity::Group::Libraries).at(0).label
                         == QStringLiteral("libA"),
              "ZN7 problemsInGroup() 只挑这一组的、且保持原来那个顺序");
        // 按组数出来的总和 = 总数（两处口径必须一致 —— 别让分组那一层多算或者漏算）。
        int byGroup = 0;
        for (VersionIntegrity::Group group : VersionIntegrity::allGroups()) {
            byGroup += report.problemsIn(group);
        }
        check(byGroup == report.problems.size()
                  && byGroup == report.missing() + report.corrupt(),
              "ZN7 四组加起来 = 总条数（分组这一层不会漏也不会重）", QString::number(byGroup));

        const QStringList lines =
            VersionIntegrity::plainReport(report, QStringLiteral("1.99.1")).split(QLatin1Char('\n'));
        check(lines.value(0) == QStringLiteral("实例「1.99.1」完整性检查")
                  && lines.value(1)
                         == QStringLiteral("3120 个文件里 3 个要修：缺 2 个、坏 1 个"),
              "★ ZN7 报告头两行：标题 + summary()",
              lines.value(0) + QStringLiteral(" / ") + lines.value(1));
        // 四组一个都不省（哪怕是 0 个要修的那两组）。
        const auto hasLine = [&lines](const QString &needle) {
            for (const QString &line : lines) {
                if (line.contains(needle)) {
                    return true;
                }
            }
            return false;
        };
        for (VersionIntegrity::Group group : VersionIntegrity::allGroups()) {
            check(hasLine(VersionIntegrity::groupName(group) + QStringLiteral("（")),
                  "★ ZN7 报告里四组都有一行（含 0 个要修的那两组）",
                  VersionIntegrity::groupName(group));
        }
        check(hasLine(QStringLiteral("库（2 个要修）"))
                  && hasLine(QStringLiteral("客户端（0 个要修）")),
              "ZN7 组标题写成「名字（N 个要修）」");
        check(hasLine(QStringLiteral("libA：缺少文件")),
              "ZN7 逐条问题写成「名字：那句话」");
        check(lines.contains(QStringLiteral("    D:/x/libA")),
              "ZN7 路径缩进换一行（4 个空格）");

        // 没跑起来那一档：只出两行。
        VersionIntegrity::Report failed;
        failed.error = QStringLiteral("读不出这个实例的 version.json，没法知道它该有哪些文件。");
        const QString failedText = VersionIntegrity::plainReport(failed, QStringLiteral("X"));
        check(failedText == QStringLiteral("实例「X」完整性检查\n") + failed.error,
              "★ ZN7 没跑起来那一档：纯文本只有标题 + 那句 error", failedText);
    }

    AppPaths::setMinecraftDir(originalDir);  // 收摊
}

// ============================================================================
// ZP. 游戏异常退出那几句话（2026-10-12，coding plan §4.3）
//
// 这一节盯的是**规则本身**：`src/diag/GameExitDiagnosis` 是个纯函数（值进、字符串出，
// 不看时钟、不读盘、不开进程），所以那张表能在这里逐格念一遍。
//
// 为什么非要单独验它：§4.3 的原话是「仅做规则明确的提示…不做不透明的『AI 猜错』」。
// "规则明确"这件事唯一能证明的方式，就是**每一条提示都能指着某个字段说"因为它这样"**
// —— 而这条链路在真机上要真起一次游戏、真崩一次才走得到，在这里喂一组值就走完了。
//
// 判据里故意混了**几组"什么都不该说"的**（只拿到一个 Java 主版本、日志没收到、一条错误
// 都没有）：那种情况下多说一句就是猜。
// ============================================================================
static void runGameExitDiagnosisTests() {
    // ---------------------------------------------------------------------
    section("ZP1. 退出码写成一句人话（认不出的原样写，不编）");
    // ---------------------------------------------------------------------
    check(GameExitDiagnosis::exitDescription(-1073741819)
              == QStringLiteral("0xC0000005（内存访问冲突）"),
          "★ ZP1 访问冲突那几个字是认出来的",
          GameExitDiagnosis::exitDescription(-1073741819));
    check(GameExitDiagnosis::exitDescription(-1073740940)
              == QStringLiteral("0xC0000374（堆损坏）"),
          "ZP1 堆损坏");
    check(GameExitDiagnosis::exitDescription(-1073741515)
              == QStringLiteral("0xC0000135（缺一个系统 DLL）"),
          "ZP1 缺 DLL");
    // 十六进制那一截是**由那个已知的码算出来的**（同一件事不写两遍）：`0xC0000006` 是
    // 分页失败，而它的十进制是 -1073741818 —— 差一个数就会指到"访问冲突"上去。
    check(GameExitDiagnosis::exitDescription(-1073741818)
              == QStringLiteral("0xC0000006（内存分页失败）"),
          "★ ZP1 名字和十六进制对得上（不另抄一张表）");
    // 认不出来的**不编**：编一个像样的名字比不写更糟 —— 用户会拿着一个错的名字去搜。
    check(GameExitDiagnosis::exitDescription(1) == QStringLiteral("1"), "★ ZP1 认不出的照原样写");
    check(GameExitDiagnosis::exitDescription(0) == QStringLiteral("0"), "ZP1 零也是原样");

    // ---------------------------------------------------------------------
    section("ZP2. 哪些退出算「异常」");
    // ---------------------------------------------------------------------
    check(!GameExitDiagnosis::isAbnormal(0, false), "★ ZP2 以 0 正常退出的不算异常");
    check(GameExitDiagnosis::isAbnormal(0, true),
          "★ ZP2 崩了但码正好是 0 **也算**（那种 0 什么都不能证明）");
    check(GameExitDiagnosis::isAbnormal(1, false), "ZP2 非 0 退出码算");
    check(GameExitDiagnosis::isAbnormal(-1073741819, false), "ZP2 负的退出码算");
    // 两个重载必须是同一条判据（上面那个调的就是下面这个）。
    GameExitDiagnosis::Facts abnormalFacts;
    abnormalFacts.exitCode = 7;
    check(GameExitDiagnosis::isAbnormal(abnormalFacts)
              == GameExitDiagnosis::isAbnormal(7, false),
          "★ ZP2 两个重载说的是同一条规则");

    // ---------------------------------------------------------------------
    section("ZP3. 一句概括");
    // ---------------------------------------------------------------------
    GameExitDiagnosis::Facts facts;
    facts.instanceName = QStringLiteral("我的整合包");
    facts.instanceId = QStringLiteral("1.20.1-forge");
    facts.crashed = true;
    facts.exitCode = -1073741819;
    check(GameExitDiagnosis::summary(facts)
              == QStringLiteral("「我的整合包」崩溃退出（0xC0000005（内存访问冲突））。"),
          "★ ZP3 崩溃那一档说的是「崩溃退出」",
          GameExitDiagnosis::summary(facts));
    facts.crashed = false;
    facts.exitCode = 3;
    check(GameExitDiagnosis::summary(facts) == QStringLiteral("「我的整合包」以非 0 退出码结束（3）。"),
          "★ ZP3 非崩溃那一档说的是「以非 0 退出码结束」",
          GameExitDiagnosis::summary(facts));
    // 名字空着时不留一个空引号（那种「「」以非 0 退出码结束」看着像坏了）。
    GameExitDiagnosis::Facts noName;
    noName.instanceId = QStringLiteral("1.20.1-forge");
    noName.exitCode = 3;
    check(GameExitDiagnosis::summary(noName)
              == QStringLiteral("「1.20.1-forge」以非 0 退出码结束（3）。"),
          "ZP3 显示名空着时用实例 id 顶上");
    noName.instanceId.clear();
    check(GameExitDiagnosis::summary(noName) == QStringLiteral("游戏以非 0 退出码结束（3）。"),
          "★ ZP3 两个名字都没有时不留空引号", GameExitDiagnosis::summary(noName));

    // ---------------------------------------------------------------------
    section("ZP4. 日志里那几句话认得出来");
    // ---------------------------------------------------------------------
    check(GameExitDiagnosis::logShowsOutOfMemory(
              QStringLiteral("[21:03:11] [Render thread/ERROR] java.lang.OutOfMemoryError: Java heap space")),
          "ZP4 OutOfMemoryError");
    check(!GameExitDiagnosis::logShowsOutOfMemory(QStringLiteral("一切正常")),
          "ZP4 没有就是没有");
    check(!GameExitDiagnosis::logShowsOutOfMemory(QString()), "ZP4 空串不当成有");
    // 三个加载器各自那句原文；大小写不敏感（有的加载器把整行大写）。
    check(GameExitDiagnosis::logShowsMissingDependency(
              QStringLiteral("Missing or unsupported mandatory dependencies:\n\tMod ID: x")),
          "ZP4 NeoForge / Forge 那句");
    check(GameExitDiagnosis::logShowsMissingDependency(
              QStringLiteral("MISSING OR UNSUPPORTED MANDATORY DEPENDENCIES:")),
          "ZP4 大写也认");
    check(GameExitDiagnosis::logShowsMissingDependency(
              QStringLiteral("Mod 'a' requires any version of mod 'b', which is missing!")),
          "ZP4 Fabric 那句");
    check(!GameExitDiagnosis::logShowsMissingDependency(QStringLiteral("Loaded 42 mods")),
          "★ ZP4 没说不许猜（认的是加载器自己那句原文，不是我们按清单猜）");

    // ---------------------------------------------------------------------
    section("ZP5. 提示那张表：每一条都指着某个字段");
    // ---------------------------------------------------------------------
    // 这一节的底：**"这一趟收到了游戏的输出"**。⑧那一条（没收到输出）在 `logCaptured`
    // 为假时**必然**多说一句，而下面绝大多数判据要量的是别的规则 —— 所以先把它摆成"收到了"，
    // 想验⑧的那两处再单独翻过去（见 ZP5 ⑦/⑧）。
    GameExitDiagnosis::Facts base;
    base.logCaptured = true;

    // ① Java 版本对不上 —— **两个数都非 0 才说话**：只拿到一个的时候分不出"对得上"和
    //    "没测出来"，那时候说"版本不匹配"就是猜。
    GameExitDiagnosis::Facts javaMismatch = base;
    javaMismatch.requiredJavaMajor = 21;
    javaMismatch.usedJavaMajor = 17;
    javaMismatch.javaPath = QStringLiteral("D:/Java/jdk17/bin/java.exe");
    const QStringList javaHints = GameExitDiagnosis::hints(javaMismatch);
    check(javaHints.size() == 1 && javaHints.first().contains(QStringLiteral("要求 Java 21"))
              && javaHints.first().contains(QStringLiteral("实际用的是 Java 17"))
              && javaHints.first().contains(QStringLiteral("D:/Java/jdk17/bin/java.exe")),
          "★ ZP5 ①Java 对不上（两个数都有时说得出来）",
          javaHints.join(QStringLiteral(" | ")));
    GameExitDiagnosis::Facts onlyRequired = javaMismatch;
    onlyRequired.usedJavaMajor = 0;   // 实际用的那个没读出来
    onlyRequired.javaPath.clear();
    check(GameExitDiagnosis::hints(onlyRequired).isEmpty(),
          "★ ZP5 ①只拿到「要什么」时**闭嘴**（那正是猜）");
    GameExitDiagnosis::Facts sameMajor = javaMismatch;
    sameMajor.usedJavaMajor = 21;
    check(GameExitDiagnosis::hints(sameMajor).isEmpty(), "ZP5 ①对得上时也不说话");

    // ② 内存：**超过物理内存**和**接近打满**分开说（前者一定分不到，后者抢起来才不够）。
    GameExitDiagnosis::Facts overMemory = base;
    overMemory.xmxMb = 65536;
    overMemory.totalMemoryMb = 32768;
    const QStringList overHints = GameExitDiagnosis::hints(overMemory);
    check(overHints.size() == 1 && overHints.first().contains(QStringLiteral("65536"))
              && overHints.first().contains(QStringLiteral("总共只有 32768 MB")),
          "★ ZP5 ②要的比机器有的还多 ⇒ 一定分不到",
          overHints.join(QStringLiteral(" | ")));
    GameExitDiagnosis::Facts nearMemory = base;
    nearMemory.xmxMb = 28672;   // 32768 的 7/8
    nearMemory.totalMemoryMb = 32768;
    const QStringList nearHints = GameExitDiagnosis::hints(nearMemory);
    check(nearHints.size() == 1 && nearHints.first().contains(QStringLiteral("四分之三以上")),
          "ZP5 ②占了四分之三以上 ⇒ 另一句（口风不一样）",
          nearHints.join(QStringLiteral(" | ")));
    // 边界：判据是 `xmx * 4 > 总内存 * 3`，所以**正好四分之三不算**"以上"（那一侧是开的）。
    // 24576 / 32768 正好是四分之三 —— 这一档一个字都不该说。
    GameExitDiagnosis::Facts exactlyThreeQuarters = base;
    exactlyThreeQuarters.xmxMb = 24576;
    exactlyThreeQuarters.totalMemoryMb = 32768;
    check(GameExitDiagnosis::hints(exactlyThreeQuarters).isEmpty(),
          "★ ZP5 ②正好四分之三 ⇒ 不算「以上」（边界是开的）");
    GameExitDiagnosis::Facts smallMemory = base;
    smallMemory.xmxMb = 4096;
    smallMemory.totalMemoryMb = 32768;
    check(GameExitDiagnosis::hints(smallMemory).isEmpty(), "ZP5 ②分得很少时不说内存");

    // ③ 日志里那句 OutOfMemoryError —— 比"看着悬"那条更硬（JVM 自己说了）。
    GameExitDiagnosis::Facts oom;
    oom.sawOutOfMemory = true;
    oom.logCaptured = true;
    check(GameExitDiagnosis::hints(oom).size() == 1
              && GameExitDiagnosis::hints(oom).first().contains(QStringLiteral("OutOfMemoryError")),
          "★ ZP5 ③日志里写着 OutOfMemoryError");

    // ④ 缺前置：依据是**加载器自己打的那句**，所以**不报个数**（我们手上确实没有那个数）。
    GameExitDiagnosis::Facts missing;
    missing.sawMissingDependency = true;
    missing.logCaptured = true;
    const QStringList missingHints = GameExitDiagnosis::hints(missing);
    check(missingHints.size() == 1
              && missingHints.first().contains(QStringLiteral("前置没装"))
              && missingHints.first().contains(QStringLiteral("检查更新")),
          "★ ZP5 ④缺前置那一条 (指向「检查更新」)",
          missingHints.join(QStringLiteral(" | ")));
    check(!missingHints.first().contains(QStringLiteral("个"))
              || missingHints.first().contains(QStringLiteral("哪一个")),
          "ZP5 ④不编一个数出来");

    // ⑤ 崩的方式：同一句"坏内存"，**原版和装了加载器的口风不一样**。
    GameExitDiagnosis::Facts vanillaCrash;
    vanillaCrash.crashed = true;
    vanillaCrash.exitCode = -1073741819;
    vanillaCrash.logCaptured = true;
    const QStringList vanillaHints = GameExitDiagnosis::hints(vanillaCrash);
    check(vanillaHints.size() == 1
              && vanillaHints.first().contains(QStringLiteral("驱动")),
          "★ ZP5 ⑤原版崩在坏内存上 ⇒ 指向本机驱动/安全软件",
          vanillaHints.join(QStringLiteral(" | ")));
    GameExitDiagnosis::Facts moddedCrash = vanillaCrash;
    moddedCrash.loaderName = QStringLiteral("Fabric");
    const QStringList moddedHints = GameExitDiagnosis::hints(moddedCrash);
    check(moddedHints.size() == 1 && moddedHints.first().contains(QStringLiteral("模组"))
              && !moddedHints.first().contains(QStringLiteral("驱动")),
          "★ ZP5 ⑤装了加载器 ⇒ 指向模组/前置（不是驱动）",
          moddedHints.join(QStringLiteral(" | ")));

    // ⑥ 加载期就死了：不是"跑到一半崩了"，排查方向差很远（缺运行库 / 被安全软件拦了）。
    GameExitDiagnosis::Facts loadFailure;
    loadFailure.exitCode = -1073741515;
    loadFailure.logCaptured = true;
    const QStringList loadHints = GameExitDiagnosis::hints(loadFailure);
    check(loadHints.size() == 1 && loadHints.first().contains(QStringLiteral("加载阶段")),
          "★ ZP5 ⑥缺 DLL 那一档说的是「进程压根没起来」",
          loadHints.join(QStringLiteral(" | ")));

    // ⑦ 非崩溃、非 0、日志里一条错误都没有 ⇒ 最像"它就是自己退出的"。**只在确实拿到了
    //    日志的情况下说** —— 没开日志开关时"没有错误行"什么都不代表。
    GameExitDiagnosis::Facts quietExit;
    quietExit.exitCode = 1;
    quietExit.logCaptured = true;
    quietExit.errorLineCount = 0;
    const QStringList quietHints = GameExitDiagnosis::hints(quietExit);
    check(quietHints.size() == 1 && quietHints.first().contains(QStringLiteral("自己退出")),
          "★ ZP5 ⑦自己退出那一档", quietHints.join(QStringLiteral(" | ")));
    GameExitDiagnosis::Facts quietNoLog = quietExit;
    quietNoLog.logCaptured = false;
    check(GameExitDiagnosis::hints(quietNoLog).size() == 1
              && GameExitDiagnosis::hints(quietNoLog).first().contains(QStringLiteral("没有收到")),
          "★ ZP5 ⑦没拿到日志时**不说**「自己退出」，改说「没收到输出」",
          GameExitDiagnosis::hints(quietNoLog).join(QStringLiteral(" | ")));

    // ⑧ 什么都没拿到 ⇒ **一个空表**（不是一句"可能有很多原因"）。
    GameExitDiagnosis::Facts nothing;
    nothing.crashed = true;
    nothing.exitCode = -1;   // 认不出来的码
    nothing.logCaptured = false;
    check(GameExitDiagnosis::hints(nothing).size() == 1
              && GameExitDiagnosis::hints(nothing).first().contains(QStringLiteral("没有收到")),
          "ZP5 ⑧跑到这儿至少会有一句「没收到输出」");

    // 全都有的时候：条数 = 那几条都在，而且**不重复**。
    GameExitDiagnosis::Facts everything;
    everything.crashed = true;
    everything.exitCode = -1073741819;
    everything.requiredJavaMajor = 21;
    everything.usedJavaMajor = 8;
    everything.xmxMb = 65536;
    everything.totalMemoryMb = 16384;
    everything.loaderName = QStringLiteral("Forge");
    everything.logCaptured = true;
    everything.errorLineCount = 3;
    everything.sawOutOfMemory = true;
    everything.sawMissingDependency = true;
    const QStringList all = GameExitDiagnosis::hints(everything);
    check(all.size() == 5,
          "★ ZP5 全都凑齐时五条各说各的（Java / 内存 / OOM / 缺前置 / 崩的方式）",
          QString::number(all.size()));
    QSet<QString> unique;
    for (const QString &hint : all) {
        unique.insert(hint);
    }
    check(unique.size() == all.size(), "ZP5 一条都不重复");
    // ★ 顺序稳定：同一个输入永远同一串话（验证工程和以后的界面都指着这一条）。
    check(GameExitDiagnosis::hints(everything) == all, "★ ZP5 同一份事实永远同一串话");
}

/**
 * @brief 世界与实例备份（2026-10-13，coding plan §4.4）：清单 / 打包 / 还原。
 *
 * 这一节**真打 zip**（走产品那条 PowerShell / .NET 的路）、**真删目录**、**真还原**，
 * 所以它在一个 `QTemporaryDir` 里换一次 `AppPaths::setMinecraftDir()`（备份落点就是
 * `<数据目录>/cache/backups`），跑完换回来 —— 不碰共享沙盒。
 *
 * 盯的是四件事，每一件都是"错了会静默丢东西"的那种：
 *   ① 清单里的名字 / 大小 / sha1 是**数出来的**，不是别人说多少就是多少；
 *   ② 排除只按**顶层目录名**（别处的同名目录照收）；
 *   ③ 还原之前**先**给"现在这一份"做安全快照，**做不成就不许动**；
 *   ④ 解出来了还要**逐文件对账**（"在"和"对"是两件事）。
 */
static void runBackupTests() {
    section("ZQ. 世界与实例备份：清单 / 打包 / 还原（§4.4）");

    const QString originalDir = AppPaths::minecraftDir();
    QTemporaryDir temp;
    check(temp.isValid(), "ZQ0 临时数据根目录建出来了");
    if (!temp.isValid()) {
        return;
    }
    AppPaths::setMinecraftDir(temp.path());

    const auto sha1Of = [](const QByteArray &bytes) {
        return QString::fromLatin1(QCryptographicHash::hash(bytes, QCryptographicHash::Sha1).toHex());
    };
    const auto fileAt = [](const QList<BackupFiles::FileRecord> &list, const QString &path) {
        for (const BackupFiles::FileRecord &record : list) {
            if (record.path == path) {
                return record;
            }
        }
        return BackupFiles::FileRecord();
    };
    const auto readAll = [](const QString &path) {
        QByteArray bytes;
        QFile file(path);
        if (file.open(QIODevice::ReadOnly)) {
            bytes = file.readAll();
        }
        return bytes;
    };
    const auto recordOf = [&sha1Of](const QString &path, const QByteArray &bytes) {
        BackupFiles::FileRecord record;
        record.path = path;
        record.size = bytes.size();
        record.sha1 = sha1Of(bytes);
        return record;
    };

    const QString work = temp.path() + QStringLiteral("/work");
    const QDateTime at = QDateTime::fromString(QStringLiteral("2026-10-13T10:15:30"), Qt::ISODate);

    // ---------- ZQ1. 清单本身：往返、格式标记、前缀的合法性 ----------
    //
    // 清单是这一整套的凭据，所以先把它单独钉一遍：进 JSON 之前和出 JSON 之后**逐格一样**
    // （少一格就是"还原出来落错地方"），认不出的格式 / 可疑的前缀**整份不认**。
    BackupFiles::Manifest sample;
    sample.kind = BackupFiles::Kind::World;
    sample.root = QStringLiteral("基地周目");
    sample.label = QStringLiteral("基地周目");
    sample.sourceInstanceId = QStringLiteral("1.20.1-forge-47.2.0");
    sample.sourceInstanceName = QStringLiteral("我的整合");
    sample.gameVersion = QStringLiteral("1.20.1（Forge 47.2.0）");
    sample.worldName = QStringLiteral("基地周目");
    sample.createdAt = at;
    sample.scope = QStringList{BackupFiles::scopeLine(QStringLiteral("saves/基地周目"), 2)};
    sample.files = QList<BackupFiles::FileRecord>{
        recordOf(QStringLiteral("level.dat"), QByteArrayLiteral("LEVELDATA")),
        recordOf(QStringLiteral("region/r.0.0.mca"), QByteArrayLiteral("REGION-0-0"))};
    // 故意写一个错的总数：清单是**记录**，不是凭据 —— 手改过这个数，界面上的"共 N MB"
    // 不该跟着错（下面 ZQ1 第三条就是钉这个）。
    sample.totalBytes = 999999;

    bool ok = false;
    const BackupFiles::Manifest back =
        BackupFiles::manifestFromJson(BackupFiles::manifestToJson(sample), &ok);
    check(ok && back.kind == BackupFiles::Kind::World && back.root == sample.root &&
              back.label == sample.label && back.sourceInstanceId == sample.sourceInstanceId &&
              back.sourceInstanceName == sample.sourceInstanceName &&
              back.gameVersion == sample.gameVersion && back.worldName == sample.worldName &&
              back.createdAt == sample.createdAt && back.scope == sample.scope,
          "★ ZQ1 清单往返：§4.4 点名的四样（来源实例 id / 时间 / 游戏版本 / 包含范围）一字不差",
          back.gameVersion);
    check(back.files.size() == 2 &&
              fileAt(back.files, QStringLiteral("region/r.0.0.mca")).sha1
                  == sha1Of(QByteArrayLiteral("REGION-0-0")) &&
              fileAt(back.files, QStringLiteral("region/r.0.0.mca")).size == 10,
          "ZQ1 逐文件记录（名字 / 大小 / sha1）往返");
    check(back.totalBytes == 19 && back.totalBytes != sample.totalBytes,
          "★ ZQ1 totalBytes 以数出来的为准（手改过那个数不作数）",
          QString::number(back.totalBytes));

    // 格式标记对不上 → 整份不认。**这是最要紧的一条**：别的启动器做的包（或者以后我们自己
    // 改了格式的旧包）只能被挡住，不能被半信半疑地往里解。
    QByteArray forged = BackupFiles::manifestToJson(sample);
    forged.replace(BackupFiles::formatTag().toUtf8(), QByteArrayLiteral("other-launcher/1"));
    bool forgedOk = true;
    check(!(BackupFiles::manifestFromJson(forged, &forgedOk).isValid()) && !forgedOk,
          "★★ ZQ1 格式标记对不上就整份不认（别人的包绝不半信半疑地往里解）");

    const QByteArray oddKind = QByteArrayLiteral(
        "{\"format\":\"wtfml-backup/1\",\"kind\":\"tarball\",\"root\":\"x\","
        "\"createdAt\":\"2026-10-13T10:15:30\"}");
    bool oddOk = true;
    check(!BackupFiles::manifestFromJson(oddKind, &oddOk).isValid() && !oddOk,
          "★★ ZQ1 认不出的档（既不是 world 也不是 instance）→ 整份不认，不猜");

    check(!BackupFiles::Manifest().isValid(), "ZQ1 空清单不算数（前缀和时间都得有）");
    BackupFiles::Manifest escape = sample;
    escape.root = QStringLiteral("../别人的目录");
    check(!escape.isValid(), "★★ ZQ1 前缀里带 `..` 的清单不认（还原的落点是拼出来的）");
    escape.root = QStringLiteral("a/b");
    check(!escape.isValid(), "★★ ZQ1 前缀里带 `/` 的清单不认");
    escape.root = QStringLiteral("C:/Windows");
    check(!escape.isValid(), "★★ ZQ1 前缀是绝对路径的清单不认");
    escape.root = QStringLiteral("..");
    check(!escape.isValid(), "ZQ1 前缀就是 `..` 的清单不认");
    const QByteArray slashRoot = QByteArrayLiteral(
        "{\"format\":\"wtfml-backup/1\",\"kind\":\"world\",\"root\":\"../../x\","
        "\"createdAt\":\"2026-10-13T10:15:30\"}");
    bool slashOk = true;
    check(!BackupFiles::manifestFromJson(slashRoot, &slashOk).isValid() && !slashOk,
          "★ ZQ1 从 JSON 读进来那条路也挡住了（不是只有手搓的结构体才查）");

    // 实例快照那两个字段只对它有意义：一个恒为 false 的 `complete` 落在世界备份上，
    // 读的人只会以为那是个开关。
    BackupFiles::Manifest snap = sample;
    snap.kind = BackupFiles::Kind::Instance;
    snap.root = QStringLiteral("1.20.1-forge-47.2.0");
    snap.worldName.clear();
    snap.complete = false;
    snap.excluded = QStringList{QStringLiteral("assets"), QStringLiteral("libraries")};
    const QByteArray snapJson = BackupFiles::manifestToJson(snap);
    check(snapJson.contains(QByteArrayLiteral("\"excluded\"")) &&
              !BackupFiles::manifestToJson(sample).contains(QByteArrayLiteral("\"excluded\"")),
          "ZQ1 `excluded` / `complete` 只有实例快照才写（世界备份无从排除起）");
    bool snapOk = false;
    const BackupFiles::Manifest snapBack = BackupFiles::manifestFromJson(snapJson, &snapOk);
    check(snapOk && snapBack.kind == BackupFiles::Kind::Instance && !snapBack.complete &&
              snapBack.excluded == snap.excluded && snapBack.worldName.isEmpty(),
          "ZQ1 实例快照那份（完整标记 + 排除表）往返");

    // ---------- ZQ2. 走目录：哪些进、排序、排除只看顶层 ----------
    const QString worldDir = work + QStringLiteral("/基地周目");
    writeFileAt(worldDir + QStringLiteral("/level.dat"), QByteArrayLiteral("LEVELDATA"));
    writeFileAt(worldDir + QStringLiteral("/region/r.0.0.mca"), QByteArrayLiteral("REGION-0-0"));
    writeFileAt(worldDir + QStringLiteral("/region/r.0.-1.mca"), QByteArrayLiteral("REGION-0-N1"));
    writeFileAt(worldDir + QStringLiteral("/sub/assets/keep.txt"), QByteArrayLiteral("keep"));
    writeFileAt(worldDir + QStringLiteral("/assets/skip.txt"), QByteArrayLiteral("skip"));
    writeFileAt(worldDir + QStringLiteral("/.session.lock"), QByteArrayLiteral("lock"));

    QString collectProblem;
    const QList<BackupFiles::FileRecord> allFiles =
        BackupFiles::collectFiles(worldDir, QStringList(), &collectProblem);
    check(collectProblem.isEmpty() && allFiles.size() == 6,
          "ZQ2 走一遍世界目录：6 个文件（嵌套的、名字里带点的都在）",
          QString::number(allFiles.size()) + " / " + collectProblem);
    check(fileAt(allFiles, QStringLiteral("region/r.0.0.mca")).sha1
              == sha1Of(QByteArrayLiteral("REGION-0-0")) &&
              fileAt(allFiles, QStringLiteral(".session.lock")).size == 4,
          "ZQ2 每条记录的校验值是按盘上内容真算的");

    QStringList collected;
    for (const BackupFiles::FileRecord &record : allFiles) {
        collected.append(record.path);
    }
    QStringList sorted = collected;
    std::sort(sorted.begin(), sorted.end());
    check(collected == sorted,
          "★★ ZQ2 清单按路径排序（同一份内容打两次包，清单要逐字一样）", collected.join('|'));
    const QList<BackupFiles::FileRecord> again =
        BackupFiles::collectFiles(worldDir, QStringList(), nullptr);
    QStringList collectedAgain;
    for (const BackupFiles::FileRecord &record : again) {
        collectedAgain.append(record.path);
    }
    check(collectedAgain == collected, "ZQ2 走两遍结果一样");

    const QList<BackupFiles::FileRecord> noAssets =
        BackupFiles::collectFiles(worldDir, QStringList{QStringLiteral("assets")}, nullptr);
    check(noAssets.size() == 5 && fileAt(noAssets, QStringLiteral("assets/skip.txt")).path.isEmpty(),
          "★ ZQ2 顶层 `assets/` 被排除掉了（§4.4：默认不收能重新下回来的那一堆）",
          QString::number(noAssets.size()));
    check(fileAt(noAssets, QStringLiteral("sub/assets/keep.txt")).path
              == QStringLiteral("sub/assets/keep.txt"),
          "★★ ZQ2 排除**只看顶层**：某个模组自己 data 里的 assets 照收不误"
          "（按名字全局排除会悄悄漏东西，几年之后才有人发现）");

    const QString emptyDir = work + QStringLiteral("/空目录");
    QDir().mkpath(emptyDir);
    QString emptyProblem;
    check(BackupFiles::collectFiles(emptyDir, QStringList(), &emptyProblem).isEmpty() &&
              emptyProblem.isEmpty(),
          "ZQ2 空目录回一张空表，**不是**一个错误（空表和「没走成」分得开）");
    QString missingProblem;
    check(BackupFiles::collectFiles(work + QStringLiteral("/没有这个目录"), QStringList(),
                                    &missingProblem)
                    .isEmpty() &&
              !missingProblem.isEmpty(),
          "ZQ2 目录不在时如实报错", missingProblem);

    // ---------- ZQ3. 打包：真打一个 zip，再用产品的读侧读回来 ----------
    BackupFiles::Manifest spec;
    spec.kind = BackupFiles::Kind::World;
    spec.root = QStringLiteral("基地周目");
    spec.label = QStringLiteral("基地周目");
    spec.sourceInstanceId = QStringLiteral("1.20.1-forge-47.2.0");
    spec.sourceInstanceName = QStringLiteral("我的整合");
    spec.gameVersion = QStringLiteral("1.20.1（Forge 47.2.0）");
    spec.worldName = QStringLiteral("基地周目");
    spec.scope = QStringList{BackupFiles::scopeLine(QStringLiteral("saves/基地周目"), 6)};
    // createdAt 故意不填：用户在界面上点的没有"时间"这回事，是打包那一趟补上的。

    const QString worldZip = BackupFiles::backupDir(BackupFiles::Kind::World) + QLatin1Char('/')
                             + BackupFiles::backupFileName(spec.label, at);
    const BackupFiles::WriteResult written = BackupFiles::writeBackup(spec, worldDir, worldZip);
    check(written.ok && QFile::exists(worldZip), "ZQ3 世界备份真打出来了", written.problem);
    check(written.manifest.fileCount() == 6 && written.manifest.createdAt.isValid() &&
              written.manifest.totalBytes == 9 + 10 + 11 + 4 + 4 + 4,
          "★ ZQ3 清单里的条数和总数是这一趟自己数出来的，时间也是这一趟补上的",
          QString::number(written.manifest.fileCount()));
    if (written.ok) {
        const QByteArray zipBytes = readAll(worldZip);
        check(zipBytes.contains(QByteArrayLiteral("wtfml-backup.json")) &&
                  zipBytes.contains(QByteArrayLiteral("/region/r.0.0.mca")),
              "★ ZQ3 zip 里：清单躺在**根上**，世界那堆文件在**一层前缀底下**"
              "（清单放前缀里就会被解回用户的世界目录）");

        bool readOk = false;
        QString readProblem;
        const BackupFiles::Manifest readBack =
            BackupFiles::readManifest(worldZip, &readOk, &readProblem);
        check(readOk && readBack.kind == BackupFiles::Kind::World &&
                  readBack.root == QStringLiteral("基地周目") &&
                  readBack.sourceInstanceId == spec.sourceInstanceId &&
                  readBack.gameVersion == spec.gameVersion && readBack.fileCount() == 6,
              "ZQ3 产品的读侧把这份包读回来了（含来源实例 id 和游戏版本）", readProblem);
    }

    // 别人的包：压缩包是好的，就是没有我们那份清单。
    const QString foreignZip = work + QStringLiteral("/别人的包.zip");
    writeFileAt(work + QStringLiteral("/别人的包.txt"), QByteArrayLiteral("hello"));
    QString foreignZipError;
    check(ZipUtil::createZip(
              foreignZip,
              {{QStringLiteral("别人的包.txt"), work + QStringLiteral("/别人的包.txt")}},
              &foreignZipError),
          "ZQ3 造一个别人的包（内容好好的，就是没有我们那份清单）", foreignZipError);
    bool foreignOk = true;
    QString foreignProblem;
    BackupFiles::readManifest(foreignZip, &foreignOk, &foreignProblem);
    check(!foreignOk && foreignProblem.contains(QStringLiteral("没有备份清单")),
          "★★ ZQ3 「不是本启动器做的包」和「读不动」是**两句不同的话**（这里说的是前者，"
          "不然用户会去怀疑一个其实好好的文件）",
          foreignProblem);
    bool junkOk = true;
    QString junkProblem;
    BackupFiles::readManifest(work + QStringLiteral("/别人的包.txt"), &junkOk, &junkProblem);
    check(!junkOk && junkProblem.contains(QStringLiteral("不是一个压缩包")),
          "ZQ3 拿一个根本不是压缩包的文件来 → 说的是「打不开」", junkProblem);

    // 打不成的那几路：一个半成品都不许留在盘上。
    const QString neverZip = work + QStringLiteral("/不该出现.zip");
    const BackupFiles::WriteResult missing =
        BackupFiles::writeBackup(spec, work + QStringLiteral("/没有这个目录"), neverZip);
    check(!missing.ok && !missing.problem.isEmpty() && !QFile::exists(neverZip),
          "★ ZQ3 来源目录不在 → 如实报错，盘上不留半成品", missing.problem);
    BackupFiles::Manifest noRoot = spec;
    noRoot.root.clear();
    check(!BackupFiles::writeBackup(noRoot, worldDir, neverZip).ok,
          "ZQ3 没说清前缀的清单打不了包（还原时落点拼不出来）");
    const BackupFiles::WriteResult emptyWrite =
        BackupFiles::writeBackup(spec, emptyDir, work + QStringLiteral("/空.zip"));
    check(!emptyWrite.ok && !QFile::exists(work + QStringLiteral("/空.zip")),
          "ZQ3 空目录没什么可备份的（不是打一个空包出来）", emptyWrite.problem);

    // ---------- ZQ4. 还原：安全快照、拒绝、对账 ----------
    const QString restoreParent = work + QStringLiteral("/还原到这儿");
    QDir().mkpath(restoreParent);
    const QString restoredWorld = restoreParent + QStringLiteral("/基地周目");

    // ① 还原到一块空地：那儿本来什么都没有，所以**不该**做安全快照。
    const BackupFiles::RestoreResult fresh = BackupFiles::restoreBackup(worldZip, restoreParent);
    check(fresh.ok && fresh.checked == 6 && fresh.mismatched == 0 && fresh.safetyZip.isEmpty(),
          "ZQ4 还原到一块空地：6 个文件全对上，没做安全快照（那儿本来什么都没有）",
          fresh.problem);
    check(fresh.targetPath == restoredWorld,
          "★ ZQ4 落点 = 目标父目录 + 清单里那个前缀（不是文件名，也不是别处）",
          fresh.targetPath);
    check(readAll(restoredWorld + QStringLiteral("/level.dat")) == QByteArrayLiteral("LEVELDATA") &&
              readAll(restoredWorld + QStringLiteral("/region/r.0.0.mca"))
                  == QByteArrayLiteral("REGION-0-0"),
          "★ ZQ4 解出来的内容一字不差（前缀被剥掉，落回来正是那个目录）");
    check(!QFile::exists(restoredWorld + QStringLiteral("/wtfml-backup.json")) &&
              !QFile::exists(restoreParent + QStringLiteral("/wtfml-backup.json")) &&
              !QFile::exists(restoreParent + QStringLiteral("/level.dat")),
          "★★ ZQ4 躺在 zip 根上的清单没有落进用户的世界目录，"
          "存档那堆文件也没倒在上一层（前缀剥掉之后由我们补回来）");
    check(QFile::exists(restoredWorld + QStringLiteral("/sub/assets/keep.txt")) &&
              QFile::exists(restoredWorld + QStringLiteral("/.session.lock")),
          "ZQ4 嵌套的、名字里带点的都回来了");

    // ② 还原到"已经有一份"的地方：必须**先**做安全快照，再整个挪走。
    //    往里塞一个备份里没有的文件 + 手改 level.dat —— 这两样如果没有被安全快照收走，
    //    就在"还原"这个动作里**没了**。
    writeFileAt(restoredWorld + QStringLiteral("/只在这儿有.txt"), QByteArrayLiteral("OLD-ONLY"));
    writeFileAt(restoredWorld + QStringLiteral("/level.dat"), QByteArrayLiteral("CHANGED-BY-HAND"));
    const BackupFiles::RestoreResult over = BackupFiles::restoreBackup(worldZip, restoreParent);
    check(over.ok && !over.safetyZip.isEmpty() && QFile::exists(over.safetyZip),
          "★ ZQ4 还原之前先给「现在这一份」做了一份安全快照", over.problem);
    if (!over.safetyZip.isEmpty()) {
        bool safetyOk = false;
        QString safetyProblem;
        const BackupFiles::Manifest safety =
            BackupFiles::readManifest(over.safetyZip, &safetyOk, &safetyProblem);
        check(safetyOk && safety.safety,
              "★★ ZQ4 那一份是「自动做出来的」（清单里带着 safety 这个记号，界面才认得出它）",
              safetyProblem);
        check(safety.root == QStringLiteral("基地周目") &&
                  safety.sourceInstanceId == spec.sourceInstanceId,
              "ZQ4 安全快照记的还是原来那个前缀 / 来源实例（不然恢复回来会落到别的地方）");
        check(fileAt(safety.files, QStringLiteral("只在这儿有.txt")).sha1
                  == sha1Of(QByteArrayLiteral("OLD-ONLY")),
              "★ ZQ4 安全快照里真有东西（那个「备份里没有、只在盘上」的文件也收进去了）");
        check(fileAt(safety.files, QStringLiteral("level.dat")).sha1
                  == sha1Of(QByteArrayLiteral("CHANGED-BY-HAND")),
              "★★ ZQ4 安全快照是**改之前**那一份 —— 顺序反了的话这里会是解出来的内容");
    }
    check(!QFile::exists(restoredWorld + QStringLiteral("/只在这儿有.txt")),
          "ZQ4 旧的整个挪走了（备份里没有的那个文件跟着一起走）");
    check(readAll(restoredWorld + QStringLiteral("/level.dat")) == QByteArrayLiteral("LEVELDATA"),
          "ZQ4 手改过的那一份被备份里的内容盖回去了");

    // ③ 拿别人的包来还原：**在动盘之前**就停下，一个字节都不动。
    writeFileAt(restoredWorld + QStringLiteral("/level.dat"), QByteArrayLiteral("STILL-HERE"));
    const BackupFiles::RestoreResult refused = BackupFiles::restoreBackup(foreignZip, restoreParent);
    check(!refused.ok && refused.stage == BackupFiles::RestoreResult::Stage::ReadManifest &&
              !refused.problem.isEmpty(),
          "★★ ZQ4 别人的包 → 第一步（读清单）就停下，连「第几步」都指得出来"
          "（账本上那几步靠它，不去抠中文里的关键字）",
          refused.problem);
    check(readAll(restoredWorld + QStringLiteral("/level.dat")) == QByteArrayLiteral("STILL-HERE"),
          "★★ ZQ4 拒绝的时候现在这一份**一个字节都没动**（读清单在动盘之前）");

    // ④ 解出来了但对不上账：手搓一个"清单说 A、包里是 B"的包。
    {
        const QString tamper = work + QStringLiteral("/对不上");
        const QByteArray realBytes = QByteArrayLiteral("真内容");
        writeFileAt(tamper + QStringLiteral("/云存档/level.dat"), realBytes);
        BackupFiles::Manifest lying;
        lying.kind = BackupFiles::Kind::World;
        lying.root = QStringLiteral("云存档");
        lying.label = QStringLiteral("云存档");
        lying.createdAt = at;
        BackupFiles::FileRecord rec;
        rec.path = QStringLiteral("level.dat");
        rec.size = realBytes.size();                     // 长短先对上
        rec.sha1 = sha1Of(QByteArrayLiteral("另一个内容"));  // 内容对不上
        lying.files = QList<BackupFiles::FileRecord>{rec};
        const QString lyingJson = work + QStringLiteral("/说谎的清单.json");
        writeFileAt(lyingJson, BackupFiles::manifestToJson(lying));
        const QString lyingZip = work + QStringLiteral("/对不上.zip");
        QString lyingZipError;
        check(ZipUtil::createZip(
                  lyingZip,
                  {{BackupFiles::manifestEntryName(), lyingJson},
                   {QStringLiteral("云存档/level.dat"),
                    tamper + QStringLiteral("/云存档/level.dat")}},
                  &lyingZipError),
              "ZQ4 手搓一个「清单和内容对不上」的包", lyingZipError);
        const BackupFiles::RestoreResult mismatch = BackupFiles::restoreBackup(lyingZip, work);
        check(!mismatch.ok && mismatch.stage == BackupFiles::RestoreResult::Stage::Verify &&
                  mismatch.mismatched == 1 && mismatch.checked == 1,
              "★★ ZQ4 解得开但对不上账 → 报出对不上的条数"
              "（「文件在那儿」和「文件是对的」是两件事）",
              mismatch.problem);
        check(QFile::exists(work + QStringLiteral("/云存档/level.dat")),
              "ZQ4 对不上账时解出来的那一份**留着**（用户手上有东西可救）");
    }

    // ⑤ **安全快照做不成就不许动** —— 这一整套里唯一不可接受的结果是"先把旧的删了、
    //    再回来告诉你备份没做出来"。办法：把实例快照那个备份目录的位置摆成一个**文件**，
    //    于是 mkpath 建不出来、zip 也落不了地。
    {
        const QString instanceDir = work + QStringLiteral("/我的实例");
        writeFileAt(instanceDir + QStringLiteral("/options.txt"), QByteArrayLiteral("fov:70"));
        writeFileAt(instanceDir + QStringLiteral("/assets/big.bin"), QByteArrayLiteral("60 MB 假装"));
        writeFileAt(instanceDir + QStringLiteral("/mods/某模组/data/assets/pack.png"),
                    QByteArrayLiteral("模组自己的"));
        BackupFiles::Manifest snapSpec;
        snapSpec.kind = BackupFiles::Kind::Instance;
        snapSpec.root = QStringLiteral("我的实例");
        snapSpec.label = QStringLiteral("我的实例");
        snapSpec.excluded = QStringList{QStringLiteral("assets"), QStringLiteral("libraries")};
        const QString snapZip = work + QStringLiteral("/实例快照.zip");
        const BackupFiles::WriteResult snapWrite =
            BackupFiles::writeBackup(snapSpec, instanceDir, snapZip);
        check(snapWrite.ok, "ZQ5 实例快照也打得出来", snapWrite.problem);
        check(fileAt(snapWrite.manifest.files, QStringLiteral("assets/big.bin")).path.isEmpty() &&
                  fileAt(snapWrite.manifest.files, QStringLiteral("mods/某模组/data/assets/pack.png"))
                          .path
                      == QStringLiteral("mods/某模组/data/assets/pack.png"),
              "★★ ZQ5 快照默认把能重新下回来的那两份（assets / libraries）排除掉了，"
              "但模组自己带的 assets 一个不落");

        const QString instanceBackups = BackupFiles::backupDir(BackupFiles::Kind::Instance);
        QDir().mkpath(QFileInfo(instanceBackups).absolutePath());
        writeFileAt(instanceBackups, QByteArrayLiteral("占住这个名字"));  // ← 让安全快照落不了地

        writeFileAt(instanceDir + QStringLiteral("/options.txt"), QByteArrayLiteral("fov:90"));
        const BackupFiles::RestoreResult blocked = BackupFiles::restoreBackup(snapZip, work);
        check(!blocked.ok && blocked.stage == BackupFiles::RestoreResult::Stage::SafetySnapshot &&
                  blocked.problem.contains(QStringLiteral("没有被改动")),
              "★★ ZQ5 安全快照做不出来时当场停下，并且**明确说这个目录没被动过**",
              blocked.problem);
        check(readAll(instanceDir + QStringLiteral("/options.txt")) == QByteArrayLiteral("fov:90") &&
                  QFile::exists(instanceDir + QStringLiteral("/assets/big.bin")),
              "★★ ZQ5 那一趟现在这一份**一个字节都没动**（先删后说不可接受）");

        QFile::remove(instanceBackups);
        QDir().mkpath(instanceBackups);  // 还回去，别影响后面
    }

    // ---------- ZQ6. 落点、文件名、范围那一句 ----------
    check(BackupFiles::backupRoot() == temp.path() + QStringLiteral("/cache/backups") &&
              BackupFiles::backupDir(BackupFiles::Kind::World)
                  == BackupFiles::backupRoot() + QStringLiteral("/worlds") &&
              BackupFiles::backupDir(BackupFiles::Kind::Instance)
                  == BackupFiles::backupRoot() + QStringLiteral("/instances"),
          "ZQ6 备份落在 <数据目录>/cache/backups/{worlds,instances}",
          BackupFiles::backupRoot());
    const QString oddName = BackupFiles::backupFileName(QStringLiteral("基地:周目/一"), at);
    check(oddName == QStringLiteral("基地-周目-一-2026-10-13-101530.zip"),
          "★ ZQ6 文件名里的非法字符换成 `-`，时间戳定宽（按名字排序 = 按时间排序）", oddName);
    check(BackupFiles::backupFileName(QStringLiteral("基地周目"), at, true)
              == QStringLiteral("基地周目-恢复前-2026-10-13-101530.zip"),
          "ZQ6 安全快照那一份文件名里带「恢复前」");
    check(BackupFiles::backupFileName(QStringLiteral("基地：周目"), at)
              .startsWith(BackupFiles::backupFilePrefix(QStringLiteral("基地：周目"))),
          "★★ ZQ6 前缀筛子和文件名是**同一把尺子**"
          "（不是的话用户自己的备份在列表里就看不见了）");
    check(BackupFiles::backupFileName(QStringLiteral(" . "), at)
              == QStringLiteral("backup-2026-10-13-101530.zip"),
          "ZQ6 光剩下点和空格的 label 退回 `backup`（Windows 会把结尾的点悄悄吃掉，"
          "两次备份就撞成同一个名字了）");
    check(BackupFiles::backupFilePrefix(QString(200, QLatin1Char('a'))).size() == 81,
          "ZQ6 label 太长时截到 80", QString::number(BackupFiles::backupFilePrefix(
                                            QString(200, QLatin1Char('a'))).size()));
    check(BackupFiles::scopeLine(QStringLiteral("saves/基地周目"), 6)
              == QStringLiteral("saves/基地周目（6 个文件）"),
          "ZQ6 范围那一句的唯一出处");

    // ---------- ZQ7. 还原之后的逐文件对账（verifyTree）单独钉一遍 ----------
    const QString checkDir = work + QStringLiteral("/对账");
    writeFileAt(checkDir + QStringLiteral("/a.txt"), QByteArrayLiteral("AAAA"));
    writeFileAt(checkDir + QStringLiteral("/b.txt"), QByteArrayLiteral("BBBBBB"));
    writeFileAt(checkDir + QStringLiteral("/多出来的.txt"), QByteArrayLiteral("多说一个不算错"));

    const BackupFiles::FileRecord goodA = recordOf(QStringLiteral("a.txt"), QByteArrayLiteral("AAAA"));
    const BackupFiles::FileRecord goodB =
        recordOf(QStringLiteral("b.txt"), QByteArrayLiteral("BBBBBB"));
    check(BackupFiles::verifyTree(checkDir, {goodA, goodB}) == 0,
          "ZQ7 全对上时 0 条对不上");
    check(BackupFiles::verifyTree(
              checkDir, {goodA, recordOf(QStringLiteral("没有这个.txt"), QByteArrayLiteral("x"))})
              == 1,
          "ZQ7 缺一个算一条");
    BackupFiles::FileRecord shortOne = goodA;
    shortOne.size += 1;
    check(BackupFiles::verifyTree(checkDir, {shortOne}) == 1,
          "ZQ7 长短不对就算不对（不用再算哈希）");
    BackupFiles::FileRecord sameSizeWrongBody = goodB;
    sameSizeWrongBody.sha1 = sha1Of(QByteArrayLiteral("CCCCCC"));
    check(BackupFiles::verifyTree(checkDir, {sameSizeWrongBody}) == 1,
          "★ ZQ7 长短一样但内容不一样 → 也算不对（只有哈希认得出这种）");
    BackupFiles::FileRecord noHash = goodA;
    noHash.sha1.clear();
    check(BackupFiles::verifyTree(checkDir, {noHash}) == 0,
          "ZQ7 清单里本来就没记校验值（手改过的清单）→ 查不了，不算它错");
    check(BackupFiles::verifyTree(
              checkDir, {recordOf(QStringLiteral("多出来的.txt"), QByteArrayLiteral("多说一个不算错"))})
              == 0,
          "ZQ7 备份里没有、盘上多出来的文件不算对不上（备份是「至少恢复这些」）");

    // ---------- ZQ8. 坏场景：包坏了 / 盘不够（coding plan §3.1③）----------
    //
    // 三个坏场景里，「**中断**」那一支已经在 ZQ7 钉过（长短不对 = 解到一半被打断留下的
    // 半截文件，`verifyTree` 的 size 那一支认得出），ZQ4 ④ 也钉了端到端那一趟。这里补上
    // 另外两个：① **包本身坏了**（读到一半断掉 / 根本不是包）；② **盘放不下**。
    {
        // ① 包坏了：把一份好好的包**切掉后半截**（zip 的中央目录在尾巴上，切了就读不动）。
        const QByteArray wholeZip = readAll(worldZip);
        check(!wholeZip.isEmpty(), "ZQ8 手上先得有一份好的包（ZQ3 打出来的那份）");
        const QString brokenZip = work + QStringLiteral("/截断的包.zip");
        writeFileAt(brokenZip, wholeZip.left(200));
        bool brokenOk = true;
        QString brokenProblem;
        BackupFiles::readManifest(brokenZip, &brokenOk, &brokenProblem);
        check(!brokenOk && !brokenProblem.isEmpty(),
              "★★ ZQ8 半截的包读不动，而且**说得出一句话**（不是静默回一份空清单）",
              brokenProblem);
        writeFileAt(restoredWorld + QStringLiteral("/level.dat"), QByteArrayLiteral("STILL-HERE-2"));
        const BackupFiles::RestoreResult fromBroken =
            BackupFiles::restoreBackup(brokenZip, restoreParent);
        check(!fromBroken.ok && fromBroken.stage == BackupFiles::RestoreResult::Stage::ReadManifest &&
                  readAll(restoredWorld + QStringLiteral("/level.dat"))
                      == QByteArrayLiteral("STILL-HERE-2"),
              "★★ ZQ8 拿坏包来还原：第一步就停下，现在这一份一个字节没动",
              fromBroken.problem);

        // ② 盘放不下：先钉纯函数那一条（判据的出处）。
        BackupFiles::Manifest small;
        small.kind = BackupFiles::Kind::World;
        small.root = QStringLiteral("小世界");
        small.createdAt = at;
        small.files = {recordOf(QStringLiteral("a"), QByteArrayLiteral("0123456789")),
                       recordOf(QStringLiteral("b"), QByteArrayLiteral("abcdefghij"))};
        const qint64 need = BackupFiles::restoreSpaceNeeded(small);
        check(need > 20,
              "★ ZQ8 「要多少空间」= 清单里各文件大小之和**再加一点余量**（不是刚好那 20 个字节）",
              QString::number(need));
        check(BackupFiles::hasRoomFor(need, need) && BackupFiles::hasRoomFor(need + 1, need)
                  && !BackupFiles::hasRoomFor(need - 1, need),
              "ZQ8 够 / 多一个 / 差一个：三种都判对");
        check(BackupFiles::hasRoomFor(-1, need),
              "★★ ZQ8 空闲空间**问不出来**（-1）时**不拦**"
              "（宁可走到解压那一步如实失败，也不凭一个假数字挡人）");

        // ② 端到端：手搓一个清单里写着"1 PB"的包，落到一块**空地**上。
        const QString hugeParent = work + QStringLiteral("/塞不下");
        QDir().mkpath(hugeParent);
        const QByteArray tiny = QByteArrayLiteral("小得可怜");
        const QString srcUnder = work + QStringLiteral("/源/大实例/region/r.0.0.mca");
        writeFileAt(srcUnder, tiny);
        BackupFiles::Manifest hugeManifest;
        hugeManifest.kind = BackupFiles::Kind::Instance;
        hugeManifest.root = QStringLiteral("大实例");
        hugeManifest.label = QStringLiteral("大实例");
        hugeManifest.createdAt = at;
        BackupFiles::FileRecord hugeRec = recordOf(QStringLiteral("region/r.0.0.mca"), tiny);
        hugeRec.size = 1LL << 50;  // 1 PB（清单在吹牛，反正轮不到解压那一步）
        hugeManifest.files = {hugeRec};
        const QString hugeJson = work + QStringLiteral("/大清单.json");
        writeFileAt(hugeJson, BackupFiles::manifestToJson(hugeManifest));
        const QString hugeZip = work + QStringLiteral("/塞不下.zip");
        QString hugeZipError;
        check(ZipUtil::createZip(hugeZip,
                                 {{BackupFiles::manifestEntryName(), hugeJson},
                                  {QStringLiteral("大实例/region/r.0.0.mca"), srcUnder}},
                                 &hugeZipError),
              "ZQ8 手搓一个「清单说要 1 PB」的包", hugeZipError);
        const BackupFiles::RestoreResult noRoom = BackupFiles::restoreBackup(hugeZip, hugeParent);
        check(!noRoom.ok && noRoom.stage == BackupFiles::RestoreResult::Stage::Space &&
                  noRoom.problem.contains(QStringLiteral("放不下")),
              "★★ ZQ8 空地那块盘放不下 → 在**动盘之前**就停下，而且话说得明白", noRoom.problem);
        check(!QFileInfo::exists(hugeParent + QStringLiteral("/大实例")),
              "★★ ZQ8 停下时那地上**什么都没建**"
              "（看空间这一眼排在安全快照和解压之前，盘上一个字节都没动）");

        // ③ 同一份包，落到**原地已经有一份**的地方：那一趟**不看**空间这一眼
        //    （把旧的挪走会把空间还回来，凭剩下的空间算会假报"放不下"）⇒ 得能走到解压。
        writeFileAt(hugeParent + QStringLiteral("/大实例/regions-先来的.txt"),
                    QByteArrayLiteral("OLD"));
        const BackupFiles::RestoreResult inPlace = BackupFiles::restoreBackup(hugeZip, hugeParent);
        check(inPlace.stage != BackupFiles::RestoreResult::Stage::Space,
              "★★ ZQ8 原地替换那一趟**不**因为「清单吹牛」就报空间不足"
              "（旧那份挪走会把空间还回来，那一趟交给解压/对账如实报）",
              inPlace.problem);
    }

    AppPaths::setMinecraftDir(originalDir);
}

// ---------------------------------------------------------------------------
// ZR. 「上一次启动」那本账（coding plan §5.1）
//
// §5.1 那张卡（主页左栏「上次游玩」）分三处验：
//   ① **这一节**：账本自己 —— 格式怎么写怎么读、时间怎么说成人话、目标没了怎么降级、
//      上限怎么截。全是纯函数（时间那一列的"现在"是参数，不问时钟），所以连界面都不用起；
//   ② **接线**（记在哪一刻、退出怎么改写、卡片上写出什么）在 mw_check 的 T36；
//   ③ **那张卡长什么样**在 ui_check 的 U31。
//
// ★ 这一节里最要紧的两条，都不是"能不能跑"，而是**这句规矩有没有被写歪**：
//   · 「上一次」以成功创建游戏进程为准 ⇒ `latestPlayable()` 跳过"没起来"那一档；
//   · 「昨天」按**日期**算，不按差了多少秒（23:59 → 次日 00:01 只差两分钟，可那是昨天）。
// ---------------------------------------------------------------------------
static void runLaunchHistoryTests() {
    section("ZR. 「上一次启动」那本账：格式 / 时间怎么说 / 目标没了怎么降级（§5.1）");

    const QString originalDir = AppPaths::minecraftDir();
    QTemporaryDir temp;
    check(temp.isValid(), "ZR0 临时数据根目录建出来了");
    if (!temp.isValid()) {
        return;
    }
    AppPaths::setMinecraftDir(temp.path());
    const QString work = temp.path() + QStringLiteral("/work");

    const QDateTime now = QDateTime::fromString(QStringLiteral("2026-10-13T22:14:00"), Qt::ISODate);
    const auto makeRecord = [](const QString &instanceId, const QDateTime &at) {
        LaunchHistory::Record record;
        record.instanceId = instanceId;
        record.instanceName = QStringLiteral("我的整合-") + instanceId;
        record.accountKey = QStringLiteral("账号-") + instanceId;
        record.startedAt = at;
        return record;
    };
    const auto firstOf = [](const QList<LaunchHistory::Record> &list) {
        return list.isEmpty() ? LaunchHistory::Record() : list.first();
    };

    // ---------- ZR1. 这本账落在哪儿、留几条 ----------
    check(LaunchHistory::historyPath() == temp.path() + QStringLiteral("/wtfml.history"),
          "★★ ZR1 账本跟着**当前游戏文件夹**走（`<当前游戏文件夹>/wtfml.history`）—— 这张卡说的是"
          "「这个文件夹里的哪一份实例上次玩过」，换了文件夹就该看见另一本账",
          LaunchHistory::historyPath());
    check(LaunchHistory::historyLimit() == 20, "ZR1 二十条封顶（§5.1 第一版点名的那个数）",
          QString::number(LaunchHistory::historyLimit()));

    // ---------- ZR2. 枚举 ⇄ 落盘用的那几个词（写和读走的是同一张表）----------
    bool keysRoundTrip = true;
    for (LaunchHistory::Result result :
         {LaunchHistory::Result::Running, LaunchHistory::Result::NormalExit,
          LaunchHistory::Result::Crash, LaunchHistory::Result::StartFailed}) {
        keysRoundTrip = keysRoundTrip
                        && LaunchHistory::resultFromKey(LaunchHistory::resultKey(result)) == result;
    }
    for (LaunchHistory::Target target : {LaunchHistory::Target::None, LaunchHistory::Target::World,
                                         LaunchHistory::Target::Server}) {
        keysRoundTrip = keysRoundTrip
                        && LaunchHistory::targetFromKey(LaunchHistory::targetKey(target)) == target;
    }
    check(keysRoundTrip, "★ ZR2 四个结局 + 三种目标：枚举 → 词 → 枚举，一格不差");
    check(LaunchHistory::resultFromKey(QStringLiteral("以后加的档")) == LaunchHistory::Result::Running
              && LaunchHistory::targetFromKey(QStringLiteral("以后加的档"))
                     == LaunchHistory::Target::None,
          "★ ZR2 认不出来的词落到**什么都没断言**的那一档（单条记录认不出来，不该让整本账作废）");

    // ---------- ZR3. 一条记录写下去读回来，逐格一样 ----------
    LaunchHistory::Record full = makeRecord(QStringLiteral("1.20.1-forge"), now);
    full.target = LaunchHistory::Target::Server;
    full.targetId = QStringLiteral("play.example.com:25565");
    full.targetDisplayName = QStringLiteral("朋友的服");
    full.durationSeconds = 4320;
    full.result = LaunchHistory::Result::Crash;

    bool ok = false;
    const QList<LaunchHistory::Record> back =
        LaunchHistory::fromJson(LaunchHistory::toJson({full}), &ok);
    const LaunchHistory::Record read = firstOf(back);
    check(ok && back.size() == 1, "ZR3 一条记录写下去读回来还是那一条",
          QString::number(back.size()));
    check(read.instanceId == full.instanceId && read.instanceName == full.instanceName
              && read.accountKey == full.accountKey && read.target == full.target
              && read.targetId == full.targetId && read.targetDisplayName == full.targetDisplayName
              && read.startedAt.toMSecsSinceEpoch() == full.startedAt.toMSecsSinceEpoch()
              && read.durationSeconds == full.durationSeconds && read.result == full.result,
          "★★ ZR3 逐格往返：哪一份 / 当时叫什么 / 谁玩的 / 进的是哪儿 / 什么时候 / 多久 / 最后怎么了");

    LaunchHistory::Record plain = makeRecord(QStringLiteral("1.21-vanilla"), now);
    // 这一档是"身份没记下来"（`accountKey` 空）—— 空着的三格**一个都不该写下去**。
    plain.accountKey.clear();
    const QJsonObject plainRoot =
        QJsonDocument::fromJson(LaunchHistory::toJson({plain})).object();
    check(plainRoot.value(QStringLiteral("format")).toString()
              == QStringLiteral("wtfml-launch-history/1"),
          "ZR3 顶上那个格式标记（认不出来就整份不认）");
    const QJsonObject plainRow = plainRoot.value(QStringLiteral("records")).toArray().at(0).toObject();
    check(!plainRow.contains(QStringLiteral("account"))
              && !plainRow.contains(QStringLiteral("targetId"))
              && !plainRow.contains(QStringLiteral("targetName")),
          "ZR3 空着的字段**根本不写下去**（不是写一个空串 —— 写空串读的人会以为那是个开关）");
    check(plainRow.contains(QStringLiteral("durationSeconds"))
              && plainRow.value(QStringLiteral("durationSeconds")).toDouble() == -1.0,
          "★ ZR3 durationSeconds **总是**写（-1 = 这一条还没结束）：「字段不在」和「写了 -1」"
          "少一层歧义，读的人一眼看得出哪一条还在跑");

    // 认不出的格式 → 整份不认（别的启动器写的、以后我们自己改了格式的旧文件，都只能被挡住）。
    QByteArray forged = LaunchHistory::toJson({plain});
    forged.replace(QByteArrayLiteral("wtfml-launch-history/1"), QByteArrayLiteral("别人的/9"));
    bool forgedOk = true;
    check(!(LaunchHistory::fromJson(forged, &forgedOk).size() > 0) && !forgedOk,
          "★★ ZR3 格式标记对不上就整份不认（不半信半疑地读成一堆空记录）");
    bool junkOk = true;
    check(LaunchHistory::fromJson(QByteArrayLiteral("这不是 json"), &junkOk).isEmpty() && !junkOk,
          "ZR3 整个文件不是 JSON ⇒ 空账 + ok=false");

    // 单条坏掉（没有实例 id / 时间认不出来）**只丢它自己**。
    const QByteArray mixed = QByteArrayLiteral(
        "{\"format\":\"wtfml-launch-history/1\",\"records\":["
        "{\"instanceId\":\"\",\"startedAt\":\"2026-10-13T10:00:00\"},"
        "{\"instanceId\":\"没有时间的那一条\",\"startedAt\":\"不是时间\"},"
        "{\"instanceId\":\"留下的那一条\",\"startedAt\":\"2026-10-13T10:00:00\"}]}");
    bool mixedOk = false;
    const QList<LaunchHistory::Record> kept = LaunchHistory::fromJson(mixed, &mixedOk);
    check(mixedOk && kept.size() == 1
              && kept.first().instanceId == QStringLiteral("留下的那一条"),
          "★★ ZR3 坏掉的那一条当它不在，别的照读（整本账不该被一条坏记录连坐）",
          QString::number(kept.size()));

    // ---------- ZR4. 盘上那一趟 + 二十条封顶 ----------
    const QString path = LaunchHistory::historyPath();
    check(LaunchHistory::load(path).isEmpty(),
          "ZR4 文件不在 = **空账**（一次都没启动过的新用户就是这样，不是错误）");
    check(LaunchHistory::save(path, {full, plain}), "ZR4 写盘成功");
    check(QFileInfo::exists(path), "★ ZR4 盘上真多了那一份");
    const QList<LaunchHistory::Record> fromDisk = LaunchHistory::load(path);
    check(fromDisk.size() == 2 && fromDisk.first().instanceId == full.instanceId
              && fromDisk.last().instanceId == plain.instanceId,
          "★ ZR4 读回来还是那两条、顺序也还是那个顺序");

    writeFileAt(path, QByteArrayLiteral("这不是 json"));
    check(LaunchHistory::load(path).isEmpty(),
          "★★ ZR4 文件被写坏了 ⇒ 空账（既不崩，也不半信半疑地留下半份）");

    writeFileAt(work + QStringLiteral("/挡住"), QByteArrayLiteral("x"));
    check(!LaunchHistory::save(work + QStringLiteral("/挡住/底下.json"), {plain}),
          "★ ZR4 目录建不出来时 save() 回 false（调用方不许静默吞掉）");

    QList<LaunchHistory::Record> many;
    for (int i = 0; i < 25; ++i) {
        many.append(makeRecord(QStringLiteral("老的那一份%1").arg(i), now.addSecs(-1000 - i)));
    }
    const LaunchHistory::Record fresh = makeRecord(QStringLiteral("刚玩的"), now);
    const QList<LaunchHistory::Record> capped = LaunchHistory::prepend(many, fresh);
    check(capped.size() == LaunchHistory::historyLimit(),
          "★★ ZR4 二十条封顶（超出来的那几条被丢掉的是**最老的**）",
          QString::number(capped.size()));
    check(capped.first().instanceId == QStringLiteral("刚玩的"),
          "ZR4 新的一条排在最前面");
    check(capped.last().instanceId == QStringLiteral("老的那一份18"),
          "★ ZR4 截掉的是**尾巴**上最老的几条，不是把新来的挤掉",
          capped.last().instanceId);
    check(LaunchHistory::prepend({}, fresh).size() == 1, "ZR4 空账上加一条就是一条");

    // ---------- ZR5. 「上一次」那一条是哪一条 ----------
    // 顺序故意乱的：账上那个列表按**写入顺序**排，而"最新"要按**时间**认。
    QList<LaunchHistory::Record> shuffled;
    shuffled.append(makeRecord(QStringLiteral("更晚的那一趟"), now.addSecs(-60)));
    shuffled.append(makeRecord(QStringLiteral("更早的那一趟"), now.addSecs(-86400)));
    check(LaunchHistory::latestPlayable(shuffled).instanceId == QStringLiteral("更晚的那一趟"),
          "★ ZR5 「最新」按**时间**认，不按它在账上的位置");

    QList<LaunchHistory::Record> withFailed;
    LaunchHistory::Record failed = makeRecord(QStringLiteral("没起来的那一份"), now);
    failed.result = LaunchHistory::Result::StartFailed;
    withFailed.append(failed);  // 时间上最新，可它压根没玩成
    withFailed.append(makeRecord(QStringLiteral("真玩过的那一份"), now.addSecs(-3600)));
    check(LaunchHistory::latestPlayable(withFailed).instanceId == QStringLiteral("真玩过的那一份"),
          "★★ ZR5 「上次没起来」那一趟**不当作**「上次游玩」（拿它当上次玩了什么是撒谎）");
    check(!LaunchHistory::latestPlayable({failed}).isValid(),
          "★ ZR5 全是「没起来」的那些 ⇒ 算没有（卡片收起来）");
    check(!LaunchHistory::latestPlayable({}).isValid(), "ZR5 空账 ⇒ 没有");

    LaunchHistory::Record running = makeRecord(QStringLiteral("正开着的那一份"), now);
    running.result = LaunchHistory::Result::Running;
    check(LaunchHistory::latestPlayable({running}).instanceId
              == QStringLiteral("正开着的那一份"),
          "★ ZR5 还在跑的那一条**算数**（游戏这会儿正开着，卡片更该显示它）");

    LaunchHistory::Record noTime;
    noTime.instanceId = QStringLiteral("没有时间的那一条");
    check(!LaunchHistory::latestPlayable({noTime}).isValid(),
          "ZR5 连时间都没有的记录不算数（卡片上那两样都得有）");

    // ---------- ZR6. 「昨天 22:14」怎么说 ----------
    const QDateTime clockNow =
        QDateTime::fromString(QStringLiteral("2026-10-13T23:00:00"), Qt::ISODate);
    check(LaunchHistory::whenText(QDateTime::fromString(QStringLiteral("2026-10-13T22:14:00"),
                                                       Qt::ISODate),
                                  clockNow) == QStringLiteral("22:14"),
          "ZR6 今天只写时刻");
    check(LaunchHistory::whenText(QDateTime::fromString(QStringLiteral("2026-10-12T23:59:00"),
                                                       Qt::ISODate),
                                  QDateTime::fromString(QStringLiteral("2026-10-13T00:01:00"),
                                                        Qt::ISODate))
              == QStringLiteral("昨天 23:59"),
          "★★ ZR6 **按日期比**，不按差了多久 —— 23:59 到次日 00:01 只差两分钟，可那是"
          "「昨天」；卡片上要的正是「哪一天」");
    check(LaunchHistory::whenText(QDateTime::fromString(QStringLiteral("2026-10-11T09:05:00"),
                                                       Qt::ISODate),
                                  clockNow) == QStringLiteral("前天 09:05"),
          "ZR6 前天");
    check(LaunchHistory::whenText(QDateTime::fromString(QStringLiteral("2026-10-05T09:05:00"),
                                                       Qt::ISODate),
                                  clockNow) == QStringLiteral("2026-10-05 09:05"),
          "ZR6 再早就把日子写全（「昨天/前天」之外不给模糊话）");
    check(LaunchHistory::whenText(QDateTime::fromString(QStringLiteral("2026-12-31T09:05:00"),
                                                       Qt::ISODate),
                                  clockNow) == QStringLiteral("2026-12-31 09:05"),
          "ZR6 将来的时间照写（钟被往回拨过 / 文件被人动过时，写真的比编一句「刚刚」强）");
    check(LaunchHistory::whenText(QDateTime(), clockNow).isEmpty()
              && LaunchHistory::whenText(QDateTime::fromString(QStringLiteral("2026-10-13T22:14:00"),
                                                               Qt::ISODate),
                                         QDateTime())
                     .isEmpty(),
          "ZR6 时间无效 ⇒ 空串（**不编**）");

    // ---------- ZR7. 卡片上那两行字 ----------
    LaunchHistory::Record world = makeRecord(QStringLiteral("world"), now);
    world.target = LaunchHistory::Target::World;
    world.targetId = QStringLiteral("基地周目");
    world.targetDisplayName = QStringLiteral("基地周目");
    check(LaunchHistory::targetLine(world) == QStringLiteral("单人世界：基地周目"),
          "ZR7 存档那一行");
    LaunchHistory::Record worldNoName = world;
    worldNoName.targetDisplayName.clear();
    check(LaunchHistory::targetLine(worldNoName) == QStringLiteral("单人世界：基地周目"),
          "ZR7 名字没记下来时退回目标 id（不写一个空的「单人世界：」）");

    LaunchHistory::Record server = makeRecord(QStringLiteral("server"), now);
    server.target = LaunchHistory::Target::Server;
    server.targetId = QStringLiteral("play.example.com:25565");
    server.targetDisplayName = QStringLiteral("朋友的服");
    check(LaunchHistory::targetLine(server) == QStringLiteral("服务器：朋友的服"),
          "ZR7 服务器那一行写的是**名字**（地址在记录里，不在这一行）");
    check(LaunchHistory::targetLine(plain).isEmpty(),
          "★★ ZR7 普通启动那一趟这一行是**空的** —— 不写「主菜单」三个字（那是句废话，"
          "少一行才叫「没什么可说的」）");

    LaunchHistory::Record note = plain;
    note.result = LaunchHistory::Result::Crash;
    check(LaunchHistory::resultNote(note) == QStringLiteral("（上次是异常退出）"),
          "ZR7 崩过就明说");
    note.result = LaunchHistory::Result::Running;
    check(LaunchHistory::resultNote(note) == QStringLiteral("（还在玩）"),
          "★ ZR7 还在跑也明说（卡片上那颗按钮点下去会提醒「已经有一份在跑」）");
    note.result = LaunchHistory::Result::StartFailed;
    check(LaunchHistory::resultNote(note) == QStringLiteral("（上次没起来）"),
          "ZR7 没起来那一档也有话说");
    note.result = LaunchHistory::Result::NormalExit;
    check(LaunchHistory::resultNote(note).isEmpty(),
          "ZR7 正常退出**不占一行**（绝大多数时候都正常，写出来只是噪音）");

    check(LaunchHistory::durationText(-1).isEmpty(), "ZR7 还没算出来 ⇒ 空串");
    check(LaunchHistory::durationText(0) == QStringLiteral("玩了不到 1 分钟")
              && LaunchHistory::durationText(59) == QStringLiteral("玩了不到 1 分钟"),
          "ZR7 不到一分钟那一档（「玩了」两个字和量词一起挪，不许拼出「玩了 不到 1 分钟」）");
    check(LaunchHistory::durationText(60) == QStringLiteral("玩了 1 分钟")
              && LaunchHistory::durationText(3599) == QStringLiteral("玩了 59 分钟"),
          "ZR7 分钟那一档");
    check(LaunchHistory::durationText(3600) == QStringLiteral("玩了 1 小时")
              && LaunchHistory::durationText(4320) == QStringLiteral("玩了 1 小时 12 分")
              && LaunchHistory::durationText(7200) == QStringLiteral("玩了 2 小时"),
          "ZR7 小时那一档（整点不写「0 分」）");

    AppPaths::setMinecraftDir(originalDir);
}

// ---------------------------------------------------------------------------
// ZS. 实例页的搜索与筛选：判据层（coding plan §7.2）
//
// §7.2 原话：「搜索实例名、版本号、加载器；筛选原版/模组实例、可更新、最近运行；搜索不
// 改变分组归属；清空搜索恢复原展开状态」。四句里只有**前两句**是这一节的事（纯判据：
// 一条实例算不算匹配）；后两句说的是"重灌树时别动别的状态"，那是接线，在 mw_check 的 T37。
//
// ★ 这一节最要紧的不是"能不能筛出来"，而是**会不会筛错**：
//   · 空搜索词 + 四颗都不勾 ⇒ 一条都不许滤掉（`isActive()` 为假是那条路的唯一判据）；
//   · 一个空串混进可比对的串里 ⇒ `contains("")` 恒真 ⇒ 搜什么都搜得到（最难发现的一种坏）；
//   · 词与词是**与**、词与串是**或**（用户打两个词是"都要有"，不是"任一"）。
// ---------------------------------------------------------------------------
static void runInstanceFilterTests() {
    section("ZS. 实例页的搜索与筛选：搜哪些串 / 四档筛子怎么算（§7.2）");

    // 造一条长得像真机上那些的实例：目录名把加载器版本揉进去了，显示名另有一套开关。
    const auto makeParts = [](const QString &id, const QString &custom, const QString &real,
                              const QString &loader, const QString &loaderVersion) {
        VersionDisplayParts parts;
        parts.id = id;
        parts.customName = custom;
        parts.realVersion = real;
        parts.loaderName = loader;
        parts.loaderVersion = loaderVersion;
        return parts;
    };
    const VersionNameOptions options;  // 出厂：自定义名 + 实际版本 + 加载器名

    // ---------- ZS1. 参与搜索的串 ----------
    const VersionDisplayParts pack = makeParts(QStringLiteral("我的整合包-1.18.2-Forge_40.3.12"),
                                               QStringLiteral("我的整合包"),
                                               QStringLiteral("1.18.2"), QStringLiteral("Forge"),
                                               QStringLiteral("40.3.12"));
    const QStringList texts = InstanceFilter::textsFor(pack, options);
    check(texts.contains(QStringLiteral("我的整合包-1.18.2-Forge")),
          "ZS1 显示名（按开关拼出来的那一串）在里头 —— 用户是照着屏幕上那一行打的",
          texts.join(QStringLiteral(" | ")));
    check(texts.contains(QStringLiteral("我的整合包-1.18.2-Forge_40.3.12")),
          "ZS1 目录名也在（加载器版本号只在它这儿是齐的）");
    check(texts.contains(QStringLiteral("1.18.2")) && texts.contains(QStringLiteral("Forge")),
          "ZS1 实际版本与加载器名各自单独可搜（§7.2 点名的那三样）");
    {
        // 把"自定义名 / 实际版本"两个开关关掉：显示名里就只剩加载器了，而那两个串
        // **照样得能搜到** —— 它们是这个实例的名字和版本，只是**这一版显示名里没写**。
        VersionNameOptions off = options;
        off.showCustomName = false;
        off.showRealVersion = false;
        const QStringList still = InstanceFilter::textsFor(pack, off);
        check(still.contains(QStringLiteral("我的整合包")) && still.contains(QStringLiteral("1.18.2")),
              "ZS1 开关关掉的那两段照样在可比对的串里（显示名里没有 ≠ 搜不到）",
              still.join(QStringLiteral(" | ")));
    }
    {
        // 空字段不许混进去：一个空串会让**任何**关键词都命中（`contains("")` 恒真）。
        const VersionDisplayParts bare = makeParts(QStringLiteral("原版ATT2地图（无模组）"),
                                                   QString(), QString(), QString(), QString());
        const QStringList bareTexts = InstanceFilter::textsFor(bare, options);
        check(!bareTexts.contains(QString()) && bareTexts.size() == 2,
              "ZS1 空字段一个都不放进去（空串会让「搜什么都搜得到」）",
              QStringLiteral("%1 个串：%2").arg(bareTexts.size()).arg(bareTexts.join('/')));
        InstanceFilter::Facts facts;
        facts.texts = bareTexts;
        InstanceFilter::Query query;
        query.text = QStringLiteral("绝对搜不到的一串字");
        check(!InstanceFilter::matches(query, facts), "ZS1 前提成立：这一串确实搜不到");
    }

    // ---------- ZS2. 分词 ----------
    check(InstanceFilter::searchTokens(QStringLiteral("  整合包   forge  ")).size() == 2,
          "ZS2 前后空白折掉、中间连着几个空格算一个",
          InstanceFilter::searchTokens(QStringLiteral("  整合包   forge  ")).join(QStringLiteral(",")));
    check(InstanceFilter::searchTokens(QStringLiteral("\t1.18.2\nforge")).size() == 2,
          "ZS2 制表符和换行也当分隔（从别处粘一串过来的样子）");
    check(InstanceFilter::searchTokens(QString()).isEmpty()
              && InstanceFilter::searchTokens(QStringLiteral("   ")).isEmpty(),
          "ZS2 空串 / 全是空白 ⇒ 空表（待会儿一条都不拦）");

    // ---------- ZS3. 匹配：词与词是与、词与串是或 ----------
    InstanceFilter::Facts packFacts;
    packFacts.texts = texts;
    packFacts.hasLoader = true;
    packFacts.updatable = true;
    const auto hit = [&packFacts](const QString &text) {
        InstanceFilter::Query query;
        query.text = text;
        return InstanceFilter::matches(query, packFacts);
    };
    check(hit(QStringLiteral("整合包")) && hit(QStringLiteral("FORGE")) && hit(QStringLiteral("1.18")),
          "ZS3 命中子串就算（大小写不敏感 —— 用户不会照着大小写打）");
    check(hit(QStringLiteral("整合包 forge")) && hit(QStringLiteral("forge 整合包")),
          "ZS3 两个词都要命中，顺序随便（用户手里那两句常常不在同一段里）");
    check(!hit(QStringLiteral("整合包 fabric")),
          "ZS3 有一个词一个地方都命不中 ⇒ 整条不算（词与词是「与」）");
    check(!hit(QStringLiteral("fabric")), "ZS3 压根没有那一串 ⇒ 不算");

    // ---------- ZS4. 四档筛子 ----------
    {
        InstanceFilter::Facts plain;  // 没加载器、没更新、没记录
        plain.texts = QStringList{QStringLiteral("原版 1.20.1")};
        InstanceFilter::Facts modded = packFacts;  // 有加载器

        InstanceFilter::Query vanilla;
        vanilla.kind = InstanceFilter::Kind::Vanilla;
        check(InstanceFilter::matches(vanilla, plain) && !InstanceFilter::matches(vanilla, modded),
              "ZS4 「原版」= 没检测到模组加载器（判据是 loaderName，不是「装没装 mods」）");

        InstanceFilter::Query moddedQuery;
        moddedQuery.kind = InstanceFilter::Kind::Modded;
        check(InstanceFilter::matches(moddedQuery, modded)
                  && !InstanceFilter::matches(moddedQuery, plain),
              "ZS4 「模组」= 检测到了模组加载器（两档互斥，同一个实例不会被两边都算上）");

        InstanceFilter::Query updatable;
        updatable.updatableOnly = true;
        check(InstanceFilter::matches(updatable, modded) && !InstanceFilter::matches(updatable, plain),
              "ZS4 「可更新」只认查过更新、且真有几条的那一份");

        InstanceFilter::Query recent;
        recent.recentOnly = true;
        InstanceFilter::Facts played = plain;
        played.recent = true;
        check(InstanceFilter::matches(recent, played) && !InstanceFilter::matches(recent, plain),
              "ZS4 「最近运行」只认账本上还留着记录的");

        // 四档叠着用是**与**：筛子过不了的时候，搜索词再准也没用。
        InstanceFilter::Query combined = vanilla;
        combined.updatableOnly = true;
        check(!InstanceFilter::matches(combined, plain),
              "ZS4 两档叠着是「与」（原版 + 可更新：一条「原版、没查过更新」的实例过不了）");
        combined.text = QStringLiteral("原版");
        check(!InstanceFilter::matches(combined, plain), "ZS4 搜索词命中也不算数（叠着的两档没过）");
    }

    // ---------- ZS5. 「在不在筛」这一个判据 ----------
    {
        const InstanceFilter::Query empty;
        check(!empty.isActive(),
              "★ ZS5 一个字都没填、四颗都没勾 ⇒ **不在筛**（这条路上一条都不许滤掉）");
        InstanceFilter::Query typed;
        typed.text = QStringLiteral("   ");
        check(!typed.isActive(), "ZS5 只打了几个空格一样是「没在筛」（按去掉空白之后算）");
        typed.text = QStringLiteral("a");
        check(typed.isActive(), "ZS5 有一个字就算在筛");
        InstanceFilter::Query chip;
        chip.recentOnly = true;
        check(chip.isActive(), "ZS5 只勾了一颗筛选 chip 也算在筛");
        // ★ 「不在筛」的那一条路必须**原样放行**：`matches()` 对着空条件也得回真。
        InstanceFilter::Facts anything;
        anything.texts = QStringList{QStringLiteral("随便什么")};
        check(InstanceFilter::matches(empty, anything),
              "★★ ZS5 空条件对任何一条都回真（`isActive()` 为假时调用方照样只走 matches()）");
    }
}

// ---------------------------------------------------------------------------
// ZT. 更新中心的「忽略这一版 / 固定这一版」：一本账 + 两条判据（coding plan §7.1）
//
// 这一节盯的是"**什么时候它自己就回来了**"这件事 —— 那两档"别再提示我"最怕的不是记不住，
// 是**记死了**（用户按一下就把这个资源永远钉在原地，作者再发新版本也不提示了）：
//   · 忽略记的是**要换上的那一版的 id** ⇒ 下一趟要换的是另一版时，它自己回来；
//   · 固定记的是**盘上那一份的 sha1** ⇒ 文件被换过（手动 / 又更新了一次）就自动失效；
//   · 两个"不知道"（拿不到当前 sha1 / 拼不出目标版本）**一律按"没记过"算** —— 不知道的
//     事不能当成知道（不知道当成知道，症状是"更新不提示了，而且用户不知道为什么"）。
//
// ★ 整节纯函数 + 一个 QTemporaryDir 里的真存真读：不联网、不碰共享沙箱、不碰 ui/。
// ---------------------------------------------------------------------------
static void runUpdatePolicyTests() {
    section("ZT. 更新中心：忽略 / 固定那一本账（§7.1）");

    const QString originalDir = AppPaths::minecraftDir();
    QTemporaryDir temp;
    check(temp.isValid(), "ZT0 临时数据根目录建出来了");
    if (!temp.isValid()) {
        return;
    }
    AppPaths::setMinecraftDir(temp.path());

    const QString instanceDir = temp.path() + QStringLiteral("/versions/1.20.1-forge-47.2.0");
    const QString instanceId = QStringLiteral("1.20.1-forge-47.2.0");
    const QString otherId = QStringLiteral("1.19.2-fabric-0.15.11");
    QDir().mkpath(instanceDir + QStringLiteral("/mods"));

    // ---------- ZT1. 那把钥匙：相对实例目录、`/` 分隔 ----------
    //
    // 绝对路径一搬走（改数据目录 / 复制实例）就全废 —— 这一条是那本账能在盘上待住的根。
    check(UpdatePolicy::storeKey(instanceDir, instanceDir + QStringLiteral("/mods/jei.jar")) ==
              QStringLiteral("mods/jei.jar"),
          "★ ZT1 键是**实例内相对路径**（绝对路径搬一次家就全废）",
          UpdatePolicy::storeKey(instanceDir, instanceDir + QStringLiteral("/mods/jei.jar")));
    // ★ 大小写 / 反斜杠：产品给的路径是 QFileInfo 出来的（在 Windows 上就是 `/`），但别的
    //   调用点万一塞了个反斜杠进来，键不能变成两个。
    check(UpdatePolicy::storeKey(instanceDir, instanceDir + QStringLiteral("/mods/jei.jar")) ==
              UpdatePolicy::storeKey(instanceDir, instanceDir + QStringLiteral("\\mods\\jei.jar")),
          "ZT1 反斜杠进来的那一条拼出**同一把**钥匙（不许一个文件记成两条）");
    // 不在这个实例底下的路径：回空串、调用方必须跳过（空键会把不相干的记录混成一条）。
    check(UpdatePolicy::storeKey(instanceDir, temp.path() + QStringLiteral("/other/mod.jar"))
              .isEmpty(),
          "★★ ZT1 不在这个实例底下的路径回**空键**（空键会把好几条混成一条、而且删不掉）");

    // ---------- ZT2. 两档的判据 ----------
    const QString shaNew = QStringLiteral("1111111111111111111111111111111111111111");
    const QString shaOld = QStringLiteral("2222222222222222222222222222222222222222");
    {
        UpdatePolicy::Entry ignored;
        ignored.ignoreVersionId = QStringLiteral("ver-2.0");
        check(UpdatePolicy::suppressed(ignored, shaNew, QStringLiteral("ver-2.0")) ==
                  UpdatePolicy::Suppress::Ignored,
              "ZT2 记着的那一版就是要换上的那一版 ⇒ 忽略生效");
        // ★★ 这一条是这一档存在的理由：作者发了更新的一版，它自己回来。
        check(UpdatePolicy::suppressed(ignored, shaNew, QStringLiteral("ver-3.0")) ==
                  UpdatePolicy::Suppress::None,
              "★★ ZT2 要换上的换成了**另一版** ⇒ 忽略**自己失效**（用户讨厌的是那一版，"
              "不是「别看更新」）");
        // 拼不出目标版本（空）：判不了 ⇒ 按"没记过"算，提示照出。
        check(UpdatePolicy::suppressed(ignored, shaNew, QString()) == UpdatePolicy::Suppress::None,
              "★★ ZT2 拼不出要换上的那一版 ⇒ **不拦**（判不了的事不许当成「忽略了」）");

        UpdatePolicy::Entry pinned;
        pinned.pinnedSha1 = shaOld;
        check(UpdatePolicy::suppressed(pinned, shaOld, QStringLiteral("ver-3.0")) ==
                  UpdatePolicy::Suppress::Pinned,
              "ZT2 盘上还是固定那一刻那一份 ⇒ 固定生效（后面有新版本也不提示）");
        check(UpdatePolicy::suppressed(pinned, shaNew, QStringLiteral("ver-3.0")) ==
                  UpdatePolicy::Suppress::None,
              "★★ ZT2 盘上那一份**被换过了** ⇒ 固定自动失效（「停在那一份上」不是「别看更新」）");
        check(UpdatePolicy::suppressed(pinned, QString(), QStringLiteral("ver-3.0")) ==
                  UpdatePolicy::Suppress::None,
              "★★ ZT2 拿不到盘上那一份的 sha1 ⇒ 固定那一档判不了 ⇒ **不拦**");
        // 两档同时记着（先忽略、后来固定）：固定那一档先说话（它是更"死"的那一条）。
        UpdatePolicy::Entry both;
        both.ignoreVersionId = QStringLiteral("ver-2.0");
        both.pinnedSha1 = shaOld;
        check(UpdatePolicy::suppressed(both, shaOld, QStringLiteral("ver-2.0")) ==
                  UpdatePolicy::Suppress::Pinned,
              "ZT2 两档都记着 ⇒ 报「已固定」（用户两个都按过，他最后按的那个意思更具体）");

        // 空记录 = 没记过。
        check(UpdatePolicy::suppressed(UpdatePolicy::Entry(), shaNew, QStringLiteral("ver-2.0")) ==
                  UpdatePolicy::Suppress::None,
              "ZT2 一条记录都没有 ⇒ 照常提示");
    }

    // ---------- ZT3. 过期固定的清理 ----------
    //
    // 「固定」过期了要**清掉**，不能留着：留着的话界面上一直写着"已固定"，而它其实早就
    // 什么都不管了（用户会以为"我固定住了"，实际每趟都在提示）。
    {
        UpdatePolicy::Store store;
        UpdatePolicy::setPinned(store, instanceId, QStringLiteral("mods/jei.jar"), shaOld);
        UpdatePolicy::setPinned(store, instanceId, QStringLiteral("mods/other.jar"), shaNew);
        UpdatePolicy::setIgnored(store, instanceId, QStringLiteral("mods/ignored.jar"),
                                 QStringLiteral("ver-2.0"));
        check(store.countFor(instanceId) == 3, "ZT3 三笔账记进去了",
              QString::number(store.countFor(instanceId)));

        QHash<QString, QString> now;
        now.insert(QStringLiteral("mods/jei.jar"), shaNew);      // 被换过了 ⇒ 这条固定过期
        now.insert(QStringLiteral("mods/other.jar"), shaNew);    // 还是那一份 ⇒ 留着
        now.insert(QStringLiteral("mods/ignored.jar"), shaNew);
        const int dropped = UpdatePolicy::dropStalePins(store, instanceId, now);
        check(dropped == 1, "★★ ZT3 只清掉过期的那一条固定", QString::number(dropped));
        check(UpdatePolicy::entryOf(store, instanceId, QStringLiteral("mods/jei.jar")).isEmpty(),
              "ZT3 过期的那条**整条没了**（不是留一个空壳）");
        check(!UpdatePolicy::entryOf(store, instanceId, QStringLiteral("mods/other.jar")).isEmpty(),
              "ZT3 没过期的那条还在");
        // ★ 忽略那一档**不清**：它记的是"那一版"，只要那一版还在，用户的意思就还成立。
        check(UpdatePolicy::entryOf(store, instanceId, QStringLiteral("mods/ignored.jar"))
                  .ignoreVersionId == QStringLiteral("ver-2.0"),
              "★★ ZT3 忽略那一档**不清**（它记的是「那一版」，和盘上现在是什么内容无关）");
        // 盘上已经**没有**这个文件了（这一趟的清单里根本没有这个键）⇒ 那条记录指不到任何
        // 东西了，清掉。
        QHash<QString, QString> emptyMap;
        check(UpdatePolicy::dropStalePins(store, instanceId, emptyMap) == 1,
              "★ ZT3 盘上见不到这个文件（清单里连这个键都没有）⇒ 那条固定也清掉");
        // ★★ 而"键在、sha1 空"是**另一回事**：那是"读不动 / 没算出来"，**不许**当成"换了"
        //    —— 清一条记录是不可逆的，用户会发现固定自己没了、而且不知道为什么。
        UpdatePolicy::Store keep;
        UpdatePolicy::setPinned(keep, instanceId, QStringLiteral("mods/jei.jar"), shaOld);
        QHash<QString, QString> unknown;
        unknown.insert(QStringLiteral("mods/jei.jar"), QString());
        check(UpdatePolicy::dropStalePins(keep, instanceId, unknown) == 0 &&
                  UpdatePolicy::entryOf(keep, instanceId, QStringLiteral("mods/jei.jar"))
                          .pinnedSha1 == shaOld,
              "★★ ZT3 键在、但这一趟没算出 sha1 ⇒ **不许清**（「不知道」不能当成「换了」）");
    }

    // ---------- ZT4. 取消：传空就把那一档抹掉，两条都空了整条不留 ----------
    {
        UpdatePolicy::Store store;
        UpdatePolicy::setIgnored(store, instanceId, QStringLiteral("mods/jei.jar"),
                                 QStringLiteral("ver-2.0"));
        UpdatePolicy::setPinned(store, instanceId, QStringLiteral("mods/jei.jar"), shaOld);
        UpdatePolicy::setIgnored(store, instanceId, QStringLiteral("mods/jei.jar"), QString());
        check(UpdatePolicy::entryOf(store, instanceId, QStringLiteral("mods/jei.jar")).pinnedSha1
                  == shaOld,
              "ZT4 取消忽略之后固定那一档还在（两档互不牵连）");
        UpdatePolicy::setPinned(store, instanceId, QStringLiteral("mods/jei.jar"), QString());
        check(UpdatePolicy::entryOf(store, instanceId, QStringLiteral("mods/jei.jar")).isEmpty(),
              "★★ ZT4 两档都取消 ⇒ 这一条**整条不留**");
        check(store.isEmpty(), "★★ ZT4 一个文件的记录都没有了 ⇒ 这个实例也不留在表里"
                               "（不留空壳，盘上那份文件也就跟着空了）");
    }

    // ---------- ZT5. 真存真读 ----------
    {
        UpdatePolicy::Store store;
        UpdatePolicy::setIgnored(store, instanceId, QStringLiteral("mods/jei.jar"),
                                 QStringLiteral("ver-2.0"));
        UpdatePolicy::setPinned(store, instanceId, QStringLiteral("shaderpacks/光影.zip"), shaOld);
        UpdatePolicy::setIgnored(store, otherId, QStringLiteral("datapacks/包.zip"),
                                 QStringLiteral("ver-9.9"));
        QString problem;
        check(UpdatePolicy::save(store, UpdatePolicy::storePath(), &problem),
              "ZT5 账本写进盘了", problem);
        // 落点：`<数据目录>/wtfml.updates`（挂在数据根目录下、可以整个拷走）。
        check(QFileInfo::exists(UpdatePolicy::storePath()),
              "ZT5 落在 `<数据目录>/wtfml.updates`", UpdatePolicy::storePath());

        bool ok = false;
        QString readProblem;
        const UpdatePolicy::Store back = UpdatePolicy::load(UpdatePolicy::storePath(), &readProblem);
        check(readProblem.isEmpty(), "ZT5 读回来没报毛病", readProblem);
        check(back.countFor(instanceId) == 2 && back.countFor(otherId) == 1,
              "ZT5 两个实例的账都对得上",
              QStringLiteral("%1 / %2").arg(back.countFor(instanceId)).arg(back.countFor(otherId)));
        const UpdatePolicy::Entry jei =
            UpdatePolicy::entryOf(back, instanceId, QStringLiteral("mods/jei.jar"));
        check(jei.ignoreVersionId == QStringLiteral("ver-2.0"),
              "ZT5 逐字一样地回来了（忽略那一档）", jei.ignoreVersionId);
        check(UpdatePolicy::entryOf(back, instanceId, QStringLiteral("shaderpacks/光影.zip"))
                  .pinnedSha1 == shaOld,
              "★ ZT5 路径里的中文原样回来（**不是**拼一把转义过的键去查 —— 那会一条都查不到）");

        // 格式标记：认不出的文件按"这份账读不懂"处理，**绝不半信半疑地往里加记录**。
        bool tagOk = false;
        const UpdatePolicy::Store foreign =
            UpdatePolicy::fromJson(QByteArrayLiteral("{\"format\":\"别的启动器\",\"version\":1}"),
                                   &tagOk);
        check(!tagOk && foreign.isEmpty(),
              "★★ ZT5 别人写的 json（格式标记不认）⇒ 空表 + **读不懂**：半信半疑地读进来，"
              "最坏的结果是把用户手上那几十个文件按一份莫名其妙的名单判成「已忽略」");
        // 这一条是"读不懂"要**说出来**（`load()` 那句毛病说的是"不是我们写的那种格式"）。
        // 读不懂却回一句"什么都没有"，用户下次打开会发现忽略全没了、而日志里一个字都没有。
        const QString foreignPath = temp.path() + QStringLiteral("/foreign.updates");
        {
            QFile file(foreignPath);
            if (file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
                file.write(QByteArrayLiteral("{\"format\":\"别的启动器\",\"version\":1}"));
            }
        }
        QString foreignProblem;
        const UpdatePolicy::Store fromDisk = UpdatePolicy::load(foreignPath, &foreignProblem);
        check(fromDisk.isEmpty() && !foreignProblem.isEmpty(),
              "★★ ZT5 读盘那一趟把这件事**说出来**了（日志里要看得见）", foreignProblem);
        bool badOk = false;
        const UpdatePolicy::Store bad = UpdatePolicy::fromJson(QByteArrayLiteral("{ 这不是 json"),
                                                               &badOk);
        check(!badOk, "★★ ZT5 根本不是 json ⇒ `ok = false`（和「不是我们写的」是两句话）");
        check(UpdatePolicy::fromJson(UpdatePolicy::toJson(UpdatePolicy::Store())).isEmpty(),
              "ZT5 空表写出去再读回来还是空的");

        // 读盘：文件不在**不是错误**（从来没忽略过谁就是这样）。
        QString missingProblem;
        const UpdatePolicy::Store none =
            UpdatePolicy::load(temp.path() + QStringLiteral("/wtfml.updates.nosuch"),
                               &missingProblem);
        check(missingProblem.isEmpty() && none.isEmpty(),
              "★★ ZT5 文件不在 ⇒ 空表、而且**不算错**（从来没忽略过谁就是这个样子）",
              missingProblem);
    }

    AppPaths::setMinecraftDir(originalDir);
    check(AppPaths::minecraftDir() == originalDir, "ZT9 数据根目录换回来了");
}

// ---------------------------------------------------------------------------
// ZU. 更新前那份轻量回滚点：抄一份 / 退回去 / 撤干净（coding plan §7.1）
//
// 这一节要**真动盘**（在一个临时游戏文件夹里造实例目录），因为这一层整个存在的意义就是
// "动手之前手上有一份旧的"：抄得对不对、退回来的**是内容是字节**、更新新添的那个文件撤回
// 时**要消失** —— 这三件事在纯值上一条都验不出来。
//
// ★ 最要紧的几条（错了会静默丢数据）：
//   · 清单里"当时有没有这个文件"要记准（记错了 = 撤销时把一个**本来就在**的文件删掉）；
//   · 只留**最新那一份**（留多代 = 每更新一次攒几十 MB，而用户永远只用最近那一次）；
//   · 一条失败**不影响其余**（"3 个没退回去"比"失败了，一个都没动"诚实）。
// ---------------------------------------------------------------------------
static void runUpdateRollbackTests() {
    section("ZU. 更新中心：更新前的轻量回滚点（§7.1）");

    const QString originalDir = AppPaths::minecraftDir();
    QTemporaryDir temp;
    check(temp.isValid(), "ZU0 临时数据根目录建出来了");
    if (!temp.isValid()) {
        return;
    }
    AppPaths::setMinecraftDir(temp.path());

    const QString instanceId = QStringLiteral("1.20.1-forge-47.2.0");
    // ★ 实例 id 里带 `/`（`isKnownGameVersion()` 那一档放行的名字）：这一层得把它换成
    //   合法的一段，否则这一份回滚点会落到别的目录里去。
    const QString slashyId = QStringLiteral("20w14∞/test");
    const QString instanceDir = temp.path() + QStringLiteral("/versions/") + instanceId;
    const QString modsDir = instanceDir + QStringLiteral("/mods");
    QDir().mkpath(modsDir);
    QDir().mkpath(instanceDir + QStringLiteral("/shaderpacks"));

    const auto writeAt = [](const QString &path, const QByteArray &bytes) {
        QDir().mkpath(QFileInfo(path).absolutePath());
        QFile file(path);
        if (file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            file.write(bytes);
        }
    };
    const auto readAt = [](const QString &path) {
        QByteArray bytes;
        QFile file(path);
        if (file.open(QIODevice::ReadOnly)) {
            bytes = file.readAll();
        }
        return bytes;
    };

    const QString jei = modsDir + QStringLiteral("/jei.jar");
    const QString shader = instanceDir + QStringLiteral("/shaderpacks/光影.zip");
    writeAt(jei, QByteArrayLiteral("JEI-1.0-OLD"));
    writeAt(shader, QByteArrayLiteral("SHADER-OLD"));

    // ---------- ZU1. 抄一份 ----------
    const QStringList relative{
        QStringLiteral("mods/jei.jar"),
        QStringLiteral("shaderpacks/光影.zip"),
        QStringLiteral("mods/新加的.jar"),  // 更新新添的那个：当时**不在**
    };
    QString problem;
    const UpdateRollback::Snapshot snapshot =
        UpdateRollback::create(instanceDir, instanceId, relative, &problem);
    check(snapshot.isValid(), "ZU1 回滚点摆成了", problem);
    check(snapshot.fileCount() == 2, "★ ZU1 清单里「当时在」的是 2 个（第三个当时不在）",
          QString::number(snapshot.fileCount()));
    check(snapshot.addedCount() == 1,
          "★★ ZU1 当时**不在**的那一个也进了清单（撤销时要把更新新添的那份删掉）",
          QString::number(snapshot.addedCount()));
    check(snapshot.totalBytes() == 11 + 10,
          "ZU1 大小是**数出来的**（JEI-1.0-OLD 11 + SHADER-OLD 10）",
          QString::number(snapshot.totalBytes()));
    // 落点：`<数据目录>/cache/update-rollback/<实例id>/`，原件摆在 `files/` 底下、相对路径
    // 原样保留（"这份回滚点是哪个文件的"一眼看得出）。
    check(snapshot.dir == UpdateRollback::snapshotDir(instanceId) &&
              snapshot.dir.startsWith(temp.path() + QStringLiteral("/cache/update-rollback/")),
          "ZU1 落在 `<数据目录>/cache/update-rollback/<实例id>/`", snapshot.dir);
    check(QFileInfo::exists(snapshot.dir + QStringLiteral("/files/mods/jei.jar")) &&
              QFileInfo::exists(snapshot.dir + QStringLiteral("/files/shaderpacks/光影.zip")),
          "★ ZU1 原件照着**相对路径**摆在 `files/` 底下（还原不用另记一张映射表）");
    check(QFileInfo::exists(snapshot.dir + QStringLiteral("/") + UpdateRollback::manifestName()),
          "ZU1 那张清单也在（没有它这一份回滚点用不了）");

    // ---------- ZU2. 上手改文件，再退回去 ----------
    writeAt(jei, QByteArrayLiteral("JEI-2.0-NEW"));
    writeAt(shader, QByteArrayLiteral("SHADER-NEW"));
    writeAt(modsDir + QStringLiteral("/新加的.jar"), QByteArrayLiteral("BRAND-NEW"));
    {
        const UpdateRollback::RestoreResult result =
            UpdateRollback::restore(snapshot, instanceDir);
        check(result.ok() && result.restored == 2 && result.removed == 1,
              "★ ZU2 退回去：换回来 2 个、删掉 1 个（更新新添的那一份）",
              QStringLiteral("restored=%1 removed=%2 failed=%3")
                  .arg(result.restored)
                  .arg(result.removed)
                  .arg(result.failed));
        check(readAt(jei) == QByteArrayLiteral("JEI-1.0-OLD"),
              "★★ ZU2 退回来的是**内容**（不只是「文件在那儿」）", QString::fromUtf8(readAt(jei)));
        check(readAt(shader) == QByteArrayLiteral("SHADER-OLD"),
              "ZU2 那个中文路径的文件也退回来了");
        check(!QFileInfo::exists(modsDir + QStringLiteral("/新加的.jar")),
              "★★ ZU2 更新新添的那一个**消失**了（「这个文件原来不在」也是一件事）");
    }

    // ---------- ZU3. 只留最新那一份 ----------
    //
    // 再摆一份（这一次少了 JEI）：上一趟那份要**整个**没掉 —— 留着的话，撤销按钮说的
    // 和用户手上那份东西就对不上了。
    {
        const UpdateRollback::Snapshot second = UpdateRollback::create(
            instanceDir, instanceId, QStringList{QStringLiteral("shaderpacks/光影.zip")});
        check(second.isValid() && second.entries.size() == 1,
              "ZU3 第二份回滚点摆成了（只记了 1 条）");
        const UpdateRollback::Snapshot back = UpdateRollback::read(instanceId);
        check(back.isValid() && back.entries.size() == 1,
              "★★ ZU3 盘上**只剩最新那一份**（上一趟那份整个删掉了）",
              QString::number(back.entries.size()));
        check(!QFileInfo::exists(back.dir + QStringLiteral("/files/mods/jei.jar")),
              "ZU3 上一趟那份的原件跟着没了");
    }

    // ---------- ZU4. 读 / 撤干净 / 清单读不动 ----------
    {
        bool ok = false;
        const UpdateRollback::Snapshot read = UpdateRollback::read(instanceId, &ok);
        check(ok && read.isValid() && read.instanceId == instanceId,
              "ZU4 读得动那一份，而且说得清它是哪个实例的", read.instanceId);
        check(read.createdAt.isValid(), "ZU4 时间戳也回来了（界面那句话说「什么时候留的」）");

        check(UpdateRollback::discard(instanceId), "ZU4 撤掉了");
        check(!QDir(UpdateRollback::snapshotDir(instanceId)).exists(),
              "★ ZU4 整个目录都没了（不是只删清单）");
        bool noneOk = false;
        UpdateRollback::read(instanceId, &noneOk);
        check(!noneOk, "★★ ZU4 撤完之后读不到「能用的那一份」（那正是「撤销」那颗按钮藏起来的判据）");
        check(UpdateRollback::discard(instanceId),
              "ZU4 本来就没有再撤一次也不算错（幂等）");

        // ★ 清单读不动 = 这一份回滚点用不了：**数据不全的东西不能拿去还原**。
        const QString dir = UpdateRollback::snapshotDir(instanceId);
        QDir().mkpath(dir + QStringLiteral("/files/mods"));
        writeAt(dir + QStringLiteral("/files/mods/jei.jar"), QByteArrayLiteral("JEI-1.0-OLD"));
        writeAt(dir + QStringLiteral("/") + UpdateRollback::manifestName(),
                 QByteArrayLiteral("{ 这不是 json"));
        QDir().mkpath(instanceDir + QStringLiteral("/mods"));
        writeAt(jei, QByteArrayLiteral("JEI-2.0-NEW"));
        bool brokenOk = false;
        QString brokenProblem;
        const UpdateRollback::Snapshot broken =
            UpdateRollback::read(instanceId, &brokenOk, &brokenProblem);
        check(!brokenOk && !broken.isValid() && !brokenProblem.isEmpty(),
              "★★ ZU4 清单读不动 ⇒ **不算「有一份」**（残缺的回滚点不能拿去还原）", brokenProblem);
        // 而且这时候**一个文件都不许动**：调用方拿到的 invalid 快照去做 restore 是没人拦的，
        // 所以这一条说的是"读侧不撒谎"。
        check(readAt(jei) == QByteArrayLiteral("JEI-2.0-NEW"),
              "ZU4 读那一趟本身一个字节都没碰");
        UpdateRollback::discard(instanceId);
    }

    // ---------- ZU5. 路径的合法性（我们自己算错的那些） ----------
    //
    // 清单里的路径是我们按目录走出来的；真出现一个不合法的，那是**上面那一层算错了**，
    // 当场拒绝比往实例目录外面写/删东西强。
    {
        QString badProblem;
        const UpdateRollback::Snapshot bad = UpdateRollback::create(
            instanceDir, instanceId,
            QStringList{QStringLiteral("../外面.jar"), QStringLiteral("mods/好的.jar")},
            &badProblem);
        check(!bad.isValid() && !badProblem.isEmpty(),
              "★★ ZU5 带 `..` 的路径 ⇒ **整份拒绝**（不就地跳过、也不往外面写）", badProblem);

        // ★ 实例 id 里带 `/` 的那一档：目录名要换成合法的一段，但**账上记的还是原来的 id**。
        QString slashyProblem;
        const UpdateRollback::Snapshot slashy = UpdateRollback::create(
            instanceDir, slashyId, QStringList{QStringLiteral("mods/jei.jar")}, &slashyProblem);
        check(slashy.isValid(), "ZU5 实例 id 里带 `/` 也能摆一份", slashyProblem);
        check(slashy.instanceId == slashyId,
              "★ ZU5 账上记的还是**原来的 id**（改成合法的那一段只是目录名）", slashy.instanceId);
        check(slashy.dir.startsWith(temp.path() + QStringLiteral("/cache/update-rollback/")) &&
                  !slashy.dir.contains(QStringLiteral("20w14∞/test")),
              "★ ZU5 而目录名里那个 `/` 被换掉了（它得是个合法的一段）", slashy.dir);
        // ★★ 清洗是**多对一**的（`a/b` 和 `a\b` 都变成 `a-b`），所以末尾还挂了原来 id 的
        //    哈希：两个实例共用一份回滚点的后果是"还原的时候把 A 的旧文件写进 B 里"。
        check(UpdateRollback::snapshotDir(QStringLiteral("a/b")) !=
                  UpdateRollback::snapshotDir(QStringLiteral("a\\b")),
              "★★ ZU5 清洗之后**还是一一对应**（两个实例不许共用一份回滚点）");
        bool slashyOk = false;
        const UpdateRollback::Snapshot slashyBack = UpdateRollback::read(slashyId, &slashyOk);
        check(slashyOk && slashyBack.instanceId == slashyId,
              "★★ ZU5 按原来的 id 读得回来（存和读用的是同一个换算）");
        UpdateRollback::discard(slashyId);
    }

    AppPaths::setMinecraftDir(originalDir);
    check(AppPaths::minecraftDir() == originalDir, "ZU9 数据根目录换回来了");
}

// ---------------------------------------------------------------------------
// ZW. 服务端判据层：状态 / EULA / server.properties / 我们记的那一份（coding plan §6 / M4）
//
// 这一节全是**纯函数**（值进、结构出）：一个服务端目录都不必真的存在、一个进程都不必起。
// 盯的是几处"错了不会报错、只会静默丢东西"的地方：
//   · `eula.txt` 到底算不算"接受了"（文件头那段声明里就有 `eula` 字样，判成"含 true 就算"会误判）；
//   · 我们写下去的那份 `eula.txt` 里那句声明**必须原样留着**（它是"用户接受了"的文本凭证）；
//   · `server.properties` 解了再写出去要**原地往返**（注释、键序、CRLF 一个字节都不许动 ——
//     用户在表单里改了端口，别的东西不该跟着变）；
//   · 从文件反推"这是哪一档"、以及"装好了没有"的判据（Spigot 那一档产物名拼不出来只能扫）。
// ---------------------------------------------------------------------------
static void runServerModelTests() {
    section("ZW. 服务端判据层：状态 / EULA / properties（§6 / M4）");

    // ---------- ZW1. 那七档状态 ----------
    check(ServerModel::statusName(ServerModel::Status::NotInstalled) == QStringLiteral("未安装"),
          "ZW1 「未安装」那句话的唯一出处");
    check(ServerModel::statusName(ServerModel::Status::Crashed) == QStringLiteral("异常退出"),
          "ZW1 异常退出是单独一档（和「已停止」不是一句话）");
    check(ServerModel::isLive(ServerModel::Status::Starting) &&
              ServerModel::isLive(ServerModel::Status::Running) &&
              ServerModel::isLive(ServerModel::Status::Stopping) &&
              !ServerModel::isLive(ServerModel::Status::Ready) &&
              !ServerModel::isLive(ServerModel::Status::Stopped),
          "ZW1 「在跑」只有启动中/运行中/停止中三档（可启动/已停止都不算）");
    check(ServerModel::canStart(ServerModel::Status::Ready) &&
              ServerModel::canStart(ServerModel::Status::Stopped) &&
              ServerModel::canStart(ServerModel::Status::Crashed) &&
              !ServerModel::canStart(ServerModel::Status::Running) &&
              !ServerModel::canStart(ServerModel::Status::NotInstalled),
          "★ ZW1 能启动的是可启动/已停止/异常退出；**没装好**和**正在跑**都不能按");

    // ---------- ZW2. eula.txt 算不算"接受了" ----------
    check(!ServerModel::eulaAccepted(QString()),
          "ZW2 空字节（服务端还没跑过）⇒ 还没接受");
    // ★ 服务端自己写的那份文件头里就有 `eula` 字样（网址那段），只按"含 true"判会误判。
    check(!ServerModel::eulaAccepted(
              QStringLiteral("#By changing the setting below to TRUE you are indicating your "
                             "agreement to our EULA (https://aka.ms/MinecraftEULA).\n"
                             "eula=false\n")),
          "★★ ZW2 文件头那段声明里出现 TRUE / eula 字样**不算**接受（判的是 `eula=` 那一项）");
    check(ServerModel::eulaAccepted(QStringLiteral("eula=true\n")),
          "ZW2 eula=true ⇒ 接受");
    check(ServerModel::eulaAccepted(QStringLiteral("eula=TRUE\n")),
          "ZW2 大小写不敏感（服务端自己写的是小写，用户手改的可能是大写）");
    // 后面的盖前面的（Java Properties 语义）：用户先写 false 又跟一行 true ⇒ 以最后那行为准。
    check(ServerModel::eulaAccepted(QStringLiteral("eula=false\neula=true\n")),
          "★ ZW2 两行都有 ⇒ **最后一个有效赋值**说了算");
    check(!ServerModel::eulaAccepted(QStringLiteral("eula=true\neula=false\n")),
          "★ ZW2 反过来（末尾是 false）⇒ 还没接受");
    check(!ServerModel::eulaAccepted(QStringLiteral("agree=true\n")),
          "ZW2 不是 eula 那一项 ⇒ 不算");

    // ---------- ZW3. 我们写下去的那份 eula.txt ----------
    const QString eulaText = ServerModel::eulaFileText(true);
    check(eulaText.contains(QStringLiteral("ka.ms/MinecraftEULA")),
          "★★ ZW3 写下去的那份**留着那句 EULA 声明**（它是「用户接受了」的文本凭证）");
    check(ServerModel::eulaAccepted(eulaText),
          "ZW3 我们自己写的那份，读回来就是「已接受」");
    check(eulaText.endsWith(QStringLiteral("eula=true\n")),
          "ZW3 最后那行就是 eula=true");
    check(!ServerModel::eulaAccepted(ServerModel::eulaFileText(false)),
          "ZW3 写 false 的那一份读回来是「没接受」（留个口子，产品里只会写 true）");

    // ---------- ZW4. server.properties：解 / 改 / 原样写回 ----------
    {
        // ★ 带注释、带 CRLF、键序打乱 —— 解了再写出去，这些**一个字节都不许动**。
        const QString raw = QStringLiteral("#Minecraft server properties\r\n"
                                           "#(这是游戏自己写的文件头)\r\n"
                                           "max-players=20\r\n"
                                           "server-port=25565\r\n"
                                           "motd=A Minecraft Server\r\n");
        const ServerModel::Properties props = ServerModel::parseProperties(raw);
        check(props.value(QStringLiteral("server-port")) == QStringLiteral("25565"),
              "ZW4 读得出一项的值");
        check(props.value(QStringLiteral("motd")) == QStringLiteral("A Minecraft Server"),
              "★ ZW4 值里的空格原样（只裁两侧空白）");
        check(!props.contains(QStringLiteral("max-players")) == false,
              "ZW4 含有的键问得出来");
        check(props.contains(QStringLiteral("server-port")) && !props.contains(QStringLiteral("nope")),
              "ZW4 不存在的键回 false");
        // 没动过 ⇒ 逐字吐回去（含那两行注释、含 CRLF）。
        check(props.toString() == raw,
              "★★ ZW4 没改过 ⇒ 解了再写出来**逐字一样**（注释、键序、CRLF 一个字节都不动）");
    }
    {
        // 改一项：被改的那行重新拼，别的原样。
        ServerModel::Properties props =
            ServerModel::parseProperties(QStringLiteral("#头\nserver-port=25565\nmotd=hi\n"));
        check(props.setValue(QStringLiteral("server-port"), QStringLiteral("25566")),
              "ZW4 改一项返回 true（真改了）");
        check(!props.setValue(QStringLiteral("server-port"), QStringLiteral("25566")),
              "ZW4 改成一样的值返回 false（没改）");
        const QString out = props.toString();
        check(out.contains(QStringLiteral("server-port=25566")) &&
                  out.contains(QStringLiteral("#头")) && out.contains(QStringLiteral("motd=hi")),
              "★ ZW4 只改了那一行，注释和别的键还在");
        // 加一项：没有的键追到末尾。
        check(props.setValue(QStringLiteral("pvp"), QStringLiteral("true")),
              "ZW4 加一项返回 true");
        check(props.toString().endsWith(QStringLiteral("pvp=true\n")),
              "ZW4 新加的键落在末尾");
    }
    {
        // 冒号分隔 / `!` 注释 / 读不懂的行原样留着。
        const ServerModel::Properties props = ServerModel::parseProperties(
            QStringLiteral("!这是感叹号注释\nserver-port:25570\n这行读不懂\n"));
        check(props.value(QStringLiteral("server-port")) == QStringLiteral("25570"),
              "★ ZW4 冒号分隔也认（Java Properties 两种都行）");
        // 读不懂的行走 raw 那条原样吐出。
        check(props.toString().contains(QStringLiteral("这行读不懂")) &&
                  props.toString().contains(QStringLiteral("!这是感叹号注释")),
              "★ ZW4 读不懂的行与 `!` 注释原样保留");
    }

    // ---------- ZW5. 端口 ----------
    check(ServerModel::serverPortOf(ServerModel::parseProperties(QString())) ==
              ServerModel::defaultServerPort(),
          "ZW5 没写端口 ⇒ 缺省 25565");
    check(ServerModel::serverPortOf(ServerModel::parseProperties(
              QStringLiteral("server-port=25566\n"))) == 25566,
          "ZW5 写了的照读");
    check(ServerModel::serverPortOf(ServerModel::parseProperties(
              QStringLiteral("server-port=abc\n"))) == -1,
          "★ ZW5 读不出来的回 **-1**（「不知道」，调用方别编一个数）");
    check(ServerModel::serverPortOf(ServerModel::parseProperties(
              QStringLiteral("server-port=99999\n"))) == -1,
          "★ ZW5 越界的端口也回 -1");

    // ---------- ZW6. 从文件反推是哪一档 ----------
    const auto infer = [](const QStringList &paths) {
        return ServerModel::inferFlavorFromPaths(paths);
    };
    check(infer(QStringList{QStringLiteral("server.jar")}) == ServerInstall::Flavor::Vanilla,
          "ZW6 只有 server.jar ⇒ 原版那一档（纸/紫水/jar 类同命，缺省最稳）");
    check(infer(QStringList{QStringLiteral("fabric-server-launch.jar"),
                            QStringLiteral("server.jar")}) == ServerInstall::Flavor::Fabric,
          "ZW6 fabric-server-launch.jar ⇒ Fabric");
    check(infer(QStringList{QStringLiteral("quilt-server-launch.jar"),
                            QStringLiteral("server.jar")}) == ServerInstall::Flavor::Quilt,
          "ZW6 quilt-server-launch.jar ⇒ Quilt");
    check(infer(QStringList{QStringLiteral("user_jvm_args.txt"),
                            QStringLiteral(
                                "libraries/net/minecraftforge/forge/1.20.1-47.2.0/win_args.txt")}) ==
              ServerInstall::Flavor::Forge,
          "★ ZW6 认得出 libraries 深处那张 win_args.txt ⇒ Forge");
    check(infer(QStringList{QStringLiteral(
              "libraries/net/neoforged/neoforge/21.1.0/win_args.txt")}) ==
              ServerInstall::Flavor::NeoForge,
          "★ ZW6 neoforged 那一支 ⇒ NeoForge（别和 minecraftforge 混）");

    // ---------- ZW7. 装好了没有 ----------
    {
        ServerInstall::Request vanilla;
        vanilla.flavor = ServerInstall::Flavor::Vanilla;
        vanilla.gameVersion = QStringLiteral("1.20.1");
        const ServerInstall::Plan vPlan = ServerInstall::planFor(vanilla);
        check(ServerModel::isInstalled(vPlan, QStringList{QStringLiteral("server.jar")}),
              "ZW7 原版：server.jar 在 ⇒ 装好了");
        check(!ServerModel::isInstalled(vPlan, QStringList{QStringLiteral("eula.txt")}),
              "ZW7 原版：没有 server.jar ⇒ 没装好");

        ServerInstall::Request quilt;
        quilt.flavor = ServerInstall::Flavor::Quilt;
        quilt.gameVersion = QStringLiteral("1.20.1");
        quilt.installerVersion = QStringLiteral("0.9.0");
        const ServerInstall::Plan qPlan = ServerInstall::planFor(quilt);
        check(!ServerModel::isInstalled(qPlan, QStringList{QStringLiteral("quilt-server-launch.jar")}),
              "★★ ZW7 Quilt 那两张**都要**（光有壳、缺 server.jar 时它一句话不说就退出）");
        check(ServerModel::isInstalled(
                  qPlan, QStringList{QStringLiteral("quilt-server-launch.jar"),
                                     QStringLiteral("server.jar")}),
              "ZW7 Quilt 两张都在 ⇒ 装好了");

        ServerInstall::Request spigot;
        spigot.flavor = ServerInstall::Flavor::Spigot;
        spigot.gameVersion = QStringLiteral("1.20.1");
        const ServerInstall::Plan sPlan = ServerInstall::planFor(spigot);
        check(sPlan.installedMarkers.isEmpty(),
              "ZW7 Spigot 那一档的 markers 是空的（产物名拼不出来）");
        check(ServerModel::isInstalled(
                  sPlan, QStringList{QStringLiteral("spigot-1.20.1-R0.1-SNAPSHOT.jar")}),
              "★★ ZW7 Spigot：扫 spigot-*.jar（名字带它自己的后缀，拼不出来）");
        check(!ServerModel::isInstalled(sPlan, QStringList{QStringLiteral("server.jar")}),
              "ZW7 Spigot：没有 spigot-*.jar ⇒ 没装好");
    }

    // ---------- ZW8. 我们记的那一份（.wtfml-server 的字节） ----------
    {
        ServerModel::Info info;
        info.serverId = QStringLiteral("srv-1");
        info.name = QStringLiteral("我的服");
        info.flavor = ServerInstall::Flavor::Forge;
        info.flavorKnown = true;
        info.gameVersion = QStringLiteral("1.20.1");
        info.loaderVersion = QStringLiteral("47.2.0");
        info.memoryMb = 4096;
        bool ok = false;
        const ServerModel::Info back = ServerModel::fromJson(ServerModel::toJson(info), &ok);
        check(ok, "ZW8 我们写的那一份读得回来");
        check(back.serverId == info.serverId && back.name == info.name &&
                  back.flavor == info.flavor && back.flavorKnown &&
                  back.gameVersion == info.gameVersion &&
                  back.loaderVersion == info.loaderVersion && back.memoryMb == 4096,
              "ZW8 逐字一样地回来了", back.name);
        // 空字节 = 真读懂了（这个服务端什么设置都没有），**不是**读不懂。
        bool emptyOk = false;
        check(ServerModel::fromJson(QByteArray(), &emptyOk).isEmpty() && emptyOk,
              "★★ ZW8 空字节回**空 Info + ok=true**（真读懂了：什么都没有）");
        // 别人写的 / 以后改了格式的 ⇒ 读不懂（别半信半疑地往里加东西）。
        bool foreignOk = false;
        check(ServerModel::fromJson(QByteArrayLiteral("{\"format\":\"别的启动器\",\"version\":1}"),
                                    &foreignOk)
                      .isEmpty() &&
                  !foreignOk,
              "★★ ZW8 格式标记不认 ⇒ 空 Info + **读不懂**");
        bool junkOk = false;
        check(ServerModel::fromJson(QByteArrayLiteral("{ 这不是 json"), &junkOk).isEmpty() &&
                  !junkOk,
              "ZW8 根本不是 json ⇒ 读不懂");

        // 能不能直接拿来启动。
        check(ServerModel::hasLaunchableInfo(info),
              "ZW8 Forge：游戏版本 + 加载器版本都在 ⇒ 能拼出启动命令");
        ServerModel::Info missing = info;
        missing.loaderVersion.clear();
        check(!ServerModel::hasLaunchableInfo(missing),
              "ZW8 Forge 缺加载器版本 ⇒ 拼不出来（得让用户挑一次）");
        ServerModel::Info fabric = info;
        fabric.flavor = ServerInstall::Flavor::Fabric;
        fabric.installerVersion.clear();
        check(!ServerModel::hasLaunchableInfo(fabric),
              "ZW8 Fabric 还要安装器版本");
    }
}

// ---------------------------------------------------------------------------
// ZX. 服务端工作区：`<数据目录>/Servers` 底下谁在住（coding plan §6 / M4）
//
// ★ 这一节**真动盘**：在一个 QTemporaryDir（当成临时数据根目录）里真建目录、真写文件、真删。
//   盯的是这一层唯一一件本事 —— "把盘上那个目录读成一行事实"：
//   · 自己记的那一份（`.wtfml-server`）优先，没有才从文件反推（反推的要标成"猜的"）；
//   · "装好了没有"是照盘上的文件认的（缺哪一样要说得出来）；
//   · `removeServer()` 的三道闸（空 id / 路径分隔符 / 不许删到根外面）。
// ---------------------------------------------------------------------------
static void runServerRegistryTests() {
    section("ZX. 服务端工作区：Servers 底下谁在住（§6 / M4）");

    const QString originalDir = AppPaths::minecraftDir();
    QTemporaryDir temp;
    check(temp.isValid(), "ZX0 临时数据根目录建出来了");
    if (!temp.isValid()) {
        return;
    }
    AppPaths::setMinecraftDir(temp.path());

    // ---------- ZX1. 根目录与空表 ----------
    check(ServerRegistry::rootDir() == temp.path() + QStringLiteral("/Servers"),
          "ZX1 根就是 `<数据目录>/Servers`", ServerRegistry::rootDir());
    check(ServerRegistry::serverIds().isEmpty(),
          "★ ZX1 根还没建出来 ⇒ 空表（不是错误）");
    QString rootProblem;
    check(ServerRegistry::ensureRoot(&rootProblem) && QDir(ServerRegistry::rootDir()).exists(),
          "ZX1 ensureRoot 把根建出来了", rootProblem);

    // ---------- ZX2. 建一个（我们记的那一份说了算） ----------
    {
        ServerModel::Info info;
        info.name = QStringLiteral("我的服");
        info.flavor = ServerInstall::Flavor::Vanilla;
        info.flavorKnown = true;
        info.gameVersion = QStringLiteral("1.20.1");
        QString problem;
        check(ServerRegistry::createServer(QStringLiteral("Srv1"), info, &problem),
              "ZX2 建出来了", problem);
        check(QFileInfo::exists(AppPaths::serverMetaPath(QStringLiteral("Srv1"))),
              "ZX2 `.wtfml-server` 落在服务端目录里");

        QString describeProblem;
        const ServerRegistry::Entry entry =
            ServerRegistry::describe(QStringLiteral("Srv1"), &describeProblem);
        check(entry.serverId == QStringLiteral("Srv1"), "ZX2 身份是目录名");
        check(entry.name == QStringLiteral("我的服"),
              "ZX2 显示名取我们记的那一份（不是目录名）", entry.name);
        check(entry.flavorKnown && entry.flavor == ServerInstall::Flavor::Vanilla,
              "★ ZX2 自己记的那一档是**已知**的（不打「反推」那句）");
        check(!entry.installed && entry.note.contains(QStringLiteral("缺")),
              "★★ ZX2 还没放 server.jar ⇒ **没装好**，而且说得出缺什么", entry.note);
        check(entry.port == ServerModel::defaultServerPort(),
              "ZX2 没有 server.properties ⇒ 端口是缺省那个", QString::number(entry.port));
        check(!entry.eulaAccepted, "ZX2 还没有 eula.txt ⇒ 没接受");
    }

    // ---------- ZX3. 放一个 server.jar 进去 ⇒ 装好了 ----------
    {
        QFile jar(AppPaths::serverDir(QStringLiteral("Srv1"))
                  + QStringLiteral("/server.jar"));
        if (jar.open(QIODevice::WriteOnly)) {
            jar.write("jar");
            jar.close();
        }
        const ServerRegistry::Entry entry = ServerRegistry::describe(QStringLiteral("Srv1"));
        check(entry.installed,
              "★★ ZX3 盘上出现了 server.jar ⇒ 判成「装好了」（判据是文件，不是我们记的那一句）");
        check(entry.note.isEmpty(), "ZX3 装好之后那句「缺 …」就没了", entry.note);
    }

    // ---------- ZX4. EULA 真存真读 ----------
    {
        QString problem;
        check(ServerRegistry::acceptEula(QStringLiteral("Srv1"), &problem),
              "ZX4 写下一份接受的 eula.txt", problem);
        check(ServerRegistry::readEula(QStringLiteral("Srv1")),
              "★ ZX4 写下去之后读回来就是「已接受」");
        check(ServerRegistry::describe(QStringLiteral("Srv1")).eulaAccepted,
              "ZX4 describe 那一行也跟着是「已接受」");
    }

    // ---------- ZX5. server.properties 真存真读 ----------
    {
        QString problem;
        ServerModel::Properties props;
        props.setValue(QStringLiteral("server-port"), QStringLiteral("25566"));
        props.setValue(QStringLiteral("motd"), QStringLiteral("我的服务器"));
        check(ServerRegistry::writeProperties(QStringLiteral("Srv1"), props, &problem),
              "ZX5 写 server.properties", problem);
        QString readProblem;
        const ServerModel::Properties back =
            ServerRegistry::readProperties(QStringLiteral("Srv1"), &readProblem);
        check(readProblem.isEmpty(), "ZX5 读回来没报毛病", readProblem);
        check(ServerModel::serverPortOf(back) == 25566 &&
                  back.value(QStringLiteral("motd")) == QStringLiteral("我的服务器"),
              "★ ZX5 端口和中文都逐字回来了（按 UTF-8 写、按 UTF-8 读）");
        check(ServerRegistry::describe(QStringLiteral("Srv1")).port == 25566,
              "ZX5 describe 那一行的端口跟着变");
    }

    // ---------- ZX6. 从外面拖进来的：没有我们记的那一份 ⇒ 从文件反推 ----------
    {
        const QString dir = AppPaths::serverDir(QStringLiteral("Paper1"));
        QDir().mkpath(dir + QStringLiteral("/libraries/net/minecraftforge/forge/1.20.1-47.2.0"));
        const auto touch = [](const QString &path) {
            QFile file(path);
            if (file.open(QIODevice::WriteOnly)) {
                file.write("x");
                file.close();
            }
        };
        touch(dir + QStringLiteral(
                       "/libraries/net/minecraftforge/forge/1.20.1-47.2.0/win_args.txt"));
        touch(dir + QStringLiteral("/user_jvm_args.txt"));

        const ServerRegistry::Entry entry = ServerRegistry::describe(QStringLiteral("Paper1"));
        check(!entry.flavorKnown,
              "★★ ZX6 没有 `.wtfml-server` ⇒ 那一档是**反推**的（标成「猜的」）");
        check(entry.flavor == ServerInstall::Flavor::Forge,
              "★★ ZX6 从 libraries 那张 win_args.txt 反推成 Forge", entry.name);
        check(entry.installed,
              "ZX6 两张参数文件都在 ⇒ 判成装好了");
        check(entry.note.contains(QStringLiteral("反推")),
              "★ ZX6 那一行写着「这一档是反推的」，让用户点一下确认");
        check(entry.name == QStringLiteral("Paper1"),
              "ZX6 没有我们记的名字 ⇒ 显示名退回目录名");
    }

    // ---------- ZX7. 名字的清洗 / 去重 ----------
    {
        check(ServerRegistry::sanitizeId(QStringLiteral("a/b:c")) == QStringLiteral("a_b_c"),
              "ZX7 路径分隔符和冒号换成下划线", ServerRegistry::sanitizeId(QStringLiteral("a/b:c")));
        check(ServerRegistry::sanitizeId(QStringLiteral("  .hidden ")) == QStringLiteral("hidden"),
              "★ ZX7 首尾的点和空白摘掉（Windows 存下去会自己吃掉，不如先摘）");
        check(ServerRegistry::sanitizeId(QStringLiteral("Server1.20.1")) ==
                  QStringLiteral("Server1.20.1"),
              "★ ZX7 名字里的点**不摘**（`Server1.20.1` 是用户真机上那种叫法）");
        // ★ 空格必须原样留着（真机上的名字就有带空格的）。这一条专门盯"s 那串禁字符里
        //   混进一个空格"那种写法 —— 症状是每个空格都被换成下划线。
        check(ServerRegistry::sanitizeId(QStringLiteral("我的 服务端 2")) ==
                  QStringLiteral("我的 服务端 2"),
              "★★ ZX7 名字里的空格**原样留着**（不许被当成禁字符换掉）",
              ServerRegistry::sanitizeId(QStringLiteral("我的 服务端 2")));
        check(ServerRegistry::sanitizeId(QString()).isEmpty(),
              "ZX7 洗空了 ⇒ 空串（调用方得让用户重敲）");
        check(ServerRegistry::uniqueServerId(QStringLiteral("Srv1")) == QStringLiteral("Srv1-2"),
              "★★ ZX7 撞名了就加后缀（Srv1 已存在 ⇒ Srv1-2）",
              ServerRegistry::uniqueServerId(QStringLiteral("Srv1")));
        check(ServerRegistry::uniqueServerId(QStringLiteral("全新")) == QStringLiteral("全新"),
              "ZX7 没撞名的原样");
        check(ServerRegistry::defaultServerName(ServerInstall::Flavor::Vanilla,
                                                QStringLiteral("1.20.1")) ==
                  QStringLiteral("Server1.20.1"),
              "ZX7 默认名照用户真机上那份叫法（Server<版本>）");
        check(ServerRegistry::defaultServerName(ServerInstall::Flavor::Vanilla, QString()) ==
                  QStringLiteral("Server"),
              "ZX7 不知道版本就回 Server");
    }

    // ---------- ZX8. 删之前那三道闸 ----------
    {
        check(!ServerRegistry::removeServer(QString(), nullptr),
              "★★ ZX8 空 id 不许删");
        check(!ServerRegistry::removeServer(QStringLiteral("."), nullptr) &&
                  !ServerRegistry::removeServer(QStringLiteral(".."), nullptr),
              "★★ ZX8 `.` / `..` 不许删（那是根）");
        check(!ServerRegistry::removeServer(QStringLiteral("a/b"), nullptr) &&
                  !ServerRegistry::removeServer(QStringLiteral("a\\b"), nullptr),
              "★★ ZX8 带路径分隔符的不许删（别删到根外面去）");
        check(ServerRegistry::removeServer(QStringLiteral("不存在的服"), nullptr),
              "ZX8 本来就不在 = 已经达成目的（回 true）");
    }

    // ---------- ZX9. 真删一个 ----------
    {
        const QString dir = AppPaths::serverDir(QStringLiteral("Srv1"));
        check(QDir(dir).exists(), "ZX9 删之前那个目录在");
        check(ServerRegistry::removeServer(QStringLiteral("Srv1"), nullptr),
              "ZX9 删成功");
        check(!QDir(dir).exists(), "ZX9 目录连带里面的文件都没了");
        check(!ServerRegistry::serverIds().contains(QStringLiteral("Srv1")),
              "ZX9 列表里也不再是它");
    }

    AppPaths::setMinecraftDir(originalDir);
    check(AppPaths::minecraftDir() == originalDir, "ZX9 数据根目录换回来了");
}

// ---------------------------------------------------------------------------
// ZY. 服务端安装那四段的**判据层**（coding plan §6.2 / M4-2）
//
// `ServerInstallRun.hpp` 那个头整个是纯函数：喂一份 `Plan` + 一份字节进去，回一个结论出来。
// 所以这一节**不联网、不建目录、不起 java** —— 那三件事是驱动层（`ServerInstallController`）
// 干的，归 mw_check。这一节盯的就是"取哪一份元数据 / 取回来怎么读 / 分成几步"这几件纯事。
//
// ★ 这里用的那几份 json 都是**手写的最小样本**，不是真回复 —— 结构照上游实测那个形状抄
//   （Paper 的 `downloads["server:default"]`、原版的 `downloads.server`），字段名错一个
//   这一节就红，正好是那个用处。
// ---------------------------------------------------------------------------
static void runServerInstallRunTests() {
    section("ZY. 服务端安装那四段：还差哪一份元数据 / 取回来怎么读（§6.2 / M4-2）");

    // ---------- ZY0. 哪一档这一轮接没接 ----------
    {
        check(!ServerInstallRun::flavorSupported(ServerInstall::Flavor::Spigot),
              "★★ ZY0 Spigot 这一轮**没接**（官方不发成品，要用 BuildTools 现编）");
        int supported = 0;
        bool invariant = true;
        for (const ServerInstall::Flavor flavor : ServerInstall::allFlavors()) {
            if (ServerInstallRun::flavorSupported(flavor)) {
                ++supported;
            }
            // ★ 两句话必须是**同一件事**：没接的档一定说得出为什么，接了的档一个字都不说。
            //   漂开的症状是"界面上写着暂不支持，可「创建」是能点的"。
            if (ServerInstallRun::unsupportedReason(flavor).isEmpty()
                == !ServerInstallRun::flavorSupported(flavor)) {
                invariant = false;
            }
        }
        check(supported == 7, "★ ZY0 八档里接了七档", QString::number(supported));
        check(invariant,
              "★★ ZY0 「接没接」和「有没有那句原因」永远是同一件事（两处判据不许漂开）");
        const QString reason =
            ServerInstallRun::unsupportedReason(ServerInstall::Flavor::Spigot);
        check(reason.contains(QStringLiteral("git")),
              "★ ZY0 那句话里点明了**为什么要本机装 git**（用户得知道卡在哪儿）", reason);
        check(!reason.contains(QStringLiteral("暂不支持")) ||
                  reason.contains(QStringLiteral("这一版还没接")),
              "ZY0 措辞是「这一版还没接」那种说法（不是「暂不支持」这种不交代原因的话）", reason);
    }

    // ---------- ZY1. 这一档还差哪一份元数据 ----------
    {
        const ServerInstall::Request vanilla = [] {
            ServerInstall::Request request;
            request.flavor = ServerInstall::Flavor::Vanilla;
            request.gameVersion = QStringLiteral("1.20.1");
            return request;
        }();
        const ServerInstall::Plan vanillaPlan = ServerInstall::planFor(vanilla);
        check(vanillaPlan.ok, "ZY1 原版这一档的计划本身是成立的", vanillaPlan.problem);
        const ServerInstallRun::Need vanillaNeed =
            ServerInstallRun::needFor(vanilla, vanillaPlan);
        check(vanillaNeed.kind == ServerInstallRun::Metadata::VersionJson,
              "★ ZY1 原版要的是那一份**版本 json**");
        check(vanillaNeed.url.isEmpty(),
              "★★ ZY1 版本 json 特意**不给地址**——先在盘上找（装过客户端就有），没有才联网");
        check(vanillaNeed.label.contains(QStringLiteral("原版")),
              "ZY1 那一步的名字说得出是干什么的", vanillaNeed.label);

        ServerInstall::Request paper = vanilla;
        paper.flavor = ServerInstall::Flavor::Paper;
        const ServerInstall::Plan paperPlan = ServerInstall::planFor(paper);
        check(paperPlan.ok, "ZY1 Paper 这一档的计划也是成立的", paperPlan.problem);
        const ServerInstallRun::Need paperNeed = ServerInstallRun::needFor(paper, paperPlan);
        check(paperNeed.kind == ServerInstallRun::Metadata::PaperBuilds,
              "★ ZY1 Paper 要的是**构建列表**");
        check(paperNeed.url == ServerInstall::paperBuildsUrl(QStringLiteral("1.20.1")),
              "★★ ZY1 那一条地址就是 `paperBuildsUrl()`（不在这儿另拼一遍）", paperNeed.url);

        // 剩下那五档的地址在 `planFor()` 里就拼好了 —— 一个请求都不用发。
        bool restQuiet = true;
        for (const ServerInstall::Flavor flavor :
             {ServerInstall::Flavor::Purpur, ServerInstall::Flavor::Fabric,
              ServerInstall::Flavor::Forge, ServerInstall::Flavor::NeoForge,
              ServerInstall::Flavor::Quilt}) {
            ServerInstall::Request request;
            request.flavor = flavor;
            request.gameVersion = QStringLiteral("1.20.1");
            request.loaderVersion = QStringLiteral("47.2.0");
            request.installerVersion = QStringLiteral("1.0.1");
            request.buildId = QStringLiteral("1234");
            const ServerInstall::Plan plan = ServerInstall::planFor(request);
            if (!plan.ok || ServerInstallRun::needFor(request, plan).ok()) {
                restQuiet = false;
                out() << "        （没安静下来的是 " << ServerInstall::flavorName(flavor) << "）\n";
            }
        }
        check(restQuiet,
              "★★ ZY1 另外五档一份元数据都不差（地址在计划里就拼好了 ⇒ 少一次往返）");

        const ServerInstall::Plan bad = ServerInstall::planFor(ServerInstall::Request{});
        check(!bad.ok && !ServerInstallRun::needFor(ServerInstall::Request{}, bad).ok(),
              "ZY1 计划本身不成立时，不问元数据（先把那句问题解决掉）");
    }

    // ---------- ZY2. 原版：版本 json 怎么读 ----------
    {
        ServerInstall::Request request;
        request.flavor = ServerInstall::Flavor::Vanilla;
        request.gameVersion = QStringLiteral("1.20.1");
        const ServerInstall::Plan plan = ServerInstall::planFor(request);

        const QByteArray versionJson = R"({
            "id": "1.20.1",
            "downloads": {
                "server": {
                    "sha1": "0d2b1e6b2b0e1f3b6dcb0a1f6b4a3d94d1f9a3b2",
                    "size": 51272711,
                    "url": "https://piston-data.mojang.com/v1/objects/0d2b…/server.jar"
                }
            }
        })";
        const ServerInstallRun::Fill fill =
            ServerInstallRun::fillDownloads(request, plan, versionJson);
        check(fill.ok, "ZY2 一份正常的版本 json 读得下来", fill.problem);
        check(fill.plan.downloads.size() == 1,
              "★ ZY2 填完正好一份要下的东西", QString::number(fill.plan.downloads.size()));
        if (fill.plan.downloads.size() == 1) {
            const ServerInstall::Download jar = fill.plan.downloads.first();
            check(jar.fileName == QStringLiteral("server.jar"),
                  "★★ ZY2 落地的名字是 `server.jar`（上游那个名字我们不用）", jar.fileName);
            check(jar.url.contains(QStringLiteral("piston-data.mojang.com")),
                  "ZY2 地址就是 json 里那一条", jar.url);
            check(jar.size == 51272711,
                  "★ ZY2 大小照抄（原版这条**有** size ⇒ 进度算得出来百分比）",
                  QString::number(jar.size));
        }
        check(fill.detail.isEmpty(),
              "ZY2 原版这一步没有小字要说（它没有「构建号」这种东西）");

        // 远古版本：官方压根没发过服务端。这不是"下载失败"，得说清楚。
        const ServerInstallRun::Fill ancient = ServerInstallRun::fillDownloads(
            request, plan, QByteArray("{\"id\":\"a1.1.2a\",\"downloads\":{}}"));
        check(!ancient.ok, "★★ ZY2 版本 json 里没有 `downloads.server` ⇒ 不成立");
        check(ancient.problem.contains(QStringLiteral("1.2.5")),
              "★★ ZY2 而且那句说的是「官方没发过」（不是「网络失败了」）—— 用户该做的是换个版本",
              ancient.problem);

        const ServerInstallRun::Fill garbage =
            ServerInstallRun::fillDownloads(request, plan, QByteArray("<html>404</html>"));
        check(!garbage.ok && garbage.problem.contains(QStringLiteral("json")),
              "★ ZY2 回来的不是 json ⇒ 说「读不懂」（别硬解）", garbage.problem);
    }

    // ---------- ZY3. Paper：构建列表怎么读 ----------
    {
        ServerInstall::Request request;
        request.flavor = ServerInstall::Flavor::Paper;
        request.gameVersion = QStringLiteral("1.21.4");
        // ★ 起手那一份计划里 `downloads` 是**空的**（地址里带着对象 sha256，拼不出来）。
        const ServerInstall::Plan plan = ServerInstall::planFor(request);
        check(plan.ok && plan.downloads.isEmpty(),
              "★ ZY3 Paper 起手那份计划就是要联网现查地址的那种");

        // 上游回的是**升序**（老的在前），而这里给的是"232 是 ALPHA、231 是 STABLE"。
        const QByteArray builds = R"([
            {"id": 231, "channel": "STABLE", "downloads": {"server:default": {
                "name": "paper-1.21.4-231.jar",
                "url": "https://api.papermc.io/v2/projects/paper/versions/1.21.4/builds/231/downloads/paper-1.21.4-231.jar",
                "checksums": {"sha256": "aaaa"}, "size": 49000000}}},
            {"id": 232, "channel": "ALPHA", "downloads": {"server:default": {
                "name": "paper-1.21.4-232.jar",
                "url": "https://api.papermc.io/v2/projects/paper/versions/1.21.4/builds/232/downloads/paper-1.21.4-232.jar",
                "checksums": {"sha256": "bbbb"}, "size": 49100000}}}
        ])";
        const ServerInstallRun::Fill fill =
            ServerInstallRun::fillDownloads(request, plan, builds);
        check(fill.ok, "ZY3 构建列表读得下来", fill.problem);
        check(fill.plan.downloads.size() == 1,
              "★★ ZY3 纸面上一共有两条构建，真正要下的是**一条**（挑出来的那一条）",
              QString::number(fill.plan.downloads.size()));
        if (fill.plan.downloads.size() == 1) {
            const ServerInstall::Download jar = fill.plan.downloads.first();
            check(jar.fileName == QStringLiteral("server.jar"),
                  "ZY3 落地名字照旧是 `server.jar`", jar.fileName);
            check(jar.url.contains(QStringLiteral("/builds/231/")),
                  "★★ ZY3 挑的是**稳定档**那一条（231），不是最新的那条 ALPHA", jar.url);
            check(jar.sha256 == QStringLiteral("aaaa"),
                  "★ ZY3 sha256 照抄（Paper 只给 sha256，没有 sha1）", jar.sha256);
        }
        check(fill.detail.contains(QStringLiteral("231")) &&
                  fill.detail.contains(QStringLiteral("稳定档")),
              "★★ ZY3 那一步收尾时的小字把**构建号**说出来（用户得知道装的是哪一条）",
              fill.detail);

        // 上游没标稳定档时：退回最新那条，但**必须说出来** —— 不然用户以为手上这个是稳定版。
        const QByteArray onlyAlpha = R"([
            {"id": 231, "channel": "ALPHA", "downloads": {"server:default": {
                "name": "paper-1.21.4-231.jar", "url": "https://example.invalid/231.jar",
                "checksums": {"sha256": "cccc"}, "size": 1}}},
            {"id": 232, "channel": "ALPHA", "downloads": {"server:default": {
                "name": "paper-1.21.4-232.jar", "url": "https://example.invalid/232.jar",
                "checksums": {"sha256": "dddd"}, "size": 1}}}
        ])";
        const ServerInstallRun::Fill alpha =
            ServerInstallRun::fillDownloads(request, plan, onlyAlpha);
        check(alpha.ok && alpha.plan.downloads.size() == 1 &&
                  alpha.plan.downloads.first().url.endsWith(QStringLiteral("232.jar")),
              "★★ ZY3 一条稳定档都没有 ⇒ 退回最新那条（不是「一条都下不了」）",
              alpha.problem);
        check(alpha.detail.contains(QStringLiteral("没标稳定档")),
              "★★ ZY3 而且那句小字**明说**这不是稳定档（用户不能以为手上这个是稳的）",
              alpha.detail);

        const ServerInstallRun::Fill none =
            ServerInstallRun::fillDownloads(request, plan, QByteArray("[]"));
        check(!none.ok && none.problem.contains(QStringLiteral("没给这个游戏版本发过构建")),
              "★ ZY3 空列表 ⇒ 明说「这个版本没有构建」（换个版本，不是重试）", none.problem);

        const ServerInstallRun::Fill wrongShape =
            ServerInstallRun::fillDownloads(request, plan, QByteArray("{\"a\":1}"));
        check(!wrongShape.ok, "ZY3 回来的不是数组 ⇒ 不成立", wrongShape.problem);
    }

    // ---------- ZY4. 其余那几档：地址已经拼好了，一个字节都不用读 ----------
    {
        for (const ServerInstall::Flavor flavor :
             {ServerInstall::Flavor::Purpur, ServerInstall::Flavor::Fabric,
              ServerInstall::Flavor::Forge, ServerInstall::Flavor::NeoForge,
              ServerInstall::Flavor::Quilt}) {
            ServerInstall::Request request;
            request.flavor = flavor;
            request.gameVersion = QStringLiteral("1.20.1");
            request.loaderVersion = QStringLiteral("47.2.0");
            request.installerVersion = QStringLiteral("1.0.1");
            const ServerInstall::Plan plan = ServerInstall::planFor(request);
            if (!plan.ok) {
                check(false, "ZY4 这一档的计划该是成立的", ServerInstall::flavorName(flavor));
                continue;
            }
            // 喂一份**垃圾**进去：这一档根本不该读它。
            const ServerInstallRun::Fill fill = ServerInstallRun::fillDownloads(
                request, plan, QByteArray("<html>这不是 json</html>"));
            // 逐项比（`Download` 没有 `operator==`）：条数一样、每一条的地址和落地名字都一样。
            bool same = fill.ok && fill.plan.downloads.size() == plan.downloads.size();
            for (int i = 0; same && i < plan.downloads.size(); ++i) {
                same = fill.plan.downloads.at(i).url == plan.downloads.at(i).url
                       && fill.plan.downloads.at(i).fileName
                              == plan.downloads.at(i).fileName;
            }
            check(same,
                  "★★ ZY4 计划里地址齐了的档：喂什么进来都原样出去（一个字节都不读）",
                  ServerInstall::flavorName(flavor));
        }
    }

    // ---------- ZY5 / ZY6. 跑安装器那条命令行 ----------
    {
        ServerInstall::Request forge;
        forge.flavor = ServerInstall::Flavor::Forge;
        forge.gameVersion = QStringLiteral("1.20.1");
        forge.loaderVersion = QStringLiteral("47.2.0");
        const ServerInstall::Plan forgePlan = ServerInstall::planFor(forge);
        check(forgePlan.ok, "ZY5 Forge 这份计划成立", forgePlan.problem);

        const QString jarName = ServerInstallRun::installerJarName(forgePlan);
        check(!jarName.isEmpty(), "★★ ZY5 Forge 要跑安装器（判据 = 计划里给没给工具参数）");
        check(jarName == forgePlan.downloads.first().fileName,
              "★ ZY5 要跑的就是计划里下下来的**第一份**", jarName);

        const QStringList command =
            ServerInstallRun::toolCommand(forgePlan, QStringLiteral("C:/srv/") + jarName);
        check(command.size() == 2 + forgePlan.toolArguments.size(),
              "★ ZY5 命令行 = `-jar` + jar 路径 + 计划里那些参数", command.join(QLatin1Char(' ')));
        check(command.size() >= 2 && command.at(0) == QStringLiteral("-jar") &&
                  command.at(1).endsWith(jarName),
              "★★ ZY5 头两个是 `-jar <那个 jar 的**完整路径**>`（相对路径起不来）",
              command.join(QLatin1Char(' ')));
        check(command.contains(QStringLiteral("--installServer")),
              "★ ZY5 Forge 那几条参数原样接在后面", command.join(QLatin1Char(' ')));
        check(ServerInstallRun::toolCommand(forgePlan, QString()).isEmpty(),
              "★ ZY5 没给 jar 路径 ⇒ 空命令行（调用方不用再判一次）");

        // 不跑安装器的那几档：`installerJarName()` 得回空。
        bool quiet = true;
        for (const ServerInstall::Flavor flavor :
             {ServerInstall::Flavor::Vanilla, ServerInstall::Flavor::Paper,
              ServerInstall::Flavor::Purpur, ServerInstall::Flavor::Fabric}) {
            ServerInstall::Request request;
            request.flavor = flavor;
            request.gameVersion = QStringLiteral("1.20.1");
            request.loaderVersion = QStringLiteral("0.15.0");
            request.installerVersion = QStringLiteral("1.0.1");
            const ServerInstall::Plan plan = ServerInstall::planFor(request);
            if (!ServerInstallRun::installerJarName(plan).isEmpty()) {
                quiet = false;
                out() << "        （多说话的是 " << ServerInstall::flavorName(flavor) << "）\n";
            }
        }
        check(quiet,
              "★ ZY6 下下来就是服务端的那几档：不跑安装器（这几档起手就该直接核对）");

        // ★ 这一条是那一层自己的不变式：判据是"有没有工具参数"，不是"是哪一档"。
        bool sameYesNo = true;
        for (const ServerInstall::Flavor flavor : ServerInstall::allFlavors()) {
            ServerInstall::Request request;
            request.flavor = flavor;
            request.gameVersion = QStringLiteral("1.20.1");
            request.loaderVersion = QStringLiteral("47.2.0");
            request.installerVersion = QStringLiteral("1.0.1");
            request.buildId = QStringLiteral("231");
            const ServerInstall::Plan plan = ServerInstall::planFor(request);
            if (ServerInstallRun::installerJarName(plan).isEmpty()
                != plan.toolArguments.isEmpty()) {
                sameYesNo = false;
            }
        }
        check(sameYesNo,
              "★★ ZY6 「要不要跑安装器」和「有没有工具参数」永远是同一件事（八档全过一遍）");
    }

    // ---------- ZY7. 这件事分成几步 ----------
    {
        ServerInstall::Request vanilla;
        vanilla.flavor = ServerInstall::Flavor::Vanilla;
        vanilla.gameVersion = QStringLiteral("1.20.1");
        const ServerInstall::Plan vanillaPlan = ServerInstall::planFor(vanilla);
        // 起手那一份（元数据还没取回来）：两步 —— 去要那一份 + 最后核对。
        const QStringList startSteps = ServerInstallRun::stepNames(vanilla, vanillaPlan);
        check(startSteps.size() == 2 && startSteps.first().contains(QStringLiteral("原版")),
              "★★ ZY7 原版起手先摆两步（去要版本信息 + 核对）", startSteps.join(QLatin1Char('|')));
        check(startSteps.last() == QStringLiteral("核对装好了没有"),
              "★★ ZY7 最后一步永远是「核对装好了没有」—— 它是「不留半成品」那句话的落点",
              startSteps.last());

        // 元数据取回来之后：三步（多出那条下载）。
        const QByteArray versionJson =
            R"({"downloads":{"server":{"url":"https://example.invalid/server.jar","sha1":"","size":1}}})";
        const ServerInstallRun::Fill filled =
            ServerInstallRun::fillDownloads(vanilla, vanillaPlan, versionJson);
        check(filled.ok, "ZY7 前置：那一份填好了", filled.problem);
        const QStringList steps = ServerInstallRun::stepNames(vanilla, filled.plan);
        check(steps.size() == 3, "★ ZY7 填完之后多出那条下载（一共三步）",
              steps.join(QLatin1Char('|')));
        bool named = !steps.isEmpty();
        for (const QString &step : steps) {
            if (step.trimmed().isEmpty()) {
                named = false;
            }
        }
        check(named, "★ ZY7 每一格都有名字（任务中心那一行不能是空的）");

        ServerInstall::Request forge;
        forge.flavor = ServerInstall::Flavor::Forge;
        forge.gameVersion = QStringLiteral("1.20.1");
        forge.loaderVersion = QStringLiteral("47.2.0");
        const ServerInstall::Plan forgePlan = ServerInstall::planFor(forge);
        const QStringList forgeSteps = ServerInstallRun::stepNames(forge, forgePlan);
        check(forgeSteps.contains(QStringLiteral("跑安装器")),
              "★★ ZY7 要跑安装器的档多一格「跑安装器」（用户得看得见机器在干活）",
              forgeSteps.join(QLatin1Char('|')));
        check(forgeSteps.indexOf(QStringLiteral("跑安装器")) == forgeSteps.size() - 2,
              "★ ZY7 它在核对那一步**前面**（顺序：下载 → 跑安装器 → 核对）",
              forgeSteps.join(QLatin1Char('|')));

        // Paper 起手那一份：元数据 + 核对，两步（地址还不知道，下载那几格也还不知道）。
        ServerInstall::Request paper;
        paper.flavor = ServerInstall::Flavor::Paper;
        paper.gameVersion = QStringLiteral("1.21.4");
        const QStringList paperSteps =
            ServerInstallRun::stepNames(paper, ServerInstall::planFor(paper));
        check(paperSteps.size() == 2 && paperSteps.first().contains(QStringLiteral("Paper")),
              "★ ZY7 Paper 起手也是两步（先问构建列表）", paperSteps.join(QLatin1Char('|')));
    }
}

// ---------------------------------------------------------------------------
// ZZ. 服务端「跑起来 / 停下来」那一层的**判据层**（coding plan §6.2 的操作 + §6.3 的停止时序 /
//     里程碑 M4-3）
//
// `ServerRun.hpp` 和 `ServerInstallRun.hpp` 同一个形状：纯头、全 inline、不联网、不起进程、
// 不看时钟 —— 喂几个数进来、回一个结论出去。所以这一节能把它整片钉死。真的 `QProcess` /
// `QTimer`（`ServerProcess`）在 mw_check 的 T41，那儿拿本工程自己的 exe 当"服务端"跑整趟。
//
// ★ 这一层里最要紧的一条是 **内存那几项插在第几位**（`Plan::launchJvmArgsIndex`）：
//   `ServerInstall.hpp` 里原来的注释把方向说反了（"接在这几个 token **后面**"），照着实现
//   出来是 `java @user_jvm_args.txt @…/win_args.txt nogui -Xmx4G` —— 那张 win_args.txt
//   **自带主类**，`-Xmx` 落在它后面会被 java 当成给服务端的**程序参数**，一个字都不生效、
//   也不报错（界面上那根内存滑杆成了摆设）。所以 ZZ0 里那几条不是在测"顺序对不对"，是在
//   钉死"那个坑不会再回来"。
// ---------------------------------------------------------------------------
static void runServerRunTests() {
    section("ZZ. 服务端跑起来 / 停下来：命令怎么拼、起来没有、宽限多久（§6.2 / §6.3 / M4-3）");

    // ---------- ZZ0. 那条启动命令怎么拼 ----------
    {
        ServerInstall::Request vanillaReq;
        vanillaReq.flavor = ServerInstall::Flavor::Vanilla;
        vanillaReq.gameVersion = QStringLiteral("1.20.1");
        const ServerInstall::Plan vanilla = ServerInstall::planFor(vanillaReq);
        check(vanilla.ok && !vanilla.launchTokens.isEmpty(), "★★ ZZ0 前置：原版那份计划是好的",
              vanilla.problem);

        // 带内存：接在最前面（原版这一档的 index 是 0）。
        const QStringList withMem = ServerRun::launchArguments(vanilla, 4096);
        check(withMem.size() == vanilla.launchTokens.size() + 1,
              "★ ZZ0 内存那一项只**多出一个** token（没把原来的抄一遍也没丢）",
              withMem.join(QLatin1Char(' ')));
        check(withMem.value(0) == QStringLiteral("-Xmx4096m"),
              "★★ ZZ0 `-Xmx` 接在最前面（index 0 那一档）", withMem.join(QLatin1Char(' ')));
        check(withMem.mid(1) == vanilla.launchTokens,
              "★ ZZ0 原来那串 token 原样跟在后面、一个不差", withMem.join(QLatin1Char(' ')));

        // ★ `<= 0` 就一项都不发（"不限制"是 java 的默认档；编一个数出来比不发更危险 ——
        //   同实例设置那条老规矩）。
        for (const int memory : {0, -1, -4096}) {
            const QStringList none = ServerRun::launchArguments(vanilla, memory);
            bool hasXmx = false;
            for (const QString &token : none) {
                if (token.contains(QStringLiteral("-Xmx"))) {
                    hasXmx = true;
                }
            }
            check(!hasXmx && none == vanilla.launchTokens,
                  QStringLiteral("★★ ZZ0 内存 %1 ⇒ 一个 `-Xmx` 都不发（原封不动）").arg(memory),
                  none.join(QLatin1Char(' ')));
        }

        // 别的 JVM 参数排在内存那几项**后面**，但仍然在同一个插入位置上。
        const QStringList extra = ServerRun::launchArguments(
            vanilla, 2048, QStringList{QStringLiteral("-XX:+UseG1GC")});
        check(extra.size() == vanilla.launchTokens.size() + 2
                  && extra.value(0) == QStringLiteral("-Xmx2048m")
                  && extra.value(1) == QStringLiteral("-XX:+UseG1GC"),
              "★★ ZZ0 额外的 JVM 参数排在内存那几项后面", extra.join(QLatin1Char(' ')));

        // 只给了别的参数、没给内存：那就只插它一个。
        const QStringList onlyExtra = ServerRun::launchArguments(
            vanilla, 0, QStringList{QStringLiteral("-XX:+UseG1GC")});
        check(onlyExtra.value(0) == QStringLiteral("-XX:+UseG1GC")
                  && onlyExtra.mid(1) == vanilla.launchTokens,
              "★ ZZ0 没给内存 ⇒ 只有额外那一项被插进来", onlyExtra.join(QLatin1Char(' ')));

        // 插在越界的那一位上：钳到两头，token 一个都不许丢。
        ServerInstall::Plan past = vanilla;
        past.launchJvmArgsIndex = 99;
        const QStringList tail = ServerRun::launchArguments(past, 1024);
        check(tail.size() == past.launchTokens.size() + 1
                  && tail.last() == QStringLiteral("-Xmx1024m"),
              "★ ZZ0 给的位子过了头 ⇒ 钳到最后一位（不丢 token）", tail.join(QLatin1Char(' ')));
        past.launchJvmArgsIndex = -7;
        const QStringList head = ServerRun::launchArguments(past, 1024);
        check(head.value(0) == QStringLiteral("-Xmx1024m"),
              "★ ZZ0 给的位子是负数 ⇒ 钳到最前面", head.join(QLatin1Char(' ')));
    }

    // ---------- ZZ0b. ★ Forge / NeoForge：内存必须夹在两张参数文件中间 ----------
    {
        ServerInstall::Request forgeReq;
        forgeReq.flavor = ServerInstall::Flavor::Forge;
        forgeReq.gameVersion = QStringLiteral("1.20.1");
        forgeReq.loaderVersion = QStringLiteral("47.2.0");
        const ServerInstall::Plan forge = ServerInstall::planFor(forgeReq);
        check(forge.ok, "ZZ0b 前置：Forge 那份计划是好的", forge.problem);

        ServerInstall::Request neoReq;
        neoReq.flavor = ServerInstall::Flavor::NeoForge;
        neoReq.gameVersion = QStringLiteral("1.20.1");
        neoReq.loaderVersion = QStringLiteral("20.4.237");
        const ServerInstall::Plan neo = ServerInstall::planFor(neoReq);
        check(neo.ok, "ZZ0b 前置：NeoForge 那份计划是好的", neo.problem);

        for (const ServerInstall::Plan &plan : {forge, neo}) {
            const QString name = ServerInstall::flavorName(plan.flavor);
            const QStringList args = ServerRun::launchArguments(plan, 4096);
            const QString joined = args.join(QLatin1Char(' '));

            check(args.size() == 4, QStringLiteral("★ ZZ0b %1 四个 token").arg(name), joined);
            check(args.value(0) == QStringLiteral("@user_jvm_args.txt"),
                  QStringLiteral("★★ ZZ0b %1 第一位是那张写着默认内存的参数文件").arg(name),
                  joined);

            const int memAt = args.indexOf(QStringLiteral("-Xmx4096m"));
            int mainAt = -1;  // 自带主类的那一张（`@…/win_args.txt`）
            for (int i = 0; i < args.size(); ++i) {
                if (args.at(i).startsWith(QLatin1Char('@'))
                    && args.at(i).endsWith(QStringLiteral("win_args.txt"))) {
                    mainAt = i;
                }
            }
            const int noguiAt = args.indexOf(QStringLiteral("nogui"));

            check(memAt == 1, QStringLiteral("★★ ZZ0b %1 `-Xmx` 在第二位（两张文件中间）").arg(name),
                  joined);
            check(mainAt == 2 && noguiAt == 3,
                  QStringLiteral("★★ ZZ0b %1 自带主类那张在 `-Xmx` **之后**").arg(name), joined);
            // ★ 这一条就是那个坑本身：`-Xmx` 一旦跑到主类后面，它就成了"给服务端的参数"。
            check(memAt >= 0 && mainAt >= 0 && memAt < mainAt,
                  QStringLiteral("★★ ZZ0b %1 `-Xmx` 不许落在主类后面（落了就等于没发）")
                      .arg(name),
                  joined);
        }
    }

    // ---------- ZZ0c. 七档都过一遍：那个"插第几位"的表不许漂 ----------
    {
        struct Sample {
            ServerInstall::Request request;
            int expectIndex;
        };
        QList<Sample> samples;
        auto add = [&samples](ServerInstall::Flavor flavor, const QString &game,
                              const QString &loader, const QString &installer, int expectIndex) {
            ServerInstall::Request req;
            req.flavor = flavor;
            req.gameVersion = game;
            req.loaderVersion = loader;
            req.installerVersion = installer;
            samples.append(Sample{req, expectIndex});
        };
        add(ServerInstall::Flavor::Vanilla, QStringLiteral("1.20.1"), QString(), QString(), 0);
        add(ServerInstall::Flavor::Paper, QStringLiteral("1.21.4"), QString(), QString(), 0);
        add(ServerInstall::Flavor::Purpur, QStringLiteral("1.21.4"), QString(), QString(), 0);
        add(ServerInstall::Flavor::Fabric, QStringLiteral("1.20.1"), QStringLiteral("0.15.0"),
            QStringLiteral("1.0.1"), 0);
        add(ServerInstall::Flavor::Forge, QStringLiteral("1.20.1"), QStringLiteral("47.2.0"),
            QString(), 1);
        add(ServerInstall::Flavor::NeoForge, QStringLiteral("1.20.1"), QStringLiteral("20.4.237"),
            QString(), 1);
        add(ServerInstall::Flavor::Quilt, QStringLiteral("1.20.1"), QString(), QStringLiteral("0.9.0"),
            0);

        int ok = 0;
        bool indicesOk = true;
        bool atOk = true;
        bool sizeOk = true;
        for (const Sample &sample : samples) {
            const ServerInstall::Plan plan = ServerInstall::planFor(sample.request);
            if (!plan.ok) {
                continue;
            }
            ++ok;
            if (plan.launchJvmArgsIndex != sample.expectIndex) {
                indicesOk = false;
            }
            // ★ 两张 `@` 参数文件是 Forge / NeoForge 那两档的记号：有它俩的档 index 必须是 1，
            //   没有的必须是 0。这条把"表"和"token 的形状"绑在一起 —— 将来加一档忘了填
            //   这一格，这儿就红。
            const bool hasArgFiles =
                !plan.launchTokens.isEmpty() && plan.launchTokens.first().startsWith(QLatin1Char('@'));
            if (hasArgFiles != (plan.launchJvmArgsIndex == 1)) {
                atOk = false;
            }
            if (ServerRun::launchArguments(plan, 2048).size() != plan.launchTokens.size() + 1) {
                sizeOk = false;
            }
        }
        check(ok == samples.size(), "★ ZZ0c 前置：七档的计划全都拼出来了（Spigot 不在里面）",
              QStringLiteral("%1/%2").arg(ok).arg(samples.size()));
        check(indicesOk, "★★ ZZ0c 每一档的 `launchJvmArgsIndex` 都对（0 一堆，Forge/NeoForge 是 1）");
        check(atOk, "★★ ZZ0c 「两张 `@` 参数文件」和「index 是 1」永远是同一件事");
        check(sizeOk, "★ ZZ0c 七档都只多出一个 `-Xmx` token");
    }

    // ---------- ZZ1. 让它停下来那一句 / 「起来了吗」 ----------
    {
        const QByteArray stop = ServerRun::stopCommandBytes();
        check(stop == QByteArrayLiteral("stop\n"), "★★ ZZ1 正常停 = 写一行 `stop`", QString::fromLatin1(stop));
        check(stop.endsWith('\n'), "★★ ZZ1 末尾那个换行**不能少**（不带回车它读到 EOF 才动）");
        check(!stop.contains('\r'), "★ ZZ1 没有多余的回车（服务端那边是按行读的）");

        bool readyAll = true;
        for (const char *line :
             {"Done (12.345s)! For help, type \"help\"",
              "[12:00:00] [Server thread/INFO]: Done (1.234s)! For help, type \"help\"",
              "[Server thread/INFO]: Done (0.001s)!"}) {
            if (!ServerRun::isReadyLine(QString::fromLatin1(line))) {
                readyAll = false;
            }
        }
        check(readyAll, "★★ ZZ1 五档都那一种 `Done (…)` 认得出来（原版/Paper/Fabric/Forge/Neo）");

        bool notReady = true;
        for (const char *line :
             {"Done loading 512 recipes",
              "[Server thread/INFO]: Preparing level \"world\"",
              "Done",
              "",
              "Starting minecraft server version 1.20.1"}) {
            if (ServerRun::isReadyLine(QString::fromLatin1(line))) {
                notReady = false;
            }
        }
        check(notReady, "★★ ZZ1 别的句子一个都不许混进来（尤其那句光秃秃的 Done）");
    }

    // ---------- ZZ2. 退了之后算哪一档 ----------
    {
        check(ServerRun::statusAfterExit(0, true) == ServerModel::Status::Stopped,
              "★★ ZZ2 退出码 0 ⇒ 已停止（我们发的 stop 生效了）");
        check(ServerRun::statusAfterExit(0, false) == ServerModel::Status::Stopped,
              "★★ ZZ2 还没说停它就 0 退出了，也算已停止（eula 没同意 / 端口被占就走这条，"
              "报成「异常退出」等于让用户去查一个不存在的崩溃）");
        check(ServerRun::statusAfterExit(1, false) == ServerModel::Status::Crashed,
              "★★ ZZ2 非 0 ⇒ 异常退出");
        check(ServerRun::statusAfterExit(1, true) == ServerModel::Status::Crashed,
              "★★ ZZ2 我们叫它停、它却非 0 退出 ⇒ 仍然是异常退出");
        check(ServerRun::statusAfterExit(-1, false) == ServerModel::Status::Crashed,
              "★ ZZ2 `FailedToStart` 那一路（−1）也算异常退出");
    }

    // ---------- ZZ3. 宽限多久才允许强杀（那张表的唯一出处） ----------
    {
        constexpr qint64 kGiB = 1024LL * 1024LL * 1024LL;
        check(ServerRun::gracefulStopMs(0, 0) == 15'000,
              "★★ ZZ3 空目录空存档 = 起手 15 秒", QString::number(ServerRun::gracefulStopMs(0, 0)));

        check(ServerRun::gracefulStopSeconds(0, 0) == 15, "★ ZZ3 秒数就是毫秒除以 1000");

        // 模组那一头：每 32 个 +5 秒。
        check(ServerRun::gracefulStopSeconds(32, 0) == 20, "★★ ZZ3 32 个模组 ⇒ 20 秒",
              QString::number(ServerRun::gracefulStopSeconds(32, 0)));
        check(ServerRun::gracefulStopSeconds(64, 0) == 25, "★ ZZ3 64 个模组 ⇒ 25 秒",
              QString::number(ServerRun::gracefulStopSeconds(64, 0)));
        check(ServerRun::gracefulStopSeconds(31, 0) == 15,
              "★ ZZ3 不到一步的不算（31 个还是 15 秒 —— 别四舍五入到 20）");
        // 封顶 +45 秒。
        check(ServerRun::gracefulStopSeconds(100'000, 0) == 60,
              "★★ ZZ3 几百个模组也只加到封顶那一档（15 + 45 = 60 秒）",
              QString::number(ServerRun::gracefulStopSeconds(100'000, 0)));

        // 存档那一头：每 1 GiB +5 秒，不足 1 GiB 也算一步。
        check(ServerRun::gracefulStopSeconds(0, kGiB) == 20, "★★ ZZ3 1 GiB 存档 ⇒ 20 秒",
              QString::number(ServerRun::gracefulStopSeconds(0, kGiB)));
        check(ServerRun::gracefulStopSeconds(0, 1) == 20,
              "★★ ZZ3 空世界但只要**有**这个世界也按一步算（1 字节和 1 GiB 同级？—— 这里"
              "刻意如此：目录在就说明有东西要存）",
              QString::number(ServerRun::gracefulStopSeconds(0, 1)));
        check(ServerRun::gracefulStopSeconds(0, kGiB / 2) == 20,
              "★ ZZ3 半个 GiB 也算一步（不然 0.9 GiB 和一个空目录一个待遇）");
        check(ServerRun::gracefulStopSeconds(0, 2 * kGiB) == 25, "★ ZZ3 2 GiB ⇒ 25 秒");
        // 封顶 +60 秒。
        check(ServerRun::gracefulStopSeconds(0, 20 * kGiB) == 75,
              "★★ ZZ3 20 GiB 也只加到封顶那一档（15 + 60 = 75 秒）",
              QString::number(ServerRun::gracefulStopSeconds(0, 20 * kGiB)));

        // 两头都拉满 ⇒ 总上限 120 秒。
        check(ServerRun::gracefulStopSeconds(100'000, 50 * kGiB) == 120,
              "★★ ZZ3 两头都拉满 ⇒ 总上限 120 秒",
              QString::number(ServerRun::gracefulStopSeconds(100'000, 50 * kGiB)));

        // ★ 两个方向的单调：东西越多只会等得越久，不会反而更短。
        bool monotone = true;
        int prevMods = 0;
        int prevWorld = 0;
        for (const int mods : {0, 1, 31, 32, 100, 500, 5000}) {
            const int ms = ServerRun::gracefulStopMs(mods, 0);
            if (ms < prevMods) {
                monotone = false;
            }
            prevMods = ms;
        }
        for (const qint64 bytes : {0LL, 1LL, kGiB, 5 * kGiB, 100 * kGiB}) {
            const int ms = ServerRun::gracefulStopMs(0, bytes);
            if (ms < prevWorld) {
                monotone = false;
            }
            prevWorld = ms;
        }
        check(monotone, "★★ ZZ3 模组更多 / 存档更大 ⇒ 等的时间只增不减");
        check(ServerRun::gracefulStopMs(-3, -7) == 15'000,
              "★ ZZ3 负数（读不出来 / 没扫到）按 0 走，不是「扣掉 5 秒」");
    }

    // ---------- ZZ4. 给用户看的那几句 ----------
    {
        const QString stopping = ServerRun::stoppingNote(20);
        check(stopping.contains(QStringLiteral("20")), "★★ ZZ4 「停止中」那句把秒数写出来", stopping);
        const QString force = ServerRun::forceKillNote(20);
        check(force.contains(QStringLiteral("20")) && force.contains(QStringLiteral("存档")),
              "★★ ZZ4 「可以强制结束了」那句把秒数写出来，并且**说清楚代价**（可能丢存档）", force);

        const QString missing = ServerRun::notInstalledMessage();
        check(!missing.isEmpty() && missing.contains(QStringLiteral("修复")),
              "★★ ZZ4 没装好那句指向「修复」那一颗（不能只说「装不了」）", missing);

        check(ServerRun::eulaUrl() == QStringLiteral("https://aka.ms/MinecraftEULA"),
              "★★ ZZ4 EULA 原文地址（可点那一行的落点）", ServerRun::eulaUrl());
        check(ServerRun::eulaUrl().startsWith(QStringLiteral("https://")),
              "★ ZZ4 是 https —— 用户点开之前那一行得能看出这是外链");
        check(!ServerRun::eulaLinkText().isEmpty()
                  && ServerRun::eulaLinkText().contains(QStringLiteral("许可协议"))
                  && ServerRun::eulaLinkText().contains(QStringLiteral("打开")),
              "★★ ZZ4 那一行可点链接的文字（用户 2026-10-13 点名要的）—— 是一句「打开…」，"
              "不是一个光秃秃的网址",
              ServerRun::eulaLinkText());

        check(ServerRun::eulaCheckBoxText().contains(QStringLiteral("我已经读过并同意")),
              "★★ ZZ4 勾选框那句是**第一人称的声明**（「我读过并同意」），不是「本协议没问题」",
              ServerRun::eulaCheckBoxText());

        const QString text = ServerRun::eulaPromptText();
        check(text.contains(QStringLiteral("eula=true")),
              "★★ ZZ4 EULA 那道闸说清楚它到底会写什么", text);
        check(text.contains(QStringLiteral("不会替你同意")),
              "★★ ZZ4 而且说清楚**不自动接受**（coding plan §6.4 明写不做）", text);
        check(!ServerRun::eulaPromptTitle().isEmpty(), "★ ZZ4 那道闸有标题");

        for (const QString &s : {ServerRun::eulaPromptTitle(), ServerRun::eulaPromptText(),
                                 ServerRun::eulaCheckBoxText(), ServerRun::eulaLinkText(),
                                 ServerRun::notInstalledMessage(), stopping, force}) {
            if (s.trimmed().isEmpty()) {
                check(false, "★★ ZZ4 这几句话一句都不许是空的");
            }
        }
    }

    // ---------- ZZ5. 管道里的字节怎么切成行（★ 一个多字节字符被劈成两半的那一路） ----------
    //
    // 2026-10-13 修的真 bug：`drainOutput()` 原来拿到一截就整块 `fromLocal8Bit`，
    // 一个三字节的汉字正好落在两次 `readyRead` 中间时，前后各解出半个 ⇒ 拼回来是乱码，
    // mw_check 的 T41.3（"回声回来了没有"）就**时红时绿**（纯 ASCII 那几条一直绿，所以之前
    // 没露头）。这一节把它钉成确定性的：喂字节、自己控制从哪儿切断。
    {
        // --- 一趟能凑几行：切出完整的行、剩下半行留到下趟 ---
        {
            QByteArray pending;
            const QStringList first = ServerRun::takeLines(pending, QByteArrayLiteral("a\nb\ncc"));
            check(first == QStringList{QStringLiteral("a"), QStringLiteral("b")},
                  "★★ ZZ5 一趟到手三行里有两整行 + 半行 ⇒ 只报那两条", first.join(QLatin1Char('|')));
            check(pending == QByteArrayLiteral("cc"),
                  "★★ ZZ5 那半行**原样**留在攒着的那截里（不是丢掉也不是先解码）",
                  QString::fromLatin1(pending));

            const QStringList second = ServerRun::takeLines(pending, QByteArrayLiteral("c\nd\n"));
            check(second == QStringList{QStringLiteral("ccc"), QStringLiteral("d")},
                  "★★ ZZ5 攒着的那截和这一趟的头一个字**拼**成一行（跨趟拼行是常态，不是边角）",
                  second.join(QLatin1Char('|')));
            check(pending.isEmpty(), "★ ZZ5 吃干净之后攒着的那截要空（不然下次会重复报）");
        }

        // --- ★★ 多字节字符被切断：这是原来那版会红的那一路 ---
        {
            const QString text = QStringLiteral("[12:00:02] [Server thread/INFO]: [回声] say 你好");
            const QByteArray whole = text.toUtf8() + QByteArrayLiteral("\n");

            // 切在最后那个「好」三个字节的中间（末尾 `\n` 之前第 2 个字节上）。
            const int cutAt = whole.size() - 2;
            const auto byteAt = [](const QByteArray &b, int i) {
                return static_cast<unsigned char>(b.at(i));
            };
            // 前置：切点那个字节是 UTF-8 的**后续字节**（0x80~0xBF）—— 后续字节不可能是一个
            // 字符的开头，所以"切点落在它身上"就等于"这一刀切进了一个多字节字符里"。
            check(byteAt(whole, cutAt) >= 0x80 && byteAt(whole, cutAt) <= 0xBF,
                  "★★ ZZ5 前置：这一刀真的切在一个多字节字符**中间**（切点是个后续字节）");

            QByteArray pending;
            const QStringList half = ServerRun::takeLines(pending, whole.left(cutAt));
            check(half.isEmpty(),
                  "★★ ZZ5 切在字符中间时**一行都不许报**（原来那版会在这儿解出两个乱码、"
                  "当成一整行报上去 —— T41.3 时红时绿就是它）",
                  half.join(QLatin1Char('|')));

            const QStringList rest = ServerRun::takeLines(pending, whole.mid(cutAt));
            check(rest.size() == 1 && rest.first() == text,
                  "★★ ZZ5 后半截一到手，拼出来的是**原来那句话**（一个字符都不差）",
                  rest.join(QLatin1Char('|')));
            check(pending.isEmpty(), "★ ZZ5 拼完又吃干净了");
        }

        // --- 一字节一字节地喂（最坏情况：每次 readyRead 只来一个字节） ---
        {
            const QString text = QStringLiteral("中文 漂 亮 🎉");  // 3 字节 ×3 + 4 字节（emoji）
            const QByteArray whole = text.toUtf8() + QByteArrayLiteral("\n");
            QByteArray pending;
            QStringList got;
            for (int i = 0; i < whole.size(); ++i) {
                got += ServerRun::takeLines(pending, whole.mid(i, 1));
            }
            check(got.size() == 1 && got.first() == text,
                  "★★ ZZ5 一个字节一个字节喂（最碎的那种分包）也只出**一行**、内容不变",
                  got.join(QLatin1Char('|')));
            check(pending.isEmpty(), "★ ZZ5 碎喂之后也不该剩下东西");
        }

        // --- 两种行尾：`\n` 是真行尾，`\r` 是它重画进度那一行自己回的 ---
        {
            QByteArray pending;
            const QStringList crlf = ServerRun::takeLines(
                pending, QByteArrayLiteral("x\r\ny\r\n"));
            check(crlf == QStringList{QStringLiteral("x"), QStringLiteral("y")},
                  "★★ ZZ5 `\\r\\n`（Windows 那套）切成两行，**不许**多出一个空行"
                  "（行数一对不上，下游数行数的判据全跟着漂）",
                  crlf.join(QLatin1Char('|')));
            check(pending.isEmpty(), "★ ZZ5 CRLF 也吃干净");

            const QStringList cr = ServerRun::takeLines(
                pending, QByteArrayLiteral("...10%\r...30%\r"));
            check(cr == QStringList{QStringLiteral("...10%"), QStringLiteral("...30%")},
                  "★★ ZZ5 单独一个 `\\r`（进度条重画）也当行尾切 —— 不切的话会挂成一长条",
                  cr.join(QLatin1Char('|')));

            const QStringList blanks = ServerRun::takeLines(pending, QByteArrayLiteral("\n\n"));
            check(blanks.isEmpty(), "★★ ZZ5 空行不回来（服务端自己会打空行）",
                  blanks.join(QLatin1Char('|')));
            check(pending.isEmpty(), "★ ZZ5 空行也吃干净");
        }

        // --- 攒着的那截在"没等到行尾"时不许自己长大之后又被当成一行 ---
        {
            QByteArray pending;
            ServerRun::takeLines(pending, QByteArrayLiteral("no newline yet"));
            check(pending == QByteArrayLiteral("no newline yet"),
                  "★ ZZ5 迟迟没有行尾 ⇒ 全攒着（一个字都不丢）", QString::fromLatin1(pending));
            const QStringList done = ServerRun::takeLines(pending, QByteArrayLiteral("\n"));
            check(done.size() == 1 && done.first() == QStringLiteral("no newline yet"),
                  "★ ZZ5 行尾终于到了 ⇒ 攒着的那些一次性成行", done.join(QLatin1Char('|')));
        }
    }
}

// ---------------------------------------------------------------------------
// ZV. 「服务端设置」那两层判据（coding plan §6.3 / 里程碑 M4-4）
//
// 这一页上有四样东西，其中三样背后各有一层**纯判据**：
//   · `ServerPropertiesForm`（哪几项、值域多少、收不收、合回文件）—— 见 ZV0 ~ ZV4；
//   · `ServerCheck`（体检报哪几条、按什么次序、每一条的出路是什么记号）—— 见 ZV5 ~ ZV6；
//   · `ServerPortCheck`（"这个端口有人占着吗"）—— 见 ZV7（**这一条要真占一次**，不联网）。
//
// ★ 这一节里最要紧的几条，都是"错了不会报错、只会静默做错事"的地方：
//   · 表里写的 `fallback` **自己必须过得了 `accepts()`** —— 缺省值都收不住的表，
//     用户点一次保存就会把 `server.properties` 写坏（而且他不会知道）；
//   · `applyEdits()` **只碰点名的键**（注释、键序、CRLF、我们不认识的键一个字节都不动）；
//   · 体检的**次序**（拦路的在最上面）和**在跑时不报端口**那两条。
// ---------------------------------------------------------------------------
static void runServerSettingsTests() {
    section("ZV. 服务端设置：那十几张表的表 / 收不收 / 合回文件 / 体检（§6.3 / M4-4）");

    // ---------- ZV0. 表本身 ----------
    {
        const QList<ServerPropertiesForm::Field> &fields = ServerPropertiesForm::commonFields();
        check(fields.size() == 19, "ZV0 常用字段一共 19 项（§6.3 说的「那十几个旋钮」）",
              QString::number(fields.size()));

        // 键唯一、每项该有的字都有。
        QSet<QString> keys;
        bool dupKey = false;
        bool blankText = false;
        for (const ServerPropertiesForm::Field &field : fields) {
            if (keys.contains(field.key)) {
                dupKey = true;
            }
            keys.insert(field.key);
            if (field.key.isEmpty() || field.label.isEmpty() || field.hint.isEmpty()) {
                blankText = true;
            }
        }
        check(!dupKey, "★★ ZV0 十九个键互不相同（键是身份，重了界面上就摆两行同一个东西）");
        check(!blankText, "★★ ZV0 每一项都有键、行首那个中文名、和那行小字");

        // ★ 表里写的那几个 `fallback` **必须过得了自己的 `accepts()`** —— 这是"按下保存会
        //   不会把文件写坏"的第一道保险。错在这儿的后果是：用户什么都没改、只按了一下保存，
        //   那一项就被写成了 `accepts()` 拒绝的东西（或者干脆写不进去、报一句他看不懂的错）。
        int badFallback = 0;
        for (const ServerPropertiesForm::Field &field : fields) {
            QString normalized;
            QString problem;
            if (!ServerPropertiesForm::accepts(field, field.fallback, &normalized, &problem)) {
                ++badFallback;
                check(false, QStringLiteral("★★ ZV0 缺省值「%1」自己过不了 accepts()").arg(field.key),
                      problem);
            } else if (!field.fallback.isEmpty() && normalized != field.fallback) {
                // 数字那几档会被规范化（`007` → `7`），出现这种说明表里写歪了。
                check(false, QStringLiteral("★★ ZV0 缺省值「%1」收下来变了样").arg(field.key),
                      normalized);
            }
        }
        check(badFallback == 0, "★★ ZV0 十九项缺省值**每一项**都收得住");

        // 每一档自己的形状：数字落在界里、下拉框的缺省就是第一个候选、开关只有两档。
        int badShape = 0;
        for (const ServerPropertiesForm::Field &field : fields) {
            switch (field.kind) {
            case ServerPropertiesForm::Kind::Number: {
                bool ok = false;
                const int value = field.fallback.toInt(&ok);
                if (!ok || value < field.min || value > field.max) {
                    ++badShape;
                }
                break;
            }
            case ServerPropertiesForm::Kind::Switch:
                if (field.fallback != QStringLiteral("true")
                    && field.fallback != QStringLiteral("false")) {
                    ++badShape;
                }
                break;
            case ServerPropertiesForm::Kind::Choice: {
                // ★ 缺省值必须是候选**之一**，不一定是第一个（`difficulty` 的缺省是 `easy`，
                //   它在候选里排第二 —— 游戏自己的顺序是 和平/简单/普通/困难，缺省却落在
                //   "简单"上）。真正要钉的是"缺省值不会掉到候选外面去"：那种值落盘之后，
                //   服务端读到的是一档它不认识的难度。
                bool inChoices = false;
                for (const ServerPropertiesForm::Choice &choice : field.choices) {
                    if (choice.token == field.fallback) {
                        inChoices = true;
                    }
                }
                if (field.choices.isEmpty() || !inChoices) {
                    ++badShape;
                }
                break;
            }
            case ServerPropertiesForm::Kind::Text:
                break;
            }
        }
        check(badShape == 0, "★★ ZV0 每一项的值域 / 候选 / 缺省三样互相对得上"
                             "（数字在界里、下拉框的缺省是第一个候选、开关只有 true/false）");

        // 下拉框每一项都得有那两个词（写进文件的那个 + 摆给用户看的那个）。
        int badChoice = 0;
        for (const ServerPropertiesForm::Field &field : fields) {
            for (const ServerPropertiesForm::Choice &choice : field.choices) {
                if (choice.token.isEmpty() || choice.name.isEmpty()) {
                    ++badChoice;
                }
            }
        }
        check(badChoice == 0, "★ ZV0 下拉框每个候选都有「写进文件的那个词」和「显示的那个词」");

        // 次序：日常（8）→ 规则（8）→ 性能（3）。前两组是建完服就想调的，最后一组是卡了才来调的。
        const auto keyAt = [&fields](int index) { return fields.value(index).key; };
        check(keyAt(0) == QStringLiteral("motd") && keyAt(7) == QStringLiteral("level-seed"),
              "ZV0 头八项是日常那几项（简介 / 端口 / 人数 / 难度 / 模式 / 极限 / 世界目录 / 种子）",
              keyAt(7));
        check(keyAt(8) == QStringLiteral("online-mode") && keyAt(15) == QStringLiteral("spawn-protection"),
              "ZV0 中间八项是规则那几项（正版验证 / 白名单 / PVP … 出生点保护）", keyAt(8));
        check(keyAt(16) == QStringLiteral("view-distance")
                  && keyAt(18) == QStringLiteral("player-idle-timeout"),
              "ZV0 最后三项是性能（视距 / 模拟距离 / 挂机踢出）", keyAt(16));

        // ★ 只有 `level-name` 是"要当目录名用"的那一项（值里带路径分隔符就等于把世界写到
        //   服务端目录外面去 —— 见 `Field::dirName` 那段）。
        int dirNameCount = 0;
        QString dirNameKey;
        for (const ServerPropertiesForm::Field &field : fields) {
            if (field.dirName) {
                ++dirNameCount;
                dirNameKey = field.key;
            }
        }
        check(dirNameCount == 1 && dirNameKey == QStringLiteral("level-name"),
              "★★ ZV0 十九项里只有 level-name 是目录名（别的项都不按路径规矩管）", dirNameKey);

        // `fieldFor` 认人认键（大小写不敏感），认不出来回 nullptr。
        check(ServerPropertiesForm::fieldFor(QStringLiteral("server-port")) != nullptr
                  && ServerPropertiesForm::fieldFor(QStringLiteral("Server-Port"))
                         == ServerPropertiesForm::fieldFor(QStringLiteral("server-port")),
              "★ ZV0 反查那一项的规格时大小写不敏感（用户手写 `Server-Port` 也认）");
        check(ServerPropertiesForm::fieldFor(QStringLiteral("nope")) == nullptr,
              "ZV0 认不出来的键回 nullptr（不是「随便给一项」）");

        // `knownKeys()` 就是表里那十九个键，次序也一致。
        const QStringList known = ServerPropertiesForm::knownKeys();
        QStringList fromFields;
        for (const ServerPropertiesForm::Field &field : fields) {
            fromFields.append(field.key);
        }
        check(known == fromFields, "★ ZV0 knownKeys() 和表**同一份**（不是另一处抄一遍）",
              known.join(QLatin1Char(',')));
    }

    // ---------- ZV1. 收不收（`accepts()`） ----------
    {
        const ServerPropertiesForm::Field *port =
            ServerPropertiesForm::fieldFor(QStringLiteral("server-port"));
        const ServerPropertiesForm::Field *view =
            ServerPropertiesForm::fieldFor(QStringLiteral("view-distance"));
        const ServerPropertiesForm::Field *pvp =
            ServerPropertiesForm::fieldFor(QStringLiteral("pvp"));
        const ServerPropertiesForm::Field *mode =
            ServerPropertiesForm::fieldFor(QStringLiteral("gamemode"));
        const ServerPropertiesForm::Field *level =
            ServerPropertiesForm::fieldFor(QStringLiteral("level-name"));
        const ServerPropertiesForm::Field *motd =
            ServerPropertiesForm::fieldFor(QStringLiteral("motd"));
        check(port != nullptr && view != nullptr && pvp != nullptr && mode != nullptr
                  && level != nullptr && motd != nullptr,
              "ZV1 前置：要拿的那六项都在表里");

        const auto accept = [](const ServerPropertiesForm::Field &field, const QString &raw,
                               QString *out) {
            QString problem;
            return ServerPropertiesForm::accepts(field, raw, out, &problem);
        };
        const auto saysProblem = [](const ServerPropertiesForm::Field &field,
                                    const QString &raw) {
            QString normalized;
            QString problem;
            ServerPropertiesForm::accepts(field, raw, &normalized, &problem);
            return problem;
        };

        // 数字：只收**严格**的整数（`toInt()` 会把 `1e3` / `10.0` 静默读成 0 —— 那 0 落在
        // 视距那一格上是个合法的烂值，见 `accepts()` 那段）。
        QString out;
        check(accept(*port, QStringLiteral(" 25566 "), &out) && out == QStringLiteral("25566"),
              "★ ZV1 数字两侧的空白裁掉（裁空白是安全的）", out);
        check(accept(*port, QStringLiteral("007"), &out) && out == QStringLiteral("7"),
              "★ ZV1 前导零规范化成十进制", out);
        check(accept(*port, QStringLiteral("+25566"), &out) && out == QStringLiteral("25566"),
              "ZV1 带正号也认", out);
        for (const QString &bad : {QStringLiteral("1e3"), QStringLiteral("10.0"),
                                   QStringLiteral("0x10"), QStringLiteral("abc"),
                                   QStringLiteral("1 0"), QStringLiteral("--1")}) {
            check(!accept(*port, bad, &out),
                  QStringLiteral("★★ ZV1 「%1」这种「看着像数字」的一律不收（不许替他猜）").arg(bad),
                  saysProblem(*port, bad));
        }
        // 空串也收不住（数字那几档）。
        check(!accept(*port, QString(), &out), "★★ ZV1 数字那几格空着不收（空值落盘之后服务端会崩）",
              saysProblem(*port, QString()));
        // 两头钳在游戏自己的界上。
        check(accept(*port, QStringLiteral("1"), &out) && accept(*port, QStringLiteral("65535"), &out)
                  && !accept(*port, QStringLiteral("0"), &out)
                  && !accept(*port, QStringLiteral("65536"), &out),
              "★★ ZV1 端口 1 ~ 65535 两头都收、两头外面都不收");
        check(accept(*view, QStringLiteral("3"), &out) && accept(*view, QStringLiteral("32"), &out)
                  && !accept(*view, QStringLiteral("2"), &out)
                  && !accept(*view, QStringLiteral("33"), &out),
              "★★ ZV1 视距 3 ~ 32（抄的是游戏自己的 clamp，**不是我们觉得合适的界**）");

        // 开关：Minecraft 自己写的是 true/false，但用户手改出来的 `yes` / `1` / `ON` 也得认 ——
        // 读进来认不出来会被当成"开着"，那是个把正版验证悄悄关掉的默认值。
        for (const QString &yes : {QStringLiteral("true"), QStringLiteral("TRUE"),
                                   QStringLiteral("yes"), QStringLiteral("on"),
                                   QStringLiteral("1")}) {
            check(accept(*pvp, yes, &out) && out == QStringLiteral("true"),
                  QStringLiteral("★ ZV1 开关认得「%1」，一律规范成 true").arg(yes), out);
        }
        for (const QString &no : {QStringLiteral("false"), QStringLiteral("FALSE"),
                                  QStringLiteral("no"), QStringLiteral("off"),
                                  QStringLiteral("0")}) {
            check(accept(*pvp, no, &out) && out == QStringLiteral("false"),
                  QStringLiteral("★ ZV1 开关认得「%1」，一律规范成 false").arg(no), out);
        }
        for (const QString &bad : {QStringLiteral("maybe"), QStringLiteral(""), QStringLiteral("2")}) {
            check(!accept(*pvp, bad, &out),
                  QStringLiteral("★★ ZV1 开关那两档之外的（「%1」）不收").arg(bad),
                  saysProblem(*pvp, bad));
        }

        // 下拉框：回**表里拼的那个词**（用户敲 `CREATIVE` 落盘也是小写那个）。
        check(accept(*mode, QStringLiteral("CREATIVE"), &out) && out == QStringLiteral("creative"),
              "★ ZV1 下拉框大小写不敏感，收下来的是表里那个词", out);
        check(!accept(*mode, QStringLiteral("survival-ish"), &out),
              "★ ZV1 候选之外的值不收", saysProblem(*mode, QStringLiteral("survival-ish")));
        check(saysProblem(*mode, QStringLiteral("nope")).contains(QStringLiteral("创造")),
              "★ ZV1 不收那句把候选**摆出来**（不是光说「不对」）",
              saysProblem(*mode, QStringLiteral("nope")));
        // 难度那一档的候选是另一套词（两个下拉框各说各的，别串台）。
        const ServerPropertiesForm::Field *difficulty =
            ServerPropertiesForm::fieldFor(QStringLiteral("difficulty"));
        check(difficulty != nullptr && accept(*difficulty, QStringLiteral("HARD"), &out)
                  && out == QStringLiteral("hard"),
              "★ ZV1 难度那一档独立认那几个词（`HARD` → `hard`）", out);
        check(!accept(*difficulty, QStringLiteral("creative"), &out),
              "★ ZV1 游戏模式那一套词不会在难度那一格上蒙对", saysProblem(*difficulty,
                                                                        QStringLiteral("creative")));

        // 文本：随便填，裁空白。
        check(accept(*motd, QStringLiteral("  hi there  "), &out) && out == QStringLiteral("hi there"),
              "ZV1 文本那几格裁两侧空白", out);
        check(accept(*motd, QString(), &out) && out.isEmpty(),
              "★ ZV1 文本那几格可以是空的（motd 空着就是空着）");

        // ★ 换行：一口下去会把这一项切成两行，落盘之后那份文件再也解不回来 —— 四种控件
        //   一律挡在这儿。
        for (const ServerPropertiesForm::Field *field : {motd, port, pvp, mode}) {
            check(!accept(*field, QStringLiteral("a\nb"), &out),
                  QStringLiteral("★★ ZV1 「%1」收不下换行（落盘会把这一项切成两行）").arg(field->key),
                  saysProblem(*field, QStringLiteral("a\nb")));
            check(!accept(*field, QStringLiteral("a\r\nb"), &out),
                  QStringLiteral("★★ ZV1 「%1」CRLF 也一样不收").arg(field->key));
        }

        // ★ 目录名那一项：空 / `.` / `..` / 带路径字符的全不收。
        check(!accept(*level, QString(), &out) && !accept(*level, QStringLiteral("  "), &out),
              "★★ ZV1 世界目录名不能是空的");
        for (const QString &bad : {QStringLiteral("."), QStringLiteral(".."),
                                   QStringLiteral("../外面的世界"),
                                   QStringLiteral("my/world"), QStringLiteral("C:world"),
                                   QStringLiteral("world?"), QStringLiteral("wor|ld")}) {
            check(!accept(*level, bad, &out),
                  QStringLiteral("★★ ZV1 世界目录名不收「%1」（它会变成 <服务端目录>/<值>）").arg(bad),
                  saysProblem(*level, bad));
        }
        check(accept(*level, QStringLiteral("我的世界"), &out) && out == QStringLiteral("我的世界"),
              "★ ZV1 中文目录名收（Windows 上没问题）", out);
    }

    // ---------- ZV2. `valuesOf` / `isInFile` ----------
    {
        const ServerModel::Properties props = ServerModel::parseProperties(
            QStringLiteral("motd=hi\nserver-port=25566\n"));
        const QList<ServerPropertiesForm::Field> &fields = ServerPropertiesForm::commonFields();
        const ServerPropertiesForm::Values values = ServerPropertiesForm::valuesOf(props, fields);
        check(values.size() == fields.size(),
              "ZV2 valuesOf 一项不少（表有十九项就回十九项）", QString::number(values.size()));
        // 次序跟着**表**走（不是跟着文件里的键序）—— 界面照它从上往下摆。
        bool orderOk = true;
        for (int i = 0; i < values.size(); ++i) {
            if (values.at(i).first != fields.at(i).key) {
                orderOk = false;
            }
        }
        check(orderOk, "★★ ZV2 valuesOf 的次序跟着**表**走（界面照它从上往下摆）");
        check(values.value(1).second == QStringLiteral("25566"),
              "ZV2 文件里写着的那一项读出来是它", values.value(1).second);
        check(values.value(0).second == QStringLiteral("hi"), "ZV2 头一项也是文件里的值");
        // 文件里没有的那一项 ⇒ 缺省值（这是"新装的、还没跑过的服务端"那一页打开时的样子）。
        check(values.value(2).second == QStringLiteral("20"),
              "★★ ZV2 文件里没写的那一项回缺省值（不是空串）", values.value(2).second);
        check(!ServerPropertiesForm::isInFile(props, fields.at(2))
                  && ServerPropertiesForm::isInFile(props, fields.at(1)),
              "★ ZV2 isInFile 分得清「文件里写着」和「用的缺省」（界面拿它说「这一项还没落盘」）");
    }

    // ---------- ZV3. `applyEdits`：只碰点名的键 ----------
    {
        // ★ 一份"什么花样都有"的文件：注释、空行、我们不认识的键、CRLF、键序打乱。
        const QString raw = QStringLiteral("#Minecraft server properties\r\n"
                                           "#Fri Oct 13 12:00:00 CST 2026\r\n"
                                           "motd=A Minecraft Server\r\n"
                                           "server-port=25565\r\n"
                                           "\r\n"
                                           "level-name=world\r\n"
                                           "some-plugin-option=nonsense value\r\n");
        ServerModel::Properties props = ServerModel::parseProperties(raw);
        const ServerPropertiesForm::Values edits = {
            {QStringLiteral("server-port"), QStringLiteral("25566")},
            {QStringLiteral("level-name"), QStringLiteral("world")},   // 值没变 ⇒ 不算改
        };
        const int changed = ServerPropertiesForm::applyEdits(props, edits);
        check(changed == 1, "★ ZV3 只算**真改了**的那一项（值一样的不算）", QString::number(changed));
        const QString expected = QStringLiteral("#Minecraft server properties\r\n"
                                                "#Fri Oct 13 12:00:00 CST 2026\r\n"
                                                "motd=A Minecraft Server\r\n"
                                                "server-port=25566\r\n"
                                                "\r\n"
                                                "level-name=world\r\n"
                                                "some-plugin-option=nonsense value\r\n");
        check(props.toString() == expected,
              "★★ ZV3 改一项之后**逐字**是这样：注释、空行、我们不认识的键、键序、CRLF 一个字节都没动",
              props.toString());
        check(props.value(QStringLiteral("server-port")) == QStringLiteral("25566"),
              "ZV3 被改的那一项真的变了");
        check(props.value(QStringLiteral("some-plugin-option")) == QStringLiteral("nonsense value"),
              "★★ ZV3 我们不认识的键原样留着（整合包和插件往里加的键一个都不动）");

        // 表里没有的键：跳过（这一层只认那十九项）。
        ServerModel::Properties other = ServerModel::parseProperties(QStringLiteral("a=1\n"));
        check(ServerPropertiesForm::applyEdits(other,
                                               {{QStringLiteral("not-in-table"), QStringLiteral("x")}})
                  == 0,
              "★ ZV3 表里没有的键不写（不是「谁传进来就写谁」）");

        // ★ 值不合法：跳过、不写 —— 这是给"调用方忘了先过 accepts()"准备的兜底。
        ServerModel::Properties bad = ServerModel::parseProperties(QStringLiteral("server-port=1\n"));
        check(ServerPropertiesForm::applyEdits(bad,
                                               {{QStringLiteral("server-port"), QStringLiteral("abc")}})
                  == 0
                  && bad.value(QStringLiteral("server-port")) == QStringLiteral("1"),
              "★★ ZV3 不合法的值**跳过**（宁可留着旧的，也不写一个服务端起不来的数进去）");

        // 文件里没有这一项 ⇒ 追加到末尾。
        ServerModel::Properties appended =
            ServerModel::parseProperties(QStringLiteral("server-port=25565\n"));
        check(ServerPropertiesForm::applyEdits(appended,
                                               {{QStringLiteral("view-distance"),
                                                 QStringLiteral("8")}})
                  == 1
                  && appended.toString().endsWith(QStringLiteral("view-distance=8\n")),
              "★ ZV3 文件里没有这一项 ⇒ 追到末尾", appended.toString());

        // 开关 / 下拉框走的是规范化之后那个词。
        ServerModel::Properties norm = ServerModel::parseProperties(QStringLiteral("pvp=1\n"));
        ServerPropertiesForm::applyEdits(norm, {{QStringLiteral("pvp"), QStringLiteral("OFF")}});
        check(norm.value(QStringLiteral("pvp")) == QStringLiteral("false"),
              "★ ZV3 写进去的是规范化之后那个词（`OFF` → `false`）",
              norm.value(QStringLiteral("pvp")));
    }

    // ---------- ZV4. `problemsIn` / `duplicateKeys` / `unknownKeys` / `worldDirName` ----------
    {
        // ★ 只查**文件里真写着的**项：缺省值按定义就是合法的，报出来只会制造噪音。
        const ServerModel::Properties clean =
            ServerModel::parseProperties(QStringLiteral("server-port=25565\nview-distance=10\n"));
        check(ServerPropertiesForm::problemsIn(clean).isEmpty(),
              "★★ ZV4 都对的时候一条都不报（新装的服务端打开这一页不该看见红字）");
        const ServerModel::Properties dirty = ServerModel::parseProperties(
            QStringLiteral("server-port=99999\nview-distance=abc\npvp=true\n"));
        const QList<ServerPropertiesForm::ValueProblem> problems =
            ServerPropertiesForm::problemsIn(dirty);
        check(problems.size() == 2,
              "★★ ZV4 只报**写歪了**的那两项（合法的第三项不报）",
              QString::number(problems.size()));
        check(problems.value(0).key == QStringLiteral("server-port")
                  && problems.value(0).label == QStringLiteral("端口")
                  && problems.value(0).value == QStringLiteral("99999")
                  && !problems.value(0).problem.isEmpty(),
              "★ ZV4 报出来的那一条带着：键、中文名、**文件里现在写着的那个值**、为什么不收",
              problems.value(0).problem);
        check(problems.value(1).key == QStringLiteral("view-distance"),
              "★ ZV4 次序跟着表走（端口在视距前面）", problems.value(1).key);

        // 重复的键：值不一样才报（值一样的是无意义的重复）。
        check(ServerPropertiesForm::duplicateKeys(ServerModel::parseProperties(
                  QStringLiteral("server-port=25565\nserver-port=25566\n")))
                  == QStringList{QStringLiteral("server-port")},
              "★★ ZV4 同一个键两行、值还不一样 ⇒ 报出来（Java 的规矩是后面盖前面，用户多半没意识到）");
        check(ServerPropertiesForm::duplicateKeys(ServerModel::parseProperties(
                  QStringLiteral("server-port=25565\nserver-port=25565\n")))
                  .isEmpty(),
              "★ ZV4 值一样的两行不报（那是无意义的重复）");
        check(ServerPropertiesForm::duplicateKeys(ServerModel::parseProperties(
                  QStringLiteral("Server-Port=1\nserver-port=2\n")))
                  == QStringList{QStringLiteral("server-port")},
              "★ ZV4 大小写写歪的同一个键也算（`Server-Port` 十有八九是想写 `server-port`）");

        // 不认识的键：不是错，只是说一声（这一层一个都不动）。
        check(ServerPropertiesForm::unknownKeys(ServerModel::parseProperties(
                  QStringLiteral("motd=hi\nfoo=1\nbar=2\n")))
                  == QStringList({QStringLiteral("foo"), QStringLiteral("bar")}),
              "★ ZV4 不认识的键按出现次序报出来、同一个键只报一次");
        check(ServerPropertiesForm::unknownKeys(ServerModel::parseProperties(
                  QStringLiteral("MOTD=hi\n")))
                  .isEmpty(),
              "★ ZV4 认键大小写不敏感（`MOTD` 不报成「不认识的」）");

        // ★ 世界目录名：认得出就是它，认不出**回空串**（调用方要靠"空"去拒绝备份 / 恢复）。
        check(ServerPropertiesForm::worldDirName(
                  ServerModel::parseProperties(QStringLiteral("level-name=mc\n")))
                  == QStringLiteral("mc"),
              "ZV4 世界目录名认得出就是它");
        check(ServerPropertiesForm::worldDirName(
                  ServerModel::parseProperties(QStringLiteral("motd=hi\n")))
                  == QStringLiteral("world"),
              "★ ZV4 文件里没写 level-name ⇒ 按游戏自己的缺省算（world）");
        check(ServerPropertiesForm::worldDirName(
                  ServerModel::parseProperties(QStringLiteral("level-name=../跑出去\n")))
                  .isEmpty(),
              "★★ ZV4 值不合法 ⇒ **回空串**（不猜 —— 猜出来的路径可能指着别人的目录）");
    }

    // ---------- ZV5. 体检：报哪几条、按什么次序 ----------
    {
        // 全好 ⇒ 一条都不报，而且有一句"没问题"的话（别摆一张空表）。
        ServerCheck::Facts good;
        good.installed = true;
        good.metaKnown = true;
        good.launchable = true;
        good.eulaAccepted = true;
        good.port = 25565;
        good.portState = ServerPortCheck::State::Free;
        good.worldName = QStringLiteral("world");
        good.worldExists = true;
        good.worldBytes = 12 * 1024 * 1024;
        good.worldBackupCount = 2;
        const QList<ServerCheck::Finding> none = ServerCheck::inspect(good);
        // ★ "全都对"**不等于**一条都不报：世界在盘上那一条是**说明**（"它在哪儿、多大"），
        //   它永远在（只要世界在盘上）。真正一条都没有的情形是"这个服务端我们连世界名叫什么
        //   都说不出来"—— 见下面那一段。这一页怕的是**空着**（用户以为页坏了）。
        check(none.size() == 1 && none.first().severity == ServerCheck::Severity::Info,
              "★★ ZV5 全都对 ⇒ 只剩那条说明（世界在盘上），一条要处理 / 提醒都没有",
              QString::number(none.size()));
        check(!none.isEmpty() && none.first().title.contains(QStringLiteral("world"))
                  && none.first().detail.contains(QStringLiteral("MB")),
              "★ ZV5 那条说明把世界名和**它多大**都写出来", none.isEmpty() ? none.first().detail
                                                                          : QString());
        check(ServerCheck::summaryText(none) == QStringLiteral("1 项说明"),
              "★ ZV5 那一档有点东西时，空的那两档一个字都不出现",
              ServerCheck::summaryText(none));
        // 真的一条都没有时：那句"没问题"（别摆一句「0 项要处理」）。
        ServerCheck::Facts silent;
        silent.installed = true;
        silent.metaKnown = true;
        silent.launchable = true;
        silent.eulaAccepted = true;
        silent.port = 25565;
        silent.portState = ServerPortCheck::State::Free;
        const QList<ServerCheck::Finding> nothing = ServerCheck::inspect(silent);
        check(nothing.isEmpty() && ServerCheck::summaryText(nothing) == ServerCheck::allGoodText()
                  && !ServerCheck::allGoodText().isEmpty(),
              "★ ZV5 一条都没有时那句总括 = 「没问题」那句（不摆「0 项要处理」）",
              ServerCheck::summaryText(nothing));

        // 一路错到底：看**次序**（拦路的在最上面）。
        ServerCheck::Facts worst;
        worst.installed = true;
        worst.metaKnown = true;
        worst.launchable = false;
        worst.launchProblem = QStringLiteral("我们记的那一份里缺了启动要用的版本信息。");
        worst.eulaAccepted = false;
        worst.running = false;
        worst.port = 25565;
        worst.portState = ServerPortCheck::State::InUse;
        worst.worldName = QStringLiteral("world");
        worst.worldExists = true;
        worst.worldBytes = 1024;
        worst.modCount = 3;
        worst.worldBackupCount = 0;
        worst.valueProblems = ServerPropertiesForm::problemsIn(
            ServerModel::parseProperties(QStringLiteral("view-distance=abc\n")));
        worst.duplicateKeys = QStringList{QStringLiteral("motd")};
        worst.unknownKeys = QStringList{QStringLiteral("foo")};
        const QList<ServerCheck::Finding> all = ServerCheck::inspect(worst);
        check(all.size() == 9, "ZV5 这一份最坏的情形报 9 条", QString::number(all.size()));
        // 前五条都是「要处理」，次序：拼不出命令 → EULA → 值不合法 → 端口被占。
        const auto titleAt = [&all](int i) { return all.value(i).title; };
        check(all.value(0).severity == ServerCheck::Severity::Problem
                  && all.value(0).action == ServerCheck::Action::Reinstall,
              "★★ ZV5 头一条是「拼不出启动命令」（拦着它起不来），出路是重装", titleAt(0));
        check(all.value(1).action == ServerCheck::Action::AcceptEula
                  && !all.value(1).title.isEmpty(),
              "★★ ZV5 第二条是 EULA（没人替你同意），出路是那道闸", titleAt(1));
        check(all.value(2).action == ServerCheck::Action::FixValues,
              "★★ ZV5 第三条是「某一项的值不对」，出路是改回缺省值", titleAt(2));
        check(all.value(3).action == ServerCheck::Action::OpenSettings,
              "★★ ZV5 第四条是「端口被占」（在跑时不报 —— 见下面那一条），出路是去改端口", titleAt(3));
        check(!all.value(3).title.isEmpty() && all.value(3).title.contains(QStringLiteral("25565")),
              "★ ZV5 端口那一条把**端口号**写出来（不然用户不知道去关谁）", titleAt(3));
        // 然后是提醒：重复的键、一份备份都没有。
        check(all.value(4).severity == ServerCheck::Severity::Warning
                  && all.value(4).title.contains(QStringLiteral("motd")),
              "★ ZV5 第五条是「同一个键写了两遍」（提醒），并且点名是哪个键", titleAt(4));
        check(all.value(5).severity == ServerCheck::Severity::Warning
                  && all.value(5).action == ServerCheck::Action::OpenBackups,
              "★ ZV5 第六条是「这个世界还没有备份」，出路是去备份那一页", titleAt(5));
        // 最后是说明：世界在盘上、装了模组、有不认识的键。
        check(all.value(6).severity == ServerCheck::Severity::Info,
              "ZV5 第七条是「世界在盘上」（说明）", titleAt(6));
        check(all.value(7).severity == ServerCheck::Severity::Info
                  && all.value(7).title.contains(QStringLiteral("3")),
              "★ ZV5 第八条是「装了几个模组」，把那个数写出来", titleAt(7));
        check(all.value(8).severity == ServerCheck::Severity::Info
                  && all.value(8).detail.contains(QStringLiteral("foo")),
              "★ ZV5 第九条是「有不认识的键」，并且**举个例**（大字里只有个数，名字在小字里）",
              titleAt(8));

        // `summaryText()` 的三档拼法（没有的那几档不出现）。
        check(ServerCheck::summaryText(all) == QStringLiteral("4 项要处理 · 2 项提醒 · 3 项说明"),
              "★★ ZV5 总括那句是三档拼出来的、次序固定", ServerCheck::summaryText(all));
        ServerCheck::Facts onlyInfo = good;
        onlyInfo.modCount = 1;  // 加上"世界在盘上"那一条 ⇒ 两条说明
        const QList<ServerCheck::Finding> twoInfo = ServerCheck::inspect(onlyInfo);
        check(twoInfo.size() == 2 && ServerCheck::summaryText(twoInfo) == QStringLiteral("2 项说明"),
              "★ ZV5 只有说明那一档时，前面两档一个字都不出现",
              ServerCheck::summaryText(twoInfo));

        // ★ 在跑的时候端口那一条**不报**：它自己就占着那个端口，报"被人占了"是一句吓人的废话。
        ServerCheck::Facts running = worst;
        running.running = true;
        running.launchable = true;
        QStringList runningTitles;
        for (const ServerCheck::Finding &finding : ServerCheck::inspect(running)) {
            runningTitles.append(finding.title);
        }
        bool mentionsPort = false;
        for (const QString &title : runningTitles) {
            if (title.contains(QStringLiteral("端口"))) {
                mentionsPort = true;
            }
        }
        check(!mentionsPort, "★★ ZV5 服务端正在跑时**不报**「端口被占」（那正是它自己占着的）");

        // ★ 没装好那一条：不再往下报 EULA / 世界 / 备份那几条 —— 那些本来就没到那一步。
        ServerCheck::Facts fresh;
        fresh.installed = false;
        fresh.installedNote = QStringLiteral("入口文件不在这个目录里。");
        const QList<ServerCheck::Finding> one = ServerCheck::inspect(fresh);
        check(one.size() == 1 && one.first().action == ServerCheck::Action::Reinstall,
              "★★ ZV5 没装好 ⇒ **只报一条**（「还没装好」），并指向「修复」",
              QString::number(one.size()));
        check(one.first().detail.contains(QStringLiteral("入口文件不在这个目录里")),
              "★ ZV5 那一条把 `Entry::note` 原话带上（「缺什么」是那一层说的）", one.first().detail);

        // 世界还没生成（新装的、没跑过）：说一声就好，不是错。
        ServerCheck::Facts virgin = good;
        virgin.worldExists = false;
        virgin.worldBytes = 0;
        virgin.worldBackupCount = 0;
        const QList<ServerCheck::Finding> first = ServerCheck::inspect(virgin);
        check(first.size() == 1 && first.first().severity == ServerCheck::Severity::Info
                  && first.first().title.contains(QStringLiteral("还没生成")),
              "★★ ZV5 第一次开服之前：只说一声「世界还没生成」（而且**不**报「还没备份」—— 没东西可备）",
              QString::number(first.size()));

        // 三档的名字和六个记号（★ `ui/` 看不见那个枚举，只认记号）。
        check(ServerCheck::severityName(ServerCheck::Severity::Problem) == QStringLiteral("要处理")
                  && ServerCheck::severityName(ServerCheck::Severity::Warning) == QStringLiteral("提醒")
                  && ServerCheck::severityName(ServerCheck::Severity::Info) == QStringLiteral("说明"),
              "★ ZV5 三档那三个词的唯一出处");
        check(ServerCheck::actionToken(ServerCheck::Action::None).isEmpty(),
              "★★ ZV5 `None` 的记号是**空串**（界面上按它决定「这一条不摆按钮」）");
        check(ServerCheck::actionToken(ServerCheck::Action::Reinstall) == QStringLiteral("reinstall")
                  && ServerCheck::actionToken(ServerCheck::Action::AcceptEula)
                         == QStringLiteral("accept-eula")
                  && ServerCheck::actionToken(ServerCheck::Action::FixValues)
                         == QStringLiteral("fix-values")
                  && ServerCheck::actionToken(ServerCheck::Action::OpenSettings)
                         == QStringLiteral("open-settings")
                  && ServerCheck::actionToken(ServerCheck::Action::OpenBackups)
                         == QStringLiteral("open-backups"),
              "★★ ZV5 五个出路的记号（`MainWindow::runServerCheckAction()` 按它分岔 —— "
              "记号改了那一边会静默什么都不做）");
    }

    // ---------- ZV6. 端口：真占一次，再放开 ----------
    {
        // ★ 这一格要**真听一次**才知道（Windows 上没有不需要权限的"谁占着这个端口"接口 ——
        //   见 `ServerPortCheck.hpp` 的文件头）。全程 127.0.0.1，不联网。
        check(ServerPortCheck::stateOf(0) == ServerPortCheck::State::Unknown
                  && ServerPortCheck::stateOf(70000) == ServerPortCheck::State::Unknown
                  && ServerPortCheck::stateOf(-1) == ServerPortCheck::State::Unknown,
              "★★ ZV6 端口不在 1~65535 里 ⇒ `Unknown`（「没查」），**不当成「被占」**");

        QTcpServer holder;
        const bool bound = holder.listen(QHostAddress::Any, 0);
        check(bound, "ZV6 前置：本机能听上一个空闲端口", holder.errorString());
        const int taken = bound ? holder.serverPort() : 0;
        if (bound) {
            check(ServerPortCheck::stateOf(taken) == ServerPortCheck::State::InUse,
                  "★★ ZV6 别人占着这个端口 ⇒ 报 `InUse`", QString::number(taken));
            holder.close();
            check(ServerPortCheck::stateOf(taken) == ServerPortCheck::State::Free,
                  "★★ ZV6 放开之后同一个端口 ⇒ 报 `Free`（一次 listen 之后立刻放掉）",
                  QString::number(taken));
        }
        // 三档那三句话的唯一出处。
        check(ServerPortCheck::stateName(ServerPortCheck::State::Free) == QStringLiteral("没被占用")
                  && ServerPortCheck::stateName(ServerPortCheck::State::InUse)
                         == QStringLiteral("被占用了")
                  && ServerPortCheck::stateName(ServerPortCheck::State::Unknown)
                         == QStringLiteral("没能查出来"),
              "★ ZV6 三档那三句话的唯一出处");
    }
}

int main(int argc, char *argv[]) {
    QCoreApplication app(argc, argv);
    app.setApplicationName("WTFML");
    app.setOrganizationName("WTFML");

    const QString repoRoot = QStringLiteral(REPO_ROOT_PATH);
    const QString metaDir = repoRoot + "/tests/meta";
    // applicationDirPath() = bin/，沙箱就落在 bin/.minecraft
    const QString sandbox = QCoreApplication::applicationDirPath() + "/.minecraft";

    // libs 模式：只打印生产代码 extractLibraries 选中了哪些 library（不下载）。
    // 用来验证平台 rules 过滤是否真的生效。
    if (argc >= 3 && QString::fromLocal8Bit(argv[1]) == QLatin1String("libs")) {
        const QString versionId = QString::fromLocal8Bit(argv[2]);
        const QJsonObject json = loadJson(metaDir + "/" + versionId + ".json");
        if (json.isEmpty()) {
            out() << "no meta for " << versionId << "\n";
            return 2;
        }
        const QJsonArray all = json[QStringLiteral("libraries")].toArray();
        DownloadManager mgr;
        const QList<Library> picked = mgr.extractLibraries(json);

        int allArtifacts = 0;
        for (const QJsonValue &v : all) {
            if (!v.toObject()[QStringLiteral("downloads")].toObject()
                     [QStringLiteral("artifact")]
                     .toObject()[QStringLiteral("path")]
                     .toString()
                     .isEmpty()) {
                ++allArtifacts;
            }
        }

        out() << "platformName=" << LibraryRules::platformName()
              << " platformArch=" << LibraryRules::platformArch() << "\n";
        out() << "version " << versionId << ": 条目 " << all.size() << "，带 artifact 的 "
              << allArtifacts << "，extractLibraries 选中 " << picked.size() << "\n";
        int foreign = 0;
        for (const Library &lib : picked) {
            const bool isForeign = lib.path.contains(QStringLiteral("natives-linux")) ||
                                   lib.path.contains(QStringLiteral("natives-macos")) ||
                                   lib.path.contains(QStringLiteral("linux-")) ||
                                   lib.path.contains(QStringLiteral("osx-"));
            if (isForeign) {
                ++foreign;
                out() << "  [外来平台!] " << lib.path << "\n";
            }
        }
        out() << "其中非 Windows 平台条目: " << foreign << "\n";
        out().flush();
        return 0;
    }

    // scan 模式：量一次「切到设置页要冻多久」。
    // MainWindow::refreshJavaList() 是**同步**跑的，scanLocalJavaVersions() 花多少毫秒，
    // 界面就冻多少毫秒 —— 这个数就是"点开设置卡一下"的那个"一下"。
    if (argc >= 2 && QString::fromLocal8Bit(argv[1]) == QLatin1String("scan")) {
        GlobalJavaSettings settings;
        QElapsedTimer scanTimer;
        scanTimer.start();
        const QMap<int, QString> versions = settings.scanLocalJavaVersions();
        const qint64 elapsed = scanTimer.elapsed();

        out() << "scanLocalJavaVersions(): " << elapsed << " ms  <- 界面就冻这么久\n";
        for (auto it = versions.cbegin(); it != versions.cend(); ++it) {
            out() << "  Java " << it.key() << "  ->  " << it.value() << "\n";
        }
        out() << "共认出来 " << versions.size() << " 个运行时\n";
        out().flush();
        return 0;
    }

    // pipeline 模式：下载批次记账的全部断言，全离线（file:// 当远端）。
    if (argc >= 2 && QString::fromLocal8Bit(argv[1]) == QLatin1String("pipeline")) {
        return runPipelineTests(app, sandbox);
    }

    // vm-batch 模式：VersionManager::downloadVersion 的批次编排，同样离线。
    if (argc >= 2 && QString::fromLocal8Bit(argv[1]) == QLatin1String("vm-batch")) {
        return runVersionManagerBatch(app, sandbox);
    }

    // loader-install 模式：**联网**真装一次带加载器的版本到沙箱里，装完连"能不能启动"
    // （启动前检查 / classpath）一起验。见这个函数上面那段说明。
    // 第三个参数是加载器（缺省 Fabric），认不出来就拒绝跑 —— 猜一个装下去是给用户装错东西。
    if (argc >= 3 && QString::fromLocal8Bit(argv[1]) == QLatin1String("loader-install")) {
        VersionManager::LoaderKind kind = VersionManager::LoaderKind::Fabric;
        if (argc >= 4) {
            const QString word = QString::fromLocal8Bit(argv[3]).toLower();
            if (word == QLatin1String("fabric")) {
                kind = VersionManager::LoaderKind::Fabric;
            } else if (word == QLatin1String("forge")) {
                kind = VersionManager::LoaderKind::Forge;
            } else if (word == QLatin1String("neoforge")) {
                kind = VersionManager::LoaderKind::NeoForge;
            } else if (word == QLatin1String("optifine")) {
                kind = VersionManager::LoaderKind::OptiFine;
            } else {
                out() << "不认识的加载器「" << word
                      << "」。用法：loader-install <游戏版本> [fabric|forge|neoforge|optifine]\n";
                out().flush();
                return 2;
            }
        }
        // 第四个词（可省）是 `mirror`：把这一趟拨到镜像源上跑。
        bool useMirror = false;
        if (argc >= 5) {
            const QString word = QString::fromLocal8Bit(argv[4]).toLower();
            if (word == QLatin1String("mirror")) {
                useMirror = true;
            } else {
                out() << "不认识的第四个参数「" << word
                      << "」。用法：loader-install <游戏版本> [fabric|forge|neoforge|optifine] "
                         "[mirror]\n";
                out().flush();
                return 2;
            }
        }
        return runLoaderInstallLive(app, sandbox, QString::fromLocal8Bit(argv[2]), kind,
                                    useMirror);
    }

    // names 模式：版本显示名的纯函数真值表 + displayParts() 读盘 + LauncherSettings
    // + 已安装版本扫描的告警 + 内存建议值。
    // modpack-read 模式：拿一个**真整合包**走一遍导入的前半段，一个字节都不下。
    //   verify.exe modpack-read "<整合包.zip>"
    // 检的是两件事：ZipUtil 从真压缩包（几百 MB、条目名大小写不一定对得上）里读单条目
    // 这条路，以及真清单的解析结果。这两步是**全离线**能验到的最远处 —— 再往下就要下
    // 加载器和那 150 个模组了（那条路在联网时用产品界面走）。
    //
    // 退出码：0 = 读出来、解析通过、每一条路径都过判据；否则 1（并把问题打在 stdout）。
    if (argc >= 3 && QString::fromLocal8Bit(argv[1]) == QLatin1String("modpack-read")) {
        const QString zipPath = QString::fromLocal8Bit(argv[2]);
        QByteArray indexJson;
        QString error;
        const ZipUtil::EntryStatus status =
            ZipUtil::readEntry(zipPath, ModpackImport::modrinthIndexName(), &indexJson, &error);
        out() << "zip=" << zipPath << "\n"
              << "status=" << static_cast<int>(status) << "\n"
              << "bytes=" << indexJson.size() << "\n"
              << "error=" << error << "\n";
        // 没读到 Modrinth 清单时，顺手看一眼它是不是 CurseForge 格式 —— 产品界面正是这么
        // 分这两种不是整合包的（见 MainWindow::onImportModpackClicked：再读一次根目录的
        // manifest.json）。探针照抄同一套判据，好让手里这个包到底属于哪种有一个离线答案：
        // 用户问的"拿这些包导入看看"里，那个 CurseForge 包就卡在这一句上。
        if (status != ZipUtil::EntryStatus::Ok) {
            QByteArray manifest;
            const bool curseForge =
                ZipUtil::readEntry(zipPath, ModpackImport::curseForgeManifestName(), &manifest,
                                   nullptr) == ZipUtil::EntryStatus::Ok;
            out() << "format=" << (curseForge ? "curseforge" : "unknown") << "\n"
                  << "problem="
                  << ModpackImport::unsupportedFormatText(
                         curseForge ? ModpackImport::Format::CurseForge
                                    : ModpackImport::Format::Unknown)
                  << "\n";
            out().flush();
            return 3;
        }
        const ModpackImport::Result result = ModpackImport::parseModrinthIndex(indexJson);
        out() << "ok=" << (result.ok ? 1 : 0) << "\n";
        if (!result.ok) {
            out() << "problem=" << result.problem << "\n";
            out().flush();
            return 1;
        }
        const ModpackImport::Pack &pack = result.pack;
        out() << "name=" << pack.name << "\n"
              << "version=" << pack.version << "\n"
              << "game=" << pack.gameVersion << "\n"
              << "loader=" << pack.loaderKey << " " << pack.loaderVersion << "\n"
              << "files=" << pack.files.size() << " skipped=" << pack.filesSkipped << "\n"
              << "instanceName=" << ModpackImport::suggestInstanceName(pack.name) << "\n"
              << "loaderProblem="
              << ModpackImport::unsupportedLoaderText(pack.loaderKey, pack.loaderVersion)
              << "\n";
        // 每一条路径都过一遍判据。一条误判的代价是**整包被拒**（判据是有意设计成
        // "整包拒绝"的），所以真包的这 150 条路径一条都不能报不安全。
        int unsafe = 0;
        qint64 totalBytes = 0;
        QString longest;
        for (const ModpackImport::PackFile &file : pack.files) {
            if (!ModpackImport::isSafeRelativePath(file.path)) {
                ++unsafe;
                out() << "unsafe: " << file.path << "\n";
            }
            if (file.size > 0) {
                totalBytes += file.size;
            }
            if (file.path.length() > longest.length()) {
                longest = file.path;
            }
        }
        out() << "unsafePaths=" << unsafe << "\n"
              << "totalBytes=" << totalBytes << "\n"
              << "longestPath=" << longest << " (" << longest.length() << " 字符)\n";
        out().flush();
        return unsafe == 0 ? 0 : 1;
    }

    if (argc >= 2 && QString::fromLocal8Bit(argv[1]) == QLatin1String("names")) {
        runVersionNameTests(sandbox);
        runInstanceFileTests(sandbox);
        runInstalledScanTests(sandbox);
        // 排在扫描之后：这一段会往 versions/ 下建一个目录再删掉，放在扫描前面
        // 万一中途崩了，扫描那几条"沙盒里有几个版本"的断言会跟着一起红，查起来绕。
        runVersionMetaWriteTests(sandbox);
        runRenameInstanceTests(sandbox);
        runInstanceGroupTests(sandbox);
        runVersionJvmArgsTests(sandbox);
        // 排在这些"要数沙箱里有几个版本"的用例之后，而且它自己会收摊 ——
        // 见这一节末尾那几条清理断言。
        runLoaderInheritanceTests(sandbox);
        runLoaderInstallTests();
        runMemorySuggestionTests(sandbox);
        runEffectiveJavaSettingsTests(sandbox);
        runJavaReleaseParseTests();
        out() << "\n===== " << (g_failures == 0 ? "全部通过" : "有失败项") << ": "
              << (g_checks - g_failures) << "/" << g_checks << " =====\n";
        out().flush();
        return g_failures == 0 ? 0 : 1;
    }

    // vm-fetch-fail 模式：元数据死路必须有终态信号（防止 UI 永久禁用）。
    if (argc >= 2 && QString::fromLocal8Bit(argv[1]) == QLatin1String("vm-fetch-fail")) {
        return runVersionManagerFetchFail(app);
    }

    // fetch 模式：用生产下载代码把一个版本拉全（客户端 jar + 库 + natives classifier）。
    // 不再自带批次（beginBatch/endBatch），用来验证"不带批次"的用法也发得出完成信号。
    if (argc >= 4 && QString::fromLocal8Bit(argv[1]) == QLatin1String("fetch")) {
        const QString versionId = QString::fromLocal8Bit(argv[2]);
        const QString mcRoot = QString::fromLocal8Bit(argv[3]);
        const QJsonObject json = loadJson(metaDir + "/" + versionId + ".json");
        if (json.isEmpty()) {
            out() << "no meta for " << versionId << "\n";
            return 2;
        }

        QDir().mkpath(mcRoot + "/versions/" + versionId);
        QFile jf(mcRoot + "/versions/" + versionId + "/" + versionId + ".json");
        if (jf.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            jf.write(QJsonDocument(json).toJson(QJsonDocument::Indented));
            jf.close();
        }

        DownloadManager mgr;
        int done = 0;
        int failed = 0;
        bool finished = false;
        bool signalSuccess = false;
        QObject::connect(&mgr, &DownloadManager::downloadFinished, &app,
                         [&](const QString &name, bool ok, const QString &err) {
                             ++done;
                             if (!ok) {
                                 ++failed;
                                 out() << "  FAIL " << name << "  " << err << "\n";
                                 out().flush();
                             }
                         });
        QEventLoop loop;
        QObject::connect(&mgr, &DownloadManager::allDownloadsFinished, &app,
                         [&](bool ok) {
                             finished = true;
                             signalSuccess = ok;
                             loop.quit();
                         });

        const QJsonObject client = json[QStringLiteral("downloads")].toObject()
                                       [QStringLiteral("client")].toObject();
        mgr.downloadClientJar(versionId, client[QStringLiteral("url")].toString(),
                              mcRoot + "/versions/" + versionId + "/" + versionId + ".jar",
                              client[QStringLiteral("sha1")].toString(),
                              client[QStringLiteral("size")].toVariant().toLongLong());

        const QList<Library> libs = mgr.extractLibraries(json);
        int natives = 0;
        for (const Library &l : libs) {
            if (l.isNative) {
                ++natives;
            }
        }
        out() << "开始下载 " << libs.size() << " 个库（其中 natives classifier " << natives
              << " 个）\n";
        out().flush();
        mgr.downloadLibraries(libs, mcRoot + "/libraries");

        // 信号可能在 exec() 之前就发出来（全部跳过时），必须先看标志
        if (!finished) {
            loop.exec();
        }
        out() << "完成 " << done << " 项，失败 " << failed << " 项"
              << "（allDownloadsFinished success=" << signalSuccess << "）\n";
        out().flush();
        return failed == 0 ? 0 : 1;
    }

    // launch 模式：完整复刻 MainWindow::onStartButtonClicked 的顺序，一路走到
    // LauncherManager::startGame，也就是真正拉起游戏进程。
    // 用法：verify launch <versionId> <major> [timeoutMs]
    // 必须放在目标 .minecraft 的上一级目录里跑（startGame 用 applicationDirPath）。
    if (argc >= 4 && QString::fromLocal8Bit(argv[1]) == QLatin1String("launch")) {
        const QString versionId = QString::fromLocal8Bit(argv[2]);
        const int major = QString::fromLocal8Bit(argv[3]).toInt();
        const int timeoutMs = argc >= 5 ? QString::fromLocal8Bit(argv[4]).toInt() : 90000;
        const QJsonObject json = loadJson(metaDir + "/" + versionId + ".json");
        if (json.isEmpty()) {
            return 2;
        }

        GlobalJavaSettings settings;
        settings.load();
        const QString originalPath = settings.javaPath();
        LauncherManager mgr;
        QObject::connect(&mgr, &LauncherManager::processOutput, &app,
                         [](int, const QString &t) { out() << "  [game] " << t << "\n"; out().flush(); });
        QObject::connect(&mgr, &LauncherManager::processError, &app,
                         [](int, const QString &t) { out() << "  [game!] " << t << "\n"; out().flush(); });

        QEventLoop loop;
        QObject::connect(&mgr, &LauncherManager::gameFinished, &loop,
                         [&](int, int code, QProcess::ExitStatus st) {
                             out() << "游戏退出: code=" << code
                                   << " status=" << (st == QProcess::NormalExit ? "Normal" : "Crash")
                                   << "\n";
                             loop.quit();
                         });

        QStringList errors;
        const QString nativesDir = mgr.prepareNatives(json, versionId, &errors);
        out() << "prepareNatives -> "
              << (nativesDir.isEmpty() ? QStringLiteral("<无 natives 需求>") : nativesDir) << "\n";
        for (const QString &e : errors) {
            out() << "  natives error: " << e << "\n";
        }
        if (nativesDir.isEmpty() && !errors.isEmpty()) {
            return 2;
        }

        if (!mgr.checkPreLaunch(versionId, &errors, json)) {
            out() << "checkPreLaunch 失败: " << errors.join(QStringLiteral("; ")) << "\n";
            return 2;
        }

        const QString component =
            json[QStringLiteral("javaVersion")].toObject()[QStringLiteral("component")].toString();
        if (!settings.ensureJavaForVersion(major, component)) {
            out() << "找不到 Java " << major << "\n";
            return 2;
        }
        out() << "java = " << settings.javaPath() << "\n";
        out().flush();

        const QString assetIndex = json[QStringLiteral("assetIndex")].toObject()["id"].toString();
        const QStringList args =
            mgr.generateJvmArguments(QString(), versionId, assetIndex, json, settings, true, major);

        QTimer::singleShot(timeoutMs, &loop, [&]() {
            out() << "超时 " << timeoutMs << "ms，结束等待\n";
            loop.quit();
        });
        out() << "startGame -> session " << mgr.startGame(args, settings, versionId,
                                                          versionId, QStringLiteral("verify-probe"))
              << "\n";
        out().flush();
        loop.exec();

        settings.setJavaPath(originalPath);
        settings.save();
        return 0;
    }

    // assets 模式：跑生产代码的 downloadAssets，把缺失的资源补齐。
    // 注意 parseAndDownloadAssets 用的是 applicationDirPath()，所以这个 exe
    // 必须放在目标 .minecraft 的上一级目录里跑。
    if (argc >= 3 && QString::fromLocal8Bit(argv[1]) == QLatin1String("assets")) {
        const QString versionId = QString::fromLocal8Bit(argv[2]);
        const QJsonObject json = loadJson(metaDir + "/" + versionId + ".json");
        if (json.isEmpty()) {
            return 2;
        }
        DownloadManager mgr;
        int done = 0;
        int failed = 0;
        bool finished = false;
        QObject::connect(&mgr, &DownloadManager::downloadFinished, &app,
                         [&](const QString &name, bool ok, const QString &err) {
                             ++done;
                             if (!ok) {
                                 ++failed;
                                 out() << "  FAIL " << name << "  " << err << "\n";
                                 out().flush();
                             }
                         });
        QEventLoop loop;
        QObject::connect(&mgr, &DownloadManager::allDownloadsFinished, &app,
                         [&](bool) {
                             finished = true;
                             loop.quit();
                         });

        const AssetIndex idx = mgr.extractAssetIndex(json);
        out() << "开始补齐 assets index " << idx.id << "\n";
        out().flush();
        mgr.downloadAssets(idx);
        // 对象全都在盘上时，整批会在 exec() 之前就结束
        if (!finished) {
            loop.exec();
        }
        out() << "完成 " << done << " 项，失败 " << failed << " 项\n";
        out().flush();
        return failed == 0 ? 0 : 1;
    }

    // dump 模式：把 generateJvmArguments 的结果逐行写入文件，供 shell 用真实
    // 参数启动游戏（验证 Java 25 那一条真正跑得起来）。
    if (argc >= 5 && QString::fromLocal8Bit(argv[1]) == QLatin1String("dump")) {
        const QString versionId = QString::fromLocal8Bit(argv[2]);
        const int major = QString::fromLocal8Bit(argv[3]).toInt();
        const QJsonObject json = loadJson(metaDir + "/" + versionId + ".json");
        if (json.isEmpty()) {
            out() << "no meta for " << versionId << "\n";
            return 2;
        }
        GlobalJavaSettings s;
        s.load();
        const QString originalPath = s.javaPath();
        // 和 MainWindow 一样先解析出该版本需要的 Java，再生成参数
        const QString component =
            json[QStringLiteral("javaVersion")].toObject()[QStringLiteral("component")].toString();
        if (!s.ensureJavaForVersion(major, component)) {
            out() << "no java for major " << major << "\n";
            return 2;
        }
        LauncherManager mgr;
        // 复刻 MainWindow 的顺序：先备好 natives，再生成参数
        QStringList nativeErrors;
        const QString nativesDir = mgr.prepareNatives(json, versionId, &nativeErrors);
        out() << "natives=" << (nativesDir.isEmpty() ? QStringLiteral("<无需/none>") : nativesDir)
              << "\n";
        for (const QString &e : nativeErrors) {
            out() << "natives error: " << e << "\n";
        }
        const QString assetIndex = json[QStringLiteral("assetIndex")].toObject()["id"].toString();
        const QStringList args = mgr.generateJvmArguments(QString(), versionId, assetIndex, json, s,
                                                          true, major);
        QFile f(QString::fromLocal8Bit(argv[4]));
        if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            return 2;
        }
        for (const QString &a : args) {
            f.write(a.toUtf8());
            f.write("\n");
        }
        // 把选中的 java 写到 stdout 供 shell 取用
        out() << "wrote " << args.size() << " args to " << f.fileName() << "\n";
        out() << "java=" << s.javaPath() << "\n";
        out().flush();
        // 测试不该改动机器上的设置
        s.setJavaPath(originalPath);
        s.save();
        return 0;
    }

    // dumpmerged 模式：和 dump 一样把参数写到文件，但版本 json 用的是**继承合并过**的那份
    // （从沙箱 build/.minecraft 里真装好的版本目录读）。
    //
    // 为什么不能直接用 meta/ 里那份：那份是加载器版本（或原版）自己写的原样 json，加载器
    // 那份里**没有原版的库**（log4j、joml 之类全在父那份），照它拼出来的 classpath 连
    // LogManager 都找不到 —— 那样起不来，也就验不出"这次改动之后游戏真的能启动"。
    if (argc >= 5 && QString::fromLocal8Bit(argv[1]) == QLatin1String("dumpmerged")) {
        const QString versionId = QString::fromLocal8Bit(argv[2]);
        const int major = QString::fromLocal8Bit(argv[3]).toInt();
        const QString sandbox = repoRoot + "/build/.minecraft";
        AppPaths::setMinecraftDir(sandbox);
        VersionManager vm;
        const QJsonObject json = vm.getVersionJson(versionId);
        if (json.isEmpty()) {
            out() << "no version " << versionId << " under " << sandbox << "\n";
            return 2;
        }
        GlobalJavaSettings s;
        s.load();
        const QString originalPath = s.javaPath();
        const QString component =
            json[QStringLiteral("javaVersion")].toObject()[QStringLiteral("component")].toString();
        if (!s.ensureJavaForVersion(major, component)) {
            out() << "no java for major " << major << "\n";
            return 2;
        }
        LauncherManager mgr;
        QStringList nativeErrors;
        const QString nativesDir = mgr.prepareNatives(json, versionId, &nativeErrors);
        out() << "natives=" << (nativesDir.isEmpty() ? QStringLiteral("<none>") : nativesDir)
              << "\n";
        const QString assetIndex = json[QStringLiteral("assetIndex")].toObject()["id"].toString();
        const QStringList args = mgr.generateJvmArguments(QString(), versionId, assetIndex, json, s,
                                                          true, major);
        QFile f(QString::fromLocal8Bit(argv[4]));
        if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            return 2;
        }
        for (const QString &a : args) {
            f.write(a.toUtf8());
            f.write("\n");
        }
        out() << "wrote " << args.size() << " args to " << f.fileName() << "\n";
        out() << "java=" << s.javaPath() << "\n";
        out().flush();
        s.setJavaPath(originalPath);
        s.save();
        return 0;
    }

    const QStringList versions = {"26.3", "26.1", "1.19", "1.18.2", "1.12.2"};
    // A verification run must not inherit files left by an earlier run.  The
    // old build-local harness happened to start with a hand-maintained
    // .minecraft tree; CTest should be reproducible from a clean checkout.
    QDir(sandbox).removeRecursively();
    QDir().mkpath(sandbox);
    AppPaths::setMinecraftDir(sandbox);

    QMap<QString, QJsonObject> jsons;
    for (const QString &v : versions) {
        jsons[v] = loadJson(metaDir + "/" + v + ".json");
        if (jsons[v].isEmpty()) {
            out() << "FATAL: 缺少元数据 " << metaDir << "/" << v << ".json\n";
            return 2;
        }
    }

    DownloadManager dm;
    LauncherManager launcher;

    // -----------------------------------------------------------------
    section("A. natives classifier 选择（DownloadManager::extractLibraries）");
    // -----------------------------------------------------------------
    QMap<QString, QList<Library>> nativesOf;
    for (const QString &v : versions) {
        const QList<Library> libs = dm.extractLibraries(jsons[v]);
        QList<Library> natives;
        QList<Library> artifacts;
        bool ghost = false;
        for (const Library &lib : libs) {
            if (lib.isNative) {
                natives << lib;
            } else {
                artifacts << lib;
            }
            if (lib.url.isEmpty() || lib.path.isEmpty()) {
                ghost = true;
            }
        }
        nativesOf[v] = natives;

        int libCount = jsons[v][QStringLiteral("libraries")].toArray().size();
        out() << "\n  " << v << ": libraries=" << libCount << " artifact=" << artifacts.size()
              << " natives=" << natives.size() << "\n";
        for (const Library &n : natives) {
            out() << "        " << n.path << "\n";
        }
        check(!ghost, QString("%1: 没有空 url/path 的幽灵下载条目").arg(v));
    }
    out() << "\n";
    check(nativesOf["1.18.2"].size() == 8, "1.18.2 选出 8 个 natives classifier",
          QString::number(nativesOf["1.18.2"].size()));
    // 1.12.2 共 5 个库带 natives 字段，其中：
    //   lwjgl-platform:2.9.2 的 rules 只 allow osx -> 排除
    //   java-objc-bridge 只有 osx 的 natives key -> 无 windows classifier
    // 剩下 3 个（lwjgl-platform:2.9.4 / jinput-platform / text2speech）
    check(nativesOf["1.12.2"].size() == 3, "1.12.2 选出 3 个 natives classifier",
          QString::number(nativesOf["1.12.2"].size()));
    check(nativesOf["1.19"].isEmpty(), "1.19 不需要 classifier（新格式）");
    check(nativesOf["26.1"].isEmpty(), "26.1 不需要 classifier（新格式）");

    bool has292 = false;
    for (const Library &n : nativesOf["1.12.2"]) {
        if (n.path.contains(QStringLiteral("2.9.2"))) {
            has292 = true;
        }
    }
    check(!has292, "1.12.2 的 rules 过滤生效（没有 2.9.2 的 DLL）");

    // -----------------------------------------------------------------
    section("B. 1.19+ classpath 零回归（对比改动前的算法）");
    // -----------------------------------------------------------------
    for (const QString &v : {"1.19", "26.1"}) {
        GlobalJavaSettings s;
        const QStringList args =
            launcher.generateJvmArguments(QString(), v, QStringLiteral("1"), jsons[v], s, true, 21);
        const int cpIndex = args.indexOf(QStringLiteral("-cp"));
        const QStringList actual =
            cpIndex >= 0 ? args.at(cpIndex + 1).split(QLatin1Char(';'), Qt::SkipEmptyParts)
                         : QStringList();
        const QStringList expected = legacy::classpath(jsons[v], v);

        check(actual == expected, QString("%1: classpath 与改动前逐项一致").arg(v),
              QString("new=%1 old=%2").arg(actual.size()).arg(expected.size()));
        if (actual != expected) {
            const QSet<QString> a(actual.begin(), actual.end());
            const QSet<QString> e(expected.begin(), expected.end());
            for (const QString &only : a - e) {
                out() << "        仅新代码: " << only << "\n";
            }
            for (const QString &only : e - a) {
                out() << "        仅旧代码: " << only << "\n";
            }
        }

        // 改动前这里断言"1.19+ 不出现 -Djava.library.path"。现在按 version.json 原样
        // 传递：1.19 和 26.1 都声明了这条属性，值就是该版本的 natives 目录。断言改成
        // "有且只有一条，且是存在的绝对路径" —— 这比"不许出现"更贴近原版行为，也仍然
        // 能抓住"把不存在的路径塞进去"那类回归（QDir::exists 会失败）。
        int libPathCount = 0;
        QString libPath;
        for (const QString &a : args) {
            if (a.startsWith(QStringLiteral("-Djava.library.path="))) {
                ++libPathCount;
                libPath = a.mid(QStringLiteral("-Djava.library.path=").size());
            }
        }
        check(libPathCount == 1, QString("%1: -Djava.library.path 恰好一条").arg(v),
              QString::number(libPathCount));
        check(QFileInfo(libPath).isAbsolute() && QDir(libPath).exists(),
              QString("%1: -Djava.library.path 是存在的绝对路径").arg(v), libPath);
    }

    // -----------------------------------------------------------------
    section("C. JVM 选项按 Java 版本过滤");
    // -----------------------------------------------------------------
    for (const auto &pair : QList<QPair<int, bool>>{{8, false}, {17, true}, {21, true}, {25, true}}) {
        GlobalJavaSettings s;
        const QStringList args = launcher.generateJvmArguments(QString(), QStringLiteral("1.19"),
                                                              QStringLiteral("1"), jsons["1.19"], s,
                                                              true, pair.first);
        const bool present = args.contains(QStringLiteral("--enable-native-access=ALL-UNNAMED"));
        check(present == pair.second,
              QString("Java %1 -> --enable-native-access %2")
                  .arg(pair.first)
                  .arg(pair.second ? "存在" : "不存在"));
    }

    // -----------------------------------------------------------------
    section("C2. arguments.jvm 展开（26.3 的 StackShadowPages）");
    // -----------------------------------------------------------------
    // generateJvmArguments 必须把 version.json 的 arguments.jvm 按规则过滤后原样
    // 传进去。26.3 崩在 jvm.dll 访问冲突，根因就是这条链没走通：它声明的
    // -XX:StackShadowPages=32 从来没被传递过，而 JDK 25 的默认值只有 8。影子区不够
    // 时，编译代码在资源重载那种深栈路径上会越过影子区踩到保护页 —— 没有 Java 异常、
    // 没有 hs_err、没有崩溃报告，进程直接消失。
    {
        const auto countExact = [](const QStringList &list, const QString &value) {
            int n = 0;
            for (const QString &item : list) {
                if (item == value) {
                    ++n;
                }
            }
            return n;
        };
        const auto countPrefix = [](const QStringList &list, const QString &prefix) {
            int n = 0;
            for (const QString &item : list) {
                if (item.startsWith(prefix)) {
                    ++n;
                }
            }
            return n;
        };
        const auto hasPrefix = [&countPrefix](const QStringList &list, const QString &prefix) {
            return countPrefix(list, prefix) > 0;
        };

        struct Expect {
            QString version;
            int javaMajor;
            QStringList mustContainExact;
            QStringList mustContainPrefix;  // 形如 "-Djna.tmpdir="，值后面还有内容
            QStringList mustNotContain;
        };
        const QList<Expect> expectations = {
            {QStringLiteral("26.3"),
             25,
             {QStringLiteral("-XX:StackShadowPages=32"), QStringLiteral("--add-exports"),
              QStringLiteral("java.base/jdk.internal.misc=ALL-UNNAMED"),
              QStringLiteral("--enable-native-access=ALL-UNNAMED")},
             {QStringLiteral("-XX:HeapDumpPath="), QStringLiteral("-Djava.library.path="),
              QStringLiteral("-Djna.tmpdir="),
              QStringLiteral("-Dorg.lwjgl.system.SharedLibraryExtractPath="),
              QStringLiteral("-Dio.netty.native.workdir=")},
             {QStringLiteral("-XstartOnFirstThread")}},
            {QStringLiteral("26.1"),
             25,
             {QStringLiteral("--sun-misc-unsafe-memory-access=allow"),
              QStringLiteral("--enable-native-access=ALL-UNNAMED")},
             {QStringLiteral("-Djna.tmpdir=")},
             {QStringLiteral("-XX:StackShadowPages=32"), QStringLiteral("-Xss1M")}},
            // Win10 规则挂在 os.version 的 "^10\." 上。用 QSysInfo::productVersion()
            // 在 Win11 上会得到 "11"，这两条就会静默消失 —— 所以顺带把它断言住。
            {QStringLiteral("1.18.2"),
             17,
             {QStringLiteral("-Dos.name=Windows 10"), QStringLiteral("-Dos.version=10.0")},
             {QStringLiteral("-XX:HeapDumpPath="), QStringLiteral("-Djava.library.path=")},
             {QStringLiteral("-XX:StackShadowPages=32"), QStringLiteral("-Xss1M")}},
            // 1.12.2 根本没有 arguments 字段（走旧版 minecraftArguments），展开结果为空，
            // 所以这里只断言"没有不该有的东西"；它兜底的 java.library.path 依赖 natives
            // 已经解压，放在 section D 里验（那里的沙箱状态是确定的）。
            {QStringLiteral("1.12.2"),
             8,
             {},
             {},
             {QStringLiteral("--enable-native-access=ALL-UNNAMED"),
              QStringLiteral("-XX:StackShadowPages=32")}},
        };

        for (const Expect &e : expectations) {
            GlobalJavaSettings s;
            const QStringList args = launcher.generateJvmArguments(
                QString(), e.version, QStringLiteral("1"), jsons[e.version], s, true, e.javaMajor);

            out() << "\n  " << e.version << ": 共 " << args.size() << " 个参数\n";
            for (const QString &need : e.mustContainExact) {
                check(args.contains(need), QString("%1: 含 %2").arg(e.version, need));
            }
            for (const QString &prefix : e.mustContainPrefix) {
                check(hasPrefix(args, prefix), QString("%1: 含 %2*").arg(e.version, prefix));
            }
            for (const QString &banned : e.mustNotContain) {
                check(!hasPrefix(args, banned), QString("%1: 不含 %2").arg(e.version, banned));
            }

            // --add-exports 和它的值是 JSON 里的两个独立元素，必须原顺序、相邻传递，
            // 不能被"配对"或重排。
            if (e.version == QLatin1String("26.3")) {
                const int flag = args.indexOf(QStringLiteral("--add-exports"));
                check(flag >= 0 && flag + 1 < args.size() &&
                          args.at(flag + 1) ==
                              QStringLiteral("java.base/jdk.internal.misc=ALL-UNNAMED"),
                      "26.3: --add-exports 的值紧跟在它后面");
            }

            // 任何残留的 ${...} 都说明有占位符没替换掉
            for (const QString &a : args) {
                if (a.contains(QStringLiteral("${"))) {
                    check(false, QString("%1: 没有未替换的占位符").arg(e.version), a);
                }
            }

            // -cp 只能有一条（version.json 里的 -cp ${classpath} 必须被丢掉，否则
            // 命令行上会出现两个 -cp，而且前一个的值是未展开的占位符）
            check(countExact(args, QStringLiteral("-cp")) == 1,
                  QString("%1: -cp 恰好一条").arg(e.version),
                  QString::number(countExact(args, QStringLiteral("-cp"))));
            const int cp = args.indexOf(QStringLiteral("-cp"));
            check(cp >= 0 && cp + 2 < args.size() &&
                      args.at(cp + 2) == QStringLiteral("net.minecraft.client.main.Main"),
                  QString("%1: 主类紧跟 classpath").arg(e.version));

            // 同一条属性不许出现两次（我们硬编码的和 version.json 声明的会重叠）
            check(countExact(args, QStringLiteral("--enable-native-access=ALL-UNNAMED")) <= 1,
                  QString("%1: --enable-native-access 不重复").arg(e.version),
                  QString::number(
                      countExact(args, QStringLiteral("--enable-native-access=ALL-UNNAMED"))));
            check(countPrefix(args, QStringLiteral("-Djava.library.path=")) <= 1,
                  QString("%1: -Djava.library.path 不重复").arg(e.version),
                  QString::number(countPrefix(args, QStringLiteral("-Djava.library.path="))));
        }
    }

    // -----------------------------------------------------------------
    section("C3. 新增选项的门槛（OmitStackTrace / sun-misc / stdout.encoding）");
    // -----------------------------------------------------------------
    {
        const auto countPrefix = [](const QStringList &list, const QString &prefix) {
            int n = 0;
            for (const QString &item : list) {
                if (item.startsWith(prefix)) {
                    ++n;
                }
            }
            return n;
        };

        // 门槛全部来自实测（java <flag> -version 逐个试）：写错门槛的后果不是"参数
        // 不生效"而是 JVM 直接 Unrecognized option 起不来，所以每一档都要钉住。
        struct Gate {
            int javaMajor;
            bool expectSunMisc;   // --sun-misc-unsafe-memory-access=allow（实测 Java 25+）
            bool expectEncoding;  // -Dstdout.encoding=utf-8（JDK 19 才引入这两个属性）
            QString note;
        };
        const QList<Gate> gates = {
            {8, false, false, QStringLiteral("Java 8：两条都不能加，加了就起不来")},
            {17, false, false, QStringLiteral("Java 17：实测拒绝 sun-misc")},
            {19, false, true, QStringLiteral("Java 19：encoding 的下界（实测 17 忽略、21 生效）")},
            {21, false, true, QStringLiteral("Java 21：实测拒绝 sun-misc，编码已生效")},
            // 24 这一档是**刻意**放"没有"边的：JEP 498 在 JDK 24 引入这个选项，但本机
            // 没有 24 的运行时，21 拒绝 / 25 接受之间无法验证。代价不对称 —— 少加一条
            // 只是少压一句警告，加错一条是 JVM 起不来 —— 所以门槛取实测下界 25。
            {24, false, true, QStringLiteral("Java 24：无法实测，取保守边（见注释）")},
            {25, true, true, QStringLiteral("Java 25：实测接受 sun-misc，门槛的下界")},
            {0, false, false, QStringLiteral("调用方没传版本：一律按最保守的来")},
        };

        for (const Gate &g : gates) {
            GlobalJavaSettings s;
            const QStringList args = launcher.generateJvmArguments(
                QString(), QStringLiteral("1.19"), QStringLiteral("1"), jsons["1.19"], s, true,
                g.javaMajor);

            const QString label = g.javaMajor <= 0 ? QStringLiteral("未传") : QString::number(g.javaMajor);
            check(args.contains(QStringLiteral("--sun-misc-unsafe-memory-access=allow")) ==
                      g.expectSunMisc,
                  QString("Java %1: --sun-misc-unsafe-memory-access %2（%3）")
                      .arg(label, g.expectSunMisc ? QStringLiteral("有") : QStringLiteral("没有"), g.note));
            check(countPrefix(args, QStringLiteral("-Dstdout.encoding=")) == (g.expectEncoding ? 1 : 0),
                  QString("Java %1: -Dstdout.encoding %2")
                      .arg(label, g.expectEncoding ? QStringLiteral("恰好一条") : QStringLiteral("没有")));
            // 两个属性必须同进同退：只加一个会让 stdout/stderr 用不同编码解码
            check(countPrefix(args, QStringLiteral("-Dstderr.encoding=")) ==
                      countPrefix(args, QStringLiteral("-Dstdout.encoding=")),
                  QString("Java %1: stdout/stderr 编码成对出现").arg(label));
            if (g.expectEncoding) {
                check(args.contains(QStringLiteral("-Dstdout.encoding=utf-8")) &&
                          args.contains(QStringLiteral("-Dstderr.encoding=utf-8")),
                      QString("Java %1: 两个编码都是 utf-8").arg(label));
            }
            // 实测 Java 8/17/25 全接受，所以这条必须**无条件**在
            check(args.contains(QStringLiteral("-XX:-OmitStackTraceInFastThrow")),
                  QString("Java %1: 无条件带 -XX:-OmitStackTraceInFastThrow").arg(label));

            // 这一批里唯一有回归风险的一处：加参数（编码）和改解码必须同进同退。
            // 只加参数不改解码 -> 中文日志成为乱码；只改解码不加参数 -> 同样乱码。
            // 直接用生产代码那个判据把两端串起来断言，将来谁改歪了这里先红。
            check(LauncherManager::commandDeclaresUtf8Output(args) == g.expectEncoding,
                  QString("Java %1: 生成参数与解码判据一致（%2）")
                      .arg(label, g.expectEncoding ? QStringLiteral("两边都是 UTF-8")
                                                   : QStringLiteral("两边都是本地代码页")));
        }

        // 解码判据本身的真值表（它是纯函数，跟参数生成本身无关的那几种输入也要对）
        struct Utf8Case {
            QStringList args;
            bool expect;
            QString note;
        };
        const QList<Utf8Case> utf8Cases = {
            {{}, false, QStringLiteral("命令行里没有这个属性 -> 本地代码页")},
            {{QStringLiteral("-Dstdout.encoding=utf-8")}, true, QStringLiteral("值就是 utf-8")},
            {{QStringLiteral("-Dstdout.encoding=UTF-8")}, true, QStringLiteral("值不区分大小写")},
            {{QStringLiteral("-Dstdout.encoding=gbk")}, false,
             QStringLiteral("显式写了别的编码 -> 不能当 UTF-8 解")},
            {{QStringLiteral("-Dstderr.encoding=utf-8")}, false,
             QStringLiteral("只有 stderr 那条不算（判据只看 stdout）")},
            {{QStringLiteral("-Dstdout.encoding=utf-8"), QStringLiteral("-Dstdout.encoding=gbk")},
             false, QStringLiteral("出现多次时取最后一份（JVM 就是这个语义）")},
            {{QStringLiteral("-Dstdout.encoding=gbk"), QStringLiteral("-Dstdout.encoding=utf-8")},
             true, QStringLiteral("同上，反过来")},
        };
        for (const Utf8Case &c : utf8Cases) {
            check(LauncherManager::commandDeclaresUtf8Output(c.args) == c.expect,
                  QString("解码判据: %1").arg(c.note));
        }

        // 按版本的自定义参数：排在全局之后（JVM 后写的胜出，所以单实例能盖掉全局默认）
        GlobalJavaSettings s;
        s.setExtraJvmArgs(QStringLiteral("-XX:+UseG1GC"));
        const QStringList withVersionArgs = launcher.generateJvmArguments(
            QString(), QStringLiteral("1.19"), QStringLiteral("1"), jsons["1.19"], s, true, 8,
            QStringList{QStringLiteral("-XX:+PerfDisableSharedMem"),
                        QStringLiteral("-XX:MaxGCPauseMillis=50")});
        const int globalIndex = withVersionArgs.indexOf(QStringLiteral("-XX:+UseG1GC"));
        const int versionIndex = withVersionArgs.indexOf(QStringLiteral("-XX:MaxGCPauseMillis=50"));
        check(globalIndex >= 0, "全局 extraJvmArgs 在参数里");
        check(versionIndex > globalIndex, "按版本的参数排在全局 extraJvmArgs 之后",
              QString("global=%1 version=%2").arg(globalIndex).arg(versionIndex));
        check(withVersionArgs.contains(QStringLiteral("-XX:+PerfDisableSharedMem")),
              "按版本的参数逐条传入，没有被打散");

        // 不带 versionJvmArgs 时参数列表里不该出现这些（默认值是空列表）
        const QStringList withoutVersionArgs = launcher.generateJvmArguments(
            QString(), QStringLiteral("1.19"), QStringLiteral("1"), jsons["1.19"], s, true, 8);
        check(!withoutVersionArgs.contains(QStringLiteral("-XX:MaxGCPauseMillis=50")),
              "不传 versionJvmArgs 时不会凭空出现按版本的参数");

        // 用户自定义参数**不参与去重**：那是用户自己写的，启动器替他删掉才是越权。
        // 26.1 的 version.json 自己声明了 --sun-misc-unsafe-memory-access=allow，
        // 用户再写一条 deny，两条都该在（JVM 取后写的，所以 version.json 那份胜出）。
        const QStringList userOverlap = launcher.generateJvmArguments(
            QString(), QStringLiteral("26.1"), QStringLiteral("1"), jsons["26.1"], s, true, 25,
            QStringList{QStringLiteral("--sun-misc-unsafe-memory-access=deny")});
        check(countPrefix(userOverlap, QStringLiteral("--sun-misc-unsafe-memory-access=")) == 2,
              "用户自定义的同名前缀参数不被去重",
              QString::number(
                  countPrefix(userOverlap, QStringLiteral("--sun-misc-unsafe-memory-access="))));

        // version.json 声明了就以它为准：我们自己硬编码的那条必须被去掉。
        // 用一个最小 version.json 保证"declared 里有它"这件事是确定的。
        QJsonArray jvmEntries;
        jvmEntries.append(QStringLiteral("--sun-misc-unsafe-memory-access=deny"));
        jvmEntries.append(QStringLiteral("-Dstdout.encoding=gbk"));
        QJsonObject argumentsObj;
        argumentsObj.insert(QStringLiteral("jvm"), jvmEntries);
        QJsonObject denyJson;
        denyJson.insert(QStringLiteral("arguments"), argumentsObj);

        const QStringList declaredWins = launcher.generateJvmArguments(
            QString(), QStringLiteral("1.19"), QStringLiteral("1"), denyJson, s, true, 25);
        check(!declaredWins.contains(QStringLiteral("--sun-misc-unsafe-memory-access=allow")),
              "version.json 声明了 sun-misc 时，我们硬编码的那条被去掉");
        check(declaredWins.contains(QStringLiteral("--sun-misc-unsafe-memory-access=deny")),
              "version.json 的 sun-misc 值原样保留");
        check(!declaredWins.contains(QStringLiteral("-Dstdout.encoding=utf-8")),
              "version.json 声明了 stdout.encoding 时，我们硬编码的那条被去掉");
        check(declaredWins.contains(QStringLiteral("-Dstdout.encoding=gbk")),
              "version.json 的 stdout.encoding 值原样保留");
        check(!declaredWins.contains(QStringLiteral("-Dstderr.encoding=utf-8")),
              "version.json 声明 stdout.encoding 时，我们那两条成对撤掉",
              "（解码侧只有一个开关，混搭编码无论取哪边都是错的）");
    }

    // -----------------------------------------------------------------
    section("C4. --gameDir / --assetsDir 是绝对路径（两个分支都要）");
    // -----------------------------------------------------------------
    // 它们以前是靠 cwd(.minecraft) 解析的相对路径，而 startGame() 又自己算了一份绝对
    // 路径。改成绝对路径后解析结果不变，但不再依赖 cwd —— 所以这里既断言"是绝对的"，
    // 也断言"指的正是那个目录"，两件事都要钉住。
    {
        const QString expectedGameDir = sandbox + "/versions/1.19";
        const QString expectedAssetsDir = sandbox + "/assets";

        const auto argValue = [](const QStringList &list, const QString &flag) -> QString {
            const int i = list.indexOf(flag);
            return (i >= 0 && i + 1 < list.size()) ? list.at(i + 1) : QString();
        };

        for (const bool offline : {true, false}) {
            GlobalJavaSettings s;
            const QStringList args = launcher.generateJvmArguments(
                QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                jsons["1.19"], s, offline, 17);

            const QString branch = offline ? QStringLiteral("离线") : QStringLiteral("在线");
            const QString gameDir = argValue(args, QStringLiteral("--gameDir"));
            const QString assetsDir = argValue(args, QStringLiteral("--assetsDir"));

            check(QDir::isAbsolutePath(gameDir),
                  QString("%1: --gameDir 是绝对路径").arg(branch), gameDir);
            check(QDir::isAbsolutePath(assetsDir),
                  QString("%1: --assetsDir 是绝对路径").arg(branch), assetsDir);
            check(QFileInfo(gameDir).absoluteFilePath() ==
                      QFileInfo(expectedGameDir).absoluteFilePath(),
                  QString("%1: --gameDir 就是 versions/<id>").arg(branch), gameDir);
            check(QFileInfo(assetsDir).absoluteFilePath() ==
                      QFileInfo(expectedAssetsDir).absoluteFilePath(),
                  QString("%1: --assetsDir 就是 .minecraft/assets").arg(branch), assetsDir);
            // 两个分支给的值必须完全一样：否则"离线能跑在线不能跑"这种 bug 只会在
            // 用户切换登录方式时冒出来
            if (!offline) {
                GlobalJavaSettings s2;
                const QStringList offlineArgs = launcher.generateJvmArguments(
                    QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                    jsons["1.19"], s2, true, 17);
                check(argValue(offlineArgs, QStringLiteral("--gameDir")) == gameDir &&
                          argValue(offlineArgs, QStringLiteral("--assetsDir")) == assetsDir,
                      "离线/在线两个分支的 --gameDir/--assetsDir 逐字节相同");
            }
        }
    }

    // -----------------------------------------------------------------
    section("C5. 多会话：一个 LauncherManager 同时管好几份游戏进程");
    // -----------------------------------------------------------------
    // 多账户多实例那件事的地基。四件容易写错的：① 早退路径不能留下"幽灵会话"
    // （底栏会永远挂着「实例运行中」）；② 两份会话的输出必须各带各的号，不然日志分不出
    // 谁是谁、"启动中"进度也会互相顶掉；③ 停一份不能连带停另一份；④ 撑到上限之后
    // 再来一份要被拦下、且不改变已有那几份。
    //
    // 长命进程用系统自带的 `ping -n N 127.0.0.1`（十几秒，够做并发断言，也能被杀）。
    // **不用 `java -version`**：它几十毫秒就结束，两份根本重叠不上，"同时在跑"这件事
    // 就无从断言了。
    {
        LauncherManager mgr;
        check(mgr.runningCount() == 0, "刚建出来时一份会话都没有");
        check(!mgr.hasRunningGame(), "hasRunningGame() 同样是假");
        check(mgr.runningGames().isEmpty(), "会话列表也是空的");
        check(mgr.session(0).sessionId == 0, "会话号 0 是哨兵，查它是空的");
        check(mgr.session(99).sessionId == 0, "没见过的会话号查出来也是空的");
        check(!mgr.isVersionRunning(QStringLiteral("1.20.1")), "没跑就是没跑");
        check(!mgr.isVersionRunning(QString()),
              "空版本号永远是假（不能变成「问谁都说在跑」）");

        // (a) 找不到 Java 的早退路径：返回 0，而且**不留会话**。
        GlobalJavaSettings missing;
        missing.setJavaPath(sandbox + "/no-such-java.exe");
        check(mgr.startGame({QStringLiteral("-version")}, missing, QStringLiteral("1.20.1")) == 0,
              "Java 路径不存在时 startGame 返回 0（不是会话号）");
        check(mgr.runningCount() == 0 && !mgr.hasRunningGame(),
              "启动失败**不留下会话** —— 底栏不该挂着一句「实例运行中」",
              QString::number(mgr.runningCount()));
        check(mgr.session(1).sessionId == 0,
              "失败的那一份连号都不占（会话表里没有它）",
              QString::number(mgr.session(1).sessionId));

        const QString ping = QStandardPaths::findExecutable(QStringLiteral("ping"));
        if (ping.isEmpty()) {
            // 静默通过比不测更糟 —— 这台机器上跑不了就把话说明白。
            check(true, "（PATH 里没有 ping，跳过多会话那几条真进程断言）");
        } else {
            GlobalJavaSettings shell;
            shell.setJavaPath(ping);

            // 收到的输出按会话号归档。**一条都没收到也算过**：这里要钉的是"哪一份说的"
            // （sessionId 对不对），不是"进程吐了多少话" —— 后者是 ping 的行为，不是我们的。
            QHash<int, int> outputCount;
            QObject::connect(&mgr, &LauncherManager::processOutput, &app,
                             [&outputCount](int sessionId, const QString &) {
                                 ++outputCount[sessionId];
                             });

            // ---- 两份**同一个实例**：这就是"一个实例同一账号多次启动 / 不同账号各一个"
            //      那条需求的最小形状（身份不同、实例相同）。
            const QStringList args{QStringLiteral("-n"), QStringLiteral("20"),
                                   QStringLiteral("127.0.0.1")};
            const int first = mgr.startGame(args, shell, QStringLiteral("1.20.1"),
                                            QStringLiteral("实例A"), QStringLiteral("账号甲"));
            const int second = mgr.startGame(args, shell, QStringLiteral("1.20.1"),
                                             QStringLiteral("实例A"), QStringLiteral("账号乙"));
            check(first > 0 && second > 0, "两份都起来了",
                  QStringLiteral("first=%1 second=%2").arg(first).arg(second));
            check(first != second, "两次启动拿到的是**两个**会话号");
            check(mgr.runningCount() == 2, "同一个实例开两份 = 两份会话同时在跑",
                  QString::number(mgr.runningCount()));
            check(mgr.isVersionRunning(QStringLiteral("1.20.1")),
                  "这个实例现在算「运行中」");
            check(!mgr.isVersionRunning(QStringLiteral("1.20.2")),
                  "别的版本没有被连带说成在跑");

            const QList<LauncherManager::GameSession> games = mgr.runningGames();
            check(games.size() == 2, "runningGames() 有两份");
            check(games.size() == 2 && games.at(0).sessionId == first &&
                      games.at(1).sessionId == second,
                  "runningGames() 按会话号（= 启动顺序）排，不是哈希表的随机顺序");
            check(games.size() == 2 && games.at(0).accountName == QStringLiteral("账号甲") &&
                      games.at(1).accountName == QStringLiteral("账号乙"),
                  "两份会话各记各的身份 —— 多账户多实例的要害（都读「当前登录的那个」就全错了）",
                  games.size() == 2
                      ? games.at(0).accountName + QStringLiteral("/") + games.at(1).accountName
                      : QString());
            check(games.size() == 2 && games.at(0).displayName == QStringLiteral("实例A") &&
                      games.at(1).displayName == QStringLiteral("实例A"),
                  "实例名是启动那一刻的快照");
            check(mgr.session(second).sessionId == second && mgr.session(second).processId > 0,
                  "按会话号查得到，而且记下了进程号",
                  QString::number(mgr.session(second).processId));

            // 输出各带各的号。
            QElapsedTimer timer;
            timer.start();
            while (timer.elapsed() < 8000 &&
                   (outputCount.value(first) == 0 || outputCount.value(second) == 0)) {
                QCoreApplication::processEvents(QEventLoop::AllEvents, 50);
            }
            check(outputCount.value(first) > 0 && outputCount.value(second) > 0,
                  "两份会话的输出各带各的 sessionId（日志里才分得出谁是谁）",
                  QStringLiteral("first=%1 second=%2")
                      .arg(outputCount.value(first))
                      .arg(outputCount.value(second)));
            check(outputCount.size() == 2,
                  "没有第三个会话号冒出来", QString::number(outputCount.size()));

            // ---- 停一份，另一份不受影响。
            check(!mgr.stopGame(9999), "停一个不存在的会话号返回 false（不崩）");
            check(mgr.stopGame(second), "stopGame 对在跑的那一份返回 true");
            timer.restart();
            while (mgr.runningCount() > 1 && timer.elapsed() < 15000) {
                QCoreApplication::processEvents(QEventLoop::AllEvents, 50);
            }
            check(mgr.runningCount() == 1, "停掉一份之后只剩一份在跑",
                  QString::number(mgr.runningCount()));
            check(mgr.runningGames().size() == 1 &&
                      mgr.runningGames().first().sessionId == first,
                  "剩下的是**另一份**（停一份没连带停另一份）");
            check(mgr.isVersionRunning(QStringLiteral("1.20.1")),
                  "同一个实例还剩一份在跑，所以它还是「运行中」");
            check(!mgr.stopGame(second), "已经停掉的那份再停一次返回 false");

            // ---- 上限那条路：撑到上限，再来一份要被拦下。
            const int cap = LauncherManager::maxConcurrentSessions();
            check(cap >= 2, "上限至少得是 2，不然「多开」这个功能本身就是空的",
                  QString::number(cap));
            QList<int> filled{first};
            for (int i = mgr.runningCount(); i < cap; ++i) {
                const int id = mgr.startGame(args, shell, QStringLiteral("1.20.1"),
                                             QStringLiteral("实例B"), QStringLiteral("账号丙"));
                if (id <= 0) {
                    break;
                }
                filled.append(id);
            }
            check(mgr.runningCount() == cap, "会话数撑到了上限", QString::number(mgr.runningCount()));
            check(mgr.startGame(args, shell, QStringLiteral("1.20.1")) == 0,
                  "到了上限再启动一份，返回 0（被拦下）");
            check(mgr.runningCount() == cap,
                  "被拦下那一次**没有**挤掉已有的一份", QString::number(mgr.runningCount()));

            for (int id : filled) {
                mgr.stopGame(id);
            }
            timer.restart();
            while (mgr.runningCount() > 0 && timer.elapsed() < 30000) {
                QCoreApplication::processEvents(QEventLoop::AllEvents, 50);
            }
            check(mgr.runningCount() == 0 && !mgr.hasRunningGame(),
                  "全停掉之后一份都不剩（会话表收干净了）",
                  QString::number(mgr.runningCount()));
            check(mgr.runningGames().isEmpty(), "会话列表也跟着空了");
        }
    }

    // -----------------------------------------------------------------
    section("C6. --username 只有调用方给的那一个来源（离线/正版都一样）");
    // -----------------------------------------------------------------
    // 底栏左下角显示的名字和游戏里那个名字必须是同一个 —— 以前离线分支自己拼
    // "Player<毫秒时间戳>"、正版分支写死 "Player"，于是底栏写着谁、游戏里就是另一个人。
    // 现在两条分支都取调用方传进来的 playerName（真实路径传 AuthManager::playerName()）。
    {
        const auto argValue = [](const QStringList &list, const QString &flag) -> QString {
            const int i = list.indexOf(flag);
            return (i >= 0 && i + 1 < list.size()) ? list.at(i + 1) : QString();
        };
        const auto usernameOf = [&argValue](const QStringList &list) {
            return argValue(list, QStringLiteral("--username"));
        };

        for (const bool offline : {true, false}) {
            const QString branch = offline ? QStringLiteral("离线") : QStringLiteral("正版");
            GlobalJavaSettings s;
            const QStringList args = launcher.generateJvmArguments(
                QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                jsons["1.19"], s, offline, 17, QStringList(), QStringLiteral("Player"));
            check(usernameOf(args) == QStringLiteral("Player"),
                  QString("%1分支：--username 是调用方给的名字").arg(branch), usernameOf(args));
        }

        // 用户自己改过名字（以后从 profile 拉回来的真实名字）也要原样传下去
        {
            GlobalJavaSettings s;
            const QStringList args = launcher.generateJvmArguments(
                QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                jsons["1.19"], s, true, 17, QStringList(), QStringLiteral("Steve"));
            check(usernameOf(args) == QStringLiteral("Steve"),
                  "换一个名字也照传（离线）", usernameOf(args));
        }

        // 调用方没给名字（测试、老调用点）：退回默认名，**绝不能是空的** ——
        // --username 空着游戏会直接拒绝启动。
        {
            GlobalJavaSettings s;
            const QStringList args = launcher.generateJvmArguments(
                QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                jsons["1.19"], s, true, 17);
            check(usernameOf(args) == QStringLiteral("Player"),
                  "没传名字时退回默认名 Player（不是空串）", usernameOf(args));
            check(args.contains(QStringLiteral("--username")),
                  "而且 --username 这个开关本身还在");
        }

        // 名字里带空格也不该被拆成两个参数（老实现拼时间戳时不会有这种情况，
        // 换成用户自定义名字之后会）
        {
            GlobalJavaSettings s;
            const QStringList args = launcher.generateJvmArguments(
                QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                jsons["1.19"], s, true, 17, QStringList(), QStringLiteral("My Name"));
            check(usernameOf(args) == QStringLiteral("My Name"),
                  "带空格的名字原样作为**一个**参数传下去", usernameOf(args));
        }

        // ---- --uuid：正版分支用调用方给的账户 UUID，离线分支不用它 ----
        // 老实现的正版分支发的是全零 UUID（登录流程那时不拉档案，没有 uuid 来源），
        // 在正版服上等于一个"谁都不是"的身份。现在档案里有了，就得传下去。
        {
            const auto uuidOf = [&argValue](const QStringList &list) {
                return argValue(list, QStringLiteral("--uuid"));
            };
            const QString steveUuid = QStringLiteral("069a79f4-44e9-4726-a5be-fca90e38aaf5");

            GlobalJavaSettings s;
            const QStringList online = launcher.generateJvmArguments(
                QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                jsons["1.19"], s, false, 17, QStringList(), QStringLiteral("Steve"), steveUuid);
            check(uuidOf(online) == steveUuid, "正版分支：--uuid 是调用方给的账户 UUID",
                  uuidOf(online));

            // 没给（没登录、或者老调用点）：退回全零，**不是空串** —— 空的 --uuid
            // 游戏会直接拒绝启动。
            const QStringList noUuid = launcher.generateJvmArguments(
                QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                jsons["1.19"], s, false, 17, QStringList(), QStringLiteral("Player"));
            check(uuidOf(noUuid) == QStringLiteral("00000000-0000-0000-0000-000000000000"),
                  "正版分支没给 UUID 时退回全零（不是空串）", uuidOf(noUuid));

            // 离线分支的 uuid 是**每次随机生成**的（单机存档认这个），不该被账户 UUID 顶掉
            const QStringList offlineArgs = launcher.generateJvmArguments(
                QStringLiteral("fake-token"), QStringLiteral("1.19"), QStringLiteral("1"),
                jsons["1.19"], s, true, 17, QStringList(), QStringLiteral("Steve"), steveUuid);
            check(uuidOf(offlineArgs) != steveUuid && !uuidOf(offlineArgs).isEmpty(),
                  "离线分支的 --uuid 还是它自己随机生成的那个", uuidOf(offlineArgs));
        }
    }

    // -----------------------------------------------------------------
    section("D. natives 解压（LauncherManager::prepareNatives）");
    // -----------------------------------------------------------------
    for (const QString &v : {"1.18.2", "1.12.2"}) {
        prepareSandbox(sandbox, v);
        QDir().mkpath(sandbox + "/versions/" + v);
        QFile::copy(metaDir + "/" + v + ".json",
                    sandbox + "/versions/" + v + "/" + v + ".json");

        // The former build/verify tree contained downloaded native JARs that
        // were never source-controlled.  Generate tiny but genuine JARs here
        // so the extraction test is hermetic.  The legacy case checks the
        // exact DLL names, while the modern case only needs a real DLL entry.
        bool nativeFixturesReady = true;
        for (qsizetype i = 0; i < nativesOf[v].size(); ++i) {
            QMap<QString, QByteArray> entries;
            if (v == QLatin1String("1.12.2") && i == 0) {
                entries.insert(QStringLiteral("lwjgl.dll"), QByteArrayLiteral("dll"));
                entries.insert(QStringLiteral("lwjgl64.dll"), QByteArrayLiteral("dll64"));
                entries.insert(QStringLiteral("OpenAL32.dll"), QByteArrayLiteral("openal32"));
                entries.insert(QStringLiteral("OpenAL64.dll"), QByteArrayLiteral("openal64"));
                entries.insert(QStringLiteral("jinput-dx8.dll"), QByteArrayLiteral("jinput"));
            } else {
                entries.insert(QStringLiteral("native-%1.dll").arg(i),
                               QByteArrayLiteral("native"));
            }
            nativeFixturesReady =
                makeFakeJar(sandbox + "/libraries/" + nativesOf[v].at(i).path, entries) &&
                nativeFixturesReady;
        }
        check(nativeFixturesReady, QString("%1: 自行生成 natives JAR 夹具").arg(v));

        const QString nativesDir = sandbox + "/versions/" + v + "/natives";
        const QFileInfo before(nativesDir);

        QStringList errors;
        const QString got = launcher.prepareNatives(jsons[v], v, &errors);
        check(!got.isEmpty(), QString("%1: prepareNatives 返回目录").arg(v),
              errors.join(QStringLiteral("; ")));
        check(QFileInfo(got).absoluteFilePath() == QFileInfo(nativesDir).absoluteFilePath(),
              QString("%1: 目录落在 versions/%1/natives").arg(v), got);

        const QStringList dlls =
            QDir(nativesDir).entryList(QStringList() << QStringLiteral("*.dll"), QDir::Files);
        out() << "        " << dlls.size() << " 个 DLL: " << dlls.join(QStringLiteral(", "))
              << "\n";
        check(!dlls.isEmpty(), QString("%1: 解压出 DLL").arg(v));

        if (v == QLatin1String("1.12.2")) {
            check(dlls.contains(QStringLiteral("lwjgl.dll")) &&
                      dlls.contains(QStringLiteral("lwjgl64.dll")) &&
                      dlls.contains(QStringLiteral("OpenAL32.dll")) &&
                      dlls.contains(QStringLiteral("OpenAL64.dll")) &&
                      dlls.contains(QStringLiteral("jinput-dx8.dll")),
                  "1.12.2: 关键 DLL 齐全");
        }

        // 守卫：第二次调用不应重新解压（目录 mtime 不变）
        const QDateTime mtimeBefore = QFileInfo(nativesDir).lastModified();
        QStringList errors2;
        const QString again = launcher.prepareNatives(jsons[v], v, &errors2);
        check(again == got && QFileInfo(nativesDir).lastModified() == mtimeBefore,
              QString("%1: 第二次调用走守卫、不重复解压").arg(v));

        // 解压后 checkPreLaunch 应该过
        QStringList preErrors;
        const bool pre = launcher.checkPreLaunch(v, &preErrors, jsons[v]);
        check(pre, QString("%1: checkPreLaunch 通过").arg(v),
              preErrors.join(QStringLiteral("; ")));

        // 生成的参数里必须带上 java.library.path
        GlobalJavaSettings s;
        const QStringList args = launcher.generateJvmArguments(
            QString(), v, QStringLiteral("1"), jsons[v], s, true, v == QLatin1String("1.12.2") ? 8 : 17);
        QString libPath;
        for (const QString &a : args) {
            if (a.startsWith(QStringLiteral("-Djava.library.path="))) {
                libPath = a.mid(QStringLiteral("-Djava.library.path=").size());
            }
        }
        check(QFileInfo(libPath).isAbsolute() && QDir(libPath).exists(),
              QString("%1: -Djava.library.path 是存在的绝对路径").arg(v), libPath);
    }

    // 反证：删掉 natives 目录后，1.18.2 的 checkPreLaunch 必须拦下来
    {
        const QString nativesDir = sandbox + "/versions/1.18.2/natives";
        QDir(nativesDir).removeRecursively();
        QStringList preErrors;
        const bool pre = launcher.checkPreLaunch(QStringLiteral("1.18.2"), &preErrors, jsons["1.18.2"]);
        check(!pre, "1.18.2: natives 缺失时 checkPreLaunch 会拦下",
              preErrors.join(QStringLiteral("; ")));
    }

    // -----------------------------------------------------------------
    section("E. Java 运行时选择（GlobalJavaSettings::ensureJavaForVersion）");
    // -----------------------------------------------------------------
    GlobalJavaSettings settings;
    settings.load();
    out() << "  配置中的 java: " << settings.javaPath() << "\n";
    const QString originalPath = settings.javaPath();

    const QList<QPair<int, QString>> requirements = {
        {25, QStringLiteral("java-runtime-epsilon")},
        {21, QStringLiteral("java-runtime-delta")},
        {17, QStringLiteral("java-runtime-beta")},
        {8, QStringLiteral("jre-legacy")},
    };
    for (const auto &req : requirements) {
        // 每次都从"错误"的配置出发，验证会主动去找匹配的版本
        settings.setJavaPath(originalPath);
        const bool ok = settings.ensureJavaForVersion(req.first, req.second);
        const QString got = settings.javaPath();
        const QString ver = ok ? javaVersionOf(got) : QStringLiteral("<未找到>");
        // Java 8 的 -version 输出是 "1.8.0_51"，其余是 "25.0.1" 这种
        const QString expect = req.first == 8 ? QStringLiteral("1.8") : QString::number(req.first);
        check(ok, QString("需要 Java %1 -> 找到").arg(req.first), got);
        check(ver.startsWith(expect),
              QString("需要 Java %1 -> 实际版本 %2").arg(req.first).arg(ver));
    }

    // 恢复用户原来的配置，测试不该改动机器上的设置
    settings.setJavaPath(originalPath);
    settings.save();
    out() << "  已恢复配置中的 java: " << settings.javaPath() << "\n";

    // -----------------------------------------------------------------
    runPipelineTests(app, sandbox);

    // -----------------------------------------------------------------
    runVersionNameTests(sandbox);

    // -----------------------------------------------------------------
    runInstanceFileTests(sandbox);

    // -----------------------------------------------------------------
    runInstalledScanTests(sandbox);

    // -----------------------------------------------------------------
    // 排在扫描之后，理由见 names 模式里同名调用点上的注释。
    runVersionMetaWriteTests(sandbox);

    // -----------------------------------------------------------------
    runRenameInstanceTests(sandbox);

    // -----------------------------------------------------------------
    runInstanceGroupTests(sandbox);

    // -----------------------------------------------------------------
    runVersionJvmArgsTests(sandbox);

    // -----------------------------------------------------------------
    runMemorySuggestionTests(sandbox);

    // -----------------------------------------------------------------
    runEffectiveJavaSettingsTests(sandbox);

    // -----------------------------------------------------------------
    runJavaWarnMismatchTests(sandbox);

    // -----------------------------------------------------------------
    runJavaReleaseParseTests();

    // -----------------------------------------------------------------
    runPlayerSkinTests(sandbox);
    runRandomSkinTests(sandbox);
    // 紧挨着它：这一节管的是"离线账号那张脸"的另一半 —— 能算出游戏会给哪一张时，
    // 就用那一张（随机那张是退路）。两节验的东西不同，别合并。
    runDefaultSkinTests(sandbox);

    // -----------------------------------------------------------------
    // 排在最后：这一节自己把 QSettings 搬进沙盒又搬回来（跑完是原生形态），
    // 所以别把它插在中间 —— 上面那些节读盘走的是真实注册表。
    runAccountSkinTests(sandbox);

    // -----------------------------------------------------------------
    runLoaderInheritanceTests(sandbox);

    // -----------------------------------------------------------------
    // 纯函数那半：地址怎么拼、列表怎么挑、profile 能不能装、界面下标怎么翻。
    // 整节离线（联网那条路没法在沙箱里跑），所以它跟 U 节一样是"自己收摊"的。
    runLoaderInstallTests();

    // -----------------------------------------------------------------------
    // 整合包导入（纯函数 + 真解一次压缩包 + 真清单），见上面 V 节。
    // Y 节：四个分类 / 四个加载器的可选版本列表（纯函数，喂真清单和真夹具）。
    // 排在整合包那节之前 —— 它只读 meta/ 下的夹具、不碰沙箱，放哪儿都不影响别人。
    runVersionChannelTests();

    runModpackImportTests(sandbox);

    // ZG 节：CurseForge 那一份整合包（清单里只有号 → 换文件 → 落点），纯函数、不联网。
    // 紧跟在上面那一节后面 —— 两节讲的是同一件事的两种格式，摆在一起才好对着看。
    runCurseForgeTests();

    // -----------------------------------------------------------------------
    // 下载页那几类资源的数据层（拼地址 + 读真响应），纯函数、离线，见上面 Z 节。
    runResourceCatalogTests();

    // -----------------------------------------------------------------------
    // 资源详情页要的那几件（时间那句 / 渠道那一档 / 分组 / chip 筛 / 头卡那行字），
    // 纯函数、离线，见上面 Z8 节。紧挨着上面那一节：两边读的是同一份夹具。
    runResourceDetailTests();

    // -----------------------------------------------------------------------
    // 图标缓存（盘上那一份）+ "别一张张干等"那道闸，见上面 ZB 节。纯函数 + 文件层，
    // 自己收摊（换过的数据根目录在节末换回来）。
    runIconCacheTests();

    // -----------------------------------------------------------------------
    // 一串字节 → 一张图（Qt 认得的那一半 + webp 走系统 WIC 那一半），见上面 ZC 节。
    // 要真解码，所以会碰一下 COM/WIC —— 不联网、不落盘。
    runImageDecodeTests();

    // -----------------------------------------------------------------
    // 设置页「启动选项」那三项（显示游戏日志 / 进程优先级 / 窗口大小）+ 窗口大小进命令行
    // 这条链，见上面 ZD 节。自己开一个 QSettings 沙盒、跑完收摊。
    runLaunchOptionsTests(sandbox);

    // -----------------------------------------------------------------
    // 服务器列表那个"连上去问一句"（Server List Ping），见上面 ZH 节。这一节自己起一台
    // 假的服务器、只连 127.0.0.1 —— 不联网，但**要真连**（纯函数那半证不了协议）。
    runServerPingTests();

    // -----------------------------------------------------------------
    // `servers.dat` 的写侧（改一条服务器的名字 / 地址），见上面 ZK 节。手搓 NBT 夹具、
    // 真落盘、真读回来 —— 全在系统临时目录里，不动沙箱。
    runServerListEditTests();

    // -----------------------------------------------------------------
    // quick play（--quickPlaySingleplayer / --quickPlayMultiplayer）那一层判据，见上面
    // ZL 节。纯值进、bool 出；真 json 那两条读的是 meta/ 里的夹具。
    runQuickPlayTests(metaDir);

    // -----------------------------------------------------------------
    // 日志窗底下那颗「导出错误报告…」写出来的那一份文本，见上面 ZI 节。纯值进、QString 出
    // —— 时间是从外面传进去的，所以整份报告能一个字一个字钉住。
    runErrorReportTests();

    // -----------------------------------------------------------------
    // 「复制实例」和「导入世界 / 世界改名」那两条真动盘的路，见上面 ZJ 节。自己开两个
    // 临时游戏文件夹、跑完换回去 —— **不碰共享沙盒**（这一节要造一整份实例和一个世界，
    // 留在那儿会给后面、以及下一次重跑留下没预料到的包袱）。
    runCopyInstanceAndWorldTests();

    // -----------------------------------------------------------------
    // Java 8 的 ASCII 别名（路径里带非 ASCII 字符就起不来），见上面 ZM 节。自己开一个临时
    // 游戏文件夹、跑完换回去 —— 这一节要真建联接和硬链接，留在共享沙箱里会碍后面的事。
    runAsciiAliasTests();

    // -----------------------------------------------------------------
    // 体检（只报不装）那套判据，见上面 ZN 节。**一个文件都不下、一个字节都不写**，
    // 所以它只在一个临时游戏文件夹里摆文件、比结论。清单和实例对不对得上（"体检说的就是
    // 这个实例装配时会去下的那些"）在 mw_check 的 T19.15。
    runVersionIntegrityTests();

    // -----------------------------------------------------------------
    // 任务账本那一套（2026-10-12，coding plan §2 / §3），见上面 AL / AM 两节。**一个
    // QWidget 都不碰、一个网络都不开**：纯规则喂值进去、账本自己在一个临时目录里落盘读回
    // —— 不碰共享沙盒。
    runTaskLedgerTests();

    // -----------------------------------------------------------------
    // 游戏异常退出那几句话（2026-10-12，coding plan §4.3），见上面 ZP 节。纯函数：值进、
    // 字符串出，不看时钟、不读盘、不起进程 —— 那一张提示表在这里逐格念一遍。
    runGameExitDiagnosisTests();

    // -----------------------------------------------------------------
    // 世界与实例备份（2026-10-13，coding plan §4.4），见上面 ZQ 节。**真打 zip、真删目录、
    // 真还原**：自己开一个临时游戏文件夹（备份落点就是 `<数据目录>/cache/backups`）、跑完
    // 换回去 —— 不碰共享沙盒；这一节留下的痕迹在盘上是好几个压缩包，留在沙箱里碍事。
    runBackupTests();

    // -----------------------------------------------------------------
    // 「上一次启动」那本账（2026-10-13，coding plan §5.1），见上面 ZR 节。**全是纯函数**：
    // 值进、字符串/一段字节出，不问时钟（那一列的"现在"是参数）—— 只有"账本落在哪个文件上"
    // 那一条要换一下数据根目录（换完就还原），所以它和 ZQ 那一节一样自己开临时目录。
    runLaunchHistoryTests();

    // -----------------------------------------------------------------
    // 实例页的搜索与筛选（2026-10-13，coding plan §7.2），见上面 ZS 节。**全是纯函数**：
    // 值进、bool 出，不读盘、不问时钟 —— 连一条实例都不必真的存在。
    runInstanceFilterTests();

    // -----------------------------------------------------------------
    // 更新中心的「忽略 / 固定」那本账（2026-10-13，coding plan §7.1），见上面 ZT 节。
    // **纯函数 + 一个临时目录里的真存真读**：不联网、不碰共享沙箱、不开任何界面。
    runUpdatePolicyTests();

    // -----------------------------------------------------------------
    // 更新前那份轻量回滚点（2026-10-13，coding plan §7.1），见上面 ZU 节。**真动盘**：
    // 自己开一个临时游戏文件夹造实例目录（这一层整个存在的意义就是"动手之前手上有一份
    // 旧的"，纯值上验不出来），跑完换回来。
    runUpdateRollbackTests();

    // -----------------------------------------------------------------
    // 服务端工作区（2026-10-13，coding plan §6 / 里程碑 M4）：判据层（状态 / EULA /
    // server.properties / 我们记的那一份），见上面 ZW 节。**纯函数**：值进、结构出。
    runServerModelTests();

    // -----------------------------------------------------------------
    // 扫盘那一层（coding plan §6 / 里程碑 M4），见上面 ZX 节。**真动盘**：自己开一个临时
    // 数据根目录，真建服务端目录、真读写那两个配置文件、真删 —— 跑完换回来。
    runServerRegistryTests();

    // -----------------------------------------------------------------
    // 服务端安装那四段的判据层（2026-10-13，coding plan §6.2 / 里程碑 M4-2），见上面 ZY 节。
    // **纯函数**：喂一份计划 + 一份字节进去，回一个结论出来（不联网、不建目录、不起 java
    // —— 真干那三件事的是驱动层，归 mw_check）。
    runServerInstallRunTests();

    // -----------------------------------------------------------------
    // 服务端"跑起来 / 停下来"那条路的判据层（2026-10-13，coding plan §6.2 的操作 + §6.3 的
    // 停止时序 / 里程碑 M4-3），见上面 ZZ 节。**纯函数**：那条命令怎么拼、起来没有、退了算
    // 哪一档状态、宽限多久才允许强杀（真起进程那一半 `ServerProcess` 归 mw_check 的 T41）。
    runServerRunTests();

    // -----------------------------------------------------------------
    // 「服务端设置」那一页底下那两层判据（2026-10-13，coding plan §6.3 / 里程碑 M4-4），见上面
    // ZV 节。**几乎全是纯函数**：表本身 / 收不收 / 合回文件 / 体检报哪几条与次序。唯一的例外
    // 是 ZV6 那一条 —— "这个端口有人占着吗"要**真听一次**（本机、不联网）。
    runServerSettingsTests();

    // -----------------------------------------------------------------
    out() << "\n===== " << (g_failures == 0 ? "全部通过" : "有失败项") << ": "
          << (g_checks - g_failures) << "/" << g_checks << " =====\n";
    out().flush();
    return g_failures == 0 ? 0 : 1;
}

